/// The `PRIM_VALUE_BUILTINS` index of a builtin, if listed.
/// The `T` of an `mpsc::SendError<T>`: a builtin whose C form is the
/// value, so its one public field `.0` is the same place.
pub(crate) fn send_error_elem(tys: &impl TyIntern, t: Ty) -> Option<Ty> {
    (crate::ty::sync::sync_kind(tys, t) == Some(crate::ty::sync::SyncTy::SendError)).then(|| tys.adt_first_ty_arg(t)).flatten()
}

pub(crate) fn prim_builtin_code(b: Builtin) -> Option<u32> {
    PRIM_VALUE_BUILTINS.iter().chain(ufcs::STD_VALUE_BUILTINS).position(|&x| x == b).map(|i| i as u32)
}

/// The builtin at a `PRIM_VALUE_BUILTINS` index, if in range.
pub(crate) fn prim_builtin_of_code(code: u32) -> Option<Builtin> {
    PRIM_VALUE_BUILTINS.iter().chain(ufcs::STD_VALUE_BUILTINS).nth(code as usize).copied()
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Res {
    None,
    Local(u32),
    Fn(LocalDefId),
    /// A unit variant value, a tuple-variant constructor, or a struct literal target.
    Variant(AdtId, u32),
    Builtin(Builtin),
    /// `None`, and `Some` used as a constructor.
    OptNone,
    OptSome,
    /// `Ok` and `Err` used as constructors.
    ResOk,
    ResErr,
    Method {
        f: LocalDefId,
        derefs: u8,
        autoref: Autoref,
    },
    BuiltinMethod {
        b: Builtin,
        derefs: u8,
        autoref: Autoref,
    },
    /// A primitive type's builtin method named by a path
    /// (`u8::is_ascii_digit`, `str::len`, TRIAGE T12): called with
    /// the receiver as its first argument, or used as a value
    /// (an `FnDef` over `ty::prim_fn_def`).
    PrimAssoc {
        b: Builtin,
        self_ty: Ty,
        name: Sym,
    },
    Field {
        derefs: u8,
        index: u32,
    },
    /// Operand deref counts for binary operators, compound assignment, and unary operators (`ld` only).
    Bin {
        ld: u8,
        rd: u8,
    },
    Index {
        derefs: u8,
    },
    /// A `base[idx]` place through a written `Index`/`IndexMut`
    /// impl (W-STD-C phase 2): the impl fns are in `index_recv`.
    TraitIndex {
        derefs: u8,
    },
    /// A `core::intrinsics::<name>` call that passed the privilege check.
    /// The payload is the intrinsic's registry id (`ty::lang::INTRINSICS`).
    /// Only spliced shipped-library source can produce this resolution.
    Intrinsic(u32),
    /// A range index `base[lo..hi]` producing a slice place (W-CORELANG).
    SliceIndex {
        derefs: u8,
    },
    /// `map[&q]` on a HashMap (W-STD-B, check/hashmap.rs `map_index`):
    /// the value behind `get`'s shared reference.
    MapIndex {
        derefs: u8,
    },
    /// A static item read, by index into `Program::statics` (W-CORELANG).
    Static(u32),
    /// A compile-time usize constant: `size_of`, `align_of`, `offset_of!`.
    ConstUsize(u64),
    /// A compile-time bool constant: `mem::needs_drop::<T>()` (W-STD-C).
    ConstBool(bool),
    /// `size_of_val` of an unsized value (`[T]` or `str`): the length
    /// builtin for the argument times the element size (1 for `str`).
    SizeOfVal {
        len: Builtin,
        elem: u64,
    },
    /// A comparison trait method (`partial_cmp`, `cmp`, `eq`, `lt`,
    /// and kin) on a scalar receiver: lowering emits the scalar
    /// comparison directly, as the binary operators do. `derefs`
    /// counts autoderefs from the receiver to the scalar.
    PrimCmp {
        kind: PrimCmpKind,
        derefs: u8,
    },
    /// An operator trait method (`add`, `neg`, `add_assign`, and
    /// kin) on a scalar receiver: lowering emits the scalar
    /// operation directly, as the operators do.
    PrimOp {
        kind: PrimOpKind,
        derefs: u8,
    },
    /// `size_of_val` or `align_of_val` on a dyn value: reads this
    /// header word of the argument's vtable (`object::VT_SIZE`, `VT_ALIGN`).
    DynMeta(u32),
    /// A `core::any` operation (check/any.rs): the receiver is reached
    /// by `derefs` derefs and `autoref` as for `Method`; the type it
    /// tests or names is `Checked::generic_args[e][0]`.
    Any {
        op: any::AnyOp,
        derefs: u8,
        autoref: Autoref,
    },
    /// A binary operator through an operator trait: the trait
    /// method to call (a template until mono rewrites it through
    /// `Checked::generic_args`), with operand deref counts.
    TraitBin {
        f: LocalDefId,
        ld: u8,
        rd: u8,
    },
    /// A comparison operator through a written `PartialEq` or
    /// `PartialOrd` impl: `f` is the impl's method (a template until
    /// mono rewrites it through `Checked::generic_args`), called with
    /// both operands borrowed; `via` turns its result into the
    /// operator's answer (core's default bodies for `ne`, `lt`, and
    /// kin).
    TraitCmp {
        f: LocalDefId,
        ld: u8,
        rd: u8,
        via: CmpVia,
    },
    /// The same in method form (`a.ne(&b)`, `a.lt(&b)`): the receiver
    /// is borrowed after `derefs` derefs; the argument is `&Rhs`.
    TraitCmpMethod {
        f: LocalDefId,
        derefs: u8,
        via: CmpVia,
    },
    /// `Ord::max`, `min`, or `clamp` by core's default bodies on a
    /// receiver taken by value: compare with Self's `PartialOrd`
    /// (`f` and `via` for a written impl, by structure when `f` is
    /// None), move the answer out, and drop the other values.
    OrdPick {
        kind: OrdPickKind,
        f: Option<LocalDefId>,
        via: CmpVia,
    },
    /// A method of `core::cmp::Ordering` (`is_lt`, `reverse`, `then`,
    /// and kin) on a receiver reached through `derefs` derefs:
    /// lowering reads its variant and computes the answer.
    OrderingOp {
        kind: OrderingOpKind,
        derefs: u8,
    },
    /// A numeric `From::from` call, lowered as a cast to the
    /// call's type. Widening conversions only (checked).
    FromCast,
    /// A scalar `TryFrom::try_from` call, lowered as a checked
    /// cast to the call's `Result` type (check/tryfrom.rs).
    TryFromCast,
    /// A `TryFrom::try_from` call through the blanket from `Into`:
    /// `Ok` around the `From` call, or around the argument itself
    /// for the identity impl (check/tryfrom.rs).
    TryFromOk(Option<LocalDefId>),
    /// A scalar `Default::default()` call, lowered as the zero
    /// value of the call's type.
    DefaultVal,
    /// A `for` loop through `IntoIterator`: the `into_iter` and
    /// `next` methods to call (templates until mono rewrites
    /// them through `Checked::generic_args`).
    ForTrait {
        into_iter: LocalDefId,
        next: LocalDefId,
    },
    /// A call through a function pointer value in the callee expression.
    Indirect,
    /// A `?` with no error conversion: on `Option`, or on `Result`
    /// whose error type already matches the enclosing return type.
    TryPlain,
    /// A `?` on `Result` whose error converts through this
    /// `From::from` method (a template until mono rewrites it
    /// through `Checked::generic_args`; `LocalDefId(u32::MAX)` when
    /// only param evidence proves it in a template body).
    TryFrom(LocalDefId),
    /// A `?` on `Result` whose error converts by a numeric
    /// widening cast (the `From` impls with no user fn).
    TryCast,
    /// A `?` on `Result` whose error converts through the builtin
    /// `From<&str> for String` or `From<&String> for String`: a
    /// copy into a fresh String with no user fn behind it.
    TryStringFrom,
    /// A call of a closure value (ARCH 2.9). `kind` is the Fn trait
    /// the call goes through (an `FnOnce` call consumes the callee),
    /// `derefs` the reference layers peeled off the callee. Lowering
    /// finds the body fn from the callee's closure type.
    ClosureCall {
        kind: closure::ClosureKind,
        derefs: u8,
    },
    /// A method call through a dyn receiver's vtable (ARCH 2.8):
    /// `owner` is the trait that declares the method (the principal
    /// or a supertrait, reached by its upcast path), `cand` its index
    /// in `object::object_cands` (one generic trait can be a
    /// supertrait twice: `B<u8> + B<u16>`), and `slot` the method's
    /// word index in that trait's vtable.
    DynMethod {
        owner: DefId,
        cand: u8,
        slot: u32,
        derefs: u8,
        autoref: Autoref,
    },
}

/// Which scalar comparison a `Res::PrimCmp` call computes. The
/// Adt is `core::cmp::Ordering`'s session-local index (variants
/// Less, Equal, Greater in that order).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PrimCmpKind {
    /// `PartialOrd::partial_cmp` -> `Option<Ordering>`.
    Partial(AdtId),
    /// `Ord::cmp` -> `Ordering`.
    Total(AdtId),
    /// `eq`/`ne`/`lt`/`le`/`gt`/`ge` -> `bool`, the binary comparison.
    Op(ast::BinOp),
}

/// How a written comparison method answers an operator or a
/// default method (`Res::TraitCmp`, `Res::OrdPick`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CmpVia {
    /// The impl's own method for the operator (`eq`, `ne`, `lt`,
    /// `le`, `gt`, `ge`).
    Direct,
    /// `ne` by core's default body: the negated `eq`.
    NotEq,
    /// `lt`/`le`/`gt`/`ge` by core's default bodies: the impl's
    /// `partial_cmp`, tested for `Some(Less)` and kin.
    Partial(ast::BinOp),
}

/// What rustc knows of a comparison call's `Rhs` (`Ctx::cmp_rhs_shape`).
#[derive(Clone)]
enum CmpShape {
    /// Not known yet: any type fits.
    Any,
    /// A reference of this kind to a type of the inner shape.
    Ref(Mut, Box<CmpShape>),
    /// This type.
    Exact(Ty),
}

/// Which `Ordering` method a `Res::OrderingOp` call computes.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum OrderingOpKind {
    IsEq,
    IsNe,
    IsLt,
    IsGt,
    IsLe,
    IsGe,
    Reverse,
    Then,
    /// `then_with(f)`: `f` is a closure called through `FnOnce`.
    ThenWith,
}

/// Which `Ord` default method a `Res::OrdPick` call runs.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum OrdPickKind {
    Max,
    Min,
    Clamp,
}

/// Which scalar operation a `Res::PrimOp` call computes.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PrimOpKind {
    /// A binary operator trait method: `recv.op(rhs)`.
    Bin(ast::BinOp),
    /// A unary operator trait method: `recv.neg()` / `recv.not()`.
    Un(ast::UnOp),
    /// An assignment operator trait method: `recv.op_assign(rhs)`.
    Assign(ast::BinOp),
    /// `recv.into()` to a scalar target: the widening cast core's
    /// `From` impl is, cast to the call's type.
    IntoCast,
    /// `recv.try_into()` to a scalar target: the checked cast
    /// core's `TryFrom` impl is, to the call's `Result` type
    /// (check/tryfrom.rs).
    TryIntoCast,
    /// `recv.into_iter()` on an iterator: core's blanket
    /// `impl<I: Iterator> IntoIterator for I` returns the receiver.
    IntoIterSelf,
}

/// One user `Deref` autoderef step (rustc's autoderef, ARCH 2.10) of
/// a method call receiver, a field access base, or an explicit `*w`:
/// after `before` builtin derefs of the step's input, lowering calls
/// `f` (the impl's `deref`, or `deref_mut` for a method call that
/// borrows mutably, `mutable`) on a borrow of it; the expression's
/// `Res` derefs then apply to the `&Target` (`target_ref`) it returns.
/// A place step also carries the impl's `deref_mut` (`f_mut`), which
/// lowering calls when it needs the place mutably. `args` and
/// `args_mut` instantiate generic fns (empty for plain ones). `depth`
/// orders a chain of steps (`W -> N -> M`): 0 is the outermost, which
/// applies first.
#[derive(Clone, Debug)]
pub struct DerefRecv {
    pub depth: u8,
    pub before: u8,
    pub f: LocalDefId,
    pub args: Vec<GenericArg>,
    pub f_mut: Option<LocalDefId>,
    pub args_mut: Vec<GenericArg>,
    pub mutable: bool,
    pub target_ref: Ty,
}

/// How a `drain(range)` call's bounds are read at lowering
/// (`lower::drain_into`): the syntactic range form reads its bound
/// expressions from the AST, a value of a builtin range kind (or a
/// `(Bound, Bound)` pair) reads its stored fields, a user
/// `RangeBounds` impl calls its two methods, and a generic
/// parameter (template checks only) just evaluates the argument.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DrainRange {
    Syntactic,
    Value(DrainForm),
    Trait { start: LocalDefId, end: LocalDefId },
    Param,
}

/// The builtin shape a drain argument's bounds are read from.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DrainForm {
    Range,
    RangeInclusive,
    RangeFrom,
    RangeTo,
    RangeFull,
    RangeToInclusive,
    /// A `(Bound<usize>, Bound<usize>)` pair.
    Bounds,
    /// A `(Bound<&usize>, Bound<&usize>)` pair.
    BoundsRef,
}

/// One `base[idx]` place through a written `Index` impl: the
/// impl's `index` fn, its `index_mut` when `IndexMut` also holds,
/// their generic args (filled per instance like deref sites),
/// The place's type is the index expression's own (the `Output`).
#[derive(Clone, Debug)]
pub struct IndexRecv {
    pub f: LocalDefId,
    pub args: Vec<GenericArg>,
    pub f_mut: Option<LocalDefId>,
    pub args_mut: Vec<GenericArg>,
}

/// Which `Checked` table a generic `deref` fn's site fills in.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum DerefTable {
    Recv,
    Coerce,
    Index,
}

/// What a raw pointer use allows of its pointee (tf-fatptr,
/// `Ctx::deferred_raw`). lust builds fat raw pointers to `str`, `[T]`
/// and `dyn Tr` only; a struct with an unsized tail stays out.
#[derive(Clone, Copy, Debug)]
enum RawUse {
    /// Sized, or one of the three fat pointees.
    Pointee,
    /// Sized only: an operation lust builds for thin pointers only.
    Thin(&'static str),
    /// As `Pointee`, but no `dyn Tr`: rustc compares vtable addresses,
    /// which it does not fix (one vtable per codegen unit, merged ones).
    NotDyn(&'static str),
}

/// A coercion applied where a value meets an expected type.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Coerce {
    None,
    /// `&String` to `&str`, or `&&str` style deref coercions ending in `&str`.
    StrFromString,
    /// `&mut T` to `&T`.
    MutToShared,
    /// `&mut T` passed where `&mut T` is expected: reborrow, so the original is not moved.
    Reborrow,
    /// `&&T` (n extra references) to `&T`: copy the inner reference out.
    Deref(u8),
    /// `&[T; N]` to a slice reference; the bool is the target mutability.
    SliceFromArray(bool),
    /// `&Vec<T>` to a slice reference; the bool is the target mutability.
    SliceFromVec(bool),
    /// `&Box<T>` (possibly behind more references) to `&T` or
    /// `&mut T`, and `&&mut T` or `&mut &mut T` to `&T` or `&mut T`:
    /// a reborrow of the place this many derefs down; the bool is the
    /// target mutability.
    BoxToRef(u8, bool),
    /// An unsizing coercion to a dyn reference (ARCH 2.8): `&T` or
    /// `&mut T` to `&dyn Tr` (a new fat pointer), or `&dyn Sub` to
    /// `&dyn Super` (trait upcasting, or dropping auto traits). The
    /// payload is the target reference type.
    Unsize(Ty),
    /// A deref coercion through user `Deref` impls (`&name` to `&str`
    /// for `Name: Deref<Target = str>`): the steps are in
    /// `Checked::deref_coerce`; the payload is the target reference
    /// type.
    UserDeref(Ty),
    /// `UserDeref` whose last target is a `Vec<T>` or `String`, then
    /// that type's builtin deref to `[T]` or `str` (`&LAZY` for a
    /// `LazyLock<Vec<T>>` at `&[T]`). The payload is the target
    /// reference type.
    UserDerefTail(Ty),
    /// `&Cow<B>` (behind this many references in all) to `&B`, the
    /// payload's type (W-STD-B): the Cow's `Deref`.
    CowDeref(u8, Ty),
    /// A `char` used as a str search pattern (`s.contains('x')`):
    /// the value becomes the `&str` of its UTF-8 encoding in a
    /// temporary String, which the search reads during the call.
    CharPat,
    /// A method receiver through the Cow's `Deref` (W-STD-B): this many
    /// derefs reach the `Cow<B>` place, whose `&B` view (the payload's
    /// type) is the receiver the method's own adjustments start from.
    CowRecv(u8, Ty),
    /// An iterator method receiver moved into the `ByNext` wrapper
    /// (the payload's type, W-STD-B check/iter.rs): adapters over a
    /// user iterator call its `next`.
    ByNext(Ty),
    /// An `IntoIterator` argument (`extend`, `from_iter`) moved through
    /// its `into_iter` call (the method instance is in
    /// `Checked::into_iter_calls`): the payload is the final iterator
    /// type, a `ByNext` wrap when the iterator runs through `next`.
    IntoIterCall(Ty),
    /// A value of a fn item type that is not a plain path to the fn (a
    /// local, a field, an index, a call result) to a fn pointer: the
    /// zero-sized value is evaluated, then the trampoline of the item
    /// its type names is the result. The payload is the fn pointer type.
    ReifyFn(Ty),
    /// A reference (or a `*mut T`) to a raw pointer (w-cinterop): the
    /// address value stays; the payload is the raw pointer type. The
    /// borrow ends here, as in Rust: a raw pointer carries no loan.
    RefToPtr(Ty),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum BindMode {
    Move,
    Ref(bool),
}

/// What a lone pattern identifier resolves to (see `Ctx::pat_ident`).
enum PatIdent {
    Const(u32),
    Static,
    Variant(AdtId, u32),
    Other,
}

/// How a checked const pattern value resolves (see
/// `Ctx::check_const_value`).
#[derive(Clone, Copy)]
enum ConstPat {
    /// Compare with the const's value: a scalar, or field by field
    /// for a structural value (lowering's `test_const_value`).
    Value,
    Variant(AdtId, u32),
    OptNone,
}

/// True when a const value holds a NaN float at any depth.
fn const_value_has_nan(v: &crate::ty::consteval::ConstValue) -> bool {
    use crate::ty::consteval::ConstValue as CV;
    match v {
        CV::Float(bits, crate::ty::FloatTy::F32) => f32::from_bits(*bits as u32).is_nan(),
        CV::Float(bits, crate::ty::FloatTy::F64) => f64::from_bits(*bits).is_nan(),
        CV::Aggregate(parts) | CV::Variant(_, parts) => parts.iter().any(const_value_has_nan),
        CV::Repeat(inner, _) | CV::Ref(inner) => const_value_has_nan(inner),
        _ => false,
    }
}

#[derive(Clone, Copy, Debug)]
pub enum PatRes {
    None,
    /// A const item used as a pattern, by index into `Program::consts`.
    ConstItem(u32),
    /// A primitive associated const used as a pattern (`i64::MAX`):
    /// its value (the pattern type carries the width).
    PrimConst(i128),
    /// A body-local const used as a pattern, by index into `Program::body_consts`.
    BodyConst(u32),
    Binding {
        local: u32,
        mode: BindMode,
    },
    Variant(AdtId, u32),
    /// `Some(..)` (true) or `None` (false).
    Opt(bool),
    /// `Ok(..)` (true) or `Err(..)` (false).
    Res(bool),
    /// `hash_map::Entry::Occupied(..)` (true) or `Entry::Vacant(..)`
    /// (false) on a map Entry (W-STD-B).
    Entry(bool),
}

#[derive(Clone)]
pub struct LocalInfo {
    pub name: Sym,
    pub ty: Ty,
    pub mutable: bool,
    pub span: Span,
}

/// The checker's output for one function. Clone: borrowck lowers each
/// closure of a fn from one check of it (`closure_reqs`).
#[derive(Clone)]
pub struct Checked<'g> {
    pub tys: Tys<'g>,
    pub expr_base: u32,
    pub pat_base: u32,
    pub expr_ty: Vec<Ty>,
    /// The const value of an expression the checker evaluated (a const item
    /// reference or an inline const block), parallel to `expr_ty`.
    pub const_exprs: Vec<Option<crate::ty::consteval::ConstValue>>,
    /// The anonymous consts of written types and paths in this body that
    /// the checker typed as code (`Ctx::type_anon_const`): lowering
    /// borrow-checks each as a body of its own.
    pub anon_exprs: Vec<ExprId>,
    /// The promotion qualifs of const item paths (`ty::constqual`),
    /// by expression; a const path with none qualifies by its type
    /// (a trait associated const: rustc does not look inside it).
    pub const_quals: crate::intern::FxMap<ExprId, crate::ty::constqual::Qualif>,
    pub expr_res: Vec<Res>,
    pub coerce: Vec<Coerce>,
    pub pat_ty: Vec<Ty>,
    pub pat_res: Vec<PatRes>,
    /// The const value of a pattern that is a primitive associated
    /// const (`u8::MAX => ..`), parallel to `pat_res`.
    pub pat_const: Vec<Option<crate::ty::consteval::ConstValue>>,
    /// Number of implicit derefs before matching each pattern (default binding modes).
    pub pat_derefs: Vec<u8>,
    /// Generic arguments of each generic call or method call, by
    /// expression index (empty for plain calls), after zonking.
    /// Lowering resolves the template in the call's `Res` plus
    /// these args to a mono instance.
    pub generic_args: Vec<Vec<GenericArg>>,
    /// Generic sites by (expression index, template): the
    /// `generic_args` slot of the same expression only keeps
    /// one site (last write), but a `for` head holds two (its
    /// own call and the loop's `next`), distinguished here.
    pub generic_site_args: Vec<(usize, LocalDefId, Vec<GenericArg>)>,
    /// Instance requests found while checking: (template,
    /// zonked args in this body's store). Mono lifts and
    /// materializes them; the driver never reads this.
    pub inst_requests: Vec<(LocalDefId, Vec<GenericArg>)>,
    /// Trait picks of a template check (see `picks.rs`), in check
    /// order. Mono stores them for the body's other checks.
    pub trait_picks: Vec<(ExprId, picks::TraitPick)>,
    /// Vtable requests from unsizing coercions: (concrete pointee
    /// type, target dyn type), zonked. Mono builds the vtables.
    pub vtable_requests: Vec<(Ty, Ty)>,
    /// Expressions that go through user `Deref` impls (method call
    /// receivers, field access bases, explicit `*x`, index bases), by
    /// expression; a chain of impls records one entry per step (see
    /// `DerefRecv::depth`).
    pub deref_recv: Vec<(ExprId, DerefRecv)>,
    /// The range form of each `drain` call, by expression.
    pub drain_ranges: Vec<(ExprId, DrainRange)>,
    /// The range form of each range-value index (`v[r]`), by the
    /// index expression (check/slice.rs).
    pub index_ranges: Vec<(ExprId, DrainForm)>,
    /// Comparisons between different sequence forms (slice, array,
    /// Vec) that lower as slice comparisons (check/slice.rs).
    pub seq_cmps: Vec<ExprId>,
    /// `if` then-block tails whose coercion rustc's LUB applies to the
    /// whole block (`lub_flip`), after the block's tail temporaries
    /// drop: `if c { &&G } else { &v[0] }` reborrows through a dead
    /// `&G` (E0716). Lowering coerces such a block's value (`block_into`).
    pub after_tail: Vec<ExprId>,
    /// The `into_iter` method instance of each `Coerce::IntoIterCall`
    /// (an `extend` or `from_iter` argument), by coerced expression.
    pub into_iter_calls: Vec<(ExprId, LocalDefId)>,
    /// The steps of each `Coerce::UserDeref`, by coerced expression,
    /// outermost first.
    pub deref_coerce: Vec<(ExprId, DerefRecv)>,
    /// Written-`Index` places, by the index expression; also the
    /// written `Borrow<str>::borrow` fn of a `[S]::join`/`concat`
    /// element (`f` only), by the method call (`SliceJoinBorrow`).
    pub index_recv: Vec<(ExprId, IndexRecv)>,
    pub locals: Vec<LocalInfo>,
    /// Locals bound to the function parameters, in order (including `self`).
    pub param_locals: Vec<u32>,
    /// Every cross-item node this body read through a query function
    /// (docs/ARCH.md section 8.2). Stored with the result; nothing consumes
    /// it for invalidation yet (S7 is record-only).
    pub reads: Reads,
    /// The closure expressions of this body, in check order, zonked.
    pub closures: Vec<closure::ClosureInfo>,
    /// Every closure call and the Fn trait it goes through. Mono keeps
    /// the template's answers for its instances (`template_calls`).
    pub closure_calls: Vec<(ExprId, closure::ClosureKind)>,
    /// Calls of a primitive method item through an Fn-family bound (in
    /// an instance), with the line of the Fn trait method rustc's fn
    /// item shim runs in core/src/ops/function.rs: a `#[track_caller]`
    /// panic in the item reports it (`Ctx::value_call`).
    pub fn_shim_calls: Vec<(ExprId, u32)>,
    /// True when this is a closure body fn whose parent failed to
    /// check: the parent reports the errors, lowering emits nothing.
    pub poisoned: bool,
    /// The regioned type a `let` annotation with an explicit lifetime
    /// gives each binding it covers, by checker local (W-BORROW): the
    /// borrow checker relates the binding's regions to it.
    pub annotations: Vec<(u32, Ty)>,
    /// The regioned target type of each cast whose target names a lifetime
    /// (`record_cast_annotation`), by cast expr: lowering puts the cast's
    /// value in a temporary annotated with it.
    pub cast_annotations: Vec<(ExprId, Ty)>,
    /// Obligations taken from this body's queue, once per take (each
    /// run round takes them all; `Obligations::work`). A work count for
    /// tests that guard against selection blow-ups.
    pub queue_work: usize,
    /// The hidden type of each `impl Trait` this body defines
    /// (`check::opaque`), by opaque def.
    pub opaque_hidden: Vec<(DefId, Ty)>,
    /// A revealed check's types of the values that hold `impl Trait`
    /// values in its opaque view, each with how (`opaque::Hold`):
    /// lowering marks the temporaries whose types hold one
    /// (`Body::opaque_locals`).
    pub opaque_holds: Vec<(Ty, opaque::Hold)>,
    /// How each checker local (binding) holds `impl Trait` values in the
    /// opaque view, which marks its IR local directly; empty when the
    /// two checks' bindings do not line up (then the type match decides).
    pub local_holds: Vec<opaque::Hold>,
    /// Per expression (by index from `expr_base`), true when its value
    /// is `Copy` here but not in the opaque view (an `impl Trait` whose
    /// hidden type is `Copy` and its bounds do not say so): rustc moves
    /// it, so lowering does too (`opaque::holds_from_view`). Empty when
    /// none is.
    pub expr_moves: Vec<bool>,
    /// The same per checker local (binding), for the moves lowering
    /// makes from places: by-value bindings and closure captures.
    pub local_moves: Vec<bool>,
    /// A revealed call of a generic definer whose hidden type holds
    /// closures, before mono made its instance: the types still name the
    /// template's closures. Mono checks the body again once the instance
    /// exists (`opaque::build_closure_map`).
    pub closure_map_pending: bool,
    /// A revealed call of a closure from another body (a non-generic
    /// definer's `impl Trait` hidden type) that no check registered yet:
    /// its kind and signature are unknown, so this check's closures and
    /// requests are provisional. Mono drops them and checks the body
    /// again after the definer (`closure::closure_facts`).
    pub closure_kind_pending: bool,
}

impl Checked<'_> {
    pub fn ty(&self, e: ExprId) -> Ty {
        self.expr_ty[(e.0 - self.expr_base) as usize]
    }
    pub fn res(&self, e: ExprId) -> Res {
        self.expr_res[(e.0 - self.expr_base) as usize]
    }
    /// The panic location of a call through a fn item shim
    /// (`fn_shim_calls`): core/src/ops/function.rs at the Fn trait
    /// method's line.
    pub fn fn_shim_span(&self, e: ExprId) -> Option<Span> {
        self.fn_shim_calls.iter().find(|(x, _)| *x == e).map(|&(_, line)| Span::std_site(15, line, 5))
    }
    /// The range form of a `drain` call (check/iter.rs).
    pub fn drain_range(&self, e: ExprId) -> Option<DrainRange> {
        self.drain_ranges.iter().find(|(x, _)| *x == e).map(|(_, d)| *d)
    }
    /// The range form of a range-value index (check/slice.rs).
    pub fn index_range(&self, e: ExprId) -> Option<DrainForm> {
        self.index_ranges.iter().find(|(x, _)| *x == e).map(|(_, d)| *d)
    }
    /// True for a comparison between different sequence forms
    /// (check/slice.rs `seq_cmp`).
    pub fn is_seq_cmp(&self, e: ExprId) -> bool {
        self.seq_cmps.contains(&e)
    }
    /// The `into_iter` instance of a `Coerce::IntoIterCall` on `e`.
    pub fn into_iter_call(&self, e: ExprId) -> Option<LocalDefId> {
        self.into_iter_calls.iter().find(|(x, _)| *x == e).map(|(_, d)| *d)
    }
    /// True for a then-block tail coerced after its block (`after_tail`).
    pub fn is_after_tail(&self, e: ExprId) -> bool {
        self.after_tail.contains(&e)
    }
    pub fn coerce(&self, e: ExprId) -> Coerce {
        self.coerce[(e.0 - self.expr_base) as usize]
    }
    pub fn pat_ty(&self, p: PatId) -> Ty {
        self.pat_ty[(p.0 - self.pat_base) as usize]
    }
    pub fn pat_res(&self, p: PatId) -> PatRes {
        self.pat_res[(p.0 - self.pat_base) as usize]
    }
    pub fn pat_const(&self, p: PatId) -> Option<&crate::ty::consteval::ConstValue> {
        self.pat_const[(p.0 - self.pat_base) as usize].as_ref()
    }
    pub fn const_value(&self, e: ExprId) -> Option<&crate::ty::consteval::ConstValue> {
        self.const_exprs[(e.0 - self.expr_base) as usize].as_ref()
    }
    pub fn pat_derefs(&self, p: PatId) -> u8 {
        self.pat_derefs[(p.0 - self.pat_base) as usize]
    }
    /// The user `Deref` steps of a method call's receiver, a field
    /// access base, or an explicit `*x`, outermost first.
    pub fn deref_recv(&self, e: ExprId) -> Vec<&DerefRecv> {
        let mut steps: Vec<&DerefRecv> = self.deref_recv.iter().filter(|(x, _)| *x == e).map(|(_, d)| d).collect();
        steps.sort_by_key(|d| d.depth);
        steps
    }
    /// The steps of a `Coerce::UserDeref` on `e`, outermost first.
    pub fn deref_coerce(&self, e: ExprId) -> Vec<&DerefRecv> {
        self.deref_coerce.iter().filter(|(x, _)| *x == e).map(|(_, d)| d).collect()
    }
    /// The written-`Index` record of an index expression, if any.
    pub fn index_recv(&self, e: ExprId) -> Option<&IndexRecv> {
        self.index_recv.iter().find(|(x, _)| *x == e).map(|(_, d)| d)
    }
}

struct Var {
    bound: Option<Ty>,
}

struct LoopCtx {
    break_ty: Option<Ty>,
    /// A fn pointer type the `loop` or labeled block is expected to
    /// have: rustc coerces every break value to it (its CoerceMany
    /// target), so distinct closures in breaks reify. Only a fn pointer
    /// expectation seeds it, since lust's other expectations can be
    /// hints that rustc would not coerce to.
    want: Option<Ty>,
    /// True when `break` may carry a value (a `loop` or a labeled block).
    is_loop: bool,
    /// True for a labeled block, which `continue` cannot target.
    is_block: bool,
    /// The label and its binding span; hygiene reads the span's context.
    label: Option<(Sym, Span)>,
}

struct Ctx<'p> {
    p: &'p Program,
    f: &'p FnInfo,
    /// The crate's recursion limit (128 unless `#![recursion_limit]`):
    /// nested trait obligations overflow at this depth, as in rustc.
    recursion_limit: usize,
    /// `depth::struct_depth` answers for this body's types.
    depth_memo: crate::intern::FxMap<(depth::Family, Ty), usize>,
    /// `auto_holds` answers for types with no param, inference variable or
    /// projection, while `opaque_env` is empty: they read only the program
    /// and the fn's own env, which a check does not change.
    auto_memo: crate::intern::FxMap<(DefId, Ty), Option<bool>>,
    /// The module this fn is defined in (root without the resolver),
    /// for field visibility checks (ARCH 1.5).
    module: crate::ty::defs::ModuleId,
    tys: Tys<'p>,
    vars: Vec<Var>,
    /// Variables a `!` value flowed into (rustc's diverging type
    /// variables). An unbound root of one falls back to `!` at body end
    /// (edition 2024), so it is no annotation error.
    diverging: Vec<u32>,
    out: Checked<'p>,
    /// Locals by (name, hygiene context): a local a macro introduces does
    /// not bind a caller ident of the same name, and an ident the caller
    /// passes in keeps the caller's context (ARCH 6.3).
    scopes: Vec<((Sym, CtxtId), u32)>,
    /// Items declared in enclosing blocks, keyed like locals by name and
    /// hygiene context, holding stmt item indexes.
    item_scopes: Vec<Vec<((Sym, CtxtId), u32)>>,
    /// `scopes.len()` when each `item_scopes` layer was pushed: a local
    /// below it is declared outside that block, so the block's items
    /// shadow it (`lookup`).
    item_scope_starts: Vec<usize>,
    /// Traits the `use` items of enclosing blocks bring into scope
    /// for method calls (`Ast::use_traits`, recorded by the
    /// resolver), one layer per block, pushed with `item_scopes`:
    /// crate traits by def, and std traits also by canonical path
    /// for the by-path queries (`std_trait_imported`).
    trait_scopes: Vec<Vec<DefId>>,
    std_trait_scopes: Vec<Vec<Vec<Sym>>>,
    /// Type items declared in enclosing blocks (R18), one layer of
    /// stmt item indexes per block, pushed with `item_scopes`.
    /// `body_scope`'s local tables are the base (from the fn's own
    /// scope, for a nested fn) plus these layers, rebuilt on every
    /// push and pop (`refresh_type_overlay`).
    type_layers: Vec<Vec<u32>>,
    /// `body_scope`'s local tables at body entry (the overlay base).
    overlay_base: (Vec<(Sym, AdtId, Option<ast::Generics>)>, Vec<(Sym, Ty)>, Vec<(Sym, DefId)>),
    loops: Vec<LoopCtx>,
    errs: Vec<Diag>,
    negated_lits: Vec<ExprId>,
    /// The trait obligation queue (ARCH 2.4), run at the fixed
    /// points in `run_obligations`.
    obl: obligations::Obligations,
    /// This fn's own local id, for its scope and env.
    fid: LocalDefId,
    /// Selection state (memos, cycle stack) for this body.
    solver: Solver,
    /// Rollback trail of variable bindings, for solver probes.
    trail: Vec<u32>,
    /// The scope body annotations resolve under (with `_` markers on).
    body_scope: Scope,
    /// Generic call sites to turn into instance requests at
    /// finish: (expression index, template, args before zonking).
    generic_sites: Vec<(usize, LocalDefId, Vec<GenericArg>)>,
    /// Trait associated const reads a template check proved only
    /// by its bounds: no value is known until an instance picks
    /// the impl. `finish` gives them a zero placeholder (after
    /// the overflow lint, so no analysis reads the fake value)
    /// purely so the template body lowers for borrowck.
    abstract_consts: Vec<ExprId>,
    /// While the const evaluator runs a const fn body (`CheckCx`'s
    /// `enter_const_fn`), the Adt `Self` means there: the fn's impl
    /// type, not this body's. Saved (override, Self type) pairs restore
    /// on exit.
    const_fn_self: Option<Option<AdtId>>,
    const_fn_saved: Vec<(Option<Option<AdtId>>, Option<Ty>)>,
    /// Saved block item scopes for const fn bodies the evaluator
    /// entered: a const fn body names its own sibling items
    /// (`next_const_fn_sibs`, stashed by `call_target`), never the
    /// caller's block items.
    const_fn_items_saved: Vec<(Vec<Vec<((Sym, CtxtId), u32)>>, Vec<usize>, Vec<Vec<DefId>>, Vec<Vec<Vec<Sym>>>, Vec<Vec<u32>>)>,
    next_const_fn_sibs: Option<Vec<u32>>,
    /// Trait method calls whose impl is selected at finish (see
    /// `method::confirm_deferred`).
    deferred_methods: Vec<method::DeferredMethod>,
    /// `as_deref` calls on an `Option` or `Result` whose payload is
    /// still open at the call; the impl is picked at finish
    /// (`method::DeferredLangMethod`, fx-option-rest).
    deferred_lang_methods: Vec<method::DeferredLangMethod>,
    /// Method calls where rustc picks a std inherent item before any user
    /// trait's method (check/std_inherent.rs): the trait probe skips user
    /// traits for them.
    std_first: Vec<ExprId>,
    /// The method call `method_via_user_deref` is probing on its target:
    /// its receiver is `&Target` there, where rustc's step is the place.
    user_deref_call: Option<ExprId>,
    /// Method calls whose Self Adt has a private inherent method of the
    /// called name: the probes skip it (rustc E0624 only when nothing
    /// else answers, `method_call_at`).
    private_inherent: Vec<(ExprId, AdtId)>,
    /// The last trait pick a probe confirmed (`record_pick_env`): the call
    /// and its trait.
    last_pick: Option<(ExprId, DefId)>,
    /// `?` expressions whose error type was still a projection:
    /// (expr, error type, return error type, span). Their
    /// conversion decides at body end (`decide_try_res`).
    deferred_try: Vec<(ExprId, Ty, Ty, Span)>,
    /// Operators whose result waits on an `Output` obligation because
    /// an operand was a general variable at their first check (see
    /// `binary`).
    deferred_binops: Vec<ExprId>,
    /// Format arguments whose type was still a variable when
    /// the format check ran: (type, spec, span). The format test
    /// re-runs at finish (W-TRAITS-CORE).
    deferred_fmt: Vec<(Ty, FmtSpec, Span)>,
    /// The resolved first turbofish type of the method call being
    /// checked, for the builtin iterator methods (`collect::<T>()`).
    turbofish_ty: Option<Ty>,
    /// `size_of_val` / `align_of_val` calls whose pointee type held an
    /// inference variable (call, pointee, align, span): answered at the
    /// body end (W-STD-C).
    deferred_layout: Vec<(ExprId, Ty, bool, Span)>,
    /// Element types a builtin Vec or slice method needs to be
    /// Clone (`extend_from_slice`, `resize`, `to_vec`), re-tested
    /// at finish like the format traits: the element type can
    /// still be a variable at the call.
    deferred_clone: Vec<(Ty, Span)>,
    /// Input types of `String::from` used as a value
    /// (`.map(String::from)`), re-tested at finish: lust's
    /// `String::from` takes `&str`, `char`, or `String`.
    deferred_string_from: Vec<(Ty, Span)>,
    /// (Target, input) of a primitive `T::from` used as a value
    /// (`map(u64::from)`, TRIAGE T12), re-tested at finish
    /// against `std_from`, like `deferred_string_from`.
    deferred_prim_from: Vec<(Ty, Ty, Span)>,
    /// (callee, call, target, input, span) of a `Box::from(x)` (or `Rc`,
    /// `Arc`) whose target only a later coercion fixes
    /// (`Box::leak(Box::from(s))` into `&str`, check/own.rs): the std
    /// conversion is picked at finish, as rustc selects the `From`
    /// impl once the target is known.
    deferred_own_from: Vec<(ExprId, ExprId, Ty, Ty, Span)>,
    /// Types a `std::any::type_name::<T>()` call names, tested at
    /// finish: lust must be able to print rustc's exact string for
    /// each (`any::type_name_of`), else the call is a reject.
    deferred_type_names: Vec<(Ty, Span)>,
    /// `extend` calls that both `Extend<T>` and `Extend<&T>` fitted,
    /// decided at finish (check/extend.rs `finish_deferred_extends`).
    deferred_extend: Vec<extend::DeferredExtend>,
    /// Trait fn values (`Into::into` in `.map(..)`, check/traitpath.rs)
    /// and calls through them: body end selects what each calls
    /// (`finish_trait_fn_values`, `finish_trait_fn_calls`).
    deferred_trait_fn_values: Vec<(ExprId, TraitRef, Sym, Vec<GenericArg>, Span)>,
    deferred_trait_fn_calls: Vec<(ExprId, TraitRef, Sym, Vec<GenericArg>, Span)>,
    /// Element types a builtin Vec method needs to be PartialEq
    /// (`contains`, `dedup`), re-tested at finish as above.
    deferred_eq: Vec<(Ty, Span)>,
    /// `collect` calls whose target type a later use fixes
    /// (`let r = it.collect(); (r, n)` returned as `(Vec<String>, _)`):
    /// target, item, and span, checked at finish (`collect_target_ok`).
    /// `collect` calls whose target only a later use fixes: target, item,
    /// span, and the call (expr, receiver type, derefs) for the
    /// `FromIterator` route (`Ctx::from_iter_route`).
    deferred_collect: Vec<(Ty, Ty, Span, (ExprId, Ty, u8))>,
    /// `sum`/`product` calls whose item type was open: (target, item,
    /// is `sum`, span), checked at body end (`finish_deferred_sums`).
    deferred_sum: Vec<(Ty, Ty, bool, Span)>,
    /// Item types an iterator method needs to be Copy (`copied`),
    /// re-tested at finish as above (W-STD-A).
    deferred_copy: Vec<(Ty, Span)>,
    /// `repeat_n(x, n)` element types: lust copies them bitwise, so a Copy
    /// type with a written `Clone` (which std's `repeat_n` calls) is
    /// rejected at body end.
    deferred_repeat_n: Vec<(Ty, Span)>,
    /// `Range<{integer}>::len` and kin: the element must end as one of
    /// core's exact-size range integers (check/iter.rs `exact_size`).
    deferred_exact_range: Vec<(Ty, bool, Span)>,
    /// `std::io::copy` calls: the `&mut R` and `&mut W` argument types,
    /// checked once known (`platform::io_copy_diag`).
    deferred_io_copy: Vec<(Ty, Ty, Span)>,
    /// The spans of a thread spawn's `F: 'static` obligation (check/sync.rs
    /// `require_spawn_static`). There a `dyn` with an inferred object
    /// lifetime (`let b: Box<dyn FnOnce() + Send> = ..` in a body) is the
    /// borrow checker's to prove: its spawn rule makes every region of
    /// the function `'static` (borrowck/regions.rs).
    spawn_static: Vec<Span>,
    /// Set while `static_bound_err` may pass a `dyn` with an inferred
    /// object lifetime: a `spawn_static` obligation, or the retry of
    /// `check_type_static` that hands the bound to the borrow checker.
    static_dyn_inferred_ok: bool,
    /// The expression of the expression statement being checked (`e;`):
    /// `Vec::splice` is taken only there, where its `Splice` drops at once.
    stmt_expr: Option<ExprId>,
    /// Item or key types an iterator method needs to be Ord (`min`,
    /// `max`, `min_by_key`, `max_by_key`), re-tested at finish.
    deferred_ord: Vec<(Ty, Span)>,
    /// Element or key types of `sort`/`sort_unstable`/`sort_by_key`:
    /// Ord, and a `PartialOrd::lt` lust can call (std's sort compares
    /// with `lt`, not `Ord::cmp`), re-tested at finish.
    deferred_sort_ord: Vec<(Ty, Span)>,
    /// Fn item / fn pointer casts whose target holds a `_`:
    /// rustc checks the signatures after inference, so the
    /// operand does not bind the `_` at the cast. The pair is
    /// (operand type, target type); rechecked at finish.
    deferred_fn_casts: Vec<(Ty, Ty, Span)>,
    /// Coercion casts (`&[1, 2] as &[u8]`, `Box::new(|| 1) as Box<dyn
    /// Fn() -> u8>`) whose operand holds an inference var: rustc checks
    /// casts at body end after literal fallback, so the cast must not
    /// pick a literal's type, also one a later use gives a var (`&v as
    /// &Vec<u8>` before `v.push(5)`). (operand type, target, span,
    /// operand); rechecked at finish.
    deferred_coerce_casts: Vec<(Ty, Ty, Span, ExprId)>,
    /// Casts whose operand type is still an open variable (a closure
    /// parameter a later trait selection fixes, `|child| child as
    /// usize`): rustc checks casts at body end (`check_casts`), so these
    /// are checked in `finish`, after literal fallback. (operand type,
    /// target, span).
    deferred_open_casts: Vec<(Ty, Ty, Span)>,
    /// `x.into()` calls whose target was open at the call, as (call,
    /// receiver type, target variable, method name span): resolved at
    /// body end through std's conversions once a later use fixed the
    /// target (`let y = s.into(); t(y)`), as rustc's pending `Into`
    /// obligation.
    deferred_into: Vec<(ExprId, Ty, Ty, Sym, Span)>,
    /// Types a `Result` method formats with Debug in its panic message.
    deferred_debug: Vec<(Ty, Span)>,
    /// Types a `take` builds with `Default::default()`.
    deferred_default: Vec<(Ty, Span)>,
    /// `vec![x; n]` element types still open at the macro: their Clone
    /// check runs at body end.
    deferred_vec_clone: Vec<(Ty, Span)>,
    /// Element types of Rc fns that lust only has for a sized `T`
    /// (by-value `try_unwrap` and `into_inner`, `get_mut`, and
    /// `downgrade`, whose `Weak` is a thin pointer).
    deferred_sized: Vec<(Ty, Span)>,
    /// Raw pointer pointees and casts checked at body end (tf-fatptr):
    /// which fat pointees (`str`, `[T]`, `dyn Tr`) a use allows.
    deferred_raw: Vec<(Ty, Span, RawUse)>,
    deferred_raw_casts: Vec<(Ty, Ty, Span)>,
    /// `Rc::downgrade` element types: sized, or a plain dyn value.
    deferred_downgrade: Vec<(Ty, Span)>,
    /// The pointee of an `Rc::make_mut`/`get_mut` (`Arc::make_mut`) call
    /// and whether it must be cloned (`make_mut`): checked at body end
    /// (check/own.rs `finish_make_mut`).
    deferred_make_mut: Vec<(Ty, Span, bool)>,
    /// Map and set keys and lookup types, re-tested at finish
    /// (`check_hash_key`, W-STD-B): (key, lookup, span).
    deferred_hash_key: Vec<(Ty, Ty, Span)>,
    /// Values the hash glue hashes for `x.hash(..)` and `hash_one(x)`,
    /// re-tested at finish (`glue_hash_ok`, W-STD-B).
    deferred_glue_hash: Vec<(Ty, Span)>,
    /// True while normalization runs inside `unify`, to keep
    /// projection normalization from recursing into itself.
    in_norm: bool,
    /// Const inference variables (from `generics::INFER_MARKER_BASE`)
    /// to the consts they bound to.
    const_bindings: std::collections::HashMap<u32, ConstId>,
    next_const_id: u32,
    /// Closures checked so far in this body (see `check::closure`).
    closures: Vec<closure::ClosureInfo>,
    /// Return types of the closure bodies being checked, innermost last:
    /// `return` inside a closure returns from the closure.
    closure_rets: Vec<Ty>,
    /// The return type this body checks against (`defining_ret`).
    fn_ret: Ty,
    /// This body's own `impl Trait` returns: (opaque def, its args, the
    /// variable standing for the hidden type).
    own_opaques: Vec<(DefId, ArgsId, Ty)>,
    /// How this check sees the `impl Trait` values of its callees
    /// (check/opaque.rs): rigid with their bounds, or revealed.
    opaque_mode: opaque::OpaqueMode,
    /// The trait picks the opaque view of this same body recorded, which
    /// its revealed check replays (`replay_pick`).
    view_picks: crate::intern::FxMap<ExprId, picks::TraitPick>,
    /// The Fn trait each call of an opaque callable went through in the
    /// opaque view, which the revealed check keeps (a closure behind
    /// `impl FnOnce` is consumed even when it is `Fn`).
    view_calls: crate::intern::FxMap<ExprId, opaque::ViewCall>,
    /// The bounds of the callee opaque types this body has met, elaborated,
    /// after the fn's own env (`opaque::note_opaques`); empty until one.
    opaque_env: Vec<Predicate>,
    opaque_seen: Vec<Ty>,

    /// The revealed callee returns that name a generic definer's opaque,
    /// and the closure def map body end builds from them for `zonk`
    /// (`opaque::callee_closure_map`).
    opaque_calls: Vec<Ty>,
    closure_map: Vec<(Ty, DefId)>,
    /// Body end: the bare inner iterators of builtin adapters that revealed
    /// opaque calls left, with their replacements (`build_closure_map`,
    /// `opaque::replace_iter_args`), which `zonk` applies.
    iter_arg_map: Vec<(Ty, Ty)>,
    /// Per template closure that a revealed generic `impl Trait` call
    /// put in a type: the call's args for the definer's params, which
    /// the closure's signature names, and the closure type the call
    /// revealed (`closure_facts`).
    opaque_closure_args: Vec<(DefId, ArgsId, Ty)>,
    /// This body's closure expressions in token order, for their defs.
    closure_order: Option<Vec<ExprId>>,
    /// The closure-argument type vars of iterator methods (`iter.rs`
    /// `fn_mut_param`) and of generic calls whose `Fn` bound takes type
    /// params (`note_closure_bounds`), each with one flag per argument:
    /// true when its outer reference is higher-ranked (`&item`). W-BORROW:
    /// the other argument regions are free; see `ClosureInfo::free_args`.
    iter_closure_args: std::collections::HashMap<u32, Vec<bool>>,
    /// W-THREADS: the closure-argument type var of each `thread::scope`
    /// call (`ClosureInfo::scope_body`).
    scope_closure_vars: Vec<u32>,
    /// W-BORROW: the closure-argument type vars of generic calls whose
    /// regioned `Fn` bound has a higher-ranked output over its one
    /// elided input lifetime (`F: Fn(&T) -> &U`), with that output's
    /// regioned type (`ClosureInfo::bound_output`).
    closure_bound_outputs: std::collections::HashMap<u32, Ty>,
    /// The regioned inputs of the `Fn` bound a closure var is passed to
    /// (`ClosureInfo::bound_inputs`).
    closure_bound_inputs: std::collections::HashMap<u32, Vec<Ty>>,
    /// Inference vars of closure arguments for a bound whose output holds
    /// a callee type param (`ClosureInfo::call_out`).
    closure_call_outs: std::collections::HashSet<u32>,
    /// Scalar operators checked while both operand types were still
    /// open (a closure's `|a, b| a + b`): (expr, op, operand type).
    /// Lowering emits the builtin operator, so the types must turn out
    /// scalar by body end (see `finish`).
    open_binops: Vec<(ExprId, BinOp, Ty)>,
    /// Operators whose trait selection rustc leaves pending on an open
    /// operand (`binop_waits`): (expr, op, lhs type, rhs type, rhs
    /// expr, span, result type unless an `Output` projection carries
    /// it), checked at body end.
    wait_binops: Vec<(ExprId, BinOp, Ty, Ty, ExprId, Span, Option<Ty>)>,
    /// `assert_eq!`/`assert_ne!` whose left type was open: (expr, left
    /// type, right type, macro span, right span), checked at body end.
    wait_asserts: Vec<(ExprId, Ty, Ty, Span, Span)>,
    /// Compound assignments with a known number on the left and an open
    /// right operand: (expr, op, lhs type, rhs type, rhs expr, span),
    /// checked at body end.
    wait_assign_ops: Vec<(ExprId, BinOp, Ty, Ty, ExprId, Span)>,
    /// Unsizing coercion sites, (concrete pointee, dyn type, span)
    /// before zonking; `finish` turns them into vtable requests.
    vtable_sites: Vec<(Ty, Ty, Span)>,
    /// `catch_unwind` closures and `panic_any` payloads, checked at
    /// body end (check/unwind.rs).
    unwind_checks: Vec<unwind::UnwindCheck>,
    /// True once an unsizing coercion made a dyn value from one that
    /// may hold a borrow (see `dyn_static_clean`).
    dyn_borrow_src: bool,
    /// The expected result type of the method call being checked, by
    /// call expression: a generic method's closure arguments read it
    /// (`expected_output_first`).
    pub(super) call_expected: Option<(ExprId, Ty)>,
    /// Variables of a generic call's return type that only the call's
    /// expected type fixed (`expected_output_first`), and whether the
    /// variable is the whole return type: rustc does not know them in a
    /// closure argument's body (`expect_only_output`).
    pub(super) expect_only_vars: Vec<(u32, bool)>,
    /// `return` expressions checked so far (a closure body compares it
    /// before and after, `closure_expr`).
    pub(super) returns_seen: u32,
    /// The fn body's own result expressions: its tail and each `return`
    /// operand, through block tails. Only a closure among them takes the
    /// return-position `impl Fn*` bound's signature (rustc's expectation
    /// reaches no `if` or `match` arm; `ClosureCx::rpit_bound`).
    pub(super) ret_exprs: Vec<ExprId>,
    /// Closures checked with no expected signature, with the params that
    /// have no type annotation: their argument regions are inferred, one
    /// each, never higher-ranked (`finish_opaques`).
    pub(super) free_sig_closures: Vec<(DefId, Vec<bool>)>,
    /// `if`, `match` and block expressions checked with only an earlier
    /// arm's type as their expectation (`branch_hint`): rustc checks them
    /// with none, so they coerce nothing to it themselves; the enclosing
    /// arm's LUB coerces their whole value, after their blocks.
    pub(super) hinted: Vec<ExprId>,
    /// User `Deref` steps the method lookup is inside (a bound on
    /// `Deref` chains).
    deref_depth: u8,
    /// Generic `deref` (or `deref_mut`, the flag) fns of
    /// `out.deref_recv` entries: the entry, the template, and its impl
    /// args (zonked into the entry and requested as instances at body
    /// end).
    deref_sites: Vec<(DerefTable, usize, bool, LocalDefId, Vec<GenericArg>)>,
    /// Instances of written `into_iter` fns that `flatten` calls per
    /// item (check/iter.rs `written_into_iter_fn`): zonked into
    /// `inst_requests` at body end.
    into_iter_requests: Vec<(LocalDefId, Vec<GenericArg>)>,
    /// Expressions with entries in `out.deref_recv`, `deref_coerce`, or
    /// `index_recv`. A second check of such an expression (a trial check,
    /// or an argument checked to pick a form and then again) first drops
    /// its old entries (`forget_place_steps`), so lowering runs each user
    /// `deref` and `index` once, as recorded by the last check.
    place_step_exprs: crate::intern::FxMap<ExprId, ()>,
    /// Or-pattern alternatives being checked against the first
    /// alternative's bindings, innermost last (see the `Pat::Or`
    /// arm of `pattern_mode`).
    or_frames: Vec<OrFrame>,
    /// Bindings of the or-pattern first alternative currently
    /// being recorded, when any (see `bind_pattern_local`).
    or_log: Option<Vec<OrBind>>,
    /// Scope length at entry to each enclosing `pattern` call:
    /// bindings between the mark and the end of `scopes` belong
    /// to that one pattern and may not repeat a name.
    pat_marks: Vec<usize>,
    /// Inside a const context (an inline const, a repeat count, an
    /// anonymous const of a written type): the number of locals declared
    /// before it, which it may not name (rustc E0435). 0 outside.
    const_floor: u32,
}

/// One name bound by a pattern alternative, with the checker
/// local every alternative shares.
#[derive(Clone)]
struct OrBind {
    name: Sym,
    ctxt: CtxtId,
    local: u32,
    mode: BindMode,
    /// The binding's own type (after its mode is applied).
    ty: Ty,
    /// The `mut` of the local itself (`ref mut` lives in `mode`).
    mutable: bool,
}

/// Checking one non-first or-pattern alternative: the bindings
/// the first alternative made, which of them this alternative
/// has bound so far, and names it bound that the first did not.
struct OrFrame {
    expected: Vec<OrBind>,
    seen: Vec<bool>,
    extra: Vec<(Sym, Span)>,
}

/// The module a body checks in: the module of the def that owns
/// the body, exactly as a non-generic body in that module sees it
/// (ARCH 1.5). AST fns read the resolver's def table
/// (`collect::def_module_of_fn`), else `fn_module` by `LocalDefId`. Fns mono
/// appends are past that vec: an instance takes its template's
/// module, and a trait-default template (or a template with no
/// local form) takes the module its def was defined in. Closure
/// body fns never reach here (`check_fn` checks them as their
/// parent). Without resolver tables every body is in the root.
fn defining_module(p: &Program, fid: LocalDefId) -> crate::ty::defs::ModuleId {
    let root = crate::ty::defs::ROOT_MODULE;
    // The lang enum methods (their instances and closure bodies share
    // their def) see no user names.
    if p.in_lang_methods(p.fn_def(fid).name_span) {
        return crate::ty::defs::STD_MODULE;
    }
    let Some(tables) = &p.resolved else { return root };
    if let Some(m) = const_body::module_of(p, fid) {
        return m;
    }
    // A def's defining module from the resolver table. Associated
    // defs (trait methods) are not module items, so the walk
    // climbs to their parent def (the trait), which is one.
    let module_of_def = |p: &Program, mut def: crate::def::DefId| -> crate::ty::defs::ModuleId {
        for _ in 0..4 {
            if let Some(info) = tables.def_info.get(&def) {
                return info.module;
            }
            // The parent def, or (trait methods carry none) the
            // trait the index files the def under.
            let parent = p.defs.parent_of(def).or_else(|| p.gx.index.trait_of_method(def)).or_else(|| p.gx.index.trait_of_assoc(def));
            let Some(parent) = parent else { break };
            def = parent;
        }
        root
    };
    let mut cur = fid;
    // Instances name their template directly, so this walks at
    // most one hop in practice; the bound guards only against a
    // malformed table.
    for _ in 0..8 {
        // The def table first: the index table shifts when collect
        // dropped fns the resolver counted (after an earlier error).
        if let Some(m) = tables.fn_module.get(cur.0 as usize) {
            return crate::check::collect::def_module_of_fn(p, cur.0 as usize).unwrap_or(*m);
        }
        if let Some(info) = p.gx.instances.get(&cur) {
            if let Some(template) = info.template_local {
                cur = template;
                continue;
            }
            return module_of_def(p, info.template_def);
        }
        return p.fn_defs.get(cur.0 as usize).map_or(root, |&def| module_of_def(p, def));
    }
    root
}

/// The trait scope layers the `use` items among `idxs` (statement
/// items of one block, or one nested fn's sibling items) bring:
/// crate traits by def (flat names resolved through `trait_names`)
/// and std traits by canonical path, from the resolver's records
/// (`Ast::use_traits`). Empty when the resolver recorded none.
fn use_item_trait_layers(p: &Program, idxs: &[u32]) -> (Vec<DefId>, Vec<Vec<Sym>>) {
    let (mut defs, mut paths) = (Vec::new(), Vec::new());
    if p.ast.use_traits.is_empty() {
        return (defs, paths);
    }
    for &idx in idxs {
        let item = &p.ast.stmt_items[idx as usize];
        if !matches!(item.kind, ItemKind::Use(_)) {
            continue;
        }
        for (span, ut) in &p.ast.use_traits {
            if *span != item.span {
                continue;
            }
            match ut {
                ast::UseTrait::Flat(flat) => {
                    if let Some(&d) = p.gx.trait_names.get(flat) {
                        defs.push(d);
                    }
                }
                ast::UseTrait::Std(path) => {
                    if let Some(last) = path.last()
                        && let Some(d) = p.gx.lang.by_name(p.interner.get(*last))
                    {
                        defs.push(d);
                    }
                    paths.push(path.clone());
                }
            }
        }
    }
    (defs, paths)
}

/// Type-checks one function body. A closure body fn checks as its
/// parent fn (closures share their parent's inference); the parent's
/// own entry reports any errors, so the closure fn reports none and
/// marks the result poisoned instead.
pub fn check_fn<'p>(p: &'p Program, fid: LocalDefId) -> (Checked<'p>, Vec<Diag>) {
    check_fn_with(p, fid, true)
}

/// `check_fn`; the body lints that run after a clean check (deny lints,
/// depth, drop check, local type depth) only when `lints`. Mono discovery
/// in a one-shot `lust check` reads no error of its checks
/// (`generics::materialize`), so it skips them.
pub(crate) fn check_fn_with<'p>(p: &'p Program, fid: LocalDefId, lints: bool) -> (Checked<'p>, Vec<Diag>) {
    // Derive lists the check reads become `Derives` reads (R12).
    // So do const fns the scalar evaluator ran for a length (`Checked`).
    let ((((mut ck, mut errs), noted), called), accessed) = crate::driver::read_cover::scoped(|| {
        scalar_reads::scoped(p.record_reads, || derive_delta::scoped(p.record_reads, || check_fn_noted(p, fid)))
    });
    derive_delta::record(p, &mut ck.reads, &noted);
    scalar_reads::record(p, &mut ck.reads, &called);
    // Std source bodies see no user name (`STD_MODULE`): their user-map
    // lookups only rule a std name in or out, and record no read.
    let span = p.fn_def(fid).name_span;
    let std_body = p.std_source_span(span) || p.in_lang_methods(span) || defining_module(p, fid) == crate::ty::defs::STD_MODULE;
    // Each flat name the check looked up records its type binding read
    // (`read_cover::names`): the name maps record none of their own.
    if p.record_reads && !std_body {
        let module = defining_module(p, fid);
        for s in crate::driver::read_cover::names(&accessed) {
            p.binding(&mut ck.reads, module, Namespace::Type, s);
        }
    }
    // `LUST_CHECK_READS`: every table answer the check used has a read.
    if p.record_reads && errs.is_empty() && !accessed.is_empty() && !std_body {
        let missing = crate::driver::read_cover::uncovered(p, &ck.reads, &accessed);
        crate::driver::read_cover::report(p, p.interner.get(p.fn_def(fid).name), &missing);
    }
    if lints
        && errs.is_empty()
        && let Some(d) = lint_tail(p, fid, &mut ck)
    {
        errs.push(d);
    }
    // An instance request past rustc's type-length limit is its
    // post-mono error (a doubling arg, `f::<((T, T), (T, T))>`); mono
    // never snapshots one (generics::snapshot_ty).
    if errs.is_empty()
        && p.gx.walk_instances
        && let Some((t, _)) = ck.inst_requests.iter().find(|(_, a)| a.iter().any(|g| g.as_ty().is_some_and(|e| generics::over_type_length(&ck.tys, e))))
    {
        errs.push(Diag::new(
            "L0611",
            p.fn_def(*t).name_span,
            format!("reached the type-length limit while instantiating `{}`", p.interner.get(p.fn_def(*t).name)),
            "Reduce the recursive generic instantiation.",
        ));
    }
    (ck, errs)
}

/// The body lints that run after a clean check (`check_fn_with`): deny
/// lints, depth, drop check, local type depth. The first error, if any.
/// Drop-check overflow (rustc E0320) is judged on the generic body,
/// never an instance; a closure's body is its parent's check.
pub(crate) fn lint_tail(p: &Program, fid: LocalDefId, ck: &mut Checked) -> Option<Diag> {
    let class = p.gx.fn_class.get(fid.0 as usize).copied().unwrap_or_default();
    if !matches!(class, generics::FnClass::Plain | generics::FnClass::Template)
        || p.in_lang_methods(p.fn_def(fid).name_span)
        || p.fn_shipped_crate(fid).is_some()
    {
        return None;
    }
    deny_lints::check_body(p, fid, ck)
        .or_else(|| depth::check_uses(p, fid, ck, where_overflow::recursion_limit(p)))
        .or_else(|| dropck::check_body(p, fid, ck))
        .or_else(|| {
            // Build-only: `cargo check` asks no `Copy` or layout query of locals.
            let types: Vec<(Ty, Span)> = if p.gx.walk_instances {
                dropck::body_types(p, fid, ck).into_iter().map(|(t, s, _)| (t, s)).collect()
            } else {
                Vec::new()
            };
            depth::check_locals(p, &types, &ck.tys, where_overflow::recursion_limit(p))
        })
}

fn check_fn_noted<'p>(p: &'p Program, fid: LocalDefId) -> (Checked<'p>, Vec<Diag>) {
    if let Some(def) = p.gx.closure_fns.get(&fid)
        && let Some(entry) = p.gx.closures.get(def)
    {
        let (mut ck, errs) = check_fn(p, entry.parent);
        ck.poisoned = !errs.is_empty();
        return (ck, Vec::new());
    }
    opaque::check_fn_opaque(p, fid)
}

/// One check of one fn body under an `impl Trait` mode, with the picks
/// its opaque view recorded when `mode` is `Revealed` (check/opaque.rs).
fn check_fn_mode<'p>(p: &'p Program, fid: LocalDefId, mode: opaque::OpaqueMode, view: opaque::ViewOut) -> (Checked<'p>, Vec<Diag>) {
    let f = p.fn_info(fid);
    let def = f.def(&p.ast);
    let n_exprs = (def.exprs.1 - def.exprs.0) as usize;
    let n_pats = (def.pats.1 - def.pats.0) as usize;
    let mut cx = Ctx {
        p,
        f,
        recursion_limit: where_overflow::recursion_limit(p),
        auto_memo: Default::default(),
        depth_memo: crate::intern::FxMap::default(),
        module: defining_module(p, fid),
        tys: Tys::new(&p.tys),
        vars: Vec::new(),
        diverging: Vec::new(),
        out: Checked {
            tys: Tys::new(&p.tys),
            expr_base: def.exprs.0,
            pat_base: def.pats.0,
            expr_ty: vec![ERROR; n_exprs],
            const_exprs: vec![None; n_exprs],
            anon_exprs: Vec::new(),
            const_quals: Default::default(),
            expr_res: vec![Res::None; n_exprs],
            coerce: vec![Coerce::None; n_exprs],
            pat_ty: vec![ERROR; n_pats],
            pat_res: vec![PatRes::None; n_pats],
            pat_const: vec![None; n_pats],
            pat_derefs: vec![0; n_pats],
            generic_args: vec![Vec::new(); n_exprs],
            generic_site_args: Vec::new(),
            inst_requests: Vec::new(),
            trait_picks: Vec::new(),
            vtable_requests: Vec::new(),
            deref_recv: Vec::new(),
            drain_ranges: Vec::new(),
            index_ranges: Vec::new(),
            seq_cmps: Vec::new(),
            after_tail: Vec::new(),
            into_iter_calls: Vec::new(),
            deref_coerce: Vec::new(),
            index_recv: Vec::new(),
            locals: Vec::new(),
            param_locals: Vec::new(),
            reads: if p.record_reads { Reads::new() } else { Reads::off() },
            closures: Vec::new(),
            closure_calls: Vec::new(),
            fn_shim_calls: Vec::new(),
            poisoned: false,
            annotations: Vec::new(),
            cast_annotations: Vec::new(),
            queue_work: 0,
            opaque_hidden: Vec::new(),
            opaque_holds: Vec::new(),
            local_holds: Vec::new(),
            expr_moves: Vec::new(),
            local_moves: Vec::new(),
            closure_map_pending: false,
            closure_kind_pending: false,
        },
        scopes: Vec::new(),
        item_scopes: Vec::new(),
        item_scope_starts: Vec::new(),
        trait_scopes: Vec::new(),
        std_trait_scopes: Vec::new(),
        type_layers: Vec::new(),
        overlay_base: (Vec::new(), Vec::new(), Vec::new()),
        loops: Vec::new(),
        errs: Vec::new(),
        negated_lits: Vec::new(),
        obl: obligations::Obligations::new(),
        fid,
        solver: Solver::new(),
        trail: Vec::new(),
        body_scope: {
            let mut sc = p.gx.fn_scopes.get(fid.0 as usize).map_or_else(Scope::default, |fs| fs.scope.clone());
            sc.infer_cell = Some(std::sync::Arc::new(std::sync::atomic::AtomicU32::new(generics::INFER_MARKER_BASE)));
            if sc.self_ty.is_none() {
                sc.self_ty = f.owner.map(|a| p.tys.get_adt_ty(a).expect("ADT types are interned during collection"));
            }
            sc
        },
        generic_sites: Vec::new(),
        abstract_consts: Vec::new(),
        const_fn_self: None,
        const_fn_saved: Vec::new(),
        const_fn_items_saved: Vec::new(),
        next_const_fn_sibs: None,
        deferred_methods: Vec::new(),
        deferred_lang_methods: Vec::new(),
        std_first: Vec::new(),
        user_deref_call: None,
        private_inherent: Vec::new(),
        last_pick: None,
        deferred_try: Vec::new(),
        spawn_static: Vec::new(),
        static_dyn_inferred_ok: false,
        deferred_binops: Vec::new(),
        deferred_fmt: Vec::new(),
        deferred_layout: Vec::new(),
        turbofish_ty: None,
        deferred_clone: Vec::new(),
        deferred_string_from: Vec::new(),
        deferred_prim_from: Vec::new(),
        deferred_own_from: Vec::new(),
        deferred_type_names: Vec::new(),
        deferred_extend: Vec::new(),
        deferred_trait_fn_values: Vec::new(),
        deferred_trait_fn_calls: Vec::new(),
        deferred_eq: Vec::new(),
        deferred_collect: Vec::new(),
        deferred_sum: Vec::new(),
        deferred_copy: Vec::new(),
        deferred_repeat_n: Vec::new(),
        deferred_exact_range: Vec::new(),
        deferred_io_copy: Vec::new(),
        stmt_expr: None,
        deferred_ord: Vec::new(),
        deferred_sort_ord: Vec::new(),
        deferred_fn_casts: Vec::new(),
        deferred_coerce_casts: Vec::new(),
        deferred_open_casts: Vec::new(),
        deferred_into: Vec::new(),
        deferred_debug: Vec::new(),
        deferred_default: Vec::new(),
        deferred_vec_clone: Vec::new(),
        deferred_sized: Vec::new(),
        deferred_raw: Vec::new(),
        deferred_raw_casts: Vec::new(),
        deferred_downgrade: Vec::new(),
        deferred_make_mut: Vec::new(),
        deferred_hash_key: Vec::new(),
        deferred_glue_hash: Vec::new(),
        in_norm: false,
        const_bindings: std::collections::HashMap::new(),
        next_const_id: generics::INFER_MARKER_BASE,
        closures: Vec::new(),
        closure_rets: Vec::new(),
        fn_ret: f.ret,
        own_opaques: Vec::new(),
        opaque_mode: mode,
        view_picks: view.picks,
        view_calls: view.calls,
        opaque_env: Vec::new(),
        opaque_seen: Vec::new(),
        opaque_calls: Vec::new(),
        closure_map: Vec::new(),
        iter_arg_map: Vec::new(),
        opaque_closure_args: Vec::new(),
        closure_order: None,
        iter_closure_args: std::collections::HashMap::new(),
        scope_closure_vars: Vec::new(),
        closure_bound_outputs: std::collections::HashMap::new(),
        expect_only_vars: Vec::new(),
        returns_seen: 0,
        ret_exprs: Vec::new(),
        free_sig_closures: Vec::new(),
        hinted: Vec::new(),
        closure_bound_inputs: std::collections::HashMap::new(),
        closure_call_outs: std::collections::HashSet::new(),
        open_binops: Vec::new(),
        wait_binops: Vec::new(),
        wait_asserts: Vec::new(),
        wait_assign_ops: Vec::new(),
        vtable_sites: Vec::new(),
        unwind_checks: Vec::new(),
        dyn_borrow_src: false,
        call_expected: None,
        deref_depth: 0,
        deref_sites: Vec::new(),
        into_iter_requests: Vec::new(),
        place_step_exprs: Default::default(),
        or_frames: Vec::new(),
        or_log: None,
        pat_marks: Vec::new(),
        const_floor: 0,
    };
    if let Some(sibs) = p.fn_siblings.get(&fid) {
        let layer: Vec<((Sym, CtxtId), u32)> = sibs
            .iter()
            .filter_map(|&si| {
                let name = match &p.ast.stmt_items[si as usize].kind {
                    ItemKind::Fn(d) => Some((d.name, d.name_span.ctxt)),
                    ItemKind::Const(c) => c.name.map(|n| (n, c.name_span.ctxt)),
                    ItemKind::Static(st) => Some((st.name, st.name_span.ctxt)),
                    _ => None,
                };
                name.map(|n| (n, si))
            })
            .collect();
        cx.item_scopes.push(layer);
        cx.item_scope_starts.push(cx.scopes.len());
        let (defs, paths) = use_item_trait_layers(p, sibs);
        cx.trait_scopes.push(defs);
        cx.std_trait_scopes.push(paths);
        let type_layer: Vec<u32> = sibs.iter().copied().filter(|si| p.body_type_items.contains_key(si)).collect();
        cx.type_layers.push(type_layer);
    }
    // The fn scope's own local tables are the overlay base (a
    // nested fn sees the type items around its definition).
    cx.overlay_base = (cx.body_scope.local_types.clone(), cx.body_scope.local_aliases.clone(), cx.body_scope.local_traits.clone());
    cx.refresh_type_overlay();
    // A template body keeps its `Param` types: the store answers
    // the structural trait queries on them from the env (`Tys::env`).
    cx.tys.env = p.gx.fn_scopes.get(fid.0 as usize).map_or(&[], |fs| fs.env.as_slice());
    let mut pi = 0;
    if let Some(sp) = &def.self_param {
        let l = cx.add_local(p.known.self_value, f.params[0], sp.mutable, sp.span);
        cx.out.param_locals.push(l);
        pi = 1;
    }
    let mut seen_params: Vec<Sym> = Vec::new();
    for param in &def.params {
        if param.pat.is_none() {
            if seen_params.contains(&param.name) {
                let name = p.name(param.name).to_string();
                cx.err("L0106", param.span, format!("`{name}` is defined more than once"), "Rename one of the parameters.");
            }
            seen_params.push(param.name);
        }
        if param.pat.is_none() && cx.prelude_variant(param.name, param.span.ctxt) {
            cx.prelude_variant_binding_err(param.name, param.span);
        }
        // A plain parameter name that resolves to a const item or a
        // unit variant is a refutable pattern, not a binding (rustc
        // E0005); a static name cannot be a pattern at all. A `mut`
        // parameter, or one named like an item of the enclosing block
        // (which hides module items), may name no static or const.
        if param.pat.is_none() && cx.body_item_of(param.name).is_none() && cx.const_param(param.name).is_some() {
            cx.binding_shadows_item(param.name, param.span, !param.mutable);
        } else if param.pat.is_none() && (param.mutable || cx.body_item_of(param.name).is_some()) {
            cx.binding_shadows_item(param.name, param.span, false);
        } else if param.pat.is_none() {
            match cx.pat_binding(param.name) {
                PatIdent::Const(_) => {
                    cx.err(
                        "L0110",
                        param.span,
                        "refutable pattern in function argument",
                        "Rename the parameter: this name is a const item, so it would be a pattern, not a binding.",
                    );
                }
                PatIdent::Static => {
                    cx.err("L0110", param.span, "statics cannot be used as patterns", "Rename the parameter: this name is a static item.");
                }
                PatIdent::Variant(a, _) if p.adt(a).is_enum => {
                    cx.err(
                        "L0110",
                        param.span,
                        "refutable pattern in function argument",
                        "Rename the parameter: this name is an enum variant, so it would be a pattern, not a binding.",
                    );
                }
                PatIdent::Variant(a, _) if p.adt(a).variants[0].shape != VariantShape::Unit => {
                    cx.err(
                        "L0110",
                        param.span,
                        "function parameters cannot shadow tuple structs",
                        "Rename the parameter: this name is a tuple struct here.",
                    );
                }
                PatIdent::Variant(a, _) => {
                    // A unit struct name as a parameter is a unit
                    // pattern: legal only against its own type.
                    let at = cx.tys.adt_ty(a);
                    if !cx.unify(at, f.params[pi]) {
                        cx.mismatch(param.span, f.params[pi], at);
                    }
                }
                _ => {}
            }
        }
        // A pattern parameter binds out of a nameless argument
        // local, like a destructuring `let` out of a temporary:
        // `param_locals` keeps it so lowering has the place, and
        // the pattern's own locals are the names the body sees.
        let l = cx.add_local(param.name, f.params[pi], param.mutable, param.span);
        cx.out.param_locals.push(l);
        if let Some(pat) = param.pat {
            let scope_before = cx.scopes.len();
            cx.pattern(pat, f.params[pi], false);
            // A name bound by two parameters is one definition
            // too many, pattern parameters included.
            for &((bound, _), _) in &cx.scopes[scope_before..].to_vec() {
                if seen_params.contains(&bound) {
                    let name = p.name(bound).to_string();
                    cx.err("L0106", param.span, format!("`{name}` is defined more than once"), "Rename one of the parameters.");
                }
                seen_params.push(bound);
            }
            if !cx.pat_always_matches(pat) {
                cx.err(
                    "L0110",
                    param.span,
                    "refutable pattern in function argument",
                    "Use a pattern that matches every value, or match in the body.",
                );
            }
        }
        pi += 1;
    }
    // A template's parameters and return value are values of their
    // types, which must be `Sized` under its env (rustc E0277): a
    // `T: ?Sized` param, or `self` in a trait default body without
    // `Self: Sized`. Collect checks the concrete forms (`[T]`, `str`).
    if cx.is_template_check() {
        let mut slots: Vec<(Ty, Span)> = Vec::new();
        let mut i = 0;
        if let Some(sp) = &def.self_param {
            slots.push((f.params[0], sp.span));
            i = 1;
        }
        for param in &def.params {
            slots.push((f.params[i], param.span));
            i += 1;
        }
        slots.push((f.ret, def.ret.map_or(def.name_span, |t| p.ast.ty_span(t))));
        for (t, span) in slots {
            if !cx.sized_ok(t) {
                let tn = cx.tn(t);
                cx.err(
                    "L0110",
                    span,
                    format!("the size for values of type `{tn}` cannot be known"),
                    "Pass the value behind a reference such as `&T`, or drop the `?Sized` bound.",
                );
            }
        }
    }
    // A declaration without a body (trait or foreign fn shape) has nothing
    // to check; the parser does not build those today.
    cx.fn_ret = cx.defining_ret();
    let ret_span = def.ret.map_or(def.name_span, |t| p.ast.ty_span(t));
    if let Some(body) = def.body {
        let fn_ret = cx.fn_ret;
        if let Some(tail) = p.ast.block(body).tail {
            cx.note_ret_expr(tail);
        }
        let body_ty = cx.block(body, Some(fn_ret));
        let body_span = p.ast.block(body).span;
        if let Some(tail) = p.ast.block(body).tail {
            cx.coerce_expr(tail, body_ty, fn_ret);
        } else {
            cx.coerce_at(body_ty, fn_ret, body_span, None);
        }
    }
    // An anonymous const's value gets the evaluator's static
    // const-context checks, as a const item's does (`const_scan`).
    if matches!(cx.f.loc, FnLoc::AnonConst(_))
        && let Some(tail) = def.body.and_then(|b| p.ast.block(b).tail)
    {
        let want = cx.fn_ret;
        cx.const_scan(tail, Some(want));
    }
    cx.push_opaque_bounds(ret_span);
    cx.finish();
    cx.finish_opaques(ret_span);
    cx.reject_opaque_uses();
    let Ctx { out, tys, errs, obl, .. } = cx;
    let mut out = out;
    out.tys = tys;
    out.queue_work = obl.work();
    let mut errs = errs;
    drop_followon_infer(&mut errs);
    // A `const fn` body must also pass the const-context rules: the
    // const evaluator only sees the calls made from const items, so a
    // body that is never const-evaluated needs its own check. Std
    // source's const fns are core's, const as rustc checks them; lust's
    // walk is coarser (it sees a drop of `self` in `unwrap`'s `None`
    // arm), so they skip it.
    if f.is_const && !p.is_lang_method(fid) {
        let prior_errs = !errs.is_empty();
        errs.extend(constfn::check_const_fn(p, &out, f, prior_errs));
    }
    (out, errs)
}

/// Drops each inference failure (L0610 "type annotations needed", L0111
/// "cannot infer the type of", and any error about a type that is still
/// unknown, `_`, or an error type, `{error}`: a field, deref, cast or
/// iterator use of it) that follows another error of the body, as rustc
/// does (`tainted_by_errors`: no E0282/E0283/E0284 once the body has an
/// error, and no error at all about an error type). Such a failure is most
/// often a follow-on of that error (a missing method leaves its result and
/// closure params unknown).
/// "Follows" is in check order or in source order: lust checks a call's
/// arguments before it reports the call's own miss, where rustc checks
/// them after it. A body with inference failures only keeps them all, so
/// this never turns a reject into an accept.
fn drop_followon_infer(errs: &mut Vec<Diag>) {
    let is_infer = |d: &Diag| {
        d.code == "L0610"
            || (d.code == "L0111" && d.message.starts_with("cannot infer the type of"))
            || d.message.contains("`_`")
            || d.message.contains("{error}")
    };
    let Some(first) = errs.iter().position(|d| !is_infer(d)) else { return };
    // The first other error's position in each file.
    let mut min_lo: std::collections::HashMap<crate::diag::FileId, u32> = std::collections::HashMap::new();
    for d in errs.iter().filter(|d| !is_infer(d)) {
        let lo = min_lo.entry(d.span.file).or_insert(d.span.lo);
        *lo = (*lo).min(d.span.lo);
    }
    let mut i = 0;
    errs.retain(|d| {
        i += 1;
        !is_infer(d) || (i <= first && min_lo.get(&d.span.file).is_none_or(|&lo| d.span.lo < lo))
    });
}

/// True if Rust can compare two string-like operands for equality. `ld` and `rd` are the
/// reference depths of the two sides and `lk` and `rk` their base kinds (`String` or `Str`).
/// The model: peel the common reference layers (the blanket `&A == &B` impl), then require
/// one of the base impls: String==String, String==str, String==&str, str==String,
/// str==str, or &str==String.
/// A value the overflow lint knows at compile time. Integers hold the
/// value's bits in an i128: for every integer type except `u128` that
/// is also the mathematical value, and `u128` operations read the bits
/// back as a u128, so values at or above 2^127 stay exact.
#[derive(Clone, PartialEq)]
enum KVal {
    Int(i128),
    Bool(bool),
    /// A known enum discriminant: the adt and the variant index. The
    /// payload stays unknown.
    Enum(AdtId, u32),
    /// A known float: its bits (`f32` bits zero-extended) and type.
    Float(u64, crate::ty::FloatTy),
    Agg(Vec<Option<KVal>>),
}

type KEnv = Vec<Option<KVal>>;

/// A known float's value. An `f32` widens to f64 exactly.
fn k_float(bits: u64, f: crate::ty::FloatTy) -> f64 {
    match f {
        crate::ty::FloatTy::F32 => f32::from_bits(bits as u32) as f64,
        _ => f64::from_bits(bits),
    }
}

/// The bits of `x` rounded once to float type `f`.
fn k_float_bits(x: f64, f: crate::ty::FloatTy) -> u64 {
    match f {
        crate::ty::FloatTy::F32 => (x as f32).to_bits() as u64,
        _ => x.to_bits(),
    }
}

/// Whether a match pattern matches a known scrutinee value, when the
/// overflow lint can tell.
enum KCov {
    Yes,
    No,
    Unknown,
}

/// State of the overflow-lint walk: addressed locals, the stack of loop
/// and labeled-block frames collecting break values, and the locals
/// assigned more than once. A multiply-assigned local is only known
/// inside the MIR basic block that assigns it (rustc const-prop's
/// `OnlyInsideOwnBlock` mode): a terminator (a call, a checked
/// operation, a branch) clears its known value, while a local assigned
/// once keeps its value across blocks.
struct KLint {
    addressed: Vec<bool>,
    multi: Vec<bool>,
    frames: Vec<(Option<Sym>, Vec<Option<KVal>>)>,
    /// The current path is known to be unreachable (a known branch that
    /// is taken diverges): the rest of the block is not linted.
    dead: bool,
    /// `#[allow(arithmetic_overflow)]` on the function.
    allow_arith: bool,
    /// `#[allow(unconditional_panic)]` on the function.
    allow_panic: bool,
    /// Statement-level allows in force (`#[allow(..)] let ..;`).
    stmt_allow_arith: u32,
    stmt_allow_panic: u32,
}

/// True when an attribute is `#[allow(<name>)]`, `#[expect(<name>)]`, or
/// `#[warn(<name>)]` (possibly one of several): each lowers a deny-by-default
/// lint so it no longer fails the build, and an expectation the code does
/// not meet is only a warning in rustc.
pub fn allow_attr(attr: &ast::Attr, interner: &Interner, name: &str) -> bool {
    if attr.path.len() != 1 || !matches!(interner.get(attr.path[0].name), "allow" | "expect" | "warn") {
        return false;
    }
    let ast::AttrInput::List(_, trees) = &attr.input else { return false };
    fn has(trees: &[crate::lexer::TokenTree], interner: &Interner, name: &str) -> bool {
        trees.iter().any(|t| match t {
            crate::lexer::TokenTree::Token(tok) => matches!(tok.tok, crate::lexer::Tok::Ident(s) if interner.get(s) == name),
            crate::lexer::TokenTree::Delim(_, inner, _) => has(inner, interner, name),
        })
    }
    has(trees, interner, name)
}

/// The name and binding span of an optional AST label.
fn label_of(label: &Option<ast::Label>) -> Option<(Sym, Span)> {
    label.map(|l| (l.name, l.span))
}

/// Maps written tuple pattern elements to field indexes. At most one `..`
/// may appear; elements after it count from the end. None on an arity
/// mismatch or a second `..`. Lowering uses the same mapping.
pub fn map_tuple_elems(ast: &crate::ast::Ast, elems: &[PatId], nfields: usize) -> Option<Vec<(usize, PatId)>> {
    let rest = elems.iter().position(|&s| matches!(ast.pat(s), Pat::Rest));
    match rest {
        None => {
            if elems.len() != nfields {
                return None;
            }
            Some(elems.iter().enumerate().map(|(i, &s)| (i, s)).collect())
        }
        Some(r) => {
            if elems[r + 1..].iter().any(|&s| matches!(ast.pat(s), Pat::Rest)) {
                return None;
            }
            let suffix = elems.len() - r - 1;
            if r + suffix > nfields {
                return None;
            }
            let mut out: Vec<(usize, PatId)> = elems[..r].iter().enumerate().map(|(i, &s)| (i, s)).collect();
            for (j, &s) in elems[r + 1..].iter().enumerate() {
                out.push((nfields - suffix + j, s));
            }
            Some(out)
        }
    }
}

/// `PartialEq` between the std string types, as std's `impl_eq!` pairs
/// and the reference blanket impl give it: after peeling the common
/// reference depth, `String` against `String`, `str`, and `&str`; `str`
/// against `str`; and `Cow<str>` (W-STD-B) against `str`, `&str`,
/// `String`, and `Cow<str>`. Each pair holds both ways.
fn string_eq_ok(ld: u8, lk: StrKind, rd: u8, rk: StrKind) -> bool {
    use StrKind::*;
    let peel = ld.min(rd);
    let (a, b) = ((ld - peel, lk), (rd - peel, rk));
    let pair = |x: (u8, StrKind), y: (u8, StrKind)| (a == x && b == y) || (a == y && b == x);
    pair((0, String), (0, String))
        || pair((0, String), (0, Str))
        || pair((0, String), (1, Str))
        || pair((0, Str), (0, Str))
        || pair((0, Cow), (0, Str))
        || pair((0, Cow), (1, Str))
        || pair((0, Cow), (0, String))
        || pair((0, Cow), (0, Cow))
}

/// How `cmp_arg` handled a comparison call's argument.
enum CmpArg {
    /// Not at all: the plain argument check (a coercion to `&base`) is rustc's.
    Plain,
    /// Checked and coerced to `&base` (or reported).
    Checked,
    /// The call is the operator `Self == R` (`cmp_cross_eq`), recorded as `Res::Bin`.
    Cross,
}

/// The std string types `string_eq_ok` compares (`Cow` is `Cow<str>`).
#[derive(Clone, Copy, PartialEq, Eq)]
enum StrKind {
    String,
    Str,
    Cow,
}

/// Integer type width and signedness by its written name; `usize`/`isize`
/// count as pointer-sized (never lossless, since that depends on the target).
fn int_shape(name: &str) -> Option<(u32, bool)> {
    Some(match name {
        "u8" => (8, false),
        "u16" => (16, false),
        "u32" => (32, false),
        "u64" => (64, false),
        "u128" => (128, false),
        "i8" => (8, true),
        "i16" => (16, true),
        "i32" => (32, true),
        "i64" => (64, true),
        "i128" => (128, true),
        "usize" => (0, false),
        "isize" => (0, true),
        _ => return None,
    })
}

/// Whether `value as to` keeps every value of `from` (a widening cast).
fn lossless_cast(from: &str, to: &str) -> bool {
    match (int_shape(from), int_shape(to)) {
        (Some((fw, fs)), Some((tw, ts))) if fw > 0 && tw > 0 => (fs == ts && fw <= tw) || (!fs && ts && fw < tw),
        _ => false,
    }
}

impl<'p> Ctx<'p> {
    fn err(&mut self, code: &'static str, span: Span, msg: impl Into<String>, fix: impl Into<String>) {
        self.errs.push(Diag::new(code, span, msg, fix));
    }
    /// An error with a concrete cast edit: `(<expr at at>) as <to>` for an
    /// integer value of type `from`. The edit is `auto` only for a widening cast,
    /// which cannot change the value; a narrowing one is offered, not applied.
    fn err_cast(&mut self, code: &'static str, span: Span, msg: String, fix: String, at: Span, from: &str, to: &str) {
        let auto = lossless_cast(from, to);
        let d = Diag::new(code, span, msg, fix)
            .with_edit(crate::diag::Edit { start: at.lo, end: at.lo, replacement: "(".to_string(), auto })
            .with_edit(crate::diag::Edit { start: at.hi, end: at.hi, replacement: format!(") as {to}"), auto });
        self.errs.push(d);
    }
    /// True when this body already has an error and `t` still holds an
    /// unresolved inference variable: as rustc's "tainted by errors"
    /// inference, a field or method lookup (or a format trait check) on
    /// such a type is a follow-up of the first error (a call of a
    /// missing fn leaves its result open), so it reports nothing more.
    /// The program is rejected either way.
    fn tainted_lookup(&self, t: Ty) -> bool {
        !self.errs.is_empty() && self.has_unbound_deep(t)
    }
    fn span(&self, e: ExprId) -> Span {
        self.p.ast.expr_span(e)
    }
    fn name(&self, s: Sym) -> &str {
        self.p.name(s)
    }
    /// Type name for messages, with inference variables resolved.
    /// Std source `BTreeMap` and `BTreeSet` (W-STD-C) order their keys
    /// with `<` and `==` over a sorted `Vec`, where std calls `Ord::cmp`
    /// in its B-tree's own sequence. Both agree exactly when no key
    /// compare reaches a written `PartialEq`/`PartialOrd`/`Ord` impl (a
    /// written one may disagree with `Ord` or log its calls), so a body
    /// that forms such a map or set with such a key rejects (L0640).
    fn check_std_order_keys(&mut self) {
        let p = self.p;
        let Some(t) = p.resolved.as_ref() else { return };
        if !t.std_modules.iter().any(|&(n, _)| p.interner.get(n) == "__lust_alloc_collections") {
            return;
        }
        if p.std_source_span(p.fn_def(self.fid).name_span) {
            return;
        }
        for i in 0..self.out.expr_ty.len() {
            let ty = self.out.expr_ty[i];
            let Some((def, args)) = self.tys.adt_parts(ty) else { continue };
            let Some(a) = p.tys.local_adt_of(def).or_else(|| self.tys.local_adt(ty)) else { continue };
            if !p.is_std_adt(a) {
                continue;
            }
            let path = p.display_path(p.adt(a).name);
            if path != "alloc::collections::BTreeMap" && path != "alloc::collections::BTreeSet" {
                continue;
            }
            let Some(key) = self.tys.args(args).iter().find_map(|g| g.as_ty()) else { continue };
            if let Some(culprit) = self.written_order_in(key, &mut Vec::new()) {
                let span = self.span(ExprId(self.out.expr_base + i as u32));
                let (kn, cn) = (self.tn(key), self.tn(culprit));
                self.err(
                    "L0640",
                    span,
                    format!("a `BTreeMap` or `BTreeSet` key of type `{kn}` compares through the written `PartialEq`/`PartialOrd`/`Ord` impl of `{cn}`, which lust does not support yet"),
                    "Derive the comparison traits for the key type.",
                );
                return;
            }
        }
    }

    /// The first type inside `t` whose `PartialEq`, `PartialOrd`, or
    /// `Ord` impl is written (not derived, not core's), if any.
    fn written_order_in(&self, t: Ty, seen: &mut Vec<Ty>) -> Option<Ty> {
        let p = self.p;
        if seen.contains(&t) {
            return None;
        }
        seen.push(t);
        match self.tys.kind(t) {
            TyKind::Ref(_, _, e) | TyKind::Slice(e) | TyKind::Array(e, _) => return self.written_order_in(e, seen),
            TyKind::Tuple(ts) => {
                let elems = self.tys.tys_of(ts).to_vec();
                return elems.into_iter().find_map(|e| self.written_order_in(e, seen));
            }
            TyKind::Adt(def, args) => {
                let lang = &p.gx.lang;
                // Written std trait impls of a user Adt are `LangImpls` reads
                // (out of the trait-system key): the scan reads them by
                // record, so note the read here.
                crate::check::derive_delta::note_def(def, crate::check::derive_delta::bit::LANG);
                let written = crate::driver::read_cover::muted(|| p.gx.index.all_impls()).any(|(_, r)| {
                    r.synthetic == crate::traits::index::Synthetic::None
                        && r.head == crate::traits::index::SelfHead::Adt(def)
                        && (r.trait_def == lang.partial_eq || r.trait_def == lang.partial_ord || r.trait_def == lang.ord)
                        // Keys compare with keys: `impl PartialEq<Name> for
                        // String` (ts-rust core.rs) is not a key compare.
                        && p.tys.args(r.trait_ref.args).get(1).and_then(|g| g.as_ty()).is_none_or(|rhs| matches!(p.tys.kind(rhs), TyKind::Param(_)) || p.tys.adt_parts(rhs).is_some_and(|(d, _)| d == def))
                        && !p.std_source_span(r.span)
                        // Std's own impls (the platform crate's `String:
                        // PartialEq<OsStr>`, W-SHIM) agree with its order.
                        && !matches!(p.shipped_crate_at(r.span), Some(lang::ShippedCrate::Core | lang::ShippedCrate::Alloc | lang::ShippedCrate::Std))
                });
                if written {
                    return Some(t);
                }
                let targs: Vec<Ty> = self.tys.args(args).iter().filter_map(|g| g.as_ty()).collect();
                if let Some(c) = targs.iter().find_map(|&e| self.written_order_in(e, seen)) {
                    return Some(c);
                }
                if let Some(a) = self.tys.local_adt(t) {
                    let fields: Vec<Ty> = p.adt(a).variants.iter().flat_map(|v| v.fields.iter().map(|f| f.ty)).collect();
                    for f in fields {
                        if self.tys.flags(f).contains_param() {
                            continue;
                        }
                        if let Some(c) = self.written_order_in(f, seen) {
                            return Some(c);
                        }
                    }
                }
            }
            _ => {}
        }
        None
    }

    /// True when an `allow`, `warn`, or `expect` of one of `names` covers
    /// this body: on the fn, or on an enclosing impl, trait, module, or the
    /// crate (the parser copies those scopes' lint attributes onto the fn).
    fn lint_lifted(&self, names: &[&str]) -> bool {
        deny_lints::leveled(self.p, &self.f.def(&self.p.ast).attrs, names)
    }

    fn tn(&self, t: Ty) -> String {
        let t = self.resolve(t);
        match self.tys.kind(t) {
            TyKind::Ref(_, _, e) if matches!(self.tys.kind(e), TyKind::Dyn(..)) => ty_name(self.p, &self.tys, t),
            TyKind::Ref(_, m, e) => format!("&{}{}", if m.is_mut() { "mut " } else { "" }, self.tn(e)),
            _ => match self.tys.builtin_of(t) {
                Some(BuiltinTy::Vec) => format!("Vec<{}>", self.tn(self.tys.adt_first_ty_arg(t).unwrap_or(ERROR))),
                Some(BuiltinTy::Option) => format!("Option<{}>", self.tn(self.tys.adt_first_ty_arg(t).unwrap_or(ERROR))),
                Some(BuiltinTy::Result) => {
                    let (a, b) = self.tys.result_args(t).unwrap_or((ERROR, ERROR));
                    format!("Result<{}, {}>", self.tn(a), self.tn(b))
                }
                _ => ty_name(self.p, &self.tys, t),
            },
        }
    }
    fn ei(&self, e: ExprId) -> usize {
        (e.0 - self.out.expr_base) as usize
    }
    /// True when an array repeat operand may repeat a non-`Copy`
    /// value: rustc re-evaluates a const item or inline const per
    /// element, so no copy is ever made. A const item read (a free
    /// or associated const) is the path form whose checked value is
    /// a baked constant with no other resolution; a static read, a
    /// constructor, and a const fn call all make one value and
    /// still need `Copy`.
    fn repeat_const_operand(&self, e: ExprId) -> bool {
        match self.p.ast.expr(e) {
            Expr::ConstBlock(_) => true,
            Expr::Path(_) | Expr::QPath { .. } => {
                let i = self.ei(e);
                self.out.const_exprs[i].is_some() && matches!(self.out.expr_res[i], Res::None)
            }
            _ => false,
        }
    }
    fn set(&mut self, e: ExprId, t: Ty) -> Ty {
        let i = self.ei(e);
        self.out.expr_ty[i] = t;
        t
    }
    fn set_res(&mut self, e: ExprId, r: Res) {
        // A method of an impl for a `'static` dyn type (`impl dyn Tr`)
        // needs a `'static` receiver: the borrow checker proves it.
        let i = self.ei(e);
        self.out.expr_res[i] = r;
    }
    fn add_local(&mut self, name: Sym, ty: Ty, mutable: bool, span: Span) -> u32 {
        let l = self.out.locals.len() as u32;
        self.out.locals.push(LocalInfo { name, ty, mutable, span });
        // `span` must be the binding name's own span: its context is the
        // hygiene key. Callers pass the pattern or parameter name span.
        self.scopes.push(((name, span.ctxt), l));
        l
    }
    fn lookup(&self, name: Sym, ctxt: CtxtId) -> Option<u32> {
        // The newest visible binding of this name: same context, or one a
        // body-local macro could already see at its definition (ARCH 6.3).
        let at = self
            .scopes
            .iter()
            .rposition(|((n, _), l)| *n == name && crate::diag::ctxt_can_see_local(ctxt, self.out.locals[*l as usize].span))?;
        // A block's items are in scope from the block's start, as in
        // rustc: an item of this name in a block the local was declared
        // outside of shadows the local (`fn f(x: u32) { static x: .. }`).
        if let Some(i) = self.item_scopes.iter().rposition(|layer| layer.iter().any(|&(k, _)| k == (name, ctxt)))
            && at < self.item_scope_starts[i]
        {
            return None;
        }
        Some(self.scopes[at].1)
    }

    /// Runs `f` in a const context: the locals declared so far are out
    /// of its scope (`const_floor`).
    fn in_const<R>(&mut self, f: impl FnOnce(&mut Self) -> R) -> R {
        let outer = std::mem::replace(&mut self.const_floor, self.out.locals.len() as u32);
        let r = f(self);
        self.const_floor = outer;
        r
    }

    /// rustc E0435: a const context names a local of the fn around it.
    fn non_const_local(&mut self, span: Span) -> Ty {
        self.err(
            "L0634",
            span,
            "attempt to use a non-constant value in a constant",
            "Use a `const` item, or compute the value outside the const context.",
        );
        ERROR
    }

    /// Types an anonymous const of a written type or path in this body
    /// (an array length, a const argument) as code in a const context,
    /// once, with type `want` when known. Lowering borrow-checks it as a
    /// body of its own (`Checked::anon_exprs`). Literals and plain names
    /// need neither.
    fn type_anon_const(&mut self, e: ExprId, want: Option<Ty>) {
        if self.p.ast.is_plain_const(e) || self.out.anon_exprs.contains(&e) {
            return;
        }
        self.out.anon_exprs.push(e);
        self.in_const(|cx| match want {
            Some(t) => cx.expect_expr(e, t),
            None => cx.expr(e, None),
        });
        self.const_scan(e, want);
    }

    /// Runs the bounded evaluator over const expression `e` for its
    /// static const-context errors only: a call to a non-const fn or a
    /// destructor run, dead branches included (rustc E0015, E0493). The
    /// value and any other evaluator limit stay with the scalar paths.
    fn const_scan(&mut self, e: ExprId, want: Option<Ty>) {
        let errs = self.errs.len();
        let mut ccx = CheckCx { cx: self };
        if let Err(d) = crate::ty::consteval::eval(&mut ccx, e, want)
            && (crate::ty::consteval::is_nonconst_call_diag(&d) || crate::ty::consteval::is_drop_diag(&d))
            && self.errs.len() == errs
        {
            self.errs.push(d);
        }
    }

    // Cross-item reads go through the section 8.2 query functions on
    // `Program`, which record into this body's read set. Bodies ask in
    // their own module (the root in single-file programs).
    /// Rebuilds `body_scope`'s local type tables from the overlay
    /// base plus the type items of the enclosing blocks (R18).
    fn refresh_type_overlay(&mut self) {
        if self.type_layers.is_empty() && self.overlay_base.0.is_empty() && self.overlay_base.1.is_empty() && self.overlay_base.2.is_empty() {
            return;
        }
        let mut acc = self.overlay_base.clone();
        for layer in &self.type_layers {
            crate::check::collect::overlay_extend(&mut acc, crate::check::collect::overlay_of_items(self.p, layer.clone()));
        }
        let (types, aliases, traits) = acc;
        self.body_scope.local_types = types;
        self.body_scope.local_aliases = aliases;
        self.body_scope.local_traits = traits;
    }

    /// The body item a name denotes in the enclosing blocks, innermost
    /// first. Items are not hygienic in `macro_rules!` expansions (only
    /// locals are), so the name alone matches: a macro body's `V` sees a
    /// `const V` of the block it expands in, as in rustc.
    /// The unit or tuple struct whose constructor a value name denotes
    /// through the type items of the enclosing blocks (R18): block by
    /// block from the innermost, as rustc's ribs, where a block value
    /// item (fn, const, static) of the name stops the search (the two
    /// in one block are E0428). Then the blocks around a nested fn
    /// (`overlay_base`). None for a module-level name.
    fn local_ctor_of(&self, name: Sym) -> Option<AdtId> {
        let p = self.p;
        let ctor = |a: AdtId| !p.adt(a).is_enum && p.adt(a).variants.first().is_some_and(|v| v.shape != VariantShape::Named);
        let of_item = |idx: u32| -> Option<AdtId> {
            let crate::check::collect::BodyTypeItem::Adt(a) = *p.body_type_items.get(&idx)? else { return None };
            match &p.ast.stmt_items[idx as usize].kind {
                ItemKind::Struct(s) if s.name == name && ctor(a) => Some(a),
                _ => None,
            }
        };
        for d in (0..self.type_layers.len()).rev() {
            if self.item_scopes.get(d).is_some_and(|l| l.iter().any(|((n, _), _)| *n == name)) {
                return None;
            }
            if let Some(a) = self.type_layers[d].iter().rev().find_map(|&i| of_item(i)) {
                return Some(a);
            }
        }
        if self.item_scopes.iter().any(|l| l.iter().any(|((n, _), _)| *n == name)) {
            return None;
        }
        self.overlay_base.0.iter().rev().find(|(n, a, _)| *n == name && ctor(*a)).map(|e| e.1)
    }

    fn body_item_of(&self, name: Sym) -> Option<crate::check::collect::BodyItem> {
        for layer in self.item_scopes.iter().rev() {
            for &((n, _), idx) in layer.iter().rev() {
                if n == name {
                    return self.p.body_items.get(&idx).copied();
                }
            }
        }
        None
    }

    /// True when this body checks in generic mode (trait selection for
    /// operators and `for`, written-type well-formedness, the generic
    /// method search): the program has user generics, or the body is a
    /// lang enum method or a closure in one. A program whose only
    /// generics are those methods checks its own bodies as a program
    /// with no generics does (`GenTables::user_generics`).
    fn generic_mode(&self) -> bool {
        let p = self.p;
        p.gx.has_generics && (p.gx.user_generics || p.in_lang_methods(p.fn_def(self.fid).name_span))
    }

    fn binding(&mut self, ns: Namespace, name: Sym) -> BindingRes {
        let p = self.p;
        let module = self.module;
        p.binding(&mut self.out.reads, module, ns, name)
    }

    /// A primitive associated const used as a pattern (`u8::MAX`,
    /// `char::MAX`): its value and type, if the path names one.
    fn primitive_const_pattern(&mut self, segs: &[ast::PathSeg]) -> Option<(crate::ty::consteval::ConstValue, Ty)> {
        use crate::ty::consteval::ConstValue;
        if segs.len() != 2 {
            return None;
        }
        let item = self.name(segs[1].name);
        if let Some(it) = self.p.known.int_ty(segs[0].name) {
            let t = int(it);
            let v = match item {
                "MAX" => crate::ty::consteval::truncate_to_int(it.max128() as i128, it),
                "MIN" => {
                    if it.signed() {
                        if it.bits() >= 128 { i128::MIN } else { -(1i128 << (it.bits() - 1)) }
                    } else {
                        0
                    }
                }
                "BITS" => return Some((ConstValue::Int(it.bits() as i128), int(IntTy::U32))),
                _ => return None,
            };
            // u128::MAX is stored as its raw bits, as in the evaluator.
            let v = if it == IntTy::U128 && item == "MAX" { -1 } else { v };
            return Some((ConstValue::Int(v), t));
        }
        if segs[0].name == self.p.known.char {
            let c = match item {
                "MAX" => char::MAX,
                "MIN" => char::MIN,
                "REPLACEMENT_CHARACTER" => char::REPLACEMENT_CHARACTER,
                _ => return None,
            };
            return Some((ConstValue::Char(c), CHAR));
        }
        None
    }

    /// A primitive float associated const used as a pattern
    /// (`f64::INFINITY`, `std::f64::consts::PI`): its value and
    /// type, from the const evaluator's table.
    fn primitive_float_const_pattern(&mut self, segs: &[ast::PathSeg]) -> Option<(crate::ty::consteval::ConstValue, Ty)> {
        use crate::ty::consteval::ConstValue;
        let names: Vec<&str> = segs.iter().map(|s| self.name(s.name)).collect();
        let (ty_name, item, module) = match names.as_slice() {
            [t, i] => (*t, *i, false),
            [p, t, c, i] if matches!(*p, "std" | "core" | "alloc") && *c == "consts" => (*t, *i, true),
            _ => return None,
        };
        let f = match ty_name {
            "f32" => FloatTy::F32,
            "f64" => FloatTy::F64,
            _ => return None,
        };
        if module {
            let bits = crate::ty::consteval::float_consts_value(f, item)?;
            return Some((ConstValue::Float(bits, f), self.tys.float_ty(f)));
        }
        match crate::ty::consteval::primitive_float_assoc(f, item)? {
            (bits, None) => Some((ConstValue::Float(bits, f), self.tys.float_ty(f))),
            (v, Some(it)) => Some((ConstValue::Int(v as i128), int(it))),
        }
    }

    /// A primitive associated const of an already resolved base
    /// type (the `<u8>::MAX` / `<f64>::INFINITY` pattern forms).
    fn primitive_const_for_base(&mut self, base: Ty, name: Sym) -> Option<(crate::ty::consteval::ConstValue, Ty)> {
        use crate::ty::consteval::ConstValue;
        let item = self.name(name);
        match self.kind(base) {
            TyKind::Int(it) => {
                let v = match item {
                    "MAX" => crate::ty::consteval::truncate_to_int(it.max128() as i128, it),
                    "MIN" => {
                        if it.signed() {
                            if it.bits() >= 128 { i128::MIN } else { -(1i128 << (it.bits() - 1)) }
                        } else {
                            0
                        }
                    }
                    "BITS" => return Some((ConstValue::Int(it.bits() as i128), int(IntTy::U32))),
                    _ => return None,
                };
                let v = if it == IntTy::U128 && item == "MAX" { -1 } else { v };
                Some((ConstValue::Int(v), int(it)))
            }
            TyKind::Float(f) => match crate::ty::consteval::primitive_float_assoc(f, item)? {
                (bits, None) => Some((ConstValue::Float(bits, f), self.tys.float_ty(f))),
                (v, Some(it)) => Some((ConstValue::Int(v as i128), int(it))),
            },
            TyKind::Char => {
                let c = match item {
                    "MAX" => char::MAX,
                    "MIN" => char::MIN,
                    "REPLACEMENT_CHARACTER" => char::REPLACEMENT_CHARACTER,
                    _ => return None,
                };
                Some((ConstValue::Char(c), CHAR))
            }
            _ => None,
        }
    }

    /// True when `name` is a std prelude variant (`None`, `Some`, `Ok`,
    /// `Err`) that no local, block item, or crate item shadows here. Such
    /// a name in a binding position is not a fresh binding (rustc
    /// E0530): plain `None` is a path pattern, and every other form
    /// (`Some`, `mut None`, `ref Ok`, a parameter) is an error.
    fn prelude_variant(&mut self, name: Sym, ctxt: CtxtId) -> bool {
        let k = &*self.p.known;
        [k.None, k.Some, k.Ok, k.Err].contains(&name)
            && self.lookup(name, ctxt).is_none()
            && self.body_item_of(name).is_none()
            && self.binding(Namespace::Value, name) == BindingRes::Absent
    }

    /// The L0110 error for a binding that names a prelude variant.
    fn prelude_variant_binding_err(&mut self, name: Sym, span: Span) {
        let n = self.name(name).to_string();
        self.err(
            "L0110",
            span,
            format!("a binding cannot shadow the std variant `{n}`"),
            format!("Rename the binding: `{n}` names `Option::{n}` or `Result::{n}` here, not a new variable."),
        );
    }

    /// Whether a plain pattern name, with no local shadowing it, is a
    /// path pattern (a const, static, unit struct, or unit variant), not
    /// a fresh binding. A block's items come first: a body const or
    /// static is one; a body fn is not, and it hides module items.
    fn names_pattern_item(&mut self, name: Sym) -> bool {
        if self.local_ctor_of(name).is_some() {
            return true;
        }
        match self.body_item_of(name) {
            Some(crate::check::collect::BodyItem::Fn(_)) => false,
            Some(_) => true,
            None => !matches!(self.pat_binding(name), PatIdent::Other),
        }
    }

    /// rustc E0530: no binding may shadow a static or a const generic
    /// param, and only a plain binding (no `mut`, `ref`, or `@`) may
    /// name a const, as its path pattern (checked before this); a
    /// plain name of a const param is E0158. A block's items come before module
    /// items, and a local of the name in between shadows both. Reports
    /// and returns true when `name` is such a static or const.
    fn binding_shadows_item(&mut self, name: Sym, span: Span, plain: bool) -> bool {
        use crate::check::collect::BodyItem;
        if self.lookup(name, span.ctxt).is_some() {
            return false;
        }
        // A `mut` or `ref` binding over a unit or tuple struct or an
        // imported variant (a block struct first, R18).
        if !plain && (self.local_ctor_of(name).is_some() || matches!(self.pat_binding(name), PatIdent::Variant(..))) {
            let n = self.name(name).to_string();
            self.err("L0110", span, "bindings cannot shadow unit structs, tuple structs, or variants", format!("Rename the binding: `{n}` names an item here."));
            return true;
        }
        let what = match self.body_item_of(name) {
            Some(BodyItem::Static(_)) => "statics",
            Some(BodyItem::Const(_)) if !plain => "constants",
            Some(_) => return false,
            // A const generic param shadows module items. As a plain
            // name it would be a pattern, which rustc forbids (E0158).
            None if self.const_param(name).is_some() => {
                let msg =
                    if plain { "constant parameters cannot be referenced in patterns" } else { "bindings cannot shadow const parameters" };
                let n = self.name(name).to_string();
                self.err("L0110", span, msg, format!("Rename the binding, or compare with `{n}` in a guard."));
                return true;
            }
            None => match self.pat_binding(name) {
                PatIdent::Static => "statics",
                PatIdent::Const(_) if !plain => "constants",
                _ => return false,
            },
        };
        let n = self.name(name).to_string();
        self.err("L0110", span, format!("bindings cannot shadow {what}"), format!("Rename the binding: `{n}` names an item here."));
        true
    }

    /// What a lone identifier in a pattern resolves to through the
    /// module bindings (imports included): a const item, a static, or
    /// a unit variant or struct constructor. Anything else stays a
    /// fresh binding, the name of a struct with named fields (`struct Z
    /// {}` too, which has no value) included. The binding query records the read, so a body
    /// rechecks when the name's target changes.
    /// `pat_ident` for the name of a binding pattern or parameter. The
    /// binding query answers a rewritten flat name in every module (a
    /// root item's flat name is its plain name), but a binding's name was
    /// never rewritten: the resolver already made each one that names an
    /// item in scope a path pattern. So outside the root module a name
    /// the module's own table does not bind is a fresh binding, even when
    /// the root has a const or unit struct of that name (rustc). The
    /// table's answer is part of the body: the resolver's rewrite of the
    /// pattern changes when it does.
    fn pat_binding(&mut self, name: Sym) -> PatIdent {
        if self.local_ctor_of(name).is_none()
            && self.module != crate::ty::defs::ROOT_MODULE
            && let Some(tables) = &self.p.resolved
            && tables.lookup(self.module, Namespace::Value, name).is_none()
        {
            return PatIdent::Other;
        }
        self.pat_ident(name)
    }

    fn pat_ident(&mut self, name: Sym) -> PatIdent {
        use crate::resolve::imports::{BindState, Target};
        let p = self.p;
        // A unit or tuple struct of an enclosing block (R18).
        if let Some(a) = self.local_ctor_of(name) {
            return PatIdent::Variant(a, 0);
        }
        if let BindingRes::Def(def) = self.binding(Namespace::Value, name) {
            let flat = p.resolved.as_ref().and_then(|t| t.def_info.get(&def)).map(|i| i.flat);
            match p.binding_kind(def) {
                Some(DefsKind::Const) => {
                    if let Some(i) = p.const_by_def(def).or_else(|| flat.and_then(|f| p.const_names.get(&f).copied())) {
                        return PatIdent::Const(i);
                    }
                }
                Some(DefsKind::Static) => {
                    if p.static_by_def(def).or_else(|| flat.and_then(|f| p.static_names.get(&f).copied())).is_some() {
                        return PatIdent::Static;
                    }
                }
                _ => {}
            }
            // The flat lookup is covered by the binding read (`LUST_CHECK_READS`):
            // for a def that is no Adt, a hit is an enum or a named-field
            // struct of the same name, which give `Other` as a miss does.
            let flat_adt = |f| crate::driver::read_cover::muted(|| p.type_names.get(&f).copied());
            if let Some(a) = p.adt_by_def(def).or_else(|| flat.and_then(flat_adt)) {
                if p.adt(a).is_enum {
                    // A variant import answers with the enum's def in
                    // the binding query; the raw table keeps the variant.
                    if let Some(tables) = &p.resolved
                        && let Some(BindState::One(b)) = tables.lookup(self.module, Namespace::Value, name)
                        && let Target::Variant(vdef, vname) = b.target
                        && vdef == def
                        && let Some(v) = p.adt(a).variants.iter().position(|x| x.name == vname)
                    {
                        return PatIdent::Variant(a, v as u32);
                    }
                    return PatIdent::Other;
                }
                if p.adt(a).variants[0].shape == VariantShape::Named {
                    return PatIdent::Other;
                }
                return PatIdent::Variant(a, 0);
            }
        }
        // Without resolver tables the flat name maps answer directly
        // (user names: std source sees none of them).
        if self.module == crate::ty::defs::STD_MODULE {
            return PatIdent::Other;
        }
        if let Some(&i) = p.const_names.get(&name) {
            return PatIdent::Const(i);
        }
        if p.static_names.contains_key(&name) {
            return PatIdent::Static;
        }
        // Covered by the value binding read above (`LUST_CHECK_READS`): it
        // answered no def, so no unit or tuple struct of the name is in
        // scope (the single-file layer reads this map for it), and a hit is
        // an enum or a named-field struct.
        if let Some(&a) = crate::driver::read_cover::muted(|| p.type_names.get(&name))
            && !p.adt(a).is_enum
            && p.adt(a).variants[0].shape != VariantShape::Named
        {
            return PatIdent::Variant(a, 0);
        }
        PatIdent::Other
    }

    /// Field visibility (ARCH 1.5): a private field of a struct from
    /// another module is L0510. Only resolver-built programs carry the
    /// field table; single-file programs are all one module. Every
    /// member privacy check here records a `Sig(adt)` read: that
    /// fingerprint covers the Adt's field and associated item
    /// visibility (driver/graph.rs `hash_vis_facts`), so the dirty walk
    /// rechecks this body when a visibility it asked about changes.
    fn check_field_vis(&mut self, a: AdtId, field: Sym, span: Span) {
        let p = self.p;
        // std's own bodies (`Result::map` calling a user constructor
        // passed as a value) reach user items only through generics,
        // which the naming site already checked.
        if self.module == crate::ty::defs::STD_MODULE {
            return;
        }
        // The fields of std's structs are private to std.
        if generics::is_std_adt(&p.tys, a) {
            let name = self.name(field).to_string();
            self.err("L0510", span, format!("field `{name}` is private"), "Use the type's methods instead.");
            return;
        }
        // The field's type and visibility (`Sig(adt)`), with module tables
        // or not: struct literals and patterns reach fields through here.
        let def = p.def_of_adt(a);
        let _ = p.sig_of(&mut self.out.reads, def);
        let Some(tables) = &p.resolved else { return };
        if let Some((def_mod, fields)) = tables.field_vis.get(&def)
            && let Some(vis) = fields.get(&field)
            && !tables.visible(vis, *def_mod, self.module, &p.interner)
        {
            let name = self.name(field).to_string();
            self.err(
                "L0510",
                span,
                format!("field `{name}` is private"),
                "Make the field `pub(crate)` (the smallest widening that works).",
            );
        }
    }

    /// Tuple-field visibility, like `check_field_vis` for `t.1` forms.
    fn check_tuple_field_vis(&mut self, a: AdtId, index: u32, span: Span) {
        let p = self.p;
        // std's own bodies (`Result::map` calling a user constructor
        // passed as a value) reach user items only through generics,
        // which the naming site already checked.
        if self.module == crate::ty::defs::STD_MODULE {
            return;
        }
        // std's tuple structs (`TryFromIntError`, the char errors) keep
        // their fields private to std, like `check_field_vis`.
        if generics::is_std_adt(&p.tys, a) && !p.adt(a).is_enum {
            self.err("L0510", span, format!("field `{index}` is private"), "Use the type's methods instead.");
            return;
        }
        let def = p.def_of_adt(a);
        let _ = p.sig_of(&mut self.out.reads, def);
        let Some(tables) = &p.resolved else { return };
        if let Some((def_mod, fields)) = tables.tuple_field_vis.get(&def)
            && let Some(vis) = fields.get(index as usize)
            && !tables.visible(vis, *def_mod, self.module, &p.interner)
        {
            self.err(
                "L0510",
                span,
                format!("field `{index}` is private"),
                "Make the field `pub(crate)` (the smallest widening that works).",
            );
        }
    }

    /// A tuple struct constructor is private when any of its fields is
    /// (rustc E0603), for calls and patterns alike.
    fn check_ctor_vis(&mut self, a: AdtId, span: Span) {
        let p = self.p;
        // std's own bodies (`Result::map` calling a user constructor
        // passed as a value) reach user items only through generics,
        // which the naming site already checked.
        if self.module == crate::ty::defs::STD_MODULE {
            return;
        }
        if generics::is_std_adt(&p.tys, a) && !p.adt(a).is_enum {
            let name = p.display_path(p.adt(a).name);
            self.err("L0510", span, format!("tuple struct constructor `{name}` is private"), "Use the type's methods instead.");
            return;
        }
        let def = p.def_of_adt(a);
        let _ = p.sig_of(&mut self.out.reads, def);
        let Some(tables) = &p.resolved else { return };
        if let Some((def_mod, fields)) = tables.tuple_field_vis.get(&def)
            && fields.iter().any(|vis| !tables.visible(vis, *def_mod, self.module, &p.interner))
        {
            let name = p.display_path(p.adt(a).name);
            self.err(
                "L0510",
                span,
                format!("tuple struct constructor `{name}` is private"),
                "Make every field `pub(crate)`, or add a public constructor function.",
            );
        }
    }

    /// Records the `Sig(adt)` read a `#[non_exhaustive]` answer for
    /// variant `v` of `a` depends on, like the field privacy checks:
    /// toggling the attribute rechecks this body. No record when
    /// neither the type nor the variant is marked.
    fn ne_read(&mut self, a: AdtId, v: u32) {
        let p = self.p;
        let adt = p.adt(a);
        let marked = adt.non_exhaustive || adt.variants.get(v as usize).is_some_and(|x| x.non_exhaustive);
        if marked && p.resolved.is_some() {
            let _ = p.sig_of(&mut self.out.reads, p.def_of_adt(a));
        }
    }

    /// A struct literal of a `#[non_exhaustive]` struct, or of a
    /// variant so marked, is an error outside the defining crate
    /// (rustc E0639), with or without a `..base` update.
    fn check_ne_lit(&mut self, a: AdtId, v: u32, span: Span) {
        self.ne_read(a, v);
        if let Some(what) = crate::check::collect::ne_lit_what(self.p, a, v, self.module) {
            self.err(
                "L0510",
                span,
                format!("cannot create non-exhaustive {what} using struct expression"),
                "Use a constructor function the defining crate exports.",
            );
        }
    }

    /// The tuple or unit constructor of a `#[non_exhaustive]` struct,
    /// and the tuple constructor of a variant so marked, is private
    /// outside the defining crate (rustc E0603), for calls, values,
    /// and patterns alike.
    fn check_ne_ctor(&mut self, a: AdtId, v: u32, span: Span) {
        self.ne_read(a, v);
        if let Some(what) = crate::check::collect::ne_ctor_what(self.p, a, v, self.module) {
            let name = self.p.display_path(self.p.adt(a).name);
            self.err("L0510", span, format!("{what} `{name}` is private"), "Use a constructor function the defining crate exports.");
        }
    }

    /// A named-field pattern on a `#[non_exhaustive]` struct or
    /// variant needs `..` outside the defining crate (rustc E0638),
    /// even when it names every field.
    fn check_ne_pat(&mut self, a: AdtId, v: u32, rest: bool, span: Span) {
        self.ne_read(a, v);
        if let Some(what) = crate::check::collect::ne_pat_what(self.p, a, v, rest, self.module) {
            self.err("L0510", span, format!("`..` required with {what} marked as non-exhaustive"), "End the pattern with `..`.");
        }
    }

    /// Inherent method visibility for a method call on a user type.
    fn check_method_vis(&mut self, base: Ty, name: Sym, span: Span) {
        if let Some(a) = self.tys.local_adt(base) {
            self.check_assoc_vis(a, name, "method", span);
        }
    }

    /// True when the inherent item `name` of Adt `a` is not visible here.
    fn assoc_private(&mut self, a: AdtId, name: Sym) -> bool {
        let p = self.p;
        let Some(tables) = &p.resolved else { return false };
        let def = p.def_of_adt(a);
        p.record_assoc_vis(&mut self.out.reads, def, name);
        tables.assoc_vis.get(&def).and_then(|items| items.get(&name)).is_some_and(|(vis, def_mod)| !tables.visible(vis, *def_mod, self.module, &p.interner))
    }

    /// Inherent associated item visibility: a method call, or a
    /// `Self::item` or `Type::item` path that check resolves. The
    /// resolver checks written type paths as well; `Self` paths reach
    /// only this check. `what` names the item kind in the message.
    fn check_assoc_vis(&mut self, a: AdtId, name: Sym, what: &str, span: Span) {
        let p = self.p;
        let Some(tables) = &p.resolved else { return };
        let def = p.def_of_adt(a);
        p.record_assoc_vis(&mut self.out.reads, def, name);
        if let Some(items) = tables.assoc_vis.get(&def)
            && let Some((vis, def_mod)) = items.get(&name)
            && !tables.visible(vis, *def_mod, self.module, &p.interner)
        {
            self.err(
                "L0510",
                span,
                format!("{what} `{}` is private", self.name(name)),
                format!("Make the {what} `pub(crate)` (the smallest widening that works)."),
            );
        }
    }

    /// Visibility of an `impl dyn Tr` method a call picked (rustc E0624):
    /// its written visibility, from the module of its impl. The method's
    /// `Sig` read covers both, so a warm caller rechecks when either moves.
    fn check_dyn_method_vis(&mut self, f: LocalDefId, span: Span) {
        let p = self.p;
        let Some(tables) = &p.resolved else { return };
        let _ = p.sig_of(&mut self.out.reads, p.def_id(f));
        let info = p.fn_info(f);
        let vis = crate::resolve::imports::vis_from_ast(&info.def(&p.ast).vis, &p.interner);
        if !tables.visible(&vis, defining_module(p, f), self.module, &p.interner) {
            self.err(
                "L0510",
                span,
                format!("method `{}` is private", self.name(info.name)),
                "Make the method `pub(crate)` (the smallest widening that works).",
            );
        }
    }

    /// The tuple struct a value binding names as a constructor, if it names one.
    fn tuple_struct_ctor(&mut self, name: Sym) -> Option<AdtId> {
        // `Self(..)` in an impl of a tuple struct (its args are the
        // impl's, see `self_path_args`).
        if name == self.p.known.self_type {
            return self.self_adt().filter(|&a| !self.p.adt(a).is_enum && self.p.adt(a).variants[0].shape == VariantShape::Tuple);
        }
        if let Some(a) = self.local_ctor_of(name) {
            return (self.p.adt(a).variants[0].shape == VariantShape::Tuple).then_some(a);
        }
        match self.binding(Namespace::Value, name) {
            BindingRes::Def(def) => match self.p.adt_by_def(def) {
                Some(a) if !self.p.adt(a).is_enum && self.p.adt(a).variants[0].shape == VariantShape::Tuple => Some(a),
                _ => None,
            },
            _ => None,
        }
    }

    /// The `fn(params) -> ret` pointer type for a signature.
    fn fn_ptr_ty(&mut self, params: &[Ty], ret: Ty) -> Ty {
        let inputs = self.tys.intern_tys(params);
        let sig =
            self.tys.intern_sig(crate::ty::Binder::plain(crate::ty::FnSig::plain(inputs, ret)));
        self.tys.intern(TyKind::FnPtr(sig))
    }

    /// A fn with a `T: 'a` bound on a named lifetime as a value: only its
    /// calls prove the bound (borrowck `call_sig_with`), so a fn pointer or
    /// `Fn` value of it is not supported yet (L0203).
    fn reject_type_outlives_value(&mut self, f: LocalDefId, span: Span) {
        let has = self
            .p
            .gx
            .fn_templates
            .get(f.0 as usize)
            .and_then(|t| t.as_ref())
            .is_some_and(|t| t.generics.predicates.iter().any(|q| matches!(q, Predicate::TypeOutlives(_, Region::Param(_)))));
        if has {
            self.err("L0203", span, "a fn with a `T: 'a` bound used as a value is not supported yet", "Call it, or wrap the call in a closure.");
        }
    }

    /// The zero-sized fn-item type of a fn used as a value. A generic
    /// fn named by a plain path instantiates as a call does (turbofish
    /// args or fresh variables, bounds queued, the site recorded for
    /// mono), and its `FnDef` carries those args. Qualified paths
    /// (`<S as Tr>::mk`) to generic fns are not supported yet.
    fn fn_value_ty(&mut self, e: ExprId, f: LocalDefId, span: Span) -> Ty {
        self.reject_track_caller_value(f, span);
        self.reject_type_outlives_value(f, span);
        if let Some(Some(tmpl)) = self.p.gx.fn_templates.get(f.0 as usize).cloned() {
            if !matches!(self.p.ast.expr(e), Expr::Path(_)) {
                self.errs.push(not_yet("L0614", span, "generic functions as values through a qualified path"));
                return ERROR;
            }
            let explicit = self.explicit_path_args(e, f);
            self.check_path_turbofish(e, f, &tmpl.generics, span);
            let (_, _, args) = self.instantiate_template(e, f, &tmpl.generics, &explicit, span);
            self.unify_written_self(e, f, &args, span);
            let args = self.tys.intern_args(&args);
            return self.tys.intern(TyKind::FnDef(self.p.def_id(f), args));
        }
        self.unify_written_self(e, f, &[], span);
        self.tys.intern(TyKind::FnDef(self.p.def_id(f), EMPTY_ARGS))
    }

    /// An inherent fn as a value through a qualified path (`<W<u16>>::get`):
    /// a generic impl's fn instantiates as on a plain path, with the
    /// written Self type fixing the impl's params.
    fn inherent_qpath_fn_value(&mut self, e: ExprId, f: LocalDefId, base: Ty, span: Span) -> Ty {
        let p = self.p;
        if p.gx.fn_templates.get(f.0 as usize).is_none_or(|t| t.is_none()) {
            return self.fn_value_ty(e, f, span);
        }
        let Some(self_tmpl) = p.gx.fn_scopes.get(f.0 as usize).and_then(|s| s.scope.self_ty) else {
            self.errs.push(not_yet("L0614", span, "generic functions as values through a qualified path"));
            return ERROR;
        };
        let t = self.fn_value_ty_prefixed(e, f, &[], span);
        if let TyKind::FnDef(_, args) = self.kind(t) {
            let args: Vec<GenericArg> = self.tys.args(args).to_vec();
            let self_ty = subst(&mut self.tys, self_tmpl, &args);
            if !self.unify(self_ty, base) {
                self.mismatch(span, base, self_ty);
            }
        }
        t
    }

    /// `fn_value_ty` for a fn whose leading generic args are already
    /// known (a trait fn through a qualified path: the selected impl's
    /// args); the fn's own params come from the path's turbofish
    /// (`<S as Tr>::conv::<u32>`), else fresh variables.
    fn fn_value_ty_prefixed(&mut self, e: ExprId, f: LocalDefId, prefix: &[GenericArg], span: Span) -> Ty {
        self.reject_track_caller_value(f, span);
        self.reject_type_outlives_value(f, span);
        let Some(Some(tmpl)) = self.p.gx.fn_templates.get(f.0 as usize).cloned() else {
            return self.tys.intern(TyKind::FnDef(self.p.def_id(f), EMPTY_ARGS));
        };
        let mut explicit: Vec<Option<GenericArg>> = prefix.iter().map(|&g| Some(g)).collect();
        if let Expr::QPath { segs, .. } = self.p.ast.expr(e)
            && let Some(last) = segs.last()
        {
            for t in last.type_args() {
                explicit.push(Some(GenericArg::Ty(self.resolve_written(t))));
            }
        }
        let supplied = self.path_supplied(e);
        self.check_turbofish_min(&tmpl.generics.clone(), prefix.len(), supplied, span);
        let (_, _, args) = self.instantiate_template(e, f, &tmpl.generics, &explicit, span);
        let args = self.tys.intern_args(&args);
        self.tys.intern(TyKind::FnDef(self.p.def_id(f), args))
    }

    /// The type of a unit struct used as a value. A generic one (const
    /// params only: rustc rejects an unused type param) takes its args
    /// from the path's turbofish (`S::<7>`) or fresh variables, with its
    /// bounds queued, as the tuple constructor below does.
    fn unit_value_ty(&mut self, e: ExprId, a: AdtId, span: Span) -> Ty {
        self.check_ne_ctor(a, 0, span);
        let p = self.p;
        let generics = p.gx.adt_generics[a.0 as usize].clone();
        if generics.params.is_empty() {
            return self.tys.adt_ty(a);
        }
        let args = match p.ast.expr(e) {
            Expr::Path(segs) => self.value_path_args(a, segs, span),
            _ => self.fresh_args(&generics),
        };
        if !generics.predicates.is_empty() {
            self.push_predicates(&generics.predicates, &args, span);
        }
        self.tys.mk_adt(p.def_of_adt(a), &args)
    }

    /// The callable-item type of a tuple struct or tuple variant
    /// constructor used as a value. It is an `FnDef` over the Adt def
    /// with the variant index as its first (const) argument, so a later
    /// call through the value can decode which constructor it is. A
    /// generic Adt's args follow (`.map(W)`): from the path's turbofish
    /// or fresh variables, with the Adt's bounds queued, as a call of
    /// the constructor does.
    fn ctor_value_ty(&mut self, e: ExprId, a: AdtId, v: u32, span: Span) -> Ty {
        let p = self.p;
        // Naming a tuple struct constructor needs every field visible,
        // called or not (`.map(m::P)` is rustc E0603).
        if !p.adt(a).is_enum {
            self.check_ctor_vis(a, span);
        }
        self.check_ne_ctor(a, v, span);
        let c = self.tys.intern_const(ConstKind::Int(v as u128));
        let mut args = vec![GenericArg::Const(c)];
        let generics = p.gx.adt_generics[a.0 as usize].clone();
        if !generics.params.is_empty() {
            let gen_args = match p.ast.expr(e) {
                Expr::Path(segs) => self.value_path_args(a, segs, span),
                _ => self.fresh_args(&generics),
            };
            if !generics.predicates.is_empty() {
                self.push_predicates(&generics.predicates, &gen_args, span);
            }
            args.extend(gen_args);
        }
        let args = self.tys.intern_args(&args);
        self.tys.intern(TyKind::FnDef(p.def_of_adt(a), args))
    }

    /// The item type of a builtin constructor or std fn used as a value
    /// (`.map(Some)`, `Result::Err`, `.map(Rc::new)`,
    /// `.map(String::from)`): an `FnDef` over the builtin Adt def.
    /// `Some`, `Ok`, and `Err` put the variant first as a const arg
    /// (Some 1, Ok 0, Err 1), then the Adt's args; `Box::new`,
    /// `Rc::new`, and `String::from` have their one input type. Args
    /// come from the turbofish or fresh variables. `builtin_item_res`
    /// decodes the item.
    fn builtin_item_value(&mut self, e: ExprId, r: Res, segs: &[ast::PathSeg], span: Span) -> Ty {
        let b = self.tys.builtins();
        let (def, variant) = match r {
            Res::OptSome => (b.option, Some(1)),
            Res::ResOk => (b.result, Some(0)),
            Res::ResErr => (b.result, Some(1)),
            Res::Builtin(Builtin::BoxNew) => (b.boxed, None),
            Res::Builtin(Builtin::RcNew) => (b.rc, None),
            // `String::as_str` shares the String def with
            // `String::from`; its item const is 1 (tf-str).
            Res::Builtin(Builtin::StringAsStr) => (b.string, Some(1)),
            _ => (b.string, None),
        };
        let tys = if def == b.string && variant == Some(1) {
            if segs.iter().any(|s| !s.type_args().is_empty()) {
                self.err("L0107", span, "`String::as_str` takes no generic arguments", "Remove the generic arguments.");
            }
            Vec::new()
        } else if def == b.string {
            // `From::from` has no params of its own: the input is open
            // until a use fixes it, then it must be a form lust's
            // `String::from` takes (checked at finish).
            if segs.iter().any(|s| !s.type_args().is_empty()) {
                self.err("L0107", span, "`String::from` takes no generic arguments", "Remove the generic arguments.");
            }
            let t = self.new_var(false);
            self.deferred_string_from.push((t, span));
            vec![t]
        } else if variant.is_none() && segs.last().is_some_and(|s| !s.type_args().is_empty()) {
            // `Box::new` and `Rc::new` have no params of their own; the
            // element type goes on the type (`Box::<u8>::new`).
            self.err("L0107", span, "this associated function takes no generic arguments", "Write the type's argument instead: `Box::<T>::new`.");
            vec![self.new_var(false)]
        } else {
            let n = if def == b.result { 2 } else { 1 };
            match self.builtin_ctor_args(segs, n, span) {
                Some(a) => a,
                None => (0..n).map(|_| self.new_var(false)).collect(),
            }
        };
        self.set_res(e, r);
        let mut args: Vec<GenericArg> = variant.map(|v| GenericArg::Const(self.tys.intern_const(ConstKind::Int(v)))).into_iter().collect();
        args.extend(tys.into_iter().map(GenericArg::Ty));
        let args = self.tys.intern_args(&args);
        self.tys.intern(TyKind::FnDef(def, args))
    }

    /// The call a builtin item over a builtin Adt def makes (see
    /// `builtin_item_value`), with the item's (params, return).
    fn builtin_item_res(&mut self, def: DefId, args: ArgsId) -> Option<(Res, Vec<Ty>, Ty)> {
        let b = self.tys.builtins();
        let a: Vec<Ty> = self.tys.args(args).iter().filter_map(|g| g.as_ty()).collect();
        Some(match a.as_slice() {
            &[t] if def == b.option => (Res::OptSome, vec![t], self.tys.mk_option(t)),
            &[t, e] if def == b.result && self.ctor_variant(args) == 0 => (Res::ResOk, vec![t], self.tys.mk_result(t, e)),
            &[t, e] if def == b.result => (Res::ResErr, vec![e], self.tys.mk_result(t, e)),
            &[t] if def == b.boxed => (Res::Builtin(Builtin::BoxNew), vec![t], self.tys.mk_boxed(t)),
            &[t] if def == b.rc => (Res::Builtin(Builtin::RcNew), vec![t], self.tys.mk_rc(t)),
            &[] if def == b.string && self.ctor_variant(args) == 1 => {
                (Res::Builtin(Builtin::StringAsStr), vec![self.tys.mk_ref(false, STRING)], REF_STR)
            }
            &[t] if def == b.string => (Res::Builtin(Builtin::StringFrom), vec![t], STRING),
            _ => return None,
        })
    }

    /// The full signature (receiver first) of a primitive type's
    /// builtin method named by a path (`u8::is_ascii_digit`,
    /// `str::len`, `String::as_str`; TRIAGE T12), from the same
    /// tables the method-call probe uses. The returned extra
    /// types are the signature's own inference variables (the `T`
    /// of `bool::then_some`): an item value carries them in its
    /// `FnDef` args, and a decode passes them back in `extra` so
    /// the same variables are reused.
    fn prim_assoc_sig(&mut self, self_ty: Ty, name: Sym, extra: &[Ty]) -> Option<(Builtin, Vec<Ty>, Ty, Vec<Ty>)> {
        use Builtin as B;
        let k = &*self.p.known;
        // `u64::from(x)` and `map(u64::from)`: std's `From` for a
        // primitive target, as the conversion builtin. The input
        // type is the one extra; its legality is checked where the
        // call is checked (and deferred for an item value, like
        // `String::from`).
        // Sync builtin methods by path (`PoisonError::into_inner`,
        // `Weak::upgrade`; TRIAGE T5): the receiver forms of
        // check/sync.rs's method table.
        if let Some(k) = crate::ty::sync::sync_kind(&self.tys, self_ty) {
            use crate::check::sync::SyncOp;
            use crate::ty::sync::SyncTy;
            if let Some((op, autoref, rest, ret)) = self.sync_path_method_sig(k, self_ty, name) {
                let recv = match autoref {
                    Autoref::None => self_ty,
                    Autoref::Ref => self.tys.mk_ref(false, self_ty),
                    Autoref::RefMut => self.tys.mk_ref(true, self_ty),
                    Autoref::SliceRef | Autoref::SliceRefMut => return None,
                };
                let extras = if extra.is_empty() {
                    let mut out = Vec::new();
                    self.collect_infer_tys(self_ty, &mut out);
                    out
                } else {
                    extra.to_vec()
                };
                let mut params = vec![recv];
                params.extend(rest);
                return Some((Builtin::Sync(op), params, ret, extras));
            }
            return None;
        }
        if let Some(sig) = self.cell_path_method_sig(self_ty, name, extra) {
            return Some(sig);
        }
        // `RefCell::borrow` and `borrow_mut` by path and as values
        // (`.map(RefCell::borrow)`): `&RefCell<T>` to its guard, the
        // receiver form of check/cells.rs's method table.
        if let Some(el) = self.tys.refcell_elem(self_ty) {
            let (b, guard) = match self.name(name) {
                "borrow" => (B::RefCellBorrow, self.tys.mk_builtin1(|d| d.ref_guard, el)),
                "borrow_mut" => (B::RefCellBorrowMut, self.tys.mk_builtin1(|d| d.ref_mut_guard, el)),
                _ => return None,
            };
            let recv = self.tys.mk_ref(false, self_ty);
            let extras = if extra.is_empty() {
                let mut out = Vec::new();
                self.collect_infer_tys(self_ty, &mut out);
                out
            } else {
                extra.to_vec()
            };
            return Some((b, vec![recv], guard, extras));
        }
        // `NonZero::get` as a value (`map_or(1, NonZero::get)`,
        // TRIAGE T5): the wrapped integer, by value.
        if let Some(inner) = generics::nonzero_elem(&self.tys, self_ty) {
            if self.name(name) == "get" {
                return Some((B::NonZeroGet, vec![self_ty], inner, Vec::new()));
            }
            return None;
        }
        if name == k.from && matches!(self.kind(self_ty), TyKind::Int(_) | TyKind::Float(_) | TyKind::Char | TyKind::Bool) {
            let src = match extra.first() {
                Some(&t) => t,
                None => self.new_var(false),
            };
            return Some((B::PrimFromCast, vec![src], self_ty, vec![src]));
        }
        // `u32::from_le_bytes([u8; 4])` and the `be`/`ne` forms (TRIAGE R26).
        if let TyKind::Int(i) = self.kind(self_ty) {
            let from_bytes = match self.name(name) {
                "from_le_bytes" => Some(B::IntFromLeBytes),
                "from_be_bytes" => Some(B::IntFromBeBytes),
                "from_ne_bytes" => Some(B::IntFromNeBytes),
                _ => None,
            };
            if let Some(b) = from_bytes {
                let arr = self.int_bytes_ty(i);
                return Some((b, vec![arr], self_ty, Vec::new()));
            }
            if self.name(name) == "from_str_radix" {
                let err = generics::parse_int_error_ty(&mut self.tys);
                let ret = self.tys.mk_result(self_ty, err);
                return Some((B::FromStrRadix(i), vec![REF_STR, int(IntTy::U32)], ret, Vec::new()));
            }
        }
        let (b, autoref, params, ret) = match self.kind(self_ty) {
            TyKind::Int(i) => self.int_method(name, self_ty, i)?,
            TyKind::Float(f) => self.float_method(name, self_ty, f)?,
            TyKind::Char => self.char_method(name)?,
            TyKind::Bool if name == k.then_some => {
                let t = match extra.first() {
                    Some(&t) => t,
                    None => self.new_var(false),
                };
                let o = self.tys.mk_option(t);
                (B::BoolThenSome, Autoref::None, vec![t], o)
            }
            TyKind::Str => {
                if name == k.len {
                    (B::StrLen, Autoref::Ref, vec![], USIZE)
                } else if name == k.is_empty {
                    (B::StrIsEmpty, Autoref::Ref, vec![], BOOL)
                } else if name == k.to_string || name == k.to_owned {
                    (B::StrToString, Autoref::Ref, vec![], STRING)
                } else if self.name(name) == "as_ptr" {
                    (B::StrAsPtr, Autoref::Ref, vec![], self.tys.intern(TyKind::RawPtr(Mut::Shared, int(IntTy::U8))))
                } else {
                    self.str_method(name)?
                }
            }
            // `<[T]>::len` and `<[T]>::is_empty` by path and as values
            // (ts-rust `owned_store_js_doc(file, host, <[Node]>::len)`).
            TyKind::Slice(_) if name == k.len => (B::SliceLen, Autoref::Ref, vec![], USIZE),
            TyKind::Slice(_) if name == k.is_empty => (B::SliceIsEmpty, Autoref::Ref, vec![], BOOL),
            // `Vec::as_slice` and kin as values (`opt.map(Vec::as_slice)`).
            _ if let Some(e) = self.tys.vec_elem(self_ty) => match self.name(name) {
                "as_slice" => {
                    let sl = self.tys.intern(TyKind::Slice(e));
                    (B::VecAsSlice, Autoref::Ref, vec![], self.tys.mk_ref(false, sl))
                }
                "as_mut_slice" => {
                    let sl = self.tys.intern(TyKind::Slice(e));
                    (B::VecAsMutSlice, Autoref::RefMut, vec![], self.tys.mk_ref(true, sl))
                }
                "len" => (B::VecLen, Autoref::Ref, vec![], USIZE),
                "is_empty" => (B::VecIsEmpty, Autoref::Ref, vec![], BOOL),
                _ => return None,
            },
            _ if self_ty == STRING => {
                if name == k.as_str {
                    (B::StringAsStr, Autoref::Ref, vec![], REF_STR)
                } else if self.name(name) == "as_mut_str" {
                    let r = self.tys.mk_ref(true, STR);
                    (B::StringAsMutStr, Autoref::RefMut, vec![], r)
                } else if name == k.len {
                    (B::StringLen, Autoref::Ref, vec![], USIZE)
                } else if name == k.is_empty {
                    (B::StringIsEmpty, Autoref::Ref, vec![], BOOL)
                } else if name == k.capacity {
                    (B::StringCapacity, Autoref::Ref, vec![], USIZE)
                } else if name == k.as_bytes {
                    let sl = self.tys.intern(TyKind::Slice(int(IntTy::U8)));
                    let r = self.tys.mk_ref(false, sl);
                    (B::StringAsBytes, Autoref::Ref, vec![], r)
                } else if name == k.into_bytes {
                    let v = self.tys.mk_vec(int(IntTy::U8));
                    (B::StringIntoBytes, Autoref::None, vec![], v)
                } else if name == k.to_string {
                    (B::ToString, Autoref::Ref, vec![], STRING)
                } else {
                    return None;
                }
            }
            _ => return None,
        };
        let recv = match autoref {
            Autoref::None => self_ty,
            Autoref::Ref => self.tys.mk_ref(false, self_ty),
            Autoref::RefMut => self.tys.mk_ref(true, self_ty),
            Autoref::SliceRef | Autoref::SliceRefMut => return None,
        };
        let mut full = vec![recv];
        full.extend(params);
        let extras = if extra.is_empty() {
            let mut out = Vec::new();
            for &t in full.iter().chain([&ret]) {
                self.collect_infer_tys(t, &mut out);
            }
            out
        } else {
            extra.to_vec()
        };
        Some((b, full, ret, extras))
    }

    /// Collect the distinct inference-variable types inside `t`.
    fn collect_infer_tys(&self, t: Ty, out: &mut Vec<Ty>) {
        match self.kind(t) {
            TyKind::Infer(_) => {
                if !out.contains(&t) {
                    out.push(t);
                }
            }
            TyKind::Ref(_, _, inner) | TyKind::RawPtr(_, inner) | TyKind::Slice(inner) | TyKind::Array(inner, _) => {
                self.collect_infer_tys(inner, out)
            }
            TyKind::Tuple(ts) => {
                for u in self.tys.tys_of(ts).to_vec() {
                    self.collect_infer_tys(u, out);
                }
            }
            TyKind::Adt(_, args) | TyKind::FnDef(_, args) | TyKind::Closure(_, args) | TyKind::Projection(_, args) | TyKind::Opaque(_, args) => {
                for g in self.tys.args(args).to_vec() {
                    if let Some(u) = g.as_ty() {
                        self.collect_infer_tys(u, out);
                    }
                }
            }
            _ => {}
        }
    }

    /// The item type of a primitive builtin method used as a value
    /// (`take_while(u8::is_ascii_digit)`, TRIAGE T12): an `FnDef`
    /// over `ty::prim_fn_def` carrying the Self type, the method
    /// name and builtin code as consts, and the signature's extra
    /// types. `prim_item_res` decodes it.
    pub(super) fn prim_item_value(&mut self, b: Builtin, self_ty: Ty, name: Sym, span: Span) -> Ty {
        let sig = match self.std_free_item_sig(b, self_ty) {
            Some(_) => Some((b, Vec::new(), UNIT, Vec::new())),
            None => self.prim_assoc_sig(self_ty, name, &[]),
        };
        let Some((_, _, _, extras)) = sig else {
            self.errs.push(unsupported(span, "this std function used as a value"));
            return ERROR;
        };
        if b == Builtin::PrimFromCast
            && let Some(&src) = extras.first()
        {
            self.deferred_prim_from.push((self_ty, src, span));
        }
        let Some(code) = prim_builtin_code(b) else {
            self.errs.push(unsupported(span, "this std function used as a value"));
            return ERROR;
        };
        let mut args = vec![
            GenericArg::Ty(self_ty),
            GenericArg::Const(self.tys.intern_const(ConstKind::Int(name.0 as u128))),
            GenericArg::Const(self.tys.intern_const(ConstKind::Int(code as u128))),
        ];
        args.extend(extras.into_iter().map(GenericArg::Ty));
        let args = self.tys.intern_args(&args);
        self.tys.intern(TyKind::FnDef(crate::ty::prim_fn_def(), args))
    }

    /// The call a primitive method item makes (see
    /// `prim_item_value`), with the item's (params, return).
    fn prim_item_res(&mut self, def: DefId, args: ArgsId) -> Option<(Res, Vec<Ty>, Ty)> {
        if def != crate::ty::prim_fn_def() {
            return None;
        }
        let gs = self.tys.args(args).to_vec();
        let self_ty = gs.first().and_then(|g| g.as_ty())?;
        let const_at = |i: usize| match gs.get(i) {
            Some(GenericArg::Const(c)) => match self.tys.const_kind(*c) {
                ConstKind::Int(v) => Some(v as u32),
                _ => None,
            },
            _ => None,
        };
        let name = Sym(const_at(1)?);
        let code = const_at(2)?;
        let b = prim_builtin_of_code(code)?;
        if let Some((params, ret)) = self.std_free_item_sig(b, self_ty) {
            return Some((Res::PrimAssoc { b, self_ty, name }, params, ret));
        }
        let extras: Vec<Ty> = gs.iter().skip(3).filter_map(|g| g.as_ty()).collect();
        let (b2, params, ret, _) = self.prim_assoc_sig(self_ty, name, &extras)?;
        if b2 != b {
            return None;
        }
        Some((Res::PrimAssoc { b, self_ty, name }, params, ret))
    }

    /// The integer inside a `NonZero` alias name (`NonZeroU32`
    /// gives `u32`), if the name is one.
    fn nonzero_alias_inner(&self, ty_name: Sym) -> Option<IntTy> {
        match self.name(ty_name) {
            "NonZeroU8" => Some(IntTy::U8),
            "NonZeroU16" => Some(IntTy::U16),
            "NonZeroU32" => Some(IntTy::U32),
            "NonZeroU64" => Some(IntTy::U64),
            "NonZeroU128" => Some(IntTy::U128),
            "NonZeroUsize" => Some(IntTy::Usize),
            "NonZeroI8" => Some(IntTy::I8),
            "NonZeroI16" => Some(IntTy::I16),
            "NonZeroI32" => Some(IntTy::I32),
            "NonZeroI64" => Some(IntTy::I64),
            "NonZeroI128" => Some(IntTy::I128),
            "NonZeroIsize" => Some(IntTy::Isize),
            _ => None,
        }
    }

    /// The primitive type a two-segment path's first segment names
    /// (`u8`, `str`, `String`; TRIAGE T12), if it names one.
    fn prim_ty_by_name(&mut self, ty_name: Sym) -> Option<Ty> {
        let it = match self.name(ty_name) {
            "i8" => Some(int(IntTy::I8)),
            "i16" => Some(int(IntTy::I16)),
            "i32" => Some(int(IntTy::I32)),
            "i64" => Some(int(IntTy::I64)),
            "i128" => Some(int(IntTy::I128)),
            "isize" => Some(int(IntTy::Isize)),
            "u8" => Some(int(IntTy::U8)),
            "u16" => Some(int(IntTy::U16)),
            "u32" => Some(int(IntTy::U32)),
            "u64" => Some(int(IntTy::U64)),
            "u128" => Some(int(IntTy::U128)),
            "usize" => Some(int(IntTy::Usize)),
            "f32" => Some(self.tys.float_ty(FloatTy::F32)),
            "f64" => Some(self.tys.float_ty(FloatTy::F64)),
            "char" => Some(CHAR),
            "bool" => Some(BOOL),
            "str" => Some(STR),
            "String" => Some(STRING),
            _ => None,
        };
        it
    }

    /// The variant a constructor `FnDef` type names, from its const arg.
    fn ctor_variant(&self, args: ArgsId) -> u32 {
        match self.tys.args(args).first() {
            Some(GenericArg::Const(c)) => match self.tys.const_kind(*c) {
                ConstKind::Int(v) => v as u32,
                _ => 0,
            },
            _ => 0,
        }
    }

    /// The (params, return) signature of a callable type: a fn pointer,
    /// a fn item, or a constructor item.
    fn callable_sig(&mut self, t: Ty) -> Option<(Vec<Ty>, Ty)> {
        let p = self.p;
        match self.kind(t) {
            TyKind::FnPtr(sig) => {
                let s = self.tys.sig(sig).value;
                Some((self.tys.tys_of(s.inputs).to_vec(), s.output))
            }
            TyKind::FnDef(def, args) => {
                if let Some((_, params, ret)) = self.builtin_item_res(def, args).or_else(|| self.prim_item_res(def, args)) {
                    return Some((params, ret));
                }
                // A trait method as a value (`Into::into`,
                // check/traitpath.rs): the trait method's own
                // signature under the item's arguments.
                if self.is_trait_method_def(def) {
                    let fargs: Vec<GenericArg> = self.tys.args(args).to_vec();
                    return self.trait_method_sig(def, &fargs);
                }
                if let Some(a) = p.adt_by_def(def) {
                    let v = self.ctor_variant(args);
                    let variant = &p.adt(a).variants[v as usize];
                    // A generic Adt's args follow the variant (see
                    // `ctor_value_ty`).
                    let adt_args: Vec<GenericArg> = self.tys.args(args).iter().skip(1).copied().collect();
                    if adt_args.is_empty() {
                        let params = variant.fields.iter().map(|f| f.ty).collect();
                        return Some((params, self.tys.adt_ty(a)));
                    }
                    let fields: Vec<Ty> = variant.fields.iter().map(|f| f.ty).collect();
                    let params = fields.into_iter().map(|t| self.subst_settled(t, &adt_args)).collect();
                    Some((params, self.tys.mk_adt(def, &adt_args)))
                } else {
                    let f = p.local_def(def.hash)?;
                    let fargs: Vec<GenericArg> = self.tys.args(args).to_vec();
                    match p.sig_of(&mut self.out.reads, def) {
                        SigOf::Fn(info) if fargs.is_empty() => Some((info.params.clone(), p.ret_view(f))).map(|(ps, r)| (ps, self.callee_ret(r))),
                        // A generic fn item: its signature under the
                        // item's args (see `fn_value_ty`).
                        SigOf::Fn(info) => {
                            let params = info.params.iter().map(|&t| self.subst_settled(t, &fargs)).collect();
                            Some((params, self.subst_settled(info.ret, &fargs)))
                        }
                        _ => None,
                    }
                }
            }
            _ => None,
        }
    }

    /// rustc's LUB of two fn or constructor items: the same item (args
    /// that unify) keeps its zero-sized type, and only differing items
    /// reify to a fn pointer. Unifies the args when it answers true.
    fn same_fn_item(&mut self, a: Ty, b: Ty) -> bool {
        let (a, b) = (self.resolve(a), self.resolve(b));
        let (TyKind::FnDef(da, _), TyKind::FnDef(db, _)) = (self.kind(a), self.kind(b)) else { return false };
        if da != db {
            return false;
        }
        let snap = self.snapshot_vars();
        if self.unify(a, b) {
            return true;
        }
        self.rollback_vars(snap);
        false
    }

    /// True when `t` is a plain fn's item type (not a constructor), so it
    /// coerces to a function pointer backed by a slot trampoline.
    /// The element type of `Vec<T>` behind one shared reference
    /// (`x = &Vec<T>`, so `&&Vec<T>` coerces to a shared `&[T]` through
    /// two derefs; ts-rust core.rs `Declarations::deref`). None for a
    /// mutable target, which a shared reference cannot give.
    fn shared_ref_vec_elem(&self, x: Ty, em: Mut) -> Option<Ty> {
        match self.kind(self.resolve(x)) {
            TyKind::Ref(_, _, v) if !em.is_mut() => self.tys.vec_elem(self.resolve(v)),
            _ => None,
        }
    }

    fn is_fn_item(&self, t: Ty) -> bool {
        match self.kind(t) {
            TyKind::FnDef(def, _) => self.p.is_fn_item_def(def),
            _ => false,
        }
    }

    /// True when `t` is an item that coerces to a fn pointer: a plain
    /// fn item (not a primitive builtin method) or a constructor.
    fn reifies(&self, t: Ty) -> bool {
        (self.is_fn_item(t) && !self.is_prim_item(t)) || self.is_ctor_item(t) || self.is_int_prim_item(t) || self.is_nopanic_prim_item(t)
    }

    /// True when `t` is a primitive builtin method item that cannot
    /// panic (`str::len`, `<[T]>::len`, `Vec::is_empty`): its fn pointer
    /// shim has no panic location to match (`is_int_prim_item`).
    fn is_nopanic_prim_item(&self, t: Ty) -> bool {
        let TyKind::FnDef(def, args) = self.kind(t) else { return false };
        let code = match self.tys.args(args).get(2) {
            Some(GenericArg::Const(c)) if def == crate::ty::prim_fn_def() => match self.tys.const_kind(*c) {
                ConstKind::Int(v) => v as u32,
                _ => return false,
            },
            _ => return false,
        };
        use Builtin as B;
        matches!(prim_builtin_of_code(code), Some(B::SliceLen | B::SliceIsEmpty | B::StrLen | B::StrIsEmpty | B::VecLen | B::VecIsEmpty))
            || prim_builtin_of_code(code).is_some_and(ufcs::no_panic_std_item)
    }

    /// True when `t` is a primitive builtin method item of an integer
    /// type (`u32::isqrt`, `i32::pow`): codegen writes its fn
    /// (`Rvalue::ItemShim`), whose panics report core's `int_impl!`
    /// line as rustc's fn pointer does. Other primitives' items have
    /// no known def site yet.
    fn is_int_prim_item(&self, t: Ty) -> bool {
        let TyKind::FnDef(def, args) = self.kind(t) else { return false };
        def == crate::ty::prim_fn_def() && matches!(self.tys.args(args).first().map(|g| g.as_ty().map(|x| self.kind(x))), Some(Some(TyKind::Int(_))))
    }

    /// True when `t` is a tuple struct or tuple variant constructor
    /// item: a user Adt's (`ctor_value_ty`), or `Some`, `Ok`, `Err`
    /// (`builtin_item_value`).
    fn is_ctor_item(&self, t: Ty) -> bool {
        let TyKind::FnDef(def, args) = self.kind(t) else { return false };
        let b = self.tys.builtins();
        let variant_first = matches!(self.tys.args(args).first(), Some(GenericArg::Const(_)));
        self.p.adt_by_def(def).is_some() || ((def == b.option || def == b.result) && variant_first)
    }

    /// True in the check of a generic fn's instance. The fn pointer
    /// region rules of `coerce_at` hold for the template's written types
    /// (its check ran them); an instance's type args may hold references
    /// (`T = &i32`) that are no binder of the pointer type.
    fn is_instance_check(&self) -> bool {
        self.p.gx.fn_class.get(self.fid.0 as usize) == Some(&generics::FnClass::Instance)
    }

    /// True when fn pointer type `t` names a region anywhere: a
    /// reference, a lifetime argument, a `dyn` type, or a nested fn
    /// pointer (or a type whose regions are not known yet).
    fn fn_ptr_has_region(&self, t: Ty) -> bool {
        let mut stack = vec![t];
        let mut first = true;
        while let Some(t) = stack.pop() {
            let t = self.resolve(t);
            match self.kind(t) {
                TyKind::FnPtr(s) if first => {
                    let s = self.tys.sig(s).value;
                    stack.extend(self.tys.tys_of(s.inputs).iter().copied());
                    stack.push(s.output);
                }
                TyKind::Ref(..) | TyKind::Dyn(..) | TyKind::FnPtr(_) | TyKind::FnDef(..) | TyKind::Closure(..) => return true,
                TyKind::Opaque(..) | TyKind::Projection(..) | TyKind::Infer(_) | TyKind::Error => return true,
                TyKind::Adt(d, _) if self.p.gx.adt_lifetimes.get(&d).is_some_and(|v| !v.is_empty()) => return true,
                TyKind::Adt(_, args) => {
                    for &g in self.tys.args(args) {
                        match g {
                            GenericArg::Ty(x) => stack.push(x),
                            GenericArg::Lifetime(_) => return true,
                            GenericArg::Const(_) => {}
                        }
                    }
                }
                TyKind::RawPtr(_, x) | TyKind::Slice(x) | TyKind::Array(x, _) => stack.push(x),
                TyKind::Tuple(ts) => stack.extend(self.tys.tys_of(ts).iter().copied()),
                _ => {}
            }
            first = false;
        }
        false
    }

    /// True when `t` is a primitive builtin method item (TRIAGE
    /// T12): it has no body fn, so it cannot reify to a function
    /// pointer (like `Box::new` today); calls through it decode
    /// to the builtin instead.
    fn is_prim_item(&self, t: Ty) -> bool {
        matches!(self.kind(t), TyKind::FnDef(def, _) if def == crate::ty::prim_fn_def())
    }

    /// The free fn a value binding names, if it names one.
    fn binding_fn(&mut self, name: Sym) -> Option<LocalDefId> {
        match self.binding(Namespace::Value, name) {
            BindingRes::Def(def) if self.p.binding_kind(def) == Some(DefsKind::Fn) => self.p.local_def(def.hash),
            _ => None,
        }
    }

    // ---------- Obligations (ARCH 2.4) ----------

    /// Binds one inference variable, recording it on the probe
    /// trail so solver probes can roll back (see `SolveCx`).
    fn bind_var(&mut self, var: u32, t: Ty) {
        // A late-bound region of `dyn Fn*` sugar stays in its object.
        let t = crate::ty::unbind(&mut self.tys, t);
        self.trail.push(var);
        self.vars[var as usize].bound = Some(t);
    }

    /// A probe snapshot of the variable bindings (see `SolveCx`).
    fn snapshot_vars(&mut self) -> usize {
        <Self as SolveCx>::snapshot(self)
    }

    /// Rolls variable bindings back to a probe snapshot.
    fn rollback_vars(&mut self, snap: usize) {
        <Self as SolveCx>::rollback(self, snap);
    }

    /// True when a fn item's signature unifies with a fn pointer type
    /// (binding inference variables on either side). A failed probe
    /// rolls its bindings back.
    fn fn_item_ptr_unifies(&mut self, item: Ty, ptr: Ty) -> bool {
        let Some((params, ret)) = self.callable_sig(item) else { return false };
        let fp = self.fn_ptr_ty(&params, ret);
        let snap = self.snapshot_vars();
        if self.unify(fp, ptr) {
            return true;
        }
        self.rollback_vars(snap);
        false
    }

    /// How many obligations wait, for probe rollback.
    fn obl_len(&self) -> usize {
        self.obl.len()
    }

    /// Drops obligations queued since an `obl_len` snapshot.
    fn obl_truncate(&mut self, len: usize) {
        self.obl.truncate(len);
    }

    /// A fresh const inference variable.
    fn fresh_const_var(&mut self) -> ConstId {
        let id = self.next_const_id;
        self.next_const_id += 1;
        self.tys.intern_const(ConstKind::Infer(id))
    }

    /// The const a const inference variable bound to, if any.
    fn resolve_const(&self, c: ConstId) -> ConstId {
        // A variable can be bound to another variable (`K::H(1)` gives
        // `K<?a>`, a struct literal field `K<?b>`, and `?b` is fixed
        // later), so follow the chain to its end.
        let mut c = c;
        while let ConstKind::Infer(id) = self.tys.const_kind(c)
            && id >= generics::INFER_MARKER_BASE
            && let Some(&next) = self.const_bindings.get(&id)
        {
            c = next;
        }
        c
    }

    /// Unifies two consts, binding a const inference variable. The
    /// binding goes on the probe trail (its id is at or above
    /// `INFER_MARKER_BASE`, never a type variable index), so a rolled
    /// back probe drops it like a type binding.
    fn unify_const(&mut self, a: ConstId, b: ConstId) -> bool {
        let (a, b) = (self.resolve_const(a), self.resolve_const(b));
        if a == b {
            return true;
        }
        match (self.tys.const_kind(a), self.tys.const_kind(b)) {
            (ConstKind::Infer(x), _) if x >= generics::INFER_MARKER_BASE => {
                self.const_bindings.insert(x, b);
                self.trail.push(x);
                true
            }
            (_, ConstKind::Infer(x)) if x >= generics::INFER_MARKER_BASE => {
                self.const_bindings.insert(x, a);
                self.trail.push(x);
                true
            }
            _ => false,
        }
    }

    /// Fresh instantiation arguments for one generics list, by
    /// parameter kind (used for Adt applications at literals).
    fn fresh_args(&mut self, generics: &Generics) -> Vec<GenericArg> {
        generics
            .params
            .iter()
            .map(|param| match param.kind {
                ParamKind::Type => GenericArg::Ty(self.new_var(false)),
                ParamKind::Lifetime => GenericArg::Lifetime(Region::Erased),
                ParamKind::Const(_) => GenericArg::Const(self.fresh_const_var()),
            })
            .collect()
    }

    /// The user Adt and args a non-generic type alias names (`type EA =
    /// E<u8>;`): value paths and patterns through the alias (`EA::A(3)`,
    /// `SA { .. }`) build or match that Adt at those args. None when
    /// `name` is not such an alias.
    /// The Adt a type item of an enclosing block binds `name` to
    /// (R18), innermost first.
    fn local_adt_of(&self, name: Sym) -> Option<AdtId> {
        self.body_scope.local_types.iter().rev().find(|(n, _, _)| *n == name).map(|e| e.1)
    }

    /// The Adt a bare type name denotes here: an enclosing block's
    /// type item first, then the flat module table.
    fn type_name_adt(&self, name: Sym) -> Option<AdtId> {
        self.local_adt_of(name).or_else(|| self.p.type_names.get(&name).copied())
    }

    fn alias_adt(&mut self, name: Sym) -> Option<(AdtId, Vec<GenericArg>)> {
        let p = self.p;
        // An alias declared in an enclosing block shadows the
        // module alias table (R18).
        if let Some(&(_, t)) = self.body_scope.local_aliases.iter().rev().find(|(n, _)| *n == name) {
            let (d, args) = p.tys.adt_parts(t)?;
            let a = p.adt_by_def(d)?;
            return Some((a, p.tys.args(args).to_vec()));
        }
        if p.aliases.is_empty() {
            return None;
        }
        let flat = match self.binding(Namespace::Type, name) {
            BindingRes::Def(def) => p.resolved.as_ref().and_then(|t| t.def_info.get(&def)).map_or(name, |i| i.flat),
            _ => name,
        };
        let &t = p.aliases.get(&flat)?;
        let (d, args) = p.tys.adt_parts(t)?;
        let a = p.adt_by_def(d)?;
        Some((a, p.tys.args(args).to_vec()))
    }

    /// `alias_adt` for the type segment of a value path, generic
    /// aliases too (`alias_seg_ty`): the user Adt and args the alias's
    /// type applies. The bool is true for a generic alias, whose written
    /// args are its own, not the Adt's.
    fn alias_adt_seg(&mut self, seg: &ast::PathSeg, span: Span) -> Option<(AdtId, Vec<GenericArg>, bool)> {
        let (t, generic) = self.alias_seg_ty(seg, span, true)?;
        let (d, args) = self.tys.adt_parts(t)?;
        let a = self.p.adt_by_def(d)?;
        Some((a, self.tys.args(args).to_vec(), generic))
    }

    /// The args of a value path through `Self` (`Self::V(..)`, `Self {
    /// .. }`, `Self(..)`, `Self::N` in patterns too): `Self` names the
    /// impl's Self type with its own args, never a fresh application of
    /// the Adt (rustc E0308 for `Self::V(5u16)` in `impl<T> G<T>`).
    /// None when the path's type segment is not `Self` or `Self` is not
    /// an application of `a`.
    fn self_path_args(&mut self, a: AdtId, segs: &[ast::PathSeg], span: Span) -> Option<Vec<GenericArg>> {
        let p = self.p;
        let ty_seg = &segs[segs.len().saturating_sub(2)];
        if ty_seg.name != p.known.self_type {
            return None;
        }
        let st = self.resolve(self.body_scope.self_ty?);
        let (d, args) = self.tys.adt_parts(st)?;
        if d != p.def_of_adt(a) {
            return None;
        }
        let args = self.tys.args(args).to_vec();
        if segs.iter().any(|s| s.has_args()) {
            self.err(
                "L0110",
                span,
                "type arguments are not allowed on a path through `Self`",
                "Remove the `::<..>` part: `Self` already names the impl's type with its arguments.",
            );
            return Some(self.error_args(&p.gx.adt_generics[a.0 as usize].clone()));
        }
        Some(args)
    }

    /// False when `name` is a const param or const item whose type is
    /// not the const param type `want` (an arg for a type param, or a
    /// name that is neither, is left to the caller).
    fn bare_const_arg_fits(&mut self, name: Sym, want: Option<ParamKind>) -> bool {
        let Some(ParamKind::Const(want)) = want else { return true };
        let have = match self.const_param(name) {
            Some((_, t, _)) => t,
            None => match self.p.const_names.get(&name) {
                Some(&ci) => self.p.consts[ci as usize].ty,
                None => return true,
            },
        };
        let (have, want) = (generics::ConstScalar::of(&self.tys, have), generics::ConstScalar::of(&self.tys, want));
        have.is_none() || have == want
    }

    /// The generic args of a value path that names user Adt `a` (a
    /// struct, or an enum through one of its variants): args written on
    /// the type segment or the variant segment, with the defaults of
    /// omitted trailing params. With no args written every param gets a
    /// fresh variable, as rustc infers them there (defaults never apply).
    fn value_path_args(&mut self, a: AdtId, segs: &[ast::PathSeg], span: Span) -> Vec<GenericArg> {
        let p = self.p;
        if let Some(args) = self.self_path_args(a, segs, span) {
            return args;
        }
        // A path through an alias of a generic Adt builds the Adt at the
        // alias's args: fixed ones (`type EA = E<u8>; EA::A(3)`), or a
        // generic alias's at the segment's args (`A::<u8>::make`).
        if let Some((aa, args, generic)) = self.alias_adt_seg(&segs[segs.len().saturating_sub(2)], span)
            && p.def_of_adt(aa) == p.def_of_adt(a)
            && !args.is_empty()
        {
            let stray = if generic { segs.len() >= 2 && segs[segs.len() - 1].has_args() } else { segs.iter().any(|s| s.has_args()) };
            if stray {
                self.err("L0105", span, "these generic arguments do not belong here", "Write the type's arguments on the alias only: `A::<u8>::name`.");
                return self.error_args(&p.gx.adt_generics[a.0 as usize].clone());
            }
            return args;
        }
        let generics = p.gx.adt_generics[a.0 as usize].clone();
        let n = segs.len();
        let written_on: Vec<&ast::PathSeg> = segs[n.saturating_sub(2)..].iter().filter(|s| s.has_args()).collect();
        let seg = match written_on.as_slice() {
            [] => return self.fresh_args(&generics),
            [one] => *one,
            _ => {
                self.err(
                    "L0110",
                    span,
                    "type arguments are not allowed on both the type and the variant",
                    "Write the arguments on one segment only.",
                );
                return self.error_args(&generics);
            }
        };
        let ast::GenericArgs::Angle(written) = &seg.args else {
            self.err("L0110", span, "parenthesized arguments are only for Fn traits", "Use angle arguments.");
            return self.error_args(&generics);
        };
        // An empty turbofish (`W::<>(..)`) infers every argument.
        if written.is_empty() {
            return self.fresh_args(&generics);
        }
        let mut args: Vec<GenericArg> = Vec::new();
        for (i, w) in written.iter().filter(|w| !matches!(w, ast::GenericArg::Lifetime(_))).enumerate() {
            let is_const = matches!(generics.params.get(i).map(|g| g.kind), Some(ParamKind::Const(_)));
            let arg = match w {
                ast::GenericArg::Type(t) if !is_const => Some(GenericArg::Ty(self.resolve_written(*t))),
                // As on a call path (`S::<true>` is a bool, `S::<{ -1 }>`
                // a negative int), then the written form's type.
                ast::GenericArg::Const(e) => {
                    let g = self.const_call_arg(*e);
                    if let (GenericArg::Const(c), Some(ParamKind::Const(t))) = (g, generics.params.get(i).map(|g| g.kind))
                        && let Some(want) = generics::ConstScalar::of(&self.tys, t)
                    {
                        let cx = p.gx.resolve_cx(&p.type_names, &p.aliases);
                        let typed = generics::check_const_expr_ty(
                            &p.ast,
                            &p.interner,
                            &p.known,
                            &cx,
                            &mut self.tys,
                            &self.body_scope,
                            *e,
                            c,
                            want,
                            span,
                            "this const argument",
                        );
                        if let Err(d) = typed {
                            self.errs.push(d);
                            return self.error_args(&generics);
                        }
                        self.type_anon_const(*e, Some(want.ty()));
                    }
                    Some(g)
                }
                ast::GenericArg::Type(t) => match p.ast.ty(*t) {
                    // A bare const name (`S::<K>`) must have the param's
                    // type, as in a type position (rustc E0308).
                    ast::TyExpr::Path(ps)
                        if ps.len() == 1 && !self.bare_const_arg_fits(ps[0].name, generics.params.get(i).map(|g| g.kind)) =>
                    {
                        self.err(
                            "L0110",
                            span,
                            "mismatched types: this const argument has the wrong type",
                            "Use a const of the parameter's type.",
                        );
                        return self.error_args(&generics);
                    }
                    ast::TyExpr::Path(ps) if ps.len() == 1 => match self.const_param(ps[0].name) {
                        Some((pi, _, val)) => Some(GenericArg::Const(self.tys.intern_const(val.unwrap_or(ConstKind::Param(pi))))),
                        None => crate::check::collect::named_const_kind(&p.ast, &p.interner, &p.known, ps[0].name, span)
                            .map(|k| GenericArg::Const(self.tys.intern_const(k))),
                    },
                    _ => None,
                },
                _ => None,
            };
            match arg {
                Some(g) => args.push(g),
                None => {
                    self.err(
                        "L0110",
                        span,
                        "this generic argument form is not supported here",
                        "Write a type, or a literal const argument.",
                    );
                    return self.error_args(&generics);
                }
            }
        }
        let cx = p.gx.resolve_cx(&p.type_names, &p.aliases);
        let g_ast = crate::check::defaults::type_generics(&p.ast, &cx, p.adt(a).name);
        let min = g_ast.map_or(generics.params.len(), crate::check::defaults::required);
        if args.len() < min || args.len() > generics.params.len() {
            self.err(
                "L0105",
                span,
                format!(
                    "`{}` takes {} generic argument(s) but {} were given",
                    p.display_path(p.adt(a).name),
                    generics.params.len(),
                    args.len()
                ),
                "Write one argument per parameter, or leave them all out to infer them.",
            );
            return self.error_args(&generics);
        }
        if let Some(g) = g_ast
            && let Err(d) = crate::check::defaults::fill(
                &p.ast,
                &p.interner,
                &p.known,
                &cx,
                &mut self.tys,
                &generics::Scope::default(),
                g,
                None,
                &mut args,
                span,
            )
        {
            self.errs.push(d);
            return self.error_args(&generics);
        }
        if !self.check_const_args(&generics, &args, span) {
            return self.error_args(&generics);
        }
        args
    }

    /// Args for a generics list after a reported error: the error type
    /// for every type param, so no second error follows from them.
    fn error_args(&mut self, generics: &Generics) -> Vec<GenericArg> {
        generics
            .params
            .iter()
            .map(|param| match param.kind {
                ParamKind::Lifetime => GenericArg::Lifetime(Region::Erased),
                ParamKind::Const(_) => GenericArg::Const(self.fresh_const_var()),
                ParamKind::Type => GenericArg::Ty(ERROR),
            })
            .collect()
    }

    /// This body's elaborated param env.
    fn env(&self) -> &'p [Predicate] {
        self.p.gx.fn_scopes.get(self.fid.0 as usize).map_or(&[], |fs| &fs.env)
    }

    /// The env selection and normalization use: `env()`, plus the bounds
    /// of the callee opaque types met so far (`opaque::note_opaques`).
    fn solve_env(&self) -> std::borrow::Cow<'p, [Predicate]> {
        if self.opaque_env.is_empty() { std::borrow::Cow::Borrowed(self.env()) } else { std::borrow::Cow::Owned(self.opaque_env.clone()) }
    }

    /// Normalizes one type here (section 2.5) through this body's
    /// solver. The solver state is taken out for the call because
    /// the context itself is the `SolveCx`.
    /// One field type of a generic Adt at the given args, with its
    /// projections normalized (`Owned(<B as ToOwned>::Owned)`).
    fn subst_field(&mut self, t: Ty, args: &[GenericArg]) -> Ty {
        let t = subst(&mut self.tys, t, args);
        if self.tys.flags(t).contains_projection() { self.normalize_here(t) } else { t }
    }

    fn normalize_here(&mut self, t: Ty) -> Ty {
        if !self.tys.flags(t).contains_projection() {
            return t;
        }
        let p = self.p;
        self.note_opaques(t);
        let env = self.solve_env();
        let mut solver = std::mem::take(&mut self.solver);
        let out = crate::traits::solve::normalize(&mut solver, self, &p.gx.index, &env, t);
        self.solver = solver;
        out
    }

    /// True when the trait ref can never hold: every impl candidate's
    /// header fails or one of its where clauses is provably false
    /// (`Solver::provably_false`). Binds nothing.
    pub(super) fn provably_false(&mut self, tr: TraitRef) -> bool {
        let p = self.p;
        let env = self.solve_env();
        let mut solver = std::mem::take(&mut self.solver);
        let out = solver.provably_false(self, &p.gx.index, &env, tr);
        self.solver = solver;
        out
    }

    /// Selects evidence for one trait obligation, with the
    /// structural answers of sections 2.7 (`Sized`, auto traits)
    /// and the derive-family queries ahead of the general solver
    /// where they are exact. Commits bindings on success, like
    /// `Solver::select`.
    fn select_obligation(&mut self, tr: TraitRef) -> Selection {
        self.select_obligation_at(tr, Span::default(), 0)
    }

    /// `select_obligation` at one nesting depth: a confirmed
    /// impl's nested predicates are queued at depth + 1, so a
    /// self-referential impl (`impl<X> T for Vec<X> where
    /// Vec<X>: T`) overflows through the queue (section 2.4
    /// step 7) instead of looping. Synchronous callers pass the
    /// span to blame and depth 0.
    fn select_obligation_at(&mut self, tr: TraitRef, span: Span, depth: u16) -> Selection {
        // rustc's evaluation depth: the root obligation is depth 0 and its
        // stack entry counts once more, so a nested obligation at depth
        // `limit` overflows (an `Option` nested 128 deep asks `u8: Copy`
        // at depth 128 and fails; 127 deep compiles).
        if depth as usize >= self.recursion_limit {
            return Selection::Overflow;
        }
        let sel = self.select_obligation_here(tr, span, depth);
        // A structural answer (the derive family and the auto traits on std
        // and structural types) queues no nested goals, so the depth rustc
        // reaches below it comes from the type (`depth::struct_depth`).
        let queued = matches!(&sel, Selection::Impl { nested, .. } if nested.iter().any(|q| matches!(q, Predicate::Trait(b) if b.count == 0)));
        if !queued
            && matches!(sel, Selection::Impl { .. } | Selection::ParamEvidence(_) | Selection::Builtin)
            && let Some(fam) = depth::family(self.p, tr.def)
            && let Some(t) = self.tys.args(tr.args).first().and_then(|g| g.as_ty())
        {
            let t = self.deep(t);
            if depth as usize + depth::struct_depth(self.p, &self.tys, fam, t, &mut self.depth_memo) >= self.recursion_limit {
                return Selection::Overflow;
            }
        }
        sel
    }

    /// `select_obligation_at` without the depth checks.
    fn select_obligation_here(&mut self, tr: TraitRef, span: Span, depth: u16) -> Selection {
        let p = self.p;
        let lang = &p.gx.lang;
        // Projections in the trait ref normalize first: an
        // associated bound like `<Local2 as IntoIter>::It: Iter`
        // selects against the concrete iterator type.
        let tr = {
            let raw: Vec<GenericArg> = self.tys.args(tr.args).to_vec();
            let normed: Vec<GenericArg> = raw
                .iter()
                .map(|&g| match g {
                    // Variables resolve first: a variable bound to
                    // `<u32 as TryInto<u16>>::Error` normalizes too.
                    GenericArg::Ty(t) => {
                        let t = if self.tys.flags(t).contains_infer() { self.deep(t) } else { t };
                        GenericArg::Ty(self.normalize_here(t))
                    }
                    other => other,
                })
                .collect();
            let args = self.tys.intern_args(&normed);
            TraitRef { args, ..tr }
        };
        let self_ty = self.deep(self.tys.args(tr.args)[0].as_ty().unwrap_or(ERROR));
        // An input with the error type (a name that did not resolve) has its
        // diagnostic already, and it matches every impl header: `&{error}: AsRef<P>`
        // picked the blanket `&T` impl with `T` unbound, which queued fresh nested
        // obligations each round, so a few of them took minutes (fx-parsehang). The
        // obligation holds instead, as in rustc. Only after an error is reported: an
        // error type with no diagnostic behind it must not make a bound hold.
        for i in 0..if self.errs.is_empty() { 0 } else { self.tys.args(tr.args).len() } {
            if let Some(t) = self.tys.args(tr.args)[i].as_ty() {
                let t = self.deep(t);
                if self.has_error_kind(t) {
                    return Selection::ParamEvidence(usize::MAX);
                }
            }
        }
        // A projection that cannot normalize while an input is still a
        // variable (`<u32 as TryInto<?T>>::Error: Debug` from
        // `x.try_into().unwrap()` before a later use names `?T`) waits
        // for inference instead of failing (fx-tryfrom).
        if matches!(self.tys.kind(self_ty), TyKind::Projection(..)) && self.has_unbound_deep(self_ty) {
            return Selection::Ambiguous;
        }
        if tr.def == lang.sized {
            // A general variable may still become `[T]`, `str`, a dyn
            // type, or a `?Sized` param's stand-in (`f(s)` runs this
            // queue before the argument unifies): keep the obligation
            // until the variable is known.
            if matches!(self.tys.kind(self_ty), TyKind::Infer(v) if !v.is_int() && !v.is_float()) {
                return Selection::Ambiguous;
            }
            return if self.sized_ok(self_ty) { Selection::ParamEvidence(usize::MAX) } else { Selection::NoImpl };
        }
        // An open input for a scalar Self has several scalar `From`
        // impls in core, not just the reflexive record: a pick of
        // `From<T> for T` (or no pick) then defers until inference
        // names the input (`T: Into<i64>` must not make `T` an i64).
        let mut defer_reflexive_from = false;
        // Numeric `From` obligations are widening casts, with no
        // impl behind them in this subset's lang records.
        if tr.def == lang.from
            && let Some(input) = self.tys.args(tr.args).get(1).and_then(|g| g.as_ty())
        {
            let input = self.deep(input);
            if Self::numeric_from_ok(self.kind(input), self.kind(self_ty)) {
                return Selection::ParamEvidence(usize::MAX);
            }
            let (ik, sk) = (self.kind(input), self.kind(self_ty));
            if let Some(sel) = self.lit_from_select(input, ik, self_ty, sk) {
                return sel;
            }
            defer_reflexive_from =
                matches!(ik, TyKind::Infer(_)) && matches!(sk, TyKind::Int(_) | TyKind::Float(_) | TyKind::Char | TyKind::Infer(_));
            if matches!(self.kind(input), TyKind::Int(_) | TyKind::Float(_) | TyKind::Char | TyKind::Bool)
                && matches!(self.kind(self_ty), TyKind::Int(_) | TyKind::Float(_) | TyKind::Char | TyKind::Bool)
            {
                return Selection::NoImpl;
            }
        }
        // std's `UnwindSafe` and `RefUnwindSafe` (check/unwind.rs).
        if let Some(refs) = unwind::unwind_trait(p, tr.def) {
            let env = self.solve_env();
            match unwind::unwind_safe(p, &mut self.tys, &env, refs, self_ty, &mut Vec::new()) {
                Some(true) => return Selection::ParamEvidence(usize::MAX),
                Some(false) => return Selection::NoImpl,
                None => {}
            }
        }
        // Scalar `TryFrom` and `TryInto` are checked casts, like
        // numeric `From` (check/tryfrom.rs).
        if let Some(sel) = self.try_from_select(tr, self_ty) {
            return sel;
        }
        if lang.is_auto(tr.def) {
            match self.auto_holds(tr.def, self_ty) {
                Some(true) => return Selection::ParamEvidence(usize::MAX),
                Some(false) => return Selection::NoImpl,
                // A non-param self type over a still-open variable
                // (`Vec<?T>: Send` from a where clause, before the
                // call's arguments name `?T`) is not yet a "no":
                // the obligation waits for inference, like a bare
                // param self type does through the solver.
                None if self.has_unbound_deep(self_ty) => return Selection::Ambiguous,
                None => {}
            }
        }
        // The object candidate (ARCH 2.8): `dyn P` implements `P` and
        // every supertrait of `P`, with no impl behind it; calls go
        // through the vtable.
        if let Some(pr) = object::principal_of(&self.tys, self_ty) {
            // The fmt traits are supertraits with no super slot (the
            // vtable header shims in check/object.rs).
            if (tr.def == lang.debug || tr.def == lang.display) && object::principal_has_supertrait(p, pr.def, tr.def) {
                return Selection::ParamEvidence(usize::MAX);
            }
            let want = object::with_self(&mut self.tys, tr, DYN_SELF);
            let want = TraitRef { bindings: EMPTY_BINDINGS, ..want };
            let holds = if pr.def == want.def {
                self.unify_args(pr.args, want.args)
            } else {
                object::upcast_path(p, &mut self.tys, pr, want).is_some()
            };
            if holds {
                return Selection::ParamEvidence(usize::MAX);
            }
        }
        // An `impl Trait` Self proves its bounds (check/opaque.rs).
        for g in self.tys.args(tr.args).to_vec() {
            if let GenericArg::Ty(t) = g {
                let t = self.deep(t);
                self.note_opaques(t);
            }
        }
        let env = self.solve_env();
        let mut solver = std::mem::take(&mut self.solver);
        let snap = self.snapshot_vars();
        let sel = solver.select(self, &p.gx.index, &env, tr);
        self.solver = solver;
        let lang_pick =
            matches!(&sel, Selection::Impl { id, .. } if p.gx.index.get(*id).synthetic == crate::traits::index::Synthetic::Lang);
        if defer_reflexive_from && (lang_pick || sel == Selection::NoImpl) {
            self.rollback_vars(snap);
            return Selection::Ambiguous;
        }
        if sel == Selection::NoImpl && self.derive_query_holds(tr.def, self_ty) {
            return Selection::ParamEvidence(usize::MAX);
        }
        // A structural derive-family answer over a type that still
        // holds inference variables is not yet a "no": `[?T; 1]:
        // Default` from a generic field's bound (`Store<[T; 1]>`
        // built before `T` is named) holds or not by what `?T`
        // becomes, so the obligation waits for inference instead
        // of failing here.
        if sel == Selection::NoImpl
            && p.gx.index.derive_family.contains(&tr.def)
            && matches!(
                self.tys.kind(self_ty),
                TyKind::Tuple(_) | TyKind::Array(..) | TyKind::Slice(_) | TyKind::Ref(..) | TyKind::RawPtr(..)
            )
            && (self.has_unbound_deep(self_ty)
                || matches!(self.tys.kind(self_ty), TyKind::Array(_, n) if matches!(self.tys.const_kind(n), ConstKind::Infer(_))))
        {
            return Selection::Ambiguous;
        }
        // An impl for a `'static` dyn type (`impl X for dyn Tr`), picked
        // for trait args that may hold a shorter lifetime.
        if let Selection::Impl { id, .. } = &sel
            && p.gx.static_dyn_impls.contains(&p.gx.index.get(*id).def)
            && !self.tys.args(tr.args).to_vec().into_iter().filter_map(|g| g.as_ty()).all(|t| {
                let t = self.deep(t);
                !self.has_unbound_deep(t) && object::static_regions_known(p, &self.tys, t)
            })
        {
            self.obl.push(obligations::Obligation::DynStatic { span });
        }
        if let Selection::Impl { nested, .. } = &sel {
            for pred in nested.clone() {
                match pred {
                    Predicate::Trait(b) if b.count == 0 => self.obl.push_trait_at(b.value, span, depth + 1),
                    Predicate::AssocEq(b) if b.count == 0 => self.obl.push(obligations::Obligation::AssocEq { eq: b.value, span }),
                    Predicate::TypeOutlives(ty, Region::Static) => self.obl.push(obligations::Obligation::TypeStatic { ty, span }),
                    _ => {}
                }
            }
        }
        sel
    }

    /// The derive-family structural queries, for types the impl
    /// index has no record for (tuples, arrays, slices, refs).
    /// User and builtin Adts answer through the solver instead.
    fn derive_query_holds(&mut self, trait_def: DefId, self_ty: Ty) -> bool {
        let p = self.p;
        let lang = &p.gx.lang;
        match self.tys.kind(self_ty) {
            TyKind::Tuple(_) | TyKind::Array(..) | TyKind::Slice(_) | TyKind::Ref(..) | TyKind::RawPtr(..) => {}
            TyKind::Closure(..) if trait_def == lang.copy || trait_def == lang.clone => {}
            // core's `impl<F: FnPtr> Hash for F` (the address), and the
            // builtin Copy and Clone of every fn pointer and fn item.
            TyKind::FnPtr(_) => return trait_def == lang.hash || trait_def == lang.copy || trait_def == lang.clone,
            TyKind::FnDef(..) => return trait_def == lang.copy || trait_def == lang.clone,
            // A builtin iterator std makes Clone (`iter_clone_is_copy`).
            // std's owning iterators (vec, option, result `IntoIter`):
            // Debug and Clone by the glue walks, and `vec::IntoIter`'s
            // Default (cgen's `CTy::VecIter` and `CTy::OptIter` glue).
            TyKind::Adt(..)
                if ((trait_def == lang.clone || trait_def == lang.debug) && crate::check::collect::owning_iter_elem(&self.tys, self_ty).is_some())
                    || (trait_def == lang.default && crate::check::collect::vec_into_iter_elem(&self.tys, self_ty).is_some()) => {}
            // `PhantomData<T>`'s Debug is glue for a `T` lust can name.
            TyKind::Adt(..) if trait_def == lang.debug && self.tys.local_adt(self_ty).is_some_and(|a| p.is_phantom_adt(a)) => {}
            TyKind::Adt(..) if trait_def == lang.clone && (self.tys.is_chars_ty(self_ty) || crate::ty::iter::iter_parts(&self.tys, self_ty).is_some()) => {
                return crate::check::collect::iter_clone_is_copy(p, &self.tys, self_ty);
            }
            // core's `impl Debug for !` (`catch_unwind` of a closure that
            // always panics gives `Result<!, _>`; W-UNWIND).
            TyKind::Never => return trait_def == lang.debug,
            // core's `impl Debug for dyn Any (+ Send (+ Sync))` (`Any { .. }`):
            // `thread::Result`'s Err unwraps with it.
            TyKind::Dyn(..) if trait_def == lang.debug => return has_debug(p, &self.tys, self_ty),
            _ => return false,
        }
        if trait_def == lang.copy {
            is_copy(p, &self.tys, self_ty)
        } else if trait_def == lang.clone {
            self.record_glue_reads(trait_def, self_ty);
            has_clone(p, &self.tys, self_ty)
        } else if trait_def == lang.debug {
            has_debug(p, &self.tys, self_ty)
        } else if trait_def == lang.partial_eq {
            self.record_glue_reads(trait_def, self_ty);
            has_eq(p, &self.tys, self_ty)
        } else if trait_def == lang.eq {
            // `Eq` is the total walk, not `PartialEq`'s: a float
            // anywhere inside (or a field that is only `PartialEq`)
            // breaks it (f32 and f64 have no `Eq` impl in core).
            self.record_glue_reads(trait_def, self_ty);
            has_total_eq(p, &self.tys, self_ty)
        } else if trait_def == lang.partial_ord {
            has_ord(p, &self.tys, self_ty)
        } else if trait_def == lang.ord {
            has_total_ord(p, &self.tys, self_ty)
        } else if trait_def == lang.hash {
            has_hash(p, &self.tys, self_ty)
        } else if trait_def == lang.default {
            self.record_glue_reads(trait_def, self_ty);
            has_default(p, &self.tys, self_ty)
        } else {
            false
        }
    }

    /// `Sized` by structure (section 2.7 basics): a parameter is
    /// sized when the env says so; an Adt when its fields are,
    /// with an unsized last field making the Adt unsized.
    fn sized_ok(&mut self, t: Ty) -> bool {
        let t = self.normalize_here(t);
        if own::dyn_wrapped_elem(&self.tys, t).is_some() {
            return false;
        }
        match self.tys.kind(t) {
            TyKind::Str | TyKind::Slice(_) | TyKind::Dyn(..) => false,
            TyKind::Param(p) => self.env().iter().any(|pred| {
                matches!(pred, Predicate::Trait(b) if b.value.def == self.p.gx.lang.sized
                    && self.tys.args(b.value.args)[0].as_ty().is_some_and(|s| matches!(self.tys.kind(s), TyKind::Param(q) if q == p)))
            }),
            TyKind::Projection(..) => true,
            TyKind::Infer(_) => true,
            // A tuple is as sized as its last element; the others
            // must be sized for the tuple to be well-formed at all.
            TyKind::Tuple(ts) => match self.tys.tys_of(ts).last() {
                Some(&e) => self.sized_ok(e),
                None => true,
            },
            TyKind::Array(..) => true,
            _ => {
                if let Some(a) = self.tys.local_adt(t) {
                    // Only a last field can be unsized. Without a
                    // materialized instance, `local_adt` answers with the
                    // template, whose fields are over its own params:
                    // substitute this application's args first.
                    let p = self.p;
                    let args: Vec<GenericArg> = self.tys.adt_parts(t).map(|(_, a)| self.tys.args(a).to_vec()).unwrap_or_default();
                    let lasts: Vec<Ty> = p.adt(a).variants.iter().filter_map(|v| v.fields.last().map(|f| f.ty)).collect();
                    lasts.into_iter().all(|f| {
                        let f = if args.is_empty() { f } else { subst(&mut self.tys, f, &args) };
                        let f = self.normalize_here(f);
                        self.sized_ok(f)
                    })
                } else {
                    crate::check::collect::is_sized_ty(&self.tys, t)
                }
            }
        }
    }

    /// An auto trait by structure (section 2.7). None when the
    /// answer needs the param env or inference to move first.
    fn auto_holds(&mut self, trait_def: DefId, t: Ty) -> Option<bool> {
        let mut seen = crate::check::collect::AutoSeen::default();
        self.auto_inner(trait_def, t, &mut seen)
    }

    fn auto_inner(&mut self, trait_def: DefId, t: Ty, seen: &mut crate::check::collect::AutoSeen) -> Option<bool> {
        let t = self.deep(t);
        // The answer reads the fields of every Adt in `t` (their
        // layouts' fingerprints cover nested field types), but not what
        // a raw pointer, or for `Send` and `Sync` an `Rc`, points at.
        let lang = &self.p.gx.lang;
        let behind = if trait_def == lang.send || trait_def == lang.sync { crate::driver::graph::Behind::SendSync } else { crate::driver::graph::Behind::Other };
        self.p.record_structure_reads(&mut self.out.reads, &self.tys, t, behind, crate::driver::graph::answer::AUTO);
        self.note_opaques(t);
        // A walk from the top answers the same each time for a type the env
        // cannot reach (`auto_memo`); one inside a cycle may lean on `seen`.
        let flags = self.tys.flags(t);
        let memo = seen.is_empty() && self.opaque_env.is_empty() && !flags.contains_param() && !flags.contains_infer() && !flags.contains_projection();
        if memo && let Some(&r) = self.auto_memo.get(&(trait_def, t)) {
            return r;
        }
        let env = self.solve_env();
        let r = crate::check::collect::auto_structural(self.p, &mut self.tys, &env, trait_def, t, seen);
        if memo {
            self.auto_memo.insert((trait_def, t), r);
        }
        r
    }

    /// W-BORROW: for each `Fn`-family bound whose self type is a param the
    /// call instantiates with an inference var (a closure argument's
    /// expected type), records how the closure's arguments get their
    /// regions (`ClosureInfo::free_args`): an input that is a type param
    /// or projection is free (the caller's type); `&` over one has a
    /// higher-ranked outer reference (the bound writes it), unless the
    /// callee's regioned bound (`fn_bounds`, `RegionSig::fn_bounds`)
    /// names that lifetime (`&'static Message`, `&'a T`: free, and
    /// borrowck ties it), as is an input whose every region the bound
    /// names; any other input with regions makes every argument
    /// higher-ranked (no entry).
    fn note_closure_bounds(&mut self, preds: &[Predicate], subst_args: &[GenericArg], fn_bounds: &[crate::borrowck::FnBound]) {
        let p = self.p;
        for pred in preds {
            let Predicate::Trait(b) = pred else { continue };
            if b.count != 0 || !p.gx.lang.is_fn_family(b.value.def) {
                continue;
            }
            let args: Vec<GenericArg> = p.tys.args(b.value.args).to_vec();
            let (Some(self_t), Some(inputs)) = (args.first().and_then(|g| g.as_ty()), args.get(1).and_then(|g| g.as_ty())) else { continue };
            let TyKind::Param(j) = p.tys.kind(self_t) else { continue };
            let Some(target) = subst_args.get(j.0 as usize).and_then(|g| g.as_ty()) else { continue };
            let target = self.resolve(target);
            let TyKind::Infer(v) = self.kind(target) else { continue };
            let TyKind::Tuple(ts) = p.tys.kind(inputs) else { continue };
            let opaque = |t: Ty| matches!(p.tys.kind(t), TyKind::Param(_) | TyKind::Projection(..)) || !bound_type_has_regions(p, t);
            let n_in = p.tys.tys_of(ts).len();
            let bound = fn_bounds.iter().find(|b| b.param == j.0 && b.inputs.len() == n_in);
            let regioned = bound.map(|b| b.inputs.as_slice());
            if let Some(b) = bound {
                self.closure_bound_inputs.insert(v.0, b.inputs.clone());
                if b.output.is_some_and(|o| p.tys.flags(o).contains_param()) {
                    self.closure_call_outs.insert(v.0);
                }
            }
            if let Some(b) = bound
                && let Some(out) = b.output
            {
                let (mut ins, mut outs) = (Vec::new(), Vec::new());
                for &t in &b.inputs {
                    crate::borrowck::regions_of(&p.tys, t, &mut ins);
                }
                crate::borrowck::regions_of(&p.tys, out, &mut outs);
                if matches!(ins[..], [Region::Bound(_)]) && outs.iter().any(|r| matches!(r, Region::Bound(_))) {
                    self.closure_bound_outputs.insert(v.0, out);
                }
            }
            let named_ref = |i: usize| {
                regioned.and_then(|ins| ins.get(i)).is_some_and(|&rt| matches!(p.tys.kind(rt), TyKind::Ref(Region::Static | Region::Param(_), _, _)))
            };
            // Every region of the regioned input is one the bound names
            // (`Box<dyn FnOnce() + Send + 'a>`, the callee's `'a`): free,
            // and borrowck ties each slot to it (`link_bound_closure`).
            let named_only = |i: usize| {
                let Some(&rt) = regioned.and_then(|ins| ins.get(i)) else { return false };
                let mut rs = Vec::new();
                bound_input_regions(p, rt, &mut rs).is_some() && !rs.is_empty() && rs.iter().all(|r| matches!(r, Region::Static | Region::Param(_)))
            };
            let mut flags = Vec::new();
            let mut ok = true;
            for (i, &t) in p.tys.tys_of(ts).iter().enumerate() {
                match p.tys.kind(t) {
                    TyKind::Ref(_, _, inner) if opaque(inner) && named_ref(i) => flags.push(false),
                    TyKind::Ref(_, _, inner) if opaque(inner) => flags.push(true),
                    _ if opaque(t) => flags.push(false),
                    _ if named_only(i) => flags.push(false),
                    _ => ok = false,
                }
            }
            if ok {
                self.iter_closure_args.insert(v.0, flags);
            }
        }
    }

    /// Pushes the predicates of one instantiated item bound set:
    /// trait predicates as obligations, equalities as `AssocEq`
    /// obligations.
    fn push_predicates(&mut self, preds: &[Predicate], subst_args: &[GenericArg], span: Span) {
        self.push_predicates_with(preds, subst_args, span, &[]);
    }

    /// `push_predicates` for a fn template whose region signature keeps
    /// its `Fn` bounds with regions (`note_closure_bounds`).
    fn push_predicates_with(&mut self, preds: &[Predicate], subst_args: &[GenericArg], span: Span, fn_bounds: &[crate::borrowck::FnBound]) {
        self.note_closure_bounds(preds, subst_args, fn_bounds);
        let mut out: Vec<obligations::Obligation> = Vec::new();
        for &pred in preds {
            let pred = crate::traits::index::subst_predicate(&mut self.tys, pred, subst_args);
            match pred {
                Predicate::Trait(b) if b.count == 0 => out.push(obligations::Obligation::Trait { trait_ref: b.value, span, depth: 0 }),
                Predicate::AssocEq(b) if b.count == 0 => out.push(obligations::Obligation::AssocEq { eq: b.value, span }),
                Predicate::TypeOutlives(ty, Region::Static) => out.push(obligations::Obligation::TypeStatic { ty, span }),
                _ => {}
            }
        }
        // Elaborate so supertraits and binding equalities are
        // proved too, then queue the lot.
        let p = self.p;
        let traits_only: Vec<Predicate> =
            preds.iter().map(|&pred| crate::traits::index::subst_predicate(&mut self.tys, pred, subst_args)).collect();
        let elaborated = generics::elaborate_env(&mut self.tys, &p.gx.index, &traits_only);
        let mut queued = out;
        for pred in elaborated {
            match pred {
                Predicate::Trait(b) if b.count == 0 => {
                    if !queued.iter().any(|o| matches!(o, obligations::Obligation::Trait { trait_ref, .. } if *trait_ref == b.value)) {
                        queued.push(obligations::Obligation::Trait { trait_ref: b.value, span, depth: 0 });
                    }
                }
                Predicate::AssocEq(b) if b.count == 0 => {
                    if !queued.iter().any(|o| matches!(o, obligations::Obligation::AssocEq { eq, .. } if *eq == b.value)) {
                        queued.push(obligations::Obligation::AssocEq { eq: b.value, span });
                    }
                }
                _ => {}
            }
        }
        for o in queued {
            self.obl.push(o);
        }
    }

    /// Runs the obligation queue (the 2.4 run points). With
    /// `hard`, anything left is an error; without, unresolved
    /// obligations stay queued for the next point.
    fn run_obligations(&mut self, hard: bool) {
        if self.obl.is_empty() {
            return;
        }
        // A fixpoint over rounds: nested obligations and bindings
        // from one round can settle the next.
        for _round in 0..128 {
            let work = self.obl.take();
            if work.is_empty() {
                break;
            }
            let mut pending: Vec<obligations::Obligation> = Vec::new();
            let mut progress = false;
            for ob in work {
                // What a selection queues and binds, to tell a repeat (below).
                let (queued, trail, vars, consts) = (self.obl.len(), self.trail.len(), self.vars.len(), self.next_const_id);
                match ob {
                    obligations::Obligation::AssocEq { eq, span } => {
                        if self.prove_assoc_eq(eq, span) {
                            progress = true;
                        } else {
                            pending.push(ob);
                        }
                    }
                    obligations::Obligation::DynStatic { .. } | obligations::Obligation::TypeStatic { .. } | obligations::Obligation::StaticSource { .. } => {
                        pending.push(ob)
                    }
                    // Error recovery: once the body has an error, an obligation
                    // over an error type proves nothing more (the compile fails
                    // anyway). Selecting it tried every impl of the trait and
                    // reported each (`fs::canonicalize(&unknown)`: 20,000 L0613
                    // in 113 s).
                    obligations::Obligation::Trait { trait_ref, .. }
                        if !self.errs.is_empty()
                            && self.tys.args(trait_ref.args).to_vec().into_iter().any(|g| g.as_ty().is_some_and(|t| {
                                let t = self.resolve(t);
                                self.has_error_kind(t)
                            })) =>
                    {
                        progress = true;
                    }
                    obligations::Obligation::Trait { trait_ref, span, depth } => match self.select_obligation_at(trait_ref, span, depth) {
                        Selection::Impl { id, args, unbound, .. } => {
                            if !unbound.is_empty() && self.still_unbound(&unbound, trait_ref) {
                                // A re-queued obligation that selects the same impl with the
                                // same args again binds only the probe's fresh variables and
                                // queues copies of the nested predicates its last selection
                                // queued: no progress. Counting it ran every run point to the
                                // round cap and grew the queue each round.
                                let bound_old = self.trail.get(trail..).unwrap_or(&[]).iter().any(|&v| {
                                    if v >= generics::INFER_MARKER_BASE { v < consts } else { (v as usize) < vars }
                                });
                                if self.obl.note_requeued(trait_ref, span, depth, id, &args) || bound_old {
                                    progress = true;
                                } else {
                                    self.obl.truncate(queued);
                                }
                                pending.push(ob);
                            } else {
                                progress = true;
                            }
                        }
                        Selection::ParamEvidence(_) | Selection::Builtin => {
                            progress = true;
                            self.prove_bindings(trait_ref, span);
                        }
                        Selection::Ambiguous => pending.push(ob),
                        Selection::NoImpl => {
                            progress = true;
                            // A doubling type (`G<(T, T)>` at each level) prints
                            // at exponential length: such a name is `_`.
                            let self_ty = self.resolve(self.tys.args(trait_ref.args)[0].as_ty().unwrap_or(ERROR));
                            let tn = if dropck::short_name(self.p, &self.tys, self_ty) == "_" { "_".to_string() } else { self.tn(self_ty) };
                            let tr_name = self.trait_name(trait_ref.def);
                            self.err("L0612", span, format!("no impl of `{tr_name}` for `{tn}`"), "Add the impl, or change the bound.");
                        }
                        Selection::Overflow => {
                            progress = true;
                            self.err(
                                "L0611",
                                span,
                                "trait selection overflowed: the obligations recurse too deeply",
                                "Simplify the impls or bounds involved.",
                            );
                        }
                    },
                }
            }
            for ob in pending {
                self.obl.push(ob);
            }
            if !progress {
                break;
            }
        }
        if hard && !self.obl.is_empty() {
            let mut dyn_static: Vec<Span> = Vec::new();
            let mut type_static: Vec<(Ty, Span)> = Vec::new();
            let mut static_src: Vec<(Ty, Span)> = Vec::new();
            for ob in self.obl.take() {
                match ob {
                    obligations::Obligation::DynStatic { span } => dyn_static.push(span),
                    obligations::Obligation::TypeStatic { ty, span } => type_static.push((ty, span)),
                    obligations::Obligation::StaticSource { ty, span } => static_src.push((ty, span)),
                    obligations::Obligation::Trait { trait_ref, span, .. } => {
                        // One last try now that literal fallbacks and
                        // late bindings have run: an impl with a
                        // still-unbound parameter is the step-4
                        // error, everything else is annotation.
                        let mut sel = self.select_obligation(trait_ref);
                        // A diverging Self variable falls back to `!`
                        // first (edition 2024), as in rustc.
                        if sel == Selection::Ambiguous
                            && let TyKind::Infer(v) = self.kind(self.tys.args(trait_ref.args)[0].as_ty().unwrap_or(ERROR))
                            && self.is_diverging_root(v.index())
                        {
                            self.bind_var(v.index(), NEVER);
                            sel = self.select_obligation(trait_ref);
                        }
                        match sel {
                            Selection::Impl { unbound, .. } if !unbound.is_empty() => {
                                self.err(
                                    "L0613",
                                    span,
                                    "an impl parameter is not known from the trait inputs",
                                    "Rewrite the impl so every parameter follows from the trait reference or an associated equality.",
                                );
                            }
                            Selection::Impl { .. } | Selection::ParamEvidence(_) | Selection::Builtin => {}
                            Selection::NoImpl => {
                                let tn = self.tn(self.tys.args(trait_ref.args)[0].as_ty().unwrap_or(ERROR));
                                let tr_name = self.trait_name(trait_ref.def);
                                self.err("L0612", span, format!("no impl of `{tr_name}` for `{tn}`"), "Add the impl, or change the bound.");
                            }
                            _ => {
                                self.err(
                                    "L0610",
                                    span,
                                    "type annotations needed: this trait obligation could not be resolved",
                                    "Annotate the types involved so one impl is picked.",
                                );
                            }
                        }
                    }
                    obligations::Obligation::AssocEq { span, .. } => {
                        self.err(
                            "L0610",
                            span,
                            "type annotations needed: an associated type could not be resolved",
                            "Annotate the types involved, or name the associated type in the bound.",
                        );
                    }
                }
            }
            for (ty, span) in static_src {
                let ty = self.deep(ty);
                // A source that borrows only through references and
                // inferred object lifetimes is the borrow checker's.
                if object::may_borrow_in(self.p, &self.tys, self.env(), ty) && object::may_borrow_untracked_in(self.p, &self.tys, self.env(), ty) {
                    self.static_source_err(ty, span);
                }
            }
            self.check_dyn_static(dyn_static);
            self.check_type_static(type_static);
        }
    }

    /// Reports the `'static` bounds that do not hold (see
    /// `static_bound_err`). Concrete instances skip them, as they skip
    /// `check_dyn_static`: the template check proved each bound over
    /// its params, and the caller proved the params' bounds.
    fn check_type_static(&mut self, items: Vec<(Ty, Span)>) {
        if items.is_empty() || matches!(self.p.gx.fn_class.get(self.fid.0 as usize), Some(generics::FnClass::Instance)) {
            return;
        }
        let mut seen: Vec<Span> = Vec::new();
        for (ty, span) in items {
            let ty = self.deep(ty);
            if seen.contains(&span) {
                continue;
            }
            let spawn = self.spawn_static.contains(&span);
            self.static_dyn_inferred_ok = spawn;
            let mut err = self.static_bound_err(ty, 0);
            // Failing only on inferred object lifetimes: the borrow
            // checker proves the bound where it is used (a call's `F:
            // 'static`, an impl's where-clause, an opaque's bound).
            if err.is_some() && !spawn {
                self.static_dyn_inferred_ok = true;
                if self.static_bound_err(ty, 0).is_none() {
                    err = None;
                }
            }
            self.static_dyn_inferred_ok = false;
            if let Some((code, msg)) = err {
                seen.push(span);
                self.err(code, span, msg, "Use a type that lives for `'static` here, or add a `'static` bound to the type parameter.");
            }
        }
    }

    /// Why `t` may fail a `'static` bound, as far as lust can tell. A
    /// type parameter needs a `'static` bound in the env (L0612, rustc
    /// E0310); a dyn type needs a `'static` object lifetime, and a
    /// reference to one a written `&'static` (L0705). Other references
    /// pass: lust erases their lifetimes, a known gap shared with every
    /// non-dyn reference. A type that nests past the walk limit is
    /// L0705: nothing is proved there.
    fn static_bound_err(&mut self, t: Ty, depth: u32) -> Option<(&'static str, String)> {
        let p = self.p;
        if depth > object::LIFETIME_WALK_LIMIT {
            return Some(("L0705", "this type nests too deeply for lust to prove that it lives for `'static`".to_string()));
        }
        let in_args = |cx: &mut Self, a: ArgsId| {
            let args: Vec<GenericArg> = cx.tys.args(a).to_vec();
            args.into_iter().filter_map(|g| g.as_ty()).find_map(|e| cx.static_bound_err(e, depth + 1))
        };
        match self.tys.kind(t) {
            TyKind::Param(_) | TyKind::Projection(..) => {
                if self.env().iter().any(|pred| matches!(pred, Predicate::TypeOutlives(x, Region::Static) if *x == t)) {
                    return None;
                }
                // A `T: 'static` the signature implies: a param, the
                // return, or the impl header names a type whose Adt
                // needs it (`impl<T> S<T>` with `struct S<T: 'static>`).
                if let TyKind::Param(ParamId(i)) = self.tys.kind(t)
                    && let Some(sig) = p.regions.body_sig(p, self.fid)
                    && crate::check::outlives::param_bounds(p, Some(sig), &[]).contains(&(i, Region::Static))
                {
                    return None;
                }
                let name = match self.tys.kind(t) {
                    TyKind::Param(ParamId(i)) => p
                        .gx
                        .fn_templates
                        .get(self.fid.0 as usize)
                        .and_then(|t| t.as_ref())
                        .and_then(|t| t.generics.params.get(i as usize))
                        .map(|d| p.name(d.name).to_string()),
                    _ => None,
                };
                let name = name.unwrap_or_else(|| self.tn(t));
                Some(("L0612", format!("the type `{name}` may not live long enough: this needs it to be `'static`")))
            }
            TyKind::Dyn(_, r) => {
                let inferred = r == Region::Erased && self.static_dyn_inferred_ok;
                if !inferred && !object::dyn_is_static(p, &self.tys, t) {
                    return Some(("L0705", format!("lust cannot prove that `{}` lives for `'static`, which this bound requires", self.tn(t))));
                }
                let pr = object::principal_of(&self.tys, t)?;
                in_args(self, pr.args)
            }
            TyKind::Ref(r, _, e) => {
                if r != Region::Static && object::mentions_dyn(&self.tys, e) {
                    return Some(("L0705", format!("lust cannot prove that `{}` lives for `'static`, which this bound requires", self.tn(t))));
                }
                self.static_bound_err(e, depth + 1)
            }
            TyKind::RawPtr(_, e) | TyKind::Slice(e) | TyKind::Array(e, _) => self.static_bound_err(e, depth + 1),
            TyKind::Tuple(ts) => {
                let ts: Vec<Ty> = self.tys.tys_of(ts).to_vec();
                ts.into_iter().find_map(|e| self.static_bound_err(e, depth + 1))
            }
            // A closure's args are its captures' field types.
            TyKind::Adt(_, a) | TyKind::Closure(_, a) | TyKind::FnDef(_, a) | TyKind::Opaque(_, a) => in_args(self, a),
            _ => None,
        }
    }

    /// Binds the integer and float variables still free in a pending
    /// obligation to i32 and f64 (see `finish`).
    fn literal_fallback_in_obligations(&mut self) {
        let pending = self.obl.take();
        for ob in &pending {
            let mut tys: Vec<Ty> = Vec::new();
            let args = match ob {
                obligations::Obligation::Trait { trait_ref, .. } => trait_ref.args,
                obligations::Obligation::AssocEq { eq, .. } => {
                    tys.push(eq.ty);
                    eq.trait_args
                }
                obligations::Obligation::DynStatic { .. } => continue,
                obligations::Obligation::TypeStatic { ty, .. } | obligations::Obligation::StaticSource { ty, .. } => {
                    self.default_literal_vars(*ty);
                    continue;
                }
            };
            tys.extend(self.tys.args(args).iter().filter_map(|g| g.as_ty()));
            for t in tys {
                self.default_literal_vars(t);
            }
        }
        for ob in pending {
            self.obl.push(ob);
        }
    }

    /// `literal_fallback_in_obligations` for one type.
    fn default_literal_vars(&mut self, t: Ty) {
        let t = self.resolve(t);
        if !self.tys.flags(t).contains_infer() {
            return;
        }
        match self.tys.kind(t) {
            TyKind::Infer(v) if v.is_int() => self.bind_var(v.index(), I32),
            TyKind::Infer(v) if v.is_float() => {
                let f = self.tys.float_ty(FloatTy::F64);
                self.bind_var(v.index(), f);
            }
            TyKind::Ref(_, _, e) | TyKind::Slice(e) | TyKind::Array(e, _) | TyKind::RawPtr(_, e) => self.default_literal_vars(e),
            TyKind::Tuple(ts) => {
                for e in self.tys.tys_of(ts).to_vec() {
                    self.default_literal_vars(e);
                }
            }
            TyKind::Adt(_, a) | TyKind::Projection(_, a) | TyKind::FnDef(_, a) | TyKind::Closure(_, a) | TyKind::Opaque(_, a) => {
                for g in self.tys.args(a).to_vec() {
                    if let Some(e) = g.as_ty() {
                        self.default_literal_vars(e);
                    }
                }
            }
            _ => {}
        }
    }

    /// True when the source `x` of an unsizing coercion to a `'static`
    /// dyn type still has inference variables: whether it may hold a
    /// borrow is decided at body end, once they are bound (a value made
    /// in a closure whose type args come from the closure's return), and
    /// the coercion goes on.
    fn defer_static_source(&mut self, x: Ty, span: Span) -> bool {
        let x = self.deep(x);
        if !self.tys.flags(x).contains_infer() {
            return false;
        }
        self.obl.push(obligations::Obligation::StaticSource { ty: x, span });
        true
    }

    /// L0705 for the source of an unsizing coercion to a `'static` dyn
    /// type that may hold a borrow.
    fn static_source_err(&mut self, x: Ty, span: Span) {
        let tn = self.tn(x);
        self.err(
            "L0705",
            span,
            format!("lust cannot prove that `{tn}` lives for `'static`, which this `dyn` type requires"),
            "Use a type without references here, or drop the `'static` bound from the `dyn` type or its trait.",
        );
    }

    /// Reports the uses that need a `'static` dyn object lifetime when
    /// this body cannot give them one (see `dyn_static_clean`). Concrete
    /// instances skip it: their caller proved the bound that picked the
    /// impl, and their params are the caller's types.
    fn check_dyn_static(&mut self, mut spans: Vec<Span>) {
        if spans.is_empty() || matches!(self.p.gx.fn_class.get(self.fid.0 as usize), Some(generics::FnClass::Instance)) || self.dyn_static_clean() {
            return;
        }
        // A probe re-selection records no span; the call site does.
        if spans.iter().any(|&s| s != Span::default()) {
            spans.retain(|&s| s != Span::default());
        } else {
            spans = vec![self.f.def(&self.p.ast).name_span];
        }
        spans.dedup();
        for span in spans {
            self.err(
                "L0705",
                span,
                "this use needs a `dyn` value that lives for `'static`, and lust cannot prove that here",
                "Make the `dyn` value `'static` (`&'static dyn Tr` or `dyn Tr + 'static`), or write `impl dyn Tr + '_` for an impl that takes any lifetime.",
            );
        }
    }

    /// True when every dyn value in this body may have a `'static` object
    /// lifetime, which rustc's inference could then pick: no parameter
    /// (other than the `'static` `self` of an `impl dyn Tr` method) and
    /// no callee's declared return type holds a dyn type with an erased
    /// object lifetime, and no unsizing coercion starts from a value that
    /// may hold a borrow.
    fn dyn_static_clean(&mut self) -> bool {
        let p = self.p;
        if self.dyn_borrow_src {
            return false;
        }
        let skip_self = usize::from(self.f.def(&self.p.ast).self_param.is_some() && p.gx.static_dyn_fns.contains(&self.fid));
        if self.f.params.iter().skip(skip_self).any(|&t| object::has_erased_dyn(p, &p.tys, t)) {
            return false;
        }
        // A dyn value that flows into the return type invariantly gets
        // the caller's object lifetime (`Option<&mut dyn Tr>`).
        if object::has_erased_dyn_invariant(p, &p.tys, self.f.ret) {
            return false;
        }
        // A closure's parameter and return lifetimes are its caller's.
        for i in 0..self.closures.len() {
            let sig: Vec<Ty> = self.closures[i].inputs.iter().copied().chain([self.closures[i].output]).collect();
            for t in sig {
                let t = self.deep(t);
                if object::has_erased_dyn(p, &self.tys, t) {
                    return false;
                }
            }
        }
        for i in 0..self.out.expr_res.len() {
            let erased = match self.out.expr_res[i] {
                Res::Fn(f) | Res::Method { f, .. } | Res::TraitBin { f, .. } => object::has_erased_dyn(p, &p.tys, p.fn_info(f).ret),
                // A `dyn Fn` call returns its `Output`: the call's type.
                Res::DynMethod { owner, .. } if p.gx.lang.is_fn_family(owner) => {
                    let t = self.deep(self.out.expr_ty[i]);
                    object::has_erased_dyn(p, &self.tys, t)
                }
                Res::DynMethod { owner, slot, .. } => {
                    let info = p.gx.dyn_infos.get(&owner);
                    let m =
                        info.and_then(|info| (0..info.methods.len()).find(|&j| info.method_slot(j) == slot).map(|j| info.methods[j].def));
                    m.and_then(|d| p.gx.trait_methods.get(&d)).is_none_or(|tm| object::has_erased_dyn(p, &p.tys, tm.ret))
                }
                Res::Indirect => {
                    let e = ExprId(self.out.expr_base + i as u32);
                    let Expr::Call { callee, .. } = p.ast.expr(e) else { continue };
                    let ct = self.out.expr_ty[self.ei(*callee)];
                    let ct = self.deep(ct);
                    object::has_erased_dyn(p, &self.tys, ct)
                }
                _ => continue,
            };
            if erased {
                return false;
            }
        }
        true
    }

    /// True while any of `unbound` still names a free variable in
    /// the confirmed selection (checked through the obligation,
    /// whose args the probe bound).
    fn still_unbound(&mut self, unbound: &[ParamId], _tr: TraitRef) -> bool {
        !unbound.is_empty()
    }

    /// Proves one associated equality by normalization. False
    /// when the projection does not normalize yet. A template's
    /// rigid projection (params, no inference variable) is its own
    /// normal form: it unifies as it is.
    fn prove_assoc_eq(&mut self, eq: AssocEqData, span: Span) -> bool {
        let proj = self.tys.intern(TyKind::Projection(AssocId(eq.assoc), eq.trait_args));
        let normed = self.normalize_here(proj);
        let want = self.normalize_here(eq.ty);
        let flags = self.tys.flags(normed);
        let rigid = flags.contains_param() && !flags.contains_infer();
        if matches!(self.tys.kind(normed), TyKind::Projection(..)) && normed != want && !rigid {
            return false;
        }
        if !self.unify(normed, want) {
            let (a, b) = (self.tn(want), self.tn(normed));
            self.err(
                "L0110",
                span,
                format!("associated type mismatch: expected `{a}`, found `{b}`"),
                "Change the binding or the impl's associated type.",
            );
        }
        true
    }

    /// Proves the bindings written on an obligation that the
    /// param env answered (the impl path proves them in its
    /// probe already).
    fn prove_bindings(&mut self, tr: TraitRef, span: Span) {
        let bindings: Vec<(DefId, GenericArg)> = self.tys.bindings(tr.bindings).to_vec();
        for (assoc, ga) in bindings {
            if let GenericArg::Ty(want) = ga {
                let eq = AssocEqData { assoc, trait_args: tr.args, ty: want };
                if !self.prove_assoc_eq(eq, span) {
                    self.obl.push(obligations::Obligation::AssocEq { eq, span });
                }
            }
        }
    }

    /// The display name of a trait def, for obligation errors.
    fn trait_name(&self, def: DefId) -> String {
        self.p.gx.index.trait_record(def).map_or_else(|| "?".to_string(), |r| self.p.display_path(r.name))
    }

    /// Replaces `_` markers in one resolved written type with
    /// fresh body variables (distinct per marker).
    fn instantiate_infers(&mut self, t: Ty) -> Ty {
        self.instantiate_inner(t, &mut std::collections::HashMap::new())
    }

    fn instantiate_inner(&mut self, t: Ty, map: &mut std::collections::HashMap<u32, Ty>) -> Ty {
        match self.tys.kind(t) {
            TyKind::Infer(v) if v.index() >= generics::INFER_MARKER_BASE => {
                if let Some(&u) = map.get(&v.index()) {
                    return u;
                }
                let u = self.new_var(false);
                map.insert(v.index(), u);
                u
            }
            _ if !self.tys.flags(t).contains_infer() => t,
            TyKind::Ref(r, m, e) => {
                let e = self.instantiate_inner(e, map);
                self.tys.intern(TyKind::Ref(r, m, e))
            }
            TyKind::Slice(e) => {
                let e = self.instantiate_inner(e, map);
                self.tys.intern(TyKind::Slice(e))
            }
            TyKind::Array(e, n) => {
                let e = self.instantiate_inner(e, map);
                self.tys.intern(TyKind::Array(e, n))
            }
            TyKind::Tuple(ts) => {
                let old: Vec<Ty> = self.tys.tys_of(ts).to_vec();
                let new: Vec<Ty> = old.iter().map(|&e| self.instantiate_inner(e, map)).collect();
                let ts = self.tys.intern_tys(&new);
                self.tys.intern(TyKind::Tuple(ts))
            }
            TyKind::Adt(d, a) => {
                let a = self.instantiate_args(a, map);
                self.tys.intern(TyKind::Adt(d, a))
            }
            TyKind::Projection(d, a) => {
                let a = self.instantiate_args(a, map);
                self.tys.intern(TyKind::Projection(d, a))
            }
            TyKind::FnDef(d, a) => {
                let a = self.instantiate_args(a, map);
                self.tys.intern(TyKind::FnDef(d, a))
            }
            TyKind::RawPtr(m, e) => {
                let e = self.instantiate_inner(e, map);
                self.tys.intern(TyKind::RawPtr(m, e))
            }
            TyKind::Closure(d, a) => {
                let a = self.instantiate_args(a, map);
                self.tys.intern(TyKind::Closure(d, a))
            }
            TyKind::Opaque(d, a) => {
                let a = self.instantiate_args(a, map);
                self.tys.intern(TyKind::Opaque(d, a))
            }
            TyKind::FnPtr(sig) => {
                let b = self.tys.sig(sig);
                let old: Vec<Ty> = self.tys.tys_of(b.value.inputs).to_vec();
                let new: Vec<Ty> = old.iter().map(|&e| self.instantiate_inner(e, map)).collect();
                let inputs = self.tys.intern_tys(&new);
                let output = self.instantiate_inner(b.value.output, map);
                let sig = self.tys.intern_sig(Binder { count: b.count, value: FnSig { inputs, output, ..b.value } });
                self.tys.intern(TyKind::FnPtr(sig))
            }
            TyKind::Dyn(b, r) => {
                let mut bounds = self.tys.dyn_bounds(b).clone();
                if let Some(pr) = &mut bounds.principal {
                    pr.value.args = self.instantiate_args(pr.value.args, map);
                    let old: Vec<(DefId, GenericArg)> = self.tys.bindings(pr.value.bindings).to_vec();
                    if !old.is_empty() {
                        let new: Vec<(DefId, GenericArg)> = old
                            .into_iter()
                            .map(|(d, g)| match g {
                                GenericArg::Ty(t) => (d, GenericArg::Ty(self.instantiate_inner(t, map))),
                                g => (d, g),
                            })
                            .collect();
                        pr.value.bindings = self.tys.intern_bindings(&new);
                    }
                }
                let b = self.tys.intern_dyn_bounds(bounds);
                self.tys.intern(TyKind::Dyn(b, r))
            }
            _ => t,
        }
    }

    fn instantiate_args(&mut self, a: ArgsId, map: &mut std::collections::HashMap<u32, Ty>) -> ArgsId {
        let old: Vec<GenericArg> = self.tys.args(a).to_vec();
        let new: Vec<GenericArg> = old
            .iter()
            .map(|&g| match g {
                GenericArg::Ty(e) => GenericArg::Ty(self.instantiate_inner(e, map)),
                other => other,
            })
            .collect();
        self.tys.intern_args(&new)
    }

    // ---------- Inference ----------

    fn new_var(&mut self, int: bool) -> Ty {
        self.vars.push(Var { bound: None });
        let id = self.vars.len() as u32 - 1;
        self.tys.intern(TyKind::Infer(InferId(id, if int { InferKind::Int } else { InferKind::General })))
    }
    /// A fresh float-literal variable: binds only to a float type,
    /// defaults to f64 at body end.
    fn new_float_var(&mut self) -> Ty {
        self.vars.push(Var { bound: None });
        let id = self.vars.len() as u32 - 1;
        self.tys.intern(TyKind::Infer(InferId(id, InferKind::Float)))
    }
    /// Records `t` as a diverging variable when it is an unbound general
    /// one: a `!` value was coerced into it (see `diverging`).
    fn mark_diverging(&mut self, t: Ty) {
        if let TyKind::Infer(v) = self.kind(t)
            && !v.is_int()
            && !v.is_float()
        {
            self.diverging.push(v.index());
        }
    }
    /// True when the unbound variable `v` is the root of a diverging
    /// variable, so it falls back to `!` and needs no annotation.
    fn is_diverging_root(&self, v: u32) -> bool {
        self.diverging.iter().any(|&d| self.var_root(d) == Some(v))
    }
    /// The unbound variable that variable `v` resolves to, if any.
    fn var_root(&self, mut v: u32) -> Option<u32> {
        loop {
            match self.vars[v as usize].bound {
                None => return Some(v),
                Some(t) => match self.tys.kind(t) {
                    TyKind::Infer(w) => v = w.index(),
                    _ => return None,
                },
            }
        }
    }
    /// Follows variable bindings at the top level only.
    fn resolve(&self, mut t: Ty) -> Ty {
        while let TyKind::Infer(v) = self.tys.kind(t) {
            match self.vars[v.index() as usize].bound {
                Some(b) => t = b,
                None => return t,
            }
        }
        t
    }
    fn kind(&self, t: Ty) -> TyKind {
        self.tys.kind(self.resolve(t))
    }
    /// Fully resolves a type, interning new structural types as needed. Unbound integer
    /// variables become i32.
    fn zonk(&mut self, t: Ty) -> Ty {
        let z = self.rebuild(t, true);
        let z = if self.iter_arg_map.is_empty() { z } else { opaque::replace_iter_args(&mut self.tys, z, &self.iter_arg_map) };
        if self.closure_map.is_empty() {
            return z;
        }
        opaque::map_closure_defs(&mut self.tys, z, &self.closure_map)
    }
    /// Resolves variables at every depth, keeping unbound ones. Trait queries need this.
    fn deep(&mut self, t: Ty) -> Ty {
        self.rebuild(t, false)
    }
    /// The shared walk of `zonk` and `deep` over the structural kinds a body can form.
    /// A type with no inference variable anywhere (the cached flag) is returned as is,
    /// so the common signature types cost one flag read. With `zonk`, an unbound
    /// variable is defaulted (integer variables to i32, others to the error type).
    fn rebuild(&mut self, t: Ty, zonk: bool) -> Ty {
        let t = self.resolve(t);
        match self.tys.kind(t) {
            TyKind::Infer(v) => {
                if !zonk {
                    return t;
                }
                let d = if v.is_int() {
                    I32
                } else if v.is_float() {
                    self.tys.float_ty(FloatTy::F64)
                } else {
                    ERROR
                };
                self.bind_var(v.index(), d);
                d
            }
            TyKind::Array(e, n) if matches!(self.tys.const_kind(n), ConstKind::Infer(id) if id >= generics::INFER_MARKER_BASE) => {
                let e = self.rebuild(e, zonk);
                let n = self.resolve_const(n);
                self.tys.intern(TyKind::Array(e, n))
            }
            _ if !self.tys.flags(t).contains_infer() => t,
            TyKind::Ref(r, m, e) => {
                let e = self.rebuild(e, zonk);
                self.tys.intern(TyKind::Ref(r, m, e))
            }
            TyKind::Slice(e) => {
                let e = self.rebuild(e, zonk);
                self.tys.intern(TyKind::Slice(e))
            }
            TyKind::Array(e, n) => {
                let e = self.rebuild(e, zonk);
                let n = self.resolve_const(n);
                self.tys.intern(TyKind::Array(e, n))
            }
            TyKind::Tuple(ts) => {
                let old: Vec<Ty> = self.tys.tys_of(ts).to_vec();
                let new: Vec<Ty> = old.iter().map(|&e| self.rebuild(e, zonk)).collect();
                let ts = self.tys.intern_tys(&new);
                self.tys.intern(TyKind::Tuple(ts))
            }
            TyKind::Adt(d, a) => {
                // Rebuild each type arg in place: the new list is allocated only
                // when some arg actually changes (the common deep() case does not).
                let n = self.tys.args(a).len();
                let mut new: Option<Vec<GenericArg>> = None;
                for i in 0..n {
                    let g = self.tys.args(a)[i];
                    let g2 = match g {
                        GenericArg::Ty(e) => GenericArg::Ty(self.rebuild(e, zonk)),
                        GenericArg::Const(c) => GenericArg::Const(self.resolve_const(c)),
                        other => other,
                    };
                    if g2 != g {
                        let v = new.get_or_insert_with(|| self.tys.args(a).to_vec());
                        v[i] = g2;
                    } else if let Some(v) = &mut new {
                        v[i] = g2;
                    }
                }
                match new {
                    None => t,
                    Some(v) => {
                        let a = self.tys.intern_args(&v);
                        self.tys.intern(TyKind::Adt(d, a))
                    }
                }
            }
            TyKind::RawPtr(m, e) => {
                let e = self.rebuild(e, zonk);
                self.tys.intern(TyKind::RawPtr(m, e))
            }
            TyKind::Projection(d, a) => {
                let a = self.rebuild_args(a, zonk);
                self.tys.intern(TyKind::Projection(d, a))
            }
            TyKind::FnDef(d, a) => {
                let a = self.rebuild_args(a, zonk);
                self.tys.intern(TyKind::FnDef(d, a))
            }
            TyKind::Closure(d, a) => {
                let a = self.rebuild_args(a, zonk);
                self.tys.intern(TyKind::Closure(d, a))
            }
            TyKind::Opaque(d, a) => {
                let a = self.rebuild_args(a, zonk);
                self.tys.intern(TyKind::Opaque(d, a))
            }
            TyKind::Dyn(b, r) => {
                let mut bounds = self.tys.dyn_bounds(b).clone();
                if let Some(pr) = &mut bounds.principal {
                    pr.value.args = self.rebuild_args(pr.value.args, zonk);
                    let old: Vec<(DefId, GenericArg)> = self.tys.bindings(pr.value.bindings).to_vec();
                    if !old.is_empty() {
                        let new: Vec<(DefId, GenericArg)> = old
                            .into_iter()
                            .map(|(d, g)| match g {
                                GenericArg::Ty(t) => (d, GenericArg::Ty(self.rebuild(t, zonk))),
                                g => (d, g),
                            })
                            .collect();
                        pr.value.bindings = self.tys.intern_bindings(&new);
                    }
                }
                let b = self.tys.intern_dyn_bounds(bounds);
                self.tys.intern(TyKind::Dyn(b, r))
            }
            TyKind::FnPtr(sig) => {
                let b = self.tys.sig(sig);
                let old: Vec<Ty> = self.tys.tys_of(b.value.inputs).to_vec();
                let new: Vec<Ty> = old.iter().map(|&e| self.rebuild(e, zonk)).collect();
                let inputs = self.tys.intern_tys(&new);
                let output = self.rebuild(b.value.output, zonk);
                let sig = self.tys.intern_sig(Binder { count: b.count, value: FnSig { inputs, output, ..b.value } });
                self.tys.intern(TyKind::FnPtr(sig))
            }
            _ => t,
        }
    }

    fn rebuild_args(&mut self, a: ArgsId, zonk: bool) -> ArgsId {
        let old: Vec<GenericArg> = self.tys.args(a).to_vec();
        let new: Vec<GenericArg> = old
            .iter()
            .map(|&g| match g {
                GenericArg::Ty(e) => GenericArg::Ty(self.rebuild(e, zonk)),
                GenericArg::Const(c) => GenericArg::Const(self.resolve_const(c)),
                other => other,
            })
            .collect();
        self.tys.intern_args(&new)
    }

    /// `t` resolved when it is a projection whose args hold no
    /// unbound inference variable (`unify` normalizes it then).
    fn closed_projection(&mut self, t: Ty) -> Option<Ty> {
        if !matches!(self.tys.kind(t), TyKind::Projection(..)) {
            return None;
        }
        if !self.tys.flags(t).contains_infer() {
            return Some(t);
        }
        let d = self.deep(t);
        (!self.tys.flags(d).contains_infer()).then_some(d)
    }

    fn unify(&mut self, a: Ty, b: Ty) -> bool {
        let (a, b) = (self.resolve(a), self.resolve(b));
        if a == b {
            return true;
        }
        // Inside its defining body an `impl Trait` is its hidden type (a
        // recursive call returns it too), as in rustc.
        if !self.own_opaques.is_empty() {
            let (ma, mb) = (self.map_own_opaque(a), self.map_own_opaque(b));
            if ma != a || mb != b {
                return self.unify(ma, mb);
            }
        }
        // A projection that normalizes now unifies through its
        // normal form (section 2.5). Only when its args hold no
        // inference variable once resolved (a late target bound
        // since: `let r = x.try_into(); let r: Result<u8, E> = r;`):
        // selection inside probes already handles the open case, and
        // normalizing there would loop.
        if !self.in_norm {
            let na = self.closed_projection(a).map_or(a, |a| {
                self.in_norm = true;
                let n = self.normalize_here(a);
                self.in_norm = false;
                n
            });
            let nb = self.closed_projection(b).map_or(b, |b| {
                self.in_norm = true;
                let n = self.normalize_here(b);
                self.in_norm = false;
                n
            });
            if na != a || nb != b {
                return self.unify(na, nb);
            }
        }
        match (self.tys.kind(a), self.tys.kind(b)) {
            (TyKind::Error, _) | (_, TyKind::Error) => true,
            (TyKind::Infer(v), TyKind::Infer(w)) => {
                // Bind the general variable to the constrained one, so
                // the int or float constraint survives. An int variable
                // never unifies with a float variable.
                if (v.is_int() && w.is_float()) || (v.is_float() && w.is_int()) {
                    return false;
                }
                if (v.is_int() || v.is_float()) && !w.is_int() && !w.is_float() {
                    self.bind_var(w.index(), a);
                } else {
                    self.bind_var(v.index(), b);
                }
                true
            }
            (TyKind::Infer(v), k) | (k, TyKind::Infer(v)) => {
                if v.is_int() && !matches!(k, TyKind::Int(_)) {
                    return false;
                }
                if v.is_float() && !matches!(k, TyKind::Float(_)) {
                    return false;
                }
                let other = if matches!(self.tys.kind(a), TyKind::Infer(_)) { b } else { a };
                if self.occurs(v.index(), other) {
                    return false;
                }
                self.bind_var(v.index(), other);
                true
            }
            // Regions do not take part in this equality: every region is `Erased`
            // until milestone 6 gives them their own solver (ARCH 5).
            (TyKind::Ref(_, m, x), TyKind::Ref(_, n, y)) => m == n && self.unify(x, y),
            (TyKind::Adt(d, x), TyKind::Adt(e, y)) => d == e && self.unify_args(x, y),
            (TyKind::Tuple(x), TyKind::Tuple(y)) => {
                self.tys.tys_of(x).len() == self.tys.tys_of(y).len()
                    && (0..self.tys.tys_of(x).len()).all(|i| {
                        let (u, v) = (self.tys.tys_of(x)[i], self.tys.tys_of(y)[i]);
                        self.unify(u, v)
                    })
            }
            (TyKind::Slice(x), TyKind::Slice(y)) => self.unify(x, y),
            (TyKind::Array(x, n), TyKind::Array(y, m)) => self.unify_const(n, m) && self.unify(x, y),
            (TyKind::RawPtr(m, x), TyKind::RawPtr(n, y)) => m == n && self.unify(x, y),
            (TyKind::Projection(d, x), TyKind::Projection(e, y)) => d == e && self.unify_args(x, y),
            (TyKind::FnDef(d, x), TyKind::FnDef(e, y)) => d == e && self.unify_args(x, y),
            (TyKind::Closure(d, x), TyKind::Closure(e, y)) => d == e && self.unify_args(x, y),
            (TyKind::Opaque(d, x), TyKind::Opaque(e, y)) => d == e && self.unify_args(x, y),
            // Fn pointers unify part by part. Their binders hold only
            // elided (late-bound) regions, which are erased here.
            (TyKind::FnPtr(x), TyKind::FnPtr(y)) => {
                let (sx, sy) = (self.tys.sig(x).value, self.tys.sig(y).value);
                let n = self.tys.tys_of(sx.inputs).len();
                if sx.is_unsafe != sy.is_unsafe || sx.extern_c != sy.extern_c || n != self.tys.tys_of(sy.inputs).len() {
                    return false;
                }
                for i in 0..n {
                    let (u, v) = (self.tys.tys_of(sx.inputs)[i], self.tys.tys_of(sy.inputs)[i]);
                    if !self.unify(u, v) {
                        return false;
                    }
                }
                self.unify(sx.output, sy.output)
            }
            // Two dyn types are equal when the principals and the written
            // auto traits are; regions are erased here, as for references.
            (TyKind::Dyn(x, _), TyKind::Dyn(y, _)) => {
                let (bx, by) = (self.tys.dyn_bounds(x).clone(), self.tys.dyn_bounds(y).clone());
                match (bx.principal, by.principal) {
                    (Some(px), Some(py)) => {
                        bx.auto == by.auto
                            && px.value.def == py.value.def
                            && self.unify_args(px.value.args, py.value.args)
                            && self.unify_bindings(px.value.bindings, py.value.bindings)
                    }
                    (None, None) => bx.auto == by.auto,
                    _ => false,
                }
            }
            _ => false,
        }
    }
    /// Two binding lists (`Output = R` of a `dyn Fn`) unify when they
    /// bind the same items, in order, to types that unify.
    fn unify_bindings(&mut self, a: BindingsId, b: BindingsId) -> bool {
        if a == b {
            return true;
        }
        let (a, b) = (self.tys.bindings(a).to_vec(), self.tys.bindings(b).to_vec());
        a.len() == b.len()
            && a.iter().zip(&b).all(|(&(da, ga), &(db, gb))| {
                da == db
                    && match (ga, gb) {
                        (GenericArg::Ty(x), GenericArg::Ty(y)) => self.unify(x, y),
                        (x, y) => x == y,
                    }
            })
    }
    /// Two generic argument lists unify element by element, in declared order.
    /// Type args unify; lifetime and const args must already be equal. Indexed
    /// reads only, so the common one-element `Vec<T>` case allocates nothing.
    fn unify_args(&mut self, a: ArgsId, b: ArgsId) -> bool {
        let n = self.tys.args(a).len();
        if n != self.tys.args(b).len() {
            // An Adt in a dyn's `Fn*` sugar may carry its late-bound
            // lifetimes (`Lifetime(DYN_LATE)`, R11); regions take no part.
            let has_lt = |tys: &Tys, x: ArgsId| tys.args(x).iter().any(|g| matches!(g, GenericArg::Lifetime(_)));
            if !has_lt(&self.tys, a) && !has_lt(&self.tys, b) {
                return false;
            }
            let strip = |tys: &Tys, x: ArgsId| -> Vec<GenericArg> { tys.args(x).iter().copied().filter(|g| !matches!(g, GenericArg::Lifetime(_))).collect() };
            let (xs, ys) = (strip(&self.tys, a), strip(&self.tys, b));
            return xs.len() == ys.len()
                && xs.into_iter().zip(ys).all(|(x, y)| match (x, y) {
                    (GenericArg::Ty(x), GenericArg::Ty(y)) => self.unify(x, y),
                    (GenericArg::Const(x), GenericArg::Const(y)) => self.unify_const(x, y),
                    (x, y) => x == y,
                });
        }
        for i in 0..n {
            let ok = match (self.tys.args(a)[i], self.tys.args(b)[i]) {
                (GenericArg::Ty(x), GenericArg::Ty(y)) => self.unify(x, y),
                (GenericArg::Const(x), GenericArg::Const(y)) => self.unify_const(x, y),
                (GenericArg::Lifetime(_), GenericArg::Lifetime(_)) => true,
                (x, y) => x == y,
            };
            if !ok {
                return false;
            }
        }
        true
    }
    fn occurs(&self, v: u32, t: Ty) -> bool {
        // A type with no inference variable holds none: without this a
        // type that doubles its args per level (`((T, T), (T, T))`)
        // makes the walk exponential.
        if !self.tys.flags(t).contains_infer() {
            return false;
        }
        match self.kind(t) {
            TyKind::Infer(w) => w.index() == v,
            TyKind::Ref(_, _, e) | TyKind::RawPtr(_, e) | TyKind::Slice(e) | TyKind::Array(e, _) => self.occurs(v, e),
            TyKind::Adt(_, a) => (0..self.tys.args(a).len()).any(|i| match self.tys.args(a)[i].as_ty() {
                Some(e) => self.occurs(v, e),
                None => false,
            }),
            TyKind::Tuple(ts) => {
                let n = self.tys.tys_of(ts).len();
                (0..n).any(|i| {
                    let e = self.tys.tys_of(ts)[i];
                    self.occurs(v, e)
                })
            }
            TyKind::Dyn(b, _) => match self.tys.dyn_bounds(b).principal {
                Some(pr) => self.tys.args(pr.value.args).to_vec().into_iter().any(|g| g.as_ty().is_some_and(|e| self.occurs(v, e))),
                None => false,
            },
            TyKind::FnPtr(sig) => {
                let s = self.tys.sig(sig).value;
                self.tys.tys_of(s.inputs).to_vec().into_iter().chain([s.output]).any(|e| self.occurs(v, e))
            }
            TyKind::FnDef(_, a) | TyKind::Closure(_, a) | TyKind::Opaque(_, a) | TyKind::Projection(_, a) => {
                self.tys.args(a).to_vec().into_iter().any(|g| g.as_ty().is_some_and(|e| self.occurs(v, e)))
            }
            _ => false,
        }
    }
    /// True when `field` is the unsized field of the newtype `outer`,
    /// directly or through nested newtypes (W-SHIM coercion in shipped
    /// std source).
    fn newtype_field_of(&mut self, outer: Ty, field: Ty) -> bool {
        let mut t = outer;
        while let TyKind::Adt(d, a) = self.kind(t) {
            let Some(f) = self.tys.unsized_field(d) else { return false };
            // A generic newtype's field under the outer type's args.
            let f = if self.tys.args(a).is_empty() {
                f
            } else {
                let args: Vec<GenericArg> = self.tys.args(a).to_vec();
                subst(&mut self.tys, f, &args)
            };
            if f == field || self.deep(f) == self.deep(field) {
                return true;
            }
            t = f;
        }
        false
    }
    fn mismatch(&mut self, span: Span, expected: Ty, found: Ty) {
        let (e, f) = (self.tn(expected), self.tn(found));
        let fix = if e == "&str" && f == "String" {
            "Borrow it: write `&value` or `value.as_str()`.".to_string()
        } else if e == "String" && f == "&str" {
            "Convert it: write `value.to_string()`.".to_string()
        } else if f.starts_with('&') && e == f[1..] {
            "Dereference it with `*value`, or clone it if the type is not Copy.".to_string()
        } else if e.starts_with('&') && f == e[1..] {
            "Borrow it with `&value`.".to_string()
        } else {
            format!("Change the value to type `{e}`, or change the expected type.")
        };
        if int_shape(&e).is_some() && int_shape(&f).is_some() {
            let fix = format!("Cast it: write `(value) as {e}`.");
            self.err_cast("L0110", span, format!("mismatched types: expected `{e}`, found `{f}`"), fix, span, &f, &e);
            return;
        }
        self.err("L0110", span, format!("mismatched types: expected `{e}`, found `{f}`"), fix);
    }
    /// Checks `found` against `expected` at a coercion site. Records the coercion on `e`.
    fn coerce_at(&mut self, found: Ty, expected: Ty, span: Span, e: Option<ExprId>) -> bool {
        // ARCH 2.4 run point: the obligation queue runs at coercion sites.
        self.run_obligations(false);
        let (fk, ek) = (self.kind(found), self.kind(expected));
        if fk == TyKind::Never {
            self.mark_diverging(expected);
            return true;
        }
        // Count reference layers, for deref coercions.
        let depth = |cx: &Self, mut t: Ty| {
            let mut n = 0u8;
            while let TyKind::Ref(_, _, inner) = cx.kind(t) {
                t = inner;
                n += 1;
            }
            (n, t)
        };
        let (fd, fbase) = depth(self, found);
        let (ed, _) = depth(self, expected);
        // The mutability a deref coercion through a smart pointer
        // may hand out: the reference directly on a `Box` bounds
        // it; an `Rc` never hands out `&mut`; a guard does when it
        // implements `DerefMut` (`RefMut`, `MutexGuard`, the write
        // guard) and the reference on it is `&mut`.
        let box_ref_mut = |cx: &Self| -> Option<bool> {
            let mut t = found;
            loop {
                match cx.kind(t) {
                    TyKind::Ref(_, m, inner) => {
                        let inner = cx.resolve(inner);
                        if cx.tys.boxed_elem(inner).is_some() {
                            return Some(m.is_mut());
                        }
                        if cx.tys.rc_elem(inner).is_some() {
                            return Some(false);
                        }
                        if let Some((_, gm)) = cx.tys.guard_elem(inner) {
                            return Some(m.is_mut() && gm);
                        }
                        t = inner;
                    }
                    _ => return None,
                }
            }
        };
        // A reference to a dyn type is an unsizing target: rustc commits
        // to unsizing there and never tries a deref coercion (`&&S` to
        // `&dyn Tr` needs `&S: Tr`), so neither does this.
        let dyn_target = matches!(ek, TyKind::Ref(_, _, y) if matches!(self.kind(y), TyKind::Dyn(..)));
        let c = match (fk, ek) {
            // A reference or thin raw pointer unsizes to a fat raw pointer
            // (tf-fatptr): `*const [T; N]` to `*const [T]` and `*const S`
            // to `*const dyn Tr`, by the rules of the reference forms.
            (TyKind::Ref(_, fm, x) | TyKind::RawPtr(fm, x), TyKind::RawPtr(em, y))
                if (!em.is_mut() || fm.is_mut()) && {
                    let (x, y) = (self.deep(x), self.deep(y));
                    match (self.kind(x), self.kind(y)) {
                        (TyKind::Array(..), TyKind::Slice(_)) => true,
                        // An upcast (`*const dyn Sub` to `*const dyn Tr`).
                        (TyKind::Dyn(..), TyKind::Dyn(..)) => match (object::principal_of(&self.tys, x), object::principal_of(&self.tys, y)) {
                            (Some(a), Some(b)) => a.def != b.def,
                            _ => false,
                        },
                        (TyKind::Dyn(..), _) => false,
                        (TyKind::Infer(v), _) if !v.is_int() && !v.is_float() => false,
                        (_, TyKind::Dyn(..)) => true,
                        _ => false,
                    }
                } =>
            {
                let (x, y) = (self.deep(x), self.deep(y));
                if let (TyKind::Array(xe, _), TyKind::Slice(ye)) = (self.kind(x), self.kind(y)) {
                    if !self.unify(xe, ye) {
                        self.mismatch(span, expected, found);
                        return false;
                    }
                    Coerce::Unsize(expected)
                } else {
                    match self.unsize_coercion(x, y, found, expected, span, e) {
                        Some(c) => c,
                        None => return false,
                    }
                }
            }
            // A reference to a raw pointer, and `*mut T` to `*const T`
            // (w-cinterop): safe coercions in Rust; the address stays.
            (TyKind::Ref(_, fm, x), TyKind::RawPtr(em, y)) if (!em.is_mut() || fm.is_mut()) && self.unify(x, y) => {
                Coerce::RefToPtr(expected)
            }
            (TyKind::RawPtr(Mut::Mut, x), TyKind::RawPtr(Mut::Shared, y)) if self.unify(x, y) => Coerce::RefToPtr(expected),
            (TyKind::Ref(..), TyKind::Ref(_, Mut::Shared, s))
                if self.kind(s) == TyKind::Str && self.tys.is_string_ty(self.resolve(fbase)) =>
            {
                Coerce::StrFromString
            }
            // `&Cow<B>` to `&B` (W-STD-B), when the types do not already
            // unify (an exact match wins, as in the arms below).
            (TyKind::Ref(..), TyKind::Ref(_, Mut::Shared, y))
                if !dyn_target
                    && ed == 1
                    && crate::check::collect::cow_arg(&self.tys, self.resolve(fbase)).is_some()
                    && {
                        let snap_vars = self.snapshot_vars();
                        let obl_len = self.obl_len();
                        let exact = self.unify(found, expected);
                        self.rollback_vars(snap_vars);
                        self.obl_truncate(obl_len);
                        !exact
                    }
                    && crate::check::collect::cow_arg(&self.tys, self.resolve(fbase)).is_some_and(|b| self.unify(b, y)) =>
            {
                Coerce::CowDeref(fd, expected)
            }
            (TyKind::Ref(..), TyKind::Ref(_, Mut::Shared, s))
                if self.kind(s) == TyKind::Str
                    && self.tys.smart_elem(self.resolve(fbase)).is_some_and(|e| self.tys.is_string_ty(self.resolve(e))) =>
            {
                Coerce::StrFromString
            }
            // Not for a dyn target: rustc commits to unsizing there
            // (`&Box<S>` to `&dyn Tr` needs `Box<S>: Tr`, E0277).
            (TyKind::Ref(..), TyKind::Ref(_, em, y))
                if ed == 1
                    && !dyn_target
                    && box_ref_mut(self).is_some_and(|bm| !em.is_mut() || bm)
                    && {
                        // An exact match wins over a deref
                        // coercion (as in the `Deref` arm below):
                        // `&Rc<T>` against `&Rc<T>` must not
                        // become `&T` by binding through the box.
                        let snap_vars = self.snapshot_vars();
                        let obl_len = self.obl_len();
                        let exact = self.unify(found, expected);
                        self.rollback_vars(snap_vars);
                        self.obl_truncate(obl_len);
                        !exact
                    }
                    && self.tys.smart_elem(self.resolve(fbase)).is_some_and(|e| self.unify(e, y)) =>
            {
                Coerce::BoxToRef(fd + 1, em.is_mut())
            }
            (TyKind::Ref(..), TyKind::Ref(_, Mut::Shared, _))
                if !dyn_target && fd > ed && {
                    // An exact structural match wins over a deref
                    // coercion: `&&S` against `&T` binds `T = &S`,
                    // never `T = S` through `*`. rustc coerces only
                    // when the types do not already unify, so try
                    // the plain unify first (rolled back; the
                    // fallback arm redoes it for real).
                    let snap_vars = self.snapshot_vars();
                    let obl_len = self.obl_len();
                    let exact = self.unify(found, expected);
                    self.rollback_vars(snap_vars);
                    self.obl_truncate(obl_len);
                    !exact && {
                        let mut t = found;
                        for _ in 0..fd - ed {
                            if let TyKind::Ref(_, _, inner) = self.kind(t) {
                                t = inner;
                            }
                        }
                        matches!(self.kind(t), TyKind::Ref(_, Mut::Shared, _)) && self.unify(t, expected)
                    }
                } =>
            {
                let mut t = found;
                for _ in 0..fd - ed {
                    if let TyKind::Ref(_, _, inner) = self.kind(t) {
                        t = inner;
                    }
                }
                self.dyn_regions(t, expected, false, span);
                Coerce::Deref(fd - ed)
            }
            // `&&mut T` to `&T` and `&mut &mut T` to `&mut T` (rustc's
            // deref coercion through an inner `&mut`): a reborrow of the
            // pointee, `&**x` or `&mut **x`, never a copy of the inner
            // `&mut`. A `&mut` target needs every reference on the way to
            // be `&mut` (rustc E0596 otherwise, which unify then reports).
            (TyKind::Ref(_, fm, _), TyKind::Ref(_, em, _))
                if !dyn_target
                    && fd > ed
                    && (!em.is_mut() || fm.is_mut())
                    && {
                        let snap_vars = self.snapshot_vars();
                        let obl_len = self.obl_len();
                        let exact = self.unify(found, expected);
                        self.rollback_vars(snap_vars);
                        self.obl_truncate(obl_len);
                        !exact && {
                            // The refs peeled off, all `&mut` for a `&mut` target.
                            let mut t = found;
                            let mut all_mut = true;
                            for _ in 0..fd - ed {
                                if let TyKind::Ref(_, m, inner) = self.kind(t) {
                                    all_mut &= m.is_mut();
                                    t = inner;
                                }
                            }
                            matches!(self.kind(t), TyKind::Ref(_, Mut::Mut, _)) && (!em.is_mut() || all_mut) && {
                                let TyKind::Ref(_, _, x) = self.kind(t) else { unreachable!() };
                                let TyKind::Ref(_, _, y) = self.kind(expected) else { unreachable!() };
                                self.unify(x, y)
                            }
                        }
                    } =>
            {
                Coerce::BoxToRef(fd - ed + 1, em.is_mut())
            }
            // A dyn target takes the unsizing arm below even when the
            // types already unify: it checks the object lifetimes.
            (TyKind::Ref(_, Mut::Mut, x), TyKind::Ref(_, Mut::Shared, y)) if !dyn_target && self.unify(x, y) => {
                self.dyn_regions(x, y, false, span);
                Coerce::MutToShared
            }
            (TyKind::Ref(_, Mut::Mut, x), TyKind::Ref(_, Mut::Mut, y)) if !dyn_target && self.unify(x, y) => {
                self.dyn_regions(x, y, true, span);
                Coerce::Reborrow
            }
            (TyKind::Ref(_, fm, x), TyKind::Ref(_, em, y))
                if matches!(self.kind(y), TyKind::Slice(_))
                    && (!em.is_mut() || fm.is_mut())
                    && match self.kind(x) {
                        TyKind::Array(xe, _) => match self.kind(y) {
                            TyKind::Slice(ye) => self.unify(xe, ye),
                            _ => false,
                        },
                        _ => false,
                    } =>
            {
                if let (TyKind::Array(xe, _), TyKind::Slice(ye)) = (self.kind(x), self.kind(y)) {
                    self.dyn_regions(xe, ye, em.is_mut(), span);
                }
                Coerce::SliceFromArray(em.is_mut())
            }
            (TyKind::Ref(_, fm, x), TyKind::Ref(_, em, y))
                if matches!(self.kind(y), TyKind::Slice(_))
                    && (!em.is_mut() || fm.is_mut())
                    && match self
                        .tys
                        .vec_elem(self.resolve(x))
                        .or_else(|| self.tys.smart_elem(self.resolve(x)).and_then(|b| self.tys.vec_elem(self.resolve(b))))
                        .or_else(|| self.shared_ref_vec_elem(x, em))
                    {
                        Some(xe) => match self.kind(y) {
                            TyKind::Slice(ye) => self.unify(xe, ye),
                            _ => false,
                        },
                        None => false,
                    } =>
            {
                if let (Some(xe), TyKind::Slice(ye)) = (self.tys.vec_elem(self.resolve(x)), self.kind(y)) {
                    self.dyn_regions(xe, ye, em.is_mut(), span);
                }
                Coerce::SliceFromVec(em.is_mut())
            }
            // Shipped std source only (W-SHIM): a reference to the field
            // of an unsized newtype is a reference to the newtype, as
            // std's pointer casts make it (`&OsStr` to `&Path`, `&[u8]`
            // to `&OsStr`). Both have one C form, so the value stays.
            // Adapter crates are shipped source too (the jemalloc-ctl
            // adapter's `Name([u8])` needs the same cast).
            (TyKind::Ref(_, fm, x), TyKind::Ref(_, em, y))
                if (!em.is_mut() || fm.is_mut())
                    && (self.p.shipped_crate_at(span) == Some(crate::ty::lang::ShippedCrate::Std) || self.p.adapter_at(span).is_some())
                    && self.newtype_field_of(self.resolve(y), self.resolve(x)) =>
            {
                if let Some(e) = e {
                    self.set(e, expected);
                }
                Coerce::None
            }
            // A plain fn item coerces to a function pointer with the
            // same signature (the value materializes as its trampoline).
            (TyKind::FnDef(..), TyKind::FnPtr(_)) if self.is_fn_item(found) && !self.is_prim_item(found) && self.fn_item_ptr_unifies(found, expected) => {
                // A path to the fn gets the pointer type, so lowering
                // materializes the trampoline value for it. Any other
                // expression keeps its zero-sized item type, and the
                // coercion builds the trampoline from that type.
                match e {
                    Some(e)
                        if !matches!(self.p.ast.expr(e), Expr::Path(_) | Expr::QPath { .. })
                            || !matches!(self.out.expr_res[self.ei(e)], Res::Fn(_)) =>
                    {
                        Coerce::ReifyFn(expected)
                    }
                    Some(e) => {
                        self.set(e, expected);
                        Coerce::None
                    }
                    None => Coerce::None,
                }
            }
            // A tuple struct or variant constructor (`JsxEmit`, `Some`,
            // `Ok`) coerces to a fn pointer with its signature: codegen
            // writes a small C fn that builds the value (`Rvalue::ItemShim`).
            // Only for a pointer type with no lifetime in it: such a
            // constructor has no region signature for borrowck to prove.
            (TyKind::FnDef(..), TyKind::FnPtr(_)) if e.is_some() && self.is_ctor_item(found) && self.fn_item_ptr_unifies(found, expected) => {
                if !self.is_instance_check() && self.fn_ptr_has_region(expected) {
                    self.err(
                        "L0203",
                        span,
                        "this constructor cannot become a fn pointer type with references or lifetimes yet",
                        "Wrap it in a closure, such as `|x| Ctor(x)`.",
                    );
                }
                Coerce::ReifyFn(expected)
            }
            // A primitive builtin method of an integer type (`u32::isqrt`),
            // or one that cannot panic (`<[T]>::len`): codegen writes its fn
            // too. Its lifetimes are all late-bound and elided, so any input
            // lifetimes are fine, but an output lifetime needs the elision
            // proof lust does not have yet.
            (TyKind::FnDef(..), TyKind::FnPtr(_))
                if e.is_some() && (self.is_int_prim_item(found) || self.is_nopanic_prim_item(found)) && self.fn_item_ptr_unifies(found, expected) =>
            {
                let out_region = match self.kind(expected) {
                    TyKind::FnPtr(s) => {
                        let o = self.tys.sig(s).value.output;
                        let fp = self.fn_ptr_ty(&[], o);
                        self.fn_ptr_has_region(fp)
                    }
                    _ => false,
                };
                if out_region && !self.is_instance_check() {
                    self.err(
                        "L0203",
                        span,
                        "this builtin method cannot become a fn pointer type whose return type has a lifetime yet",
                        "Wrap it in a closure.",
                    );
                }
                Coerce::ReifyFn(expected)
            }
            // A closure value that captures nothing coerces to a fn
            // pointer with its signature: lowering reads the zero-sized
            // value, then takes its body fn's trampoline.
            (TyKind::Closure(..), TyKind::FnPtr(_)) if e.is_some() && self.closure_ptr_unifies(found, expected) => Coerce::ReifyFn(expected),
            (TyKind::Ref(_, fm, x), TyKind::Ref(_, em, y))
                if dyn_target && (!em.is_mut() || fm.is_mut()) && !matches!(self.kind(x), TyKind::Infer(v) if !v.is_int() && !v.is_float()) =>
            {
                match self.unsize_coercion(x, y, found, expected, span, e) {
                    Some(c) => c,
                    None => return false,
                }
            }
            // `Box<T>` to `Box<dyn Tr>` and `Rc<T>` to `Rc<dyn Tr>`: an
            // owning unsizing, under the rules of the reference form.
            (TyKind::Adt(..), TyKind::Adt(..)) if let Some((x, y)) = self.owning_unsize_parts(found, expected) => {
                // `Box<[T; N]>` to `Box<[T]>` (and the Rc and Arc forms).
                if let (TyKind::Array(xe, _), TyKind::Slice(ye)) = (self.kind(x), self.kind(y)) {
                    if !self.unify(xe, ye) {
                        self.mismatch(span, expected, found);
                        return false;
                    }
                    if let Some(e) = e {
                        let i = self.ei(e);
                        self.out.coerce[i] = Coerce::Unsize(expected);
                    }
                    return true;
                }
                match self.unsize_coercion(x, y, found, expected, span, e) {
                    Some(c) => c,
                    None => return false,
                }
            }
            _ => {
                if !self.unify(found, expected) {
                    // A deref coercion through user `Deref` impls (`&name`
                    // where `&str` is wanted).
                    if let (Some(ex), TyKind::Ref(_, fm, _), TyKind::Ref(_, em, y)) = (e, fk, ek)
                        && (!em.is_mut() || fm.is_mut())
                        && let Some(c) = self.user_deref_coercion(ex, found, y, em.is_mut(), span)
                    {
                        let i = self.ei(ex);
                        self.out.coerce[i] = c;
                        return true;
                    }
                    if self.coerce_deep(found, expected, e) {
                        // The whole value now has the expected type; the
                        // inner coercions recorded on its parts build it.
                        if let Some(e) = e {
                            self.set(e, expected);
                        }
                        return true;
                    }
                    self.mismatch(span, expected, found);
                    return false;
                }
                let (f, x) = self.guard_unsize(found, expected).unwrap_or((found, expected));
                self.dyn_regions(f, x, false, span);
                Coerce::None
            }
        };
        if let Some(e) = e {
            let i = self.ei(e);
            self.out.coerce[i] = c;
        }
        true
    }

    /// The object lifetime checks of a coercion whose types unified
    /// (`unify` ignores regions; see `check::object`). A `'static`
    /// object lifetime the found type lacks is the borrow checker's
    /// (it relates the types' object lifetime slots). Under `&mut`, `*mut`, a user Adt (lust computes no
    /// variance), a fn pointer, or trait args (`invariant`), the object
    /// lifetimes must match; and a written `&'static` reference to a
    /// dyn value cannot come from a shorter one. lust cannot prove
    /// either, so both are L0705.
    fn dyn_regions(&mut self, found: Ty, expected: Ty, invariant: bool, span: Span) {
        let (f, e) = (self.deep(found), self.deep(expected));
        // A dyn type's principal args do not reach the type flags, so the
        // signature check runs first.
        if let Some(why) = self.sig_static_mismatch(f, e, invariant, 0) {
            self.err("L0110", span, why, "Write `&'static` in both types, or elide it in both.");
            return;
        }
        if !self.tys.flags(f).contains_static_region() && !self.tys.flags(e).contains_static_region() {
            return;
        }
        if let Some(why) = self.region_walk(f, e, invariant, 0) {
            self.err("L0705", span, why, "Use the same object lifetime on both sides, or drop the `'static` bound from the `dyn` type.");
        }
    }

    /// The object types of a `RefCell` guard coercion (`RefMut<'b, dyn Tr +
    /// 'static>` to `RefMut<'b, dyn Tr + 'b>`, std's `CoerceUnsized` for
    /// `Ref` and `RefMut`): at a coercion site, the guard's object
    /// lifetime may shorten, as for `&mut dyn Tr`. None for other types.
    fn guard_unsize(&mut self, found: Ty, expected: Ty) -> Option<(Ty, Ty)> {
        let (f, e) = (self.deep(found), self.deep(expected));
        let b = self.tys.builtin_of(f);
        if !matches!(b, Some(BuiltinTy::RefGuard | BuiltinTy::RefMutGuard)) || b != self.tys.builtin_of(e) {
            return None;
        }
        let (TyKind::Adt(_, af), TyKind::Adt(_, ae)) = (self.tys.kind(f), self.tys.kind(e)) else { return None };
        let (xf, xe) = (self.tys.args(af).iter().find_map(|g| g.as_ty())?, self.tys.args(ae).iter().find_map(|g| g.as_ty())?);
        matches!((self.tys.kind(xf), self.tys.kind(xe)), (TyKind::Dyn(..), TyKind::Dyn(..))).then_some((xf, xe))
    }

    /// `dyn_regions` over two unified types, in parallel. A `'static`
    /// object lifetime the found type lacks is the borrow checker's; this
    /// returns the reason when the regions cannot match, or when the
    /// types nest past the walk limit (nothing is proved there).
    fn region_walk(&mut self, f: Ty, e: Ty, invariant: bool, depth: u32) -> Option<String> {
        let p = self.p;
        if f == e {
            return None;
        }
        if depth > object::LIFETIME_WALK_LIMIT {
            return Some("these types nest too deeply for lust to check their object lifetimes".to_string());
        }
        match (self.tys.kind(f), self.tys.kind(e)) {
            (TyKind::Dyn(bf, _), TyKind::Dyn(be, _)) => {
                let (fs, es) = (object::dyn_is_static(p, &self.tys, f), object::dyn_is_static(p, &self.tys, e));
                if fs && !es && invariant {
                    return Some(format!(
                        "`{}` and `{}` must have the same object lifetime here, and lust cannot prove that",
                        self.tn(f),
                        self.tn(e)
                    ));
                }
                match (self.tys.dyn_bounds(bf).principal, self.tys.dyn_bounds(be).principal) {
                    (Some(pf), Some(pe)) if pf.value.def == pe.value.def => self.args_walk(pf.value.args, pe.value.args, true, depth),
                    _ => None,
                }
            }
            (TyKind::Ref(rf, _, xf), TyKind::Ref(re, me, xe)) => {
                // Only `&'static dyn Tr` is checked here; a `&'static` in a
                // fn pointer type or `dyn Fn` sugar (`Scope::static_refs`)
                // is the borrow checker's.
                let to_dyn = matches!(self.tys.kind(xe), TyKind::Dyn(..));
                if to_dyn && re == Region::Static && rf != Region::Static {
                    return Some(format!("lust cannot prove that this reference lives for `'static`, which `{}` requires", self.tn(e)));
                }
                if to_dyn && rf == Region::Static && re != Region::Static && invariant {
                    return Some(format!("`{}` and `{}` must have the same lifetime here, and lust cannot prove that", self.tn(f), self.tn(e)));
                }
                self.region_walk(xf, xe, invariant || me.is_mut(), depth + 1)
            }
            (TyKind::RawPtr(_, xf), TyKind::RawPtr(me, xe)) => self.region_walk(xf, xe, invariant || me.is_mut(), depth + 1),
            (TyKind::Slice(xf), TyKind::Slice(xe)) | (TyKind::Array(xf, _), TyKind::Array(xe, _)) => {
                self.region_walk(xf, xe, invariant, depth + 1)
            }
            (TyKind::Tuple(a), TyKind::Tuple(b)) => {
                let (a, b) = (self.tys.tys_of(a).to_vec(), self.tys.tys_of(b).to_vec());
                a.into_iter().zip(b).find_map(|(x, y)| self.region_walk(x, y, invariant, depth + 1))
            }
            // `Option`, `Result`, `Vec`, `Box`, `Rc`, `Arc`, and the
            // shared guards `Ref` and `RwLockReadGuard` are covariant.
            (TyKind::Adt(df, af), TyKind::Adt(de, ae)) if df == de => {
                let covariant = matches!(
                    self.tys.builtin_of(f),
                    Some(BuiltinTy::Option | BuiltinTy::Result | BuiltinTy::Vec | BuiltinTy::Boxed | BuiltinTy::Rc | BuiltinTy::RefGuard)
                        | Some(BuiltinTy::Sync(crate::ty::sync::SyncTy::Arc | crate::ty::sync::SyncTy::RwLockReadGuard))
                );
                self.args_walk(af, ae, invariant || !covariant, depth)
            }
            (TyKind::FnPtr(sf), TyKind::FnPtr(se)) => {
                let (sf, se) = (self.tys.sig(sf).value, self.tys.sig(se).value);
                let (inf, ine) = (self.tys.tys_of(sf.inputs).to_vec(), self.tys.tys_of(se.inputs).to_vec());
                inf.into_iter()
                    .chain([sf.output])
                    .zip(ine.into_iter().chain([se.output]))
                    .find_map(|(x, y)| self.region_walk(x, y, true, depth + 1))
            }
            (TyKind::FnDef(df, af), TyKind::FnDef(de, ae))
            | (TyKind::Closure(df, af), TyKind::Closure(de, ae))
            | (TyKind::Opaque(df, af), TyKind::Opaque(de, ae))
                if df == de =>
            {
                self.args_walk(af, ae, true, depth)
            }
            _ => None,
        }
    }

    /// W-BORROW: a fn pointer type or `dyn Fn*` sugar may write `&'static`
    /// (`Scope::static_refs`); every other region there is late-bound.
    /// `found` fits `expected` only when it is at least as general: no
    /// `'static` input where `expected` takes any lifetime, and no
    /// late-bound output where `expected` returns `'static` (rustc E0308;
    /// under `invariant`, the two must agree). Walks two unified types in
    /// parallel to the signatures in them.
    fn sig_static_mismatch(&mut self, f: Ty, e: Ty, invariant: bool, depth: u32) -> Option<String> {
        if f == e || depth > object::LIFETIME_WALK_LIMIT {
            return None;
        }
        let sigs = |this: &mut Self, t: Ty| -> Option<(Vec<Ty>, Ty)> {
            match this.tys.kind(t) {
                TyKind::FnPtr(s) => {
                    let s = this.tys.sig(s).value;
                    Some((this.tys.tys_of(s.inputs).to_vec(), s.output))
                }
                TyKind::Dyn(..) => {
                    let (_, tuple, out) = this.dyn_fn_parts(t)?;
                    let ins = match this.tys.kind(tuple) {
                        TyKind::Tuple(ts) => this.tys.tys_of(ts).to_vec(),
                        _ => Vec::new(),
                    };
                    Some((ins, out))
                }
                _ => None,
            }
        };
        if let (Some((fi, fo)), Some((ei, eo))) = (sigs(self, f), sigs(self, e)) {
            for (x, y) in fi.into_iter().zip(ei) {
                if let Some(why) = self.sig_pos_mismatch(x, y, true, invariant, f, e) {
                    return Some(why);
                }
            }
            if self.ptr_out_tied_lost(f, e, invariant) {
                return Some(format!("`{}` is not as general as `{}`: their lifetimes differ", self.tn(f), self.tn(e)));
            }
            return self.sig_pos_mismatch(fo, eo, false, invariant, f, e);
        }
        match (self.tys.kind(f), self.tys.kind(e)) {
            (TyKind::Ref(_, _, x), TyKind::Ref(_, m, y)) | (TyKind::RawPtr(_, x), TyKind::RawPtr(m, y)) => {
                self.sig_static_mismatch(x, y, invariant || m.is_mut(), depth + 1)
            }
            (TyKind::Slice(x), TyKind::Slice(y)) | (TyKind::Array(x, _), TyKind::Array(y, _)) => self.sig_static_mismatch(x, y, invariant, depth + 1),
            (TyKind::Tuple(a), TyKind::Tuple(b)) => {
                let (a, b) = (self.tys.tys_of(a).to_vec(), self.tys.tys_of(b).to_vec());
                a.into_iter().zip(b).find_map(|(x, y)| self.sig_static_mismatch(x, y, invariant, depth + 1))
            }
            (TyKind::Adt(df, af), TyKind::Adt(de, ae)) if df == de => {
                let covariant = matches!(self.tys.builtin_of(f), Some(BuiltinTy::Option | BuiltinTy::Result | BuiltinTy::Vec | BuiltinTy::Boxed | BuiltinTy::Rc));
                let (a, b) = (self.tys.args(af).to_vec(), self.tys.args(ae).to_vec());
                a.into_iter().zip(b).find_map(|(x, y)| match (x.as_ty(), y.as_ty()) {
                    (Some(x), Some(y)) => self.sig_static_mismatch(x, y, invariant || !covariant, depth + 1),
                    _ => None,
                })
            }
            _ => None,
        }
    }

    /// Records `e` and the tails of the blocks it is (`ret_exprs`).
    fn note_ret_expr(&mut self, mut e: ExprId) {
        loop {
            self.ret_exprs.push(e);
            match self.p.ast.expr(e) {
                Expr::Block(b) | Expr::UnsafeBlock(b) => match self.p.ast.block(*b).tail {
                    Some(t) => e = t,
                    None => return,
                },
                _ => return,
            }
        }
    }

    /// True when fn pointer `f` is not as general as fn pointer `e` in a
    /// way `sig_pos_mismatch` does not see (rustc E0308): `f` returns its
    /// one input's borrow in an output slot where `e`'s slot was filled by
    /// a type argument (`FnSig::out_substituted`: `fn(&u8) -> &u8` passed
    /// for `fn(&u8) -> T` with `T = &u8`; known only when `f` has more such
    /// slots than `e` writes), or the other way round when
    /// `invariant`; or an input slot of `f` is a free region where `e`'s
    /// is higher-ranked. Slots line up: the two types unified.
    fn ptr_out_tied_lost(&mut self, f: Ty, e: Ty, invariant: bool) -> bool {
        let (TyKind::FnPtr(sf), TyKind::FnPtr(se)) = (self.tys.kind(f), self.tys.kind(e)) else { return false };
        let (sf, se) = (self.tys.sig(sf).value, self.tys.sig(se).value);
        let al = &self.p.gx.adt_lifetimes;
        // A source input slot that is the enclosing item's lifetime
        // (`fn(&'x u8) -> &'x u8`, `FnSig::free_slots`) cannot take every
        // region a higher-ranked target input slot may be.
        if sf.free_slots != 0 && se.free_slots == 0 {
            let mut ins = Vec::new();
            for &t in self.tys.tys_of(se.inputs) {
                crate::borrowck::paired_slot_regions(al, &self.tys, t, t, &mut ins);
            }
            if ins.iter().enumerate().any(|(j, r)| j < 32 && sf.free_slots >> j & 1 == 1 && *r != Region::Static) {
                return true;
            }
        }
        let mut slots = Vec::new();
        crate::borrowck::paired_slot_regions(al, &self.tys, sf.output, sf.output, &mut slots);
        let n = slots.len();
        // A substituted side's slots are no binder's; an exact one's are
        // its `own_out` bits.
        // A substitution keeps the written own slots but moves them, so
        // a substituted side has that many own slots somewhere: more
        // tied slots on the other side cannot all meet one.
        let tied = |s: &crate::ty::FnSig| if s.out_substituted(n) || s.out_slots == u8::MAX { None } else { Some(s.own_out) };
        match (tied(&sf), tied(&se)) {
            (Some(a), None) if se.out_substituted(n) => a.count_ones() > se.own_out.count_ones(),
            (None, Some(b)) if invariant && sf.out_substituted(n) => b.count_ones() > sf.own_out.count_ones(),
            _ => false,
        }
    }

    /// One input (`input`) or the output of two signatures in parallel
    /// (`sig_static_mismatch`): their `&'static` and late-bound
    /// references, place by place.
    fn sig_pos_mismatch(&mut self, x: Ty, y: Ty, input: bool, invariant: bool, f: Ty, e: Ty) -> Option<String> {
        match (self.tys.kind(x), self.tys.kind(y)) {
            (TyKind::Ref(rx, _, xi), TyKind::Ref(ry, _, yi)) => {
                let (sx, sy) = (rx == Region::Static, ry == Region::Static);
                let bad = if invariant { sx != sy } else if input { sx && !sy } else { sy && !sx };
                if bad {
                    return Some(format!("`{}` is not as general as `{}`: their `'static` references differ", self.tn(f), self.tn(e)));
                }
                self.sig_pos_mismatch(xi, yi, input, invariant, f, e)
            }
            (TyKind::Tuple(a), TyKind::Tuple(b)) => {
                let (a, b) = (self.tys.tys_of(a).to_vec(), self.tys.tys_of(b).to_vec());
                a.into_iter().zip(b).find_map(|(p, q)| self.sig_pos_mismatch(p, q, input, invariant, f, e))
            }
            (TyKind::Slice(p), TyKind::Slice(q)) | (TyKind::Array(p, _), TyKind::Array(q, _)) => self.sig_pos_mismatch(p, q, input, invariant, f, e),
            // The covariant std containers keep the position
            // (`Option<&'static T>` is an `Option<&T>`, W-BORROW3); any
            // other Adt holds its args invariant.
            (TyKind::Adt(dx, ax), TyKind::Adt(dy, ay)) if dx == dy => {
                let covariant = matches!(self.tys.builtin_of(x), Some(BuiltinTy::Option | BuiltinTy::Result | BuiltinTy::Vec | BuiltinTy::Boxed | BuiltinTy::Rc));
                let (a, b) = (self.tys.args(ax).to_vec(), self.tys.args(ay).to_vec());
                a.into_iter().zip(b).find_map(|(p, q)| match (p.as_ty(), q.as_ty()) {
                    (Some(p), Some(q)) => self.sig_pos_mismatch(p, q, input, invariant || !covariant, f, e),
                    _ => None,
                })
            }
            _ => None,
        }
    }

    fn args_walk(&mut self, a: ArgsId, b: ArgsId, invariant: bool, depth: u32) -> Option<String> {
        let (a, b) = (self.tys.args(a).to_vec(), self.tys.args(b).to_vec());
        a.into_iter().zip(b).find_map(|(x, y)| match (x.as_ty(), y.as_ty()) {
            (Some(x), Some(y)) => self.region_walk(x, y, invariant, depth + 1),
            _ => None,
        })
    }
    /// Structural equality with inference variables as wildcards.
    fn ty_matchish(&self, a: Ty, b: Ty) -> bool {
        let (a, b) = (self.resolve(a), self.resolve(b));
        if a == b {
            return true;
        }
        match (self.tys.kind(a), self.tys.kind(b)) {
            (TyKind::Infer(_), _) | (_, TyKind::Infer(_)) => true,
            (TyKind::Ref(_, _, x), TyKind::Ref(_, _, y)) => self.ty_matchish(x, y),
            (TyKind::Slice(x), TyKind::Slice(y)) | (TyKind::Array(x, _), TyKind::Array(y, _)) => self.ty_matchish(x, y),
            (TyKind::Tuple(xs), TyKind::Tuple(ys)) => {
                let (xs, ys) = (self.tys.tys_of(xs), self.tys.tys_of(ys));
                xs.len() == ys.len() && xs.iter().zip(ys).all(|(&x, &y)| self.ty_matchish(x, y))
            }
            (TyKind::Adt(d, x), TyKind::Adt(e, y)) => {
                d == e
                    && self.tys.args(x).len() == self.tys.args(y).len()
                    && self.tys.args(x).iter().zip(self.tys.args(y)).all(|(x, y)| match (x, y) {
                        (GenericArg::Ty(x), GenericArg::Ty(y)) => self.ty_matchish(*x, *y),
                        _ => x == y,
                    })
            }
            _ => false,
        }
    }

    /// True when a reference coercion (unsize to a slice, `&String` to
    /// `&str`, `&mut` to `&`) takes `f` to `e`. Pure: no unification.
    fn ref_coercible(&self, f: Ty, e: Ty) -> bool {
        // A reference (or `*mut T`) to a raw pointer (w-cinterop), so a
        // deep coercion through `Some(..)` or a tuple reaches it.
        match (self.kind(f), self.kind(e)) {
            (TyKind::Ref(_, fm, x), TyKind::RawPtr(em, y)) => return (!em.is_mut() || fm.is_mut()) && self.ty_matchish(x, y),
            (TyKind::RawPtr(Mut::Mut, x), TyKind::RawPtr(Mut::Shared, y)) => return self.ty_matchish(x, y),
            _ => {}
        }
        let (TyKind::Ref(_, fm, x), TyKind::Ref(_, em, y)) = (self.kind(f), self.kind(e)) else { return false };
        if em.is_mut() && !fm.is_mut() {
            return false;
        }
        // Unsizing (`&[T; N]` to `&[T]`), then a deref coercion: `y` on
        // `x`'s autoderef chain (`&Box<[T]>`, `&Vec<T>`, `&Box<Vec<T>>`
        // to `&[T]`; `&String`, `&Box<str>`, `&Rc<String>` to `&str`).
        if let (TyKind::Array(xe, _), TyKind::Slice(ye)) = (self.kind(x), self.kind(y)) {
            return self.ty_matchish(xe, ye);
        }
        self.deref_reaches(x, y, em.is_mut())
    }

    /// True when `y` is on the builtin autoderef chain of `x` (`x`
    /// itself, then through references, `Box`, `Rc`, `Arc`, the cell
    /// and lock guards, `String` to `str`, `Vec<T>` to `[T]`, and `Cow<B>`
    /// to `B`): the deref coercion `&x` to `&y`. With `mutable` (a `&mut
    /// y` target) only `DerefMut` steps count: `&mut`, `Box`, `String`,
    /// `Vec`, and the guards that hand out `&mut`. A user `Deref` step
    /// is not followed (the coercion sites check it themselves). Pure.
    fn deref_reaches(&self, x: Ty, y: Ty, mutable: bool) -> bool {
        let mut t = self.resolve(x);
        for _ in 0..16 {
            if self.ty_matchish(t, y) {
                return true;
            }
            // `Vec<T>` derefs to `[T]`, the end of its chain.
            if let Some(e) = self.tys.vec_elem(t) {
                return matches!(self.kind(y), TyKind::Slice(ye) if self.ty_matchish(e, ye));
            }
            let next = match self.kind(t) {
                TyKind::Ref(_, m, inner) if !mutable || m.is_mut() => Some(inner),
                TyKind::Ref(..) => None,
                _ if self.tys.is_string_ty(t) => Some(STR),
                _ if mutable => self.tys.boxed_elem(t).or_else(|| self.tys.guard_elem(t).filter(|g| g.1).map(|g| g.0)),
                _ => self
                    .tys
                    .smart_elem(t)
                    .or_else(|| (self.tys.builtin_of(t) == Some(BuiltinTy::Sync(crate::ty::sync::SyncTy::Arc))).then(|| self.tys.adt_first_ty_arg(t)).flatten())
                    .or_else(|| crate::check::collect::cow_arg(&self.tys, t)),
            };
            match next {
                Some(n) => t = self.resolve(n),
                None => return false,
            }
        }
        false
    }

    /// True when the fn item to fn pointer coercion takes `f` to `e`.
    /// Pure: no unification (the same test `coerce_at` applies).
    fn fn_coercible(&mut self, f: Ty, e: Ty) -> bool {
        if !matches!(self.kind(e), TyKind::FnPtr(_)) || !self.reifies(f) {
            return false;
        }
        // Part by part, as `unify` compares fn pointers: a written
        // `&'static` or free lifetime in `e` (W-BORROW3) is the borrow
        // checker's to prove (`fnptr::fn_item_to_ptr`).
        let (snap, obl) = (self.snapshot_vars(), self.obl_len());
        let ok = self.fn_item_ptr_unifies(f, e);
        self.rollback_vars(snap);
        self.obl_truncate(obl);
        ok
    }

    /// Coercion inside an aggregate value whose producer is in hand: a
    /// tuple literal, or a one-argument variant call such as `Some(&v)`
    /// where `&[u8]` is wanted. The inner coercions record on the inner
    /// expressions, so lowering applies them while building the value.
    /// Other shapes keep the plain type-mismatch error.
    fn coerce_deep(&mut self, found: Ty, expected: Ty, e: Option<ExprId>) -> bool {
        let Some(e) = e else { return false };
        let span = self.span(e);
        match (self.kind(found), self.kind(expected)) {
            (TyKind::Tuple(xs), TyKind::Tuple(ys)) => {
                let Expr::Tuple(elems) = self.p.ast.expr(e) else { return false };
                let (xs, ys) = (self.tys.tys_of(xs).to_vec(), self.tys.tys_of(ys).to_vec());
                if xs.len() != ys.len() || elems.len() != xs.len() {
                    return false;
                }
                if !xs.iter().zip(&ys).all(|(&x, &y)| self.ty_matchish(x, y) || self.ref_coercible(x, y) || self.fn_coercible(x, y)) {
                    return false;
                }
                elems.iter().zip(xs.iter().zip(&ys)).all(|(&el, (&x, &y))| self.coerce_at(x, y, span, Some(el)))
            }
            (TyKind::Adt(df, af), TyKind::Adt(de, ae)) if df == de => {
                let (fa, ea) = (self.tys.args(af).to_vec(), self.tys.args(ae).to_vec());
                if fa.len() != ea.len() || fa.len() != 1 {
                    return false;
                }
                let (Some(x), Some(y)) = (fa[0].as_ty(), ea[0].as_ty()) else { return false };
                if !self.ref_coercible(x, y) && !self.fn_coercible(x, y) {
                    return false;
                }
                // The producer must be a one-argument variant call
                // (`Some(..)`), whose argument carries the coercion.
                let Expr::Call { args, .. } = self.p.ast.expr(e) else { return false };
                if args.len() != 1 || !matches!(self.out.expr_res[self.ei(e)], Res::Variant(..) | Res::OptSome) {
                    return false;
                }
                let inner_found = self.out.expr_ty[self.ei(args[0])];
                self.coerce_at(inner_found, y, span, Some(args[0]))
            }
            _ => false,
        }
    }

    /// The unsizing coercion to a dyn type with only auto traits
    /// (`Box<T>` to `Box<dyn Send>`, R25): a sized source that implements
    /// each written auto trait (queued as obligations), `'static` when
    /// the object lifetime is, and a vtable request for the method-less
    /// vtable (`object::vtable_key`).
    fn auto_only_unsize(&mut self, mut x: Ty, y: Ty, found: Ty, expected: Ty, span: Span, e: Option<ExprId>) -> Option<Coerce> {
        let p = self.p;
        if matches!(self.kind(expected), TyKind::Ref(Region::Static, ..))
            && !matches!(self.kind(found), TyKind::Ref(Region::Static, ..))
            && !e.is_some_and(|e| self.static_borrow(e))
        {
            let tn = self.tn(expected);
            self.err(
                "L0705",
                span,
                format!("lust cannot prove that this reference lives for `'static`, which `{tn}` requires"),
                "Borrow a `static` item here, or use a shorter reference.",
            );
            return None;
        }
        // A dyn source drops its principal or some auto traits (`dyn Tr +
        // Send` or `dyn Send + Sync` to `dyn Send`): it must have every
        // target auto trait. Every vtable starts with drop, size, and
        // align, so the fat pointer stays as it is (lower.rs `unsize`).
        if matches!(self.kind(x), TyKind::Dyn(..)) {
            let have = object::dyn_auto(p, &self.tys, x);
            let want = match self.tys.kind(y) {
                TyKind::Dyn(b, _) => self.tys.dyn_bounds(b).auto,
                _ => AutoTraits::default(),
            };
            if (want.send && !have.send) || (want.sync && !have.sync) || (want.unpin && !have.unpin) {
                self.mismatch(span, expected, found);
                return None;
            }
            // A `'static` target object lifetime: the borrow checker proves it.
            return Some(Coerce::Unsize(expected));
        }
        // A numeric literal falls back to i32 (f64), as no trait picks it.
        if let TyKind::Infer(v) = self.tys.kind(x)
            && (v.is_int() || v.is_float())
        {
            let t = if v.is_int() { I32 } else { self.tys.float_ty(FloatTy::F64) };
            self.unify(x, t);
            x = t;
        }
        if !self.sized_ok(x) {
            let tn = self.tn(x);
            self.err(
                "L0110",
                span,
                format!("the size for values of type `{tn}` cannot be known, so it cannot become a `dyn` value"),
                "Only a sized type converts to a `dyn` value.",
            );
            return None;
        }
        let to_static = object::dyn_is_static(p, &self.tys, y);
        let borrows = if to_static { object::may_borrow_in(p, &self.tys, self.env(), x) } else { object::may_borrow(p, &self.tys, x) };
        if !to_static && borrows {
            self.dyn_borrow_src = true;
        }
        let instance = matches!(p.gx.fn_class.get(self.fid.0 as usize), Some(generics::FnClass::Instance));
        if to_static && borrows && !instance && !self.defer_static_source(x, span) && !self.bck_static_source(x) {
            self.static_source_err(x, span);
            return None;
        }
        let want = match self.tys.kind(y) {
            TyKind::Dyn(b, _) => self.tys.dyn_bounds(b).auto,
            _ => AutoTraits::default(),
        };
        let lang = p.gx.lang;
        for (on, def) in [(want.send, lang.send), (want.sync, lang.sync), (want.unpin, lang.unpin)] {
            if on {
                let args = self.tys.intern_args(&[GenericArg::Ty(x)]);
                self.obl.push_trait_at(TraitRef { def, args, bindings: EMPTY_BINDINGS }, span, 0);
            }
        }
        let y = object::erase_dyn_region(&mut self.tys, y);
        self.vtable_sites.push((x, y, span));
        Some(Coerce::Unsize(expected))
    }

    /// A single-segment type path with no args that names a const
    /// parameter of the body and no type parameter: the const (its
    /// value in an instance check).
    fn const_param_path(&mut self, t: ast::TyId) -> Option<ConstId> {
        let ast::TyExpr::Path(segs) = self.p.ast.ty(t) else { return None };
        let [seg] = segs.as_slice() else { return None };
        if seg.has_args() || self.body_scope.param_tys.iter().any(|(n, _)| *n == seg.name) {
            return None;
        }
        // An instance check sees the parameter's value.
        if let Some(&(_, c)) = self.body_scope.const_values.iter().find(|(n, _)| *n == seg.name) {
            return Some(c);
        }
        let &(_, i, _) = self.body_scope.const_params.iter().find(|(n, ..)| *n == seg.name)?;
        Some(self.tys.intern_const(ConstKind::Param(i)))
    }

    fn coerce_expr(&mut self, e: ExprId, found: Ty, expected: Ty) -> bool {
        let span = self.span(e);
        // An eta closure's argument (parser `eta_closure`) stands for a
        // fn item's parameter, which is no coercion site: `str::cmp` as
        // a `sort_by` callable over `&str` items takes `&&str` and
        // rejects (rustc E0631), as the fn item does.
        if self.is_eta_arg(e) {
            self.run_obligations(false);
            if self.unify(found, expected) {
                return true;
            }
            self.mismatch(span, expected, found);
            return false;
        }
        self.coerce_at(found, expected, span, Some(e))
    }

    /// True for a parameter read inside an eta closure's call: a path
    /// to a `__lust_eta` local at the span of its own binding (the
    /// parser gives every eta node the path's span, which no written
    /// read of a local shares).
    pub(super) fn is_eta_arg(&self, e: ExprId) -> bool {
        let Res::Local(l) = self.out.expr_res[self.ei(e)] else { return false };
        let local = &self.out.locals[l as usize];
        local.span == self.span(e) && self.name(local.name).starts_with("__lust_eta")
    }

    /// The Self type of the only impl of `trait_def` for an integer (or
    /// float) type, if exactly one such impl exists and no blanket impl
    /// could also take the literal.
    fn literal_impl_ty(&self, trait_def: DefId, float: bool) -> Option<Ty> {
        let index = &self.p.gx.index;
        let mut found: Option<Ty> = None;
        for &id in index.impls_of_trait(trait_def) {
            let t = index.get(id).self_ty(&self.p.tys);
            match self.p.tys.kind(t) {
                TyKind::Int(_) if !float => {}
                TyKind::Float(_) if float => {}
                TyKind::Param(_) => return None,
                _ => continue,
            }
            if found.is_some_and(|f| f != t) {
                return None;
            }
            found = Some(t);
        }
        found
    }

    /// The unsizing coercion from a reference to `x` to a reference to
    /// the dyn type `y` (ARCH 2.8). A dyn source upcasts (the target
    /// principal is the source's or a supertrait of it) or drops auto
    /// traits; a sized source must implement the principal and every
    /// written auto trait, which are queued as obligations, and becomes
    /// a vtable request. Reports the error and returns None when the
    /// coercion cannot apply.
    fn unsize_coercion(&mut self, x: Ty, y: Ty, found: Ty, expected: Ty, span: Span, e: Option<ExprId>) -> Option<Coerce> {
        let p = self.p;
        let (mut x, y) = (self.deep(x), self.deep(y));
        if matches!(self.tys.kind(y), TyKind::Dyn(b, _) if self.tys.dyn_bounds(b).principal.is_none()) {
            return self.auto_only_unsize(x, y, found, expected, span, e);
        }
        let to = object::principal_of(&self.tys, y)?;
        // A written `&'static dyn Tr` target: lust tracks no reference
        // lifetimes, so only a borrow of a static item (or a reference
        // already typed `&'static`) proves it.
        if matches!(self.kind(expected), TyKind::Ref(Region::Static, ..))
            && !matches!(self.kind(found), TyKind::Ref(Region::Static, ..))
            && !e.is_some_and(|e| self.static_borrow(e))
        {
            let tn = self.tn(expected);
            self.err(
                "L0705",
                span,
                format!("lust cannot prove that this reference lives for `'static`, which `{tn}` requires"),
                "Borrow a `static` item here, or use `&(dyn Tr + 'static)` (a shorter reference to a `'static` object).",
            );
            return None;
        }
        // A numeric literal behind the coercion (`&3 as &dyn Tr`): as in
        // rustc, the one impl of the trait for a type of that kind
        // decides it, and otherwise the literal falls back to i32 (f64).
        if let TyKind::Infer(v) = self.tys.kind(x)
            && (v.is_int() || v.is_float())
        {
            let fallback = if v.is_int() { I32 } else { self.tys.float_ty(FloatTy::F64) };
            let t = self.literal_impl_ty(to.def, v.is_float()).unwrap_or(fallback);
            self.unify(x, t);
            x = t;
        }
        let want = match self.tys.kind(y) {
            TyKind::Dyn(b, _) => self.tys.dyn_bounds(b).auto,
            _ => AutoTraits::default(),
        };
        // A `'static` target: written (`+ 'static`), or implied by a
        // `'static` bound on the principal or one of its supertraits.
        let to_static = object::dyn_is_static(p, &self.tys, y);
        if let Some(from) = object::principal_of(&self.tys, x) {
            let have = object::dyn_auto(p, &self.tys, x);
            let auto_ok = (!want.send || have.send) && (!want.sync || have.sync) && (!want.unpin || have.unpin);
            let path_ok = if from.def == to.def {
                self.unify_args(from.args, to.args) && self.unify_bindings(from.bindings, to.bindings)
            } else {
                object::upcast_path(p, &mut self.tys, from, to).is_some()
            };
            if !auto_ok || !path_ok {
                self.mismatch(span, expected, found);
                return None;
            }
            // W-BORROW: `dyn Fn(&'static T)` is not as general as `dyn
            // Fn(&T)` (rustc E0308; `sig_static_mismatch`).
            if from.def == to.def
                && let Some(why) = self.sig_static_mismatch(x, y, false, 0)
            {
                self.err("L0110", span, why, "Write `&'static` in both types, or elide it in both.");
                return None;
            }
            // A `'static` target object lifetime: the borrow checker proves it.
            return Some(Coerce::Unsize(expected));
        }
        if !self.sized_ok(x) {
            let tn = self.tn(x);
            self.err(
                "L0110",
                span,
                format!("the size for values of type `{tn}` cannot be known, so it cannot become a `dyn` value"),
                "Only a sized type converts to `&dyn Trait`; pass a reference to a sized value.",
            );
            return None;
        }
        // The source of a `'static` target must be `'static` itself; a
        // type param passes with a `'static` bound in the env.
        let borrows = if to_static { object::may_borrow_in(p, &self.tys, self.env(), x) } else { object::may_borrow(p, &self.tys, x) };
        if !to_static && borrows {
            self.dyn_borrow_src = true;
        }
        // An instance replays its template, which proved this under the
        // env's `'static` bounds (a `T: 'static` arg may be `&'static str`).
        let instance = matches!(p.gx.fn_class.get(self.fid.0 as usize), Some(generics::FnClass::Instance));
        if to_static && borrows && !instance && !self.defer_static_source(x, span) && !self.bck_static_source(x) {
            self.static_source_err(x, span);
            return None;
        }
        let lang = p.gx.lang;
        // A `dyn Fn(A) -> R` value (ARCH 2.9): a closure (its body fn is
        // the vtable's call entry), a fn item, or a fn pointer; `R` is its
        // `Output`. A type param with an Fn bound (`hooks.push(Box::new(f))`
        // for `f: F`) checks here and builds the vtable in each instance.
        // A tuple constructor there is not supported yet. An `impl Fn..`
        // value checks by its bounds in the opaque view; the revealed
        // check (which codegen gets) sees its hidden type here instead.
        if lang.is_fn_family(to.def) {
            let fn_value = match self.kind(x) {
                TyKind::FnDef(def, _) => p.is_fn_item_def(def),
                TyKind::Closure(..) | TyKind::Param(_) | TyKind::FnPtr(_) => true,
                TyKind::Opaque(..) => self.opaque_mode == opaque::OpaqueMode::View,
                // A reference to a closure or to a `dyn Fn`/`FnMut` (core's
                // `impl Fn* for &F / &mut F`; `&mut v` with `v: &mut
                // {closure}` or `v: &mut dyn FnMut(..)` in an instance): its
                // call entry goes through the reference (cgen `vtable_shim`,
                // `dyn_ref_shim`). Not as a `dyn FnOnce`, which would consume
                // the reference.
                TyKind::Ref(_, _, inner) => {
                    let inner = self.resolve(inner);
                    to.def != lang.fn_once
                        && (matches!(self.kind(inner), TyKind::Closure(..))
                            || object::principal_of(&self.tys, inner).is_some_and(|pr| lang.is_fn_family(pr.def) && pr.def != lang.fn_once))
                }
                _ => false,
            };
            if !fn_value {
                let tn = self.tn(x);
                self.errs.push(generics::dyn_not_yet(span, &format!("a `dyn` Fn value made from `{tn}` (closures, fn items, and fn pointers only)")));
                return None;
            }
            let tr = object::with_self(&mut self.tys, to, x);
            for (assoc, g) in self.tys.bindings(to.bindings).to_vec() {
                if let GenericArg::Ty(ty) = g {
                    self.obl.push(obligations::Obligation::AssocEq { eq: AssocEqData { assoc, trait_args: tr.args, ty }, span });
                }
            }
        }
        let tr = object::with_self(&mut self.tys, to, x);
        self.obl.push_trait_at(tr, span, 0);
        for (on, def) in [(want.send, lang.send), (want.sync, lang.sync), (want.unpin, lang.unpin)] {
            if on {
                let args = self.tys.intern_args(&[GenericArg::Ty(x)]);
                self.obl.push_trait_at(TraitRef { def, args, bindings: EMPTY_BINDINGS }, span, 0);
            }
        }
        let y = object::erase_dyn_region(&mut self.tys, y);
        self.vtable_sites.push((x, y, span));
        Some(Coerce::Unsize(expected))
    }
    /// A method found through a user `Deref` impl of the receiver
    /// (rustc's autoderef, ARCH 2.10; `SmallVec` derefs to `[T]`): when
    /// nothing answers on `base` (the receiver after `before` builtin
    /// derefs) and `base` has a written `Deref` impl, the call checks
    /// on `&Target`, through `DerefMut` when it borrows mutably, and
    /// lowering calls the impl's fn first (`Checked::deref_recv`).
    /// None when no such impl applies.
    #[allow(clippy::too_many_arguments)]
    fn method_via_user_deref(
        &mut self,
        e: ExprId,
        recv: ExprId,
        base: Ty,
        before: u8,
        name: Sym,
        name_span: Span,
        args: &[ExprId],
        turbofish: &[ast::GenericArg],
        expected: Option<Ty>,
    ) -> Option<Ty> {
        let lang = self.p.gx.lang;
        // The depth counts the steps of this call's own receiver chain
        // (`W` to `X` to `Y`); a call nested in an argument starts its
        // own chain at 0.
        let depth = if self.user_deref_call == Some(e) { self.deref_depth } else { 0 };
        if depth >= 4 || self.tys.local_adt(base).is_none() {
            return None;
        }
        // Core's blanket `Into`/`TryInto` may hold for any receiver, so
        // rustc picks them at the first step and never reaches the target:
        // `W<String>` into a `String` is E0277, not `String`'s impl.
        if matches!(self.name(name), "into" | "try_into") {
            return None;
        }
        let (f, target, impl_args) = self.user_deref_fn(lang.deref, base, "deref", name_span)?;
        let tref = self.tys.mk_ref(false, target);
        let saved = std::mem::replace(&mut self.deref_depth, depth + 1);
        let outer = self.user_deref_call.replace(e);
        let ret = self.method_call_with_rt(e, recv, tref, name, name_span, args, turbofish, expected);
        self.user_deref_call = outer;
        self.deref_depth = saved;
        let mutable = match self.out.expr_res[self.ei(e)] {
            // A pick on the `&Target` value itself (no deref of it) used
            // a step rustc does not have (it steps to the target place).
            Res::Method { derefs: 0, .. } | Res::BuiltinMethod { derefs: 0, .. } | Res::DynMethod { derefs: 0, .. } if ret != ERROR => {
                let tn = self.tn(base);
                self.err(
                    "L0104",
                    name_span,
                    format!("no method `{}` on type `{tn}` or its `Deref` target", self.name(name)),
                    "Call the method on an explicit reference, such as `(&*w).m()`.",
                );
                return Some(ERROR);
            }
            Res::Method { autoref, .. } | Res::BuiltinMethod { autoref, .. } | Res::DynMethod { autoref, .. } => {
                matches!(autoref, Autoref::RefMut | Autoref::SliceRefMut)
            }
            // The lookup on the target failed and reported why.
            Res::None => return Some(ret),
            _ => {
                self.errs.push(not_yet("L0820", name_span, "this method through a user `Deref` impl"));
                return Some(ERROR);
            }
        };
        let (f, impl_args) = if mutable {
            match self.user_deref_fn(lang.deref_mut, base, "deref_mut", name_span) {
                Some((g, _, a)) => (g, a),
                None => {
                    let tn = self.tn(base);
                    self.err(
                        "L0308",
                        name_span,
                        format!("cannot borrow data in a dereference of `{tn}` as mutable"),
                        format!("Implement `DerefMut` for `{tn}`."),
                    );
                    return Some(ERROR);
                }
            }
        } else {
            (f, impl_args)
        };
        let target_ref = self.tys.mk_ref(mutable, target);
        let idx = self.out.deref_recv.len();
        self.out.deref_recv.push((e, DerefRecv { depth, before, f, args: Vec::new(), f_mut: None, args_mut: Vec::new(), mutable, target_ref }));
        self.place_step_exprs.insert(e, ());
        if self.p.gx.fn_templates.get(f.0 as usize).is_some_and(|t| t.is_some()) {
            self.deref_sites.push((DerefTable::Recv, idx, false, f, impl_args));
        }
        Some(ret)
    }

    /// Drops the place-step entries an earlier check of `e` recorded
    /// (see `place_step_exprs`): all of them at the start of a check of
    /// `e`, or with `coerce_only` its deref-coercion steps before a new
    /// coercion of `e` records its own. An entry is marked dead, not
    /// removed, so `deref_sites` indexes stay valid.
    fn forget_place_steps(&mut self, e: ExprId, coerce_only: bool) {
        if self.place_step_exprs.is_empty() || !self.place_step_exprs.contains_key(&e) {
            return;
        }
        const DEAD: ExprId = ExprId(u32::MAX);
        for (x, _) in self.out.deref_coerce.iter_mut() {
            if *x == e {
                *x = DEAD;
            }
        }
        if coerce_only {
            return;
        }
        self.place_step_exprs.remove(&e);
        for (x, _) in self.out.deref_recv.iter_mut() {
            if *x == e {
                *x = DEAD;
            }
        }
        for (x, _) in self.out.index_recv.iter_mut() {
            if *x == e {
                *x = DEAD;
            }
        }
    }

    /// One user `Deref` step of a place (a field access through it, or
    /// an explicit `*w`): records the impl's `deref`, and its
    /// `deref_mut` when `DerefMut` holds, for `e` after `before`
    /// builtin derefs; lowering picks by the place's use. Returns the
    /// target type; None when `base` has no written `Deref` impl.
    fn record_place_deref(&mut self, e: ExprId, base: Ty, before: u8, span: Span) -> Option<Ty> {
        let lang = self.p.gx.lang;
        if self.tys.local_adt(base).is_none() {
            return None;
        }
        let (f, target, args) = self.user_deref_fn_lit(lang.deref, base, "deref", span, true)?;
        let (f_mut, args_mut) = match self.user_deref_fn_lit(lang.deref_mut, base, "deref_mut", span, true) {
            Some((g, _, a)) => (Some(g), a),
            None => (None, Vec::new()),
        };
        let target_ref = self.tys.mk_ref(false, target);
        let idx = self.out.deref_recv.len();
        // Place steps record outermost first.
        let depth = self.out.deref_recv.iter().filter(|(x, _)| *x == e).count() as u8;
        self.out.deref_recv.push((e, DerefRecv { depth, before, f, args: Vec::new(), f_mut, args_mut: Vec::new(), mutable: false, target_ref }));
        self.place_step_exprs.insert(e, ());
        let is_template = |cx: &Self, f: LocalDefId| cx.p.gx.fn_templates.get(f.0 as usize).is_some_and(|t| t.is_some());
        if is_template(self, f) {
            self.deref_sites.push((DerefTable::Recv, idx, false, f, args));
        }
        if let Some(g) = f_mut
            && is_template(self, g)
        {
            self.deref_sites.push((DerefTable::Recv, idx, true, g, args_mut));
        }
        Some(target)
    }

    /// A deref coercion through user `Deref` impls (rustc's coercion
    /// autoderef): from `found` (a reference to a user type, through
    /// any reference layers) by one or more impl steps to `&y` (`&mut
    /// y` through `DerefMut` when `mutable`). Records the steps on `e`
    /// and returns the coercion; None when no chain reaches `y`
    /// (nothing is bound then).
    fn user_deref_coercion(&mut self, e: ExprId, found: Ty, y: Ty, mutable: bool, span: Span) -> Option<Coerce> {
        let lang = self.p.gx.lang;
        let mut t = self.resolve(found);
        let mut before = 0u8;
        while let TyKind::Ref(_, _, inner) = self.kind(t) {
            t = self.resolve(inner);
            before += 1;
        }
        if before == 0 || self.tys.local_adt(t).is_none() {
            return None;
        }
        // (before, fn, args, target) per step.
        let mut steps: Vec<(u8, LocalDefId, Vec<GenericArg>, Ty)> = Vec::new();
        let snap = self.snapshot_vars();
        let obl_len = self.obl_len();
        for _ in 0..4 {
            let (trait_def, fname) = if mutable { (lang.deref_mut, "deref_mut") } else { (lang.deref, "deref") };
            if self.tys.local_adt(t).is_none() {
                break;
            }
            let Some((f, _, args)) = self.user_deref_fn(trait_def, t, fname, span) else { break };
            // `deref_mut` returns `&mut Target`: the target is the
            // same as `deref`'s.
            let Some((_, target, _)) = self.user_deref_fn(lang.deref, t, "deref", span) else { break };
            steps.push((before, f, args, target));
            let inner_snap = self.snapshot_vars();
            if self.unify(target, y) {
                self.forget_place_steps(e, true);
                let idx0 = self.out.deref_coerce.len();
                for (i, (b, f, args, target)) in steps.into_iter().enumerate() {
                    let target_ref = self.tys.mk_ref(mutable, target);
                    let template = self.p.gx.fn_templates.get(f.0 as usize).is_some_and(|t| t.is_some());
                    self.out.deref_coerce.push((
                        e,
                        DerefRecv { depth: i as u8, before: b, f, args: Vec::new(), f_mut: None, args_mut: Vec::new(), mutable, target_ref },
                    ));
                    if template {
                        self.deref_sites.push((DerefTable::Coerce, idx0 + i, false, f, args));
                    }
                }
                self.place_step_exprs.insert(e, ());
                return Some(Coerce::UserDeref(self.tys.mk_ref(mutable, y)));
            }
            self.rollback_vars(inner_snap);
            // The last user step reaches a `Vec<T>` or `String`: its
            // builtin deref to `[T]` or `str` ends the chain.
            let tail_ok = match (self.kind(self.resolve(target)), self.kind(self.resolve(y))) {
                (_, TyKind::Slice(want)) => self.tys.vec_elem(self.resolve(target)).is_some_and(|el| self.unify(el, want)),
                (_, TyKind::Str) => !mutable && self.tys.is_string_ty(self.resolve(target)),
                _ => false,
            };
            if tail_ok {
                self.forget_place_steps(e, true);
                let idx0 = self.out.deref_coerce.len();
                for (i, (b, f, args, target)) in steps.into_iter().enumerate() {
                    let target_ref = self.tys.mk_ref(mutable, target);
                    let template = self.p.gx.fn_templates.get(f.0 as usize).is_some_and(|t| t.is_some());
                    self.out.deref_coerce.push((
                        e,
                        DerefRecv { depth: i as u8, before: b, f, args: Vec::new(), f_mut: None, args_mut: Vec::new(), mutable, target_ref },
                    ));
                    if template {
                        self.deref_sites.push((DerefTable::Coerce, idx0 + i, false, f, args));
                    }
                }
                self.place_step_exprs.insert(e, ());
                return Some(Coerce::UserDerefTail(self.tys.mk_ref(mutable, y)));
            }
            self.rollback_vars(inner_snap);
            t = target;
            before = 1;
        }
        self.rollback_vars(snap);
        self.obl_truncate(obl_len);
        None
    }

    /// The written impl of `Deref` (or `DerefMut`) for `base`: its
    /// `fname` fn, the target type, and the impl args. None for no
    /// impl or a core one.
    /// One written `Index` (and, when it holds, `IndexMut`) impl
    /// for `base[idx]`: records the impl fns on `e` and returns the
    /// `Output` type. None when no written impl answers for this
    /// index type (a synthetic impl has no fn to call).
    fn record_trait_index(&mut self, e: ExprId, base: Ty, idx_ty: Ty, span: Span) -> Option<Ty> {
        use crate::traits::index::Synthetic;
        let p = self.p;
        let lang = p.gx.lang;
        // Selection runs with a fresh input (as the method probe
        // does): the written index type can still be an open
        // literal var that only the impl's `Borrow` bound fixes.
        // The picked input then unifies with the written type;
        // any failure rolls the whole pick back.
        // A type with two `Index` impls (indexmap's `Index<&Q>` and
        // `Index<usize>`) is ambiguous at a fresh input, so the written
        // index type is tried first, then the fresh input.
        let pick_with = |cx: &mut Self, trait_def: DefId, fname: &str, written: bool| -> Option<(LocalDefId, Ty, Vec<GenericArg>)> {
            let snap = cx.snapshot_vars();
            let obl_len = cx.obl_len();
            let found = (|cx: &mut Self| -> Option<(LocalDefId, Ty, Vec<GenericArg>)> {
                let input = if written { cx.deep(idx_ty) } else { cx.new_var(false) };
                let args = cx.tys.intern_args(&[GenericArg::Ty(base), GenericArg::Ty(input)]);
                let tr = TraitRef { def: trait_def, args, bindings: EMPTY_BINDINGS };
                let Selection::Impl { id, args: impl_args, .. } = cx.select_obligation_at(tr, span, 0) else { return None };
                let rec = p.gx.index.get(id).clone();
                if rec.synthetic != Synthetic::None {
                    return None;
                }
                let input = cx.deep(input);
                if !cx.unify(input, idx_ty) {
                    return None;
                }
                let f = rec.items.iter().copied().find_map(|d| p.local_def(d.hash).filter(|&l| p.name(p.fn_info(l).name) == fname))?;
                let ret = p.fn_info(f).ret;
                let ret = if impl_args.is_empty() { ret } else { subst(&mut cx.tys, ret, &impl_args) };
                let ret = cx.normalize_here(ret);
                let TyKind::Ref(_, _, out) = cx.kind(ret) else { return None };
                let out = cx.resolve(out);
                if matches!(cx.kind(out), TyKind::Error) {
                    return None;
                }
                Some((f, out, impl_args))
            })(cx);
            if found.is_none() {
                cx.rollback_vars(snap);
                cx.obl_truncate(obl_len);
            }
            found
        };
        let pick = |cx: &mut Self, trait_def: DefId, fname: &str| pick_with(cx, trait_def, fname, true).or_else(|| pick_with(cx, trait_def, fname, false));
        let (f, output, args) = pick(self, lang.index, "index")?;
        let (f_mut, args_mut) = match pick(self, lang.index_mut, "index_mut") {
            Some((g, _, a)) => (Some(g), a),
            None => (None, Vec::new()),
        };
        let idx = self.out.index_recv.len();
        self.out.index_recv.push((e, IndexRecv { f, args: Vec::new(), f_mut, args_mut: Vec::new() }));
        self.place_step_exprs.insert(e, ());
        let is_template = |cx: &Self, f: LocalDefId| cx.p.gx.fn_templates.get(f.0 as usize).is_some_and(|t| t.is_some());
        if is_template(self, f) {
            self.deref_sites.push((DerefTable::Index, idx, false, f, args));
        }
        if let Some(g) = f_mut
            && is_template(self, g)
        {
            self.deref_sites.push((DerefTable::Index, idx, true, g, args_mut));
        }
        Some(output)
    }

    fn user_deref_fn(&mut self, trait_def: DefId, base: Ty, fname: &str, span: Span) -> Option<(LocalDefId, Ty, Vec<GenericArg>)> {
        self.user_deref_fn_lit(trait_def, base, fname, span, false)
    }

    /// `user_deref_fn`; with `lit_ok` the target may be a literal's
    /// open `{integer}` or `{float}` type (`*m` on a
    /// `ManuallyDrop::new(5)`), as in rustc. Only place derefs pass
    /// it: a method lookup on an open literal type is rustc's E0689.
    fn user_deref_fn_lit(&mut self, trait_def: DefId, base: Ty, fname: &str, span: Span, lit_ok: bool) -> Option<(LocalDefId, Ty, Vec<GenericArg>)> {
        use crate::traits::index::Synthetic;
        let p = self.p;
        let args = self.tys.intern_args(&[GenericArg::Ty(base)]);
        let tr = TraitRef { def: trait_def, args, bindings: EMPTY_BINDINGS };
        let Selection::Impl { id, args: impl_args, .. } = self.select_obligation_at(tr, span, 0) else { return None };
        let rec = p.gx.index.get(id).clone();
        if rec.synthetic != Synthetic::None {
            return None;
        }
        let f = rec.items.iter().copied().find_map(|d| p.local_def(d.hash).filter(|&l| p.name(p.fn_info(l).name) == fname))?;
        let ret = p.fn_info(f).ret;
        let ret = if impl_args.is_empty() { ret } else { subst(&mut self.tys, ret, &impl_args) };
        let ret = self.normalize_here(ret);
        let TyKind::Ref(_, _, target) = self.kind(ret) else { return None };
        let target = self.resolve(target);
        match self.kind(target) {
            TyKind::Infer(v) if lit_ok && v.1 != InferKind::General => {}
            TyKind::Infer(_) | TyKind::Error => return None,
            _ => {}
        }
        Some((f, target, impl_args))
    }

    /// rustc's expected inputs for a closure argument: a generic call
    /// that returns its own type variable (`fn with<R>(f: impl FnOnce()
    /// -> R) -> R`) under an expected type fixes that variable first, so
    /// a closure body that needs its output type sees it (`let s: u32 =
    /// with(|| v.iter().sum())`). The same fixing binds a parameter
    /// that only rides inside the return type (`LazyCell<T, F>` from
    /// `LazyCell::new(f)`): under `LazyCell<T, fn() -> T>` the `F` is
    /// the fn pointer type before the argument checks, so a closure
    /// or fn item argument coerces to it instead of binding `F` to
    /// its own item type. Only when the return type still holds a
    /// variable, an argument is a closure or a path (a fn item), and
    /// the expectation has no dyn, where the result could still
    /// coerce (rustc's own expectation is not binding there). A lazy
    /// cell never coerces, so its dyn value type does not count
    /// (`LazyLock<Box<dyn Fn()>>`). A failed unify rolls back, so a
    /// coercion-only match keeps its old path.
    pub(super) fn expected_output_first(&mut self, ret: Ty, expected: Option<Ty>, args: &[ExprId]) {
        let Some(want) = expected else { return };
        let ret_deep = self.deep(ret);
        if !self.tys.flags(ret_deep).contains_infer()
            || !args.iter().any(|&a| matches!(self.p.ast.expr(a), Expr::Closure { .. } | Expr::Path(_)))
        {
            return;
        }
        let want = self.deep(want);
        let p = self.p;
        let lazy = self.tys.local_adt(want).is_some_and(|a| matches!(p.display_path(p.adt(a).name).as_str(), "std::sync::LazyLock" | "core::cell::LazyCell"));
        if (!lazy && object::mentions_dyn(&self.tys, want)) || matches!(self.kind(want), TyKind::Infer(_) | TyKind::Never | TyKind::Error) {
            return;
        }
        let mut open = Vec::new();
        self.unbound_vars(ret_deep, &mut open);
        let whole = matches!(self.kind(ret_deep), TyKind::Infer(_));
        let snap = self.snapshot_vars();
        let obl_len = self.obl_len();
        if self.unify(ret, want) {
            self.expect_only_vars.extend(open.into_iter().map(|v| (v, whole)));
        } else {
            self.rollback_vars(snap);
            self.obl_truncate(obl_len);
        }
    }

    /// The pointees of an owning unsizing (`Box<T>` to `Box<dyn Tr>`,
    /// `Rc<T>` to `Rc<dyn Tr>`, ARCH 2.8; `Arc<[T; N]>` to `Arc<[T]>`,
    /// w-unsized): the same smart pointer on both sides, a dyn target
    /// (or a slice target from an array), and a known source.
    fn owning_unsize_parts(&self, found: Ty, expected: Ty) -> Option<(Ty, Ty)> {
        let (f, e) = (self.resolve(found), self.resolve(expected));
        if self.tys.builtin_of(f) != self.tys.builtin_of(e) {
            return None;
        }
        // `rc::Weak<T>` and `sync::Weak<T>` to a `Weak<dyn Tr>` too
        // (std's `CoerceUnsized` impls), only to a dyn value.
        let weak = |t: Ty| self.tys.weak_elem(t).or_else(|| self.tys.arc_weak_elem(t));
        if let (Some(x), Some(y)) = (weak(f), weak(e)) {
            let (x, y) = (self.resolve(x), self.resolve(y));
            let known = !matches!(self.kind(x), TyKind::Infer(v) if !v.is_int() && !v.is_float());
            return (known && matches!(self.kind(y), TyKind::Dyn(..))).then_some((x, y));
        }
        let (x, y) = match (self.tys.boxed_elem(f), self.tys.boxed_elem(e)) {
            (Some(x), Some(y)) => (x, y),
            _ => (self.tys.rc_elem(f)?, self.tys.rc_elem(e)?),
        };
        let (mut x, mut y) = (self.resolve(x), self.resolve(y));
        // `Rc<RefCell<S>>` to `Rc<RefCell<dyn Tr>>` (and `Arc<Mutex<S>>`
        // to `Arc<Mutex<dyn Tr>>`): the cell's value unsizes.
        let inner = |t: Ty| self.tys.refcell_elem(t).map(|e| (0u8, e)).or_else(|| self.tys.lock_elem(t).filter(|l| l.0 == crate::ty::sync::SyncTy::Mutex).map(|l| (1u8, l.1)));
        if let (Some((xk, xe)), Some((yk, ye))) = (inner(x), inner(y))
            && xk == yk
        {
            (x, y) = (self.resolve(xe), self.resolve(ye));
            if !matches!(self.kind(y), TyKind::Dyn(..)) {
                return None;
            }
        }
        let known = !matches!(self.kind(x), TyKind::Infer(v) if !v.is_int() && !v.is_float());
        let to_slice = matches!((self.kind(x), self.kind(y)), (TyKind::Array(..), TyKind::Slice(_)));
        (known && (to_slice || matches!(self.kind(y), TyKind::Dyn(..)))).then_some((x, y))
    }

    /// True when `e` borrows a static item (`&S0`): the one reference
    /// lust knows lives for `'static`.
    fn static_borrow(&self, e: ExprId) -> bool {
        match self.p.ast.expr(e) {
            Expr::Ref { raw: false, expr, .. } => matches!(self.out.expr_res[self.ei(*expr)], Res::Static(_)),
            _ => false,
        }
    }

    fn expect_expr(&mut self, e: ExprId, expected: Ty) -> Ty {
        let t = self.expr(e, Some(expected));
        self.coerce_expr(e, t, expected);
        t
    }

    // ---------- Blocks and statements ----------

    fn block(&mut self, b: ast::BlockId, expected: Option<Ty>) -> Ty {
        let block = self.p.ast.block(b);
        let scope = self.scopes.len();
        {
            let mut layer: Vec<((Sym, CtxtId), u32)> = Vec::new();
            let mut use_idxs: Vec<u32> = Vec::new();
            for stmt in &block.stmts {
                if let Stmt::Item(idx) = stmt {
                    if matches!(self.p.ast.stmt_items[*idx as usize].kind, ItemKind::Use(_)) {
                        use_idxs.push(*idx);
                    }
                    if let Some(name) = match &self.p.ast.stmt_items[*idx as usize].kind {
                        ItemKind::Fn(d) => Some((d.name, d.name_span.ctxt)),
                        ItemKind::Const(c) => c.name.map(|n| (n, c.name_span.ctxt)),
                        ItemKind::Static(st) => Some((st.name, st.name_span.ctxt)),
                        _ => None,
                    } {
                        layer.push((name, *idx));
                    }
                }
            }
            self.item_scopes.push(layer);
            self.item_scope_starts.push(self.scopes.len());
            let (defs, paths) = use_item_trait_layers(self.p, &use_idxs);
            self.trait_scopes.push(defs);
            self.std_trait_scopes.push(paths);
            let type_layer: Vec<u32> = block
                .stmts
                .iter()
                .filter_map(|s| if let Stmt::Item(idx) = s { Some(*idx) } else { None })
                .filter(|idx| self.p.body_type_items.contains_key(idx))
                .collect();
            self.type_layers.push(type_layer);
            self.refresh_type_overlay();
        }
        let mut diverges = false;
        for stmt in &block.stmts {
            match stmt {
                Stmt::Let { pat, ty, init, els, .. } => {
                    let ty_ann = ty;
                    let annotated = ty.filter(|&t| self.annotation_has_regions(t));
                    let declared = ty.map(|t| if annotated.is_some() { self.resolve_annotation(t) } else { self.resolve_written(t) });
                    let ty = match (declared, init) {
                        (Some(d), Some(init)) => {
                            let t = self.expr(*init, Some(d));
                            self.coerce_expr(*init, t, d);
                            if self.kind(t) == TyKind::Never {
                                diverges = true;
                            }
                            d
                        }
                        (Some(d), None) => d,
                        (None, Some(init)) => {
                            let t = self.expr(*init, None);
                            if self.kind(t) == TyKind::Never {
                                diverges = true;
                            }
                            t
                        }
                        (None, None) => self.new_var(false),
                    };
                    // The `else` block runs when the pattern does not
                    // match, so it is checked before the pattern binds
                    // anything (its names are not in scope there), and
                    // it must diverge, as in Rust.
                    if let Some(els_b) = els {
                        let et = self.block(*els_b, None);
                        if self.kind(et) != TyKind::Never {
                            self.err(
                                "L0110",
                                self.p.ast.block(*els_b).span,
                                "the `else` block of a `let...else` must diverge",
                                "End it with `return`, `break`, `continue`, or a panic.",
                            );
                        }
                    }
                    // A local is a value: a written type must be
                    // `Sized` when the let stores one, by an
                    // initializer or a by-value binding (`let x:
                    // str;`). A bare `let _: str;` stores nothing.
                    if let Some(w) = declared.and(*ty_ann)
                        && (init.is_some() || self.pat_binds_value(*pat))
                    {
                        self.require_sized(ty, self.p.ast.ty_span(w));
                    }
                    match self.p.ast.pat(*pat) {
                        // A plain name that resolves to a const, static,
                        // or unit path is a pattern, not a fresh binding:
                        // check it like any destructuring let, which
                        // rejects it as refutable where rustc does.
                        Pat::Binding { name, mutable: false, by_ref: false }
                            if self.lookup(*name, self.p.ast.pat_span(*pat).ctxt).is_none()
                                && (self.names_pattern_item(*name)
                                    || (*name == self.p.known.None && self.prelude_variant(*name, self.p.ast.pat_span(*pat).ctxt))) =>
                        {
                            if init.is_none() {
                                let s = self.p.ast.pat_span(*pat);
                                self.errs.push(unsupported(s, "destructuring in `let` without an initializer"));
                            } else {
                                // A `let...else` allows refutable
                                // patterns, like a match arm does.
                                self.pattern(*pat, ty, els.is_some());
                                if !self.pat_always_matches_at(*pat, init.is_some_and(|i| self.place_behind_deref(i))) {
                                    let s = self.p.ast.pat_span(*pat);
                                    if els.is_none() {
                                        self.err(
                                            "L0110",
                                            s,
                                            "refutable pattern in local binding",
                                            "Use `match`, `if let`, or `let...else` for a pattern that can fail.",
                                        );
                                    }
                                }
                            }
                        }
                        Pat::Binding { name, mutable, by_ref } => {
                            let (name, mutable, by_ref) = (*name, *mutable, *by_ref);
                            let span = self.p.ast.pat_span(*pat);
                            if self.prelude_variant(name, span.ctxt) {
                                self.prelude_variant_binding_err(name, span);
                            }
                            self.binding_shadows_item(name, self.p.ast.pat_span(*pat), !mutable && !by_ref);
                            let lty = if by_ref { self.tys.mk_ref(mutable, ty) } else { ty };
                            // The binding's hygiene key is the pattern name's
                            // own context, not the `let` keyword's (ARCH 6.3).
                            let l = self.add_local(name, lty, mutable && !by_ref, self.p.ast.pat_span(*pat));
                            let pi = (pat.0 - self.out.pat_base) as usize;
                            self.out.pat_ty[pi] = ty;
                            let mode = if by_ref { BindMode::Ref(mutable) } else { BindMode::Move };
                            self.out.pat_res[pi] = PatRes::Binding { local: l, mode };
                        }
                        Pat::Wild => {
                            let pi = (pat.0 - self.out.pat_base) as usize;
                            self.out.pat_ty[pi] = ty;
                        }
                        _ => {
                            if init.is_none() {
                                let s = self.p.ast.pat_span(*pat);
                                self.errs.push(unsupported(s, "destructuring in `let` without an initializer"));
                            } else {
                                // A `let...else` allows refutable
                                // patterns, like a match arm does.
                                self.pattern(*pat, ty, els.is_some());
                                if !self.pat_always_matches_at(*pat, init.is_some_and(|i| self.place_behind_deref(i))) {
                                    let s = self.p.ast.pat_span(*pat);
                                    if els.is_none() {
                                        self.err(
                                            "L0110",
                                            s,
                                            "refutable pattern in local binding",
                                            "Use `match`, `if let`, or `let...else` for a pattern that can fail.",
                                        );
                                    }
                                }
                            }
                        }
                    }
                    if let Some(t) = annotated {
                        self.record_annotation(*pat, t);
                    } else if let Some(&t) = ty_ann.as_ref()
                        && generics::qpath_names_lifetime(&self.p.ast, &self.p.interner, t)
                    {
                        self.annotation_outlives(t);
                    }
                }
                // Body items and statement macros are rejected by the parser today.
                Stmt::Item(_) | Stmt::Macro { .. } => {}
                Stmt::Expr { expr, semi, .. } => {
                    let saved = std::mem::replace(&mut self.stmt_expr, semi.then_some(*expr));
                    let t = self.expr(*expr, if *semi { None } else { Some(UNIT) });
                    self.stmt_expr = saved;
                    if self.kind(t) == TyKind::Never {
                        diverges = true;
                    } else if !semi && !self.unify(t, UNIT) {
                        let s = self.span(*expr);
                        self.err("L0110", s, format!("expected `()`, found `{}`", self.tn(t)), "Add a `;` after this expression.");
                    }
                }
            }
        }
        let t = match block.tail {
            Some(tail) => self.expr(tail, expected),
            None if diverges => NEVER,
            None => UNIT,
        };
        self.scopes.truncate(scope);
        self.item_scopes.pop();
        self.item_scope_starts.pop();
        self.trait_scopes.pop();
        self.std_trait_scopes.pop();
        self.type_layers.pop();
        self.refresh_type_overlay();
        t
    }

    /// A `let` annotation that names a lifetime (W-BORROW): resolved like
    /// any written type, with explicit lifetimes allowed, since
    /// `record_annotation` keeps their regions for the borrow checker.
    fn resolve_annotation(&mut self, t: ast::TyId) -> Ty {
        let saved = (self.body_scope.annotation, self.body_scope.fn_ptr_free);
        self.body_scope.annotation = true;
        self.body_scope.fn_ptr_free = true;
        let ty = self.resolve_written(t);
        (self.body_scope.annotation, self.body_scope.fn_ptr_free) = saved;
        ty
    }

    /// Records the regioned form of `let` annotation `t` for each binding
    /// pattern `pat` covers (W-BORROW): `'static` and the fn's named
    /// lifetimes keep their regions, elided ones are free. A pattern
    /// shape this cannot follow (by-ref bindings, `_`, nested patterns
    /// other than tuples) would drop the annotation's constraints, so it is
    /// a reject (L0203).
    fn record_annotation(&mut self, pat: ast::PatId, t: ast::TyId) {
        let p = self.p;
        let Some(r) = self.regioned_annotation(t, Region::Erased, true) else { return };
        // The annotation must be well-formed under the fn's implied
        // bounds (`&'a T` needs `T: 'a`, rustc E0309).
        let env = self.env();
        if let Some(sig) = p.regions.body_sig(p, self.fid)
            && let Some(d) = crate::check::outlives::check_body_ty(p, &mut self.tys, sig, env, r, p.ast.ty_span(t))
        {
            self.errs.push(d);
        }
        if !self.annotate_pat(pat, r) {
            let s = p.ast.pat_span(pat);
            self.err(
                "L0203",
                s,
                "an explicit lifetime in the annotation of this pattern is not supported yet",
                "Bind a plain name (`let x: T = ..`), or a tuple of names.",
            );
        }
    }

    /// Records the regioned form of cast target `t` for cast `e`
    /// (`Checked::cast_annotations`), after the same outlives check as a
    /// `let` annotation.
    fn record_cast_annotation(&mut self, e: ExprId, t: ast::TyId) {
        let p = self.p;
        let Some(r) = self.regioned_annotation(t, Region::Erased, true) else { return };
        let env = self.env();
        if let Some(sig) = p.regions.body_sig(p, self.fid)
            && let Some(d) = crate::check::outlives::check_body_ty(p, &mut self.tys, sig, env, r, p.ast.ty_span(t))
        {
            self.errs.push(d);
        }
        self.out.cast_annotations.push((e, r));
    }

    /// The outlives check of a `let` annotation whose lifetimes sit only in
    /// a qualified path (`generics::qpath_names_lifetime`): the type must be
    /// well-formed under the fn's implied bounds (rustc E0309). The borrow
    /// checker does not see these regions (the local has the erased type).
    fn annotation_outlives(&mut self, t: ast::TyId) {
        let p = self.p;
        let Some(r) = self.regioned_annotation(t, Region::Erased, false) else { return };
        let env = self.env();
        if let Some(sig) = p.regions.body_sig(p, self.fid)
            && let Some(d) = crate::check::outlives::check_body_ty(p, &mut self.tys, sig, env, r, p.ast.ty_span(t))
        {
            self.errs.push(d);
        }
    }

    /// The regioned form of an annotation that names lifetimes (W-BORROW):
    /// `'static` and the fn's named lifetimes keep their regions, elided
    /// ones are free (`Region::Erased`). None after reporting `_` inside
    /// the annotation (no region form without inference, L0203).
    fn regioned_annotation(&mut self, t: ast::TyId, elided: Region, report: bool) -> Option<Ty> {
        let p = self.p;
        let cx = p.gx.resolve_cx(&p.type_names, &p.aliases);
        let mut sc = self.body_scope.clone();
        sc.annotation = true;
        sc.fn_ptr_free = true;
        sc.infer_cell = None;
        sc.regions = generics::RegionMode::Keep { next: None, elided: Some(elided) };
        match generics::resolve_scoped(&p.ast, &p.interner, &p.known, &cx, &mut self.tys, t, &sc) {
            Ok(r) => Some(r),
            Err(_) if !report => None,
            Err(_) => {
                let s = p.ast.ty_span(t);
                self.err("L0203", s, "an explicit lifetime in a type annotation with `_` is not supported yet", "Write the full type, or drop the lifetime.");
                None
            }
        }
    }

    fn annotate_pat(&mut self, pat: ast::PatId, r: Ty) -> bool {
        let pi = (pat.0 - self.out.pat_base) as usize;
        match (self.p.ast.pat(pat), self.out.pat_res.get(pi).copied()) {
            (Pat::Binding { .. }, Some(PatRes::Binding { local, mode: BindMode::Move })) => {
                self.out.annotations.push((local, r));
                true
            }
            (Pat::Tuple(elems), _) => match self.tys.kind(r) {
                TyKind::Tuple(ts) => {
                    let parts: Vec<Ty> = self.tys.tys_of(ts).to_vec();
                    let elems = elems.clone();
                    elems.len() == parts.len() && elems.iter().zip(parts).all(|(&e, t)| self.annotate_pat(e, t))
                }
                _ => false,
            },
            _ => false,
        }
    }

    fn resolve_written(&mut self, t: ast::TyId) -> Ty {
        let p = self.p;
        let written_span = p.ast.ty_span(t);
        self.written_names(t);
        let cx = p.gx.resolve_cx(&p.type_names, &p.aliases);
        let span = p.ast.ty_span(t);
        let resolved = generics::resolve_scoped(&p.ast, &p.interner, &p.known, &cx, &mut self.tys, t, &self.body_scope.clone());
        if resolved.is_ok() {
            for (e, want) in crate::check::const_body::written_anon_consts(p, t) {
                let want = want.map(|w| w.ty());
                self.type_anon_const(e, want);
            }
        }
        match resolved {
            Ok(t) => {
                let t = self.instantiate_infers(t);
                if let Some(d) = object::dyn_type_diag(p, &self.tys, t, span) {
                    self.errs.push(d);
                }
                // A written type must be well-formed: the
                // bounds of every local Adt it applies, and the
                // trait ref of every projection in it as written,
                // become obligations here (rustc E0277 at the type).
                let n = self.normalize_here(t);
                if n != t {
                    self.wf_check_written(t, written_span);
                }
                self.wf_check_written(n, written_span);
                n
            }
            Err(d) => {
                self.errs.push(d);
                ERROR
            }
        }
    }

    /// Records a binding read of every name a written type resolves
    /// through: each path's type name, in generic arguments, bounds, fn
    /// pointer and qualified-path parts too, and each plain const path in
    /// an array length or const argument (a value read: a const's `Sig`
    /// folds its value). Resolution reads them with no other recorded read,
    /// so an alias inside `Option<m::A>` or the `N` of `[u8; N]` that
    /// changes under an unchanged body checks that body again (Sol's
    /// const-body review round 2: false accepts in fn bodies too). Primitive
    /// names and `Self` are scope layers, not bindings.
    fn written_names(&mut self, t: ast::TyId) {
        let p = self.p;
        match p.ast.ty(t) {
            ast::TyExpr::Path(segs) => self.written_path(segs, Namespace::Type),
            ast::TyExpr::Ref { inner, .. } | ast::TyExpr::Slice(inner) | ast::TyExpr::Ptr { inner, .. } | ast::TyExpr::Paren(inner) => {
                self.written_names(*inner)
            }
            ast::TyExpr::Tuple(ts) => ts.iter().for_each(|&e| self.written_names(e)),
            ast::TyExpr::Array { inner, len } => {
                self.written_names(*inner);
                self.written_const(*len);
            }
            ast::TyExpr::FnPtr { inputs, ret, .. } => {
                inputs.iter().for_each(|i| self.written_names(i.ty));
                ret.iter().for_each(|&r| self.written_names(r));
            }
            ast::TyExpr::Dyn { bounds, .. } | ast::TyExpr::ImplTrait { bounds, .. } => self.written_bounds(bounds),
            ast::TyExpr::QPath { self_ty, trait_path, segs } => {
                self.written_names(*self_ty);
                self.written_path(trait_path, Namespace::Type);
                self.written_args(segs);
            }
            ast::TyExpr::Unit | ast::TyExpr::Never | ast::TyExpr::Infer | ast::TyExpr::MacroCall(_) => {}
        }
    }

    /// `written_names` for one path: its name (a single segment, or the
    /// last one after `std`), then its generic arguments.
    fn written_path(&mut self, segs: &[ast::PathSeg], ns: Namespace) {
        let p = self.p;
        let seg = if segs.len() > 1 && segs[0].name == p.known.std {
            segs.last()
        } else if segs.len() == 1 {
            segs.first()
        } else {
            None
        };
        if let Some(seg) = seg {
            let name = seg.name;
            if p.known.int_ty(name).is_none() && name != p.known.bool && name != p.known.char && name != p.known.str && name != p.known.self_type {
                self.binding(ns, name);
            }
        }
        self.written_args(segs);
    }

    fn written_args(&mut self, segs: &[ast::PathSeg]) {
        for seg in segs {
            match &seg.args {
                ast::GenericArgs::Angle(args) => {
                    for a in args {
                        match a {
                            ast::GenericArg::Type(t) => self.written_names(*t),
                            ast::GenericArg::Const(e) => self.written_const(*e),
                            ast::GenericArg::Binding { kind, .. } => match kind {
                                ast::BindingKind::EqTy(t) => self.written_names(*t),
                                ast::BindingKind::EqConst(e) => self.written_const(*e),
                                ast::BindingKind::Constraint(b) => self.written_bounds(b),
                            },
                            ast::GenericArg::Lifetime(_) => {}
                        }
                    }
                }
                ast::GenericArgs::Parenthesized { inputs, output } => {
                    inputs.iter().for_each(|&t| self.written_names(t));
                    output.iter().for_each(|&t| self.written_names(t));
                }
                ast::GenericArgs::None => {}
            }
        }
    }

    fn written_bounds(&mut self, bounds: &[ast::TraitBound]) {
        for b in bounds {
            if let ast::TraitBound::Trait { trait_ref, .. } = b {
                self.written_path(&trait_ref.path, Namespace::Type);
            }
        }
    }

    /// A plain const path (`N`, or `{ N }`) in a written type: a value
    /// binding read. Other const expressions are anonymous consts, checked
    /// with their own reads (`type_anon_const`).
    fn written_const(&mut self, e: ast::ExprId) {
        let ast = &self.p.ast;
        let path = match ast.expr(e) {
            ast::Expr::Path(segs) => Some(segs),
            ast::Expr::Block(b) => {
                let b = ast.block(*b);
                b.tail.filter(|_| b.stmts.is_empty()).and_then(|t| match ast.expr(t) {
                    ast::Expr::Path(segs) => Some(segs),
                    _ => None,
                })
            }
            _ => None,
        };
        if let Some(segs) = path.filter(|s| s.len() == 1) {
            self.binding(Namespace::Value, segs[0].name);
        }
    }

    /// Queues the well-formedness obligations of one body
    /// type: for every application of a local Adt inside it,
    /// the Adt's parameter bounds under the written arguments,
    /// for every projection its trait ref, and for every std
    /// adapter `Iterator` (`generics::adapter_iter_goal`). The parts
    /// `check::sized::parts` names must be `Sized` here (L0110).
    fn wf_check_written(&mut self, t: Ty, span: Span) {
        let generic = self.generic_mode();
        let mut stack: Vec<Ty> = vec![t];
        let mut seen: Vec<Ty> = Vec::new();
        let mut need: Vec<Ty> = Vec::new();
        while let Some(t) = stack.pop() {
            let t = self.deep(t);
            if seen.contains(&t) {
                continue;
            }
            seen.push(t);
            sized::parts(&self.tys, t, &mut |e| need.push(e));
            match self.tys.kind(t) {
                TyKind::Adt(d, a) => {
                    let argv: Vec<GenericArg> = self.tys.args(a).to_vec();
                    if generic && let Some(idx) = self.p.gx.adt_info.iter().position(|&(def, _)| def == d) {
                        let preds = self.p.gx.adt_generics[idx].predicates.clone();
                        if !preds.is_empty() {
                            self.push_predicates(&preds, &argv, span);
                        }
                    }
                    // A written std adapter must be an iterator here
                    // (`generics::adapter_iter_goal`).
                    if let Some((k, _)) = crate::ty::iter::iter_parts(&self.tys, t)
                        && k.is_adapter()
                    {
                        let args = self.tys.intern_args(&[GenericArg::Ty(t)]);
                        self.obl.push_trait_at(TraitRef { def: self.p.gx.lang.iterator, args, bindings: EMPTY_BINDINGS }, span, 0);
                    }
                    for g in argv {
                        if let Some(e) = g.as_ty() {
                            stack.push(e);
                        }
                    }
                }
                TyKind::Ref(_, _, e) | TyKind::RawPtr(_, e) | TyKind::Slice(e) | TyKind::Array(e, _) => stack.push(e),
                TyKind::Tuple(ts) => stack.extend(self.tys.tys_of(ts).iter().copied()),
                TyKind::FnDef(_, a) | TyKind::Closure(_, a) | TyKind::Opaque(_, a) | TyKind::Projection(_, a) => {
                    if let TyKind::Projection(assoc, _) = self.tys.kind(t)
                        && let Some(def) = self.p.gx.index.trait_of_assoc(assoc.0)
                    {
                        self.obl.push_trait_at(TraitRef { def, args: a, bindings: EMPTY_BINDINGS }, span, 0);
                    }
                    let argv: Vec<GenericArg> = self.tys.args(a).to_vec();
                    for g in argv {
                        if let Some(e) = g.as_ty() {
                            stack.push(e);
                        }
                    }
                }
                TyKind::FnPtr(sig) => {
                    let b = self.tys.sig(sig);
                    stack.extend(self.tys.tys_of(b.value.inputs).iter().copied());
                    stack.push(b.value.output);
                }
                TyKind::Dyn(b, _) => {
                    if let Some(pr) = self.tys.dyn_bounds(b).principal {
                        stack.extend(self.tys.args(pr.value.args).iter().skip(1).filter_map(|g| g.as_ty()));
                    }
                }
                _ => {}
            }
        }
        for e in need {
            self.require_sized(e, span);
        }
    }

    /// True when a pattern binds some part by value (a binding
    /// without `ref`, anywhere inside it).
    fn pat_binds_value(&self, pat: PatId) -> bool {
        match self.p.ast.pat(pat) {
            Pat::Binding { by_ref, .. } => !by_ref,
            Pat::At { by_ref, inner, .. } => !by_ref || self.pat_binds_value(*inner),
            Pat::TupleStruct { elems, .. } | Pat::Tuple(elems) | Pat::Or(elems) => elems.iter().any(|&e| self.pat_binds_value(e)),
            Pat::Struct { fields, .. } => fields.iter().any(|&(_, s)| self.pat_binds_value(s)),
            Pat::Slice { prefix, middle, suffix } => {
                prefix.iter().chain(suffix.iter()).any(|&s| self.pat_binds_value(s)) || middle.is_some_and(|m| self.pat_binds_value(m))
            }
            Pat::Ref { inner, .. } | Pat::Paren(inner) => self.pat_binds_value(*inner),
            _ => false,
        }
    }

    /// Reports L0110 when `t` is not `Sized` here (a value
    /// position: a `let` binding, a closure param or return).
    fn require_sized(&mut self, t: Ty, span: Span) {
        if !self.sized_ok(t) {
            let d = sized::unsized_diag(self.p, &self.tys, t, span);
            self.errs.push(d);
        }
    }

    /// Instantiates one fn template at a call site: fresh
    /// variables for its parameters (explicit turbofish types
    /// where written), the substituted signature, bound
    /// obligations queued, and the site recorded for mono.
    /// Returns (params, ret, args).
    fn instantiate_template(
        &mut self,
        e: ExprId,
        template: LocalDefId,
        generics: &Generics,
        explicit: &[Option<GenericArg>],
        span: Span,
    ) -> (Vec<Ty>, Ty, Vec<GenericArg>) {
        let p = self.p;
        let info = p.fn_info(template);
        // More written generic arguments than the item has
        // parameters is an arity error (rustc E0107); `explicit`
        // is aligned to `generics.params` at every call site. The
        // params of `impl Trait` arguments (`impl#N`, appended last)
        // take no written argument.
        let declared = generics.params.iter().filter(|g| !self.name(g.name).starts_with("impl#")).count();
        if explicit.len() > declared {
            self.err("L0107", span, format!("too many generic arguments: this item takes {declared}"), "Remove the extra arguments.");
        }
        let mut args: Vec<GenericArg> = Vec::with_capacity(generics.params.len());
        for (i, param) in generics.params.iter().enumerate() {
            let given = explicit.get(i).copied().flatten();
            // A written argument of the wrong kind (a type where a
            // const parameter sits, or the reverse) is an error,
            // never a silent substitution.
            let given = match (given, &param.kind) {
                (Some(GenericArg::Ty(_)), ParamKind::Type)
                | (Some(GenericArg::Const(_)), ParamKind::Const(_))
                | (Some(GenericArg::Lifetime(_)), ParamKind::Lifetime)
                | (None, _) => given,
                (Some(_), _) => {
                    self.err(
                        "L0110",
                        span,
                        "generic argument has the wrong kind for its parameter",
                        "Match each argument to its parameter: a type for a type parameter, a const value for a const parameter.",
                    );
                    None
                }
            };
            args.push(match (given, &param.kind) {
                (Some(g), _) => g,
                (None, ParamKind::Type) => GenericArg::Ty(self.new_var(false)),
                (None, ParamKind::Lifetime) => GenericArg::Lifetime(Region::Erased),
                (None, ParamKind::Const(_)) => GenericArg::Const(self.fresh_const_var()),
            });
        }
        if self.check_const_args(generics, &args, span) {
            self.check_written_const_tys(e, generics, explicit, span);
        }
        let params: Vec<Ty> = info.params.iter().map(|&t| subst(&mut self.tys, t, &args)).collect();
        let ret = subst(&mut self.tys, info.ret, &args);
        let ret = self.callee_ret(ret);
        let preds = generics.predicates.clone();
        let fn_bounds = p.regions.fns.get(&template).map(|s| s.fn_bounds.clone()).unwrap_or_default();
        self.push_predicates_with(&preds, &args, span, &fn_bounds);
        self.generic_sites.push((self.ei(e), template, args.clone()));
        (params, ret, args)
    }

    /// The explicit generic arguments written on a call path
    /// (`f::<u8, _>(..)`), resolved in this body's scope and
    /// aligned to parameter positions. Unwritten positions are
    /// None.
    /// Checks written const generic arguments against their params'
    /// declared types (rustc E0308, and the out-of-range literal error):
    /// an integer in the type's range, a bool, a char, or a const param
    /// of this body with the same declared type. Reports once and
    /// returns false on a misfit.
    fn check_const_args(&mut self, generics: &Generics, args: &[GenericArg], span: Span) -> bool {
        for (param, arg) in generics.params.iter().zip(args) {
            let (ParamKind::Const(want), GenericArg::Const(c)) = (param.kind, *arg) else { continue };
            let want = self.deep(want);
            let fits = match (self.tys.const_kind(self.resolve_const(c)), self.kind(want)) {
                (ConstKind::Int(v), TyKind::Int(it)) => generics::const_int_fits(v, it),
                (ConstKind::Bool(_), TyKind::Bool) | (ConstKind::Char(_), TyKind::Char) => true,
                (ConstKind::Param(i), _) => {
                    let have = match self.p.gx.fn_templates.get(self.fid.0 as usize).and_then(|t| t.as_ref()) {
                        Some(t) => match t.generics.params.get(i as usize).map(|g| g.kind) {
                            Some(ParamKind::Const(t)) => Some(t),
                            _ => None,
                        },
                        None => None,
                    };
                    have.is_none_or(|h| self.deep(h) == want)
                }
                (ConstKind::Infer(_), _) => true,
                _ => false,
            };
            if !fits {
                let tn = self.tn(want);
                self.err(
                    "L0110",
                    span,
                    format!("mismatched types: this const argument is not a value of type `{tn}`"),
                    format!("Write a `{tn}` value in its range."),
                );
                return false;
            }
        }
        true
    }

    /// A braced or literal const generic argument on a call path
    /// (`f::<3>`, `f::<{ -3 }>`, `f::<true>`, `f::<{ N }>`): its value
    /// by the scalar evaluator. A form it cannot evaluate is an error,
    /// never an unwritten argument (that left the instance unmade).
    fn const_call_arg(&mut self, e: ExprId) -> GenericArg {
        let kind = self.const_call_kind(e);
        match kind {
            Some(k) => GenericArg::Const(self.tys.intern_const(k)),
            None => {
                let span = self.span(e);
                self.err(
                    "L0110",
                    span,
                    "this const generic argument form is not supported here",
                    "Write a literal, a const item, or a const param, such as `::<3>`.",
                );
                GenericArg::Const(self.fresh_const_var())
            }
        }
    }

    /// The value of a const generic argument expression (see
    /// `const_call_arg`), or None for a form the evaluator cannot read.
    fn const_call_kind(&mut self, e: ExprId) -> Option<ConstKind> {
        let p = self.p;
        let inner = match p.ast.expr(e) {
            Expr::Block(b) if p.ast.block(*b).stmts.is_empty() => p.ast.block(*b).tail.unwrap_or(e),
            _ => e,
        };
        match p.ast.expr(inner) {
            Expr::Bool(b) => Some(ConstKind::Bool(*b)),
            Expr::Char(c) => Some(ConstKind::Char(*c)),
            Expr::Path(segs)
                // `(N)` is a const operation on the parameter, not
                // the parameter itself; reject like the type forms.
                if segs.len() == 1 && !p.ast.is_parenthesized(inner)
                    && let Some((i, _, val)) = self.const_param(segs[0].name) =>
            {
                Some(val.unwrap_or(ConstKind::Param(i)))
            }
            _ => crate::check::collect::eval_const_int(&p.ast, &p.interner, &p.known, inner).map(|v| ConstKind::Int(v as u128)),
        }
    }

    /// The written forms of a call's turbofish const args against their
    /// params' declared types (`f::<{ 3u8 }>()` or `f::<L>()` with
    /// `const L: u8` for a `usize` param, rustc E0308);
    /// `check_const_args` checks the values. The written args are the
    /// last entries of `explicit` (a method's impl args come first). An
    /// entry that is not the written arg's value is left alone.
    fn check_written_const_tys(&mut self, e: ExprId, generics: &Generics, explicit: &[Option<GenericArg>], span: Span) {
        let p = self.p;
        fn angle(seg: Option<&ast::PathSeg>) -> &[ast::GenericArg] {
            match seg.map(|s| &s.args) {
                Some(ast::GenericArgs::Angle(a)) => a.as_slice(),
                _ => &[],
            }
        }
        let written: &[ast::GenericArg] = match p.ast.expr(e) {
            Expr::MethodCall { generic_args, .. } => generic_args,
            Expr::Call { callee, .. } => match p.ast.expr(*callee) {
                Expr::Path(segs) => angle(segs.last()),
                _ => &[],
            },
            Expr::Path(segs) => angle(segs.last()),
            _ => &[],
        };
        let Some(offset) = explicit.len().checked_sub(written.len()) else { return };
        for (j, w) in written.iter().enumerate() {
            let i = offset + j;
            let (Some(Some(GenericArg::Const(c))), Some(ParamKind::Const(t))) = (explicit.get(i), generics.params.get(i).map(|g| g.kind))
            else {
                continue;
            };
            let t = self.deep(t);
            let Some(want) = generics::ConstScalar::of(&self.tys, t) else { continue };
            let cx = p.gx.resolve_cx(&p.type_names, &p.aliases);
            let fits = match w {
                ast::GenericArg::Const(x) => {
                    if self.const_call_kind(*x).map(|k| self.tys.intern_const(k)) != Some(*c) {
                        continue;
                    }
                    let scope = &self.body_scope;
                    let fits = generics::check_const_expr_ty(&p.ast, &p.interner, &p.known, &cx, &mut self.tys, scope, *x, *c, want, span, "").is_ok();
                    if fits {
                        self.type_anon_const(*x, Some(want.ty()));
                    }
                    fits
                }
                // A bare name in a const position (`f::<L>`).
                ast::GenericArg::Type(t) => match p.ast.ty(*t) {
                    ast::TyExpr::Path(segs) if segs.len() == 1 => {
                        let scope = &self.body_scope;
                        generics::const_name_ty(&p.ast, &p.interner, &p.known, &cx, &mut self.tys, scope, segs[0].name)
                            .is_none_or(|s| s == want)
                    }
                    _ => true,
                },
                _ => true,
            };
            if !fits {
                let tn = self.tn(t);
                self.err(
                    "L0110",
                    span,
                    format!("mismatched types: this const argument is not a value of type `{tn}`"),
                    format!("Write a `{tn}` value, or cast with `as {tn}`."),
                );
                return;
            }
        }
    }

    fn explicit_call_args(&mut self, callee: ExprId) -> Vec<Option<GenericArg>> {
        let p = self.p;
        let ast::Expr::Path(segs) = p.ast.expr(callee) else { return Vec::new() };
        let Some(seg) = segs.last() else { return Vec::new() };
        self.explicit_seg_args(seg)
    }

    /// How many leading template params belong to the parent impl
    /// of an inherent fn (0 for a plain fn).
    pub(super) fn inherent_parent_n(&self, f: LocalDefId) -> usize {
        self.p.gx.inherent_self_pats.get(&f).map_or(0, |(_, g)| g.params.len())
    }

    /// The non-lifetime args written in one segment's angle list, or
    /// None when the segment writes no angle list.
    fn seg_supplied(seg: &ast::PathSeg) -> Option<usize> {
        match &seg.args {
            // An empty turbofish (`g::<>(..)`) supplies nothing and
            // is allowed: every argument is inferred.
            ast::GenericArgs::Angle(a) if !a.is_empty() => {
                Some(a.iter().filter(|x| !matches!(x, ast::GenericArg::Lifetime(_))).count())
            }
            _ => None,
        }
    }

    /// The non-lifetime args written on the last segment of a path
    /// expression, or None when it writes no turbofish.
    fn path_supplied(&self, callee: ExprId) -> Option<usize> {
        match self.p.ast.expr(callee) {
            ast::Expr::Path(segs) | ast::Expr::QPath { segs, .. } => segs.last().and_then(Self::seg_supplied),
            _ => None,
        }
    }

    /// rustc E0107: a written turbofish must supply every parameter
    /// of its segment (the params after `offset`, synthetic `impl#N`
    /// params excluded). `supplied` is None when no turbofish is
    /// written.
    pub(super) fn check_turbofish_min(&mut self, generics: &Generics, offset: usize, supplied: Option<usize>, span: Span) {
        let Some(supplied) = supplied else { return };
        let required = generics.params.iter().skip(offset).filter(|g| !self.name(g.name).starts_with("impl#")).count();
        if supplied < required {
            self.err(
                "L0107",
                span,
                format!("this item takes {required} generic argument(s) but {supplied} were supplied"),
                "Supply every generic argument, or remove the `::<...>` to let them be inferred.",
            );
        }
    }

    /// `check_turbofish_min` for a fn named by a path: the last
    /// segment's turbofish fills only the fn's own params.
    fn check_path_turbofish(&mut self, callee: ExprId, f: LocalDefId, generics: &Generics, span: Span) {
        let supplied = self.path_supplied(callee);
        let offset = self.inherent_parent_n(f);
        self.check_turbofish_min(generics, offset, supplied, span);
    }

    /// The explicit args of an inherent fn named by a path
    /// (`Type::<A>::name::<B>`, fx-option-rest): the type segment's
    /// args fill the impl's params first, the name segment's
    /// turbofish fills only the fn's own (rustc E0107 otherwise, via
    /// `instantiate_template`'s arity check on the aligned list).
    /// For a plain fn this is `explicit_call_args`.
    fn explicit_path_args(&mut self, callee: ExprId, f: LocalDefId) -> Vec<Option<GenericArg>> {
        let p = self.p;
        let Some((_, impl_g)) = p.gx.inherent_self_pats.get(&f) else { return self.explicit_call_args(callee) };
        let parent_n = impl_g.params.len();
        if parent_n == 0 {
            return self.explicit_call_args(callee);
        }
        let ast::Expr::Path(segs) = p.ast.expr(callee) else { return self.explicit_call_args(callee) };
        if segs.len() < 2 {
            return self.explicit_call_args(callee);
        }
        let mut out: Vec<Option<GenericArg>> = vec![None; parent_n];
        for (i, a) in self.explicit_seg_args(&segs[segs.len() - 2]).into_iter().enumerate() {
            if let Some(slot) = out.get_mut(i) {
                *slot = a;
            }
        }
        out.extend(self.explicit_seg_args(&segs[segs.len() - 1]));
        out
    }

    /// The explicit generic args written on one path segment.
    /// A turbofish argument the parser read as a type: a type, or a const
    /// when the bare name is a const parameter of this body or a const
    /// item and no type (rustc reads it by the parameter's kind, so
    /// `f::<N>()` and `x.m::<N>()` take the const). `instantiate_template`
    /// rejects a kind mismatch.
    fn written_type_arg(&mut self, t: ast::TyId) -> Option<GenericArg> {
        let p = self.p;
        if let ast::TyExpr::Path(segs) = p.ast.ty(t)
            && segs.iter().all(|s| !s.has_args())
        {
            let is_param =
                |cx: &Self, n: Sym| cx.body_scope.param_tys.iter().any(|(pn, _)| *pn == n) || n == p.known.self_type;
            // Type or const by the flat maps, which record no read: the body
            // checks again when a type comes to share a const's name, and
            // when the const's value changes (its `Sig` folds the value), as
            // `written_const` reads it.
            if let [seg] = segs.as_slice()
                && !is_param(self, seg.name)
            {
                self.binding(Namespace::Type, seg.name);
                self.binding(Namespace::Value, seg.name);
            }
            match segs.as_slice() {
                // A const param of this body (`f::<N>()`).
                // `(N)` is a const operation on it, not
                // the parameter itself.
                [seg] if let Some((i, _, val)) = self.const_param(seg.name) => {
                    if p.ast.is_parenthesized_ty(t) {
                        self.err(
                            "L0110",
                            p.ast.ty_span(t),
                            "generic parameters may not be used in const operations",
                            "Write the const parameter without parentheses.",
                        );
                    }
                    Some(GenericArg::Const(self.tys.intern_const(val.unwrap_or(ConstKind::Param(i)))))
                }
                [seg]
                    if !is_param(self, seg.name)
                        && !p.type_names.contains_key(&seg.name)
                        && !p.aliases.contains_key(&seg.name)
                        && p.const_names.contains_key(&seg.name) =>
                {
                    use crate::ty::consteval::ConstValue;
                    let idx = p.const_names[&seg.name];
                    match &p.consts[idx as usize].value {
                        // Stored as `const_call_kind` stores a literal: the
                        // two's complement bits (`const_int_fits` reads them).
                        ConstValue::Int(v) => Some(GenericArg::Const(self.tys.intern_const(ConstKind::Int(*v as u128)))),
                        ConstValue::Bool(b) => Some(GenericArg::Const(self.tys.intern_const(ConstKind::Bool(*b)))),
                        ConstValue::Char(c) => Some(GenericArg::Const(self.tys.intern_const(ConstKind::Char(*c)))),
                        _ => Some(GenericArg::Ty(self.resolve_written(t))),
                    }
                }
                // Multi-segment paths stay type paths:
                // a const path as a generic argument
                // needs braces in Rust (`h::<{ S::N }>`).
                _ => Some(GenericArg::Ty(self.resolve_written(t))),
            }
        } else {
            Some(GenericArg::Ty(self.resolve_written(t)))
        }
    }

    fn explicit_seg_args(&mut self, seg: &ast::PathSeg) -> Vec<Option<GenericArg>> {
        let p = self.p;
        let ast::GenericArgs::Angle(written) = &seg.args else { return Vec::new() };
        let mut out = Vec::new();
        for a in written {
            out.push(match a {
                ast::GenericArg::Type(t) => self.written_type_arg(*t),
                ast::GenericArg::Lifetime(_) => None,
                ast::GenericArg::Const(e) => Some(self.const_call_arg(*e)),
                ast::GenericArg::Binding { span, .. } => {
                    self.errs.push(not_yet("L0621", *span, "associated bindings in call arguments"));
                    None
                }
            });
        }
        out
    }

    // ---------- Expressions ----------

    /// The `&&` elements of a condition, left to right.
    fn split_and(&self, e: ExprId, out: &mut Vec<ExprId>) {
        match self.p.ast.expr(e) {
            Expr::Binary { op: BinOp::And, lhs, rhs } => {
                self.split_and(*lhs, out);
                self.split_and(*rhs, out);
            }
            _ => out.push(e),
        }
    }

    /// True when a condition is a let chain (some `&&` element is a `let`).
    fn is_let_chain(&self, cond: ExprId) -> bool {
        let mut elems = Vec::new();
        self.split_and(cond, &mut elems);
        elems.iter().any(|&e| matches!(self.p.ast.expr(e), Expr::Let { .. }))
    }

    /// Checks a let-chain condition: each `let` element binds into the
    /// current scope (visible to later elements and the then block, which
    /// the caller checks before truncating), each other element is bool.
    fn check_chain(&mut self, cond: ExprId) {
        let mut elems = Vec::new();
        self.split_and(cond, &mut elems);
        for el in elems {
            match self.p.ast.expr(el) {
                Expr::Let { pat, scrut } => {
                    let (pat, scrut) = (*pat, *scrut);
                    let st = self.expr(scrut, None);
                    self.set(el, BOOL);
                    self.pattern(pat, st, true);
                }
                _ => {
                    self.expect_expr(el, BOOL);
                }
            }
        }
    }

    fn expr(&mut self, e: ExprId, expected: Option<Ty>) -> Ty {
        let t = self.expr_inner(e, expected);
        self.set(e, t)
    }

    fn expr_inner(&mut self, e: ExprId, expected: Option<Ty>) -> Ty {
        self.forget_place_steps(e, false);
        let span = self.span(e);
        let p = self.p;
        match p.ast.expr(e) {
            Expr::Int(_, Some(s)) => int(IntTy::from_suffix(*s)),
            Expr::Int(_, None) => match expected.map(|t| (self.resolve(t), self.kind(t))) {
                Some((t, TyKind::Int(_))) => t,
                Some((t, k)) if k.is_int_infer() => t,
                _ => self.new_var(true),
            },
            Expr::Float(i) => {
                let text = p.ast.strings[*i as usize].as_str();
                match crate::check::collect::parse_float_literal(text) {
                    Some((_, suffix)) => match suffix {
                        Some(f) => self.tys.float_ty(f),
                        // An unsuffixed float literal stays a float
                        // variable until a use decides f32 or f64; it
                        // defaults to f64 at body end, like rustc.
                        None => match expected.map(|t| (self.resolve(t), self.kind(t))) {
                            Some((t, TyKind::Float(_))) => t,
                            Some((t, k)) if k.is_float_infer() => t,
                            _ => self.new_float_var(),
                        },
                    },
                    None => {
                        self.err("L0118", span, "invalid float literal", "Write the literal in a simpler form.");
                        ERROR
                    }
                }
            }
            Expr::Bool(_) => BOOL,
            Expr::Char(_) => CHAR,
            Expr::Str(_) => REF_STR,
            Expr::ByteStr(i) => {
                // A byte string's array value: `[u8; N]` over its blob.
                let n = p.ast.blobs.get(*i as usize).map_or(0, |b| b.len());
                let c = self.tys.intern_const(ConstKind::Int(n as u128));
                self.tys.intern(TyKind::Array(int(IntTy::U8), c))
            }
            Expr::Unit => UNIT,
            Expr::SelfValue => match self.lookup(p.known.self_value, span.ctxt) {
                Some(l) if l < self.const_floor => self.non_const_local(span),
                Some(l) => {
                    self.set_res(e, Res::Local(l));
                    self.out.locals[l as usize].ty
                }
                None => {
                    self.err("L0101", span, "`self` is not available here", "Only methods with a `self` parameter can use `self`.");
                    ERROR
                }
            },
            Expr::Path(segs) => {
                self.lifetime_turbofish(segs);
                self.path_expr(e, segs, span)
            }
            Expr::Block(b) => {
                if let Some(tail) = p.ast.block(*b).tail
                    && self.hinted.contains(&e)
                {
                    self.hinted.push(tail);
                }
                self.block(*b, expected)
            }
            Expr::If { cond, then, els } if self.is_let_chain(*cond) => {
                let scope = self.scopes.len();
                self.check_chain(*cond);
                match els {
                    None => {
                        let t = self.block(*then, Some(UNIT));
                        let bspan = p.ast.block(*then).span;
                        if let Some(tail) = p.ast.block(*then).tail {
                            self.coerce_expr(tail, t, UNIT);
                        } else {
                            self.coerce_at(t, UNIT, bspan, None);
                        }
                        self.scopes.truncate(scope);
                        UNIT
                    }
                    Some(els) => {
                        let real = if self.hinted.contains(&e) { None } else { expected };
                        if real.is_none()
                            && expected.is_some()
                            && let Some(tail) = p.ast.block(*then).tail
                        {
                            self.hinted.push(tail);
                        }
                        let t1 = self.block(*then, expected);
                        self.scopes.truncate(scope);
                        if real.is_none() {
                            self.hinted.push(*els);
                        }
                        let t2 = self.expr(*els, self.branch_hint(expected, Some(t1)));
                        if let Some(d) = self.dyn_ref_expectation(real) {
                            self.coerce_block_tail(*then, t1, d);
                            self.coerce_expr(*els, t2, d);
                            return d;
                        }
                        if let Some(exp) = real.filter(|e| !self.has_unbound_deep(*e)) {
                            self.coerce_block_tail(*then, t1, exp);
                            self.coerce_expr(*els, t2, exp);
                            return exp;
                        }
                        if real.is_none()
                            && let Some(tail) = p.ast.block(*then).tail
                            && self.lub_flip(&[tail], t1, t2)
                        {
                            // A place tail (`b`, `x.f`) makes no
                            // temporary, so where it coerces is the same.
                            if !matches!(p.ast.expr(tail), Expr::Path(_) | Expr::Field { .. } | Expr::TupleField { .. } | Expr::Deref(_)) {
                                self.out.after_tail.push(tail);
                            }
                            return t2;
                        }
                        {
                            let tail: Vec<ExprId> = p.ast.block(*then).tail.into_iter().collect();
                            self.join(t1, t2, &tail, Some(*els), span)
                        }
                    }
                }
            }
            Expr::If { cond, then, els } => {
                self.expect_expr(*cond, BOOL);
                match els {
                    None => {
                        let t = self.block(*then, Some(UNIT));
                        let bspan = p.ast.block(*then).span;
                        if let Some(tail) = p.ast.block(*then).tail {
                            self.coerce_expr(tail, t, UNIT);
                        } else {
                            self.coerce_at(t, UNIT, bspan, None);
                        }
                        UNIT
                    }
                    Some(els) => {
                        let real = if self.hinted.contains(&e) { None } else { expected };
                        if real.is_none()
                            && expected.is_some()
                            && let Some(tail) = p.ast.block(*then).tail
                        {
                            self.hinted.push(tail);
                        }
                        let t1 = self.block(*then, expected);
                        if real.is_none() {
                            self.hinted.push(*els);
                        }
                        let t2 = self.expr(*els, self.branch_hint(expected, Some(t1)));
                        if let Some(d) = self.dyn_ref_expectation(real) {
                            self.coerce_block_tail(*then, t1, d);
                            self.coerce_expr(*els, t2, d);
                            return d;
                        }
                        if let Some(exp) = real.filter(|e| !self.has_unbound_deep(*e)) {
                            self.coerce_block_tail(*then, t1, exp);
                            self.coerce_expr(*els, t2, exp);
                            return exp;
                        }
                        if real.is_none()
                            && let Some(tail) = p.ast.block(*then).tail
                            && self.lub_flip(&[tail], t1, t2)
                        {
                            // A place tail (`b`, `x.f`) makes no
                            // temporary, so where it coerces is the same.
                            if !matches!(p.ast.expr(tail), Expr::Path(_) | Expr::Field { .. } | Expr::TupleField { .. } | Expr::Deref(_)) {
                                self.out.after_tail.push(tail);
                            }
                            return t2;
                        }
                        {
                            let tail: Vec<ExprId> = p.ast.block(*then).tail.into_iter().collect();
                            self.join(t1, t2, &tail, Some(*els), span)
                        }
                    }
                }
            }
            Expr::While { label, cond, body } if self.is_let_chain(*cond) => {
                let scope = self.scopes.len();
                self.check_chain(*cond);
                self.loops.push(LoopCtx { break_ty: None, want: None, is_loop: false, is_block: false, label: label_of(label) });
                let t = self.block(*body, Some(UNIT));
                self.unit_body(t, *body);
                self.loops.pop();
                self.scopes.truncate(scope);
                UNIT
            }
            Expr::While { label, cond, body } => {
                self.expect_expr(*cond, BOOL);
                self.loops.push(LoopCtx { break_ty: None, want: None, is_loop: false, is_block: false, label: label_of(label) });
                let t = self.block(*body, Some(UNIT));
                self.unit_body(t, *body);
                self.loops.pop();
                UNIT
            }
            Expr::Loop { label, body } => {
                let want = self.fn_ptr_expectation(expected);
                self.loops.push(LoopCtx { break_ty: None, want, is_loop: true, is_block: false, label: label_of(label) });
                let t = self.block(*body, Some(UNIT));
                self.unit_body(t, *body);
                let l = self.loops.pop().unwrap();
                l.break_ty.unwrap_or(NEVER)
            }
            Expr::For { label, pat, iter, body } => {
                let item = self.for_iter(e, *iter);
                let scope = self.scopes.len();
                self.pattern(*pat, item, false);
                if !self.pat_always_matches(*pat) {
                    let s = self.p.ast.pat_span(*pat);
                    self.err(
                        "L0110",
                        s,
                        "refutable pattern in `for` loop binding",
                        "Use `while let` or `match` for a pattern that can fail.",
                    );
                }
                self.loops.push(LoopCtx { break_ty: None, want: None, is_loop: false, is_block: false, label: label_of(label) });
                let t = self.block(*body, Some(UNIT));
                self.unit_body(t, *body);
                self.loops.pop();
                self.scopes.truncate(scope);
                UNIT
            }
            Expr::Match { scrut, arms } => {
                let real = if self.hinted.contains(&e) { None } else { expected };
                let st = self.expr(*scrut, None);
                // ARCH 2.12 run point: a match must know the scrutinee enum.
                self.run_obligations(false);
                let mut result: Option<Ty> = None;
                let mut sites: Vec<ExprId> = Vec::new();
                for arm in arms {
                    let scope = self.scopes.len();
                    self.pattern(arm.pat, st, true);
                    if let Some(g) = arm.guard {
                        // A by-value slice-pattern middle binds
                        // before its guard runs (there is no
                        // subarray place to read it through by
                        // reference), so a failed guard would drop
                        // the moved parts early. Copy elements are
                        // exact already; anything else is a reject
                        // for now rather than wrong drop order.
                        if self.entry_payload_bound(arm.pat) {
                            self.errs.push(unsupported(self.span(g), "match guards over a bound map Entry payload"));
                        }
                        if self.slice_middle_move_blocks_guard(arm.pat) {
                            self.errs.push(unsupported(self.span(g), "match guards over a by-value slice-pattern middle"));
                        }
                        self.expect_expr(g, BOOL);
                    }
                    if real.is_none() && (result.is_some() || expected.is_some()) {
                        self.hinted.push(arm.body);
                    }
                    let bt = self.expr(arm.body, self.branch_hint(expected, result));
                    if let Some(d) = self.dyn_ref_expectation(real) {
                        self.coerce_expr(arm.body, bt, d);
                        result = Some(d);
                        self.scopes.truncate(scope);
                        continue;
                    }
                    // With a known expected type every arm is a
                    // coercion site to it (`let r: &str = match ..
                    // { Some(s) => s, .. }` deref-coerces `&String`
                    // to `&str` per arm), as in rustc.
                    if let Some(exp) = real.filter(|e| !self.has_unbound_deep(*e)) {
                        self.coerce_expr(arm.body, bt, exp);
                        result = Some(exp);
                        self.scopes.truncate(scope);
                        continue;
                    }
                    result = Some(match result {
                        None => bt,
                        Some(r) if real.is_none() && self.lub_flip(&sites, r, bt) => bt,
                        Some(r) => self.join(r, bt, &sites, Some(arm.body), self.span(arm.body)),
                    });
                    sites.push(arm.body);
                    self.scopes.truncate(scope);
                }
                let behind = self.place_behind_deref(*scrut);
                self.exhaustive(st, arms, span, behind);
                result.unwrap_or(NEVER)
            }
            Expr::Call { callee, args } => {
                if let Expr::Path(segs) = p.ast.expr(*callee) {
                    self.lifetime_turbofish(segs);
                }
                let t = match self.self_from_expected_call(e, *callee, args, expected, span) {
                    Some(t) => t,
                    None => self.call(e, *callee, args, span, expected),
                };
                // `std::io::copy`: the shapes std specializes (check/platform.rs).
                if let Res::Fn(f) = self.out.res(*callee)
                    && args.len() == 2
                    && crate::check::platform::is_platform_io_copy(p, f)
                {
                    let (r, w) = (self.out.ty(args[0]), self.out.ty(args[1]));
                    self.deferred_io_copy.push((r, w, span));
                }
                // Every call path (variant ctors like `Some(v[1..])` too).
                for &a in args.iter() {
                    self.reject_unsized_value(a);
                }
                t
            }
            Expr::MethodCall { recv, name, name_span, generic_args, args } => {
                self.method_chain(e, *recv, *name, *name_span, args, generic_args, expected)
            }
            Expr::Field { base, name } => {
                let bt = self.expr(*base, None);
                // ARCH 2.12 run point: a field access must know the base type.
                self.run_obligations(false);
                let bt = self.deep(bt);
                let (mut derefs, mut inner) = self.autoderef_smart(bt);
                let mut cow_step = false;
                for step in 0..=4 {
                    if let Some(a) = self.tys.local_adt(inner) {
                        // The lookup reads the Adt's field list, found or
                        // not: a field added, removed, or retyped moves its
                        // `Sig`. A body that reaches the Adt through a
                        // reference has no other read of it.
                        let _ = p.sig_of(&mut self.out.reads, p.def_of_adt(a));
                        let adt = p.adt(a);
                        if !adt.is_enum
                            && let Some(i) = adt.variants[0].fields.iter().position(|f| f.name == *name)
                        {
                            self.check_field_vis(a, *name, span);
                            self.set_res(e, Res::Field { derefs, index: i as u32 });
                            // A generic Adt's fields are the template's,
                            // substituted with this value's args (the
                            // instance AdtDef already has them concrete).
                            let fty = adt.variants[0].fields[i].ty;
                            return match self.tys.adt_parts(inner) {
                                Some((_, args)) if args != EMPTY_ARGS && self.tys.flags(fty).contains_param() => {
                                    let gargs: Vec<GenericArg> = self.tys.args(args).to_vec();
                                    self.subst_norm(fty, &gargs, span)
                                }
                                _ => fty,
                            };
                        }
                    }
                    // The public fields of the range kinds (`start`
                    // and `end`; `RangeInclusive`'s are private).
                    if let Some((i, fty)) = self.range_field(inner, *name) {
                        self.set_res(e, Res::Field { derefs, index: i });
                        return fty;
                    }
                    // rustc's autoderef goes on through a user `Deref`
                    // impl (`info.file_index` on a type that derefs to
                    // the struct holding it), and through a Cow's
                    // `Deref` as the first step (check/cow.rs).
                    if step == 4 {
                        break;
                    }
                    if let Some(b) = crate::check::collect::cow_arg(&self.tys, inner) {
                        if step == 0 && !cow_step && self.cow_place_step(*base, inner, derefs).is_some() {
                            cow_step = true;
                            let view = self.tys.mk_ref(false, b);
                            (derefs, inner) = self.autoderef_smart(view);
                            continue;
                        }
                        if self.cow_view_has_field(b, *name) {
                            let tn = self.tn(b);
                            self.err(
                                "L0640",
                                span,
                                format!("a field of `{tn}` through this `Cow` is not implemented yet"),
                                format!("Bind the view first: `let v: &{tn} = &cow;`, then read `v.{}`.", self.name(*name)),
                            );
                            return ERROR;
                        }
                        break;
                    }
                    if cow_step {
                        if self.probe_user_deref(inner, span) {
                            self.err(
                                "L0640",
                                span,
                                "a field through a `Cow` and a user `Deref` is not implemented yet".to_string(),
                                "Bind the view first: `let v = &*cow;`, then read the field.",
                            );
                            return ERROR;
                        }
                        break;
                    }
                    let Some(target) = self.record_place_deref(e, inner, derefs, span) else { break };
                    let tref = self.tys.mk_ref(false, target);
                    (derefs, inner) = self.autoderef_smart(tref);
                }
                if !matches!(self.kind(inner), TyKind::Error) && !self.tainted_lookup(bt) {
                    let tn = self.tn(bt);
                    self.err("L0103", span, format!("no field `{}` on type `{tn}`", self.name(*name)), "Check the field name.");
                }
                ERROR
            }
            Expr::Index { base, index } => {
                let bt = self.expr(*base, None);
                // ARCH 2.12 run point: an index must know the indexed type; the
                // index type then follows from the selected `Index` impl.
                self.run_obligations(false);
                let (mut derefs, mut inner) = self.autoderef_smart(bt);
                // A user type indexes through its `Deref` impls (a wrapper
                // over a Vec or slice), as rustc's index autoderef, and a
                // Cow indexes through its view as the first step
                // (check/cow.rs).
                let mut cow_step = false;
                let mut first_step = true;
                for _ in 0..4 {
                    let indexable = matches!(self.kind(inner), TyKind::Array(..) | TyKind::Slice(_) | TyKind::Str | TyKind::Error)
                        || self.tys.vec_elem(inner).is_some()
                        || self.tys.is_string_ty(inner)
                        || crate::ty::hash::hash_parts(&self.tys, inner).is_some_and(|(k, _)| k == crate::ty::hash::HashTy::HashMap);
                    // rustc tries the type's own `Index` impl before any
                    // deref, so such a type stops the walk here and the
                    // written-impl path below answers for it.
                    if indexable || self.has_user_index_impl(inner) {
                        break;
                    }
                    if let Some(b) = crate::check::collect::cow_arg(&self.tys, inner) {
                        if first_step && !cow_step && self.cow_place_step(*base, inner, derefs).is_some() {
                            cow_step = true;
                            first_step = false;
                            let view = self.tys.mk_ref(false, b);
                            (derefs, inner) = self.autoderef_smart(view);
                            continue;
                        }
                        if self.cow_view_indexable(b) {
                            self.err(
                                "L0640",
                                span,
                                "indexing through this `Cow` is not implemented yet".to_string(),
                                "Bind the view first: `let v = &*cow;`, then index `v`.",
                            );
                            if !matches!(p.ast.expr(*index), Expr::Range { .. }) {
                                self.expr(*index, None);
                            }
                            return ERROR;
                        }
                        break;
                    }
                    if cow_step {
                        if self.probe_user_deref(inner, span) {
                            self.err(
                                "L0640",
                                span,
                                "indexing through a `Cow` and a user `Deref` is not implemented yet".to_string(),
                                "Bind the view first: `let v = &*cow;`, then index `v`.",
                            );
                            if !matches!(p.ast.expr(*index), Expr::Range { .. }) {
                                self.expr(*index, None);
                            }
                            return ERROR;
                        }
                        break;
                    }
                    first_step = false;
                    let Some(target) = self.record_place_deref(e, inner, derefs, span) else { break };
                    let tref = self.tys.mk_ref(false, target);
                    (derefs, inner) = self.autoderef_smart(tref);
                }
                if let Expr::Range { lo, hi, .. } = p.ast.expr(*index) {
                    // A range index makes a slice place. Bounds are usize.
                    // The range expression itself is not checked as a value;
                    // give it the error-free unit record so lowering (which
                    // reads the bounds directly) never sees a stale type.
                    for b in [lo, hi].into_iter().flatten() {
                        self.expect_expr(*b, USIZE);
                    }
                    self.set(*index, UNIT);
                    // A range index into a string makes a str place; the
                    // runtime range check also validates char boundaries.
                    if self.kind(inner) == TyKind::Str || self.tys.is_string_ty(inner) {
                        self.set_res(e, Res::SliceIndex { derefs });
                        return STR;
                    }
                    let elem = match self.kind(inner) {
                        TyKind::Array(elem, _) | TyKind::Slice(elem) => Some(elem),
                        _ => self.tys.vec_elem(inner),
                    };
                    match elem {
                        Some(elem) => {
                            self.set_res(e, Res::SliceIndex { derefs });
                            return self.tys.intern(TyKind::Slice(elem));
                        }
                        None => {
                            if !matches!(self.kind(inner), TyKind::Error) {
                                let tn = self.tn(bt);
                                self.err(
                                    "L0113",
                                    span,
                                    format!("cannot slice a value of type `{tn}`"),
                                    "Slice an array, a Vec, a slice, or a string.",
                                );
                            }
                            return ERROR;
                        }
                    }
                }
                if let Some((crate::ty::hash::HashTy::HashMap, targs)) = crate::ty::hash::hash_parts(&self.tys, inner) {
                    return self.map_index(e, *base, *index, &targs, derefs, span);
                }
                // A written `Index` impl on a non-builtin type
                // (`map[&k]`, `deque[i]`, a user container): the
                // place is the call's returned reference, recorded
                // for lowering like a user `Deref` step.
                if self.has_user_index_impl(inner)
                    && !matches!(self.kind(inner), TyKind::Array(..) | TyKind::Slice(_) | TyKind::Str | TyKind::Error)
                    && self.tys.vec_elem(inner).is_none()
                    && !self.tys.is_string_ty(inner)
                {
                    let idx_ty = self.expr(*index, None);
                    return match self.record_trait_index(e, inner, idx_ty, span) {
                        Some(out) => {
                            self.set_res(e, Res::TraitIndex { derefs });
                            out
                        }
                        None => {
                            let tn = self.tn(bt);
                            let itn = self.tn(idx_ty);
                            if !matches!(self.kind(inner), TyKind::Error) && !matches!(self.kind(idx_ty), TyKind::Error) {
                                self.err(
                                    "L0113",
                                    span,
                                    format!("cannot index into a value of type `{tn}` with `{itn}`"),
                                    "Check the index type the `Index` impl takes.",
                                );
                            }
                            ERROR
                        }
                    };
                }
                // A range value as the index (`v[r]` with `r` a
                // `RangeTo<usize>` value, tf-slice): the same slice
                // place as a syntactic range. The helper checks the
                // index either way (and coerces a plain one), so the
                // `expect_expr` runs only when it did not run.
                let seq_inner = matches!(self.kind(inner), TyKind::Array(..) | TyKind::Slice(_) | TyKind::Str)
                    || self.tys.vec_elem(inner).is_some()
                    || self.tys.is_string_ty(inner);
                if seq_inner {
                    if let Some(t) = self.range_value_index(e, *index, inner, derefs, span) {
                        return t;
                    }
                } else {
                    self.expect_expr(*index, USIZE);
                }
                match self.kind(inner) {
                    TyKind::Array(elem, _) | TyKind::Slice(elem) => {
                        self.set_res(e, Res::Index { derefs });
                        elem
                    }
                    _ if self.tys.vec_elem(inner).is_some() => {
                        self.set_res(e, Res::Index { derefs });
                        self.tys.vec_elem(inner).unwrap()
                    }
                    TyKind::Error => ERROR,
                    _ if self.kind(inner) == TyKind::Str || self.tys.is_string_ty(inner) => {
                        self.err(
                            "L0113",
                            span,
                            "strings cannot be indexed by an integer",
                            "Use `.chars()` later, or `.as_bytes()`. Not supported in the prototype yet.",
                        );
                        ERROR
                    }
                    _ => {
                        let tn = self.tn(bt);
                        self.err(
                            "L0113",
                            span,
                            format!("cannot index into a value of type `{tn}`"),
                            "Only Vec supports indexing in the prototype.",
                        );
                        ERROR
                    }
                }
            }
            Expr::Binary { op, lhs, rhs } => self.binary_chain(e, *op, *lhs, *rhs, span),
            Expr::Unary { op, expr } => {
                if *op == UnOp::Neg
                    && let Expr::Int(..) = p.ast.expr(*expr)
                {
                    self.negated_lits.push(*expr);
                }
                let t = self.expr(*expr, expected);
                // Rust has `-` and `!` for `&T` (shared references only, not `&mut T`).
                let (d, inner) = match self.kind(t) {
                    TyKind::Ref(_, Mut::Shared, inner) => (1, inner),
                    _ => (0, t),
                };
                self.set_res(e, Res::Bin { ld: d, rd: 0 });
                let k = self.kind(inner);
                match (op, k) {
                    (UnOp::Neg, TyKind::Float(_)) => inner,
                    (UnOp::Neg, k) if k.is_float_infer() => inner,
                    (UnOp::Neg, TyKind::Int(i)) if i.signed() => inner,
                    // The variable may still become unsigned (`let y: u64
                    // = x`): queue `Neg` for body end, as `x.neg()` does.
                    (UnOp::Neg, k) if k.is_int_infer() => {
                        let args_id = self.tys.intern_args(&[GenericArg::Ty(inner)]);
                        let tr = TraitRef { def: p.gx.lang.neg, args: args_id, bindings: EMPTY_BINDINGS };
                        self.obl.push_trait_at(tr, span, 0);
                        inner
                    }
                    (UnOp::Not, TyKind::Bool | TyKind::Int(_)) => inner,
                    (UnOp::Not, k) if k.is_int_infer() => inner,
                    (_, TyKind::Error) => ERROR,
                    // A user operator impl answers for the operand type as
                    // written (core's `Neg for &i32` and kin are scalar
                    // only): `-&v` needs `impl Neg for &V`.
                    _ => match self.trait_unop(e, *op, t, 0, span) {
                        Some(t) => t,
                        None => {
                            let tn = self.tn(t);
                            let sym = if *op == UnOp::Neg { "-" } else { "!" };
                            self.err(
                                "L0113",
                                span,
                                format!("cannot apply unary `{sym}` to type `{tn}`"),
                                "Use a signed integer type for `-`, or a bool or integer for `!`.",
                            );
                            ERROR
                        }
                    },
                }
            }
            Expr::Cast { expr, ty } => {
                // A target that names a lifetime (`f as fn(TableKey<'a>)`)
                // is an annotation of the cast's value (W-BORROW): lowering
                // puts that value in a temporary with these regions.
                let target = if self.annotation_has_regions(*ty) {
                    let target = self.resolve_annotation(*ty);
                    self.record_cast_annotation(e, *ty);
                    target
                } else {
                    self.resolve_written(*ty)
                };
                // A bare `_` cast target takes the expected type:
                // `let x: u16 = 3u8 as _` casts to `u16`.
                let target = if matches!(self.kind(target), TyKind::Infer(_)) {
                    match expected {
                        Some(exp) => {
                            self.unify(target, exp);
                            self.resolve(target)
                        }
                        None => target,
                    }
                } else {
                    target
                };
                // An unsuffixed literal takes its type from the cast
                // target: `300 as u8` is a u8 literal out of range,
                // and `3000000000 as u64` needs no i32 fit first.
                // A closure cast to a fn pointer (`(|a| a + 1) as fn(u8) ->
                // u8`) takes the pointer's signature, as rustc deduces it from
                // the cast's expectation; capturing nothing, it becomes that
                // pointer (`closure_expr`).
                let closure_ptr = matches!(p.ast.expr(*expr), Expr::Closure { .. })
                    && matches!(self.kind(target), TyKind::FnPtr(_))
                    && !self.has_unbound_deep(target);
                let exp = if crate::ty::consteval::is_unsuffixed_lit(&p.ast, *expr) || closure_ptr { Some(target) } else { None };
                let t = self.expr(*expr, exp);
                let coerce_cast = matches!(
                    (self.kind(t), self.kind(target)),
                    (TyKind::Ref(..), TyKind::Ref(..)) | (TyKind::Ref(..), TyKind::RawPtr(..))
                ) || self.owning_unsize_parts(t, target).is_some();
                if coerce_cast && self.cast_operand_open(t) {
                    self.deferred_coerce_casts.push((t, target, span, *expr));
                    return target;
                }
                // An operand of a still unknown type to a scalar target:
                // decided at body end (`deferred_open_casts`).
                if matches!(self.kind(t), TyKind::Infer(v) if v.1 == InferKind::General)
                    && matches!(self.kind(target), TyKind::Int(_) | TyKind::Float(_) | TyKind::Char | TyKind::Bool)
                {
                    self.deferred_open_casts.push((t, target, span));
                    return target;
                }
                // A cast to a dyn reference is a coercion cast: rustc
                // allows any coercion through `as` (ARCH 2.8).
                if matches!(self.kind(target), TyKind::Ref(_, _, inner) if matches!(self.kind(inner), TyKind::Dyn(..))) {
                    self.coerce_expr(*expr, t, target);
                    return target;
                }
                let enum_cast = match self.tys.local_adt(self.resolve(t)) {
                    Some(a) => p.adt(a).is_enum && p.adt(a).variants.iter().all(|v| v.shape == VariantShape::Unit),
                    None => false,
                };
                // A fn item casts to a fn pointer of the same signature,
                // and a fn pointer casts to itself. The item form goes
                // through the coercion path, which gives the inner
                // expression the pointer type for lowering.
                // A target with a `_` (`f as fn(_) -> u8`) is only
                // probed here: rustc checks fn casts after
                // inference, so the operand's signature must not
                // bind the `_` yet (a later `g(3)` defaults it to
                // `i32` and the cast then fails). The real check
                // is deferred to `finish`.
                let fn_cast = match (self.kind(t), self.kind(target)) {
                    (TyKind::FnDef(..), TyKind::FnPtr(_)) if self.reifies(t) => {
                        if self.has_unbound_deep(target) {
                            let snap = self.snapshot_vars();
                            let ok = self.fn_item_ptr_unifies(t, target) && self.coerce_at(t, target, span, Some(*expr));
                            self.rollback_vars(snap);
                            if ok {
                                self.deferred_fn_casts.push((t, target, span));
                            }
                            ok
                        } else {
                            self.fn_item_ptr_unifies(t, target) && self.coerce_at(t, target, span, Some(*expr))
                        }
                    }
                    (TyKind::FnPtr(_), TyKind::FnPtr(_)) => match (self.callable_sig(t), self.callable_sig(target)) {
                        (Some((pa, ra)), Some((pb, rb))) => {
                            if self.has_unbound_deep(target) {
                                let snap = self.snapshot_vars();
                                let ok = pa.len() == pb.len() && pa.iter().zip(&pb).all(|(&a, &b)| self.unify(a, b)) && self.unify(ra, rb);
                                self.rollback_vars(snap);
                                if ok {
                                    self.deferred_fn_casts.push((t, target, span));
                                }
                                ok
                            } else {
                                pa.len() == pb.len() && pa.iter().zip(&pb).all(|(&a, &b)| self.unify(a, b)) && self.unify(ra, rb)
                            }
                        }
                        _ => false,
                    },
                    _ => false,
                };
                // A reference-to-reference cast is a coercion cast in
                // rustc (`&[T; N] as &[T]`, `&mut T as &T`, `&Vec<T> as
                // &[T]`): it holds exactly when the coercion does. The
                // probe rolls back on failure so the cast error below
                // is the only diagnostic.
                // So is an owning unsizing (`Rc<[T; N]> as Rc<[T]>`,
                // `Box<S> as Box<dyn Tr>`).
                let ref_cast = (matches!(
                    (self.kind(t), self.kind(target)),
                    (TyKind::Ref(..), TyKind::Ref(..)) | (TyKind::Ref(..), TyKind::RawPtr(..)) | (TyKind::RawPtr(..), TyKind::RawPtr(..))
                ) || self.owning_unsize_parts(t, target).is_some())
                    && {
                    let snap = self.snapshot_vars();
                    let obl_len = self.obl_len();
                    let err_len = self.errs.len();
                    if self.coerce_at(t, target, span, Some(*expr)) {
                        true
                    } else {
                        self.rollback_vars(snap);
                        self.obl_truncate(obl_len);
                        self.errs.truncate(err_len);
                        false
                    }
                };
                // The `as` table rustc enforces (E0054, E0604, E0606): bool
                // and char never cast to a float, only `u8` casts to char,
                // nothing casts to bool, a fieldless enum casts only to an
                // integer. A same-kind cast (`bool as bool`) is fine.
                let ok = fn_cast
                    || ref_cast
                    || match (self.kind(t), self.kind(target)) {
                        // An integer of unknown type stays open: later uses decide it (default i32).
                        (k, TyKind::Int(_)) if k.is_int_infer() => true,
                        (k, TyKind::Float(_) | TyKind::Int(_)) if k.is_float_infer() => true,
                        (_, TyKind::Int(_)) if enum_cast => true,
                        (TyKind::Int(_) | TyKind::Bool | TyKind::Char, TyKind::Int(_)) => true,
                        (TyKind::Int(_) | TyKind::Float(_), TyKind::Float(_)) => true,
                        (TyKind::Float(_), TyKind::Int(_)) => true,
                        (TyKind::Int(IntTy::U8) | TyKind::Char, TyKind::Char) => true,
                        // Pointer casts (w-cinterop): between raw pointers
                        // of any pointee or mutability, and between a raw
                        // pointer and an integer, as in Rust. A reference
                        // to a raw pointer is the coercion cast above.
                        // A fat pointer's casts are checked at body end
                        // (`deferred_raw_casts`, tf-fatptr).
                        (TyKind::RawPtr(..), TyKind::RawPtr(..)) | (TyKind::RawPtr(..), TyKind::Int(_)) | (TyKind::Int(_), TyKind::RawPtr(..)) => {
                            self.deferred_raw_casts.push((t, target, span));
                            true
                        }
                        (TyKind::Bool, TyKind::Bool) => true,
                        (TyKind::Error, _) | (_, TyKind::Error) => true,
                        _ => false,
                    };
                if !ok {
                    let (a, b) = (self.tn(t), self.tn(target));
                    self.err(
                        "L0116",
                        span,
                        format!("cannot cast `{a}` as `{b}`"),
                        "Lust allows `as` between integers, from bool and char to integers, from u8 to char, and between raw pointers and integers.",
                    );
                }
                target
            }
            Expr::Ref { mutable, expr, .. } => {
                let inner_expected = expected.and_then(|t| match self.kind(t) {
                    TyKind::Ref(_, _, inner) => Some(inner),
                    _ => None,
                });
                let t = self.expr(*expr, inner_expected);
                // `&|a| a` against `&fn(..)`: a closure right under `&`
                // keeps its closure type (rustc E0308); only a coercion
                // site (`&{ |a| a }`, `&[|a| a]`) makes it a fn pointer.
                if matches!(self.p.ast.expr(*expr), Expr::Closure { .. }) && matches!(self.kind(self.resolve(t)), TyKind::FnPtr(_)) {
                    self.err(
                        "L0110",
                        span,
                        "mismatched types: a closure right under `&` does not coerce to a fn pointer",
                        "Coerce it first (`let f: fn(..) -> _ = |..| ..;`), then borrow `&f`.",
                    );
                    return ERROR;
                }
                self.check_packed_borrow(*expr, span);
                // `&mut STATIC` (rustc E0596; `static mut` needs `unsafe`,
                // which lust has not): lowering makes every static
                // borrow a shared `StaticRef`, so this was accepted.
                if *mutable && let Res::Static(_) = self.out.expr_res[self.ei(*expr)] {
                    self.err("L0308", span, "cannot borrow a static item as mutable", "Use a `const`, or a `static` with interior mutability.");
                }
                self.tys.mk_ref(*mutable, t)
            }
            Expr::Deref(inner) => {
                let t = self.expr(*inner, None);
                // ARCH 2.12 run point: a deref must know the pointee source type.
                self.run_obligations(false);
                let t = self.resolve(t);
                match self.kind(t) {
                    TyKind::Ref(_, _, x) => x,
                    TyKind::Error => ERROR,
                    // `String` and `Vec<T>` deref to `str` and
                    // `[T]` (their std `Deref` impls), as a method
                    // receiver step already treats them.
                    _ if self.tys.is_string_ty(t) => STR,
                    _ if self.tys.vec_elem(t).is_some() => {
                        let elem = self.tys.vec_elem(t).unwrap_or(ERROR);
                        self.tys.intern(TyKind::Slice(elem))
                    }
                    _ if self.tys.smart_elem(t).is_some() => self.tys.smart_elem(t).unwrap_or(ERROR),
                    // `*cow` is `*Deref::deref(&cow)` (W-STD-B): the place
                    // behind the Cow's `&B` view.
                    _ if let Some(b) = crate::check::collect::cow_arg(&self.tys, t) => {
                        let view = self.tys.mk_ref(false, b);
                        let i = self.ei(*inner);
                        self.out.coerce[i] = Coerce::CowRecv(0, view);
                        b
                    }
                    // `*w` through a user `Deref` impl.
                    _ if let Some(target) = self.record_place_deref(e, t, 0, span) => target,
                    _ => {
                        let tn = self.tn(t);
                        self.err(
                            "L0113",
                            span,
                            format!("type `{tn}` cannot be dereferenced"),
                            "Only references, `Box` values, and `Rc` values can be dereferenced with `*`.",
                        );
                        ERROR
                    }
                }
            }
            Expr::Assign { lhs, rhs } => {
                if self.assign_lhs_needs_expected(*lhs) {
                    // A target with a struct form or a `..` rest gets
                    // its element types from the right-hand side, as a
                    // pattern gets them from its scrutinee.
                    let rt = self.expr(*rhs, None);
                    self.assign_lhs_expected(*lhs, rt);
                    self.place_check(*lhs, true);
                    return UNIT;
                }
                let lt = self.assign_lhs_ty(*lhs);
                self.place_check(*lhs, true);
                self.expect_expr(*rhs, lt);
                UNIT
            }
            Expr::AssignOp { op, lhs, rhs } => {
                let lt = self.expr(*lhs, None);
                self.place_check(*lhs, false);
                // A known number on the left gives the right side no type:
                // `u8: AddAssign<u8>` and `AddAssign<&u8>` both exist (shifts
                // take any integer), so rustc's `Rhs` stays open (E0283)
                // unless the right side fixes it; such an operator waits
                // for body end (`wait_assign_ops`).
                let known_number = matches!(self.kind(self.resolve(lt)), TyKind::Int(_) | TyKind::Float(_));
                // An open left side (`*last_bits |= bits` before a later push
                // fixes the element type) is rustc's pending `?T: BitOrAssign<R>`
                // obligation: it waits for body end too.
                let open_lhs = self.unbound_general(self.resolve(lt));
                // `String += x` and `Cow<str> += x` as `String + x` (`binary_with_lt`).
                let lt_deep = self.deep(lt);
                let expect = if *op == BinOp::Add && self.tys.is_string_ty(lt_deep) {
                    Some(REF_STR)
                } else if known_number || open_lhs || (*op == BinOp::Add && crate::check::collect::cow_arg(&self.tys, lt_deep) == Some(STR)) {
                    None
                } else {
                    Some(lt)
                };
                let rt = self.expr(*rhs, expect);
                if open_lhs || (known_number && self.unbound_general(self.resolve(self.peel_one_ref(rt).1))) {
                    self.set_res(e, Res::Bin { ld: 0, rd: 0 });
                    self.wait_assign_ops.push((e, *op, lt, rt, *rhs, span));
                    return UNIT;
                }
                self.assign_op_types(e, *op, lt, rt, *rhs, span)
            }
            Expr::StructLit { path, fields, update } => self.struct_lit(e, path, fields, *update, span, expected),
            Expr::Range { lo, hi, inclusive } => self.range_value(e, *lo, *hi, *inclusive, span),
            Expr::Break { label, value: val } => {
                // Edition 2024 (rustc E0695): an unlabeled break may not
                // target or pass through a labeled block. If the innermost
                // breakable is a labeled block, the break needs the label.
                if label.is_none()
                    && let Some(lp) = self.loops.last()
                    && lp.is_block
                {
                    self.err(
                        "L0120",
                        span,
                        "unlabeled `break` inside of a labeled block",
                        "Give the break the block's label, such as `break 'a;`.",
                    );
                    if let Some(v) = val {
                        self.expr(*v, None);
                    }
                    return NEVER;
                }
                let target = match label {
                    None => self.loops.len().checked_sub(1),
                    Some(l) => self
                        .loops
                        .iter()
                        .rposition(|lp| lp.label.is_some_and(|(n, bs)| n == l.name && crate::diag::ctxt_can_see_local(l.span.ctxt, bs))),
                };
                let Some(ti) = target else {
                    match label {
                        Some(l) => {
                            let n = self.name(l.name).to_string();
                            self.err("L0120", span, format!("cannot find label `'{n}` in this scope"), "Check the label name.");
                        }
                        None => self.err("L0120", span, "`break` outside of a loop", "Remove the break, or put it inside a loop."),
                    }
                    if let Some(v) = val {
                        self.expr(*v, None);
                    }
                    return NEVER;
                };
                let is_loop = self.loops[ti].is_loop;
                let prev = self.loops[ti].break_ty.or(self.loops[ti].want);
                match val {
                    Some(v) if !is_loop => {
                        self.expr(*v, None);
                        self.err(
                            "L0120",
                            span,
                            "`break` with a value is only allowed in `loop` and labeled blocks",
                            "Remove the value, or use `loop`.",
                        );
                    }
                    Some(v) => {
                        let t = self.expr(*v, prev);
                        // No LUB flip here: rustc coerces a later break to
                        // the earlier breaks' type only (`loop { break &s;
                        // break "b"; }` is E0308).
                        match prev {
                            Some(pt) => {
                                self.coerce_expr(*v, t, pt);
                                self.loops[ti].break_ty = Some(pt);
                            }
                            None => self.loops[ti].break_ty = Some(t),
                        }
                    }
                    None if is_loop => match prev {
                        Some(pt) => {
                            self.coerce_at(UNIT, pt, span, None);
                            self.loops[ti].break_ty = Some(pt);
                        }
                        None => self.loops[ti].break_ty = Some(UNIT),
                    },
                    None => {}
                }
                NEVER
            }
            Expr::Continue(label) => {
                // Edition 2024 (rustc E0695), as for `break` above: an
                // unlabeled continue may not pass through a labeled block.
                if label.is_none()
                    && let Some(lp) = self.loops.last()
                    && lp.is_block
                {
                    self.err(
                        "L0120",
                        span,
                        "unlabeled `continue` inside of a labeled block",
                        "Give the continue the loop's label, such as `continue 'a;`, or move it out of the labeled block.",
                    );
                    return NEVER;
                }
                let found = match label {
                    None => self.loops.iter().rposition(|lp| !lp.is_block),
                    Some(l) => self
                        .loops
                        .iter()
                        .rposition(|lp| lp.label.is_some_and(|(n, bs)| n == l.name && crate::diag::ctxt_can_see_local(l.span.ctxt, bs))),
                };
                match found {
                    None => match label {
                        Some(l) => {
                            let n = self.name(l.name).to_string();
                            self.err("L0120", span, format!("cannot find label `'{n}` in this scope"), "Check the label name.");
                        }
                        None => self.err("L0120", span, "`continue` outside of a loop", "Remove the continue, or put it inside a loop."),
                    },
                    Some(ti) if self.loops[ti].is_block => {
                        self.err("L0120", span, "`continue` cannot target a labeled block", "`continue` needs a loop label.");
                    }
                    Some(_) => {}
                }
                NEVER
            }
            Expr::Return(val) => {
                self.returns_seen += 1;
                if self.closure_rets.is_empty()
                    && let Some(v) = val
                {
                    self.note_ret_expr(*v);
                }
                let ret = self.closure_rets.last().copied().unwrap_or(self.fn_ret);
                match val {
                    Some(v) => {
                        self.expect_expr(*v, ret);
                    }
                    None => {
                        self.coerce_at(UNIT, ret, span, None);
                    }
                }
                NEVER
            }
            Expr::LabeledBlock { label, body } => {
                let want = self.fn_ptr_expectation(expected);
                self.loops.push(LoopCtx { break_ty: None, want, is_loop: true, is_block: true, label: Some((label.name, label.span)) });
                let t = self.block(*body, expected);
                let l = self.loops.pop().unwrap();
                // The tail coerces to the breaks' type (rustc's target is
                // the first break's type in a `let`), so distinct closures
                // or fn items do not join as a fn pointer here; a fn
                // pointer expectation (`LoopCtx::want`) made that type
                // the pointer already.
                match (l.break_ty, p.ast.block(*body).tail) {
                    (Some(bt), Some(tail)) if self.kind(t) != TyKind::Never => {
                        if self.coerce_expr(tail, t, bt) { bt } else { ERROR }
                    }
                    (Some(bt), _) => self.join(bt, t, &[], None, span),
                    (None, _) => t,
                }
            }
            Expr::Macro { kind, args, fmt, repeat } => self.macro_expr(e, *kind, args, fmt, *repeat, span, expected),
            Expr::Tuple(elems) => {
                let exp: Option<Vec<Ty>> = expected.and_then(|t| match self.kind(t) {
                    TyKind::Tuple(ts) if self.tys.tys_of(ts).len() == elems.len() => Some(self.tys.tys_of(ts).to_vec()),
                    _ => None,
                });
                let mut out = Vec::with_capacity(elems.len());
                for (i, &el) in elems.iter().enumerate() {
                    let want = exp.as_ref().map(|v| v[i]);
                    // A `&dyn` element is a coercion site, as in rustc's
                    // tuple check under a tuple expectation.
                    if let Some(w) = self.dyn_ref_expectation(want).or(self.fn_ptr_expectation(want)) {
                        self.expect_expr(el, w);
                        out.push(w);
                    } else if let Some(w) = want {
                        // Every element under a known tuple type is a
                        // coercion site (`&(1, &[true])` at
                        // `&(u8, &[bool])` unsizes the inner array).
                        let bt = self.expr(el, want);
                        out.push(if self.coerce_expr(el, bt, w) { w } else { bt });
                    } else {
                        out.push(self.expr(el, want));
                    }
                }
                for &el in elems.iter() {
                    self.reject_unsized_value(el);
                }
                let ts = self.tys.intern_tys(&out);
                self.tys.intern(TyKind::Tuple(ts))
            }
            Expr::Array(elems) => {
                // An expected array or slice (`&[x]` where `&[Box<dyn Tr>]` is
                // expected) gives the element type each element coerces to,
                // as rustc's `check_expr_array` takes it.
                let exp_elem = expected.and_then(|t| match self.kind(t) {
                    TyKind::Array(el, _) | TyKind::Slice(el) => Some(el),
                    _ => None,
                });
                let elem = self.array_elems(elems, exp_elem);
                for &el in elems.iter() {
                    self.reject_unsized_value(el);
                }
                let c = self.tys.intern_const(ConstKind::Int(elems.len() as u128));
                self.tys.intern(TyKind::Array(elem, c))
            }
            Expr::ArrayRepeat { value, len } => {
                let exp_elem = expected.and_then(|t| match self.kind(t) {
                    TyKind::Array(el, _) => Some(el),
                    _ => None,
                });
                let elem = self.expr(*value, exp_elem);
                self.reject_unsized_value(*value);
                let errs_before = self.errs.len();
                self.in_const(|cx| cx.expect_expr(*len, USIZE));
                // A const param length (`[x; N]`): symbolic in the template
                // check, the instance's value in an instance. The element
                // must be Copy or a const, as for any length above 1.
                // `(N)` is a const operation, not the parameter itself:
                // it falls through to the constant-integer error below.
                if let Expr::Path(segs) = p.ast.expr(*len)
                    && segs.len() == 1
                    && !p.ast.is_parenthesized(*len)
                    && self.lookup(segs[0].name, span.ctxt).is_none()
                    && let Some((i, _, val)) = self.const_param(segs[0].name)
                {
                    let c = self.tys.intern_const(val.unwrap_or(ConstKind::Param(i)));
                    let n = match val {
                        Some(ConstKind::Int(n)) => n,
                        _ => 2,
                    };
                    let const_val = self.repeat_const_operand(*value);
                    let elem_d = self.deep(elem);
                    if n > 1 && !const_val && !is_copy(p, &self.tys, elem_d) {
                        self.err(
                            "L0110",
                            span,
                            "the trait `Copy` is not implemented for this type",
                            "Array repeat with a length above 1 needs a Copy element, or write the elements out.",
                        );
                    }
                    return self.tys.intern(TyKind::Array(elem, c));
                }
                // `[x; Self::D]` where `D` uses a generic parameter of the
                // impl: rustc's "constant expression depends on a generic
                // parameter" (one that uses none is only a warning there).
                if self.len_names_generic_self(*len) {
                    self.err(
                        "L0110",
                        span,
                        "array repeat length must be a constant integer: it depends on a generic parameter",
                        "Use a const parameter directly (`[0; N]`), or a literal length.",
                    );
                    return ERROR;
                }
                // The scalar subset first; then the full bounded
                // evaluator, so size_of calls, const items, and const
                // fn calls all give lengths in expression position.
                let scalar = crate::check::collect::eval_array_len(&p.ast, &p.interner, &p.known, *len);
                if scalar.is_some() && self.errs.len() == errs_before && !p.ast.is_plain_const(*len) {
                    self.const_scan(*len, Some(USIZE));
                }
                let n = scalar.or_else(|| {
                    if self.errs.len() != errs_before {
                        return None;
                    }
                    let mut ccx = CheckCx { cx: self };
                    match crate::ty::consteval::eval(&mut ccx, *len, Some(USIZE)) {
                        Ok((crate::ty::consteval::ConstValue::Int(n), _)) if n >= 0 => Some(n as u128),
                        _ => None,
                    }
                });
                match n {
                    Some(n) => {
                        let const_val = self.repeat_const_operand(*value);
                        let elem_d = self.deep(elem);
                        if n > 1 && !const_val && !is_copy(p, &self.tys, elem_d) {
                            self.err(
                                "L0110",
                                span,
                                "the trait `Copy` is not implemented for this type",
                                "Array repeat with a length above 1 needs a Copy element, or write the elements out.",
                            );
                        }
                        let c = self.tys.intern_const(ConstKind::Int(n));
                        self.tys.intern(TyKind::Array(elem, c))
                    }
                    None => {
                        self.err(
                            "L0110",
                            span,
                            "array repeat length must be a constant integer",
                            "Write a literal length such as `[0; 4]`.",
                        );
                        ERROR
                    }
                }
            }
            Expr::TupleField { base, index } => {
                let bt = self.expr(*base, None);
                self.run_obligations(false);
                let (mut derefs, mut inner) = self.autoderef_smart(bt);
                // As for named fields, autoderef goes on through user
                // `Deref` impls (`m.0` on a `ManuallyDrop<Newtype>`).
                // A Cow base stays a reject (its view is check/cow.rs's).
                for _ in 0..4 {
                    // As for named fields: the lookup reads the field list.
                    if let Some(a) = self.tys.local_adt(inner) {
                        let _ = p.sig_of(&mut self.out.reads, p.def_of_adt(a));
                    }
                    let has = match self.kind(inner) {
                        TyKind::Tuple(ts) => (*index as usize) < self.tys.tys_of(ts).len(),
                        _ if *index == 0 && send_error_elem(&self.tys, inner).is_some() => true,
                        _ => self.tys.local_adt(inner).is_some_and(|a| {
                            !p.adt(a).is_enum && p.adt(a).variants[0].shape == VariantShape::Tuple && (*index as usize) < p.adt(a).variants[0].fields.len()
                        }),
                    };
                    if has || crate::check::collect::cow_arg(&self.tys, inner).is_some() {
                        break;
                    }
                    let Some(target) = self.record_place_deref(e, inner, derefs, span) else { break };
                    let tref = self.tys.mk_ref(false, target);
                    (derefs, inner) = self.autoderef_smart(tref);
                }
                let field_ty = match self.kind(inner) {
                    TyKind::Tuple(ts) => self.tys.tys_of(ts).get(*index as usize).copied(),
                    // `mpsc::SendError<T>(pub T)`: its field is the value
                    // itself (lower.rs keeps the place, cgen/sync.rs).
                    _ if *index == 0 && send_error_elem(&self.tys, inner).is_some() => send_error_elem(&self.tys, inner),
                    _ => match self.tys.local_adt(inner) {
                        Some(a) if !p.adt(a).is_enum && p.adt(a).variants[0].shape == VariantShape::Tuple => {
                            // As for named fields: a generic Adt's field is
                            // the template's, substituted with these args.
                            p.adt(a).variants[0].fields.get(*index as usize).map(|f| match self.tys.adt_parts(inner) {
                                Some((_, args)) if args != EMPTY_ARGS && self.tys.flags(f.ty).contains_param() => {
                                    let gargs: Vec<GenericArg> = self.tys.args(args).to_vec();
                                    self.subst_norm(f.ty, &gargs, span)
                                }
                                _ => f.ty,
                            })
                        }
                        _ => None,
                    },
                };
                match field_ty {
                    Some(t) => {
                        if let Some(a) = self.tys.local_adt(inner) {
                            self.check_tuple_field_vis(a, *index, span);
                        }
                        self.set_res(e, Res::Field { derefs, index: *index });
                        t
                    }
                    None => {
                        if !matches!(self.kind(inner), TyKind::Error) {
                            let tn = self.tn(bt);
                            self.err("L0103", span, format!("no field `{index}` on type `{tn}`"), "Check the field index.");
                        }
                        ERROR
                    }
                }
            }
            Expr::ConstBlock(b) => {
                let b = *b;
                let mut ccx = CheckCx { cx: self };
                match crate::ty::consteval::eval(&mut ccx, e, expected) {
                    Ok((v, t)) => {
                        let i = ccx.cx.ei(e);
                        ccx.cx.out.const_exprs[i] = Some(v);
                        // The block is typed as code too: lowering
                        // borrow-checks it as a body of its own
                        // (lower.rs `check_anon_consts`).
                        let bt = self.in_const(|cx| cx.block(b, Some(t)));
                        self.unify(bt, t);
                        t
                    }
                    // A generic inline const (ARCH 2.13): a layout over the
                    // template's params has no value here, so the template
                    // check checks the block in generic form and each
                    // instance evaluates it with its own types (a failing
                    // assert is then a build error, as rustc's post-mono
                    // error is).
                    Err(d) if d.code == "L0652" && ccx.cx.is_template_check() => self.in_const(|cx| cx.block(b, expected)),
                    Err(d) => {
                        ccx.cx.errs.push(d);
                        ERROR
                    }
                }
            }
            Expr::Let { .. } => {
                self.errs.push(not_yet("L0820", span, "`let` outside an `if` or `while` condition chain"));
                ERROR
            }
            Expr::OffsetOf { ty, fields } => {
                let t = self.resolve_written(*ty);
                let mut cur = self.deep(t);
                // The offset is baked into this body as a constant; the
                // layout fingerprint hashes field types deeply, so one
                // read set over the root type covers the field walk.
                p.record_layout_reads(&mut self.out.reads, &self.tys, cur);
                let mut off: u64 = 0;
                let mut bad = false;
                for &ffield in fields {
                    let Some(a) = self.tys.local_adt(cur) else {
                        self.err("L0110", span, "`offset_of!` needs a struct type", "Use a struct with named fields.");
                        bad = true;
                        break;
                    };
                    if !matches!(
                        p.adt(a).repr.kind,
                        crate::ty::layout::ReprKind::C | crate::ty::layout::ReprKind::Transparent
                    ) && p.adt(a).repr.pack.is_none()
                    {
                        self.err(
                            "L0650",
                            span,
                            "`offset_of!` on a default-repr type is not supported",
                            "Add `#[repr(C)]` to the type, or measure with `size_of`.",
                        );
                        bad = true;
                        break;
                    }
                    let found = match ffield {
                        crate::ast::OffsetField::Name(fname) => p.adt(a).variants[0].fields.iter().position(|f| f.name == fname),
                        crate::ast::OffsetField::Index(idx) => {
                            if p.adt(a).variants[0].shape == VariantShape::Tuple && (idx as usize) < p.adt(a).variants[0].fields.len() {
                                Some(idx as usize)
                            } else {
                                None
                            }
                        }
                    };
                    let Some(i) = found else {
                        let shown = match ffield {
                            crate::ast::OffsetField::Name(fname) => self.name(fname).to_string(),
                            crate::ast::OffsetField::Index(idx) => idx.to_string(),
                        };
                        self.err("L0103", span, format!("no field `{shown}` for `offset_of!`"), "Check the field name.");
                        bad = true;
                        break;
                    };
                    match ffield {
                        crate::ast::OffsetField::Name(fname) => self.check_field_vis(a, fname, span),
                        crate::ast::OffsetField::Index(idx) => self.check_tuple_field_vis(a, idx, span),
                    }
                    match crate::ty::layout::layout_of_ty(&self.tys, &UserLayout(p), cur) {
                        Ok(l) => off += l.field_offsets.get(i).copied().unwrap_or(0),
                        Err(()) => {
                            self.err(
                                "L0652",
                                span,
                                "unsupported layout form in `offset_of!`",
                                "Use a type inside the supported layout grammar.",
                            );
                            bad = true;
                            break;
                        }
                    }
                    cur = p.adt(a).variants[0].fields[i].ty;
                }
                if bad {
                    ERROR
                } else {
                    self.set_res(e, Res::ConstUsize(off));
                    USIZE
                }
            }
            Expr::Closure { is_move, is_async: false, params, ret, body } => self.closure_expr(e, *is_move, params, *ret, *body, expected),
            Expr::Closure { .. } => {
                self.err("L0820", span, "async closures are not supported yet", "Use a plain closure.");
                ERROR
            }
            Expr::Try(inner) => {
                // `?` is a match whose break arm returns, so its value
                // is a diverging variable when nothing else fixes it
                // (`let _ = Err(e)?;`), as in rustc.
                let t = self.try_expr(e, *inner, span, expected);
                self.mark_diverging(t);
                t
            }
            Expr::Underscore => {
                self.err(
                    "L0110",
                    span,
                    "in expressions, `_` can only be used on the left-hand side of an assignment",
                    "Remove the `_`, or use it as a discard target in an assignment.",
                );
                ERROR
            }
            Expr::QPath { self_ty, trait_path, segs } => self.qpath_value(e, *self_ty, trait_path, segs, span),
            // AST v2 expression forms the parser still rejects.
            Expr::Await(_) | Expr::AsyncBlock { .. } | Expr::UnsafeBlock(_) | Expr::MacroCall(_) => ERROR,
        }
    }

    /// The `?` operator. On `Option` the enclosing return type must
    /// be an `Option`; on `Result` it must be a `Result` whose error
    /// type matches, widens numerically, or converts through a
    /// `From` impl, selected here like `From::from` itself is in
    /// `assoc_call`. The conversion plan rides in `Res` for lowering.
    fn try_expr(&mut self, e: ExprId, inner: ExprId, span: Span, expected: Option<Ty>) -> Ty {
        // The operand's expected type, for a try `collect` whose
        // turbofish names the wrapper (`collect::<Result<_, _>>()?`
        // into a `Vec` binding, F3): the binding's type is the
        // value inside the wrapper, so the operand expects the
        // wrapper around it. Only the written wrapper name decides
        // the shape; every other operand keeps no expected type.
        let inner_expected = expected.and_then(|t| {
            let Expr::MethodCall { name, generic_args, .. } = self.p.ast.expr(inner) else { return None };
            if self.name(*name) != "collect" {
                return None;
            }
            let [ast::GenericArg::Type(ty)] = generic_args.as_slice() else { return None };
            let crate::ast::TyExpr::Path(segs) = self.p.ast.ty(*ty) else { return None };
            match segs.last().map(|s| self.name(s.name)) {
                Some("Result") => {
                    let e = self.new_var(false);
                    Some(self.tys.mk_result(t, e))
                }
                Some("Option") => Some(self.tys.mk_option(t)),
                _ => None,
            }
        });
        let it0 = self.expr(inner, inner_expected);
        self.run_obligations(false);
        let it = self.resolve(it0);
        let ret = self.closure_rets.last().copied().unwrap_or(self.fn_ret);
        let ret = self.resolve(ret);
        let general_var = |cx: &Self, t: Ty| matches!(cx.tys.kind(t), TyKind::Infer(v) if !v.is_int() && !v.is_float());
        if let Some(elem) = self.tys.option_elem(it) {
            let ok = self.tys.option_elem(ret).is_some()
                || (general_var(self, ret) && {
                    let v = self.new_var(false);
                    let o = self.tys.mk_option(v);
                    self.unify(ret, o)
                });
            if !ok && self.kind(it) != TyKind::Error && self.kind(ret) != TyKind::Error {
                self.err(
                    "L0112",
                    span,
                    "the `?` operator on an `Option` can only be used in a function that returns `Option`",
                    "Change the return type to `Option<_>`, or handle the `None` case with `match`.",
                );
            }
            self.set_res(e, Res::TryPlain);
            return elem;
        }
        if let Some((ok_t, err_t)) = self.tys.result_args(it) {
            let ret_err = match self.tys.result_args(ret) {
                Some((_, e2)) => Some(e2),
                None if general_var(self, ret) => {
                    let o = self.new_var(false);
                    let r = self.tys.mk_result(o, err_t);
                    if self.unify(ret, r) { Some(err_t) } else { None }
                }
                None => None,
            };
            let Some(ret_err) = ret_err else {
                if self.kind(it) != TyKind::Error && self.kind(ret) != TyKind::Error {
                    self.err(
                        "L0112",
                        span,
                        "the `?` operator on a `Result` can only be used in a function that returns `Result`",
                        "Change the return type to `Result<_, _>`, or handle the `Err` case with `match`.",
                    );
                }
                self.set_res(e, Res::TryPlain);
                return ok_t;
            };
            // An error type still a projection (`x.try_into()?`
            // before a later use fixes the target, fx-tryfrom)
            // decides its conversion at body end, once it
            // normalizes; anything else decides here.
            let err_t = self.normalize_here(err_t);
            if matches!(self.kind(err_t), TyKind::Projection(..)) {
                self.deferred_try.push((e, err_t, ret_err, span));
                self.set_res(e, Res::TryPlain);
                return ok_t;
            }
            self.decide_try_res(e, err_t, ret_err, span);
            return ok_t;
        }
        if let Some((def, b, c)) = self.control_flow_args(it) {
            // `Break(b)` returns as `ControlFlow::Break(b)`: the break
            // types must agree (std's `FromResidual` converts nothing).
            let ok = match self.control_flow_args(ret) {
                Some((_, b2, _)) => self.unify(b, b2),
                None if general_var(self, ret) => {
                    let v = self.new_var(false);
                    let cf = self.tys.mk_adt(def, &[GenericArg::Ty(b), GenericArg::Ty(v)]);
                    self.unify(ret, cf)
                }
                None => false,
            };
            if !ok && self.kind(it) != TyKind::Error && self.kind(ret) != TyKind::Error {
                let tn = self.tn(it);
                self.err(
                    "L0112",
                    span,
                    format!("the `?` operator on `{tn}` can only be used in a function that returns a `ControlFlow` with the same break type"),
                    "Change the return type to `ControlFlow<B, _>` with this `B`, or handle the `Break` case with `match`.",
                );
            }
            self.set_res(e, Res::TryPlain);
            return c;
        }
        if self.kind(it) != TyKind::Error {
            let tn = self.tn(it);
            self.err(
                "L0112",
                span,
                format!("the `?` operator can only be used on `Option`, `Result`, or `ControlFlow` values, not `{tn}`"),
                "Remove the `?`, or produce an `Option` or `Result` first.",
            );
        }
        self.set_res(e, Res::TryPlain);
        ERROR
    }

    /// The def and `(B, C)` args of a `core::ops::ControlFlow<B, C>`
    /// type (std source, W-STD-C), for `?` (`try_expr`).
    fn control_flow_args(&self, t: Ty) -> Option<(DefId, Ty, Ty)> {
        let (def, args) = self.tys.adt_parts(t)?;
        if !self.tys.local_adt_of(def).is_some_and(|a| self.p.is_control_flow_adt(a)) {
            return None;
        }
        match self.tys.args(args) {
            [b, c] => Some((def, b.as_ty()?, c.as_ty()?)),
            _ => None,
        }
    }

    /// Picks how one `?` on `Result` converts its error type
    /// `err_t` into the enclosing return error `ret_err`, and
    /// records it as the expression's `Res`. Runs in `try_expr`,
    /// or at body end for an error type that was still a
    /// projection there (`deferred_try`, fx-tryfrom).
    fn decide_try_res(&mut self, e: ExprId, err_t: Ty, ret_err: Ty, span: Span) {
        let p = self.p;
        // The common case: the error types already agree.
        let snap = self.snapshot_vars();
        if self.unify(err_t, ret_err) {
            self.set_res(e, Res::TryPlain);
            return;
        }
        self.rollback_vars(snap);
        let (e1, e2) = (self.resolve(err_t), self.resolve(ret_err));
        if Self::numeric_from_ok(self.kind(e1), self.kind(e2)) {
            self.set_res(e, Res::TryCast);
            return;
        }
        // The builtin `From<&str>` and `From<&String>` for
        // String: a copy, with no impl record behind it.
        if e2 == STRING && matches!(self.kind(e1), TyKind::Ref(_, _, i) if i == STR || i == STRING) {
            self.set_res(e, Res::TryStringFrom);
            return;
        }
        let args_id = self.tys.intern_args(&[GenericArg::Ty(e2), GenericArg::Ty(e1)]);
        let tr = TraitRef { def: p.gx.lang.from, args: args_id, bindings: EMPTY_BINDINGS };
        // The obligation is what makes a generic body without the
        // `From` bound fail at finish; selection here only picks
        // the call target for lowering.
        self.obl.push_trait_at(tr, span, 0);
        let sel = self.select_obligation_at(tr, span, 0);
        let from_fn = match &sel {
            Selection::Impl { id, args: impl_args, .. } => {
                self.method_instance_for_impl(e, *id, tr, impl_args.clone(), "from", span).map(|(local, _, _)| local)
            }
            _ => None,
        };
        match (sel, from_fn) {
            (_, Some(local)) => self.set_res(e, Res::TryFrom(local)),
            // The MAX marker is a template-only plan: an instance
            // check re-selects and fills in the real target. In a
            // concrete body it would lower as a plain move of the
            // wrong type, so it must not escape a template check.
            (Selection::Impl { .. } | Selection::ParamEvidence(_), None) if self.is_template_check() => {
                self.set_res(e, Res::TryFrom(LocalDefId(u32::MAX)))
            }
            _ => {
                let (a, b) = (self.tn(e1), self.tn(e2));
                self.err(
                    "L0112",
                    span,
                    format!("the `?` operator cannot convert the error type `{a}` to `{b}`"),
                    format!("Implement `From<{a}>` for `{b}`, or map the error before the `?`."),
                );
                self.set_res(e, Res::TryPlain);
            }
        }
    }

    fn unit_body(&mut self, t: Ty, b: ast::BlockId) {
        let block = self.p.ast.block(b);
        if let Some(tail) = block.tail {
            self.coerce_expr(tail, t, UNIT);
        }
    }

    /// The value type `T` of `want` when it is the type builtin `b`
    /// constructs from one value: `Box`, `Rc`, `Arc`, `Mutex`, `RwLock`,
    /// `RefCell`, or `Cell` `::new`.
    fn wrapper_value_ty(&self, b: Builtin, want: Ty) -> Option<Ty> {
        match b {
            Builtin::BoxNew => self.tys.boxed_elem(want),
            Builtin::RcNew => (self.tys.builtin_of(want) == Some(BuiltinTy::Rc)).then(|| self.tys.rc_elem(want)).flatten(),
            Builtin::Sync(sync::SyncOp::ArcNew) => {
                (self.tys.builtin_of(want) == Some(BuiltinTy::Sync(crate::ty::sync::SyncTy::Arc))).then(|| self.tys.rc_elem(want)).flatten()
            }
            Builtin::Sync(sync::SyncOp::LockNew(k)) => self.tys.lock_elem(want).filter(|(w, _)| *w == k).map(|(_, t)| t),
            Builtin::RefCellNew => self.tys.refcell_elem(want),
            Builtin::CellNew => self.tys.cell_elem(want),
            _ => None,
        }
    }

    /// True when `t` is `Sized` as far as it is known: `is_sized`, also
    /// through a `Mutex<T>` or `RwLock<T>` (builtins `is_sized` counts as
    /// sized).
    fn sized_value(&mut self, t: Ty) -> bool {
        let t = self.deep(t);
        if let Some((_, e)) = self.tys.lock_elem(t) {
            return self.sized_value(e);
        }
        crate::check::sized::is_sized(self.p, &mut self.tys, t, &|_| true)
    }

    /// The expected type when it is a pointer to a dyn type: a
    /// reference, or an owning `Box<dyn Tr>` or `Rc<dyn Tr>` (also an
    /// owning pointer to `RefCell<dyn Tr>`, `Mutex<dyn Tr>`, or `[T]`,
    /// check/own.rs). Branch results then coerce to it one by one, as
    /// rustc's expectation does, instead of joining the branch types
    /// first (ARCH 2.8). Also a fn pointer type that names a lifetime of
    /// the fn (W-BORROW3): a method with the impl's early-bound lifetime
    /// fits it, never the joined pointer type of the branches.
    fn dyn_ref_expectation(&self, expected: Option<Ty>) -> Option<Ty> {
        let t = self.resolve(expected?);
        match self.kind(t) {
            TyKind::FnPtr(s) if self.tys.sig(s).value.free_slots != 0 => Some(t),
            TyKind::Ref(_, _, inner) if matches!(self.kind(inner), TyKind::Dyn(..)) => Some(t),
            TyKind::Adt(..) if self.tys.smart_elem(t).is_some_and(|e| matches!(self.kind(self.resolve(e)), TyKind::Dyn(..))) => Some(t),
            TyKind::Adt(..) if own::own_parts(&self.tys, t).is_some_and(|(_, e)| matches!(self.kind(e), TyKind::Slice(_)) || own::dyn_wrapped_elem(&self.tys, e).is_some()) => {
                Some(t)
            }
            _ => None,
        }
    }

    /// The expectation for a later branch of an `if` or `match`: the real
    /// one, else the earlier branches' type as an inference hint. A
    /// closure or fn item type is no hint: rustc checks each branch on its
    /// own and then joins them (two closures make a fn pointer), while a
    /// nested `if` or `match` would coerce its arms to the hint.
    fn branch_hint(&self, expected: Option<Ty>, prev: Option<Ty>) -> Option<Ty> {
        // A diverging earlier branch (`!`) says nothing about the
        // others: `if a { return x; } else if b { 1 } else { 2 }`.
        expected.or(prev.filter(|&t| !matches!(self.kind(self.resolve(t)), TyKind::Closure(..) | TyKind::FnDef(..) | TyKind::Never | TyKind::Error)))
    }

    /// The expected type when it is a fn pointer (see `LoopCtx::want`).
    fn fn_ptr_expectation(&self, expected: Option<Ty>) -> Option<Ty> {
        expected.map(|t| self.resolve(t)).filter(|&t| matches!(self.kind(t), TyKind::FnPtr(_)))
    }

    /// The element type of an array literal (or `vec![..]`) with
    /// elements `elems`, checked against the expected element type
    /// `exp_elem` when there is one, else joined as rustc's LUB does.
    fn array_elems(&mut self, elems: &[ExprId], exp_elem: Option<Ty>) -> Ty {
        match (exp_elem, elems.first()) {
            (Some(el), _) => {
                for &el_e in elems {
                    self.expect_expr(el_e, el);
                }
                self.fn_elems_lub(elems, el);
                el
            }
            (None, Some(&first)) => {
                let el = self.expr(first, None);
                // An array of plain fn items holds function
                // pointers: retag the first element too when any
                // element is a different fn item.
                let elt = self.resolve(el);
                // Closures that capture nothing join as a fn
                // pointer when they differ (rustc's LUB coercion). An
                // element whose form coerces inside (`{ || 2 }`) must
                // have the first element's type, rustc's hint for it.
                if elems.len() > 1 && matches!(self.kind(elt), TyKind::Closure(_, caps) if self.tys.args(caps).is_empty()) {
                    let mut joined = elt;
                    for (i, &el_e) in elems.iter().enumerate().skip(1) {
                        let t = self.expr(el_e, None);
                        if self.kind(self.resolve(t)) == TyKind::Never || (self.coerces_to_hint(el_e) && !self.coerce_expr(el_e, t, elt)) {
                            continue;
                        }
                        joined = match self.closure_lub_sites(joined, t, &elems[..i], Some(el_e)) {
                            Some(fp) => fp,
                            None => {
                                if !self.unify(joined, t) {
                                    let sp = self.span(el_e);
                                    self.mismatch(sp, joined, t);
                                }
                                joined
                            }
                        };
                    }
                    return joined;
                }
                // Fn items join as a fn pointer only when they
                // differ (`[a, b]`); `[a, a]` keeps the item type,
                // which is zero-sized (rustc's LUB coercion).
                if elems.len() > 1 && self.reifies(elt) {
                    let rest: Vec<Ty> = elems[1..].iter().map(|&el_e| self.expr(el_e, None)).collect();
                    for (&el_e, &t) in elems[1..].iter().zip(&rest) {
                        if self.coerces_to_hint(el_e) && self.kind(self.resolve(t)) != TyKind::Never && !self.same_fn_item(elt, t) {
                            let sp = self.span(el_e);
                            self.mismatch(sp, elt, t);
                            return ERROR;
                        }
                    }
                    if rest.iter().all(|&t| self.same_fn_item(elt, t)) {
                        return elt;
                    }
                    let Some((params, ret)) = self.callable_sig(elt) else {
                        return ERROR;
                    };
                    let fp = self.fn_ptr_ty(&params, ret);
                    // A fn path takes the pointer type (lowering then
                    // makes its trampoline); a constructor or builtin
                    // method item coerces.
                    if self.is_ctor_item(elt) || self.is_int_prim_item(elt) {
                        self.coerce_expr(first, elt, fp);
                    } else {
                        self.set(first, fp);
                    }
                    for (&el_e, &t) in elems[1..].iter().zip(&rest) {
                        self.coerce_expr(el_e, t, fp);
                    }
                    // W-BORROW3: rustc's LUB of two fn items needs the
                    // same lifetimes when either is higher-ranked.
                    if let Res::Fn(a) = self.out.expr_res[self.ei(first)] {
                        for &el_e in &elems[1..] {
                            if let Res::Fn(b) = self.out.expr_res[self.ei(el_e)]
                                && a != b
                                && !crate::borrowck::lub_items_fit(self.p, &self.tys, a, b, fp)
                            {
                                let sp = self.span(el_e);
                                self.lub_lifetimes_err(sp);
                            }
                        }
                    }
                    return fp;
                }
                let mut el = el;
                for (i, &el_e) in elems.iter().enumerate().skip(1) {
                    let t = self.expr(el_e, Some(el));
                    if self.lub_flip(&elems[..i], el, t) {
                        el = t;
                    } else {
                        self.coerce_expr(el_e, t, el);
                    }
                }
                self.fn_elems_lub(elems, el);
                el
            }
            (None, None) => self.new_var(false),
        }
    }

    /// True for the expression forms that rustc checks by coercing
    /// their inner value sites to the expected type (a block's tail,
    /// `if` and `match` arms, a loop's breaks). As an array element
    /// after the first, such a form must coerce to the first element's
    /// type, which is rustc's hint there, instead of joining by LUB.
    fn coerces_to_hint(&self, e: ExprId) -> bool {
        matches!(
            self.p.ast.expr(e),
            Expr::Block(_)
                | Expr::UnsafeBlock(_)
                | Expr::LabeledBlock { .. }
                | Expr::ConstBlock(_)
                | Expr::If { .. }
                | Expr::Match { .. }
                | Expr::Loop { .. }
        )
    }

    /// rustc's LUB of the elements of an array or `vec!` literal of fn
    /// pointer type `el` (W-BORROW3): each fn item after the first must
    /// have `el`'s lifetimes up to renaming its binders when either is
    /// higher-ranked (`borrowck::lub_shapes_fit`), else rustc's E0308.
    fn fn_elems_lub(&mut self, elems: &[ExprId], el: Ty) {
        let el = self.deep(el);
        if !matches!(self.kind(el), TyKind::FnPtr(_)) {
            return;
        }
        for &e in elems.iter().skip(1) {
            if let Res::Fn(f) = self.out.expr_res[self.ei(e)]
                && !crate::borrowck::lub_shapes_fit(self.p, &self.tys, f, el)
            {
                let sp = self.span(e);
                self.lub_lifetimes_err(sp);
            }
        }
    }

    /// L0110 for `fn_elems_lub`.
    fn lub_lifetimes_err(&mut self, span: Span) {
        self.err(
            "L0110",
            span,
            "this fn's lifetimes differ from the other elements' fn pointer type: one type is more general than the other",
            "Give the fns in one array or `vec!` the same lifetimes.",
        );
    }

    /// Coerces a block's result to `to` at its tail expression.
    fn coerce_block_tail(&mut self, b: ast::BlockId, t: Ty, to: Ty) {
        let block = self.p.ast.block(b);
        match block.tail {
            Some(tail) => {
                self.coerce_expr(tail, t, to);
            }
            None => {
                self.coerce_at(t, to, block.span, None);
            }
        }
    }

    /// rustc's LUB fallback (CoerceMany): when the new site's type `new`
    /// cannot coerce to `prev`, the type of the earlier sites, but `prev`
    /// coerces to `new` (`[&&d, &d]`, or `match n { 0 => &[], _ => v }`
    /// with `v: &[u8]`), and no earlier site carries a coercion yet, the
    /// earlier sites coerce to `new`. True when it applied them; the
    /// caller then takes `new` as the joined type. The tests are pure,
    /// so a false answer leaves the usual coercion (and its error).
    fn lub_flip(&mut self, prev: &[ExprId], prev_ty: Ty, new: Ty) -> bool {
        if prev.is_empty() || self.kind(prev_ty) == TyKind::Never || self.kind(new) == TyKind::Never {
            return false;
        }
        if self.pure_coercible(new, prev_ty) || !self.pure_coercible(prev_ty, new) {
            return false;
        }
        // rustc lets only no-op adjustments stand on the earlier sites:
        // none, or a `&mut T` to `&T` reborrow of the same pointee.
        if prev.iter().any(|&s| !matches!(self.out.coerce[self.ei(s)], Coerce::None | Coerce::MutToShared | Coerce::Reborrow)) {
            return false;
        }
        for &s in prev {
            let t = self.out.expr_ty[self.ei(s)];
            if self.kind(t) != TyKind::Never {
                self.coerce_expr(s, t, new);
            }
        }
        true
    }

    /// True when `coerce_at` may take `f` to `e`: the types match up to
    /// inference variables, or a reference coercion applies (slice and
    /// `str` unsizing, `&mut` to `&`, deref of extra reference layers),
    /// or `e` is a dyn reference (an unsizing site). Pure.
    fn pure_coercible(&self, f: Ty, e: Ty) -> bool {
        // A shared reference never coerces to `&mut` (`ty_matchish`
        // does not look at mutability).
        if let (TyKind::Ref(_, fm, _), TyKind::Ref(_, em, _)) = (self.kind(f), self.kind(e))
            && em.is_mut()
            && !fm.is_mut()
        {
            return false;
        }
        if self.ty_matchish(f, e) || self.ref_coercible(f, e) {
            return true;
        }
        // A smart pointer to a sized value unsizes to one to a dyn type
        // (`Box<u8>` to `Box<dyn Tr>`).
        if let (Some(x), Some(y)) = (self.tys.smart_elem(self.resolve(f)), self.tys.smart_elem(self.resolve(e)))
            && matches!(self.kind(self.resolve(y)), TyKind::Dyn(..))
            && !matches!(self.kind(self.resolve(x)), TyKind::Dyn(..))
        {
            return true;
        }
        let (TyKind::Ref(..), TyKind::Ref(_, em, y)) = (self.kind(f), self.kind(e)) else { return false };
        if matches!(self.kind(y), TyKind::Dyn(..)) {
            return true;
        }
        let mut t = f;
        while let TyKind::Ref(_, _, inner) = self.kind(t)
            && matches!(self.kind(inner), TyKind::Ref(..))
        {
            t = inner;
            if !em.is_mut() && (self.ty_matchish(t, e) || self.ref_coercible(t, e)) {
                return true;
            }
        }
        false
    }

    /// Joins the types of two branches. A diverging branch takes the
    /// other branch's type. `prev` are the coercion sites that joined to
    /// `a` so far and `be` is the site of `b` (when known).
    fn join(&mut self, a: Ty, b: Ty, prev: &[ExprId], be: Option<ExprId>, span: Span) -> Ty {
        if self.kind(a) == TyKind::Never {
            self.mark_diverging(b);
            return b;
        }
        if self.kind(b) == TyKind::Never {
            self.mark_diverging(a);
            return a;
        }
        // Two closures that capture nothing (or one and a fn item or
        // pointer) with one signature join as a function pointer, as
        // rustc's LUB coercion does; each site gets the reify coercion.
        if let Some(fp) = self.closure_lub_sites(a, b, prev, be) {
            return fp;
        }
        if self.same_fn_item(a, b) {
            return a;
        }
        // Two plain fn items (or an item and a pointer) with one
        // signature join as a function pointer.
        if self.reifies(a) || self.reifies(b) || matches!(self.kind(a), TyKind::FnPtr(_)) {
            if let (Some(sa), Some(sb)) = (self.callable_sig(a), self.callable_sig(b))
                && sa == sb
            {
                // rustc keeps the earlier side's signature, and the later
                // one must be a subtype of it (`lub_out`): `if c { stat }
                // else { tied }` is E0308, the other order joins as tied.
                let out = self.deep(sa.1);
                let mut fp = self.fn_ptr_ty(&sa.0, sa.1);
                if crate::check::closure::holds_region_slots(&self.p.gx.adt_lifetimes, &self.tys, out)
                    && let (Some(false), Some(true)) = (self.out_tied(a), self.out_tied(b))
                {
                    self.mismatch(span, a, b);
                    return ERROR;
                }
                if crate::check::closure::holds_region_slots(&self.p.gx.adt_lifetimes, &self.tys, out)
                    && self.lub_out(a, b) == Some(false)
                    && let Some(st) = crate::check::closure::static_output(&self.p.gx.adt_lifetimes, &mut self.tys, out)
                {
                    fp = self.fn_ptr_ty(&sa.0, st);
                }
                if let Some(be) = be {
                    self.coerce_expr(be, b, fp);
                }
                return fp;
            }
        }
        if let Some(be) = be {
            if self.coerce_expr(be, b, a) {
                return a;
            }
            return ERROR;
        }
        if !self.unify(a, b) {
            self.mismatch(span, a, b);
            return ERROR;
        }
        a
    }

    /// Requires an assignable place expression on the left of `=`.
    /// A reference to a packed field could be unaligned (ARCH 4.4): any borrow
    /// of a field place whose base is a packed Adt, explicit or implicit
    /// (method autoref, format arguments), is an error at the borrow, unless
    /// the field type's alignment is at or under the pack bound, when the
    /// field is always aligned for it and Rust allows the reference.
    fn check_packed_borrow(&mut self, place_e: ExprId, span: Span) {
        let base = match self.p.ast.expr(place_e) {
            Expr::Field { base, .. } | Expr::TupleField { base, .. } => *base,
            _ => return,
        };
        let bt = self.out.expr_ty[self.ei(base)];
        let (_, inner) = self.autoderef(bt);
        if let Some(a) = self.tys.local_adt(inner)
            && let Some(pack) = self.p.adt(a).repr.pack
        {
            // rustc E0793: a reference to a field whose alignment the
            // pack bound caps may be unaligned; at or under the bound
            // the field is aligned and the reference is allowed.
            let ft = self.deep(self.out.expr_ty[self.ei(place_e)]);
            if crate::ty::layout::layout_of_ty(&self.tys, self.p, ft).is_ok_and(|l| l.align <= pack) {
                return;
            }
            self.err("L0651", span, "reference to a packed field is not allowed", "Copy the field value into a local first.");
        }
    }

    /// Assignment into a static is never a plain place write here: an
    /// immutable static cannot be assigned, and a mutable one needs `unsafe`.
    fn static_root(&self, e: ExprId) -> Option<u32> {
        match self.p.ast.expr(e) {
            Expr::Path(_) => match self.out.expr_res[self.ei(e)] {
                Res::Static(idx) => Some(idx),
                _ => None,
            },
            Expr::Field { base, .. } | Expr::TupleField { base, .. } | Expr::Index { base, .. } => self.static_root(*base),
            _ => None,
        }
    }

    /// The type of an assignment target. Tuple and array targets are
    /// destructuring assignment: their elements are targets in turn,
    /// and `_` discards its element with a fresh type variable. Every
    /// other target checks as the place expression it is.
    fn assign_lhs_ty(&mut self, e: ExprId) -> Ty {
        match self.p.ast.expr(e) {
            Expr::Underscore => {
                let t = self.new_var(false);
                self.set(e, t)
            }
            Expr::Tuple(elems) => {
                let ts: Vec<Ty> = elems.iter().map(|&el| self.assign_lhs_ty(el)).collect();
                let id = self.tys.intern_tys(&ts);
                let t = self.tys.intern(TyKind::Tuple(id));
                self.set(e, t)
            }
            Expr::Array(elems) => {
                let mut elem_ty = None;
                for &el in elems {
                    let et = self.assign_lhs_ty(el);
                    match elem_ty {
                        None => elem_ty = Some(et),
                        Some(prev) => {
                            if !self.unify(prev, et) {
                                let s = self.span(el);
                                self.mismatch(s, prev, et);
                            }
                        }
                    }
                }
                let elem = elem_ty.unwrap_or_else(|| self.new_var(false));
                let c = self.tys.intern_const(ConstKind::Int(elems.len() as u128));
                let t = self.tys.intern(TyKind::Array(elem, c));
                self.set(e, t)
            }
            _ => self.expr(e, None),
        }
    }

    /// True for a bare `..` element of an assignment target. The
    /// parser reads it as an open range expression.
    fn is_rest_elem(&self, e: ExprId) -> bool {
        matches!(self.p.ast.expr(e), Expr::Range { lo: None, hi: None, inclusive: false })
    }

    /// True when an assignment target contains a struct form or a
    /// `..` rest, so its element types must come from the right-hand
    /// side type (see `assign_lhs_expected`). Plain tuple and array
    /// targets build their type from their places instead, which
    /// lets the right-hand side infer against them.
    fn assign_lhs_needs_expected(&self, e: ExprId) -> bool {
        match self.p.ast.expr(e) {
            Expr::StructLit { .. } | Expr::Call { .. } => true,
            Expr::Tuple(elems) | Expr::Array(elems) => {
                elems.iter().any(|&el| self.is_rest_elem(el) || self.assign_lhs_needs_expected(el))
            }
            _ => false,
        }
    }

    /// Maps target elements to source indices around a `..` rest,
    /// like `map_tuple_elems` for patterns. None when the counts do
    /// not fit a source of `n` elements.
    fn map_assign_elems(&self, elems: &[ExprId], n: usize) -> Option<Vec<(usize, ExprId)>> {
        match elems.iter().position(|&e| self.is_rest_elem(e)) {
            None => {
                if elems.len() != n {
                    return None;
                }
                Some(elems.iter().enumerate().map(|(i, &e)| (i, e)).collect())
            }
            Some(r) => {
                if elems[r + 1..].iter().any(|&e| self.is_rest_elem(e)) {
                    return None;
                }
                let suffix = elems.len() - r - 1;
                if r + suffix > n {
                    return None;
                }
                let mut out: Vec<(usize, ExprId)> = elems[..r].iter().enumerate().map(|(i, &e)| (i, e)).collect();
                for (j, &e) in elems[r + 1..].iter().enumerate() {
                    out.push((n - suffix + j, e));
                }
                Some(out)
            }
        }
    }

    /// Resolves the struct or variant an assignment target names and
    /// unifies it with the right-hand side type, as a pattern does
    /// with its scrutinee. Answers the Adt, the variant, and the
    /// scrutinee's generic arguments for field substitution. An enum
    /// variant of a multi-variant enum can fail to match, so it is
    /// an error here (rustc E0005) but still resolves.
    fn assign_variant(&mut self, segs: &[ast::PathSeg], want: Ty, span: Span) -> Option<(AdtId, u32, Vec<GenericArg>)> {
        let p = self.p;
        let target = if segs.len() == 1 {
            let n = segs[0].name;
            if n != p.known.self_type {
                self.binding(Namespace::Type, n);
            }
            let a = if n == p.known.self_type { self.self_adt() } else { self.type_name_adt(n) };
            match a.filter(|&a| !p.adt(a).is_enum).map(|a| (a, 0)) {
                Some(v) => Some(v),
                None => match self.pat_ident(n) {
                    PatIdent::Variant(a, v) => Some((a, v)),
                    _ => None,
                },
            }
        } else {
            match self.resolve_assoc(segs, span) {
                Some(Res::Variant(a, v)) => Some((a, v)),
                Some(_) => {
                    self.err("L0110", span, "expected a variant or struct in this pattern", "Use `Type::Variant`.");
                    None
                }
                None => return None,
            }
        };
        let Some((a, v)) = target else {
            let last = segs.last().map(|s| s.name);
            if last == Some(p.known.Some) || last == Some(p.known.Ok) || last == Some(p.known.Err) {
                self.err("L0110", span, "refutable pattern in assignment", "Use `if let` or `match` for a pattern that can fail.");
            } else {
                self.err("L0102", span, "unknown struct or variant in pattern", "Check the name.");
            }
            return None;
        };
        // A path through `Self` names the impl's own type.
        if let Some(args) = self.self_path_args(a, segs, span)
            && !args.is_empty()
        {
            let st = self.tys.mk_adt(p.def_of_adt(a), &args);
            if !self.unify(st, want) {
                self.mismatch(span, want, st);
                return None;
            }
        }
        let dt = self.deep(want);
        let scrut_args: Vec<GenericArg> = match self.tys.adt_parts(dt) {
            Some((d, aa)) if d == p.def_of_adt(a) => self.tys.args(aa).to_vec(),
            _ => Vec::new(),
        };
        let (a, adt_ty) = match self.tys.local_adt(dt) {
            Some(inst) if inst != a && p.def_of_adt(inst) == p.def_of_adt(a) => (inst, dt),
            _ if !scrut_args.is_empty() => (a, dt),
            _ => (a, self.tys.adt_ty(a)),
        };
        if !self.unify(adt_ty, want) {
            self.mismatch(span, want, adt_ty);
            return None;
        }
        if p.adt(a).is_enum && p.adt(a).variants.len() != 1 {
            self.err("L0110", span, "refutable pattern in assignment", "Use `if let` or `match` for a pattern that can fail.");
        }
        Some((a, v, scrut_args))
    }

    /// Checks an assignment target against the right-hand side type,
    /// top down, as a pattern checks against its scrutinee type.
    /// Used for targets with a struct form or a `..` rest. Records
    /// the target type on every sub-target, which lowering reads for
    /// the element types of struct forms.
    fn assign_lhs_expected(&mut self, e: ExprId, want: Ty) {
        let p = self.p;
        let span = self.span(e);
        match p.ast.expr(e) {
            Expr::Underscore => {
                self.set(e, want);
            }
            Expr::Tuple(elems) => {
                self.set(e, want);
                match self.kind(want) {
                    TyKind::Tuple(ts) => {
                        let kt: Vec<Ty> = self.tys.tys_of(ts).to_vec();
                        match self.map_assign_elems(elems, kt.len()) {
                            Some(mapped) => {
                                for (i, sub) in mapped {
                                    self.assign_lhs_expected(sub, kt[i]);
                                }
                            }
                            None => {
                                self.err(
                                    "L0110",
                                    span,
                                    format!("this tuple has {} element(s)", kt.len()),
                                    "Match every element, use `_`, or skip the middle with `..`.",
                                );
                                for &sub in elems {
                                    if !self.is_rest_elem(sub) {
                                        self.assign_lhs_expected(sub, ERROR);
                                    }
                                }
                            }
                        }
                    }
                    TyKind::Error => {
                        for &sub in elems {
                            if !self.is_rest_elem(sub) {
                                self.assign_lhs_expected(sub, ERROR);
                            }
                        }
                    }
                    _ => {
                        let vars: Vec<Ty> = elems.iter().map(|_| self.new_var(false)).collect();
                        for (i, &sub) in elems.iter().enumerate() {
                            if !self.is_rest_elem(sub) {
                                self.assign_lhs_expected(sub, vars[i]);
                            }
                        }
                        let ts = self.tys.intern_tys(&vars);
                        let tt = self.tys.intern(TyKind::Tuple(ts));
                        if !self.unify(tt, want) {
                            self.mismatch(span, want, tt);
                        }
                    }
                }
            }
            Expr::Array(elems) => {
                self.set(e, want);
                let (elem, arr_len, is_slice) = match self.kind(want) {
                    TyKind::Array(el, c) => {
                        let n = match self.tys.const_kind(c) {
                            ConstKind::Int(n) => Some(n as usize),
                            _ => None,
                        };
                        (el, n, false)
                    }
                    TyKind::Slice(el) => (el, None, true),
                    TyKind::Error => {
                        for &sub in elems {
                            if !self.is_rest_elem(sub) {
                                self.assign_lhs_expected(sub, ERROR);
                            }
                        }
                        return;
                    }
                    _ => {
                        let tn = self.tn(want);
                        self.err(
                            "L0110",
                            span,
                            format!("slice pattern cannot match a value of type `{tn}`"),
                            "Match on an array or a slice, for example `&value[..]`.",
                        );
                        for &sub in elems {
                            if !self.is_rest_elem(sub) {
                                self.assign_lhs_expected(sub, ERROR);
                            }
                        }
                        return;
                    }
                };
                if is_slice {
                    // A slice can be too short, so this can fail.
                    self.err("L0110", span, "refutable pattern in assignment", "Use `if let` or `match` for a pattern that can fail.");
                    for &sub in elems {
                        if !self.is_rest_elem(sub) {
                            self.assign_lhs_expected(sub, elem);
                        }
                    }
                    return;
                }
                match arr_len {
                    Some(n) => match self.map_assign_elems(elems, n) {
                        Some(mapped) => {
                            for (_, sub) in mapped {
                                self.assign_lhs_expected(sub, elem);
                            }
                        }
                        None => {
                            let fixed = elems.iter().filter(|&&s| !self.is_rest_elem(s)).count();
                            self.err(
                                "L0110",
                                span,
                                format!("pattern requires {fixed} element(s) but the array has {n}"),
                                "Change the pattern length, or skip the middle with `..`.",
                            );
                            for &sub in elems {
                                if !self.is_rest_elem(sub) {
                                    self.assign_lhs_expected(sub, elem);
                                }
                            }
                        }
                    },
                    None => {
                        for &sub in elems {
                            if !self.is_rest_elem(sub) {
                                self.assign_lhs_expected(sub, elem);
                            }
                        }
                    }
                }
            }
            Expr::StructLit { path, fields, update } => {
                self.set(e, want);
                let rest = update.is_some_and(|u| self.is_rest_elem(u));
                if let Some(u) = update {
                    if rest {
                        self.set(*u, ERROR);
                    } else {
                        self.expr(*u, None);
                        self.err(
                            "L0121",
                            span,
                            "invalid left-hand side of assignment",
                            "Assign to a variable, a field, an index, or `*reference`.",
                        );
                    }
                }
                let Some((a, v, scrut_args)) = self.assign_variant(path, want, span) else {
                    for &(_, _, fe) in fields {
                        self.assign_lhs_expected(fe, ERROR);
                    }
                    return;
                };
                self.set_res(e, Res::Variant(a, v));
                let variant = &p.adt(a).variants[v as usize];
                if variant.shape != VariantShape::Named {
                    self.err("L0110", span, "this variant does not have named fields", "Use the tuple form.");
                    for &(_, _, fe) in fields {
                        self.assign_lhs_expected(fe, ERROR);
                    }
                    return;
                }
                let mut seen = vec![false; variant.fields.len()];
                for &(fname, fspan, fe) in fields {
                    match variant.fields.iter().position(|f| f.name == fname) {
                        Some(i) => {
                            if seen[i] {
                                self.err("L0106", fspan, format!("field `{}` is set twice", self.name(fname)), "Remove one of them.");
                            }
                            seen[i] = true;
                            self.check_field_vis(a, fname, fspan);
                            let ft = variant.fields[i].ty;
                            let ft = if scrut_args.is_empty() { ft } else { self.subst_norm(ft, &scrut_args, span) };
                            self.assign_lhs_expected(fe, ft);
                        }
                        None => {
                            self.assign_lhs_expected(fe, ERROR);
                            self.err("L0103", fspan, format!("no field `{}` in this variant", self.name(fname)), "Check the field name.");
                        }
                    }
                }
                self.check_ne_pat(a, v, rest, span);
                if !rest && seen.iter().any(|s| !s) {
                    self.err("L0107", span, "pattern does not mention all fields", "Add the missing fields, or end the pattern with `..`.");
                }
            }
            Expr::Call { callee, args } => {
                self.set(e, want);
                let Expr::Path(segs) = p.ast.expr(*callee) else {
                    self.err(
                        "L0121",
                        span,
                        "invalid left-hand side of assignment",
                        "Assign to a variable, a field, an index, or `*reference`.",
                    );
                    for &arg in args {
                        if !self.is_rest_elem(arg) {
                            self.assign_lhs_expected(arg, ERROR);
                        }
                    }
                    return;
                };
                let segs = segs.clone();
                let Some((a, v, scrut_args)) = self.assign_variant(&segs, want, span) else {
                    for &arg in args {
                        if !self.is_rest_elem(arg) {
                            self.assign_lhs_expected(arg, ERROR);
                        }
                    }
                    return;
                };
                self.set_res(e, Res::Variant(a, v));
                self.set_res(*callee, Res::Variant(a, v));
                self.set(*callee, ERROR);
                let variant = &p.adt(a).variants[v as usize];
                if variant.shape != VariantShape::Tuple {
                    self.err(
                        "L0110",
                        span,
                        format!("this variant has {} field(s)", variant.fields.len()),
                        "Match every field, or use `_` for the ones you do not need.",
                    );
                    for &arg in args {
                        if !self.is_rest_elem(arg) {
                            self.assign_lhs_expected(arg, ERROR);
                        }
                    }
                    return;
                }
                if !p.adt(a).is_enum {
                    self.check_ctor_vis(a, span);
                }
                self.check_ne_ctor(a, v, span);
                match self.map_assign_elems(args, variant.fields.len()) {
                    Some(mapped) => {
                        for (i, sub) in mapped {
                            let ft = variant.fields[i].ty;
                            let ft = if scrut_args.is_empty() { ft } else { self.subst_norm(ft, &scrut_args, span) };
                            self.assign_lhs_expected(sub, ft);
                        }
                    }
                    None => {
                        self.err(
                            "L0110",
                            span,
                            format!("this variant has {} field(s)", variant.fields.len()),
                            "Match every field, use `_`, or skip the middle with `..`.",
                        );
                        for &arg in args {
                            if !self.is_rest_elem(arg) {
                                self.assign_lhs_expected(arg, ERROR);
                            }
                        }
                    }
                }
            }
            _ => {
                let t = self.expr(e, None);
                if !self.unify(t, want) {
                    self.mismatch(span, want, t);
                }
            }
        }
    }

    fn place_check(&mut self, e: ExprId, destr: bool) {
        if let Some(idx) = self.static_root(e) {
            let s = self.span(e);
            if self.p.statics[idx as usize].mutable {
                self.err(
                    "L0404",
                    s,
                    "writing a mutable static requires `unsafe`, which is not supported",
                    "Make the static immutable, or use a local variable.",
                );
            } else {
                self.err("L0121", s, "cannot assign to an immutable static", "Statics are read-only; use a variable instead.");
            }
            return;
        }
        let ok = match self.p.ast.expr(e) {
            Expr::Path(segs) => {
                (segs.len() == 1 && matches!(self.out.expr_res[self.ei(e)], Res::Local(_)))
                    || (destr
                        && match self.out.expr_res[self.ei(e)] {
                            // A unit variant target (`U = make_u();`)
                            // writes nothing. A variant of a
                            // multi-variant enum can fail to match.
                            Res::Variant(a, v) => {
                                self.p.adt(a).variants[v as usize].shape == VariantShape::Unit
                                    && (!self.p.adt(a).is_enum || self.p.adt(a).variants.len() == 1)
                            }
                            _ => false,
                        })
            }
            Expr::Field { .. } | Expr::TupleField { .. } | Expr::Index { .. } | Expr::Deref(_) | Expr::SelfValue => true,
            Expr::Underscore => true,
            Expr::Unit => destr,
            Expr::Tuple(elems) | Expr::Array(elems) => {
                for &el in elems {
                    if !self.is_rest_elem(el) {
                        self.place_check(el, destr);
                    }
                }
                return;
            }
            Expr::StructLit { fields, .. } if destr => {
                for &(_, _, fe) in fields {
                    self.place_check(fe, destr);
                }
                return;
            }
            Expr::Call { args, .. } if destr && matches!(self.out.expr_res[self.ei(e)], Res::Variant(..)) => {
                for &arg in args {
                    if !self.is_rest_elem(arg) {
                        self.place_check(arg, destr);
                    }
                }
                return;
            }
            _ => false,
        };
        if !ok {
            let s = self.span(e);
            self.err("L0121", s, "invalid left-hand side of assignment", "Assign to a variable, a field, an index, or `*reference`.");
        }
    }

    /// Strips all references. Returns the count and the inner type.
    fn autoderef(&self, t: Ty) -> (u8, Ty) {
        let mut t = self.resolve(t);
        let mut n = 0;
        while let TyKind::Ref(_, _, inner) = self.tys.kind(t) {
            t = self.resolve(inner);
            n += 1;
        }
        (n, t)
    }

    /// Autoderef through references and `Box`: the chain field
    /// access, indexing, and method calls follow in Rust. The
    /// count is in the same units as `autoderef` (one `Deref`
    /// projection per step), so recorded resolutions lower
    /// uniformly.
    /// The (derefs, autoref) adjustment that takes a receiver
    /// of type `rt` to a typed receiver type `want` (`Box<Self>`,
    /// `&Rc<Self>`, kin), if one exists: peel references and
    /// smart pointers until the type is `want` itself (by
    /// value) or the pointee of the reference `want` asks for.
    fn typed_receiver_adjust(&self, rt: Ty, want: Ty) -> Option<(u8, Autoref)> {
        let want = self.resolve(want);
        let mut t = self.resolve(rt);
        for d in 0..8u8 {
            if t == want {
                return Some((d, Autoref::None));
            }
            if let TyKind::Ref(_, m, inner) = self.kind(want)
                && self.resolve(inner) == t
            {
                return Some((d, if m.is_mut() { Autoref::RefMut } else { Autoref::Ref }));
            }
            t = match self.kind(t) {
                TyKind::Ref(_, _, inner) => self.resolve(inner),
                _ => self.resolve(self.tys.smart_elem(t)?),
            };
        }
        None
    }

    /// Where the method probe of call `e` on a receiver of type `rt`
    /// starts, as (derefs, step type): a call through a user `Deref`
    /// (`method_via_user_deref`) checks on `&Target`, a step rustc does
    /// not have, so its probe starts one deref in, at the target place.
    pub(super) fn probe_start(&self, e: ExprId, rt: Ty) -> (u8, Ty) {
        let rt = self.resolve(rt);
        match self.tys.kind(rt) {
            TyKind::Ref(_, _, inner) if self.user_deref_call == Some(e) => (1, self.resolve(inner)),
            _ => (0, rt),
        }
    }

    /// True for a std container type with a known head whose `Clone`
    /// only waits on an open element variable: `Vec<_>`, `Option<_>`,
    /// `Result<_, _>`, `HashMap<_, _>`, `HashSet<_>`, a tuple or an
    /// array. Core's impls there are Clone exactly when the elements are
    /// (`deferred_clone` checks that at body end). Not `Box<_>` or
    /// `Rc<_>`: rustc's method probe derefs them to the open `_` and
    /// stops (E0282, type must be known at this point).
    fn open_std_clone_head(&self, t: Ty) -> bool {
        let t = self.resolve(t);
        if !self.has_unbound_deep(t) {
            return false;
        }
        matches!(self.tys.kind(t), TyKind::Tuple(_) | TyKind::Array(..))
            || self.tys.vec_elem(t).is_some()
            || self.tys.option_elem(t).is_some()
            || self.tys.result_args(t).is_some()
            || crate::ty::hash::hash_parts(&self.tys, t).is_some_and(|(k, _)| matches!(k, crate::ty::hash::HashTy::HashMap | crate::ty::hash::HashTy::HashSet))
    }

    /// rustc's probe for `Clone::clone` (`&self`) or, with `mutable`,
    /// `clone_from` (`&mut self`) over the reference and guard steps of
    /// `rt`: the first step whose by-value form (the step is `&Self`, or
    /// `&mut Self`) or autoref form has a Clone `Self`. A shared reference
    /// is Clone, so the walk stops at the first one: `(&&s).clone()` is
    /// `&String`, `(&s).clone()` is `String`, `(& &mut s).clone()` is
    /// `& &mut String`. Gives the derefs to `Self` (units as `autoderef`)
    /// and `Self`; None when no step has a Clone `Self` (the later
    /// dispatch reports or finds a user `Deref` step).
    fn clone_self_step(&self, e: ExprId, rt: Ty, mutable: bool) -> Option<(u8, Ty)> {
        let p = self.p;
        let (mut d, mut t) = self.probe_start(e, rt);
        loop {
            if let TyKind::Ref(_, m, inner) = self.tys.kind(t)
                && m.is_mut() == mutable
                && has_clone(p, &self.tys, self.resolve(inner))
            {
                return Some((d + 1, self.resolve(inner)));
            }
            // `clone` autorefs with `&`, `clone_from` with `&mut`.
            if has_clone(p, &self.tys, t) {
                return Some((d, t));
            }
            t = match self.tys.kind(t) {
                TyKind::Ref(_, _, inner) => self.resolve(inner),
                _ => self.resolve(self.tys.guard_elem(t)?.0),
            };
            d = d.checked_add(1)?;
        }
    }

    /// `x.clone()` or `x.clone_from(src)` when `clone_self_step` puts Self
    /// at a reference type: the builtin copy of that reference. None when
    /// Self is no reference (the dispatch below answers at the pointee).
    fn ref_clone_call(&mut self, e: ExprId, recv: ExprId, rt: Ty, name: Sym, name_span: Span, args: &[ExprId]) -> Option<Ty> {
        let mutable = match self.name(name) {
            "clone" => false,
            "clone_from" => true,
            _ => return None,
        };
        let (derefs, self_ty) = self.clone_self_step(e, rt, mutable)?;
        if !matches!(self.tys.kind(self_ty), TyKind::Ref(..)) {
            return None;
        }
        // A user trait's `clone` may come first or tie: the user method
        // probe decides.
        let std_recv = self.tys.mk_ref(mutable, self_ty);
        if self.user_trait_at_or_before(e, rt, name, std_recv) {
            return None;
        }
        let lang = self.p.gx.lang;
        let (_, base) = self.autoderef(rt);
        self.record_glue_reads(lang.clone, base);
        self.check_packed_borrow(recv, name_span);
        if mutable {
            self.set_res(e, Res::BuiltinMethod { b: Builtin::CloneFrom, derefs, autoref: Autoref::RefMut });
            let src = self.tys.mk_ref(false, self_ty);
            self.check_args(&[src], args, name_span);
            return Some(UNIT);
        }
        self.set_res(e, Res::BuiltinMethod { b: Builtin::Clone, derefs, autoref: Autoref::Ref });
        // An instance must clone the same reference even where its
        // pointee type is Clone (`t.clone()` on `t: &T`, T unbounded).
        // (`clone_from`'s walk never asks a pointee type at a shared step.)
        self.record_pick(e, lang.clone, derefs, ReceiverForm::Ref);
        self.check_args(&[], args, name_span);
        Some(self_ty)
    }

    fn autoderef_smart(&self, t: Ty) -> (u8, Ty) {
        let (mut n, mut base) = self.autoderef(t);
        while let Some(inner) = self.tys.smart_elem(base) {
            base = self.resolve(inner);
            n += 1;
            let (d, b) = self.autoderef(base);
            n += d;
            base = b;
        }
        (n, base)
    }
    fn peel_one_ref(&self, t: Ty) -> (u8, Ty) {
        match self.kind(t) {
            TyKind::Ref(_, _, inner) => (1, inner),
            _ => (0, t),
        }
    }
    /// True when `e` is a byte string literal, which the parser
    /// builds as a reference to a byte array literal.
    fn is_byte_str_lit(&self, e: ExprId) -> bool {
        match self.p.ast.expr(e) {
            Expr::Ref { mutable: false, raw: false, expr } => matches!(self.p.ast.expr(*expr), Expr::ByteStr(_) | Expr::Array(_)),
            _ => false,
        }
    }

    /// True when a byte string pattern of type `&[u8; N]` may match
    /// a scrutinee of type `t`: rustc also allows `&[u8]` with the
    /// same mutability and element type. Other shapes (an array
    /// value, `&str`, a different length) stay type errors.
    fn byte_str_pat_ok(&mut self, lt: Ty, t: Ty) -> bool {
        let (TyKind::Ref(_, lm, li), TyKind::Ref(_, tm, ti)) = (self.kind(lt), self.kind(t)) else { return false };
        if lm != tm {
            return false;
        }
        match (self.kind(li), self.kind(ti)) {
            (TyKind::Array(e1, _), TyKind::Slice(e2)) => self.unify(e1, e2),
            _ => false,
        }
    }

    /// The value of a float pattern bound, widened to `f64` (exact
    /// for `f32`), if it is known: a float literal (possibly
    /// negated) or a const the checker evaluated.
    fn const_float(&self, e: ExprId, ft: crate::ty::FloatTy) -> Option<f64> {
        use crate::ty::FloatTy;
        if let Some(cv) = &self.out.const_exprs[self.ei(e)] {
            return match cv {
                crate::ty::consteval::ConstValue::Float(bits, FloatTy::F32) => Some(f32::from_bits(*bits as u32) as f64),
                crate::ty::consteval::ConstValue::Float(bits, FloatTy::F64) => Some(f64::from_bits(*bits)),
                _ => None,
            };
        }
        match self.p.ast.expr(e) {
            Expr::Float(i) => {
                let text = &self.p.ast.strings[*i as usize];
                crate::check::collect::parse_float_literal_as(text, ft).map(|bits| match ft {
                    FloatTy::F32 => f32::from_bits(bits as u32) as f64,
                    FloatTy::F64 => f64::from_bits(bits),
                })
            }
            Expr::Unary { op: UnOp::Neg, expr } => self.const_float(*expr, ft).map(|v| -v),
            _ => None,
        }
    }

    /// The value of a literal expression (an integer, possibly negated, or a char), if it is one.
    fn const_scalar(&self, e: ExprId) -> Option<i128> {
        // A const item or associated const the checker evaluated.
        if let Some(cv) = &self.out.const_exprs[self.ei(e)] {
            return match cv {
                crate::ty::consteval::ConstValue::Int(v) => Some(*v),
                crate::ty::consteval::ConstValue::Char(c) => Some(*c as i128),
                crate::ty::consteval::ConstValue::Bool(b) => Some(*b as i128),
                _ => None,
            };
        }
        match self.p.ast.expr(e) {
            Expr::Int(v, _) => Some(*v as u128 as i128),
            Expr::Char(c) => Some(*c as i128),
            Expr::Unary { op: UnOp::Neg, expr } => match self.p.ast.expr(*expr) {
                Expr::Int(v, _) => {
                    if *v == (1u128 << 127) {
                        Some(i128::MIN)
                    } else {
                        Some(-(*v as i128))
                    }
                }
                _ => None,
            },
            _ => None,
        }
    }
    /// The mutability of each reference layer of `t`, outermost first.
    fn ref_layers(&self, t: Ty) -> Vec<bool> {
        let mut out = Vec::new();
        let mut t = t;
        while let TyKind::Ref(_, m, inner) = self.kind(t) {
            out.push(m.is_mut());
            t = inner;
        }
        out
    }

    /// Rejects an explicit lifetime in a value path's turbofish
    /// (`f::<'static>`, ARCH 5.5): rustc rejects it whenever the fn has a
    /// late-bound lifetime (E0794); lust rejects it always (W-BORROW).
    fn lifetime_turbofish(&mut self, segs: &[ast::PathSeg]) {
        let p = self.p;
        for seg in segs {
            if let ast::GenericArgs::Angle(args) = &seg.args {
                for g in args {
                    if let ast::GenericArg::Lifetime(lt) = g
                        && p.interner.get(lt.name) != "_"
                    {
                        self.err("L0731", lt.span, "explicit lifetime arguments on a fn are not supported", "Remove the lifetime argument; Rust infers it.");
                    }
                }
            }
        }
    }

    /// The written type args on a builtin `Option`/`Result` constructor
    /// path (`None::<u8>`, `Option::<u8>::Some`, `Ok::<u8, E>`,
    /// `Result::<u8, E>::Err`), `n` of them in the type's param order;
    /// `_` is a fresh variable. None when the path writes no type args;
    /// a wrong count is rustc's E0107.
    fn builtin_ctor_args(&mut self, segs: &[ast::PathSeg], n: usize, span: Span) -> Option<Vec<Ty>> {
        let p = self.p;
        // Through an alias (`type OP = Option<u8>; OP::Some(3)`) the
        // alias's type gives them; `resolve_assoc` reported its errors.
        if let Some(t) = self.builtin_alias_ty(segs, span, false) {
            return Some(self.builtin_self_args(t, n));
        }
        let written: Vec<ast::TyId> = segs.iter().flat_map(|s| s.type_args()).collect();
        if written.is_empty() {
            return None;
        }
        if written.len() != n {
            self.err(
                "L0107",
                span,
                format!("this type takes {n} generic argument(s) but {} were given", written.len()),
                "Write one type per parameter.",
            );
            return Some((0..n).map(|_| ERROR).collect());
        }
        Some(
            written
                .into_iter()
                .map(|g| if matches!(p.ast.ty(g), ast::TyExpr::Infer) { self.new_var(false) } else { self.resolve_written(g) })
                .collect(),
        )
    }

    /// The const generic param a body path names (`N`): its index in
    /// the template's generics, its declared type, and in an instance
    /// its value from the instance's args (None in the template). None
    /// when `name` names no const param here.
    /// True when the array length `e` reads `Self::D` (through operators,
    /// casts, and calls) for an inherent associated const `D` whose value
    /// uses a generic parameter of its impl (`p.gx.assoc_const_tmpls`):
    /// rustc rejects such a length, as an anonymous const may not use
    /// generic parameters.
    fn len_names_generic_self(&mut self, e: ExprId) -> bool {
        let p = self.p;
        match p.ast.expr(e) {
            Expr::Path(segs) if segs.len() == 2 && segs[0].name == p.known.self_type => {
                let segs = segs.clone();
                let Some((adt, item)) = self.assoc_const_key(&segs) else { return false };
                let Some(base) = self.assoc_const_base(&segs, None) else { return false };
                matches!(self.inherent_assoc_pick(adt, item, base, None), Some(Some((idx, _))) if p.gx.assoc_const_tmpls.contains_key(&idx))
            }
            Expr::Binary { lhs, rhs, .. } => {
                let (l, r) = (*lhs, *rhs);
                self.len_names_generic_self(l) || self.len_names_generic_self(r)
            }
            Expr::Unary { expr, .. } | Expr::Cast { expr, .. } => {
                let x = *expr;
                self.len_names_generic_self(x)
            }
            Expr::Call { args, .. } | Expr::MethodCall { args, .. } => {
                let args = args.clone();
                args.iter().any(|&a| self.len_names_generic_self(a))
            }
            _ => false,
        }
    }

    fn const_param(&mut self, name: Sym) -> Option<(u32, Ty, Option<ConstKind>)> {
        let p = self.p;
        let decl = |tl: LocalDefId, i: u32| -> Option<Ty> {
            match p.gx.fn_templates.get(tl.0 as usize)?.as_ref()?.generics.params.get(i as usize)?.kind {
                ParamKind::Const(t) => Some(t),
                _ => None,
            }
        };
        if let Some(&(_, i, _)) = self.body_scope.const_params.iter().find(|(n, ..)| *n == name) {
            return Some((i, decl(self.fid, i)?, None));
        }
        let info = p.gx.instances.get(&self.fid)?;
        let tl = info.template_local?;
        let &(_, i, _) = p.gx.fn_scopes.get(tl.0 as usize)?.scope.const_params.iter().find(|(n, ..)| *n == name)?;
        let GenericArg::Const(c) = *p.tys.args(info.args).get(i as usize)? else { return None };
        Some((i, decl(tl, i)?, Some(p.tys.const_kind(c))))
    }

    fn path_expr(&mut self, e: ExprId, segs: &[ast::PathSeg], span: Span) -> Ty {
        let p = self.p;
        // `U::MAX` through `type U = u8` is `u8::MAX` (check/alias_path.rs).
        if let Some(canon) = self.primitive_alias_segs(segs, span) {
            return self.path_expr(e, &canon, span);
        }
        if segs.len() == 1 {
            let name = segs[0].name;
            if let Some(l) = self.lookup(name, span.ctxt) {
                if l < self.const_floor {
                    return self.non_const_local(span);
                }
                self.set_res(e, Res::Local(l));
                return self.out.locals[l as usize].ty;
            }
            // A unit or tuple struct of an enclosing block (R18).
            if let Some(a) = self.local_ctor_of(name) {
                self.set_res(e, Res::Variant(a, 0));
                return match p.adt(a).variants[0].shape {
                    VariantShape::Unit => self.unit_value_ty(e, a, span),
                    _ => self.ctor_value_ty(e, a, 0, span),
                };
            }
            match self.body_item_of(name) {
                Some(crate::check::collect::BodyItem::Fn(f)) => {
                    // A nested fn used as a value is a fn item like a
                    // top-level one (its type was the error type with no
                    // diagnostic, so `k as fn(..)` built a null pointer).
                    self.set_res(e, Res::Fn(f));
                    return self.fn_value_ty(e, f, span);
                }
                Some(crate::check::collect::BodyItem::Const(ci)) => {
                    let c = &p.body_consts[ci as usize];
                    let (v, t) = (c.value.clone(), c.ty);
                    let i = self.ei(e);
                    self.out.const_exprs[i] = Some(v);
                    self.out.const_quals.insert(e, c.qualif);
                    return self.deep(t);
                }
                Some(crate::check::collect::BodyItem::Static(idx)) => {
                    let st = &p.statics[idx as usize];
                    if st.mutable {
                        self.err(
                            "L0404",
                            span,
                            "reading a mutable static requires `unsafe`, which is not supported",
                            "Make the static immutable, or read it through a const.",
                        );
                        return ERROR;
                    }
                    let t = st.ty;
                    self.set_res(e, Res::Static(idx));
                    return self.deep(t);
                }
                None => {}
            }
            // A const generic param (`N`): abstract in the template check
            // (a placeholder value for its own lowering), the instance's
            // arg in an instance.
            if let Some((_, t, val)) = self.const_param(name) {
                let i = self.ei(e);
                match val {
                    Some(ConstKind::Int(v)) => self.out.const_exprs[i] = Some(crate::ty::consteval::ConstValue::Int(v as i128)),
                    Some(ConstKind::Bool(b)) => self.out.const_exprs[i] = Some(crate::ty::consteval::ConstValue::Bool(b)),
                    Some(ConstKind::Char(c)) => self.out.const_exprs[i] = Some(crate::ty::consteval::ConstValue::Char(c)),
                    _ => self.abstract_consts.push(e),
                }
                return self.deep(t);
            }
            // One value-namespace binding read covers the fn and constructor
            // cases below. The prelude `None` keeps its place between them,
            // as before: it is a prelude name, not a module binding.
            // `Self` as a value in an impl of a unit or tuple struct: the
            // unit value or the constructor, at the impl's own args.
            if name == p.known.self_type
                && let Some(a) = self.self_adt()
                && !p.adt(a).is_enum
            {
                match p.adt(a).variants[0].shape {
                    VariantShape::Unit => {
                        self.set_res(e, Res::Variant(a, 0));
                        return match self.self_path_args(a, segs, span) {
                            Some(args) if !args.is_empty() => self.tys.mk_adt(p.def_of_adt(a), &args),
                            _ => self.tys.adt_ty(a),
                        };
                    }
                    VariantShape::Tuple => {
                        // In an instance `Self` names a materialized Adt;
                        // the constructor item is the template's, at the
                        // instance's args.
                        let a = match p.gx.adt_instance_of.get(a.0 as usize).copied().flatten() {
                            Some((def, _)) => p.adt_by_def(def).unwrap_or(a),
                            None => a,
                        };
                        self.set_res(e, Res::Variant(a, 0));
                        return self.ctor_value_ty(e, a, 0, span);
                    }
                    VariantShape::Named => {}
                }
            }
            let bound = self.binding(Namespace::Value, name);
            if let BindingRes::Def(def) = bound
                && p.binding_kind(def) == Some(DefsKind::Fn)
                && let Some(f) = p.local_def(def.hash)
            {
                self.set_res(e, Res::Fn(f));
                return self.fn_value_ty(e, f, span);
            }
            if let BindingRes::Def(def) = bound {
                match p.binding_kind(def) {
                    Some(DefsKind::Const) => {
                        if let Some(idx) = p.const_by_def(def) {
                            let c = &p.consts[idx as usize];
                            let (v, t) = (c.value.clone(), c.ty);
                            let i = self.ei(e);
                            self.out.const_exprs[i] = Some(v);
                            self.out.const_quals.insert(e, c.qualif);
                            // The value lives in the global store; rebuild the
                            // type in this body's overlay so unification sees it.
                            return self.deep(t);
                        }
                    }
                    Some(DefsKind::Static) => {
                        if let Some(idx) = p.static_by_def(def) {
                            let st = &p.statics[idx as usize];
                            if st.mutable {
                                self.err(
                                    "L0404",
                                    span,
                                    "reading a mutable static requires `unsafe`, which is not supported",
                                    "Make the static immutable, or read it through a const.",
                                );
                                return ERROR;
                            }
                            let t = st.ty;
                            self.set_res(e, Res::Static(idx));
                            return self.deep(t);
                        }
                    }
                    _ => {}
                }
            }
            if name == p.known.None {
                self.set_res(e, Res::OptNone);
                let v = match self.builtin_ctor_args(segs, 1, span) {
                    Some(a) => a[0],
                    None => self.new_var(false),
                };
                return self.tys.mk_option(v);
            }
            if let BindingRes::Def(def) = bound
                && let Some(a) = p.adt_by_def(def)
            {
                let shape = match p.sig_of(&mut self.out.reads, def) {
                    SigOf::Adt(adt) if !adt.is_enum => Some(adt.variants[0].shape),
                    _ => None,
                };
                match shape {
                    Some(VariantShape::Unit) => {
                        self.set_res(e, Res::Variant(a, 0));
                        return self.unit_value_ty(e, a, span);
                    }
                    Some(VariantShape::Tuple) => {
                        self.set_res(e, Res::Variant(a, 0));
                        return self.ctor_value_ty(e, a, 0, span);
                    }
                    _ => {}
                }
            }
            // The prelude's `Some`, `Ok`, and `Err` as values
            // (`.map(Some)`), when no binding takes the name.
            if matches!(bound, BindingRes::Absent) {
                let k = &*p.known;
                let r = [(k.Some, Res::OptSome), (k.Ok, Res::ResOk), (k.Err, Res::ResErr)].into_iter().find(|&(n, _)| n == name);
                if let Some((_, r)) = r {
                    return self.builtin_item_value(e, r, segs, span);
                }
                // The prelude's `drop` as a value (`.for_each(drop)`).
                if let Some(t) = self.prelude_fn_value(e, &segs[0], span) {
                    return t;
                }
            }
            self.err(
                "L0101",
                span,
                format!("cannot find value `{}` in this scope", self.name(name)),
                "Check the spelling, or declare it with `let` first.",
            );
            return ERROR;
        }
        // Float associated consts: `f64::NAN`, `f32::EPSILON`,
        // `std::f64::consts::PI`, and kin.
        {
            let names: Vec<&str> = segs.iter().map(|s| self.name(s.name)).collect();
            let assoc = match names.as_slice() {
                [t, item] => Some((*t, *item, false)),
                [pre, t, c, item] if matches!(*pre, "std" | "core") && *c == "consts" => Some((*t, *item, true)),
                _ => None,
            };
            if let Some((ty_name, item, module)) = assoc {
                let f = match ty_name {
                    "f32" => Some(FloatTy::F32),
                    "f64" => Some(FloatTy::F64),
                    _ => None,
                };
                if let Some(f) = f {
                    use crate::ty::consteval::ConstValue;
                    if module {
                        if let Some(bits) = crate::ty::consteval::float_consts_value(f, item) {
                            let i = self.ei(e);
                            self.out.const_exprs[i] = Some(ConstValue::Float(bits, f));
                            return self.tys.float_ty(f);
                        }
                    } else if let Some((v, int_ty)) = crate::ty::consteval::primitive_float_assoc(f, item) {
                        let i = self.ei(e);
                        return match int_ty {
                            Some(it) => {
                                self.out.const_exprs[i] = Some(ConstValue::Int(v as i64 as i128));
                                int(it)
                            }
                            None => {
                                self.out.const_exprs[i] = Some(ConstValue::Float(v, f));
                                self.tys.float_ty(f)
                            }
                        };
                    }
                }
            }
        }
        // `ExitCode::SUCCESS` and `ExitCode::FAILURE` (check/process.rs).
        if let Some(t) = self.exit_code_const(e, segs) {
            return t;
        }
        // Char associated consts.
        if segs.len() == 2 && segs[0].name == p.known.char {
            let c = match self.name(segs[1].name) {
                "MAX" => Some(char::MAX),
                "MIN" => Some(char::MIN),
                "REPLACEMENT_CHARACTER" => Some(char::REPLACEMENT_CHARACTER),
                _ => None,
            };
            if let Some(c) = c {
                let i = self.ei(e);
                self.out.const_exprs[i] = Some(crate::ty::consteval::ConstValue::Char(c));
                return CHAR;
            }
            if self.name(segs[1].name) == "UNICODE_VERSION" {
                use crate::ty::consteval::ConstValue;
                let (maj, min, pat) = char::UNICODE_VERSION;
                let u8t = int(IntTy::U8);
                let ts = self.tys.intern_tys(&[u8t, u8t, u8t]);
                let ty = self.tys.intern(TyKind::Tuple(ts));
                let parts = vec![ConstValue::Int(maj as i128), ConstValue::Int(min as i128), ConstValue::Int(pat as i128)];
                let val = ConstValue::Aggregate(parts);
                let i = self.ei(e);
                self.out.const_exprs[i] = Some(val);
                return ty;
            }
        }
        // Primitive associated consts: `i64::MAX`, `u32::BITS`, and kin.
        if segs.len() == 2
            && let Some(it) = p.known.int_ty(segs[0].name)
        {
            let item = self.name(segs[1].name);
            let bits = it.bits();
            let v = match item {
                "MAX" => Some(crate::ty::consteval::truncate_to_int(it.max128() as i128, it)),
                "MIN" => Some(if it.signed() { if bits >= 128 { i128::MIN } else { -(1i128 << (bits - 1)) } } else { 0 }),
                "BITS" => Some(bits as i128),
                _ => None,
            };
            if let Some(v) = v {
                let (ty, val) = if item == "BITS" {
                    (int(IntTy::U32), crate::ty::consteval::ConstValue::Int(v))
                } else {
                    // u128::MAX does not fit an i128; store its bits as -1 and
                    // let materialization reinterpret them at the u128 type.
                    let val = if it == IntTy::U128 && item == "MAX" { -1 } else { v };
                    (int(it), crate::ty::consteval::ConstValue::Int(val))
                };
                let i = self.ei(e);
                self.out.const_exprs[i] = Some(val);
                return ty;
            }
        }
        // `NonZero::MIN` and `MAX` (TRIAGE T5): the wrapped
        // integer's own bounds, as an aggregate constant.
        if segs.len() >= 2 {
            let ty_seg = &segs[segs.len() - 2];
            let item = self.name(segs.last().unwrap().name).to_string();
            if matches!(item.as_str(), "MIN" | "MAX") {
                let inner = match self.nonzero_alias_inner(ty_seg.name) {
                    Some(i) => Some(int(i)),
                    None if self.name(ty_seg.name) == "NonZero" => match ty_seg.type_args().first() {
                        Some(&a) => Some(self.resolve_written(a)),
                        None => None,
                    },
                    None => None,
                };
                if let Some(inner) = inner
                    && let TyKind::Int(it) = self.kind(inner)
                {
                    let bits = it.bits();
                    let v = if item.as_str() == "MAX" {
                        if it == IntTy::U128 { -1 } else { crate::ty::consteval::truncate_to_int(it.max128() as i128, it) }
                    } else if it.signed() {
                        if bits >= 128 { i128::MIN } else { -(1i128 << (bits - 1)) }
                    } else {
                        1
                    };
                    let val = crate::ty::consteval::ConstValue::Aggregate(vec![crate::ty::consteval::ConstValue::Int(v)]);
                    let i = self.ei(e);
                    self.out.const_exprs[i] = Some(val);
                    return generics::nonzero_ty(&mut self.tys, inner);
                }
            }
        }
        // Associated consts of inherent impls (Self::A, Type::A) read
        // as their evaluated value, like free consts. Inherent items
        // shadow trait items, as in rustc. Same-name consts of
        // disjoint impls pick by the written Self type instance.
        // The value is baked into this body, so the const's
        // `Sig` read (its fingerprint folds the value) is
        // recorded, as `const_item_pat` does.
        let assoc_base = if segs.len() == 2 { self.assoc_const_base(segs, Some(span)) } else { None };
        if let Some((adt, item)) = self.assoc_const_key(segs)
            && let Some(picked) = assoc_base.and_then(|base| self.inherent_assoc_pick(adt, item, base, Some(span)))
        {
            return match picked {
                Some((idx, v)) => {
                    if let Some(&def) = p.const_defs.get(idx as usize) {
                        let _ = p.sig_of(&mut self.out.reads, def);
                    }
                    self.check_assoc_vis(adt, item, "associated constant", span);
                    let t = p.consts[idx as usize].ty;
                    let i = self.ei(e);
                    self.out.const_exprs[i] = Some(v);
                    self.out.const_quals.insert(e, p.consts[idx as usize].qualif);
                    self.deep(t)
                }
                None => ERROR,
            };
        }
        // Associated consts of traits (`Type::C`, `T::C`,
        // `Self::C`): the value when an impl is confirmed, the
        // declared type alone under param evidence.
        if segs.len() == 2
            && (self.replay_pick(e).is_some()
                || !self.assoc_const_key(segs).is_some_and(|(adt, item)| self.inherent_value_blocks(adt, item)))
            && let Some(base) = assoc_base.or_else(|| self.prim_ty_by_name(segs[0].name))
            && let Some((idx, t)) = self.trait_assoc_const(Some(e), base, None, segs[1].name, span)
        {
            if let Some((_, v)) = idx {
                let i = self.ei(e);
                self.out.const_exprs[i] = Some(v);
            }
            return t;
        }
        // `T::f` as a value on a type parameter, or `Self::f` in a
        // trait default body: the trait comes from the bounds in scope
        // (in an instance, the template's bound at the concrete `T`).
        if let Some(base) = self.param_path_base(segs) {
            let name = segs[1].name;
            if let Some(tr) = self.instance_bound_ref(name, base).or_else(|| self.unique_item_trait(base, name))
                && let Some(t) = self.trait_ref_fn_value(e, tr, name, span)
            {
                return t;
            }
        }
        // A trait's function as a value through the trait name
        // (`Into::into`, check/traitpath.rs).
        if let Some(t) = self.trait_path_fn_value(e, segs, span) {
            return t;
        }
        let mark = self.errs.len();
        let resolved = self.resolve_assoc(segs, span);
        // No inherent item, variant, or written impl fn of that name
        // (`S::clone` for a derived Clone, `Self::default`, `i32::cmp`):
        // the one trait in scope that has the item and holds for the
        // type, as rustc probes traits after inherent items.
        if resolved.is_none()
            && segs.len() == 2
            && let Some(base) = assoc_base.or_else(|| self.prim_ty_by_name(segs[0].name))
            && let Some(tr) = self.unique_item_trait(base, segs[1].name)
            && let Some(t) = self.trait_ref_fn_value(e, tr, segs[1].name, span)
        {
            self.errs.truncate(mark);
            return t;
        }
        // `OnceCell::from`, `Arc::from` as values (check/ufcs.rs).
        if matches!(resolved, None | Some(Res::Builtin(Builtin::OwnFrom(_))))
            && let Some(t) = self.from_path_value(e, segs, assoc_base, span)
        {
            self.errs.truncate(mark);
            return t;
        }
        if let Some(r) = resolved {
            self.set_res(e, r);
            if r == Res::OptNone {
                let v = match self.builtin_ctor_args(segs, 1, span) {
                    Some(a) => a[0],
                    None => self.new_var(false),
                };
                return self.tys.mk_option(v);
            }
            if let Res::Variant(a, v) = r {
                self.check_ne_ctor(a, v, span);
                let variant = &p.adt(a).variants[v as usize];
                if variant.shape == VariantShape::Unit {
                    if p.gx.adt_generics[a.0 as usize].params.is_empty() {
                        return self.tys.adt_ty(a);
                    }
                    // A unit variant of a generic enum: its params come
                    // from any turbofish, else from later uses.
                    let gen_args = self.value_path_args(a, segs, span);
                    let preds = p.gx.adt_generics[a.0 as usize].predicates.clone();
                    if !preds.is_empty() {
                        self.push_predicates(&preds, &gen_args, span);
                    }
                    return self.tys.mk_adt(p.def_of_adt(a), &gen_args);
                }
                if variant.shape == VariantShape::Tuple {
                    return self.ctor_value_ty(e, a, v, span);
                }
                self.err("L0101", span, "expected value, found struct variant", "Write a struct literal: `Enum::Variant { .. }`.");
                return ERROR;
            }
            if let Res::Fn(f) = r {
                return self.fn_value_ty(e, f, span);
            }
            if matches!(r, Res::OptSome | Res::ResOk | Res::ResErr | Res::Builtin(Builtin::BoxNew | Builtin::RcNew | Builtin::StringFrom | Builtin::StringAsStr)) {
                return self.builtin_item_value(e, r, segs, span);
            }
            if let Res::PrimAssoc { b, self_ty, name } = r {
                return self.prim_item_value(b, self_ty, name, span);
            }
            // Other std fns (`String::new`, `Vec::from`) have no value
            // form yet. An error type without a diagnostic would reach
            // codegen, so report every one.
            self.errs.push(unsupported(span, "this std function used as a value"));
            return ERROR;
        }
        ERROR
    }

    /// Resolves a `core::intrinsics::<name>` path. Order is fixed: the
    /// name must exist in the registry, the call site's crate must be on
    /// the row's privilege list, and codegen must implement the row.
    /// A user call site never has a shipped crate, so it stops at the
    /// privilege test with L0642 (docs/ARCH.md sections 3.1 and 3.2).
    fn resolve_intrinsic(&mut self, name: Sym, span: Span) -> Option<Res> {
        let text = self.name(name).to_string();
        // The generic interior-write builtins of std source (W-STD-C):
        // the same privilege rule as registry intrinsics.
        // The panic hook slot of std's `set_hook` source (W-UNWIND).
        if matches!(text.as_str(), "panic_hook_swap" | "panic_hook_ref" | "panic_hook_payload" | "panic_hook_location") {
            if self.p.shipped_crate_at(span) != Some(lang::ShippedCrate::Std) {
                self.err(
                    "L0642",
                    span,
                    format!("intrinsic `core::intrinsics::{text}` can only be called from lust's shipped library crates"),
                    "Call the public std item that wraps it instead.",
                );
                return None;
            }
            let op = match text.as_str() {
                "panic_hook_swap" => sync::SyncOp::PanicHookSwap,
                "panic_hook_ref" => sync::SyncOp::PanicHookRef,
                "panic_hook_payload" => sync::SyncOp::PanicHookPayload,
                _ => sync::SyncOp::PanicHookLocation,
            };
            return Some(Res::Builtin(Builtin::Sync(op)));
        }
        if matches!(text.as_str(), "discriminant_value" | "discriminant_kind") {
            if self.p.shipped_crate_at(span) != Some(lang::ShippedCrate::Core) {
                self.err(
                    "L0642",
                    span,
                    format!("intrinsic `core::intrinsics::{text}` can only be called from lust's shipped library crates"),
                    "Call the public std item that wraps it instead (`std::mem::discriminant`).",
                );
                return None;
            }
            return Some(Res::Builtin(if text == "discriminant_value" { Builtin::DiscriminantValue } else { Builtin::DiscriminantKind }));
        }
        if matches!(text.as_str(), "once_init" | "once_take") {
            if !matches!(self.p.shipped_crate_at(span), Some(lang::ShippedCrate::Core | lang::ShippedCrate::Std)) {
                self.err(
                    "L0642",
                    span,
                    format!("intrinsic `core::intrinsics::{text}` can only be called from lust's shipped library crates"),
                    "Call the public std item that wraps it instead.",
                );
                return None;
            }
            return Some(Res::Builtin(if text == "once_init" { Builtin::OnceInit } else { Builtin::OnceTake }));
        }
        let Some(id) = lang::intrinsic_by_name(&text) else {
            self.err(
                "L0104",
                span,
                format!("no intrinsic `core::intrinsics::{text}`"),
                "Intrinsics are a closed registry (src/ty/lang.rs). Call a public std item instead.",
            );
            return None;
        };
        let def = lang::intrinsic(id);
        if !def.allows(self.p.shipped_crate_at(span)) {
            self.err(
                "L0642",
                span,
                format!("intrinsic `core::intrinsics::{text}` can only be called from lust's shipped library crates"),
                "Call the public std item that wraps it instead.",
            );
            return None;
        }
        if !def.implemented {
            self.err(
                "L0640",
                span,
                format!("intrinsic `core::intrinsics::{text}` is declared but not yet implemented"),
                "Implement the registry row and its runtime hook first (docs/ARCH.md section 3.2).",
            );
            return None;
        }
        Some(Res::Intrinsic(id))
    }

    /// Resolves `Type::item` and `std::env::args`. Reports an error and returns None on failure.
    fn resolve_assoc(&mut self, segs: &[ast::PathSeg], span: Span) -> Option<Res> {
        let p = self.p;
        let k = &*p.known;
        // `Alias::item` through an alias of a builtin type is the item of
        // the type the alias names, by its canonical std path
        // (check/alias_path.rs); the alias's args are the written Self.
        if let Some(t) = self.builtin_alias_ty(segs, span, true) {
            if t == ERROR {
                return None;
            }
            if segs[1].has_args() {
                self.err("L0107", span, "this associated item takes no generic arguments", "Write the type's arguments on the alias.");
                return None;
            }
            let canon = self.canonical_item_segs(t, &segs[1])?;
            return self.resolve_assoc(&canon, span);
        }
        let names: Vec<Sym> = segs.iter().map(|s| s.name).collect();
        if names.len() == 3 && names[0] == k.core && names[1] == k.intrinsics {
            return self.resolve_intrinsic(names[2], span);
        }
        // Shipped source std fns (the `STD_FNS` registry). A declared row
        // with no body yet rejects with L0640; an implemented row routes
        // to the spliced body the loader put in this program. If std was
        // not loaded (the driver trigger missed this spelling), the path
        // falls through to the module-path reject below, never an accept.
        if names[0] == k.std {
            for def in lang::STD_FNS {
                if def.path.len() == names.len() && def.path.iter().zip(&names).all(|(s, n)| *s == self.name(*n)) {
                    if !def.implemented {
                        self.err(
                            "L0640",
                            span,
                            format!("`{}` is declared but not yet implemented in lust std", def.path.join("::")),
                            "Use a std item lust implements today, or write the behavior in your own code.",
                        );
                        return None;
                    }
                    if let Some(f) = p.std_fn_for_path(&names) {
                        return Some(Res::Fn(f));
                    }
                    break;
                }
            }
        }
        if names == [k.std, k.env, k.args] {
            return Some(Res::Builtin(Builtin::EnvArgs));
        }
        // `std::panic::Location::caller()` (check/caller.rs).
        if names.len() == 4
            && (names[0] == k.std || names[0] == k.core)
            && self.name(names[1]) == "panic"
            && self.name(names[2]) == "Location"
            && self.name(names[3]) == "caller"
        {
            return Some(Res::Builtin(Builtin::LocationCaller));
        }
        if names.len() == 3
            && (names[0] == k.std || names[0] == k.core)
            && self.name(names[1]) == "mem"
            && matches!(self.name(names[2]), "size_of" | "align_of")
        {
            let align = self.name(names[2]) == "align_of";
            return Some(self.layout_query(&segs[2], align, span));
        }
        if names.len() == 3 && (names[0] == k.std || names[0] == k.core) && self.name(names[1]) == "mem" && self.name(names[2]) == "needs_drop" {
            return Some(self.needs_drop_query(&segs[2], span));
        }
        if names.len() == 2 && names[1] == k.from_bits {
            if names[0] == k.f64 {
                return Some(Res::Builtin(Builtin::F64FromBits));
            }
            if names[0] == k.f32 {
                return Some(Res::Builtin(Builtin::F32FromBits));
            }
        }
        // `char::from_u32` and `char::from_digit` (associated fns
        // without a receiver). The Unicode predicate paths
        // (`char::is_alphabetic(c)`) resolve through the primitive
        // method table below (`prim_assoc_sig`), as values too.
        if names.len() == 2 && names[0] == k.char {
            let b = match names[1] {
                n if n == k.from_u32 => Some(Builtin::CharFromU32),
                n if n == k.from_digit => Some(Builtin::CharFromDigit),
                _ => None,
            };
            if let Some(b) = b {
                return Some(Res::Builtin(b));
            }
        }
        // `fmt::Error`, the unit struct value (W-STD-B).
        if names.len() == 3
            && (names[0] == k.std || names[0] == k.core)
            && self.name(names[1]) == "fmt"
            && self.name(names[2]) == "Error"
            && let Some(a) = p.tys.local_adt_of(generics::fmt_error_def())
        {
            return Some(Res::Variant(a, 0));
        }
        // `std::borrow::Cow::Borrowed` and `Owned` (W-STD-B): the
        // synthetic generic enum collect registers.
        if names.len() == 4
            && (names[0] == k.std || self.name(names[0]) == "alloc")
            && self.name(names[1]) == "borrow"
            && self.name(names[2]) == "Cow"
            && let Some(a) = p.tys.local_adt_of(generics::cow_def())
        {
            if let Some(v) = p.adt(a).variants.iter().position(|v| v.name == names[3]) {
                return Some(Res::Variant(a, v as u32));
            }
            // `Cow::from(x)`: std's `From` impls for Cow (check/convert.rs).
            if names[3] == k.from {
                return Some(Res::Builtin(Builtin::ConvInto));
            }
            // `Cow::default()`: the default glue over the Owned type
            // (`cow_default_sig`, check/cow.rs).
            if self.name(names[3]) == "default" {
                return Some(Res::Builtin(Builtin::DefaultGlue));
            }
        }
        // `mpsc::RecvError`, the unit struct value (W-THREADS).
        if names.len() == 4
            && names[0] == k.std
            && self.name(names[1]) == "sync"
            && self.name(names[2]) == "mpsc"
            && self.name(names[3]) == "RecvError"
            && let Some(a) = p.tys.local_adt_of(generics::recv_error_def())
        {
            return Some(Res::Variant(a, 0));
        }
        // `std::cmp::Ordering::Less`, `std::sync::atomic::Ordering::SeqCst`,
        // and kin: a variant of a synthetic std enum by its full path.
        if names.len() >= 4 && (names[0] == k.std || names[0] == k.core) {
            let path: Vec<&str> = names.iter().map(|n| self.name(*n)).collect();
            if let Some((a, v)) = generics::std_variant_of(p, &path) {
                return Some(Res::Variant(a, v));
            }
            if let Some(a) = generics::std_adt_of_path(&path[..path.len() - 1]).and_then(|d| p.tys.local_adt_of(d))
                && p.adt(a).is_enum
                && crate::ty::lang::std_path_kind(&path[..path.len() - 1]) == Some(crate::ty::lang::StdPathKind::Type)
            {
                let all: Vec<String> = p.adt(a).variants.iter().map(|v| format!("`{}`", self.name(v.name))).collect();
                self.err(
                    "L0104",
                    span,
                    format!("no variant `{}` on `{}`", path[path.len() - 1], path[path.len() - 2]),
                    format!("Check the name: {}.", all.join(", ")),
                );
                return None;
            }
        }
        // `std::sync::atomic::fence` and the other sync free fns.
        if names.len() >= 3 && (names[0] == k.std || names[0] == k.core) {
            let path: Vec<&str> = names.iter().map(|n| self.name(*n)).collect();
            if let Some(op) = sync::sync_free_fn(&path) {
                return Some(Res::Builtin(Builtin::Sync(op)));
            }
        }
        // The `core::mem` and `core::cmp` free fns by module path.
        if names.len() == 3 && (names[0] == k.std || names[0] == k.core) {
            let b = match (self.name(names[1]), self.name(names[2])) {
                ("mem", "drop") => Some(Builtin::MemDrop),
                ("mem", "forget") => Some(Builtin::MemForget),
                ("mem", "swap") => Some(Builtin::MemSwap),
                ("mem", "replace") => Some(Builtin::MemReplace),
                ("mem", "take") => Some(Builtin::MemTake),
                ("cmp", "max") => Some(Builtin::CmpMax),
                ("cmp", "min") => Some(Builtin::CmpMin),
                ("hint", "black_box") => Some(Builtin::HintBlackBox),
                ("str", "from_utf8") => Some(Builtin::StrFromUtf8),
                ("iter", "repeat_n") => Some(Builtin::IterRepeatN),
                ("array", "from_fn") => Some(Builtin::ArrayFromFn),
                ("slice", "from_ref") | ("slice", "from_mut") => Some(Builtin::SliceFromRef),
                ("ptr", "from_ref") | ("ptr", "from_mut") => Some(Builtin::PtrFromRef),
                ("ptr", "null") | ("ptr", "null_mut") => Some(Builtin::PtrNull),
                ("ptr", "eq") => Some(Builtin::PtrEqFn),
                ("ptr", "addr_eq") => Some(Builtin::PtrAddrEqFn),
                _ => None,
            };
            if let Some(b) = b {
                return Some(Res::Builtin(b));
            }
        }
        // `std::fmt::format` lives in alloc, so `core::fmt::format` is
        // no path (rustc E0425).
        if names.len() == 3
            && (names[0] == k.std || self.name(names[0]) == "alloc")
            && self.name(names[1]) == "fmt"
            && self.name(names[2]) == "format"
        {
            return Some(Res::Builtin(Builtin::FmtFormat));
        }
        // A canonical std type path plus an associated item
        // (`std::vec::Vec::new`, `core::option::Option::Some`):
        // the last two segments name the type and the item, as in
        // the two-segment spelling. Only exact table rows qualify.
        let std_ty = segs.len() > 2;
        let (ty_name, item) = if segs.len() == 2 {
            (names[0], names[1])
        } else {
            let path: Vec<&str> = names[..names.len() - 1].iter().map(|n| self.name(*n)).collect();
            if crate::ty::lang::std_path_kind(&path) != Some(crate::ty::lang::StdPathKind::Type) {
                self.errs.push(module_path_not_yet(&names.iter().map(|n| self.name(*n)).collect::<Vec<_>>(), span));
                return None;
            }
            (names[names.len() - 2], names[names.len() - 1])
        };
        // A type item of an enclosing block shadows every builtin and
        // module type of its name (R18).
        if segs.len() == 2
            && ty_name != k.self_type
            && let Some(a) = self.local_adt_of(ty_name)
        {
            return self.adt_assoc(a, ty_name, item, segs, span, false);
        }
        // The hashed collections and hashers by their std path (an
        // import expands to it; a bare name reaching here was not
        // imported, which rustc rejects).
        if segs.len() > 2
            && let Some(hk) = crate::ty::hash::HashTy::by_name(self.name(ty_name))
        {
            return match crate::check::hashmap::hash_ctor_builtin(hk, self.name(item)) {
                Some(b) => Some(Res::Builtin(b)),
                None => {
                    self.err("L0104", span, format!("no function `{}::{}`", self.name(ty_name), self.name(item)), "Check the name.");
                    None
                }
            };
        }
        // The first segment is a type-namespace binding read (`Self` is a
        // scope name, not a binding, and records nothing).
        let ty_bound = if ty_name == k.self_type { BindingRes::Absent } else { self.binding(Namespace::Type, ty_name) };
        if ty_name == k.String || ty_name == k.str {
            if let Some(r) = self.utf8_assoc(ty_name == k.String, item, span) {
                return r;
            }
        }
        // `MaybeUninit::uninit`, `new`, and `zeroed` by path
        // (TRIAGE T5).
        if self.name(ty_name) == "MaybeUninit" {
            let b = match self.name(item) {
                "uninit" => Some(Builtin::MaybeUninitUninit),
                "zeroed" => Some(Builtin::MaybeUninitZeroed),
                "new" => Some(Builtin::MaybeUninitNew),
                _ => None,
            };
            if let Some(b) = b {
                return Some(Res::Builtin(b));
            }
            self.err(
                "L0104",
                span,
                format!("no variant or associated function `{}` on `MaybeUninit`", self.name(item)),
                "Check the name.",
            );
            return None;
        }
        // `NonZero::new`, `NonZeroU64::new`, and `NonZero::get` by
        // path (TRIAGE T5/T12): `new` is the constructor builtin,
        // `get` rides the primitive assoc machinery as a value.
        if self.name(ty_name) == "NonZero" || self.name(ty_name).starts_with("NonZero") && self.nonzero_alias_inner(ty_name).is_some() {
            let inner = match self.nonzero_alias_inner(ty_name) {
                Some(i) => int(i),
                None => match self.builtin_ctor_args(segs, 1, span) {
                    Some(a) => a[0],
                    None => self.new_var(false),
                },
            };
            if item == k.new {
                return Some(Res::Builtin(Builtin::NonZeroNew));
            }
            if self.name(item) == "get" && prim_builtin_code(Builtin::NonZeroGet).is_some() {
                let self_ty = generics::nonzero_ty(&mut self.tys, inner);
                return Some(Res::PrimAssoc { b: Builtin::NonZeroGet, self_ty, name: item });
            }
            let tn = self.name(ty_name).to_string();
            self.err(
                "L0104",
                span,
                format!("no variant or associated function `{}` on `{tn}`", self.name(item)),
                "Check the name.",
            );
            return None;
        }
        // A primitive type's method by path (`u8::is_ascii_digit`,
        // `str::len`, `char::to_lowercase`; TRIAGE T12): a std source
        // inherent fn when one is registered, else the builtin
        // method table as a `PrimAssoc`. Associated consts
        // (`u8::MAX`) resolve elsewhere and fall through.
        if let Some(self_ty) = self.prim_ty_by_name(ty_name) {
            if let Some(fs) = p.gx.prim_inherent_methods.get(&(self_ty, item)).filter(|fs| !fs.is_empty()) {
                let written: Vec<LocalDefId> = fs.iter().copied().filter(|f| !p.gx.instances.contains_key(f)).collect();
                if let [f] = written.as_slice() {
                    return Some(Res::Fn(*f));
                }
                if written.is_empty() {
                    return Some(Res::Fn(fs[0]));
                }
            }
            if let Some((b, _, _, _)) = self.prim_assoc_sig(self_ty, item, &[]) {
                return Some(Res::PrimAssoc { b, self_ty, name: item });
            }
            if self_ty != STRING && self.name(item).chars().next().is_some_and(|c| c.is_ascii_lowercase() || c == '_') {
                let tn = self.name(ty_name).to_string();
                self.err(
                    "L0104",
                    span,
                    format!("no variant or associated function `{}` on `{tn}`", self.name(item)),
                    "Check the name.",
                );
                return None;
            }
        }
        if ty_name == k.String {
            let b = if item == k.new {
                Builtin::StringNew
            } else if item == k.as_str {
                Builtin::StringAsStr
            } else if item == k.from {
                Builtin::StringFrom
            } else if item == k.with_capacity {
                Builtin::StringWithCapacity
            } else if item == k.clone {
                Builtin::Clone
            } else {
                self.err(
                    "L0104",
                    span,
                    format!("no function `String::{}`", self.name(item)),
                    "Lust supports String::new, String::from, String::with_capacity, and String::as_str.",
                );
                return None;
            };
            return Some(Res::Builtin(b));
        }
        if ty_name == k.Vec {
            let b = if item == k.new {
                Builtin::VecNew
            } else if item == k.with_capacity {
                Builtin::VecWithCapacity
            } else if item == k.from {
                Builtin::VecFrom
            } else if item == k.clone {
                Builtin::Clone
            } else if let Some(vt) = Some(self.new_var(false)).map(|e| self.tys.mk_vec(e))
                && let Some((b, _, _, _)) = self.prim_assoc_sig(vt, item, &[])
            {
                // `Vec::as_slice` and kin as values (`prim_assoc_sig`).
                return Some(Res::PrimAssoc { b, self_ty: vt, name: item });
            } else {
                self.err(
                    "L0104",
                    span,
                    format!("no function `Vec::{}`", self.name(item)),
                    "Lust supports Vec::new, Vec::with_capacity, and Vec::from.",
                );
                return None;
            };
            return Some(Res::Builtin(b));
        }
        if ty_name == k.Box {
            if item == k.new {
                return Some(Res::Builtin(Builtin::BoxNew));
            }
            if item == k.clone {
                return Some(Res::Builtin(Builtin::Clone));
            }
            if item == k.leak {
                return Some(Res::Builtin(Builtin::BoxLeak));
            }
            // `Box::default()`: the default glue of `Box<T>` (`box_default_sig`;
            // `Box::<T>::default()` keeps its own path).
            if self.name(item) == "default" && segs.len() >= 2 && segs[segs.len() - 2].type_args().is_empty() {
                return Some(Res::Builtin(Builtin::DefaultGlue));
            }
            // alloc's safe uninit surface (`assume_init` is unsafe and
            // stays out).
            match self.name(item) {
                "new_uninit" => return Some(Res::Builtin(Builtin::BoxNewUninit)),
                "new_zeroed" => return Some(Res::Builtin(Builtin::BoxNewZeroed)),
                "new_uninit_slice" | "new_zeroed_slice" => return Some(Res::Builtin(Builtin::BoxNewUninitSlice)),
                "write" => return Some(Res::Builtin(Builtin::BoxWrite)),
                "as_ptr" | "as_mut_ptr" => return Some(Res::Builtin(Builtin::BoxAsPtr)),
                _ => {}
            }
            if item == k.from {
                return Some(Res::Builtin(Builtin::OwnFrom(own::Owner::Box)));
            }
            self.err(
                "L0104",
                span,
                format!("no function `Box::{}`", self.name(item)),
                "Lust supports Box::new, Box::leak, Box::as_ptr, Box::as_mut_ptr, Box::new_uninit, Box::new_zeroed, their _slice forms, and Box::write.",
            );
            return None;
        }
        // `AtomicUsize::new`, `Arc::new`, `sync::Weak::new`, and the other
        // sync types by their full path (check/sync.rs), ahead of the
        // `rc::Weak` names below.
        // alloc's safe `Arc` uninit constructors (the `Arc` path test is
        // `sync_assoc`'s; `assume_init` is unsafe and stays out).
        if std_ty
            && let Some((&item, ty_path)) = names.split_last()
            && matches!(self.name(item), "new_uninit" | "new_zeroed")
            && crate::ty::sync::SyncTy::by_path(&ty_path.iter().map(|n| self.name(*n)).collect::<Vec<_>>()) == Some(crate::ty::sync::SyncTy::Arc)
        {
            return Some(Res::Builtin(Builtin::ArcNewUninit));
        }
        if let Some(r) = self.sync_assoc(&names, std_ty, span) {
            return r.map(|r| self.written_prim_self(r, segs, span));
        }
        // `Rc::downgrade`, `Weak::new`, `RefCell::new`, and kin (check/cells.rs).
        if let Some(r) = self.cell_assoc(ty_name, item, std_ty, span) {
            return r.map(|r| self.written_prim_self(r, segs, span));
        }
        if let Some(r) = self.exit_code_assoc(ty_name, item, std_ty, span) {
            return r;
        }
        // A user type named `Rc` shadows std's (which needs a `use`),
        // but never on a std path.
        if ty_name == k.Rc && (std_ty || !self.p.type_names.contains_key(&ty_name)) {
            if matches!(self.name(item), "new_uninit" | "new_zeroed") {
                return Some(Res::Builtin(Builtin::RcNewUninit));
            }
            let b = if item == k.new {
                Builtin::RcNew
            } else if item == k.clone {
                Builtin::Clone
            } else if item == k.strong_count {
                Builtin::RcStrongCount
            } else if item == k.weak_count {
                Builtin::RcWeakCount
            } else if item == k.make_mut {
                Builtin::RcMakeMut
            } else if item == k.get_mut {
                Builtin::RcGetMut
            } else if item == k.try_unwrap {
                Builtin::RcTryUnwrap
            } else if self.name(item) == "into_inner" {
                Builtin::RcIntoInner
            } else if self.name(item) == "unwrap_or_clone" {
                Builtin::RcUnwrapOrClone
            } else if item == k.from {
                Builtin::OwnFrom(own::Owner::Rc)
            } else if self.name(item) == "default" {
                Builtin::DefaultGlue
            } else {
                self.err(
                    "L0104",
                    span,
                    format!("no function `Rc::{}`", self.name(item)),
                    "Lust supports Rc::new, Rc::strong_count, Rc::weak_count, Rc::make_mut, Rc::get_mut, Rc::try_unwrap, Rc::into_inner, and Rc::unwrap_or_clone.",
                );
                return None;
            };
            return Some(Res::Builtin(b));
        }
        // Qualified builtin variant constructors: `Option::Some(..)`,
        // `Result::Ok(..)`, `Result::Err(..)`, unless a user type of
        // the name shadows std's.
        let lang_ty = std_ty || (!self.p.type_names.contains_key(&ty_name) && self.local_adt_of(ty_name).is_none());
        if ty_name == k.Option && item == k.Some && lang_ty {
            return Some(Res::OptSome);
        }
        if ty_name == k.Option && item == k.None && lang_ty {
            return Some(Res::OptNone);
        }
        if ty_name == k.Result && item == k.Ok && lang_ty {
            return Some(Res::ResOk);
        }
        if ty_name == k.Result && item == k.Err && lang_ty {
            return Some(Res::ResErr);
        }
        // The std source methods of the lang enums as path calls and
        // fn values (`Option::map(x, f)`, `.filter(Option::is_some)`,
        // fx-option-rest): the impl templates collect keyed on the
        // builtin def (`inherent_methods`), as a user Adt's do below.
        // `iter`, `iter_mut`, and `into_iter` are builtin, not source:
        // they answer as `Builtin::IterOptRes` calls.
        if lang_ty && (ty_name == k.Option || ty_name == k.Result) {
            if matches!(self.name(item), "iter" | "iter_mut" | "into_iter") {
                return Some(Res::Builtin(Builtin::IterOptRes));
            }
            let def = if ty_name == k.Option { self.tys.builtins().option } else { self.tys.builtins().result };
            p.inherent_reads(&mut self.out.reads, def, item);
            if let Some(fs) = p.gx.inherent_methods.get(&(def, item)).filter(|fs| !fs.is_empty()) {
                let fs = fs.clone();
                let written: Vec<LocalDefId> = fs.iter().copied().filter(|f| !p.gx.instances.contains_key(f)).collect();
                let f = match written.as_slice() {
                    [] => fs[0],
                    &[f] => f,
                    _ => self.lang_fn_by_self(def, &written, segs, span)?,
                };
                return Some(Res::Fn(f));
            }
            let tn = self.name(ty_name).to_string();
            self.err("L0104", span, format!("no variant or associated function `{}` on `{tn}`", self.name(item)), "Check the name.");
            return None;
        }
        // In an instance `Self` names a materialized Adt; its items are
        // the template's (a fn of another impl block has no instance yet).
        let adt = if ty_name == p.known.self_type {
            self.self_adt().map(|a| match p.gx.adt_instance_of.get(a.0 as usize).copied().flatten() {
                Some((def, _)) => p.adt_by_def(def).unwrap_or(a),
                None => a,
            })
        } else {
            match ty_bound {
                BindingRes::Def(def) => p.adt_by_def(def),
                _ => None,
            }
        };
        // A type item of an enclosing block (`E::A(3)` for a local
        // enum), then a type alias of a user Adt (`EA::A(3)`,
        // `SA::new()`, generic `A::make(5)`); `value_path_args`
        // gives its args.
        let adt = adt.or_else(|| self.local_adt_of(ty_name));
        let adt = adt.or_else(|| self.alias_adt_seg(&segs[segs.len() - 2], span).map(|(a, ..)| a));
        let Some(a) = adt else {
            self.err(
                "L0101",
                span,
                format!("cannot find type `{}`", crate::intern::source_name(self.name(ty_name))),
                "Check the spelling.",
            );
            return None;
        };
        self.adt_assoc(a, ty_name, item, segs, span, std_ty)
    }

    /// `resolve_assoc` for a path whose type segment names the user
    /// Adt `a` (a module item, `Self`, an alias, or a type item of an
    /// enclosing block): its variant, inherent fn, or trait fn `item`.
    fn adt_assoc(&mut self, a: AdtId, ty_name: Sym, item: Sym, segs: &[ast::PathSeg], span: Span, std_ty: bool) -> Option<Res> {
        let p = self.p;
        // A std path names std's type, never a user type of the same
        // name (std's `Ordering` is the one std Adt here).
        if std_ty && !generics::is_std_adt(&p.tys, a) {
            self.errs.push(collect::std_path_shadowed(&p.interner, ty_name, span));
            return None;
        }
        // The variant and associated-item tables of the Adt are part of its
        // signature read. Associated fns get their own index query when the
        // trait index lands (W-TRAITS-CORE); the method map stays behind
        // this `Sig` read until then.
        let adef = p.def_of_adt(a);
        let is_variant = match p.sig_of(&mut self.out.reads, adef) {
            SigOf::Adt(def) if def.is_enum => def.variants.iter().position(|v| v.name == item),
            _ => None,
        };
        if let Some(v) = is_variant {
            if self.hidden_variant(a, v as u32, span) {
                return None;
            }
            return Some(Res::Variant(a, v as u32));
        }
        p.inherent_reads(&mut self.out.reads, adef, item);
        if let Some(fs) = p.methods.get(&(a, item)).filter(|fs| !fs.is_empty()) {
            // Materialized instances join the same entry; the written
            // fns (one per impl) are the candidates.
            let written: Vec<LocalDefId> = fs.iter().copied().filter(|f| !p.gx.instances.contains_key(f)).collect();
            let f = match written.as_slice() {
                [] => fs[0],
                &[f] => f,
                _ => self.inherent_fn_by_self(a, &written, segs, span)?,
            };
            let what = if p.fn_info(f).self_kind.is_some() { "method" } else { "associated function" };
            self.check_assoc_vis(a, item, what, span);
            return Some(Res::Fn(f));
        }
        // A trait's function of a non-generic type as a value
        // (`S::mk`, `.map(S::from)`): the written impl's own fn.
        if p.gx.adt_generics.get(a.0 as usize).is_none_or(|g| g.params.is_empty()) {
            let base = self.tys.adt_ty(a);
            if let Some(f) = self.trait_fn_value(base, None, item, false, span) {
                return f.map(|(f, _)| Res::Fn(f));
            }
        }
        // A std source type's own name, not its hidden module path.
        let tn = crate::intern::source_name(self.name(ty_name)).to_string();
        self.err("L0104", span, format!("no variant or associated function `{}` on `{tn}`", self.name(item)), "Check the name.");
        None
    }

    /// A trait's function as a value on a concrete type (`S::mk`,
    /// `<S as Tr>::mk`): the trait (written in `hint`, else every
    /// trait in scope with a method of that name) selects a written
    /// impl, and its fn is the value: the impl's own fn, or the
    /// trait's default body when the impl does not write it. Returns
    /// the fn and its instantiation prefix (the impl's args for an
    /// impl fn, the trait ref's args for a default body). With
    /// `generic` false only a plain (non-template) fn answers. None
    /// when nothing applies; Some(None) after reporting an ambiguity.
    /// Core's synthetic impls have no fn to name here (a reject).
    fn trait_fn_value(
        &mut self,
        base: Ty,
        hint: Option<TraitRef>,
        name: Sym,
        generic: bool,
        span: Span,
    ) -> Option<Option<(LocalDefId, Vec<GenericArg>)>> {
        let p = self.p;
        let traits: Vec<DefId> = match hint {
            Some(tr) => vec![tr.def],
            None => p.gx.traits_by_method.get(&name).cloned().unwrap_or_default().into_iter().filter(|&d| method::trait_in_scope_at(self, d, base)).collect(),
        };
        // First pass, rolled back: which traits answer.
        let mut hits: Vec<TraitRef> = Vec::new();
        for trait_def in traits {
            let Some(rec) = p.gx.index.trait_record(trait_def).cloned() else { continue };
            if rec.method_by_name(name).is_none() {
                continue;
            }
            let tr = match hint {
                Some(t) => t,
                None => {
                    let mut tr_args: Vec<GenericArg> = vec![GenericArg::Ty(base)];
                    for _ in 1..rec.generics.params.len() {
                        tr_args.push(GenericArg::Ty(self.new_var(false)));
                    }
                    let args_id = self.tys.intern_args(&tr_args);
                    TraitRef { def: trait_def, args: args_id, bindings: EMPTY_BINDINGS }
                }
            };
            // A trait applies when its impl selects at all, also when
            // that impl has no fn to name here (a default body with
            // `generic` false, a synthetic impl, open impl params):
            // rustc counts it for the ambiguity (E0034).
            let snap = self.snapshot_vars();
            let obl_len = self.obl_len();
            let applies = match self.select_obligation_at(tr, span, 0) {
                Selection::Impl { .. } | Selection::ParamEvidence(_) | Selection::Builtin => true,
                Selection::Ambiguous => rec.generics.params.len() > 1,
                _ => false,
            };
            self.rollback_vars(snap);
            self.obl_truncate(obl_len);
            if applies {
                hits.push(tr);
            }
        }
        match hits.len() {
            0 => None,
            // The winner selects again, keeping its bindings.
            1 => self.trait_fn_of(hits[0], name, generic, span).map(Some),
            _ => {
                self.err(
                    "L0720",
                    span,
                    format!("multiple trait functions named `{}` apply here", self.name(name)),
                    "Name the trait with a qualified path, such as `<Type as Trait>::name`.",
                );
                Some(None)
            }
        }
    }

    /// One trait's fn `name` for trait ref `tr` (see `trait_fn_value`):
    /// selection must confirm a written impl with every impl param known.
    fn trait_fn_of(&mut self, tr: TraitRef, name: Sym, generic: bool, span: Span) -> Option<(LocalDefId, Vec<GenericArg>)> {
        use crate::traits::index::Synthetic;
        let p = self.p;
        let Selection::Impl { id, args: impl_args, unbound, .. } = self.select_obligation_at(tr, span, 0) else { return None };
        let rec_impl = p.gx.index.get(id);
        if !unbound.is_empty() || rec_impl.synthetic != Synthetic::None {
            return None;
        }
        let (f, prefix) = match rec_impl.items.iter().find_map(|&d| p.local_def(d.hash).filter(|&l| p.fn_info(l).name == name)) {
            Some(l) => (l, impl_args),
            None => {
                let m = p.gx.index.trait_record(tr.def)?.method_by_name(name)?;
                let l = p.local_def(m.hash)?;
                let raw: Vec<GenericArg> = self.tys.args(tr.args).to_vec();
                (l, raw.into_iter().map(|g| if let GenericArg::Ty(t) = g { GenericArg::Ty(self.deep(t)) } else { g }).collect())
            }
        };
        let is_template = p.gx.fn_templates.get(f.0 as usize).is_some_and(|t| t.is_some());
        if is_template && !generic {
            return None;
        }
        Some((f, prefix))
    }

    /// The one turbofish type argument on a path callee's last
    /// segment, resolved; a fresh inference variable when absent.
    fn callee_turbo_ty(&mut self, callee: ExprId, span: Span) -> Ty {
        let args = match self.p.ast.expr(callee) {
            Expr::Path(segs) => segs.last().map(|s| s.type_args()).unwrap_or_default(),
            _ => Vec::new(),
        };
        match args.len() {
            0 => self.new_var(false),
            1 => self.resolve_written(args[0]),
            _ => {
                self.err("L0105", span, "this function takes one type argument", "Write one type in the `::<...>`.");
                ERROR
            }
        }
    }

    /// A `size_of` or `align_of` query on the given turbofish type argument:
    /// the layout engine answers, or the layout reject fires (ARCH 4.4).
    /// `mem::needs_drop::<T>()`: whether `T` has drop glue, baked in as
    /// a constant like `size_of`. Types whose drop answer lust models
    /// loosely (closures, iterator adapters, trait objects) reject.
    fn needs_drop_query(&mut self, seg: &ast::PathSeg, span: Span) -> Res {
        let args = seg.type_args();
        if args.len() != 1 {
            self.err("L0105", span, "this function takes one type argument", "Write `needs_drop::<Type>()`.");
            return Res::ConstBool(false);
        }
        let t = self.resolve_written(args[0]);
        let t = self.deep(t);
        let p: &Program = self.p;
        p.record_layout_reads(&mut self.out.reads, &self.tys, t);
        if self.is_template_check() && self.tys.flags(t).contains_param() {
            return Res::ConstBool(false);
        }
        if depth::query_overflows(p, &self.tys, t, true, self.recursion_limit) {
            self.err("L0611", span, "overflow evaluating whether this type is `Copy`: it nests deeper than the recursion limit", "Nest the type less deeply, or raise `#![recursion_limit]`.");
            return Res::ConstBool(false);
        }
        // The question is about a written, concrete type: ask the
        // global store (a body-local inference leftover answers None).
        let drop = p.gx.lang.drop;
        let drop_defs: Vec<DefId> = p
            .gx
            .index
            .all_impls()
            .filter(|(_, r)| r.trait_def == drop)
            .filter_map(|(_, r)| p.tys.args(r.trait_ref.args).first().and_then(|g| g.as_ty()).and_then(|s| p.tys.adt_parts(s)).map(|(d, _)| d))
            .collect();
        let answer = if self.tys.flags(t).contains_infer() { None } else { needs_drop_answer(p, &mut self.tys, &drop_defs, t) };
        match answer {
            Some(b) => Res::ConstBool(b),
            None => {
                let tn = self.tn(t);
                self.err("L0641", span, format!("`needs_drop` of `{tn}` is not supported yet"), "Ask about a type without closures, iterators, or trait objects.");
                Res::ConstBool(false)
            }
        }
    }

    fn layout_query(&mut self, seg: &ast::PathSeg, align: bool, span: Span) -> Res {
        let args = seg.type_args();
        if args.len() != 1 {
            self.err("L0105", span, "this function takes one type argument", "Write `size_of::<Type>()`.");
            return Res::ConstUsize(0);
        }
        let t = self.resolve_written(args[0]);
        let p: &Program = self.p;
        let t = self.deep(t);
        if depth::query_overflows(p, &self.tys, t, false, self.recursion_limit) {
            self.err("L0611", span, "queries overflow the depth limit computing this type's layout", "Nest the type less deeply, or raise `#![recursion_limit]`.");
            return Res::ConstUsize(0);
        }
        // The answer is baked into this body as a constant. Record a
        // layout read for every Adt in the type: the written-type
        // binding read only names an outermost path, so a compound
        // type (`[S; 2]`, `(S, u8)`) would record nothing for `S`.
        p.record_layout_reads(&mut self.out.reads, &self.tys, t);
        // A template check has no layout for a type over its params;
        // each instance answers with its own (the template body is
        // never generated). A const context still needs the number,
        // and its evaluator rejects the param (`ConstCx::layout`). A
        // generic associated const's initializer body is check-only too:
        // its value comes per instance from `assoc_eval`.
        // The placeholder still needs rustc's `T: Sized` requirement:
        // `size_of::<T>()` with only `T: ?Sized` in the env rejects.
        if self.layout_placeholders() && self.tys.flags(t).contains_param() {
            if !self.sized_ok(t) {
                let tn = self.tn(t);
                self.err(
                    "L0110",
                    span,
                    format!("the size for values of type `{tn}` cannot be known"),
                    "Add a `Sized` bound, or use `size_of_val` on a reference.",
                );
            }
            return Res::ConstUsize(0);
        }
        match crate::ty::layout::layout_of_ty(&self.tys, &UserLayout(p), t) {
            Ok(l) => Res::ConstUsize(if align { l.align } else { l.size }),
            Err(()) => {
                self.err(
                    "L0652",
                    span,
                    format!("unsupported layout form: `{}`", self.tn(t)),
                    "Use a type inside the supported layout grammar.",
                );
                Res::ConstUsize(0)
            }
        }
    }

    /// `From` between a literal variable and a scalar (`u32: From<{integer}>`,
    /// `{float}: From<f32>`), decided as rustc decides it from core's
    /// numeric impls: none is NoImpl, exactly one binds the literal to
    /// it (`let c: char = From::from(65)` makes 65 a u8), more defer to
    /// the literal fallback. None when neither side is such a pair.
    fn lit_from_select(&mut self, input: Ty, ik: TyKind, self_ty: Ty, sk: TyKind) -> Option<Selection> {
        let scalar = |k: TyKind| matches!(k, TyKind::Int(_) | TyKind::Float(_) | TyKind::Char | TyKind::Bool);
        let floats = [self.tys.float_ty(FloatTy::F32), self.tys.float_ty(FloatTy::F64)];
        let lit_types = |k: TyKind| -> Option<Vec<Ty>> {
            if k.is_int_infer() {
                Some(IntTy::ALL_SUPPORTED.iter().map(|&i| int(i)).collect())
            } else if k.is_float_infer() {
                Some(floats.to_vec())
            } else {
                None
            }
        };
        let (var, choices): (Ty, Vec<Ty>) = match (lit_types(ik), lit_types(sk)) {
            (Some(_), Some(_)) => return Some(Selection::Ambiguous),
            (Some(ts), None) if scalar(sk) => (input, ts.into_iter().filter(|&t| Self::numeric_from_ok(self.kind(t), sk)).collect()),
            (None, Some(ts)) if scalar(ik) => (self_ty, ts.into_iter().filter(|&t| Self::numeric_from_ok(ik, self.kind(t))).collect()),
            _ => return None,
        };
        Some(match choices[..] {
            [] => Selection::NoImpl,
            [t] if self.unify(var, t) => Selection::ParamEvidence(usize::MAX),
            [_] => Selection::NoImpl,
            _ => Selection::Ambiguous,
        })
    }

    /// True for the scalar conversions `From` provides in core
    /// (identity is the blanket's job and also answers true).
    fn numeric_from_ok(src: TyKind, dst: TyKind) -> bool {
        // Core's exact `From` set between the scalar types (rustc
        // 1.99 on a 64-bit target; probed exhaustively). Identity
        // is the blanket's job and also answers true. Notable
        // non-obvious cells: `usize`/`isize` have no outgoing
        // impls at all, `usize` is a target only of u8/u16/bool,
        // `isize` only of u8/i8/i16/bool, int-to-float exists only
        // where every value is exact (f32: 16-bit ints, f64:
        // 32-bit ints), and bool converts to every int and float.
        use IntTy::*;
        if src == dst {
            return true;
        }
        match (src, dst) {
            (TyKind::Bool, TyKind::Int(_) | TyKind::Float(_)) => true,
            (TyKind::Char, TyKind::Int(U32 | U64 | U128)) => true,
            (TyKind::Int(U8), TyKind::Char) => true,
            (TyKind::Float(FloatTy::F32), TyKind::Float(FloatTy::F64)) => true,
            (TyKind::Int(s), TyKind::Int(d)) => match (s, d) {
                (Usize | Isize, _) => false,
                (U8 | U16, Usize) => true,
                (U8 | I8 | I16, Isize) => true,
                (_, Usize | Isize) => false,
                _ => d.bits() > s.bits() && (!s.signed() || d.signed()),
            },
            (TyKind::Int(s), TyKind::Float(f)) => match f {
                FloatTy::F32 => matches!(s, U8 | U16 | I8 | I16),
                FloatTy::F64 => matches!(s, U8 | U16 | U32 | I8 | I16 | I32),
            },
            _ => false,
        }
    }

    /// The Adt `Self` names in this body: the method's owner, or the
    /// scope's Self type (a trait default assoc fn has no receiver to
    /// name an owner).
    fn self_adt(&self) -> Option<AdtId> {
        if let Some(a) = self.const_fn_self {
            return a;
        }
        self.f.owner.or_else(|| self.body_scope.self_ty.and_then(|t| self.tys.local_adt(t)))
    }

    /// The Self type of `Type::name(..)` when the call goes through a
    /// trait: `Type` is an Adt (or an alias of one) with no variant and
    /// no inherent fn called `name`, or `picked` (the template check
    /// already resolved the call through a trait). Type arguments are
    /// the written ones (`M::<u8>::mk`, `Self` in `impl M<u8>`, an
    /// alias's), else fresh variables: rustc selects the impl for
    /// that type (E0599 when only `M<u16>` has one).
    fn trait_assoc_base(&mut self, segs: &[ast::PathSeg], picked: bool, span: Span) -> Option<Ty> {
        let p = self.p;
        let (ty_name, item) = (segs[0].name, segs[1].name);
        // A primitive type names itself as the base (`u32::from(x)`):
        // there is no Adt, and the assoc call probes traits for it.
        if let Some(it) = p.known.int_ty(ty_name) {
            return Some(int(it));
        }
        if ty_name == p.known.bool {
            return Some(BOOL);
        }
        if ty_name == p.known.char {
            return Some(CHAR);
        }
        if ty_name == p.known.f32 {
            return Some(self.tys.float_ty(FloatTy::F32));
        }
        if ty_name == p.known.f64 {
            return Some(self.tys.float_ty(FloatTy::F64));
        }
        let a = if ty_name == p.known.self_type {
            self.self_adt()?
        } else if let Some(a) = self.local_adt_of(ty_name) {
            a
        } else {
            match self.binding(Namespace::Type, ty_name) {
                BindingRes::Def(def) => p.adt_by_def(def).or_else(|| self.alias_adt_seg(&segs[0], span).map(|(a, ..)| a))?,
                _ => return None,
            }
        };
        if !picked {
            p.inherent_reads(&mut self.out.reads, p.def_of_adt(a), item);
        }
        if !picked && (p.methods.contains_key(&(a, item)) || (p.adt(a).is_enum && p.adt(a).variants.iter().any(|v| v.name == item))) {
            return None;
        }
        let generics = p.gx.adt_generics.get(a.0 as usize).cloned().unwrap_or_default();
        if generics.params.is_empty() {
            return Some(self.tys.adt_ty(a));
        }
        let args = self.value_path_args(a, &segs[..1], span);
        Some(self.tys.mk_adt(p.def_of_adt(a), &args))
    }

    /// `W::<u8>::new()`: type arguments written on the type segment
    /// of a path call fix the Self type of the inherent impl, and so
    /// the impl's parameters in the method's template args.
    /// The type a two-segment `T::item` path heads with when `T` is a
    /// type parameter in scope (its instance type in an instance), or
    /// `Self` in a trait default body (the trait's Self param).
    fn param_path_base(&self, segs: &[ast::PathSeg]) -> Option<Ty> {
        if segs.len() != 2 {
            return None;
        }
        let param_self = self.body_scope.self_ty.filter(|&t| matches!(self.tys.kind(t), TyKind::Param(_)));
        self.body_scope
            .param_tys
            .iter()
            .find(|(n, _)| *n == segs[0].name)
            .map(|&(_, t)| t)
            .or(if segs[0].name == self.p.known.self_type { param_self } else { None })
    }

    /// In an instance of a generic body, the template's one bound on
    /// `self_ty` whose trait declares `method`, substituted at the
    /// instance's args: what a `T::method(..)` call meant in the
    /// template, where a type param resolves only through its bounds
    /// (see `instance_bound_arg` for the conversion methods). None
    /// outside instances, or when no bound or several bounds match.
    fn instance_bound_ref(&mut self, method: Sym, self_ty: Ty) -> Option<TraitRef> {
        let p = self.p;
        let info = p.gx.instances.get(&self.fid)?;
        let tl = info.template_local?;
        let env = p.gx.fn_scopes.get(tl.0 as usize)?.env.clone();
        let args: Vec<GenericArg> = p.tys.args(info.args).to_vec();
        let self_ty = self.resolve(self_ty);
        let mut found: Option<TraitRef> = None;
        for pred in env {
            let Predicate::Trait(b) = pred else { continue };
            if b.count != 0 || p.gx.index.trait_record(b.value.def).and_then(|r| r.method_by_name(method)).is_none() {
                continue;
            }
            let tr = crate::traits::index::subst_trait_ref_pub(&mut self.tys, b.value, &args);
            if self.tys.args(tr.args).first().and_then(|g| g.as_ty()) != Some(self_ty) {
                continue;
            }
            if found.is_some_and(|f| f != tr) {
                return None;
            }
            found = Some(tr);
        }
        found
    }

    /// True when `t` is an Adt with a written `Index` or `IndexMut`
    /// impl (any args).
    fn has_user_index_impl(&self, t: Ty) -> bool {
        use crate::traits::index::{SelfHead, Synthetic};
        let p = self.p;
        let Some((def, _)) = self.tys.adt_parts(t) else { return false };
        [p.gx.lang.index, p.gx.lang.index_mut].iter().any(|&tr| {
            p.gx.index.impls_of_trait(tr).iter().any(|&id| {
                let rec = p.gx.index.peek(id);
                rec.synthetic == Synthetic::None && rec.head == SelfHead::Adt(def)
            })
        })
    }

    /// `inherent_fn_by_self` for a lang enum (`Option::copied` lives
    /// on both `Option<&T>` and `Option<&mut T>`): the written Self
    /// type comes from the type segment's args (`Option::<&i32>`);
    /// with none written every param is fresh, so several fits report
    /// the ambiguity rustc reports (E0034).
    fn lang_fn_by_self(&mut self, def: crate::def::DefId, fs: &[LocalDefId], segs: &[ast::PathSeg], span: Span) -> Option<LocalDefId> {
        let p = self.p;
        let n_params = if def == self.tys.builtins().option { 1 } else { 2 };
        let mut args: Vec<GenericArg> = Vec::new();
        if let Some(seg) = segs.get(segs.len().saturating_sub(2))
            && let ast::GenericArgs::Angle(written) = &seg.args
        {
            for w in written.iter().filter(|w| !matches!(w, ast::GenericArg::Lifetime(_))) {
                match w {
                    ast::GenericArg::Type(t) => args.push(GenericArg::Ty(self.resolve_written(*t))),
                    _ => args.push(GenericArg::Ty(self.new_var(false))),
                }
            }
        }
        while args.len() < n_params {
            args.push(GenericArg::Ty(self.new_var(false)));
        }
        args.truncate(n_params);
        let written = self.tys.mk_adt(def, &args);
        let mut found = Vec::new();
        for &f in fs {
            let Some(self_tmpl) = p.gx.fn_scopes.get(f.0 as usize).and_then(|s| s.scope.self_ty) else { continue };
            let self_ty = match p.gx.fn_templates.get(f.0 as usize) {
                Some(Some(tmpl)) => {
                    let args = self.fresh_args(&tmpl.generics.clone());
                    subst(&mut self.tys, self_tmpl, &args)
                }
                _ => self_tmpl,
            };
            let snap = self.snapshot_vars();
            if self.unify(self_ty, written) {
                found.push(f);
            }
            self.rollback_vars(snap);
        }
        let item = self.name(segs[segs.len() - 1].name).to_string();
        match found.as_slice() {
            &[f] => Some(f),
            [] => {
                let tn = self.tn(written);
                self.err("L0104", span, format!("no associated function `{item}` for `{tn}`"), "Check the type's arguments.");
                None
            }
            _ => {
                self.err(
                    "L0720",
                    span,
                    format!("multiple applicable items named `{item}` are in scope"),
                    "Write the type's arguments, such as `Option::<&u8>::name`.",
                );
                None
            }
        }
    }

    /// One of several inherent fns of one name, each in its own impl
    /// (`impl W<u8>` and `impl W<u16>` both define `tag`), by the
    /// path's Self type (`W::<u16>::tag`, an alias, or `Self`): the one
    /// fn whose impl's Self type unifies with it. None after reporting
    /// no match (rustc E0599) or more than one (E0034, `W::tag()`).
    fn inherent_fn_by_self(&mut self, a: AdtId, fs: &[LocalDefId], segs: &[ast::PathSeg], span: Span) -> Option<LocalDefId> {
        let p = self.p;
        let gargs = self.value_path_args(a, &segs[..segs.len().saturating_sub(1).max(1)], span);
        let written = self.tys.mk_adt(p.def_of_adt(a), &gargs);
        let mut found = Vec::new();
        for &f in fs {
            let Some(self_tmpl) = p.gx.fn_scopes.get(f.0 as usize).and_then(|s| s.scope.self_ty) else { continue };
            let self_ty = match p.gx.fn_templates.get(f.0 as usize) {
                Some(Some(tmpl)) => {
                    let args = self.fresh_args(&tmpl.generics.clone());
                    subst(&mut self.tys, self_tmpl, &args)
                }
                _ => self_tmpl,
            };
            let snap = self.snapshot_vars();
            if self.unify(self_ty, written) {
                found.push(f);
            }
            self.rollback_vars(snap);
        }
        let item = self.name(segs[segs.len() - 1].name).to_string();
        match found.as_slice() {
            &[f] => Some(f),
            [] => {
                let tn = self.tn(written);
                self.err("L0104", span, format!("no associated function `{item}` for `{tn}`"), "Check the type's arguments.");
                None
            }
            _ => {
                self.err(
                    "L0720",
                    span,
                    format!("multiple applicable items named `{item}` are in scope"),
                    "Write the type's arguments, such as `W::<u8>::name`.",
                );
                None
            }
        }
    }

    /// The Self type a path call or fn value writes before the fn's
    /// name fixes the impl's params: `S::<u8>::make`, `Self::make` (the
    /// impl's own Self type, also in `impl S<u8>` calling a fn of
    /// `impl<T> S<T>`), or an alias of the Adt at fixed args (`type A =
    /// S<u8>; A::make(5)`), where `value_path_args` gives the args. `inst_args` is empty
    /// for a plain fn: a concrete impl's Self (`impl S<u8>`) must then
    /// be the written type (rustc E0599 for `S::<u16>::make`).
    fn unify_written_self(&mut self, callee: ExprId, f: LocalDefId, inst_args: &[GenericArg], span: Span) {
        let p = self.p;
        let Expr::Path(segs) = p.ast.expr(callee) else { return };
        if segs.len() != 2
            || !(segs[0].has_args()
                || segs[0].name == p.known.self_type
                || self.alias_adt_seg(&segs[0], span).is_some_and(|(_, args, _)| !args.is_empty()))
        {
            return;
        }
        let Some(owner) = p.fn_info(f).owner else { return };
        let Some(self_tmpl) = p.gx.fn_scopes.get(f.0 as usize).and_then(|s| s.scope.self_ty) else { return };
        let gargs = self.value_path_args(owner, &segs[..1], span);
        let written_ty = self.tys.mk_adt(p.def_of_adt(owner), &gargs);
        let self_ty = subst(&mut self.tys, self_tmpl, inst_args);
        if !self.unify(self_ty, written_ty) {
            self.mismatch(span, written_ty, self_ty);
        }
    }

    /// An associated function call through a trait:
    /// `<T as Tr>::name(..)` or `T::name(..)`. Selects the impl
    /// for the Self type and calls the method as a free fn (an
    /// explicit receiver is simply its first parameter).
    fn assoc_call(
        &mut self,
        e: ExprId,
        callee: ExprId,
        base: Ty,
        hint: Option<TraitRef>,
        name: Sym,
        args: &[ExprId],
        span: Span,
    ) -> Option<Ty> {
        let p = self.p;
        // `Type::name` with no written trait: a std item of the name wins
        // or ties (check/std_inherent.rs).
        if hint.is_none() && self.replay_pick(e).is_none() && self.std_shadow_path(base, name, false, span) {
            for &a in args {
                self.expr(a, None);
            }
            return Some(ERROR);
        }
        // An instance replays the template's param-env evidence for a
        // `from` call (`U: From<u8>` fixes the input: check/picks.rs).
        let hint = match self.replayed_trait_ref(e, p.gx.lang.from) {
            Some(r) if self.name(name) == "from" && hint.is_none_or(|h| h.def == p.gx.lang.from) => Some(r),
            _ => hint,
        };
        // Numeric `From::from` is a widening cast, with no user
        // fn behind it (the lang blanket covers only identity).
        if self.name(name) == "from" && args.len() == 1 && hint.is_none_or(|h| h.def == p.gx.lang.from) {
            let src = self.expr(args[0], None);
            // A written trait (`<M as From<i32>>::from`) fixes the
            // input type: a literal takes it, and a suffixed
            // argument of another type is the mismatch rustc
            // reports through the impl's signature below.
            let hint_input = hint.and_then(|h| self.tys.args(h.args).get(1).and_then(|g| g.as_ty())).map(|t| self.deep(t));
            let hint_ok = match hint_input {
                Some(hi) => self.unify(src, hi),
                None => true,
            };
            let src = self.deep(src);
            if hint_ok && Self::numeric_from_ok(self.kind(src), self.kind(base)) {
                self.set_res(callee, Res::FromCast);
                self.set_res(e, Res::FromCast);
                return Some(base);
            }
            let src_kind = self.kind(src);
            if matches!(src_kind, TyKind::Int(_) | TyKind::Float(_) | TyKind::Char | TyKind::Bool)
                || src_kind.is_int_infer()
                || src_kind.is_float_infer()
            {
                // With the input type known from the argument,
                // selection can pick between input-specific impls
                // (or, in a template check, the bounds for each From).
                // An unsuffixed literal with several fitting impls
                // falls back to i32/f64, as in rustc: try the
                // written or literal type first, then the fallback.
                let mut candidates: Vec<TraitRef> = Vec::new();
                match hint {
                    Some(h) => candidates.push(h),
                    None => {
                        let args_id = self.tys.intern_args(&[GenericArg::Ty(base), GenericArg::Ty(src)]);
                        candidates.push(TraitRef { def: p.gx.lang.from, args: args_id, bindings: EMPTY_BINDINGS });
                    }
                }
                let fallback = if src_kind.is_int_infer() {
                    Some(int(IntTy::I32))
                } else if src_kind.is_float_infer() {
                    Some(self.tys.float_ty(FloatTy::F64))
                } else {
                    None
                };
                let n_tries = if fallback.is_some() { 2 } else { 1 };
                for try_no in 0..n_tries {
                    let snap = self.snapshot_vars();
                    let obl_len = self.obl_len();
                    let sites_len = self.generic_sites.len();
                    let tr = if try_no == 0 {
                        candidates[0]
                    } else {
                        let fb = fallback.expect("second try has a fallback");
                        if !self.unify(src, fb) {
                            break;
                        }
                        // The fallback type widens like a suffixed literal.
                        if Self::numeric_from_ok(self.kind(fb), self.kind(base)) {
                            self.set_res(callee, Res::FromCast);
                            self.set_res(e, Res::FromCast);
                            return Some(base);
                        }
                        let args_id = self.tys.intern_args(&[GenericArg::Ty(base), GenericArg::Ty(fb)]);
                        TraitRef { def: p.gx.lang.from, args: args_id, bindings: EMPTY_BINDINGS }
                    };
                    let mut env_pick: Option<usize> = None;
                    let found = match self.select_obligation_at(tr, span, 0) {
                        Selection::Impl { id, args: impl_args, .. } => self.method_instance_for_impl(e, id, tr, impl_args, "from", span),
                        // The one numeric impl a literal fits (it is bound now).
                        Selection::ParamEvidence(usize::MAX) => {
                            self.set_res(callee, Res::FromCast);
                            self.set_res(e, Res::FromCast);
                            return Some(base);
                        }
                        Selection::ParamEvidence(i) => {
                            env_pick = Some(i);
                            self.stub_instance(e, tr, name, span)
                        }
                        _ => None,
                    };
                    if let Some((local, params, ret)) = found {
                        if env_pick.is_some() {
                            self.record_pick_env(e, p.gx.lang.from, 0, ReceiverForm::Value, env_pick);
                        }
                        self.set_res(e, Res::Fn(local));
                        self.check_args(&params, args, span);
                        return Some(self.normalize_use(ret, span));
                    }
                    self.rollback_vars(snap);
                    self.obl_truncate(obl_len);
                    self.generic_sites.truncate(sites_len);
                }
                // A literal argument with no scalar impl even after its fallback
                // has no other reading (`let d: u32 = From::from(c)` with
                // `c = 3` needs `u32: From<i32>`): report it here, not
                // through a later path that does not check the impl.
                if let Some(fb) = fallback
                    && matches!(self.kind(base), TyKind::Int(_) | TyKind::Float(_) | TyKind::Char | TyKind::Bool)
                {
                    let (fbn, tn) = (self.tn(fb), self.tn(base));
                    let msg = format!("no impl of `From<{fbn}>` for `{tn}`");
                    self.err("L0612", span, msg, "Add a literal suffix, or change the target type.");
                    return Some(ERROR);
                }
                return None;
            }
        }
        // Scalar and blanket `try_from` (check/tryfrom.rs), like
        // the numeric `from` above.
        if let Some(t) = self.try_from_assoc_call(e, callee, base, hint, name, args, span) {
            return Some(t);
        }
        if let Some(t) = self.try_into_assoc_call(e, callee, base, hint, name, args, span) {
            return Some(t);
        }
        // `BuildHasher::build_hasher` and `hash_one` by path
        // (check/hashmap.rs): written methods, std's builders, and
        // the provided `hash_one` have no fn in the trait index.
        if let Some(t) = self.builder_assoc_call(e, callee, base, hint, name, args, span) {
            return Some(t);
        }
        if self.name(name) == "default"
            && args.is_empty()
            && matches!(self.kind(base), TyKind::Int(_) | TyKind::Bool | TyKind::Char | TyKind::Unit)
        {
            self.set_res(callee, Res::DefaultVal);
            self.set_res(e, Res::DefaultVal);
            return Some(base);
        }
        // `{integer}::midpoint(a, b)` (1.85 unsigned, 1.87 signed):
        // an inherent associated fn, so no trait probe finds it.
        // The 128-bit forms stay out for now.
        if name == p.known.midpoint
            && args.len() == 2
            && let TyKind::Int(it) = self.kind(base)
            && it.bits() < 128
        {
            self.set_res(callee, Res::Builtin(Builtin::IntMidpoint));
            self.set_res(e, Res::Builtin(Builtin::IntMidpoint));
            self.check_args(&[base, base], args, span);
            return Some(base);
        }
        // `<dyn P as Tr>::m(d)` and `<dyn P>::m(d)` (ARCH 2.8): an
        // `impl dyn P` method, or an object candidate through the vtable.
        if let Some(t) = self.dyn_assoc_call(e, base, hint, name, args, span) {
            return Some(t);
        }
        // The trait: written, or the template check's pick, or the
        // where clauses of a type parameter (rustc probes those as
        // inherent candidates first), or every trait in scope.
        let bound = if hint.is_none() { self.bound_traits_with(base, name) } else { Vec::new() };
        let traits: Vec<DefId> = match (hint, self.replay_pick(e)) {
            (Some(tr), _) => vec![tr.def],
            (None, Some(pick)) => vec![pick.trait_def],
            (None, None) if !bound.is_empty() => bound,
            (None, None) => {
                p.gx.traits_by_method
                    .get(&name)
                    .cloned()
                    .unwrap_or_default()
                    .into_iter()
                    .filter(|&d| method::trait_in_scope_at(self, d, base))
                    .collect()
            }
        };
        let mut hits: Vec<(LocalDefId, Vec<Ty>, Ty)> = Vec::new();
        let mut hit_traits: Vec<DefId> = Vec::new();
        // The env predicate of the first param-env hit (`record_pick_env`).
        let mut hit_env: Option<usize> = None;
        // Traits whose selection the open inputs left ambiguous.
        let mut ambiguous: Vec<DefId> = Vec::new();
        // A `Default` impl with no method fn (a derive, or core's
        // impl for a builtin type) that builds its value by
        // structure: lowering emits the `default` glue.
        let mut default_glue = false;
        for trait_def in traits {
            let Some(rec) = p.gx.index.trait_record(trait_def).cloned() else { continue };
            if rec.method_by_name(name).is_none() {
                continue;
            }
            let snap = self.snapshot_vars();
            let obl_len = self.obl_len();
            let sites_len = self.generic_sites.len();
            let tr = self.assoc_trait_ref(e, base, hint, trait_def, &rec);
            match self.select_obligation_at(tr, span, 0) {
                Selection::Impl { id, args: impl_args, .. } => {
                    let mname = self.name(name).to_string();
                    if let Some(found) = self.method_instance_for_impl(e, id, tr, impl_args, &mname, span) {
                        hits.push(found);
                        hit_traits.push(trait_def);
                        continue;
                    }
                    if trait_def == p.gx.lang.default
                        && mname == "default"
                        && p.gx.index.get(id).synthetic != crate::traits::index::Synthetic::None
                        && has_default(p, &self.tys, base)
                    {
                        default_glue = true;
                        hit_traits.push(trait_def);
                        continue;
                    }
                }
                // A structural answer (tuples, arrays: no impl
                // record) is not a bound: `Default` builds by glue,
                // and no other trait method has a body to call.
                Selection::ParamEvidence(usize::MAX) => {
                    if trait_def == p.gx.lang.default && self.name(name) == "default" && has_default(p, &self.tys, base) {
                        default_glue = true;
                        hit_traits.push(trait_def);
                        continue;
                    }
                }
                Selection::ParamEvidence(i) => {
                    if let Some(found) = self.stub_instance(e, tr, name, span) {
                        hits.push(found);
                        hit_traits.push(trait_def);
                        hit_env.get_or_insert(i);
                        continue;
                    }
                }
                // The trait's inputs are open (`S::conv(3u8)` with impls
                // of `Conv<u8>` and `Conv<u16>`; `S::from(o)`, where
                // core's identity impl also applies): the args may fix
                // them (`assoc_call_deferred`).
                Selection::Ambiguous if rec.generics.params.len() > 1 => ambiguous.push(trait_def),
                _ => {}
            }
            self.rollback_vars(snap);
            self.obl_truncate(obl_len);
            self.generic_sites.truncate(sites_len);
        }
        if hits.is_empty()
            && !default_glue
            && let [trait_def] = ambiguous[..]
        {
            return self.assoc_call_deferred(e, base, hint, trait_def, name, args, span);
        }
        // A trait with open inputs applies too: with another trait that
        // has the method, the path is ambiguous (rustc E0034).
        let hits_len = if ambiguous.is_empty() { hits.len() } else { hit_traits.len() + ambiguous.len() };
        match hits_len {
            0 if default_glue && hit_traits.len() == 1 => {
                self.record_glue_reads(p.gx.lang.default, base);
                self.record_pick(e, hit_traits[0], 0, ReceiverForm::Value);
                self.set_res(callee, Res::DefaultVal);
                self.set_res(e, Res::DefaultVal);
                self.check_args(&[], args, span);
                Some(base)
            }
            1 if !default_glue => {
                let (local, params, ret) = hits.into_iter().next().unwrap();
                self.record_pick_env(e, hit_traits[0], 0, ReceiverForm::Value, hit_env);
                self.set_res(e, Res::Fn(local));
                self.check_args(&params, args, span);
                Some(self.normalize_use(ret, span))
            }
            0 => None,
            _ => {
                self.err(
                    "L0720",
                    span,
                    format!("multiple trait methods named `{}` apply here", self.name(name)),
                    "Call the method with a fully qualified path, such as `<Type as Trait>::method(...)`.",
                );
                for &a in args {
                    self.expr(a, None);
                }
                Some(ERROR)
            }
        }
    }

    /// Records the reads behind a structural answer of the derive
    /// glue (`has_clone`, `has_default`): the layout of every Adt in
    /// `t`, whose fingerprint covers derives, nested field types, and
    /// the written impls the glue calls (`glue_methods`), so a warm
    /// body rechecks when one of those changes (section 8.2; the
    /// predicates themselves record nothing).
    fn record_glue_reads(&mut self, trait_def: DefId, t: Ty) {
        let t = self.deep(t);
        // `Clone` of a reference or a shared pointer reads nothing of
        // its target (`glue_clone`).
        use crate::driver::graph::{Behind, answer};
        let lang = &self.p.gx.lang;
        let behind = if trait_def == lang.clone { Behind::Clone } else { Behind::Other };
        let kind = match trait_def {
            d if d == lang.clone => answer::CLONE,
            d if d == lang.partial_eq => answer::PARTIAL_EQ,
            d if d == lang.eq => answer::EQ,
            d if d == lang.partial_ord => answer::PARTIAL_ORD,
            _ => answer::DEFAULT,
        };
        self.p.record_structure_reads(&mut self.out.reads, &self.tys, t, behind, kind);
    }

    /// The trait ref an assoc call on `base` asks of `trait_def`: the
    /// written one, or Self with the template's replayed inputs, or
    /// fresh variables for them.
    fn assoc_trait_ref(&mut self, e: ExprId, base: Ty, hint: Option<TraitRef>, trait_def: DefId, rec: &crate::traits::index::TraitRecord) -> TraitRef {
        if let Some(written) = hint.filter(|h| h.def == trait_def) {
            return written;
        }
        let replayed = self.replayed_trait_ref(e, trait_def);
        let mut tr_args: Vec<GenericArg> = vec![GenericArg::Ty(base)];
        for (i, param) in rec.generics.params.iter().enumerate().skip(1) {
            let arg = match replayed.and_then(|r| self.tys.args(r.args).get(i).copied()) {
                Some(g) => g,
                None => match param.kind {
                    ParamKind::Const(_) => GenericArg::Const(self.fresh_const_var()),
                    _ => GenericArg::Ty(self.new_var(false)),
                },
            };
            tr_args.push(arg);
        }
        let args_id = self.tys.intern_args(&tr_args);
        TraitRef { def: trait_def, args: args_id, bindings: EMPTY_BINDINGS }
    }

    /// An assoc call whose trait inputs only the args fix (see
    /// `assoc_call`), deferred as rustc does and as method calls do
    /// (`method::confirm_deferred`): the call is typed by the trait's
    /// own signature, the trait obligation stays queued (its error is
    /// rustc's E0277), and body end selects the impl
    /// (`method::finish_deferred_methods`).
    #[allow(clippy::too_many_arguments)]
    fn assoc_call_deferred(
        &mut self,
        e: ExprId,
        base: Ty,
        hint: Option<TraitRef>,
        trait_def: DefId,
        name: Sym,
        args: &[ExprId],
        span: Span,
    ) -> Option<Ty> {
        let p = self.p;
        let rec = p.gx.index.trait_record(trait_def)?;
        let method_def = rec.method_by_name(name)?;
        let n_trait = rec.generics.params.len();
        let tr = self.assoc_trait_ref(e, base, hint, trait_def, rec);
        let mut full: Vec<GenericArg> = self.tys.args(tr.args).to_vec();
        let (sig_params, sig_ret, preds) = match p.gx.trait_methods.get(&method_def) {
            Some(t) => {
                for param in t.generics.params.iter().skip(n_trait) {
                    full.push(match param.kind {
                        ParamKind::Type => GenericArg::Ty(self.new_var(false)),
                        ParamKind::Lifetime => GenericArg::Lifetime(Region::Erased),
                        ParamKind::Const(_) => GenericArg::Const(self.fresh_const_var()),
                    });
                }
                (t.params.clone(), t.ret, t.generics.predicates.clone())
            }
            None => {
                let s = p.gx.lang_method_sigs.get(&method_def)?;
                (s.params.clone(), s.ret, Vec::new())
            }
        };
        let mut params: Vec<Ty> = sig_params.iter().map(|&t| subst(&mut self.tys, t, &full)).collect();
        let ret = subst(&mut self.tys, sig_ret, &full);
        self.normalize_params(&mut params, span);
        self.push_predicates(&preds, &full, span);
        self.obl.push_trait_at(tr, span, 0);
        method::defer_path_call(self, e, tr, name, full[n_trait..].to_vec());
        self.record_pick(e, trait_def, 0, ReceiverForm::Value);
        self.check_args(&params, args, span);
        Some(self.normalize_use(ret, span))
    }

    /// `Default::default()`, `From::from(x)`, and a user trait's fn
    /// with no `self` (`Mk::mk(8)`) written through the trait name,
    /// where no arg names Self: the expected type does (rustc infers it
    /// the same way), and the call is the assoc call on that type. With
    /// the expected type not known yet, a user trait's call is typed by
    /// the trait's signature with Self open (`assoc_call_deferred`), so
    /// a later use can fix it; nothing fixing it is rustc's E0790. None
    /// when the callee is another form or a type of that name shadows
    /// the trait.
    fn self_from_expected_call(&mut self, e: ExprId, callee: ExprId, args: &[ExprId], expected: Option<Ty>, span: Span) -> Option<Ty> {
        let p = self.p;
        let Expr::Path(segs) = p.ast.expr(callee) else { return None };
        if segs.len() != 2 {
            return None;
        }
        // The flat maps answer with no read of their own: the body checks
        // again when a user item comes to shadow the name (`struct Default`
        // over `Default::default()`).
        self.binding(Namespace::Type, segs[0].name);
        if p.type_names.contains_key(&segs[0].name) || p.aliases.contains_key(&segs[0].name) {
            return None;
        }
        if self.body_scope.param_tys.iter().any(|(n, _)| *n == segs[0].name) {
            return None;
        }
        let lang = &p.gx.lang;
        let tdef = p.gx.resolve_cx(&p.type_names, &p.aliases).trait_by_bare_name(&p.interner, segs[0].name)?;
        let rec = p.gx.index.trait_record(tdef)?;
        let lang_fn = match self.name(segs[1].name) {
            "default" => tdef == lang.default && args.is_empty(),
            "from" => tdef == lang.from && args.len() == 1,
            "try_from" => tdef == lang.try_from && args.len() == 1,
            _ => false,
        };
        let user_fn = !lang_fn
            && rec.method_by_name(segs[1].name).and_then(|m| p.gx.trait_methods.get(&m)).is_some_and(|t| t.self_kind.is_none());
        if !lang_fn && !user_fn {
            return None;
        }
        // `TryFrom::try_from` is expected at a `Result<Self, _>`:
        // Self is its `Ok` type (fx-tryfrom).
        let expected = if tdef == lang.try_from {
            expected.and_then(|t| { let t = self.deep(t); self.tys.result_args(t) }).map(|(ok, _)| ok)
        } else {
            expected
        };
        let known = expected.map(|t| self.deep(t)).filter(|&b| b != ERROR && !self.unbound_general(b));
        let Some(base) = known else {
            if !user_fn {
                return None;
            }
            let base = self.new_var(false);
            return self.assoc_call_deferred(e, base, None, tdef, segs[1].name, args, span);
        };
        let hint = self.assoc_trait_ref(e, base, None, tdef, rec);
        self.assoc_call(e, callee, base, Some(hint), segs[1].name, args, span)
    }

    /// The trait method's signature stub for a call the param env
    /// proves (a template check), instantiated at the trait ref's
    /// args and the method's own fresh ones: (stub, params, ret).
    fn stub_instance(&mut self, e: ExprId, tr: TraitRef, name: Sym, span: Span) -> Option<(LocalDefId, Vec<Ty>, Ty)> {
        let p = self.p;
        let method_def = p.gx.index.trait_record(tr.def)?.method_by_name(name)?;
        let stub = *p.gx.trait_method_stubs.get(&method_def)?;
        let generics = p.gx.fn_templates.get(stub.0 as usize)?.as_ref()?.generics.clone();
        let raw: Vec<GenericArg> = self.tys.args(tr.args).to_vec();
        let prefix: Vec<Option<GenericArg>> = raw
            .iter()
            .map(|&g| {
                Some(match g {
                    GenericArg::Ty(t) => GenericArg::Ty(self.deep(t)),
                    other => other,
                })
            })
            .collect();
        let (mut params, ret, _) = self.instantiate_template(e, stub, &generics, &prefix, span);
        self.normalize_params(&mut params, span);
        Some((stub, params, ret))
    }

    /// A call through an Fn-family bound of a type parameter or
    /// projection in this body's env (a template check). Rust calls
    /// through `Fn` when the bounds give it, else `FnMut`, else
    /// `FnOnce`: (the trait method's stub, the receiver form, the
    /// input types, the output type).
    fn fn_bound_call(&mut self, callee: Ty) -> Option<(LocalDefId, Autoref, Vec<Ty>, Ty)> {
        let p = self.p;
        let lang = p.gx.lang;
        for (tr, method, autoref) in
            [(lang.fn_, "call", Autoref::Ref), (lang.fn_mut, "call_mut", Autoref::RefMut), (lang.fn_once, "call_once", Autoref::None)]
        {
            self.note_opaques(callee);
            let env = self.solve_env();
            let Some(bound) = env.iter().find_map(|pred| match pred {
                Predicate::Trait(b)
                    if b.count == 0 && b.value.def == tr && self.tys.args(b.value.args).first().and_then(|g| g.as_ty()) == Some(callee) =>
                {
                    Some(b.value)
                }
                _ => None,
            }) else {
                continue;
            };
            let inputs = match self.tys.args(bound.args).get(1).and_then(|g| g.as_ty()).map(|t| self.tys.kind(t)) {
                Some(TyKind::Tuple(ts)) => self.tys.tys_of(ts).to_vec(),
                _ => Vec::new(),
            };
            // The output: the bound's own binding when written there,
            // else its projection, which the env's equalities settle.
            let out_assoc = lang.output_of(tr)?;
            let out = match self.tys.bindings(bound.bindings).iter().find(|(d, _)| *d == out_assoc).and_then(|(_, g)| g.as_ty()) {
                Some(t) => t,
                None => self.tys.intern(TyKind::Projection(AssocId(out_assoc), bound.args)),
            };
            let method_def = p.gx.index.trait_record(tr)?.method_by_name(p.interner.intern(method))?;
            let stub = *p.gx.trait_method_stubs.get(&method_def)?;
            return Some((stub, autoref, inputs, out));
        }
        None
    }

    /// The call resolution for a callable value's type: a fn pointer
    /// calls indirectly, a fn item calls its fn directly, and a
    /// constructor item builds its variant.
    fn callable_res(&mut self, ct: Ty) -> Option<Res> {
        match self.kind(ct) {
            TyKind::FnPtr(_) => Some(Res::Indirect),
            TyKind::FnDef(def, cargs) if def == self.tys.builtins().string => self.builtin_item_res(def, cargs).map(|(r, _, _)| r),
            TyKind::FnDef(def, cargs) => match self.p.adt_by_def(def) {
                Some(a) => Some(Res::Variant(a, self.ctor_variant(cargs))),
                None => self
                    .builtin_item_res(def, cargs)
                    .or_else(|| self.prim_item_res(def, cargs))
                    .map(|(r, _, _)| r)
                    .or_else(|| self.p.local_def(def.hash).map(Res::Fn)),
            },
            _ => None,
        }
    }

    /// A trait ref written in a body path (`<T as Tr<u8, _>>`,
    /// `Tr::<u8>::m`) with `base` as Self; `_` args become body
    /// variables.
    fn written_trait_ref(&mut self, base: Ty, tref: &ast::TraitRefExpr, span: Span) -> Result<TraitRef, Diag> {
        let p = self.p;
        // The trait's name resolves through the flat maps: its binding read.
        self.written_path(&tref.path, Namespace::Type);
        let cx = p.gx.resolve_cx(&p.type_names, &p.aliases);
        let tr =
            generics::resolve_trait_ref(&p.ast, &p.interner, &p.known, &cx, &mut self.tys, &self.body_scope.clone(), base, tref, span)?;
        let old: Vec<GenericArg> = self.tys.args(tr.args).to_vec();
        let new: Vec<GenericArg> = old
            .into_iter()
            .map(|g| match g {
                GenericArg::Ty(t) => GenericArg::Ty(self.instantiate_infers(t)),
                g => g,
            })
            .collect();
        Ok(TraitRef { args: self.tys.intern_args(&new), ..tr })
    }

    /// True when the trait args of `hint` past Self can name the
    /// existential trait ref `owner`: each equal, or still inferred.
    fn trait_args_fit(&mut self, hint: TraitRef, owner: TraitRef) -> bool {
        let (hs, os) = (self.tys.args(hint.args).to_vec(), self.tys.args(owner.args).to_vec());
        hs.len() == os.len()
            && hs.iter().zip(&os).skip(1).all(|(a, b)| match (a.as_ty(), b.as_ty()) {
                (Some(a), Some(b)) => {
                    let a = self.deep(a);
                    matches!(self.tys.kind(a), TyKind::Infer(_)) || a == self.deep(b)
                }
                _ => true,
            })
    }

    /// A path call on a dyn Self type: the `impl dyn P` method of that
    /// name, else the one object candidate (of the hinted trait, when
    /// written, or of the template's pick when this body replays one),
    /// called through the vtable with the receiver as the first
    /// argument. None when `base` is not a dyn type or nothing matches
    /// (the caller reports).
    fn dyn_assoc_call(&mut self, e: ExprId, base: Ty, hint: Option<TraitRef>, name: Sym, args: &[ExprId], span: Span) -> Option<Ty> {
        let p = self.p;
        let base = self.resolve(base);
        let principal = object::principal_of(&self.tys, base)?;
        let key = object::erase_dyn_region(&mut self.tys, base);
        let only = hint.map(|h| h.def).or_else(|| self.replay_pick(e).map(|pick| pick.trait_def));
        if only.is_none()
            && let Some(&f) = p.gx.dyn_inherent.get(&(key, name))
        {
            // Object candidates are inherent too, so a trait method of
            // the same name makes the path ambiguous (rustc E0034).
            if !object::object_cands(p, &mut self.tys, principal, name).is_empty() {
                self.err(
                    "L0720",
                    span,
                    format!("multiple applicable items named `{}` are in scope for this `dyn` type", self.name(name)),
                    "Name the trait: `<dyn Trait as Trait>::method(receiver)`.",
                );
                for &a in args {
                    self.expr(a, None);
                }
                return Some(ERROR);
            }
            self.check_dyn_method_vis(f, span);
            let (params, ret) = {
                let info = p.fn_info(f);
                (info.params.clone(), p.ret_view(f))
            };
            let ret = self.callee_ret(ret);
            self.set_res(e, Res::Fn(f));
            self.check_args(&params, args, span);
            return Some(ret);
        }
        let mut cands: Vec<(usize, object::ObjectCand)> = object::object_cands(p, &mut self.tys, principal, name)
            .into_iter()
            .enumerate()
            .filter(|(_, c)| only.is_none_or(|t| t == c.owner.def))
            .collect();
        // Written trait args pick the ref of that trait (`<dyn P as
        // B<u16>>::m` with `P: B<u8> + B<u16>`), or none.
        if let Some(h) = hint {
            cands.retain(|(_, c)| self.trait_args_fit(h, c.owner));
        }
        if cands.len() != 1 {
            return None;
        }
        let (ci, c) = cands.into_iter().next().unwrap();
        if let Some(h) = hint {
            let (hs, os) = (self.tys.args(h.args).to_vec(), self.tys.args(c.owner.args).to_vec());
            for (a, b) in hs.iter().zip(&os).skip(1) {
                if let (Some(a), Some(b)) = (a.as_ty(), b.as_ty()) {
                    self.unify(a, b);
                }
            }
        }
        let slot = match c.call {
            Ok((slot, _)) => slot,
            Err(why) => {
                let tn = self.tn(base);
                self.err(
                    "L0703",
                    span,
                    format!("the method `{}` cannot be called on `{tn}`: {why}", self.name(name)),
                    "Call it on a concrete type.",
                );
                return Some(ERROR);
            }
        };
        let tm = p.gx.trait_methods.get(&c.def)?;
        let (tparams, tret) = (tm.params.clone(), tm.ret);
        let mut sargs: Vec<GenericArg> = self.tys.args(c.owner.args).to_vec();
        sargs[0] = GenericArg::Ty(base);
        let params: Vec<Ty> = tparams.iter().map(|&t| subst(&mut self.tys, t, &sargs)).collect();
        let ret = subst(&mut self.tys, tret, &sargs);
        let cand = u8::try_from(ci).expect("at most 256 object candidates");
        self.set_res(e, Res::DynMethod { owner: c.owner.def, cand, slot, derefs: 0, autoref: Autoref::None });
        if c.needs_static && !object::dyn_is_static(p, &self.tys, base) {
            self.obl.push(obligations::Obligation::DynStatic { span });
        }
        self.check_args(&params, args, span);
        Some(self.normalize_here(ret))
    }

    /// Some(true) for a callee that names std's `align_of_val`, Some(false)
    /// for `size_of_val`: the bare prelude name (since Rust 1.80) unless a
    /// user fn of that name shadows it, or a `std::mem`/`core::mem` path.
    fn layout_of_val_callee(&mut self, callee: ExprId) -> Option<bool> {
        let Expr::Path(segs) = self.p.ast.expr(callee) else { return None };
        let last = match segs.iter().map(|s| self.name(s.name)).collect::<Vec<_>>().as_slice() {
            [n] | ["std" | "core", "mem", n] => *n,
            _ => return None,
        };
        let align = match last {
            "size_of_val" => false,
            "align_of_val" => true,
            _ => return None,
        };
        if let [seg] = segs.as_slice()
            && (self.body_item_of(seg.name).is_some() || self.binding_fn(seg.name).is_some())
        {
            return None;
        }
        Some(align)
    }

    /// `size_of_val(&value)` or `align_of_val(&value)`: a constant from
    /// the layout of the value's type, or for a dyn value the size or
    /// align word of its vtable.
    fn layout_of_val(&mut self, e: ExprId, args: &[ExprId], align: bool, span: Span) -> Ty {
        let what = if align { "align_of_val" } else { "size_of_val" };
        if args.len() != 1 {
            self.err("L0105", span, "this function takes 1 argument but a different number was given", "Pass exactly one reference.");
            for &a in args {
                self.expr(a, None);
            }
            return ERROR;
        }
        let at = self.expr(args[0], None);
        let at = self.deep(at);
        let inner = match self.kind(at) {
            TyKind::Ref(_, _, inner) => inner,
            _ => {
                let tn = self.tn(at);
                self.err("L0110", span, format!("`{what}` takes a reference, found `{tn}`"), "Pass `&value`.");
                return ERROR;
            }
        };
        let inner = self.deep(inner);
        // A literal's type that later code may still fix (`let a = 1;
        // size_of_val(&a); let b: u64 = a;`) is read at the body end,
        // after every constraint and the integer and float fallback.
        if self.tys.flags(inner).contains_infer() {
            self.deferred_layout.push((e, inner, align, span));
            return USIZE;
        }
        self.layout_val_res(e, inner, align, span)
    }

    /// The `size_of_val` / `align_of_val` answer for a resolved pointee
    /// type: `Res` of call `e`, and its type.
    fn layout_val_res(&mut self, e: ExprId, inner: Ty, align: bool, span: Span) -> Ty {
        let p = self.p;
        if matches!(self.kind(inner), TyKind::Dyn(..)) {
            self.set_res(e, Res::DynMeta(if align { object::VT_ALIGN } else { object::VT_SIZE }));
            return USIZE;
        }
        p.record_layout_reads(&mut self.out.reads, &self.tys, inner);
        // A template check has no layout for a type over its
        // params (`size_of_val(t)` with `T: ?Sized` included);
        // each instance answers with its own, as in
        // `layout_query`. No Sized proof is needed here.
        if self.is_template_check() && self.tys.flags(inner).contains_param() {
            self.set_res(e, Res::ConstUsize(0));
            return USIZE;
        }
        match crate::ty::layout::layout_of_ty(&self.tys, &UserLayout(p), inner) {
            Ok(l) => {
                self.set_res(e, Res::ConstUsize(if align { l.align } else { l.size }));
                USIZE
            }
            Err(()) => {
                // Unsized tails with a runtime length: a slice is
                // `len * size_of::<elem>()`, a `str` is its byte
                // length; the align of both is the element's. Other
                // unsized forms (a generic Adt with an unsized last
                // field) stay the layout reject.
                let tail = match self.kind(inner) {
                    TyKind::Slice(elem) => {
                        crate::ty::layout::layout_of_ty(&self.tys, &UserLayout(p), elem).ok().map(|l| (Builtin::SliceLen, l.size, l.align))
                    }
                    TyKind::Str => Some((Builtin::StrLen, 1, 1)),
                    _ => None,
                };
                match tail {
                    Some((_, _, elem_align)) if align => {
                        self.set_res(e, Res::ConstUsize(elem_align));
                        USIZE
                    }
                    Some((len, elem, _)) => {
                        self.set_res(e, Res::SizeOfVal { len, elem });
                        USIZE
                    }
                    None => {
                        self.err(
                            "L0652",
                            span,
                            format!("unsupported layout form: `{}`", self.tn(inner)),
                            "Use a type inside the supported layout grammar.",
                        );
                        ERROR
                    }
                }
            }
        }
    }

    /// True when `name` names a `const` or `static` item (a body item or a
    /// module binding): a call of it calls the value it holds, a fn pointer
    /// (`static S: fn(u32) -> u32 = f; S(1)`), as a call of a local does.
    fn value_item_callee(&mut self, name: Sym) -> bool {
        match self.body_item_of(name) {
            Some(crate::check::collect::BodyItem::Const(_) | crate::check::collect::BodyItem::Static(_)) => return true,
            Some(_) => return false,
            None => {}
        }
        matches!(self.binding(Namespace::Value, name), BindingRes::Def(def) if matches!(self.p.binding_kind(def), Some(DefsKind::Const | DefsKind::Static)))
    }

    fn call(&mut self, e: ExprId, callee: ExprId, args: &[ExprId], span: Span, expected: Option<Ty>) -> Ty {
        let p = self.p;
        // A callee that names a local (or is not a path at all)
        // is a value call: closures and Fn-bound parameters.
        let is_value = match p.ast.expr(callee) {
            Expr::Path(segs) if segs.len() == 1 => {
                self.lookup(segs[0].name, self.span(callee).ctxt).is_some() || (!segs[0].has_args() && self.value_item_callee(segs[0].name))
            }
            Expr::Path(_) | Expr::QPath { .. } => false,
            _ => true,
        };
        if is_value {
            return self.value_call(e, callee, args, span);
        }
        // `std::mem::drop(value)`: move the value and drop it now.
        // A user fn or body item named `drop` shadows the prelude
        // name, so the one-segment form checks those first.
        if let Expr::Path(segs) = p.ast.expr(callee) {
            let names: Vec<&str> = segs.iter().map(|s| self.name(s.name)).collect();
            let qualified = matches!(names.as_slice(), ["std" | "core", "mem", "drop"] | ["mem", "drop"]);
            let bare = names.as_slice() == ["drop"]
                && self.binding_fn(segs[0].name).is_none()
                && self.body_item_of(segs[0].name).is_none();
            if qualified || bare {
                if args.len() != 1 {
                    self.err("L0105", span, "this function takes 1 argument but a different number was given", "Pass exactly one value.");
                    for &a in args {
                        self.expr(a, None);
                    }
                    return ERROR;
                }
                // `drop::<T>(x)`: x must have type T (rustc E0308).
                if segs.last().is_some_and(|s| s.has_args()) {
                    let t = self.callee_turbo_ty(callee, span);
                    self.check_args(&[t], args, span);
                } else {
                    self.expr(args[0], None);
                }
                self.reject_unsized_value(args[0]);
                self.set_res(e, Res::Builtin(Builtin::MemDrop));
                return UNIT;
            }
        }
        if let Some(align) = self.layout_of_val_callee(callee) {
            return self.layout_of_val(e, args, align, span);
        }
        // `Type::from_iter(arg)` by path (check/iter.rs, fx-fromiter).
        if let Some(t) = self.from_iter_call(e, callee, args, span, expected) {
            return t;
        }
        // The Self type a type-relative builtin call writes (an alias's
        // type, `<T>::`, or a turbofish on the type), which the builtin's
        // signature must agree with (check/alias_path.rs).
        let mut written_self: Option<Ty> = None;
        let res = match p.ast.expr(callee) {
            Expr::Path(segs) if segs.len() == 1 => {
                let name = segs[0].name;
                match self.body_item_of(name) {
                    _ if let Some(a) = self.local_ctor_of(name) && p.adt(a).variants[0].shape == VariantShape::Tuple => Res::Variant(a, 0),
                    Some(crate::check::collect::BodyItem::Fn(f)) => Res::Fn(f),
                    _ => match self.binding_fn(name) {
                        Some(f) => Res::Fn(f),
                        None if name == p.known.Some => Res::OptSome,
                        None if name == p.known.Ok => Res::ResOk,
                        None if name == p.known.Err => Res::ResErr,
                        // The prelude re-exports `core::mem::drop` by
                        // this plain name (2024 prelude).
                        None if self.name(name) == "drop" => Res::Builtin(Builtin::MemDrop),
                        None if matches!(self.name(name), "size_of" | "align_of") && !segs[0].type_args().is_empty() => {
                            let align = self.name(name) == "align_of";
                            self.layout_query(&segs[0], align, span)
                        }
                        None => match self.tuple_struct_ctor(name) {
                            Some(a) => Res::Variant(a, 0),
                            None => {
                                let cs = self.span(callee);
                                self.err(
                                    "L0101",
                                    cs,
                                    format!("cannot find function `{}`", self.name(name)),
                                    "Check the spelling, or define the function.",
                                );
                                for &a in args {
                                    self.expr(a, None);
                                }
                                return ERROR;
                            }
                        },
                    },
                }
            }
            Expr::QPath { self_ty, trait_path, segs } => 'qpath: {
                if segs.len() == 1 {
                    let base = self.resolve_written(*self_ty);
                    // `<Vec<u8>>::new()`: a builtin type's own items first,
                    // then the traits, as for `Alias::new()`.
                    if trait_path.is_empty()
                        && let Some(r) = self.builtin_type_item(base, &segs[0], span)
                    {
                        written_self = Some(base);
                        break 'qpath r;
                    }
                    // `<[u8]>::len(s)`: a slice's builtin method by path.
                    if trait_path.is_empty()
                        && let base_r = self.resolve(base)
                        && matches!(self.kind(base_r), TyKind::Slice(_))
                        && let Some((b, ..)) = self.prim_assoc_sig(base_r, segs[0].name, &[])
                    {
                        break 'qpath Res::PrimAssoc { b, self_ty: base_r, name: segs[0].name };
                    }
                    let hint = if trait_path.is_empty() {
                        None
                    } else {
                        let tref = ast::TraitRefExpr { path: trait_path.clone() };
                        match self.written_trait_ref(base, &tref, span) {
                            Ok(tr) => Some(tr),
                            Err(d) => {
                                self.errs.push(d);
                                for &a in args {
                                    self.expr(a, None);
                                }
                                return ERROR;
                            }
                        }
                    };
                    if let Some(t) = self.assoc_call(e, callee, base, hint, segs[0].name, args, span) {
                        return t;
                    }
                    // A builtin Self's std trait item (`<Vec<u8> as
                    // Borrow<[u8]>>::borrow`), as for `Alias::new()`.
                    if let Some(t) = self.std_trait_assoc_call(e, callee, base, segs[0].name, args, span) {
                        return t;
                    }
                    // The written trait ref with no impl fn behind it
                    // (`<T as Clone>::clone(t)` at `T = i32`), or with no
                    // trait written, the one trait in scope whose item it
                    // is and that holds for the type (`<&T>::clone(&t)`).
                    if let Some(tr) = hint.or_else(|| self.unique_item_trait(base, segs[0].name))
                        && let Some(t) = self.trait_ref_call(e, tr, segs[0].name, args, span)
                    {
                        return t;
                    }
                }
                for &a in args {
                    self.expr(a, None);
                }
                self.err("L0101", span, "cannot find the associated function", "Check the trait and the name.");
                return ERROR;
            }
            Expr::Path(segs) => 'path: {
                // `Rune::from(c)` through `type Rune = i32` is `i32::from(c)`.
                let prim;
                let segs = match self.primitive_alias_segs(segs, self.span(callee)) {
                    Some(c) => {
                        prim = c;
                        &prim[..]
                    }
                    None => segs,
                };
                // `T::assoc_fn(..)` on a type parameter, or `Self::f(..)`
                // in a trait default body (Self is the trait's param):
                // the trait comes from the bounds in scope here.
                if let Some(base) = self.param_path_base(segs) {
                    // In an instance, the template's bound fixes the trait
                    // args (`U: From<u8>` at U = u16 calls `<u16 as
                    // From<u8>>::from`); a builtin Self's own impls can be
                    // ambiguous (`u16: From<{integer}>`).
                    let hint = self.instance_bound_ref(segs[1].name, base);
                    if let Some(t) = self.assoc_call(e, callee, base, hint, segs[1].name, args, span) {
                        return t;
                    }
                    // A std trait's item at a builtin Self (`T::clone(t)`
                    // at `T = i32`) has no impl fn: the deferred trait
                    // path picks the builtin, as for `Clone::clone(t)`.
                    if let Some(tr) = hint
                        && let Some(t) = self.trait_ref_call(e, tr, segs[1].name, args, span)
                    {
                        return t;
                    }
                }
                // `Trait::method(self_arg, ..)`: the trait name
                // heads the path and the first argument is the
                // receiver. The Self type comes from that
                // argument (trial-checked, then rechecked by the
                // assoc call itself).
                if !args.is_empty()
                    && let Some((tdef, method_def, tseg)) = self.trait_path_head(segs)
                    && let Some(rec) = p.gx.index.trait_record(tdef).cloned()
                    // A method with no `self` (`From::from`) takes
                    // no receiver: its Self is the output type,
                    // never the first argument's. The deferred
                    // trait path below types those instead.
                    && !p
                        .gx
                        .trait_methods
                        .get(&method_def)
                        .map(|t| t.self_kind)
                        .or_else(|| p.gx.lang_method_sigs.get(&method_def).map(|s| s.self_kind))
                        .is_some_and(|k| k.is_none())
                {
                    {
                        let mname = segs[segs.len() - 1].name;
                        let snap = self.snapshot_vars();
                        let obl_len = self.obl_len();
                        let sites_len = self.generic_sites.len();
                        let err_len = self.errs.len();
                        // The place steps the trial records (`&**w`
                        // through a user `Deref`, a user `Index`) are
                        // recorded again by the recheck; kept, a step
                        // would run twice (one `deref` call on the
                        // other's result).
                        let place_lens =
                            (self.out.deref_recv.len(), self.out.deref_coerce.len(), self.out.index_recv.len(), self.deref_sites.len());
                        let at = self.expr(args[0], None);
                        let at = self.deep(at);
                        self.rollback_vars(snap);
                        self.obl_truncate(obl_len);
                        self.generic_sites.truncate(sites_len);
                        self.errs.truncate(err_len);
                        self.out.deref_recv.truncate(place_lens.0);
                        self.out.deref_coerce.truncate(place_lens.1);
                        self.out.index_recv.truncate(place_lens.2);
                        self.deref_sites.truncate(place_lens.3);
                        // An argument of no known type yet (an eta
                        // closure's param, `|a, b| PartialEq::eq(a, b)`)
                        // says nothing about Self: the deferred trait
                        // path below types the call, Self a fresh var.
                        let unknown = matches!(self.tys.kind(at), TyKind::Infer(v) if !v.is_int() && !v.is_float());
                        let mut bases = if unknown { Vec::new() } else { vec![at] };
                        if let TyKind::Ref(_, _, inner) = self.tys.kind(at) {
                            bases.insert(0, self.deep(inner));
                        }
                        for base in bases {
                            // Written trait args (`Tr::<u8>::m(x)`) fix the
                            // trait ref, as in `<_ as Tr<u8>>::m(x)`.
                            let hint = if matches!(segs[tseg].args, ast::GenericArgs::Angle(_)) {
                                let tref = ast::TraitRefExpr { path: segs[..=tseg].to_vec() };
                                match self.written_trait_ref(base, &tref, span) {
                                    Ok(tr) => tr,
                                    Err(d) => {
                                        self.errs.push(d);
                                        for &a in args {
                                            self.expr(a, None);
                                        }
                                        return ERROR;
                                    }
                                }
                            } else {
                                let mut tr_args: Vec<GenericArg> = vec![GenericArg::Ty(base)];
                                for _ in 1..rec.generics.params.len() {
                                    tr_args.push(GenericArg::Ty(self.new_var(false)));
                                }
                                let args_id = self.tys.intern_args(&tr_args);
                                TraitRef { def: tdef, args: args_id, bindings: EMPTY_BINDINGS }
                            };
                            if let Some(t) = self.assoc_call(e, callee, base, Some(hint), mname, args, span) {
                                return t;
                            }
                        }
                        if !unknown && matches!(segs[tseg].args, ast::GenericArgs::Angle(_)) {
                            let shown = match self.tys.kind(at) {
                                TyKind::Ref(_, _, inner) => self.deep(inner),
                                _ => at,
                            };
                            let (tr_name, tn) = (self.trait_name(tdef), self.tn(shown));
                            self.err(
                                "L0612",
                                span,
                                format!("no impl of `{tr_name}` with these trait arguments for `{tn}`"),
                                "Change the trait arguments, or add the impl.",
                            );
                            for &a in args {
                                self.expr(a, None);
                            }
                            return ERROR;
                        }
                    }
                }
                // `V4::new()` through `type V4 = Vec<u8>`: the builtin's
                // own item at the alias's type, else a trait's
                // (`FxHashMap::default()`), as for `<Vec<u8>>::new()`.
                if let Some(base) = self.alias_path_target(segs, self.span(callee), true) {
                    if base != ERROR && !segs[1].has_args() {
                        if let Some(r) = self.builtin_type_item(base, &segs[1], span) {
                            written_self = Some(base);
                            break 'path r;
                        }
                        if let Some(t) = self.std_trait_assoc_call(e, callee, base, segs[1].name, args, span) {
                            return t;
                        }
                        // A builtin method by the alias's path
                        // (`FxHashMap::clone(&m)`, check/ufcs.rs).
                        let mark = self.errs.len();
                        if let Some(t) = self.builtin_method_by_path(e, segs, Some(base), self.span(callee), args, span, expected) {
                            return t;
                        }
                        self.errs.truncate(mark);
                        let (item, tn) = (self.name(segs[1].name).to_string(), self.tn(base));
                        self.err("L0104", span, format!("no function or associated item `{item}` for `{tn}`"), "Check the name.");
                    } else if base != ERROR {
                        self.err("L0107", span, "this associated item takes no generic arguments", "Write the type's arguments on the alias.");
                    }
                    for &a in args {
                        self.expr(a, None);
                    }
                    return ERROR;
                }
                // `M::from(x)`: an Adt with no variant or inherent fn of
                // that name finds it in the traits in scope (rustc
                // probes inherent items first, then traits). A call the
                // template check resolved through a trait keeps that
                // trait (`Self::mk()` in a trait default body).
                if segs.len() == 2
                    && !(segs[1].name == p.known.clone
                        && [p.known.String, p.known.Vec, p.known.Box, p.known.Rc].contains(&segs[0].name))
                    && let Some(base) = self.trait_assoc_base(segs, self.replay_pick(e).is_some(), span)
                    && let Some(t) = self.assoc_call(e, callee, base, None, segs[1].name, args, span)
                {
                    return t;
                }
                // `Into::into(x)` and kin the assoc paths above had
                // no answer for: typed by the trait method's
                // signature and deferred (check/traitpath.rs).
                if let Some(t) = self.trait_path_call(e, callee, segs, args, span) {
                    return t;
                }
                let cs = self.span(callee);
                let mark = self.errs.len();
                let r = if self.is_type_id_of(segs) {
                    self.type_id_of_path(e, segs.last().unwrap(), cs)
                } else if self.is_type_name_path(segs) {
                    self.type_name_path(e, segs.last().unwrap(), cs)
                } else {
                    self.resolve_assoc(segs, cs)
                };
                match r {
                    Some(r) => r,
                    None => {
                        // `String::default()`: no builtin item of that
                        // name, so a std trait's (as for aliases above).
                        if self.errs[mark..].iter().all(|d| matches!(d.code, "L0101" | "L0104"))
                            && let Some(base) = self
                                .builtin_path_base(segs, cs, expected)
                                .or_else(|| if segs.len() == 2 { self.prim_ty_by_name(segs[0].name) } else { None })
                        {
                            let saved = self.errs.split_off(mark);
                            let name = segs[segs.len() - 1].name;
                            if let Some(t) = self.std_trait_assoc_call(e, callee, base, name, args, span) {
                                return t;
                            }
                            // `i32::cmp(a, b)`, `String::eq(a, b)`: the one
                            // trait in scope with the item that holds for
                            // the builtin, deferred like `Ord::cmp(a, b)`.
                            if let Some(tr) = self.unique_item_trait(base, name)
                                && let Some(t) = self.trait_ref_call(e, tr, name, args, span)
                            {
                                return t;
                            }
                            self.errs.extend(saved);
                        }
                        // `Vec::len(&v)`, `std::thread::Builder::spawn(b, f)`:
                        // a builtin method by path (check/ufcs.rs). The
                        // builtin type may answer "not implemented" for
                        // the item (L0640), as the sync types do.
                        let n = segs.len();
                        if n >= 2
                            && !segs[n - 1].has_args()
                            && self.errs[mark..].iter().all(|d| matches!(d.code, "L0101" | "L0104" | "L0640"))
                        {
                            // With no written type the receiver must be the
                            // builtin the path names (`builtin_names_path`).
                            let written = self.builtin_path_base(segs, cs, None);
                            let saved = self.errs.split_off(mark);
                            if let Some(t) = self.builtin_method_by_path(e, segs, written, cs, args, span, expected) {
                                return t;
                            }
                            self.errs.extend(saved);
                        }
                        for &a in args {
                            self.expr(a, None);
                        }
                        return ERROR;
                    }
                }
            }
            _ => return self.value_call(e, callee, args, span),
        };
        // An indirect call's callee is a value expression with a
        // resolution of its own (a local, an index): keep it.
        if res != Res::Indirect {
            self.set_res(callee, res);
        }
        self.set_res(e, res);
        if res == Res::OptSome {
            if args.len() != 1 {
                self.err("L0105", span, "`Some` takes one argument", "Write `Some(value)`.");
                return ERROR;
            }
            // Turbofish (`Some::<u8>(..)`, `Option::<u8>::Some(..)`) fixes
            // the element type; the argument is a coercion site for it.
            let turbo = match p.ast.expr(callee) {
                Expr::Path(segs) => self.builtin_ctor_args(segs, 1, span),
                _ => written_self.map(|t| self.builtin_self_args(t, 1)),
            };
            if let Some(a) = turbo {
                self.expect_expr(args[0], a[0]);
                return self.tys.mk_option(a[0]);
            }
            // Under an `Option<T>` expectation the argument is a
            // coercion site for `T`, as rustc's expected inputs
            // make it: this reaches dyn unsizing and the sites
            // inside a tuple or struct argument alike
            // (`Some((1, &[true]))` at `Option<(u8, &[bool])>`).
            let elem = expected.and_then(|t| self.tys.option_elem(self.resolve(t)));
            if let Some(want) = elem {
                self.expect_expr(args[0], want);
                return self.tys.mk_option(want);
            }
            let t = self.expr(args[0], None);
            return self.tys.mk_option(t);
        }
        if res == Res::ResOk || res == Res::ResErr {
            let who = if res == Res::ResOk { "Ok" } else { "Err" };
            if args.len() != 1 {
                self.err("L0105", span, format!("`{who}` takes one argument"), format!("Write `{who}(value)`."));
                return ERROR;
            }
            // Turbofish on the constructor or on `Result` itself pins
            // both sides (`_` is a fresh var); otherwise the other side
            // is a fresh var.
            let turbo: Vec<Ty> = match p.ast.expr(callee) {
                Expr::Path(segs) => self.builtin_ctor_args(segs, 2, span).unwrap_or_default(),
                _ => written_self.map(|t| self.builtin_self_args(t, 2)).unwrap_or_default(),
            };
            // Written args fix the side: the argument is a coercion site
            // for it (rustc E0308 for `Result::<u16, u8>::Ok(1u8)`).
            if turbo.len() == 2 {
                self.expect_expr(args[0], if res == Res::ResOk { turbo[0] } else { turbo[1] });
                return self.tys.mk_result(turbo[0], turbo[1]);
            }
            // Under a `Result<Ok, Err>` expectation the argument is
            // a coercion site for its side, as for `Some`.
            if let Some((ok, err)) = expected.and_then(|t| self.tys.result_args(self.resolve(t))) {
                self.expect_expr(args[0], if res == Res::ResOk { ok } else { err });
                return self.tys.mk_result(ok, err);
            }
            let other = self.new_var(false);
            let t = self.expr(args[0], None);
            return if res == Res::ResOk { self.tys.mk_result(t, other) } else { self.tys.mk_result(other, t) };
        }
        match res {
            Res::ConstUsize(_) => {
                if !args.is_empty() {
                    self.err("L0105", span, "this function takes no arguments", "Write `size_of::<Type>()`.");
                }
                USIZE
            }
            Res::Any { op, .. } => {
                if !args.is_empty() {
                    self.err("L0105", span, "this function takes no arguments", "Write `TypeId::of::<Type>()`.");
                }
                if op == any::AnyOp::TypeName { REF_STR } else { generics::type_id_ty(&mut self.tys) }
            }
            Res::ConstBool(_) => {
                if !args.is_empty() {
                    self.err("L0105", span, "this function takes no arguments", "Write `needs_drop::<Type>()`.");
                }
                BOOL
            }
            Res::Fn(f) => {
                // Path calls such as `Type::method(x)` pass `self` explicitly, so all params apply.
                if let Some(Some(tmpl)) = p.gx.fn_templates.get(f.0 as usize).cloned() {
                    let explicit = self.explicit_path_args(callee, f);
                    self.check_path_turbofish(callee, f, &tmpl.generics, span);
                    let (mut params, ret, inst_args) = self.instantiate_template(e, f, &tmpl.generics.clone(), &explicit, span);
                    self.unify_written_self(callee, f, &inst_args, span);
                    self.normalize_params(&mut params, span);
                    self.expected_output_first(ret, expected, args);
                    self.check_args(&params, args, span);
                    return self.normalize_use(ret, span);
                }
                let (params, ret) = match p.sig_of(&mut self.out.reads, p.def_id(f)) {
                    SigOf::Fn(info) => (info.params.clone(), p.ret_view(f)),
                    _ => return ERROR,
                };
                let ret = self.callee_ret(ret);
                self.unify_written_self(callee, f, &[], span);
                self.check_args(&params, args, span);
                ret
            }
            Res::Variant(a, v) => {
                if !p.adt(a).is_enum {
                    self.check_ctor_vis(a, span);
                }
                self.check_ne_ctor(a, v, span);
                let adef = p.def_of_adt(a);
                let _ = p.sig_of(&mut self.out.reads, adef);
                let variant = &p.adt(a).variants[v as usize];
                if variant.shape != VariantShape::Tuple {
                    self.err("L0114", span, "this variant is not a tuple variant", "Use `Type::Variant` or `Type::Variant { .. }`.");
                    return ERROR;
                }
                let n = p.gx.adt_generics[a.0 as usize].params.len();
                if n == 0 {
                    let params: Vec<Ty> = variant.fields.iter().map(|f| f.ty).collect();
                    self.check_args(&params, args, span);
                    self.tys.adt_ty(a)
                } else {
                    let gen_args: Vec<GenericArg> = match p.ast.expr(callee) {
                        Expr::Path(segs) => self.value_path_args(a, segs, span),
                        _ => self.fresh_args(&p.gx.adt_generics[a.0 as usize].clone()),
                    };
                    // The expected type fixes the params first (rustc's
                    // expected inputs), so a closure or a reference
                    // argument sees its field's type (`S<u8>(|x| ..)`).
                    if let Some(want) = expected.map(|t| self.resolve(t))
                        && self.tys.adt_parts(want).is_some_and(|(d, _)| d == adef)
                    {
                        let snap = self.snapshot_vars();
                        let mine = self.tys.mk_adt(adef, &gen_args);
                        if !self.unify(mine, want) {
                            self.rollback_vars(snap);
                        }
                    }
                    let params: Vec<Ty> = variant.fields.iter().map(|f| self.subst_norm(f.ty, &gen_args, span)).collect();
                    self.check_args(&params, args, span);
                    // Forming the type owes its parameter bounds.
                    let preds = p.gx.adt_generics[a.0 as usize].predicates.clone();
                    if !preds.is_empty() {
                        self.push_predicates(&preds, &gen_args, span);
                    }
                    self.tys.mk_adt(adef, &gen_args)
                }
            }
            Res::Indirect => {
                let ct = self.out.expr_ty[self.ei(callee)];
                match self.callable_sig(ct) {
                    Some((params, ret)) => {
                        self.check_args(&params, args, span);
                        ret
                    }
                    None => ERROR,
                }
            }
            Res::PrimAssoc { self_ty, name, .. } => {
                // A primitive builtin method called by path
                // (`u8::is_ascii_digit(&b)`; TRIAGE T12): the
                // receiver is the first argument, checked against
                // the method table's own signature. The str search
                // methods take std's `Pattern` in the second
                // argument, as in the method form.
                match self.prim_assoc_sig(self_ty, name, &[]) {
                    Some((b, params, ret, _)) if b == Builtin::PrimFromCast => {
                        // `u64::from(x)` called by path: the one
                        // argument converts, as `std_from` answers
                        // (check/convert.rs), with a literal source
                        // narrowed like an owner's `from`.
                        self.check_args(&params, args, span);
                        if params.len() == 1 && args.len() == 1 {
                            let src = self.deep(params[0]);
                            if !self.has_error_kind(src)
                                && !matches!(self.kind(src), TyKind::Infer(_))
                                && !Self::numeric_from_ok(self.kind(src), self.kind(self_ty))
                            {
                                let (dn, sn) = (self.tn(self_ty), self.tn(src));
                                self.err(
                                    "L0612",
                                    span,
                                    format!("the trait bound `{dn}: From<{sn}>` is not satisfied"),
                                    "Check the conversion: `From` between primitives only widens.",
                                );
                            }
                        }
                        ret
                    }
                    Some((b, params, ret, _)) => {
                        if matches!(
                            b,
                            Builtin::StrContains
                                | Builtin::StrFind
                                | Builtin::StrRfind
                                | Builtin::StrStartsWith
                                | Builtin::StrEndsWith
                                | Builtin::StrStripPrefix
                                | Builtin::StrStripSuffix
                                | Builtin::StrReplace
                        ) && params.len() >= 2
                            && args.len() == params.len()
                        {
                            self.check_args(&params[..1], &args[..1], span);
                            self.check_str_pattern_args(&params[1..], &args[1..], span);
                        } else {
                            self.check_args(&params, args, span);
                        }
                        ret
                    }
                    None => ERROR,
                }
            }
            Res::Builtin(b) => {
                if self.type_item_has_args(callee) {
                    self.err("L0107", span, "this associated function takes no generic arguments", "Write the type's arguments on the type: `Vec::<u8>::new()`.");
                    for &a in args {
                        self.expr(a, None);
                    }
                    return ERROR;
                }
                if written_self.is_none()
                    && let Expr::Path(segs) = p.ast.expr(callee)
                {
                    written_self = self.written_builtin_self(segs, span);
                }
                // rustc's expected inputs: `Box::new(|x| ..)` (or `Rc::new`)
                // where `Box<dyn Fn(A) -> R>` is expected checks the
                // argument against the dyn type, so a closure takes that
                // signature; the box of its own type then unsizes at the
                // caller's coercion.
                let arc_new = b == Builtin::Sync(sync::SyncOp::ArcNew);
                if (matches!(b, Builtin::BoxNew | Builtin::RcNew) || arc_new)
                    && args.len() == 1
                    && written_self.is_none()
                    && let Some(want) = expected.map(|t| self.resolve(t))
                    && self.tys.builtin_of(want) == Some(match b {
                        Builtin::BoxNew => BuiltinTy::Boxed,
                        Builtin::RcNew => BuiltinTy::Rc,
                        _ => BuiltinTy::Sync(crate::ty::sync::SyncTy::Arc),
                    })
                    && let Some(inner) = if b == Builtin::BoxNew { self.tys.boxed_elem(want) } else { self.tys.rc_elem(want) }
                    && matches!(self.kind(inner), TyKind::Dyn(..))
                {
                    let at = self.expr(args[0], Some(inner));
                    return match b {
                        Builtin::BoxNew => self.tys.mk_boxed(at),
                        Builtin::RcNew => self.tys.mk_rc(at),
                        _ => crate::ty::sync::sync_ty(&mut self.tys, crate::ty::sync::SyncTy::Arc, &[at]),
                    };
                }
                let (params, ret): (Vec<Ty>, Ty) = match b {
                    Builtin::Sync(op) => self.sync_call_sig(op, callee, span),
                    b if crate::check::hashmap::is_hash_ctor(b) => match self.hash_ctor_sig(b, callee, span) {
                        Some(sig) if b == Builtin::HashFromArray => self.hash_from_array_sig(sig.1, args, span),
                        Some(sig) => sig,
                        None => (vec![], ERROR),
                    },
                    Builtin::Clone => {
                        // The associated form `Type::clone(&x)`: the
                        // argument fixes the type, within the written
                        // type's shape (`Rc::clone(&&rc)` derefs to the
                        // `Rc`, never clones the reference).
                        let written = match p.ast.expr(callee) {
                            Expr::Path(segs) if segs.len() >= 2 => {
                                let cs = self.span(callee);
                                // `Arc::clone` and `sync::Weak::clone` pick
                                // this builtin on a std path only (`sync_assoc`;
                                // `rc::Weak::clone` is no builtin).
                                let sync = match self.name(segs[segs.len() - 2].name) {
                                    "Arc" => Some(crate::ty::sync::SyncTy::Arc),
                                    "Weak" => Some(crate::ty::sync::SyncTy::ArcWeak),
                                    _ => None,
                                };
                                match sync {
                                    Some(k) => {
                                        let v = self.new_var(false);
                                        Some(crate::ty::sync::sync_ty(&mut self.tys, k, &[v]))
                                    }
                                    None => self.builtin_path_base(segs, cs, None),
                                }
                            }
                            _ => None,
                        };
                        let base = written.unwrap_or_else(|| self.new_var(false));
                        self.clone_path_unique(base, span);
                        self.deferred_clone.push((base, span));
                        let r = self.tys.mk_ref(false, base);
                        (vec![r], base)
                    }
                    Builtin::StringNew => (vec![], STRING),
                    Builtin::StringAsStr => (vec![self.tys.mk_ref(false, STRING)], REF_STR),
                    // `Cow::from(x)` (the String and Vec forms pick it in
                    // their own arms): the expected Cow if one is written,
                    // else the argument picks the Cow: the str and slice
                    // shapes first (their specific std impls), then the
                    // two generic impls (`&B` borrows, a sized value is
                    // its own Owned). Forming the Cow owes `B: ToOwned`.
                    Builtin::ConvInto => {
                        let at = if args.len() == 1 { self.expr(args[0], None) } else { ERROR };
                        let at = self.deep(at);
                        let (inner, m) = match self.kind(at) {
                            TyKind::Ref(_, m, i) => (i, Some(m)),
                            _ => (at, None),
                        };
                        let mut cands: Vec<Ty> = Vec::new();
                        let expected_b = match expected {
                            Some(t) => {
                                let t = self.deep(t);
                                crate::check::collect::cow_arg(&self.tys, t)
                            }
                            None => None,
                        };
                        if let Some(b) = expected_b {
                            cands.push(b);
                        }
                        let shaped = match self.kind(inner) {
                            TyKind::Str if m.is_some() => Some(STR),
                            TyKind::Slice(_) if m.is_some() => Some(inner),
                            _ if self.tys.is_string_ty(inner) => Some(STR),
                            _ => self.tys.vec_elem(inner).map(|e| self.tys.intern(TyKind::Slice(e))),
                        };
                        if let Some(b) = shaped
                            && !cands.contains(&b)
                        {
                            cands.push(b);
                        }
                        if m.is_some_and(|mm| !mm.is_mut()) && !cands.contains(&inner) {
                            cands.push(inner);
                        }
                        if m.is_none() && !cands.contains(&at) {
                            cands.push(at);
                        }
                        let mut picked = None;
                        for b in cands {
                            let d = self.tys.mk_adt(generics::cow_def(), &[GenericArg::Ty(b)]);
                            if let Some(a) = self.std_from_arg(d, at) {
                                picked = Some((d, a, b));
                                break;
                            }
                        }
                        match picked {
                            Some((d, a, b)) => {
                                if let Some(idx) = p.gx.adt_info.iter().position(|&(def, _)| def == generics::cow_def()) {
                                    let preds = p.gx.adt_generics[idx].predicates.clone();
                                    if !preds.is_empty() {
                                        self.push_predicates(&preds, &[GenericArg::Ty(b)], span);
                                    }
                                }
                                (vec![a], d)
                            }
                            None => {
                                let tn = self.tn(at);
                                if !matches!(self.kind(at), TyKind::Error) {
                                    self.err(
                                        "L0612",
                                        span,
                                        format!("`Cow` has no `From<{tn}>` impl that lust supports"),
                                        "Pass `&B` or `<B as ToOwned>::Owned` for some `B: ToOwned`, such as `&str` or `String`.",
                                    );
                                }
                                (vec![at], ERROR)
                            }
                        }
                    }
                    Builtin::StringFrom => {
                        // The forms lust takes: `&str` (and `&String`
                        // through deref), a String by value, and a
                        // char. Picked from the argument's type;
                        // `check_args` then checks it as itself.
                        let at = if args.len() == 1 { self.expr(args[0], None) } else { ERROR };
                        let at = self.resolve(at);
                        if at == CHAR || at == STRING {
                            (vec![at], STRING)
                        } else if let Some(at) = self.std_from_arg(STRING, at) {
                            // std's other forms (`String::from(cow)`): the
                            // conversion builtin (check/convert.rs).
                            self.set_res(callee, Res::Builtin(Builtin::ConvInto));
                            self.set_res(e, Res::Builtin(Builtin::ConvInto));
                            (vec![at], STRING)
                        } else {
                            // rustc picks the `From` impl by the argument's
                            // own type, with no deref coercion: `&str`,
                            // `&mut str`, and `&String` only (`&&str`,
                            // `&Box<str>`, `&mut String` are E0277).
                            let exact = match self.kind(at) {
                                TyKind::Ref(_, m, inner) => {
                                    let inner = self.resolve(inner);
                                    inner == STR || (inner == STRING && !m.is_mut()) || matches!(self.kind(inner), TyKind::Infer(v) if !v.is_int() && !v.is_float())
                                }
                                TyKind::Infer(v) => !v.is_int() && !v.is_float(),
                                TyKind::Error => true,
                                _ => false,
                            };
                            if !exact {
                                let tn = self.tn(at);
                                self.err(
                                    "L0612",
                                    span,
                                    format!("no impl of `From<{tn}>` for `String`"),
                                    "Pass a `&str`, a `&String`, a `String`, or a `char`.",
                                );
                            }
                            (vec![REF_STR], STRING)
                        }
                    }
                    Builtin::StringWithCapacity => (vec![USIZE], STRING),
                    Builtin::OwnFrom(k) => self.own_from_sig(k, callee, e, args, written_self.or(expected), span),
                    Builtin::EnvArgs => (vec![], ARGS),
                    Builtin::LocationCaller => {
                        let l = self.tys.intern(TyKind::Adt(generics::location_def(), EMPTY_ARGS));
                        (vec![], self.tys.mk_ref(false, l))
                    }
                    Builtin::F64FromBits => (vec![int(IntTy::U64)], self.tys.float_ty(FloatTy::F64)),
                    Builtin::F32FromBits => (vec![int(IntTy::U32)], self.tys.float_ty(FloatTy::F32)),
                    Builtin::CharFromU32 => (vec![int(IntTy::U32)], self.tys.mk_option(CHAR)),
                    Builtin::MaybeUninitUninit | Builtin::MaybeUninitZeroed | Builtin::MaybeUninitNew => {
                        // `MaybeUninit::uninit()` and kin (TRIAGE
                        // T5): the element from the written type.
                        let inner = match p.ast.expr(callee) {
                            Expr::Path(segs) => match self.builtin_ctor_args(segs, 1, span) {
                                Some(a) => a[0],
                                None => self.new_var(false),
                            },
                            _ => self.new_var(false),
                        };
                        let mu = generics::maybe_uninit_ty(&mut self.tys, inner);
                        if b == Builtin::MaybeUninitNew {
                            (vec![inner], mu)
                        } else {
                            (vec![], mu)
                        }
                    }
                    Builtin::NonZeroNew => {
                        // `NonZero::new(x)` and `NonZeroU64::new(x)`
                        // (TRIAGE T5): the integer from the alias
                        // name, the written type argument, or the
                        // expected type's element.
                        let inner = match p.ast.expr(callee) {
                            Expr::Path(segs) if segs.len() >= 2 => {
                                let ty_name = segs[segs.len() - 2].name;
                                match self.nonzero_alias_inner(ty_name) {
                                    Some(i) => int(i),
                                    None => match self.builtin_ctor_args(segs, 1, span) {
                                        Some(a) => a[0],
                                        None => self.new_var(false),
                                    },
                                }
                            }
                            _ => self.new_var(false),
                        };
                        let nz = generics::nonzero_ty(&mut self.tys, inner);
                        (vec![inner], self.tys.mk_option(nz))
                    }
                    Builtin::CharFromDigit => (vec![int(IntTy::U32), int(IntTy::U32)], self.tys.mk_option(CHAR)),
                    Builtin::CharIsAlphabeticUnicode
                    | Builtin::CharIsNumericUnicode
                    | Builtin::CharIsAlphanumericUnicode
                    | Builtin::CharIsLowercaseUnicode
                    | Builtin::CharIsUppercaseUnicode
                    | Builtin::CharIsWhitespaceUnicode
                    | Builtin::CharIsControlUnicode => (vec![CHAR], BOOL),
                    Builtin::VecFrom => {
                        // The three forms lust takes: `&[T]` and
                        // `&[T; N]` (clone each element, exact
                        // capacity) and `[T; N]` (move each element).
                        // The argument is checked once here to pick
                        // the form; `check_args` below then checks it
                        // against its own type.
                        let at = if args.len() == 1 { self.expr(args[0], None) } else { ERROR };
                        let at = self.resolve(at);
                        let elem = match self.kind(at) {
                            TyKind::Ref(_, _, inner) => match self.kind(self.resolve(inner)) {
                                TyKind::Slice(e) | TyKind::Array(e, _) => {
                                    self.deferred_clone.push((e, span));
                                    Some(e)
                                }
                                _ => None,
                            },
                            TyKind::Array(e, _) => Some(e),
                            TyKind::Error => Some(ERROR),
                            TyKind::Infer(_) => Some(ERROR),
                            _ => None,
                        };
                        // std's other forms (`Vec::from(string)`, from
                        // `&str`, `Box<[T]>`, `Cow<[T]>`): the conversion
                        // builtin (check/convert.rs).
                        let other = if elem.is_none() {
                            let atd = self.deep(at);
                            let el = if atd == STRING || matches!(self.kind(atd), TyKind::Ref(_, _, s) if s == STR) {
                                Some(int(IntTy::U8))
                            } else {
                                self.tys.boxed_slice_elem(atd).or_else(|| {
                                    crate::check::collect::cow_arg(&self.tys, atd).and_then(|b| match self.kind(b) {
                                        TyKind::Slice(e) => Some(e),
                                        _ => None,
                                    })
                                })
                            };
                            el.map(|el| self.tys.mk_vec(el)).and_then(|dst| self.std_from_arg(dst, atd).map(|a| (dst, a)))
                        } else {
                            None
                        };
                        match (elem, other) {
                            (_, Some((dst, at))) => {
                                self.set_res(callee, Res::Builtin(Builtin::ConvInto));
                                self.set_res(e, Res::Builtin(Builtin::ConvInto));
                                (vec![at], dst)
                            }
                            (Some(e), None) => (vec![at], self.tys.mk_vec(e)),
                            (None, None) => {
                                let tn = self.tn(at);
                                self.err(
                                    "L0110",
                                    span,
                                    format!("`Vec::from` needs a slice, an array, a String, a `&str`, a `Box<[T]>`, or a `Cow<[T]>`, found `{tn}`"),
                                    "Pass `&[T]`, `&[T; N]`, or `[T; N]`.",
                                );
                                (vec![at], ERROR)
                            }
                        }
                    }
                    // The element of these comes from the written Self
                    // type (`unify_builtin_self` below), else inference.
                    Builtin::BoxNew => {
                        let elem = self.new_var(false);
                        (vec![elem], self.tys.mk_boxed(elem))
                    }
                    Builtin::BoxLeak => {
                        let elem = self.new_var(false);
                        let bx = self.tys.mk_boxed(elem);
                        let r = self.tys.mk_ref(true, elem);
                        (vec![bx], r)
                    }
                    // `Box::as_ptr(&b)`, `Box::as_mut_ptr(&mut b)`: the written
                    // name gives the mutability, as for `ptr::from_ref`.
                    Builtin::BoxAsPtr => {
                        let elem = self.new_var(false);
                        self.deferred_raw.push((elem, span, RawUse::Pointee));
                        let m = match p.ast.expr(callee) {
                            Expr::Path(segs) => segs.last().is_some_and(|s| self.name(s.name) == "as_mut_ptr"),
                            _ => false,
                        };
                        if let Some(want) = written_self.take() {
                            let bx = self.tys.mk_boxed(elem);
                            if !self.unify(bx, want) {
                                self.mismatch(span, want, bx);
                            }
                        }
                        let bx = self.tys.mk_boxed(elem);
                        (vec![self.tys.mk_ref(m, bx)], self.tys.intern(TyKind::RawPtr(Mut::from_bool(m), elem)))
                    }
                    // The written Self is `Box<T>` for these two but the
                    // result is `Box<MaybeUninit<T>>`, so the written T
                    // is the element here, not a unify of the result.
                    Builtin::BoxNewUninit | Builtin::BoxNewZeroed => {
                        let elem = self.new_var(false);
                        self.deferred_sized.push((elem, span));
                        if let Some(want) = written_self.take() {
                            let bx = self.tys.mk_boxed(elem);
                            if !self.unify(bx, want) {
                                self.mismatch(span, want, bx);
                            }
                        }
                        let mu = generics::maybe_uninit_ty(&mut self.tys, elem);
                        (vec![], self.tys.mk_boxed(mu))
                    }
                    // The same for the `Rc`/`Arc` ones. The slice form
                    // is on `impl<T> Box<[T]>`: the written Self is
                    // `Box<[T]>` (`Box::<u8>::new_uninit_slice` is E0599).
                    Builtin::BoxNewUninitSlice
                    | Builtin::RcNewUninit
                    | Builtin::ArcNewUninit => {
                        let elem = self.new_var(false);
                        self.deferred_sized.push((elem, span));
                        let owner = |this: &mut Self, t: Ty| match b {
                            Builtin::BoxNewUninitSlice => this.tys.mk_boxed(t),
                            Builtin::RcNewUninit => this.tys.mk_rc(t),
                            _ => crate::ty::sync::sync_ty(&mut this.tys, crate::ty::sync::SyncTy::Arc, &[t]),
                        };
                        let slice = b == Builtin::BoxNewUninitSlice;
                        if let Some(want) = written_self.take() {
                            let written = if slice { self.tys.intern(TyKind::Slice(elem)) } else { elem };
                            let o = owner(self, written);
                            if !self.unify(o, want) {
                                let tn = self.tn(want);
                                let item = if slice { "new_uninit_slice" } else { "new_uninit" };
                                self.err("L0104", span, format!("no associated function `{item}` for `{tn}`"), "Check the type's arguments.");
                            }
                        }
                        let mu = generics::maybe_uninit_ty(&mut self.tys, elem);
                        let pointee = if slice { self.tys.intern(TyKind::Slice(mu)) } else { mu };
                        (if slice { vec![USIZE] } else { vec![] }, owner(self, pointee))
                    }
                    // `impl<T> Box<MaybeUninit<T>>`: the written Self is
                    // the first param's type, not the result's.
                    Builtin::BoxWrite => {
                        let elem = self.new_var(false);
                        self.deferred_sized.push((elem, span));
                        let mu = generics::maybe_uninit_ty(&mut self.tys, elem);
                        let bx = self.tys.mk_boxed(mu);
                        if let Some(want) = written_self.take()
                            && !self.unify(bx, want)
                        {
                            let tn = self.tn(want);
                            self.err("L0104", span, format!("no associated function `write` for `{tn}`"), "`Box::write` takes a `Box<MaybeUninit<T>>`.");
                        }
                        (vec![bx, elem], self.tys.mk_boxed(elem))
                    }
                    Builtin::RcNew => {
                        let elem = self.new_var(false);
                        (vec![elem], self.tys.mk_rc(elem))
                    }
                    Builtin::RcStrongCount | Builtin::RcWeakCount => {
                        let elem = self.new_var(false);
                        let rc = self.tys.mk_rc(elem);
                        let r = self.tys.mk_ref(false, rc);
                        (vec![r], USIZE)
                    }
                    Builtin::RcMakeMut => {
                        let elem = self.new_var(false);
                        self.deferred_make_mut.push((elem, span, true));
                        let rc = self.tys.mk_rc(elem);
                        let rm = self.tys.mk_ref(true, rc);
                        let r = self.tys.mk_ref(true, elem);
                        (vec![rm], r)
                    }
                    Builtin::RcGetMut => {
                        let elem = self.new_var(false);
                        self.deferred_make_mut.push((elem, span, false));
                        let rc = self.tys.mk_rc(elem);
                        let rm = self.tys.mk_ref(true, rc);
                        let r = self.tys.mk_ref(true, elem);
                        let opt = self.tys.mk_option(r);
                        (vec![rm], opt)
                    }
                    Builtin::RcDowngrade | Builtin::RcNewCyclic | Builtin::RcPtrEq | Builtin::SmartAsPtr | Builtin::WeakNew | Builtin::WeakPtrEq | Builtin::RefCellNew | Builtin::CellNew => {
                        self.cell_call_sig(b, callee)
                    }
                    Builtin::DefaultGlue => match self
                        .cow_default_sig(callee, span)
                        .or_else(|| self.box_default_sig(callee, span))
                        .or_else(|| self.smart_default_sig(callee, span))
                    {
                        Some(sig) => sig,
                        None => self.cell_default_sig(callee, span),
                    },
                    Builtin::ExitCodeFrom => (vec![int(IntTy::U8)], self.tys.exit_code_ty()),
                    Builtin::StringFromUtf8 | Builtin::StrFromUtf8 | Builtin::StringFromUtf8Lossy | Builtin::StringFromUtf16Lossy => self.utf8_call_sig(b),
                    Builtin::RcTryUnwrap => {
                        let elem = self.new_var(false);
                        self.deferred_sized.push((elem, span));
                        let rc = self.tys.mk_rc(elem);
                        let res = self.tys.mk_result(elem, rc);
                        (vec![rc], res)
                    }
                    Builtin::RcIntoInner => {
                        let elem = self.new_var(false);
                        self.deferred_sized.push((elem, span));
                        let rc = self.tys.mk_rc(elem);
                        (vec![rc], self.tys.mk_option(elem))
                    }
                    Builtin::RcUnwrapOrClone => {
                        let elem = self.new_var(false);
                        self.deferred_sized.push((elem, span));
                        let rc = self.tys.mk_rc(elem);
                        self.deferred_clone.push((elem, span));
                        (vec![rc], elem)
                    }
                    Builtin::VecNew | Builtin::VecWithCapacity => {
                        let elem = self.new_var(false);
                        let params = if b == Builtin::VecNew { vec![] } else { vec![USIZE] };
                        (params, self.tys.mk_vec(elem))
                    }
                    Builtin::MemDrop | Builtin::MemForget => {
                        let t = self.callee_turbo_ty(callee, span);
                        (vec![t], UNIT)
                    }
                    Builtin::FmtFormat => (vec![crate::ty::fmt::fmt_ty(&mut self.tys, crate::ty::fmt::FmtTy::Arguments)], STRING),
                    Builtin::DiscriminantValue | Builtin::DiscriminantKind => {
                        let t = self.new_var(false);
                        let r = self.tys.mk_ref(false, t);
                        (vec![r], if b == Builtin::DiscriminantValue { int(IntTy::I128) } else { int(IntTy::U8) })
                    }
                    Builtin::OnceInit | Builtin::OnceTake => {
                        let t = self.new_var(false);
                        let o = self.tys.mk_option(t);
                        let r = self.tys.mk_ref(false, o);
                        if b == Builtin::OnceInit { (vec![r, t], UNIT) } else { (vec![r], o) }
                    }
                    Builtin::MemSwap => {
                        let t = self.callee_turbo_ty(callee, span);
                        let r = self.tys.mk_ref(true, t);
                        (vec![r, r], UNIT)
                    }
                    Builtin::MemReplace => {
                        let t = self.callee_turbo_ty(callee, span);
                        let r = self.tys.mk_ref(true, t);
                        (vec![r, t], t)
                    }
                    Builtin::MemTake => {
                        let t = self.callee_turbo_ty(callee, span);
                        let r = self.tys.mk_ref(true, t);
                        (vec![r], t)
                    }
                    Builtin::CmpMax | Builtin::CmpMin => {
                        let t = self.callee_turbo_ty(callee, span);
                        (vec![t, t], t)
                    }
                    Builtin::HintBlackBox => {
                        let t = self.callee_turbo_ty(callee, span);
                        (vec![t], t)
                    }
                    // `slice::from_ref(&T) -> &[T]`, `from_mut(&mut T)
                    // -> &mut [T]` (fx-option-rest): the written name
                    // gives the mutability.
                    Builtin::SliceFromRef => {
                        let t = self.callee_turbo_ty(callee, span);
                        self.deferred_sized.push((t, span));
                        let m = match p.ast.expr(callee) {
                            Expr::Path(segs) => segs.last().is_some_and(|s| self.name(s.name) == "from_mut"),
                            _ => false,
                        };
                        let sl = self.tys.intern(TyKind::Slice(t));
                        (vec![self.tys.mk_ref(m, t)], self.tys.mk_ref(m, sl))
                    }
                    // `ptr::from_ref(&T) -> *const T`, `from_mut(&mut T)
                    // -> *mut T` (w-cinterop): the written name gives the
                    // mutability, as for `slice::from_ref`.
                    Builtin::PtrFromRef => {
                        let t = self.callee_turbo_ty(callee, span);
                        self.deferred_raw.push((t, span, RawUse::Pointee));
                        let m = match p.ast.expr(callee) {
                            Expr::Path(segs) => segs.last().is_some_and(|s| self.name(s.name) == "from_mut"),
                            _ => false,
                        };
                        (vec![self.tys.mk_ref(m, t)], self.tys.intern(TyKind::RawPtr(Mut::from_bool(m), t)))
                    }
                    // `ptr::null::<T>() -> *const T`, `null_mut` the
                    // mutable form (w-cinterop).
                    Builtin::PtrNull => {
                        let t = self.callee_turbo_ty(callee, span);
                        self.deferred_sized.push((t, span));
                        let m = match p.ast.expr(callee) {
                            Expr::Path(segs) => segs.last().is_some_and(|s| self.name(s.name) == "null_mut"),
                            _ => false,
                        };
                        (vec![], self.tys.intern(TyKind::RawPtr(Mut::from_bool(m), t)))
                    }
                    // `ptr::eq` (w-cinterop): two raw pointers of one
                    // pointee; references coerce. `addr_eq::<T, U>`
                    // compares the addresses of two pointee types. A dyn
                    // pointee has no `eq` (`RawUse::NotDyn`).
                    Builtin::PtrEqFn | Builtin::PtrAddrEqFn => {
                        let seg = match p.ast.expr(callee) {
                            Expr::Path(segs) => segs.last(),
                            _ => None,
                        };
                        let written = seg.map(|s| s.type_args()).unwrap_or_default();
                        let pointees = if seg.is_some_and(|s| self.name(s.name) == "addr_eq") {
                            if !matches!(written.len(), 0 | 2) {
                                self.err("L0105", span, "this function takes two type arguments", "Write two types in the `::<...>`.");
                            }
                            let mut one = |i: usize| match written.get(i) {
                                Some(&w) => self.resolve_written(w),
                                None => self.new_var(false),
                            };
                            [one(0), one(1)]
                        } else {
                            let t = self.callee_turbo_ty(callee, span);
                            [t, t]
                        };
                        let is_eq = !seg.is_some_and(|s| self.name(s.name) == "addr_eq");
                        let ps = pointees.map(|t| {
                            self.deferred_raw.push((t, span, if is_eq { RawUse::NotDyn("`ptr::eq`") } else { RawUse::Pointee }));
                            self.tys.intern(TyKind::RawPtr(Mut::Shared, t))
                        });
                        (ps.to_vec(), BOOL)
                    }
                    // `Option::iter(&o)`, `Result::into_iter(r)`, and
                    // kin (fx-option-rest): a method in path form, so
                    // the receiver is the one argument. The expansion
                    // keys on the result iterator kind.
                    Builtin::IterOptRes => {
                        use crate::ty::iter::{IterKind as IK, mk_iter};
                        let (is_opt, item_name, written_tys) = match p.ast.expr(callee) {
                            Expr::Path(segs) if segs.len() >= 2 => {
                                let ty_seg = &segs[segs.len() - 2];
                                let tys: Vec<Ty> = ty_seg.type_args().into_iter().map(|t| self.resolve_written(t)).collect();
                                (self.name(ty_seg.name) == "Option", self.name(segs[segs.len() - 1].name).to_string(), tys)
                            }
                            _ => (true, String::new(), Vec::new()),
                        };
                        let t = written_tys.first().copied().unwrap_or_else(|| self.new_var(false));
                        let e = written_tys.get(1).copied().unwrap_or_else(|| self.new_var(false));
                        let self_ty = if is_opt { self.tys.mk_option(t) } else { self.tys.mk_result(t, e) };
                        match item_name.as_str() {
                            "iter_mut" => {
                                let k = if is_opt { IK::OptionIterMut } else { IK::ResultIterMut };
                                (vec![self.tys.mk_ref(true, self_ty)], mk_iter(&mut self.tys, k, &[t]))
                            }
                            "into_iter" => {
                                let k = if is_opt { IK::OptionIntoIter } else { IK::ResultIntoIter };
                                (vec![self_ty], mk_iter(&mut self.tys, k, &[t]))
                            }
                            _ => {
                                let k = if is_opt { IK::OptionIter } else { IK::ResultIter };
                                (vec![self.tys.mk_ref(false, self_ty)], mk_iter(&mut self.tys, k, &[t]))
                            }
                        }
                    }
                    // `repeat_n(x, n)` with `T: Clone` (W-STD-B, ty/iter.rs).
                    Builtin::IterRepeatN => {
                        let t = self.callee_turbo_ty(callee, span);
                        self.deferred_clone.push((t, span));
                        self.deferred_repeat_n.push((t, span));
                        (vec![t, USIZE], crate::ty::iter::mk_iter(&mut self.tys, crate::ty::iter::IterKind::RepeatN, &[t]))
                    }
                    // `std::array::from_fn::<T, N, F>(f) -> [T; N]` with
                    // `F: FnMut(usize) -> T`: the written turbofish names
                    // `T` and `N` first, then the expected array type,
                    // then fresh variables unified by the call's uses.
                    Builtin::ArrayFromFn => {
                        let (mut elem, mut len_c): (Option<Ty>, Option<ConstId>) = (None, None);
                        let mut f_written: Option<Ty> = None;
                        if let Expr::Path(segs) = p.ast.expr(callee)
                            && let Some(seg) = segs.last()
                            && let ast::GenericArgs::Angle(written) = &seg.args
                        {
                            // By position, as the parameters run
                            // `T`, `N`, `F`: a `_` at `N` parses as a
                            // type, so counting types alone miscounts.
                            let mut pos = 0usize;
                            for g in written {
                                match (pos, g) {
                                    (_, ast::GenericArg::Lifetime(_)) => {
                                        self.err("L0107", span, "this function takes no lifetime arguments", "Write `from_fn::<T, N, F>(..)`.");
                                    }
                                    (0, ast::GenericArg::Type(t)) => elem = Some(self.resolve_written(*t)),
                                    (1, ast::GenericArg::Const(e)) => {
                                        let scope = self.body_scope.clone();
                                        match generics::resolve_const_arg(&p.ast, &p.interner, &p.known, &mut self.tys, &scope, *e, span) {
                                            Ok(c) => len_c = Some(c),
                                            Err(d) => self.errs.push(d),
                                        }
                                    }
                                    // A written type at the const slot is
                                    // the inferred length (`_`).
                                    (1, ast::GenericArg::Type(t)) => {
                                        let _ = self.resolve_written(*t);
                                    }
                                    (2, ast::GenericArg::Type(t)) => f_written = Some(self.resolve_written(*t)),
                                    _ => {
                                        self.err("L0107", span, "this function takes at most 3 generic arguments", "Write `from_fn::<T, N, F>(..)`.");
                                    }
                                }
                                pos += 1;
                            }
                        }
                        if (elem.is_none() || len_c.is_none())
                            && let Some(want) = expected
                            && let TyKind::Array(e, n) = self.kind(self.resolve(want))
                        {
                            elem.get_or_insert(self.resolve(e));
                            len_c.get_or_insert(n);
                        }
                        let elem = elem.unwrap_or_else(|| self.new_var(false));
                        let len_c = len_c.unwrap_or_else(|| self.fresh_const_var());
                        let arr = self.tys.intern(TyKind::Array(elem, len_c));
                        let f = self.fn_mut_param(&[USIZE], elem, span);
                        if let Some(fw) = f_written
                            && !self.unify(f, fw)
                        {
                            self.mismatch(span, fw, f);
                        }
                        (vec![f], arr)
                    }
                    _ => unreachable!(),
                };
                if let Some(want) = written_self {
                    let item = match p.ast.expr(callee) {
                        Expr::Path(segs) => segs[segs.len() - 1].name,
                        Expr::QPath { segs, .. } => segs[0].name,
                        _ => p.known.new,
                    };
                    if !self.unify_builtin_self(want, &params, ret, item, span) {
                        for &a in args {
                            self.expr(a, None);
                        }
                        return ERROR;
                    }
                }
                // rustc checks the arguments against the inputs the expected
                // output implies: `HashMap::with_capacity_and_hasher(n,
                // Default::default())` in a typed `let` knows its `S` before
                // the hasher argument (W-STD-B). A hash table has no coercion,
                // so a failed try only rolls back.
                if crate::check::hashmap::is_hash_ctor(b)
                    && let Some(want) = expected
                {
                    let snap = self.snapshot_vars();
                    if !self.unify(ret, want) {
                        self.rollback_vars(snap);
                    }
                }
                // The same for the one-value wrappers (`Mutex::new(x)` where
                // `Mutex<Option<Box<dyn Fn()>>>` is expected): the argument is
                // then a coercion site for the expected value type, as
                // rustc coerces to a sized expected input (`Some` does this
                // in its own arm; a `dyn` value is the arm above; an unsized
                // one such as `RefCell<dyn Tr>` is only a hint in rustc).
                if written_self.is_none()
                    && args.len() == 1
                    && let Some(want) = expected.map(|t| self.resolve(t))
                    && let Some(elem) = self.wrapper_value_ty(b, want)
                    && self.sized_value(elem)
                {
                    let snap = self.snapshot_vars();
                    if !self.unify(ret, want) {
                        self.rollback_vars(snap);
                    }
                }
                self.check_args(&params, args, span);
                // The Rc and Arc fns that need a sized value, or that lust
                // has not built for `str` and `[T]` (check/own.rs).
                if self.own_call_guard(b, &params, span) {
                    return ERROR;
                }
                // `Rc::try_unwrap` needs `T: Sized` (rustc E0277), and
                // the other value-reaching Rc builtins are not built for
                // `Rc<dyn Tr>` yet; the counts are.
                if matches!(b, Builtin::RcMakeMut | Builtin::RcGetMut | Builtin::RcTryUnwrap)
                    && let Some(&pt) = params.first()
                    && let t = self.deep(pt)
                    && let Some(rc) = Some(match self.kind(t) {
                        TyKind::Ref(_, _, inner) => inner,
                        _ => t,
                    })
                    && self.tys.rc_elem(rc).is_some_and(|e| matches!(self.kind(e), TyKind::Dyn(..)))
                {
                    if b == Builtin::RcTryUnwrap {
                        self.err("L0110", span, "`Rc::try_unwrap` needs a sized value, not a `dyn` one", "Keep the `Rc<dyn Tr>` and call through it.");
                    } else {
                        self.errs.push(generics::dyn_not_yet(span, "this `Rc` function on an `Rc<dyn Tr>`"));
                    }
                    return ERROR;
                }
                if let Builtin::Sync(op) = b {
                    self.lint_atomic_ordering(op, args);
                }
                // The byte-move and scalar-cmp builtins have type
                // limits rustc states as `Sized`, `Default`, and
                // `Ord` bounds; outside the exact supported shapes
                // lust rejects (a safe false reject) instead of
                // guessing a value.
                let elem_of = |this: &mut Self, i: usize| {
                    let t = this.resolve(params[i]);
                    match this.tys.kind(t) {
                        TyKind::Ref(_, _, inner) => this.resolve(inner),
                        _ => t,
                    }
                };
                match b {
                    Builtin::MemDrop | Builtin::MemForget | Builtin::MemSwap | Builtin::MemReplace => {
                        // For `drop` and `forget`, T is the argument
                        // itself (a reference to an unsized value is
                        // sized); for swap/replace, T sits behind the `&mut`.
                        let t = if matches!(b, Builtin::MemDrop | Builtin::MemForget) { self.resolve(params[0]) } else { elem_of(self, 0) };
                        if matches!(self.tys.kind(t), TyKind::Slice(_) | TyKind::Str | TyKind::Dyn(..)) {
                            let tn = self.tn(t);
                            self.err(
                                "L0110",
                                span,
                                format!("the size for values of type `{tn}` cannot be known at compilation time"),
                                "Use a sized value, or move through a sized place.",
                            );
                        }
                    }
                    Builtin::MemTake => {
                        let t = elem_of(self, 0);
                        let k = self.tys.kind(t);
                        // The default glue builds any value `has_default`
                        // accepts (derived `Default` included).
                        let ok = matches!(k, TyKind::Int(_) | TyKind::Float(_) | TyKind::Bool | TyKind::Char | TyKind::Unit)
                            || k.is_int_infer()
                            || k.is_float_infer()
                            || (!matches!(k, TyKind::Param(_) | TyKind::Projection(..)) && has_default(self.p, &self.tys, t));
                        if ok {
                            self.record_glue_reads(self.p.gx.lang.default, t);
                        }
                        // A type a later use fixes (`.and_then(Arc::get_mut)`)
                        // waits for body end, as rustc's `T: Default`
                        // obligation does; an error type is a follow-on.
                        if !ok && matches!(k, TyKind::Infer(_)) {
                            self.deferred_default.push((t, span));
                        } else if !ok && k != TyKind::Error {
                            self.errs.push(unsupported(span, "`mem::take` on this type"));
                        }
                    }
                    Builtin::CmpMax | Builtin::CmpMin => {
                        let t = elem_of(self, 0);
                        let k = self.tys.kind(t);
                        // The written name must be the builtin's own (not a
                        // `use std::cmp::max as min` rename).
                        let want = if b == Builtin::CmpMin { "min" } else { "max" };
                        let name = match p.ast.expr(callee) {
                            Expr::Path(segs) => segs.last().map(|s| s.name).filter(|&n| self.name(n) == want),
                            _ => None,
                        };
                        if !(matches!(k, TyKind::Int(_) | TyKind::Char | TyKind::Bool) || k.is_int_infer()) {
                            match name {
                                // Other types call `Ord::min`/`max` (std's body).
                                Some(name) if !matches!(k, TyKind::Infer(_) | TyKind::Error) => self.cmp_free_fn_as_ord(e, t, name, span),
                                _ => self.errs.push(unsupported(span, "`cmp::max`/`cmp::min` on this type")),
                            }
                        }
                    }
                    _ => {}
                }
                ret
            }
            Res::Intrinsic(id) => {
                let def = lang::intrinsic(id);
                let params: Vec<Ty> = def.params.iter().map(|s| s.resolve(&mut self.tys)).collect();
                self.check_args(&params, args, span);
                def.ret.resolve(&mut self.tys)
            }
            _ => ERROR,
        }
    }

    fn check_args(&mut self, params: &[Ty], args: &[ExprId], span: Span) {
        if params.len() != args.len() {
            self.err(
                "L0105",
                span,
                format!("this function takes {} argument(s) but {} were given", params.len(), args.len()),
                "Pass exactly the declared arguments.",
            );
        }
        // Closure arguments check last, as rustc does: their parameter
        // types often come from the other arguments (`apply(|x| .., 5u8)`).
        for closures in [false, true] {
            for (i, &a) in args.iter().enumerate() {
                if matches!(self.p.ast.expr(a), Expr::Closure { .. }) != closures {
                    continue;
                }
                match params.get(i) {
                    Some(&pt) => {
                        self.expect_expr(a, pt);
                    }
                    None => {
                        self.expr(a, None);
                    }
                }
                self.reject_unsized_value(a);
            }
        }
    }

    /// An argument, tuple or array element, struct literal field, or
    /// closure body moves its value, which needs a statically known size
    /// (rustc E0277/E0161): `drop(*b)` for `b: Box<dyn Tr>`, `Some(v[1..])`.
    /// Reports once per expression.
    pub(super) fn reject_unsized_value(&mut self, a: ExprId) {
        let t = self.deep(self.out.expr_ty[self.ei(a)]);
        if self.out.coerce[self.ei(a)] == Coerce::None && matches!(self.kind(t), TyKind::Dyn(..) | TyKind::Str | TyKind::Slice(_)) {
            let (tn, span) = (self.tn(t), self.span(a));
            if self.errs.iter().any(|d| d.code == "L0110" && d.span == span) {
                return;
            }
            self.err(
                "L0110",
                span,
                format!("the size for values of type `{tn}` cannot be known, so it cannot be used by value"),
                "Use a reference instead: `&*b`.",
            );
        }
    }

    /// The ambiguity guard of the scalar lang-method probes: a
    /// second in-scope trait with an impl of the same method name
    /// for this receiver makes the call ambiguous in rustc
    /// (E0034). Reports it and returns true. (Declining instead
    /// would let the generic search take the other trait alone:
    /// the lang candidate has no impl method fn there, so the
    /// generic search would silently accept.)
    fn prim_lang_guard(&mut self, name: Sym, name_span: Span, args: &[ExprId], trait_def: DefId, base: Ty) -> bool {
        let p = self.p;
        let others: Vec<DefId> = p
            .gx
            .traits_by_method
            .get(&name)
            .cloned()
            .unwrap_or_default()
            .into_iter()
            .filter(|&d| d != trait_def && method::trait_in_scope_at(self, d, base))
            .collect();
        for other in others {
            let Some(rec) = p.gx.index.trait_record(other) else { continue };
            let snap = self.snapshot_vars();
            let obl_len = self.obl_len();
            let mut tr_args: Vec<GenericArg> = vec![GenericArg::Ty(base)];
            for _ in 1..rec.generics.params.len() {
                tr_args.push(GenericArg::Ty(self.new_var(false)));
            }
            let args_id = self.tys.intern_args(&tr_args);
            let tr = TraitRef { def: other, args: args_id, bindings: EMPTY_BINDINGS };
            let hits = matches!(self.select_obligation(tr), Selection::Impl { .. } | Selection::ParamEvidence(_));
            self.rollback_vars(snap);
            self.obl_truncate(obl_len);
            if hits {
                self.err(
                    "L0720",
                    name_span,
                    format!("multiple trait methods named `{}` apply here", self.name(name)),
                    "Call the method with a fully qualified path, such as `<Type as Trait>::method(...)`.",
                );
                for &a in args {
                    self.expr(a, None);
                }
                return true;
            }
        }
        false
    }

    /// An operator trait method on a scalar receiver in method
    /// form (`a.add(b)`, `a.neg()`, `a.add_assign(b)`): the same
    /// shape as `prim_cmp_method`, through `Res::PrimOp`. The
    /// operator traits are not in the prelude, so without a pick
    /// replay the trait must be in scope, as in rustc. Operand
    /// sets are core's exactly (see the synthetic impls in
    /// `generics::add_synthetic_impls`): arithmetic on ints and
    /// floats, bit operators on ints and bool, shifts on ints
    /// with any int right side, `Neg` on signed ints and floats,
    /// `Not` on ints and bool.
    #[allow(clippy::too_many_arguments)]
    fn prim_op_method(
        &mut self,
        e: ExprId,
        recv: ExprId,
        base: Ty,
        derefs: u8,
        name: Sym,
        name_span: Span,
        args: &[ExprId],
        turbofish: &[ast::GenericArg],
        builtin_only: bool,
    ) -> Option<Ty> {
        if !turbofish.is_empty() {
            return None;
        }
        let p = self.p;
        let lang = &p.gx.lang;
        // `String::add(&str)`: the one non-scalar operator impl
        // with a builtin body (the same value `String + &str`
        // builds). Scope and ambiguity follow the scalar rules.
        if self.name(name) == "add" && self.tys.is_string_ty(self.resolve(base)) {
            if !builtin_only && !method::trait_in_scope_pub(self, lang.add) {
                return None;
            }
            if !builtin_only && self.prim_lang_guard(name, name_span, args, lang.add, base) {
                return Some(ERROR);
            }
            self.check_args(&[REF_STR], args, name_span);
            self.set_res(e, Res::PrimOp { kind: PrimOpKind::Bin(BinOp::Add), derefs });
            return Some(STRING);
        }
        let bk = self.kind(base);
        let intlike = matches!(bk, TyKind::Int(_)) || bk.is_int_infer();
        let floatlike = matches!(bk, TyKind::Float(_)) || bk.is_float_infer();
        let signed = matches!(bk, TyKind::Int(i) if i.signed());
        let arith = intlike || floatlike;
        let bits = intlike || matches!(bk, TyKind::Bool);
        use BinOp::*;
        use PrimOpKind as K;
        let (kind, trait_def) = match self.name(name) {
            "add" if arith => (K::Bin(Add), lang.add),
            "sub" if arith => (K::Bin(Sub), lang.sub),
            "mul" if arith => (K::Bin(Mul), lang.mul),
            "div" if arith => (K::Bin(Div), lang.div),
            "rem" if arith => (K::Bin(Rem), lang.rem),
            "bitand" if bits => (K::Bin(BitAnd), lang.bit_and),
            "bitor" if bits => (K::Bin(BitOr), lang.bit_or),
            "bitxor" if bits => (K::Bin(BitXor), lang.bit_xor),
            "shl" if intlike => (K::Bin(Shl), lang.shl),
            "shr" if intlike => (K::Bin(Shr), lang.shr),
            "neg" if floatlike || signed || bk.is_int_infer() => (K::Un(ast::UnOp::Neg), lang.neg),
            "not" if bits => (K::Un(ast::UnOp::Not), lang.not),
            "add_assign" if arith => (K::Assign(Add), lang.add_assign),
            "sub_assign" if arith => (K::Assign(Sub), lang.sub_assign),
            "mul_assign" if arith => (K::Assign(Mul), lang.mul_assign),
            "div_assign" if arith => (K::Assign(Div), lang.div_assign),
            "rem_assign" if arith => (K::Assign(Rem), lang.rem_assign),
            "bitand_assign" if bits => (K::Assign(BitAnd), lang.bit_and_assign),
            "bitor_assign" if bits => (K::Assign(BitOr), lang.bit_or_assign),
            "bitxor_assign" if bits => (K::Assign(BitXor), lang.bit_xor_assign),
            "shl_assign" if intlike => (K::Assign(Shl), lang.shl_assign),
            "shr_assign" if intlike => (K::Assign(Shr), lang.shr_assign),
            _ => return None,
        };
        if !builtin_only && !method::trait_in_scope_pub(self, trait_def) {
            return None;
        }
        if !builtin_only && self.prim_lang_guard(name, name_span, args, trait_def, base) {
            return Some(ERROR);
        }
        // An unsuffixed literal receiver of `neg` can still bind
        // to an unsigned type from context; the bound then has no
        // impl in rustc. Queue the obligation so body end (after
        // fallback settles the type) makes that call.
        if matches!(kind, K::Un(ast::UnOp::Neg)) && bk.is_int_infer() {
            let args_id = self.tys.intern_args(&[GenericArg::Ty(base)]);
            let tr = TraitRef { def: lang.neg, args: args_id, bindings: EMPTY_BINDINGS };
            self.obl.push_trait_at(tr, name_span, 0);
        }
        let ret = match kind {
            K::Bin(op) => {
                // Shifts take any int right side; the rest take Self.
                let rhs_ty = if matches!(op, Shl | Shr) { self.new_var(true) } else { base };
                self.check_args(&[rhs_ty], args, name_span);
                base
            }
            K::Un(_) => {
                self.check_args(&[], args, name_span);
                base
            }
            K::Assign(op) => {
                self.check_packed_borrow(recv, name_span);
                let rhs_ty = if matches!(op, Shl | Shr) { self.new_var(true) } else { base };
                self.check_args(&[rhs_ty], args, name_span);
                UNIT
            }
            // `prim_into_method` and `into_iter_self` build these
            // kinds, never this match.
            K::IntoCast | K::IntoIterSelf | K::TryIntoCast => unreachable!(),
        };
        self.set_res(e, Res::PrimOp { kind, derefs });
        Some(ret)
    }

    /// A comparison trait method on a scalar receiver in method
    /// form (`a.partial_cmp(b)`, `a.cmp(b)`, `a.eq(b)`, `a.lt(b)`,
    /// and kin): core's impls for the scalar types are the scalar
    /// comparisons themselves, so the call resolves here and
    /// lowering emits them (`Res::PrimCmp`). This is also where a
    /// template pick for one of these traits lands in an instance
    /// (`builtin_only`: the trait was fixed by the template check,
    /// so no ambiguity question is asked again). Without a pick,
    /// another in-scope trait with an impl of the same method name
    /// for this receiver makes the call ambiguous in rustc: the
    /// probe then reports the ambiguity itself.
    #[allow(clippy::too_many_arguments)]
    fn prim_cmp_method(
        &mut self,
        e: ExprId,
        recv: ExprId,
        base: Ty,
        derefs: u8,
        name: Sym,
        name_span: Span,
        args: &[ExprId],
        turbofish: &[ast::GenericArg],
        builtin_only: bool,
    ) -> Option<Ty> {
        if !turbofish.is_empty() {
            return None;
        }
        let p = self.p;
        let lang = &p.gx.lang;
        let bk = self.kind(base);
        let intlike = matches!(bk, TyKind::Int(_)) || bk.is_int_infer();
        let floatlike = matches!(bk, TyKind::Float(_)) || bk.is_float_infer();
        if !intlike && !floatlike && !matches!(bk, TyKind::Bool | TyKind::Char) {
            // The iterator range kinds (`Range`, `RangeInclusive`,
            // `RangeFrom`) by value, or through `&mut` or `Box`: rustc's
            // by-value probe finds `Iterator::eq` and kin first (as
            // method.rs `iterator_shadows` has it for user iterators), so
            // the iterator path answers, not `PartialEq`.
            if !builtin_only && self.range_iter_receiver(recv) {
                return None;
            }
            // Other types compare by structure when every part does
            // (strings, tuples, containers, derived impls): lowering
            // uses the `eq` and `cmp` glue for them.
            self.record_glue_reads(p.gx.lang.partial_eq, base);
            let ok = match self.name(name) {
                // `partial_cmp` also takes the `PCmp` glue: elements with a
                // written `partial_cmp` beside an `Ord` impl (lower.rs
                // picks `PCmpCode` then).
                "partial_cmp" => has_ord(p, &self.tys, base) || has_partial_cmp(p, &self.tys, base),
                "lt" | "le" | "gt" | "ge" => has_ord(p, &self.tys, base),
                "cmp" => has_total_ord(p, &self.tys, base),
                "eq" | "ne" => has_eq(p, &self.tys, base),
                _ => false,
            };
            if !ok || matches!(bk, TyKind::Param(_) | TyKind::Projection(..) | TyKind::Infer(_) | TyKind::Error) {
                return None;
            }
        }
        let (kind, trait_def) = match self.name(name) {
            "partial_cmp" => (PrimCmpKind::Partial(p.tys.local_adt_of(generics::ordering_def())?), lang.partial_ord),
            "cmp" if !floatlike => (PrimCmpKind::Total(p.tys.local_adt_of(generics::ordering_def())?), lang.ord),
            "eq" => (PrimCmpKind::Op(BinOp::Eq), lang.partial_eq),
            "ne" => (PrimCmpKind::Op(BinOp::Ne), lang.partial_eq),
            "lt" => (PrimCmpKind::Op(BinOp::Lt), lang.partial_ord),
            "le" => (PrimCmpKind::Op(BinOp::Le), lang.partial_ord),
            "gt" => (PrimCmpKind::Op(BinOp::Gt), lang.partial_ord),
            "ge" => (PrimCmpKind::Op(BinOp::Ge), lang.partial_ord),
            _ => return None,
        };
        if !builtin_only && self.prim_lang_guard(name, name_span, args, trait_def, base) {
            return Some(ERROR);
        }
        self.check_packed_borrow(recv, name_span);
        let other_ty = self.tys.mk_ref(false, base);
        match self.cmp_arg(e, recv, base, trait_def, args, name) {
            CmpArg::Plain => self.check_args(&[other_ty], args, name_span),
            CmpArg::Checked => {}
            // `x.eq(y)` as the operator `Self == R` (`cmp_cross_eq`).
            CmpArg::Cross => return Some(BOOL),
        }
        self.set_res(e, Res::PrimCmp { kind, derefs });
        Some(match kind {
            PrimCmpKind::Partial(_) => {
                let ord = generics::ordering_ty(&mut self.tys);
                self.tys.mk_option(ord)
            }
            PrimCmpKind::Total(_) => generics::ordering_ty(&mut self.tys),
            PrimCmpKind::Op(_) => BOOL,
        })
    }

    /// True when the receiver `recv` is, by value or through `&mut` or
    /// `Box`, one of the range kinds std makes iterators (`Range`,
    /// `RangeInclusive`, `RangeFrom`): `prim_cmp_method` leaves its
    /// comparison method names to the iterator path.
    fn range_iter_receiver(&mut self, recv: ExprId) -> bool {
        use crate::ty::iter::IterKind as K;
        let rt = self.out.expr_ty[self.ei(recv)];
        let rt = self.deep(rt);
        let t = match self.kind(rt) {
            TyKind::Ref(_, Mut::Mut, inner) => self.resolve(inner),
            TyKind::Ref(..) => return false,
            _ => self.tys.boxed_elem(rt).map_or(rt, |e| self.resolve(e)),
        };
        crate::ty::iter::iter_parts(&self.tys, t).is_some_and(|(k, _)| matches!(k, K::Range | K::RangeInclusive | K::RangeFrom))
    }

    /// The argument of a comparison method call (`eq`, `partial_cmp`,
    /// `cmp`, ...) as rustc types it (`cmp_arg_rule`), then coerced on to
    /// `&base`, which lowering compares; false when the plain check (a
    /// coercion to `&base`) is rustc's: `Self` is `base` with one impl.
    /// `s.eq(&&s)` on a `String` is E0277 (several impls: no deref
    /// coercion); `Box::new(5).eq(&5)` is E0308 (`Rhs` is the Box).
    fn cmp_arg(&mut self, e: ExprId, recv: ExprId, base: Ty, trait_def: DefId, args: &[ExprId], name: Sym) -> CmpArg {
        let [a] = args else { return CmpArg::Plain };
        let rt = self.out.expr_ty[self.ei(recv)];
        let rt = self.deep(rt);
        let self_ty = self.cmp_self_ty(rt);
        let open = trait_def != self.p.gx.lang.ord && self.cmp_rhs_open(self_ty, trait_def);
        if !open && self_ty == base {
            return CmpArg::Plain;
        }
        let want = self.tys.mk_ref(false, self_ty);
        let at = self.expr(*a, Some(want));
        if open && self.cmp_cross_eq(e, rt, self_ty, at, name) {
            return CmpArg::Cross;
        }
        if self.cmp_arg_rule(rt, at, trait_def, *a, name) {
            let to = self.tys.mk_ref(false, base);
            self.coerce_expr(*a, at, to);
        }
        CmpArg::Checked
    }

    /// `x.eq(y)` or `x.ne(y)` when `Self` has several `PartialEq` impls
    /// and the argument is `&R` with `R` not `Self`: rustc selects
    /// `Self: PartialEq<R>`, which is the operator `Self == R`. The
    /// std pairs the operator knows are taken here: the string types
    /// (`string_eq_ok`: `String` with `str`, `&str`, `Cow<str>`, ...)
    /// and the sequence forms (`seq_cmp`: `Vec<T>` with `[T]`,
    /// `&[T]`, `[T; N]`, ...). The call records `Res::Bin` with
    /// depths from the receiver's and the argument's own types, so
    /// lowering emits the operator. False leaves the call to
    /// `cmp_arg_rule` (Rhs = Self, or its L0612).
    fn cmp_cross_eq(&mut self, e: ExprId, rt: Ty, self_ty: Ty, at: Ty, name: Sym) -> bool {
        let op = match self.name(name) {
            "eq" => BinOp::Eq,
            "ne" => BinOp::Ne,
            _ => return false,
        };
        let r = match self.kind(at) {
            TyKind::Ref(_, _, u) => self.resolve(u),
            _ => return false,
        };
        let self_ty = self.deep(self_ty);
        let r = self.deep(r);
        if self.unbound_general(r) || self.unbound_general(self_ty) {
            return false;
        }
        let snap = self.snapshot_vars();
        let same = self.unify(r, self_ty);
        self.rollback_vars(snap);
        if same {
            return false;
        }
        // The receiver's place reaches `Self` after one peeled
        // reference (`cmp_self_ty`); the argument is `&R`.
        let peel = u8::from(matches!(self.kind(rt), TyKind::Ref(_, Mut::Shared, _)));
        let (ld, lb) = self.autoderef(self_ty);
        let (rd, rb) = self.autoderef(r);
        if let (Some(lk), Some(rk)) = (self.str_kind(lb, true), self.str_kind(rb, true)) {
            if !string_eq_ok(ld, lk, rd, rk) {
                return false;
            }
            self.set_res(e, Res::Bin { ld: ld + peel, rd: rd + 1 });
            return true;
        }
        let span = self.span(e);
        if self.seq_cmp(e, op, self_ty, r, ld, lb, rd, rb, span).is_none() {
            return false;
        }
        if let Res::Bin { ld, rd } = self.out.expr_res[self.ei(e)] {
            self.set_res(e, Res::Bin { ld: ld + peel, rd: rd + 1 });
        }
        true
    }

    /// Rustc's `Self` of a comparison method call on a receiver of type
    /// `rt`: one shared reference peeled (`x: &T` matches `&self` by
    /// value at the first step), else the receiver itself (an autoref).
    fn cmp_self_ty(&mut self, rt: Ty) -> Ty {
        match self.kind(rt) {
            TyKind::Ref(_, Mut::Shared, inner) => self.resolve(inner),
            _ => rt,
        }
    }

    /// Checks the argument type `at` (before coercion) of a comparison
    /// call on a receiver of type `rt` by rustc's rule, reporting L0612
    /// at `a` when it fails. Rustc knows of `Rhs` what `Self`'s impls fix
    /// (`cmp_rhs_shape`): an unknown `Rhs` takes the argument's pointee
    /// as is; a known shape takes the first deref of it that fits (deref
    /// coercion). Lust compares `Rhs = Self` only. Also run after the
    /// method search picks a written impl of a std type (check/method.rs
    /// `cmp_needs_rustc_rhs`), whose argument it coerced as a plain call.
    pub(super) fn cmp_arg_rule(&mut self, rt: Ty, at: Ty, trait_def: DefId, a: ExprId, name: Sym) -> bool {
        let rt = self.deep(rt);
        let at = self.deep(at);
        let self_ty = self.cmp_self_ty(rt);
        let shape = self.cmp_rhs_shape(self_ty, trait_def);
        let mut u = match self.kind(at) {
            TyKind::Ref(_, _, u) => Some(self.resolve(u)),
            _ => None,
        };
        let ok = match &shape {
            None => u.is_some_and(|u| self.unify(u, self_ty)),
            Some(shape) => {
                let mut hit = false;
                for _ in 0..16 {
                    let Some(t) = u else { break };
                    if self.cmp_shape_fits(t, shape) {
                        hit = self.unify(t, self_ty);
                        break;
                    }
                    u = match self.kind(t) {
                        TyKind::Ref(_, _, i) => Some(self.resolve(i)),
                        _ => self.tys.smart_elem(t).map(|i| self.resolve(i)),
                    };
                }
                hit
            }
        };
        if !ok && self.kind(at) != TyKind::Error && self.kind(self_ty) != TyKind::Error {
            let (sn, an, n) = (self.tn(self_ty), self.tn(at), self.name(name).to_string());
            let why = if shape.is_none() { "`Self` has several impls, so the argument's type picks one" } else { "the argument must deref to `&Self`" };
            self.err(
                "L0612",
                self.span(a),
                format!("`{sn}::{n}` takes `&{sn}` here, not `{an}` ({why})"),
                "Pass a reference to a value of the receiver's type, such as `x.eq(&y)`.",
            );
        }
        ok
    }

    /// What rustc knows of `Rhs` for `Self = t` before it types the
    /// argument: None when several impls leave it open (`cmp_rhs_open`;
    /// a reference's `PartialEq` has two blanket impls), else its shape:
    /// `t` itself, or for a reference's one `PartialOrd` blanket impl a
    /// reference of the same kind to its pointee's shape.
    fn cmp_rhs_shape(&mut self, t: Ty, trait_def: DefId) -> Option<CmpShape> {
        let lang = self.p.gx.lang;
        if trait_def == lang.ord {
            return Some(CmpShape::Exact(t));
        }
        match self.kind(t) {
            TyKind::Ref(_, m, inner) => {
                if trait_def == lang.partial_eq {
                    return None;
                }
                let inner = self.resolve(inner);
                let p = self.cmp_rhs_shape(inner, trait_def).unwrap_or(CmpShape::Any);
                Some(CmpShape::Ref(m, Box::new(p)))
            }
            _ if self.cmp_rhs_open(t, trait_def) => None,
            _ => Some(CmpShape::Exact(t)),
        }
    }

    /// True when type `t` fits `shape` (an `Exact` part unifies).
    fn cmp_shape_fits(&mut self, t: Ty, shape: &CmpShape) -> bool {
        match shape {
            CmpShape::Any => true,
            CmpShape::Ref(m, p) => match self.kind(t) {
                TyKind::Ref(_, m2, inner) if m2 == *m => {
                    let inner = self.resolve(inner);
                    self.cmp_shape_fits(inner, p)
                }
                _ => false,
            },
            CmpShape::Exact(x) => self.unify(t, *x),
        }
    }

    /// True when `t` has more than one `trait_def` (`PartialEq` or
    /// `PartialOrd`) impl in std 1.99, so a method call leaves `Rhs` to
    /// the argument. A reference has two `PartialEq` blanket impls (`&A`
    /// with `&B` and with `&mut B`) and one `PartialOrd` (its pointee's
    /// answer). Literal variables have one impl per type.
    pub(super) fn cmp_rhs_open(&mut self, t: Ty, trait_def: DefId) -> bool {
        let eq = trait_def == self.p.gx.lang.partial_eq;
        match self.kind(t) {
            TyKind::Ref(_, _, inner) => eq || self.cmp_rhs_open(inner, trait_def),
            TyKind::Infer(v) => v.is_int() || v.is_float(),
            TyKind::Str | TyKind::Array(..) | TyKind::Slice(_) => eq,
            _ if self.tys.is_string_ty(t) || self.tys.vec_elem(t).is_some() => eq,
            _ if crate::check::collect::cow_arg(&self.tys, t).is_some() => true,
            _ => {
                let Some(a) = self.tys.local_adt(t) else { return false };
                if method::std_display_path(self.p, a) {
                    let path = self.p.display_path(self.p.adt(a).name);
                    let seg = path.rsplit("::").next().unwrap_or("");
                    return match seg {
                        "OsStr" | "OsString" | "Ipv4Addr" | "Ipv6Addr" | "IpAddr" | "Path" | "PathBuf" => true,
                        "VecDeque" | "CString" => eq,
                        _ => false,
                    };
                }
                // A user type: its own impls of the trait, any `Rhs`.
                let Some((def, _)) = self.tys.adt_parts(t) else { return false };
                use crate::traits::index::SelfHead;
                {
                    let index = &self.p.gx.index;
                    index.impls_of_trait(trait_def).iter().filter(|&&id| index.peek(id).head == SelfHead::Adt(def) && index.get(id).head == SelfHead::Adt(def)).count() > 1
                }
            }
        }
    }

    /// `x.into()` where the target is a scalar type core has a
    /// `From` impl for: the call is the same widening cast as
    /// `Target::from(x)` (lowered as `PrimOpKind::IntoCast`). The target must be
    /// known here (an annotation, a return type, a template
    /// replay through an `Into` bound): a target fixed only
    /// later declines to the trait search, which handles user
    /// types. A scalar target with no core impl also declines,
    /// so the plain obligation error can report.
    #[allow(clippy::too_many_arguments)]
    fn prim_into_method(
        &mut self,
        e: ExprId,
        base: Ty,
        derefs: u8,
        name: Sym,
        name_span: Span,
        args: &[ExprId],
        turbofish: &[ast::GenericArg],
        expected: Option<Ty>,
        builtin_only: bool,
    ) -> Option<Ty> {
        // Core's blanket `Into` applies at the first autoderef step, so
        // on a receiver reached through a deref Self is the reference
        // (or Box) type, which no scalar `From` impl takes (rustc E0277
        // for `let x: i64 = (&3i32).into()`).
        if !turbofish.is_empty() || self.name(name) != "into" || derefs > 0 {
            return None;
        }
        // An instance replays the template's `T: Into<U>` evidence, so
        // the target is known even with no expected type.
        let into = self.p.gx.lang.into;
        let replayed = self.replayed_trait_ref(e, into).and_then(|r| self.tys.args(r.args).get(1).and_then(|g| g.as_ty()));
        let dst = match replayed {
            Some(t) => t,
            None => self.deep(expected?),
        };
        let src_kind = self.kind(base);
        let dst_kind = self.kind(dst);
        if !Self::numeric_from_ok(src_kind, dst_kind) {
            return None;
        }
        // Core's set is between concrete scalar types; an
        // inference-variable side stays the trait search's call.
        if !matches!(src_kind, TyKind::Int(_) | TyKind::Float(_) | TyKind::Bool | TyKind::Char) {
            return None;
        }
        if !builtin_only && self.prim_lang_guard(name, name_span, args, self.p.gx.lang.into, base) {
            return Some(ERROR);
        }
        self.check_args(&[], args, name_span);
        self.set_res(e, Res::PrimOp { kind: PrimOpKind::IntoCast, derefs });
        Some(dst)
    }

    /// `x.into_iter()` where `x` is an iterator (a builtin iterator, a
    /// range, a user `impl Iterator`, or `T: Iterator` in a template):
    /// core's blanket `impl<I: Iterator> IntoIterator for I` returns the
    /// receiver itself. By value only (through a deref rustc would move
    /// out of a borrow), except a `&mut I` receiver (`rt`): `&mut I` is an
    /// iterator itself, so its first probe step takes it by value.
    #[allow(clippy::too_many_arguments)]
    fn into_iter_self(&mut self, e: ExprId, rt: Ty, base: Ty, derefs: u8, name: Sym, args: &[ExprId], turbofish: &[ast::GenericArg]) -> Option<Ty> {
        if !args.is_empty() || !turbofish.is_empty() || self.name(name) != "into_iter" {
            return None;
        }
        let rt = self.deep(rt);
        let (base, derefs) = match (derefs, self.kind(rt)) {
            (0, _) => (base, 0),
            (1, TyKind::Ref(_, Mut::Mut, inner)) if self.deep(inner) == self.deep(base) => (rt, 0),
            _ => return None,
        };
        let base = self.deep(base);
        if matches!(self.kind(base), TyKind::Infer(_) | TyKind::Error) {
            return None;
        }
        // `&mut I` is an iterator when `I` is (core's `impl<I: Iterator +
        // ?Sized> Iterator for &mut I`): `r.into_iter()` with `r: &mut
        // array::IntoIter<T, N>`, or `I = &mut ..` in an instance.
        let probe = match self.kind(base) {
            TyKind::Ref(_, Mut::Mut, inner) => self.deep(inner),
            _ => base,
        };
        let args_id = self.tys.intern_args(&[GenericArg::Ty(probe)]);
        let tr = TraitRef { def: self.p.gx.lang.iterator, args: args_id, bindings: EMPTY_BINDINGS };
        // A trial: the selection's nested obligations (`impl<T> Iterator
        // for Gen<T>` queues `?T: Sized`) go with its variables, or the
        // queue keeps an unbound `?T: Sized` to body end (L0610).
        let snap = self.snapshot_vars();
        let obl_len = self.obl_len();
        let is_iter = crate::ty::iter::is_iter(&self.tys, probe)
            || self.tys.is_chars_ty(probe)
            || matches!(self.select_obligation(tr), Selection::Impl { .. } | Selection::ParamEvidence(_));
        self.rollback_vars(snap);
        self.obl_truncate(obl_len);
        if !is_iter {
            return None;
        }
        self.set_res(e, Res::PrimOp { kind: PrimOpKind::IntoIterSelf, derefs });
        Some(base)
    }

    /// Checks a method call, walking a receiver chain (`x.m().m()...`,
    /// up to the parser's 2000-link cap) in a loop: collect the spine,
    /// run the turbofish lifetime rejects outermost first (the order
    /// the recursive walk ran them), check the base receiver, then
    /// fold `method_call_with_rt` back up. A spine of one goes through
    /// `method_call` exactly as before.
    fn method_chain(
        &mut self,
        e: ExprId,
        recv: ExprId,
        name: Sym,
        name_span: Span,
        args: &[ExprId],
        generic_args: &[ast::GenericArg],
        expected: Option<Ty>,
    ) -> Ty {
        let p = self.p;
        let mut spine: Vec<(ExprId, ExprId, Sym, Span, &[ExprId], &[ast::GenericArg])> =
            vec![(e, recv, name, name_span, args, generic_args)];
        let mut cur = recv;
        while let Expr::MethodCall { recv: r, name: n, name_span: ns, generic_args: g, args: a } = p.ast.expr(cur) {
            spine.push((cur, *r, *n, *ns, a, g));
            cur = *r;
        }
        for (_, _, n, _, a, g) in &spine {
            let seg = ast::PathSeg { name: *n, args: ast::GenericArgs::Angle(g.to_vec()) };
            self.lifetime_turbofish(std::slice::from_ref(&seg));
        }
        let writes: Vec<(ExprId, ExprId, Span)> =
            spine.iter().filter(|s| p.interner.get(s.2) == "write_fmt").map(|s| (s.0, s.1, s.3)).collect();
        let calls: Vec<(ExprId, ExprId)> = spine.iter().map(|s| (s.0, s.1)).collect();
        let rt = if spine.len() == 1 {
            self.method_call(e, recv, name, name_span, args, generic_args, expected)
        } else {
            let mut rt = self.expr(cur, None);
            let n = spine.len();
            for (i, (node, r, nm, ns, a, g)) in spine.into_iter().rev().enumerate() {
                let outer = i + 1 == n;
                rt = self.method_call_with_rt(node, r, rt, nm, ns, a, g, if outer { expected } else { None });
                if !outer {
                    self.set(node, rt);
                }
            }
            rt
        };
        // A by-value `self` moves the receiver: an unsized place
        // (`v[1..].into()` under `where [T]: Into<U>`) is rustc E0508/E0161.
        for (node, r) in calls {
            if let Res::Method { derefs: 0, autoref: Autoref::None, .. } = self.out.res(node) {
                self.reject_unsized_value(r);
            }
        }
        // `write!` into a user `io::Write` type (W-SHIM, check/platform.rs).
        for (node, r, ns) in writes {
            if let Res::Method { f, .. } = self.out.res(node) {
                let mut w = self.deep(self.out.ty(r));
                while let TyKind::Ref(_, _, inner) = self.kind(w) {
                    w = inner;
                }
                if let Some(d) = crate::check::platform::user_write_fmt_call(p, &self.tys, f, w, ns) {
                    self.errs.push(d);
                }
            }
        }
        rt
    }

    fn method_call(
        &mut self,
        e: ExprId,
        recv: ExprId,
        name: Sym,
        name_span: Span,
        args: &[ExprId],
        turbofish: &[ast::GenericArg],
        expected: Option<Ty>,
    ) -> Ty {
        let rt = self.expr(recv, None);
        self.method_call_with_rt(e, recv, rt, name, name_span, args, turbofish, expected)
    }

    /// `method_call` with the receiver already checked to type `rt`
    /// (before `deep`); `recv` is still named for the borrow and
    /// packed-field checks inside. Split out so `expr_inner` can check
    /// a method chain (`x.m().m()...`) in a loop instead of recursing
    /// down its receiver spine.
    fn method_call_with_rt(
        &mut self,
        e: ExprId,
        recv: ExprId,
        rt: Ty,
        name: Sym,
        name_span: Span,
        args: &[ExprId],
        turbofish: &[ast::GenericArg],
        expected: Option<Ty>,
    ) -> Ty {
        self.forget_place_steps(e, false);
        let rt = self.deep(rt);
        self.call_expected = expected.map(|t| (e, t));
        // ARCH 2.12 run point: a method call must know the receiver type. The
        // obligation queue runs just before that head is required (ARCH 2.4).
        self.run_obligations(false);
        self.method_call_at(e, recv, rt, name, name_span, args, turbofish, expected)
    }

    /// `method_call` once the receiver's type `rt` is known: also the
    /// step through a Cow's `&B` view (check/cow.rs), with `rt` the view.
    #[allow(clippy::too_many_arguments)]
    pub(super) fn method_call_at(
        &mut self,
        e: ExprId,
        recv: ExprId,
        rt: Ty,
        name: Sym,
        name_span: Span,
        args: &[ExprId],
        turbofish: &[ast::GenericArg],
        expected: Option<Ty>,
    ) -> Ty {
        let p = self.p;
        let k = &*p.known;
        // `Box` is a builtin deref step for method calls, as in
        // Rust. Its own `clone` is found before the step (it is
        // the one Box method this wave resolves at step zero),
        // so that name keeps the unpeeled receiver.
        // `Box<str>::into_string` and `String::into_boxed_str` by value
        // (check/own.rs), found before the deref step.
        if let Some(r) = self.own_by_value_method(e, rt, name, args, name_span) {
            return r;
        }
        // `Box<[T]>`'s by-value methods, found before the deref step.
        if let Some(el) = self.tys.boxed_slice_elem(self.resolve(rt)) {
            match self.name(name) {
                "into_vec" => {
                    self.set_res(e, Res::BuiltinMethod { b: Builtin::BoxSliceIntoVec, derefs: 0, autoref: Autoref::None });
                    self.check_args(&[], args, name_span);
                    return self.tys.mk_vec(el);
                }
                // Rust 2024 iterates a boxed slice by value here.
                "into_iter" => {
                    self.set_res(e, Res::BuiltinMethod { b: Builtin::BoxSliceIntoIter, derefs: 0, autoref: Autoref::None });
                    self.check_args(&[], args, name_span);
                    return crate::ty::iter::mk_iter(&mut self.tys, crate::ty::iter::IterKind::VecIntoIter, &[el]);
                }
                _ => {}
            }
        }
        // `clone_from` is the smart pointer's own method too, like
        // `clone`: it keeps the unpeeled receiver.
        let (derefs, base) = if name == k.clone || self.name(name) == "clone_from" {
            // A `RefCell` guard has no `clone` method of its own (only
            // the associated `Ref::clone`): the call clones the value.
            let (mut d, mut b) = self.autoderef(rt);
            while let Some((inner, _)) = self.tys.guard_elem(b) {
                let (d2, b2) = self.autoderef(self.resolve(inner));
                d += 1 + d2;
                b = b2;
            }
            (d, b)
        } else {
            self.autoderef_smart(rt)
        };
        // A private inherent method of the name is no candidate: a visible
        // trait method may answer instead, and a miss reports it private.
        if let Some(a) = self.tys.local_adt(base)
            && self.assoc_private(a, name)
        {
            self.private_inherent.push((e, a));
        }
        let bk = self.tys.kind(base);
        // ARCH 2.12: a method call needs a known receiver head (rustc
        // E0282, also for a closure parameter a later call would fix).
        if let TyKind::Infer(v) = bk
            && !v.is_int()
            && !v.is_float()
        {
            self.err(
                "L0610",
                name_span,
                "type annotations needed: the receiver type must be known here",
                "Annotate the receiver's type, for example the closure parameter as `|x: Vec<u8>|`.",
            );
            for &a in args {
                self.expr(a, None);
            }
            return ERROR;
        }
        // `extend` on a source-written collection whose item or element
        // type is open (check/extend.rs): rustc E0283/E0282, before the
        // impl probe picks one.
        if self.name(name) == "extend"
            && let Some(ret) = self.source_extend(e, base, derefs, args)
        {
            return ret;
        }
        // User methods, through the method-set probes of section 2.10: every
        // form is probed in order and recorded, hit or miss, before the
        // builtin compat dispatch below runs.
        let head = Head::of(&self.tys, base);
        // Turbofish args of the method (`x.m::<U>(..)`), resolved
        // in this body's scope for the generic probes below. A `'static`
        // on a reference in the turbofish of a `core::any` method
        // (`downcast_ref::<&'static str>()`) is the elided form, since
        // `T: 'static` there; it resolves, and a call that turns out to be
        // another method reports it below (L0203). With no user method
        // of that name, every std one bounds its `T` by `'static`
        // (`Any`, `Error`).
        let p = self.p;
        let any_static = matches!(self.name(name), "is" | "downcast_ref" | "downcast_mut" | "downcast")
            && !p.methods.keys().any(|(_, m)| *m == name)
            && !p.gx.traits_by_method.get(&name).is_some_and(|ts| ts.iter().any(|t| p.gx.index.trait_record(*t).is_some_and(|r| r.local)))
            && turbofish.iter().any(|a| {
                matches!(a, ast::GenericArg::Type(t) if generics::names_lifetime(&p.ast, &p.interner, *t)
                    && !generics::names_lifetime_beyond_static_refs(&p.ast, &p.interner, *t))
            });
        let explicit: Vec<Option<GenericArg>> = turbofish
            .iter()
            .map(|a| match a {
                ast::GenericArg::Type(t) if any_static => Some(GenericArg::Ty(self.resolve_annotation(*t))),
                // `x.m::<N>()` with `N` a const parameter of the body or a
                // const item: the parser reads it as a type path (tf-p5,
                // `as_chunks::<N>`).
                ast::GenericArg::Type(t) => self.written_type_arg(*t),
                ast::GenericArg::Const(e2) => Some(self.const_call_arg(*e2)),
                _ => None,
            })
            .collect();
        // A call the template check resolved through a trait keeps
        // that trait in every other check of the body (ARCH 4.1):
        // selection on this body's Self type picks the impl, and no
        // method lookup runs again.
        let mut builtin_only = false;
        if let Some(pick) = self.replay_pick(e) {
            match picks::replay_method(self, e, rt, pick, name, name_span, args, &explicit, expected) {
                Some(ret) => return ret,
                None => builtin_only = true,
            }
        }
        // A user trait's method next to a std item of the same name: who
        // wins in rustc's probe order (check/std_inherent.rs).
        if !builtin_only && let Some(ret) = self.std_shadow_call(e, rt, base, name, name_span, args, &explicit, expected) {
            return ret;
        }
        // `deref`/`deref_mut` whose first hit in rustc's probe is a std
        // impl (core's `&T`, Box, Cow, ...) answer before the user and Cow
        // searches, which would deref further (check/convert.rs).
        if !builtin_only
            && turbofish.is_empty()
            && args.is_empty()
            && matches!(self.p.interner.get(name), "deref" | "deref_mut")
            && let drt = self.deep(rt)
            && let Some(ret) = self.deref_call(e, recv, drt, self.p.interner.get(name) == "deref_mut", name_span)
        {
            return ret;
        }
        // `clone`/`clone_from` whose Self is a reference (core's `Clone for
        // &T`): rustc's probe stops at the first shared reference step, so
        // `(&&s).clone()` is `&String`, never `S::clone` on the pointee.
        if !builtin_only
            && turbofish.is_empty()
            && let Some(ret) = self.ref_clone_call(e, recv, rt, name, name_span, args)
        {
            return ret;
        }
        // The inherent methods of `core::cmp::Ordering` (no user
        // impl can add inherent methods to it).
        if let Some(ret) = self.ordering_method(e, base, derefs, name, name_span, args) {
            return ret;
        }
        // `type_id`, `is`, and the downcasts of `core::any` (check/any.rs).
        if let Some(ret) = self.any_method(e, rt, name, name_span, args, turbofish, &explicit, expected) {
            return ret;
        }
        if any_static {
            for a in turbofish {
                if let ast::GenericArg::Type(t) = a {
                    self.resolve_written(*t);
                }
            }
        }
        // `LocalKey` methods on a `thread_local!` static (check/tls.rs).
        if let Some(ret) = self.tls_method(e, recv, base, derefs, name, name_span, args) {
            return ret;
        }
        // The inherent methods of `core::ops::Bound<T>` (same).
        if let Some(ret) = self.bound_adt_method(e, recv, base, derefs, name, name_span, args) {
            return ret;
        }
        // The inherent methods of `core::num::NonZero<T>` (same).
        if let Some(ret) = self.nonzero_adt_method(e, recv, base, derefs, name, name_span, args) {
            return ret;
        }
        // The inherent methods of `core::mem::MaybeUninit<T>` (same).
        if let Some(ret) = self.maybe_uninit_method(e, recv, base, derefs, name, name_span, args) {
            return ret;
        }
        // `WaitTimeoutResult::timed_out` (same).
        if let Some(ret) = self.wait_timeout_result_method(e, recv, base, derefs, name, name_span, args) {
            return ret;
        }
        // The inherent methods of `alloc::borrow::Cow` (W-STD-B).
        if let Some(ret) = self.cow_method(e, recv, base, derefs, name, name_span, args) {
            return ret;
        }
        // Generic and trait receivers go through the full 2.10
        // search (check/method.rs), which probes plain inherent
        // methods with the same recorded reads, in step+form
        // order. Builtin and scalar receivers stay on the path
        // below.
        if self.generic_mode()
            && !builtin_only
            && (self.tys.local_adt(base).is_some()
                || matches!(self.tys.kind(base), TyKind::Param(_) | TyKind::Projection(..) | TyKind::Dyn(..) | TyKind::Opaque(..)))
        {
            match method::generic_method_search(self, e, rt, name, name_span, args, &explicit, expected) {
                method::Probe::Hit(ret) => return ret,
                method::Probe::Failed => return ERROR,
                method::Probe::Miss => {}
            }
        }
        // Std source methods of `Option` and `Result` (library/core,
        // W-STD-A): generic inherent templates on the builtin def,
        // probed by receiver form like a generic user Adt's.
        if !builtin_only
            && matches!(self.tys.builtin_of(base), Some(BuiltinTy::Option | BuiltinTy::Result))
            && let Some((def, _)) = self.tys.adt_parts(base)
            && p.gx.inherent_methods.contains_key(&(def, name))
        {
            for form in ReceiverForm::PROBE_ORDER {
                let probe = method::RcvProbe::at(self, base, form);
                if p.gx.inherent_methods.get(&(def, name)).is_some_and(|ts| ts.len() > 1)
                    && method::inherent_template_fits(self, e, probe, name, name_span) > 1
                {
                    // `as_deref` on a still-open payload defers to body
                    // end instead (fx-option-rest): core has one impl
                    // over `T: Deref`, so rustc has no ambiguity to
                    // report here; lust's per-type impls pick at finish.
                    if matches!(self.name(name), "as_deref" | "as_deref_mut") {
                        if probe.autoref != Autoref::None {
                            self.check_packed_borrow(recv, name_span);
                        }
                        self.check_args(&[], args, name_span);
                        // Typed as the method's result shape over a
                        // fresh target, so a chained call can type
                        // and can itself fix the target.
                        let mutable = self.name(name) == "as_deref_mut";
                        let target = self.new_var(false);
                        let rt = self.tys.mk_ref(mutable, target);
                        let ret = if matches!(self.tys.builtin_of(base), Some(BuiltinTy::Option)) {
                            self.tys.mk_option(rt)
                        } else {
                            let e_ty = self.tys.result_args(base).map_or(ERROR, |(_, e2)| e2);
                            let re = self.tys.mk_ref(mutable, e_ty);
                            self.tys.mk_result(rt, re)
                        };
                        self.deferred_lang_methods.push(method::DeferredLangMethod {
                            e,
                            base,
                            form,
                            derefs,
                            name,
                            name_span,
                            ret,
                            explicit: explicit.clone(),
                        });
                        return ret;
                    }
                    self.err(
                        "L0610",
                        name_span,
                        format!("type annotations needed: more than one `{}` method fits this receiver", self.name(name)),
                        "Annotate the receiver's type, for example `let x: Option<&i32> = ..`.",
                    );
                    for &a in args {
                        self.expr(a, None);
                    }
                    return ERROR;
                }
                let hit = match method::inherent_template_probe(self, e, probe, derefs, name, name_span, args, &explicit) {
                    method::Probe::Miss => method::lang_plain_probe(self, e, probe, derefs, name, name_span, args),
                    other => other,
                };
                match hit {
                    method::Probe::Hit(ret) => {
                        if probe.autoref != Autoref::None {
                            self.check_packed_borrow(recv, name_span);
                        }
                        return ret;
                    }
                    method::Probe::Failed => return ERROR,
                    method::Probe::Miss => {}
                }
            }
        }
        // Every candidate of every form, in probe order. The set
        // is keyed by the template Adt head, so a candidate only
        // counts when its receiver type unifies with this
        // receiver (a method of `impl W<u8>` does not apply to
        // `W<u32>`); templates confirm inside their probe.
        let mut assoc_fn_seen = false;
        for form in ReceiverForm::PROBE_ORDER {
            if builtin_only {
                break;
            }
            let set = p.method_set(&mut self.out.reads, head, name, form);
            for c in set.candidates {
                if matches!(head, Head::Adt(d) if self.private_inherent.iter().any(|&(x, a)| x == e && p.def_of_adt(a) == d)) {
                    continue;
                }
                let Some(cform) = c.receiver else {
                    assoc_fn_seen = true;
                    continue;
                };
                let f = p.local_def(c.def.hash).expect("a method candidate names a local fn");
                if !turbofish.is_empty() && p.gx.fn_templates.get(f.0 as usize).is_none_or(|t| t.is_none()) {
                    self.errs.push(not_yet("L0721", name_span, "turbofish on method calls"));
                    for &a in args {
                        self.expr(a, None);
                    }
                    return ERROR;
                }
                // A generic inherent method: instantiate it like a
                // generic call, with the receiver unifying the impl
                // and method parameters.
                if p.gx.fn_templates.get(f.0 as usize).is_some_and(|t| t.is_some()) {
                    let probe = method::RcvProbe::at(self, base, cform);
                    match method::inherent_template_probe(self, e, probe, derefs, name, name_span, args, &explicit) {
                        method::Probe::Hit(ret) => return ret,
                        method::Probe::Failed => return ERROR,
                        method::Probe::Miss => continue,
                    }
                }
                let probe = method::RcvProbe::at(self, base, cform);
                let (params, ret) = match p.sig_of(&mut self.out.reads, c.def) {
                    SigOf::Fn(info) => (info.params.clone(), p.local_def(c.def.hash).map_or(info.ret, |f| p.ret_view(f))),
                    _ => return ERROR,
                };
                let ret = self.callee_ret(ret);
                let snap_vars = self.snapshot_vars();
                let obl_len = self.obl_len();
                if params.first().is_none_or(|&want| !self.unify(want, probe.recv_ty)) {
                    self.rollback_vars(snap_vars);
                    self.obl_truncate(obl_len);
                    // A typed receiver (`self: Box<Self>`, `self:
                    // &Rc<Self>`): it buckets as Value, so match
                    // it by its written receiver type against the
                    // unpeeled receiver (ARCH 2.10 step 3).
                    if p.fn_info(f).self_kind == Some(ast::SelfKind::Typed)
                        && let Some(&want) = params.first()
                        && let Some((td, ta)) = self.typed_receiver_adjust(rt, want)
                    {
                        if ta != Autoref::None {
                            self.check_packed_borrow(recv, name_span);
                        }
                        self.set_res(e, Res::Method { f, derefs: td, autoref: ta });
                        self.check_args(&params[1.min(params.len())..], args, name_span);
                        return ret;
                    }
                    continue;
                }
                if probe.autoref != Autoref::None {
                    self.check_packed_borrow(recv, name_span);
                }
                self.set_res(e, Res::Method { f, derefs, autoref: probe.autoref });
                self.check_args(&params[1.min(params.len())..], args, name_span);
                return ret;
            }
        }
        // An associated fn of the name (no `self`) is no method
        // candidate: the probe goes on (trait methods, later deref
        // steps such as `LazyLock<HashMap<..>>::get`), as in rustc, and
        // only a miss reports it (E0599's note).
        if name == k.clone {
            if has_clone(p, &self.tys, base) {
                self.record_glue_reads(p.gx.lang.clone, base);
                self.check_packed_borrow(recv, name_span);
                self.set_res(e, Res::BuiltinMethod { b: Builtin::Clone, derefs, autoref: Autoref::Ref });
                self.check_args(&[], args, name_span);
                return base;
            }
            // A std container whose element a later use fixes (`let w =
            // v.clone(); v.push(1u8)`): its builtin clone, with `base:
            // Clone` checked at body end, as rustc's pending obligation.
            if self.open_std_clone_head(base) {
                self.record_glue_reads(p.gx.lang.clone, base);
                self.check_packed_borrow(recv, name_span);
                self.deferred_clone.push((base, name_span));
                self.set_res(e, Res::BuiltinMethod { b: Builtin::Clone, derefs, autoref: Autoref::Ref });
                self.check_args(&[], args, name_span);
                return base;
            }
        }
        // `clone_from` with no written fn: the `clonefrom` glue
        // (derived and core bodies) at a `Clone` receiver. A hash
        // table's own `clone_from` reuses its bucket array in ways
        // the glue does not model, so a receiver holding one stays
        // a precise reject instead of a wrong capacity or order.
        if self.name(name) == "clone_from" && has_clone(p, &self.tys, base) && mentions_hash_table(p, &self.tys, base) {
            self.errs.push(not_yet("L0640", name_span, "`clone_from` on a type holding a hash table"));
            for &a in args {
                self.expr(a, None);
            }
            return ERROR;
        }
        if self.name(name) == "clone_from" && has_clone(p, &self.tys, base) {
            self.record_glue_reads(p.gx.lang.clone, base);
            self.check_packed_borrow(recv, name_span);
            self.set_res(e, Res::BuiltinMethod { b: Builtin::CloneFrom, derefs, autoref: Autoref::RefMut });
            let src = self.tys.mk_ref(false, base);
            self.check_args(&[src], args, name_span);
            return UNIT;
        }
        // Comparison trait methods on a scalar receiver
        // (`partial_cmp`, `cmp`, `eq`, `lt`, and kin in method
        // form): the template side is the lang stub, the instance
        // side is the scalar comparison itself.
        if let Some(ret) = self.prim_cmp_method(e, recv, base, derefs, name, name_span, args, turbofish, builtin_only) {
            return ret;
        }
        // Operator trait methods on a scalar receiver, likewise.
        if let Some(ret) = self.prim_op_method(e, recv, base, derefs, name, name_span, args, turbofish, builtin_only) {
            return ret;
        }
        // `into()` to a scalar target core has a `From` impl for.
        if let Some(ret) = self.prim_into_method(e, base, derefs, name, name_span, args, turbofish, expected, builtin_only) {
            return ret;
        }
        // `into()` through a std `From` impl lust keeps builtin (check/into.rs).
        if let Some(ret) = self.builtin_into_method(e, rt, name, args, turbofish, expected) {
            return ret;
        }
        // `try_into()` to a scalar target: the checked cast
        // (check/tryfrom.rs).
        if let Some(ret) = self.prim_try_into_method(e, base, derefs, name, name_span, args, turbofish, expected, builtin_only) {
            return ret;
        }
        // `try_into()` on a `Box<[T]>` value: alloc's `TryFrom<Box<[T]>>
        // for Box<[T; N]>`, picked at the first autoderef step (by
        // value), before the slice under the box (check/tryfrom.rs).
        let rt_box = self.deep(rt);
        if self.tys.boxed_slice_elem(rt_box).is_some()
            && let Some(ret) = self.vec_try_into_method(e, rt_box, 0, name, name_span, args, turbofish, expected, builtin_only)
        {
            return ret;
        }
        // `try_into()` from a slice to an array target (check/tryfrom.rs).
        if let Some(ret) = self.slice_try_into_method(e, rt, base, derefs, name, name_span, args, turbofish, expected, builtin_only) {
            return ret;
        }
        // `try_into()` from a Vec to an array target (check/tryfrom.rs).
        if let Some(ret) = self.vec_try_into_method(e, base, derefs, name, name_span, args, turbofish, expected, builtin_only) {
            return ret;
        }
        // `into_iter()` on a value that is its own iterator.
        if let Some(ret) = self.into_iter_self(e, rt, base, derefs, name, args, turbofish) {
            return ret;
        }
        // `into()` through std's other `From` impls between builtin
        // types (check/convert.rs, W-STD-B).
        if let Some(ret) = self.std_into_method(e, rt, name, args, turbofish, expected) {
            return ret;
        }
        // `into()` with a known receiver and a target a later statement
        // fixes: typed by a fresh target, resolved at body end
        // (`deferred_into`).
        if args.is_empty()
            && turbofish.is_empty()
            && self.name(name) == "into"
            && !builtin_only
            && expected.is_none_or(|t| matches!(self.kind(self.resolve(t)), TyKind::Infer(v) if !v.is_int() && !v.is_float()))
            && self.replayed_trait_ref(e, self.p.gx.lang.into).is_none()
        {
            let src = self.deep(rt);
            if !self.tys.flags(src).contains_infer() && !self.has_error_kind(src) && !matches!(self.kind(src), TyKind::Param(_) | TyKind::Projection(..) | TyKind::Opaque(..)) {
                let dst = match expected {
                    Some(t) => t,
                    None => self.new_var(false),
                };
                self.check_args(&[], args, name_span);
                self.deferred_into.push((e, rt, dst, name, name_span));
                return dst;
            }
        }
        // Slice inherent methods on slices, arrays, and Vecs
        // (check/slice.rs).
        if let Some(ret) = self.slice_method(e, recv, base, derefs, name, name_span, args, turbofish) {
            return ret;
        }
        // `Vec::drain` and `String::drain` (check/iter.rs).
        if let Some(ret) = self.drain_method(e, recv, base, derefs, name, name_span, args, turbofish) {
            return ret;
        }
        // `start_bound` and `end_bound` on a builtin range value.
        if let Some(ret) = self.bound_method(e, base, derefs, name, name_span, args, turbofish, expected) {
            return ret;
        }
        // `contains`, `is_empty`, and `RangeInclusive::start/`end`.
        if let Some(ret) = self.range_query_method(e, base, derefs, name, name_span, args, turbofish) {
            return ret;
        }
        // Iterator sources on sequences and every method on a builtin
        // iterator (check/iter.rs, W-STD-A).
        // The turbofish type is resolved once, above: the iterator
        // methods take it from here (a second resolution left the
        // first one's `_: Sized` obligations unbound, W-STD-C).
        self.turbofish_ty = explicit.first().copied().flatten().and_then(|g| g.as_ty());
        let iter_ret = self.iter_method(e, recv, rt, base, derefs, name, name_span, args, turbofish, expected);
        self.turbofish_ty = None;
        if let Some(ret) = iter_ret {
            return ret;
        }
        // `str::parse` (tf-str, check/split.rs): ahead of the
        // turbofish-free hooks below, as it takes a turbofish.
        if let Some(ret) = self.str_parse_method(e, base, derefs, name, name_span, args, turbofish) {
            return ret;
        }
        // `write!` (`write_fmt(format_args!(..))`), Formatter and builder
        // methods, and `fmt` on builtin values (check/fmt.rs, W-STD-B).
        if turbofish.is_empty() {
            if self.p.interner.get(name) == "write_fmt"
                && let Some(ret) = self.write_fmt_call(e, recv, base, derefs, name_span, args)
            {
                return ret;
            }
            if let Some(ret) = self.fmt_method(e, recv, rt, base, derefs, name, name_span, args) {
                return ret;
            }
            // AsRef, AsMut, Borrow, BorrowMut, ToOwned on builtin values
            // (check/convert.rs, W-STD-B).
            if let Some(ret) = self.convert_method(e, recv, rt, name, name_span, args, expected) {
                return ret;
            }
            // `extend` on Vec and String (check/extend.rs, W-STD-B), and on
            // a type parameter through its `Extend<A>` bound.
            if self.p.interner.get(name) == "extend"
                && let Some(ret) = self.seq_extend(e, recv, base, derefs, name_span, args).or_else(|| self.param_extend(e, base, derefs, name_span, args))
            {
                return ret;
            }
            // HashMap, HashSet, and Entry methods (check/hashmap.rs).
            if let Some(ret) = self.hash_coll_method(e, recv, rt, base, derefs, name, name_span, args) {
                return ret;
            }
            // `x.hash(&mut h)`, `s.hash_one(x)`, and Hasher methods on a
            // concrete hasher (check/hashmap.rs).
            if let Some(ret) = self.hasher_method(e, base, derefs, name, name_span, args) {
                return ret;
            }
            // The str split family (check/split.rs).
            if let Some(ret) = self.str_split_method(e, base, derefs, name, name_span, args) {
                return ret;
            }
            // The str search, trim, and matches methods over a
            // `Pattern` (check/split.rs, tf-str).
            if let Some(ret) = self.str_search_method(e, base, derefs, name, name_span, args) {
                return ret;
            }
        }
        // `Ord::max`/`min`/`clamp` on a receiver reached through a
        // deref resolve at the first autoderef step when the receiver
        // type itself is `Ord` (`&A`, `Box<A>`): Self is that type, so
        // the arguments and the result have it too (`(&3).max(5)` is
        // rustc E0308). A user trait with a method of the name could
        // also apply there (rustc E0034); that case stays unsupported.
        if derefs > 0 && matches!(self.name(name), "max" | "min" | "clamp") && has_total_ord(p, &self.tys, rt) {
            let user_trait = p.gx.traits_by_method.get(&name).is_some_and(|ds| ds.iter().any(|&d| d != p.gx.lang.ord));
            if !user_trait && let Some(ret) = self.ord_pick_method(e, recv, rt, 0, name, name_span, args) {
                return ret;
            }
            for &a in args {
                self.expr(a, None);
            }
            self.errs.push(not_yet("L0614", name_span, "`Ord` methods on this receiver type"));
            return ERROR;
        }
        // `Weak`, `RefCell`, and `Cell` methods (check/cells.rs).
        if let Some(ret) = self.cell_method(e, recv, base, derefs, name, name_span, args) {
            return ret;
        }
        // Atomic and other sync methods (check/sync.rs).
        if let Some(ret) = self.sync_method(e, recv, base, derefs, name, name_span, args) {
            return ret;
        }
        if let Some(ret) = self.utf8_method(e, recv, base, derefs, name, name_span, args) {
            return ret;
        }
        // `std::panic::Location` (check/caller.rs).
        if let Some(ret) = self.location_method(e, recv, base, derefs, name, name_span, args) {
            return ret;
        }
        use Builtin as B;
        // Builtin methods dispatch on the v2 builtin def in the first slot and on
        // the general kind in the second; user Adts were handled above.
        let found: Option<(B, Autoref, Vec<Ty>, Ty)> = match (self.tys.builtin_of(base), bk) {
            // The safe raw pointer methods (w-cinterop).
            (None, TyKind::RawPtr(m, inner)) => self.ptr_method(name, m, inner, &explicit, name_span),
            (Some(BuiltinTy::String), _) => {
                if name == k.len {
                    Some((B::StringLen, Autoref::Ref, vec![], USIZE))
                } else if name == k.is_empty {
                    Some((B::StringIsEmpty, Autoref::Ref, vec![], BOOL))
                } else if name == k.push_str {
                    Some((B::StringPushStr, Autoref::RefMut, vec![REF_STR], UNIT))
                } else if name == k.push {
                    Some((B::StringPush, Autoref::RefMut, vec![CHAR], UNIT))
                } else if name == k.as_str {
                    Some((B::StringAsStr, Autoref::Ref, vec![], REF_STR))
                } else if self.name(name) == "as_mut_str" {
                    let r = self.tys.mk_ref(true, STR);
                    Some((B::StringAsMutStr, Autoref::RefMut, vec![], r))
                } else if name == k.to_string {
                    Some((B::ToString, Autoref::Ref, vec![], STRING))
                } else if name == k.capacity {
                    Some((B::StringCapacity, Autoref::Ref, vec![], USIZE))
                } else if name == k.reserve {
                    Some((B::StringReserve, Autoref::RefMut, vec![USIZE], UNIT))
                } else if name == k.reserve_exact {
                    Some((B::StringReserveExact, Autoref::RefMut, vec![USIZE], UNIT))
                } else if name == k.shrink_to_fit {
                    Some((B::StringShrinkToFit, Autoref::RefMut, vec![], UNIT))
                } else if name == k.shrink_to {
                    Some((B::StringShrinkTo, Autoref::RefMut, vec![USIZE], UNIT))
                } else if name == k.pop {
                    let opt = self.tys.mk_option(CHAR);
                    Some((B::StringPop, Autoref::RefMut, vec![], opt))
                } else if name == k.remove {
                    Some((B::StringRemove, Autoref::RefMut, vec![USIZE], CHAR))
                } else if name == k.insert {
                    Some((B::StringInsert, Autoref::RefMut, vec![USIZE, CHAR], UNIT))
                } else if name == k.insert_str {
                    Some((B::StringInsertStr, Autoref::RefMut, vec![USIZE, REF_STR], UNIT))
                } else if name == k.truncate {
                    Some((B::StringTruncate, Autoref::RefMut, vec![USIZE], UNIT))
                } else if name == k.clear {
                    Some((B::StringClear, Autoref::RefMut, vec![], UNIT))
                } else if name == k.split_off {
                    Some((B::StringSplitOff, Autoref::RefMut, vec![USIZE], STRING))
                } else if name == k.as_bytes {
                    let sl = self.tys.intern(TyKind::Slice(int(IntTy::U8)));
                    let r = self.tys.mk_ref(false, sl);
                    Some((B::StringAsBytes, Autoref::Ref, vec![], r))
                } else if name == k.into_bytes {
                    let v = self.tys.mk_vec(int(IntTy::U8));
                    Some((B::StringIntoBytes, Autoref::None, vec![], v))
                } else if self.name(name) == "as_ptr" {
                    Some((B::StrAsPtr, Autoref::Ref, vec![], self.tys.intern(TyKind::RawPtr(Mut::Shared, int(IntTy::U8)))))
                } else {
                    // String derefs to str, so it has every str method.
                    self.str_method(name)
                }
            }
            (None, TyKind::Str) => {
                if self.name(name) == "as_ptr" {
                    Some((B::StrAsPtr, Autoref::Ref, vec![], self.tys.intern(TyKind::RawPtr(Mut::Shared, int(IntTy::U8)))))
                } else if name == k.len {
                    Some((B::StrLen, Autoref::Ref, vec![], USIZE))
                } else if name == k.is_empty {
                    Some((B::StrIsEmpty, Autoref::Ref, vec![], BOOL))
                } else if name == k.to_string || name == k.to_owned {
                    Some((B::StrToString, Autoref::Ref, vec![], STRING))
                } else {
                    self.str_method(name)
                }
            }
            (Some(BuiltinTy::Vec), _) => {
                let elem = self.tys.adt_first_ty_arg(base).unwrap_or(ERROR);
                // Return types are built only in the arms that return them:
                // interning has no visible effect, so the common arms skip it.
                if name == k.len {
                    Some((B::VecLen, Autoref::Ref, vec![], USIZE))
                } else if name == k.is_empty {
                    Some((B::VecIsEmpty, Autoref::Ref, vec![], BOOL))
                } else if name == k.push {
                    Some((B::VecPush, Autoref::RefMut, vec![elem], UNIT))
                } else if name == k.pop {
                    let opt = self.tys.mk_option(elem);
                    Some((B::VecPop, Autoref::RefMut, vec![], opt))
                } else if name == k.get {
                    let r = self.tys.mk_ref(false, elem);
                    let opt_ref = self.tys.mk_option(r);
                    Some((B::VecGet, Autoref::Ref, vec![USIZE], opt_ref))
                } else if name == k.first {
                    let r = self.tys.mk_ref(false, elem);
                    let opt_ref = self.tys.mk_option(r);
                    Some((B::VecFirst, Autoref::Ref, vec![], opt_ref))
                } else if name == k.last {
                    let r = self.tys.mk_ref(false, elem);
                    let opt_ref = self.tys.mk_option(r);
                    Some((B::VecLast, Autoref::Ref, vec![], opt_ref))
                } else if name == k.contains {
                    self.deferred_eq.push((elem, name_span));
                    let r = self.tys.mk_ref(false, elem);
                    Some((B::VecContains, Autoref::Ref, vec![r], BOOL))
                } else if name == k.swap {
                    Some((B::VecSwap, Autoref::RefMut, vec![USIZE, USIZE], UNIT))
                } else if name == k.clear {
                    Some((B::VecClear, Autoref::RefMut, vec![], UNIT))
                } else if name == k.insert {
                    Some((B::VecInsert, Autoref::RefMut, vec![USIZE, elem], UNIT))
                } else if name == k.remove {
                    Some((B::VecRemove, Autoref::RefMut, vec![USIZE], elem))
                } else if name == k.truncate {
                    Some((B::VecTruncate, Autoref::RefMut, vec![USIZE], UNIT))
                } else if name == k.capacity {
                    Some((B::VecCapacity, Autoref::Ref, vec![], USIZE))
                } else if name == k.reserve {
                    Some((B::VecReserve, Autoref::RefMut, vec![USIZE], UNIT))
                } else if name == k.reserve_exact {
                    Some((B::VecReserveExact, Autoref::RefMut, vec![USIZE], UNIT))
                } else if name == k.shrink_to_fit {
                    Some((B::VecShrinkToFit, Autoref::RefMut, vec![], UNIT))
                } else if derefs == 0 && name == k.leak {
                    let sl = self.tys.intern(TyKind::Slice(elem));
                    Some((B::VecLeak, Autoref::None, vec![], self.tys.mk_ref(true, sl)))
                } else if derefs == 0 && self.name(name) == "into_boxed_slice" {
                    let sl = self.tys.intern(TyKind::Slice(elem));
                    Some((B::VecIntoBoxedSlice, Autoref::None, vec![], self.tys.mk_boxed(sl)))
                } else if name == k.shrink_to {
                    Some((B::VecShrinkTo, Autoref::RefMut, vec![USIZE], UNIT))
                } else if name == k.swap_remove {
                    Some((B::VecSwapRemove, Autoref::RefMut, vec![USIZE], elem))
                } else if name == k.append {
                    let r = self.tys.mk_ref(true, base);
                    Some((B::VecAppend, Autoref::RefMut, vec![r], UNIT))
                } else if name == k.extend_from_slice {
                    self.deferred_clone.push((elem, name_span));
                    let sl = self.tys.intern(TyKind::Slice(elem));
                    let r = self.tys.mk_ref(false, sl);
                    Some((B::VecExtendFromSlice, Autoref::RefMut, vec![r], UNIT))
                } else if name == k.split_off {
                    Some((B::VecSplitOff, Autoref::RefMut, vec![USIZE], base))
                } else if name == k.resize {
                    self.deferred_clone.push((elem, name_span));
                    Some((B::VecResize, Autoref::RefMut, vec![USIZE, elem], UNIT))
                } else if name == k.dedup {
                    self.deferred_eq.push((elem, name_span));
                    Some((B::VecDedup, Autoref::RefMut, vec![], UNIT))
                } else if name == k.retain {
                    // `FnMut(&T) -> bool`, the reference higher-ranked.
                    let r = self.tys.mk_ref(false, elem);
                    let f = self.fn_mut_param_ref(&[r], BOOL, name_span);
                    Some((B::VecRetain, Autoref::RefMut, vec![f], UNIT))
                } else if name == k.retain_mut {
                    let r = self.tys.mk_ref(true, elem);
                    let f = self.fn_mut_param_ref(&[r], BOOL, name_span);
                    Some((B::VecRetainMut, Autoref::RefMut, vec![f], UNIT))
                } else if name == k.reverse {
                    Some((B::VecReverse, Autoref::RefMut, vec![], UNIT))
                } else if name == k.first_mut {
                    let r = self.tys.mk_ref(true, elem);
                    let opt_ref = self.tys.mk_option(r);
                    Some((B::VecFirstMut, Autoref::RefMut, vec![], opt_ref))
                } else if name == k.last_mut {
                    let r = self.tys.mk_ref(true, elem);
                    let opt_ref = self.tys.mk_option(r);
                    Some((B::VecLastMut, Autoref::RefMut, vec![], opt_ref))
                } else if name == k.get_mut {
                    let r = self.tys.mk_ref(true, elem);
                    let opt_ref = self.tys.mk_option(r);
                    Some((B::VecGetMut, Autoref::RefMut, vec![USIZE], opt_ref))
                } else if name == k.as_slice {
                    let sl = self.tys.intern(TyKind::Slice(elem));
                    let r = self.tys.mk_ref(false, sl);
                    Some((B::VecAsSlice, Autoref::Ref, vec![], r))
                } else if name == k.as_mut_slice {
                    let sl = self.tys.intern(TyKind::Slice(elem));
                    let r = self.tys.mk_ref(true, sl);
                    Some((B::VecAsMutSlice, Autoref::RefMut, vec![], r))
                } else if name == k.to_vec {
                    // `[T]::to_vec` through the Vec's `Deref<Target = [T]>`.
                    self.deferred_clone.push((elem, name_span));
                    let v = self.tys.mk_vec(elem);
                    Some((B::SliceToVec, Autoref::Ref, vec![], v))
                } else if self.name(name) == "spare_capacity_mut" {
                    let mu = generics::maybe_uninit_ty(&mut self.tys, elem);
                    let sl = self.tys.intern(TyKind::Slice(mu));
                    let r = self.tys.mk_ref(true, sl);
                    Some((B::VecSpareCapacityMut, Autoref::RefMut, vec![], r))
                } else if self.name(name) == "as_ptr" {
                    Some((B::SeqAsPtr, Autoref::Ref, vec![], self.tys.intern(TyKind::RawPtr(Mut::Shared, elem))))
                } else if self.name(name) == "as_mut_ptr" {
                    Some((B::SeqAsPtr, Autoref::RefMut, vec![], self.tys.intern(TyKind::RawPtr(Mut::Mut, elem))))
                } else {
                    self.slice_split_method(name, elem)
                }
            }
            (None, TyKind::Slice(_)) | (None, TyKind::Array(..)) => {
                let elem = match bk {
                    TyKind::Slice(e) | TyKind::Array(e, _) => e,
                    _ => ERROR,
                };
                if name == k.as_slice && matches!(bk, TyKind::Array(..)) {
                    let sl = self.tys.intern(TyKind::Slice(elem));
                    let r = self.tys.mk_ref(false, sl);
                    Some((B::VecAsSlice, Autoref::Ref, vec![], r))
                } else if name == k.as_mut_slice && matches!(bk, TyKind::Array(..)) {
                    let sl = self.tys.intern(TyKind::Slice(elem));
                    let r = self.tys.mk_ref(true, sl);
                    Some((B::VecAsMutSlice, Autoref::RefMut, vec![], r))
                } else if self.name(name) == "as_ptr" {
                    Some((B::SeqAsPtr, Autoref::Ref, vec![], self.tys.intern(TyKind::RawPtr(Mut::Shared, elem))))
                } else if self.name(name) == "as_mut_ptr" {
                    Some((B::SeqAsPtr, Autoref::RefMut, vec![], self.tys.intern(TyKind::RawPtr(Mut::Mut, elem))))
                } else if name == k.len {
                    Some((B::SliceLen, Autoref::Ref, vec![], USIZE))
                } else if name == k.is_empty {
                    Some((B::SliceIsEmpty, Autoref::Ref, vec![], BOOL))
                } else if name == k.to_vec {
                    self.deferred_clone.push((elem, name_span));
                    let v = self.tys.mk_vec(elem);
                    Some((B::SliceToVec, Autoref::Ref, vec![], v))
                } else if name == k.reverse {
                    Some((B::VecReverse, Autoref::RefMut, vec![], UNIT))
                } else if name == k.swap {
                    Some((B::VecSwap, Autoref::RefMut, vec![USIZE, USIZE], UNIT))
                } else if name == k.first {
                    let r = self.tys.mk_ref(false, elem);
                    let opt_ref = self.tys.mk_option(r);
                    Some((B::VecFirst, Autoref::Ref, vec![], opt_ref))
                } else if name == k.last {
                    let r = self.tys.mk_ref(false, elem);
                    let opt_ref = self.tys.mk_option(r);
                    Some((B::VecLast, Autoref::Ref, vec![], opt_ref))
                } else if name == k.get {
                    let r = self.tys.mk_ref(false, elem);
                    let opt_ref = self.tys.mk_option(r);
                    Some((B::VecGet, Autoref::Ref, vec![USIZE], opt_ref))
                } else if name == k.first_mut {
                    let r = self.tys.mk_ref(true, elem);
                    let opt_ref = self.tys.mk_option(r);
                    Some((B::VecFirstMut, Autoref::RefMut, vec![], opt_ref))
                } else if name == k.last_mut {
                    let r = self.tys.mk_ref(true, elem);
                    let opt_ref = self.tys.mk_option(r);
                    Some((B::VecLastMut, Autoref::RefMut, vec![], opt_ref))
                } else if name == k.get_mut {
                    let r = self.tys.mk_ref(true, elem);
                    let opt_ref = self.tys.mk_option(r);
                    Some((B::VecGetMut, Autoref::RefMut, vec![USIZE], opt_ref))
                } else if name == k.contains {
                    self.deferred_eq.push((elem, name_span));
                    let r = self.tys.mk_ref(false, elem);
                    Some((B::VecContains, Autoref::Ref, vec![r], BOOL))
                } else {
                    self.slice_split_method(name, elem)
                }
            }
            (Some(BuiltinTy::Chars), _) => {
                let opt = self.tys.mk_option(CHAR);
                if name == k.next {
                    Some((B::CharsNext, Autoref::RefMut, vec![], opt))
                } else if name == k.count && derefs == 0 {
                    // Through `&mut Chars` the iterator path counts in place
                    // (core's `impl Iterator for &mut I`, check/iter.rs).
                    Some((B::CharsCount, Autoref::None, vec![], USIZE))
                } else {
                    None
                }
            }
            (None, TyKind::Char) if name != k.to_string => self.char_method(name),
            (None, TyKind::Int(i)) => self.int_method(name, base, i),
            (None, TyKind::Float(f)) => self.float_method(name, base, f),
            // Trait methods work on a float of unknown width; inherent
            // ones do not (rustc E0689), as with integers below.
            (None, k2) if k2.is_float_infer() && name == k.to_string => Some((B::ToString, Autoref::Ref, vec![], STRING)),
            (None, k2) if k2.is_float_infer() => {
                if self.generic_mode() && !builtin_only {
                    match method::generic_method_search(self, e, rt, name, name_span, args, &explicit, expected) {
                        method::Probe::Hit(ret) => return ret,
                        method::Probe::Failed => return ERROR,
                        method::Probe::Miss => {}
                    }
                }
                if self.float_method(name, base, FloatTy::F64).is_some() {
                    self.err(
                        "L0111",
                        name_span,
                        format!("cannot call method `{}` on a float whose type is not known yet", self.name(name)),
                        "Add a type suffix such as `2.0f32`, or a type annotation on the variable.",
                    );
                    return ERROR;
                }
                None
            }
            (None, TyKind::Bool) if name == k.then_some => {
                let t = self.new_var(false);
                let o = self.tys.mk_option(t);
                Some((B::BoolThenSome, Autoref::None, vec![t], o))
            }
            (None, TyKind::Bool) if name == k.then => {
                // `F: FnOnce() -> T`; lowering calls closures only
                // (as for `Ordering::then_with`).
                let lang = self.p.gx.lang;
                let t = self.new_var(false);
                let f = self.new_var(false);
                let unit_args = self.tys.intern_tys(&[]);
                let unit = self.tys.intern(TyKind::Tuple(unit_args));
                let args_id = self.tys.intern_args(&[GenericArg::Ty(f), GenericArg::Ty(unit)]);
                self.obl.push(obligations::Obligation::Trait {
                    trait_ref: TraitRef { def: lang.fn_once, args: args_id, bindings: EMPTY_BINDINGS },
                    span: name_span,
                    depth: 0,
                });
                if let Some(out) = lang.output_of(lang.fn_once) {
                    self.obl.push(obligations::Obligation::AssocEq { eq: AssocEqData { assoc: out, trait_args: args_id, ty: t }, span: name_span });
                }
                let o = self.tys.mk_option(t);
                Some((B::BoolThen, Autoref::None, vec![f], o))
            }
            (None, TyKind::Bool | TyKind::Char) if name == k.to_string => Some((B::ToString, Autoref::Ref, vec![], STRING)),
            // Trait methods work on an integer of unknown type; inherent ones (pow, abs) do not.
            (None, k2) if k2.is_int_infer() && name == k.min => Some((B::Min, Autoref::None, vec![base], base)),
            (None, k2) if k2.is_int_infer() && name == k.max => Some((B::Max, Autoref::None, vec![base], base)),
            (None, k2) if k2.is_int_infer() && name == k.to_string => Some((B::ToString, Autoref::Ref, vec![], STRING)),
            (None, k2) if k2.is_int_infer() => {
                // A trait method still applies: selection fixes the
                // integer type when exactly one impl matches, as in
                // rustc. Inherent integer methods need the type.
                if self.generic_mode() && !builtin_only {
                    match method::generic_method_search(self, e, rt, name, name_span, args, &explicit, expected) {
                        method::Probe::Hit(ret) => return ret,
                        method::Probe::Failed => return ERROR,
                        method::Probe::Miss => {}
                    }
                }
                // `Ord::clamp` holds for every integer type.
                if self.name(name) == "clamp"
                    && let Some(ret) = self.ord_pick_method(e, recv, base, derefs, name, name_span, args)
                {
                    return ret;
                }
                self.err(
                    "L0111",
                    name_span,
                    format!("cannot call method `{}` on an integer whose type is not known yet", self.name(name)),
                    "Add a type suffix such as `5i64`, or a type annotation on the variable.",
                );
                return ERROR;
            }
            (_, TyKind::Error) => return ERROR,
            _ => None,
        };
        match found {
            Some((b, autoref, params, ret)) => {
                if autoref != Autoref::None {
                    self.check_packed_borrow(recv, name_span);
                }
                // `to_string` binds Self where rustc's probe does: the
                // first step whose `&Self` is the receiver (one reference
                // peeled), else the receiver by autoref. Self picks the
                // capacity rule (W-STD-B): `&&u8` is the generic path.
                let derefs = if b == B::ToString { u8::from(matches!(self.tys.kind(rt), TyKind::Ref(..))) } else { derefs };
                self.set_res(e, Res::BuiltinMethod { b, derefs, autoref });
                // The str search methods take std's `Pattern`: a char
                // in the pattern position becomes its encoding as a
                // &str (`Coerce::CharPat`), which searches the same.
                if matches!(b, B::StrContains | B::StrFind | B::StrRfind | B::StrStartsWith | B::StrEndsWith | B::StrStripPrefix | B::StrStripSuffix | B::StrReplace | B::StrReplacen)
                    && args.len() == params.len()
                    && !args.is_empty()
                {
                    self.check_str_pattern_args(&params, args, name_span);
                } else {
                    self.check_args(&params, args, name_span);
                }
                if matches!(b, B::VecRetain | B::VecRetainMut | B::BoolThen) && self.adapter_callable_gap(args, &params, b == B::BoolThen) {
                    return ERROR;
                }
                ret
            }
            None => {
                // Inherent methods std source defines on a primitive
                // receiver (`impl char`, TRIAGE T8).
                if let method::Probe::Hit(ret) = method::prim_inherent_probe(self, e, base, derefs, name, name_span, args) {
                    return ret;
                }
                // Generic and trait methods over the full autoderef
                // chain (check/method.rs).
                if self.generic_mode() && !builtin_only {
                    match method::generic_method_search(self, e, rt, name, name_span, args, &explicit, expected) {
                        method::Probe::Hit(ret) => return ret,
                        method::Probe::Failed => return ERROR,
                        method::Probe::Miss => {}
                    }
                }
                if let Some(ret) = self.lang_default_method(e, recv, base, derefs, name, name_span, args) {
                    return ret;
                }
                if let Some(ret) = self.cow_deref_method(e, recv, base, derefs, name, name_span, args, turbofish, expected) {
                    return ret;
                }
                if let Some(ret) = self.method_via_user_deref(e, recv, base, derefs, name, name_span, args, turbofish, expected) {
                    return ret;
                }
                for &a in args {
                    self.expr(a, None);
                }
                // A user trait's method was skipped for std's item, which
                // lust does not model.
                if self.std_first.contains(&e) {
                    self.report_std_shadow(base, name, false, name_span);
                    return ERROR;
                }
                if let Some(&(_, a)) = self.private_inherent.iter().find(|(x, _)| *x == e) {
                    self.check_assoc_vis(a, name, "method", name_span);
                    return ERROR;
                }
                if assoc_fn_seen {
                    self.err(
                        "L0104",
                        name_span,
                        format!("`{}` is an associated function, not a method", self.name(name)),
                        "Call it as `Type::name(...)`.",
                    );
                    return ERROR;
                }
                if self.tainted_lookup(base) {
                    return ERROR;
                }
                let tn = self.tn(base);
                self.err(
                    "L0104",
                    name_span,
                    format!("no method `{}` on type `{tn}`", self.name(name)),
                    "Check the method name. The prototype supports a small std subset (see README).",
                );
                ERROR
            }
        }
    }


    /// Inherent `char` methods (the ASCII family, the Unicode
    /// predicates, encoding; TRIAGE T8/T12). The receiver form
    /// follows std: ASCII predicates and case maps take `&self`,
    /// the Unicode predicates take `self`.
    fn char_method(&mut self, name: Sym) -> Option<(Builtin, Autoref, Vec<Ty>, Ty)> {
        use Builtin as B;
        let k = &*self.p.known;

        let b = [
            (k.is_ascii_digit, B::CharIsDigit),
            (k.is_ascii_alphabetic, B::CharIsAlphabetic),
            (k.is_ascii_alphanumeric, B::CharIsAlphanumeric),
            (k.is_ascii_whitespace, B::CharIsWhitespace),
            (k.is_ascii_uppercase, B::CharIsUppercase),
            (k.is_ascii_lowercase, B::CharIsLowercase),
        ];
        // The Unicode predicates take `self`, not `&self`.
        let u = [
            (k.is_alphabetic, B::CharIsAlphabeticUnicode),
            (k.is_numeric, B::CharIsNumericUnicode),
            (k.is_alphanumeric, B::CharIsAlphanumericUnicode),
            (k.is_lowercase, B::CharIsLowercaseUnicode),
            (k.is_uppercase, B::CharIsUppercaseUnicode),
            (k.is_whitespace, B::CharIsWhitespaceUnicode),
            (k.is_control, B::CharIsControlUnicode),
        ];
        if let Some(&(_, b)) = u.iter().find(|(n, _)| *n == name) {
            Some((b, Autoref::None, vec![], BOOL))
        } else if let Some(&(_, b)) = b.iter().find(|(n, _)| *n == name) {
            Some((b, Autoref::Ref, vec![], BOOL))
        } else if name == k.to_ascii_uppercase {
            Some((B::CharToUppercase, Autoref::Ref, vec![], CHAR))
        } else if name == k.to_ascii_lowercase {
            Some((B::CharToLowercase, Autoref::Ref, vec![], CHAR))
        } else if name == k.make_ascii_lowercase {
            Some((B::MakeAsciiLowercase, Autoref::RefMut, vec![], UNIT))
        } else if name == k.make_ascii_uppercase {
            Some((B::MakeAsciiUppercase, Autoref::RefMut, vec![], UNIT))
        } else if name == k.to_digit {
            let o = self.tys.mk_option(int(IntTy::U32));
            Some((B::CharToDigit, Autoref::None, vec![int(IntTy::U32)], o))
        } else if name == k.is_digit {
            Some((B::CharIsDigitRadix, Autoref::None, vec![int(IntTy::U32)], BOOL))
        } else if name == k.len_utf8 {
            Some((B::CharLenUtf8, Autoref::None, vec![], USIZE))
        } else if name == k.len_utf16 {
            Some((B::CharLenUtf16, Autoref::None, vec![], USIZE))
        } else if name == k.encode_utf8 {
            let sl = self.tys.intern(TyKind::Slice(int(IntTy::U8)));
            let dst = self.tys.mk_ref(true, sl);
            let ret = self.tys.mk_ref(true, STR);
            Some((B::CharEncodeUtf8, Autoref::None, vec![dst], ret))
        } else if name == k.encode_utf16 {
            let sl = self.tys.intern(TyKind::Slice(int(IntTy::U16)));
            let dst = self.tys.mk_ref(true, sl);
            Some((B::CharEncodeUtf16, Autoref::None, vec![dst], dst))
        } else if name == k.is_ascii {
            Some((B::CharIsAscii, Autoref::Ref, vec![], BOOL))
        } else if name == k.is_ascii_punctuation {
            Some((B::CharIsAsciiPunctuation, Autoref::Ref, vec![], BOOL))
        } else if name == k.is_ascii_graphic {
            Some((B::CharIsAsciiGraphic, Autoref::Ref, vec![], BOOL))
        } else if name == k.is_ascii_hexdigit {
            Some((B::CharIsAsciiHexdigit, Autoref::Ref, vec![], BOOL))
        } else if name == k.is_ascii_control {
            Some((B::CharIsAsciiControl, Autoref::Ref, vec![], BOOL))
        } else {
            None
        }
        }

    /// Inherent integer methods (`checked_add`, `count_ones`, and kin).
    /// All take the receiver by value. The 128-bit checked, saturating,
    /// and overflowing families (plus euclid division) are not
    /// implemented yet and answer None, like a missing method.
    /// `[u8; N]` with N the byte size of `i`: what `to_le_bytes`
    /// returns and `from_le_bytes` takes.
    fn int_bytes_ty(&mut self, i: IntTy) -> Ty {
        let n = self.tys.intern_const(ConstKind::Int((i.bits() / 8) as u128));
        self.tys.intern(TyKind::Array(int(IntTy::U8), n))
    }

    fn int_method(&mut self, name: Sym, t: Ty, i: IntTy) -> Option<(Builtin, Autoref, Vec<Ty>, Ty)> {
        use Builtin as B;
        let k = &*self.p.known;
        let s = i.signed();
        let w128 = i.bits() >= 128;
        let u32t = int(IntTy::U32);
        let bin = |b: Builtin| Some((b, Autoref::None, vec![t], t));
        let chk = |b: Builtin, cx: &mut Self| {
            let o = cx.tys.mk_option(t);
            Some((b, Autoref::None, vec![t], o))
        };
        let ovf = |b: Builtin, cx: &mut Self| {
            let ts = cx.tys.intern_tys(&[t, BOOL]);
            let tt = cx.tys.intern(TyKind::Tuple(ts));
            Some((b, Autoref::None, vec![t], tt))
        };
        let sh = |b: Builtin| Some((b, Autoref::None, vec![u32t], t));
        let un = |b: Builtin| Some((b, Autoref::None, vec![], t));
        let n = name;
        // The `u8` ascii family (`u8::is_ascii_uppercase` and friends):
        // core defines them on the byte value with the same ranges as
        // the `char` forms, so the char builtins serve both. The
        // predicates take `&self`; the case maps return a new `u8`.
        if i == IntTy::U8 {
            let pred = [
                (k.is_ascii, B::CharIsAscii),
                (k.is_ascii_alphabetic, B::CharIsAlphabetic),
                (k.is_ascii_alphanumeric, B::CharIsAlphanumeric),
                (k.is_ascii_digit, B::CharIsDigit),
                (k.is_ascii_whitespace, B::CharIsWhitespace),
                (k.is_ascii_uppercase, B::CharIsUppercase),
                (k.is_ascii_lowercase, B::CharIsLowercase),
                (k.is_ascii_hexdigit, B::CharIsAsciiHexdigit),
                (k.is_ascii_punctuation, B::CharIsAsciiPunctuation),
                (k.is_ascii_graphic, B::CharIsAsciiGraphic),
                (k.is_ascii_control, B::CharIsAsciiControl),
            ];
            if let Some(&(_, b)) = pred.iter().find(|(m, _)| *m == n) {
                return Some((b, Autoref::Ref, vec![], BOOL));
            }
            if n == k.to_ascii_uppercase {
                return Some((B::CharToUppercase, Autoref::Ref, vec![], t));
            }
            if n == k.to_ascii_lowercase {
                return Some((B::CharToLowercase, Autoref::Ref, vec![], t));
            }
            if n == k.make_ascii_lowercase {
                return Some((B::MakeAsciiLowercase, Autoref::RefMut, vec![], UNIT));
            }
            if n == k.make_ascii_uppercase {
                return Some((B::MakeAsciiUppercase, Autoref::RefMut, vec![], UNIT));
            }
        }
        // `next_multiple_of` and its checked form are unsigned only;
        // `unsigned_abs` maps a signed value to its unsigned twin.
        if n == k.next_multiple_of && !s {
            return bin(B::NextMultipleOf);
        }
        if n == k.checked_next_multiple_of && !s {
            let o = self.tys.mk_option(t);
            return Some((B::CheckedNextMultipleOf, Autoref::None, vec![t], o));
        }
        if n == k.unsigned_abs && s {
            return Some((B::UnsignedAbs, Autoref::None, vec![], int(i.counterpart())));
        }
        // `abs_diff` gives the unsigned twin; `midpoint` as a method is
        // the associated fn's (the 128-bit forms stay out, as there).
        if n == k.abs_diff && !w128 {
            return Some((B::IntAbsDiff, Autoref::None, vec![t], int(if s { i.counterpart() } else { i })));
        }
        if n == k.midpoint && !w128 {
            return bin(B::IntMidpoint);
        }
        // The families that stay within the value (wrapping and plain).
        if n == k.wrapping_add {
            return bin(B::WrappingAdd);
        }
        if n == k.wrapping_sub {
            return bin(B::WrappingSub);
        }
        if n == k.wrapping_mul {
            return bin(B::WrappingMul);
        }
        if n == k.wrapping_div && !w128 {
            return bin(B::WrappingDiv);
        }
        if n == k.wrapping_rem && !w128 {
            return bin(B::WrappingRem);
        }
        if n == k.wrapping_neg {
            return un(B::WrappingNeg);
        }
        if n == k.wrapping_pow && !w128 {
            return sh(B::WrappingPow);
        }
        if n == k.wrapping_shl {
            return sh(B::WrappingShl);
        }
        if n == k.wrapping_shr {
            return sh(B::WrappingShr);
        }
        if n == k.wrapping_abs && s {
            return un(B::WrappingAbs);
        }
        if n == k.abs && s {
            return un(B::Abs);
        }
        if n == k.pow {
            return sh(B::Pow);
        }
        if n == k.min {
            return bin(B::Min);
        }
        if n == k.max {
            return bin(B::Max);
        }
        if n == k.div_euclid && !w128 {
            return bin(B::DivEuclid);
        }
        // `div_ceil` is unsigned only (there is no checked form).
        if n == k.div_ceil && !s && !w128 {
            return bin(B::DivCeil);
        }
        if n == k.rem_euclid && !w128 {
            return bin(B::RemEuclid);
        }
        if n == k.signum && s {
            return un(B::Signum);
        }
        if n == k.is_positive && s {
            return Some((B::IsPositive, Autoref::None, vec![], BOOL));
        }
        if n == k.is_negative && s {
            return Some((B::IsNegative, Autoref::None, vec![], BOOL));
        }
        if n == k.is_power_of_two && !s {
            return Some((B::IsPowerOfTwo, Autoref::None, vec![], BOOL));
        }
        // The 1.84 to 1.97 bit and shift families (fx-defaults):
        // `is_multiple_of` and `bit_width` are unsigned only, the
        // casts name the other signedness, and the isolate and
        // highest/lowest forms run on the raw bits of either.
        if n == k.is_multiple_of && !s {
            return Some((B::IsMultipleOf, Autoref::None, vec![t], BOOL));
        }
        if n == k.unbounded_shl {
            return sh(B::UnboundedShl);
        }
        if n == k.unbounded_shr {
            return sh(B::UnboundedShr);
        }
        if n == k.cast_signed && !s {
            return Some((B::CastSigned, Autoref::None, vec![], int(i.counterpart())));
        }
        if n == k.cast_unsigned && s {
            return Some((B::CastUnsigned, Autoref::None, vec![], int(i.counterpart())));
        }
        if n == k.bit_width && !s {
            return Some((B::BitWidth, Autoref::None, vec![], u32t));
        }
        if n == k.highest_one {
            let o = self.tys.mk_option(u32t);
            return Some((B::HighestOne, Autoref::None, vec![], o));
        }
        if n == k.lowest_one {
            let o = self.tys.mk_option(u32t);
            return Some((B::LowestOne, Autoref::None, vec![], o));
        }
        if n == k.isolate_highest_one {
            return un(B::IsolateHighestOne);
        }
        if n == k.isolate_lowest_one {
            return un(B::IsolateLowestOne);
        }
        if n == k.count_ones {
            return Some((B::CountOnes, Autoref::None, vec![], u32t));
        }
        if n == k.count_zeros {
            return Some((B::CountZeros, Autoref::None, vec![], u32t));
        }
        if n == k.leading_zeros {
            return Some((B::LeadingZeros, Autoref::None, vec![], u32t));
        }
        if n == k.trailing_zeros {
            return Some((B::TrailingZeros, Autoref::None, vec![], u32t));
        }
        if n == k.leading_ones {
            return Some((B::LeadingOnes, Autoref::None, vec![], u32t));
        }
        if n == k.trailing_ones {
            return Some((B::TrailingOnes, Autoref::None, vec![], u32t));
        }
        if n == k.rotate_left {
            return sh(B::RotateLeft);
        }
        if n == k.rotate_right {
            return sh(B::RotateRight);
        }
        if n == k.swap_bytes {
            return un(B::SwapBytes);
        }
        if n == k.reverse_bits {
            return un(B::ReverseBits);
        }
        // `to_le_bytes`, `to_be_bytes`, `to_ne_bytes` (TRIAGE R26): the
        // value's bytes, `[u8; size_of::<Self>()]`.
        let to_bytes = match self.name(n) {
            "to_le_bytes" => Some(B::IntToLeBytes),
            "to_be_bytes" => Some(B::IntToBeBytes),
            "to_ne_bytes" => Some(B::IntToNeBytes),
            _ => None,
        };
        if let Some(b) = to_bytes {
            let arr = self.int_bytes_ty(i);
            return Some((b, Autoref::None, vec![], arr));
        }
        if n == k.to_string {
            return Some((B::ToString, Autoref::Ref, vec![], STRING));
        }
        if w128 {
            return None;
        }
        // `isqrt` (1.84): every integer; the signed form panics on a
        // negative input, `checked_isqrt` gives `None` there. The
        // 128-bit forms stay out with the families below.
        if n == k.isqrt {
            return un(B::Isqrt);
        }
        // R13 (tf-small-a): powers of two (unsigned) and the integer logs.
        match self.p.interner.get(n) {
            "next_power_of_two" if !s => return un(B::NextPowerOfTwo),
            "checked_next_power_of_two" if !s => {
                let o = self.tys.mk_option(t);
                return Some((B::CheckedNextPowerOfTwo, Autoref::None, vec![], o));
            }
            "ilog2" => return Some((B::Ilog2, Autoref::None, vec![], u32t)),
            "ilog10" => return Some((B::Ilog10, Autoref::None, vec![], u32t)),
            "ilog" => return Some((B::Ilog, Autoref::None, vec![t], u32t)),
            m @ ("checked_ilog2" | "checked_ilog10" | "checked_ilog") => {
                let o = self.tys.mk_option(u32t);
                return Some(match m {
                    "checked_ilog2" => (B::CheckedIlog2, Autoref::None, vec![], o),
                    "checked_ilog10" => (B::CheckedIlog10, Autoref::None, vec![], o),
                    _ => (B::CheckedIlog, Autoref::None, vec![t], o),
                });
            }
            _ => {}
        }
        if n == k.checked_isqrt && s {
            let o = self.tys.mk_option(t);
            return Some((B::CheckedIsqrt, Autoref::None, vec![], o));
        }
        // Checked, saturating, and overflowing families (64-bit and below).
        if n == k.checked_add {
            return chk(B::CheckedAdd, self);
        }
        if n == k.checked_sub {
            return chk(B::CheckedSub, self);
        }
        if n == k.checked_mul {
            return chk(B::CheckedMul, self);
        }
        if n == k.checked_div {
            return chk(B::CheckedDiv, self);
        }
        if n == k.checked_rem {
            return chk(B::CheckedRem, self);
        }
        if n == k.checked_neg {
            let o = self.tys.mk_option(t);
            return Some((B::CheckedNeg, Autoref::None, vec![], o));
        }
        if n == k.checked_abs && s {
            let o = self.tys.mk_option(t);
            return Some((B::CheckedAbs, Autoref::None, vec![], o));
        }
        if n == k.checked_pow {
            let o = self.tys.mk_option(t);
            return Some((B::CheckedPow, Autoref::None, vec![u32t], o));
        }
        if n == k.checked_shl {
            let o = self.tys.mk_option(t);
            return Some((B::CheckedShl, Autoref::None, vec![u32t], o));
        }
        if n == k.checked_shr {
            let o = self.tys.mk_option(t);
            return Some((B::CheckedShr, Autoref::None, vec![u32t], o));
        }
        if n == k.saturating_add {
            return bin(B::SaturatingAdd);
        }
        if n == k.saturating_sub {
            return bin(B::SaturatingSub);
        }
        if n == k.saturating_mul {
            return bin(B::SaturatingMul);
        }
        if n == k.saturating_div {
            return bin(B::SaturatingDiv);
        }
        if n == k.saturating_neg && s {
            return un(B::SaturatingNeg);
        }
        if n == k.saturating_abs && s {
            return un(B::SaturatingAbs);
        }
        if n == k.saturating_pow {
            return sh(B::SaturatingPow);
        }
        if n == k.overflowing_add {
            return ovf(B::OverflowingAdd, self);
        }
        if n == k.overflowing_sub {
            return ovf(B::OverflowingSub, self);
        }
        if n == k.overflowing_mul {
            return ovf(B::OverflowingMul, self);
        }
        if n == k.overflowing_div {
            return ovf(B::OverflowingDiv, self);
        }
        if n == k.overflowing_rem {
            return ovf(B::OverflowingRem, self);
        }
        if n == k.overflowing_neg {
            let ts = self.tys.intern_tys(&[t, BOOL]);
            let tt = self.tys.intern(TyKind::Tuple(ts));
            return Some((B::OverflowingNeg, Autoref::None, vec![], tt));
        }
        if n == k.overflowing_abs && s {
            let ts = self.tys.intern_tys(&[t, BOOL]);
            let tt = self.tys.intern(TyKind::Tuple(ts));
            return Some((B::OverflowingAbs, Autoref::None, vec![], tt));
        }
        if n == k.overflowing_pow {
            let ts = self.tys.intern_tys(&[t, BOOL]);
            let tt = self.tys.intern(TyKind::Tuple(ts));
            return Some((B::OverflowingPow, Autoref::None, vec![u32t], tt));
        }
        if n == k.overflowing_shl {
            let ts = self.tys.intern_tys(&[t, BOOL]);
            let tt = self.tys.intern(TyKind::Tuple(ts));
            return Some((B::OverflowingShl, Autoref::None, vec![u32t], tt));
        }
        if n == k.overflowing_shr {
            let ts = self.tys.intern_tys(&[t, BOOL]);
            let tt = self.tys.intern(TyKind::Tuple(ts));
            return Some((B::OverflowingShr, Autoref::None, vec![u32t], tt));
        }
        // The strict family (1.91): the plain operations with their
        // overflow panics kept even in release builds.
        if n == k.strict_add {
            return bin(B::StrictAdd);
        }
        if n == k.strict_sub {
            return bin(B::StrictSub);
        }
        if n == k.strict_mul {
            return bin(B::StrictMul);
        }
        if n == k.strict_div {
            return bin(B::StrictDiv);
        }
        if n == k.strict_rem {
            return bin(B::StrictRem);
        }
        if n == k.strict_div_euclid {
            return bin(B::StrictDivEuclid);
        }
        if n == k.strict_rem_euclid {
            return bin(B::StrictRemEuclid);
        }
        if n == k.strict_neg {
            return un(B::StrictNeg);
        }
        if n == k.strict_abs && s {
            return un(B::StrictAbs);
        }
        if n == k.strict_pow {
            return sh(B::StrictPow);
        }
        if n == k.strict_shl {
            return sh(B::StrictShl);
        }
        if n == k.strict_shr {
            return sh(B::StrictShr);
        }
        // The mixed-sign families: the argument is the same-width
        // type of the other signedness. `checked`, `saturating`,
        // `wrapping`, and `overflowing` for both directions, plus
        // the strict forms (1.90 and 1.91, with their older kin).
        let other = int(i.counterpart());
        let mixed = |b: Builtin, kind: u8, cx: &mut Self| -> Option<(Builtin, Autoref, Vec<Ty>, Ty)> {
            let ret = match kind {
                b'c' => cx.tys.mk_option(t),
                b'o' => {
                    let ts = cx.tys.intern_tys(&[t, BOOL]);
                    cx.tys.intern(TyKind::Tuple(ts))
                }
                _ => t,
            };
            Some((b, Autoref::None, vec![other], ret))
        };
        if (s && n == k.checked_add_unsigned) || (!s && n == k.checked_add_signed) {
            return mixed(B::MixedCheckedAdd, b'c', self);
        }
        if (s && n == k.checked_sub_unsigned) || (!s && n == k.checked_sub_signed) {
            return mixed(B::MixedCheckedSub, b'c', self);
        }
        if (s && n == k.wrapping_add_unsigned) || (!s && n == k.wrapping_add_signed) {
            return mixed(B::MixedWrappingAdd, b'w', self);
        }
        if (s && n == k.wrapping_sub_unsigned) || (!s && n == k.wrapping_sub_signed) {
            return mixed(B::MixedWrappingSub, b'w', self);
        }
        if (s && n == k.saturating_add_unsigned) || (!s && n == k.saturating_add_signed) {
            return mixed(B::MixedSaturatingAdd, b't', self);
        }
        if (s && n == k.saturating_sub_unsigned) || (!s && n == k.saturating_sub_signed) {
            return mixed(B::MixedSaturatingSub, b't', self);
        }
        if (s && n == k.overflowing_add_unsigned) || (!s && n == k.overflowing_add_signed) {
            return mixed(B::MixedOverflowingAdd, b'o', self);
        }
        if (s && n == k.overflowing_sub_unsigned) || (!s && n == k.overflowing_sub_signed) {
            return mixed(B::MixedOverflowingSub, b'o', self);
        }
        if (s && n == k.strict_add_unsigned) || (!s && n == k.strict_add_signed) {
            return mixed(B::MixedStrictAdd, b's', self);
        }
        if (s && n == k.strict_sub_unsigned) || (!s && n == k.strict_sub_signed) {
            return mixed(B::MixedStrictSub, b's', self);
        }
        if n == k.checked_signed_diff && !s {
            let o = self.tys.mk_option(other);
            return Some((B::CheckedSignedDiff, Autoref::None, vec![t], o));
        }
        // The carrying forms (1.91, unsigned): wide add, sub, and
        // multiply with the carry or borrow in and out.
        if !s && (n == k.carrying_add || n == k.borrowing_sub) {
            let b = if n == k.carrying_add { B::CarryingAdd } else { B::BorrowingSub };
            let ts = self.tys.intern_tys(&[t, BOOL]);
            let tt = self.tys.intern(TyKind::Tuple(ts));
            return Some((b, Autoref::None, vec![t, BOOL], tt));
        }
        if !s && n == k.carrying_mul {
            let ts = self.tys.intern_tys(&[t, t]);
            let tt = self.tys.intern(TyKind::Tuple(ts));
            return Some((B::CarryingMul, Autoref::None, vec![t, t], tt));
        }
        if !s && n == k.carrying_mul_add {
            let ts = self.tys.intern_tys(&[t, t]);
            let tt = self.tys.intern(TyKind::Tuple(ts));
            return Some((B::CarryingMulAdd, Autoref::None, vec![t, t, t], tt));
        }
        None
    }

    /// Inherent float methods (`sqrt`, `powi`, `to_bits`, and kin).
    /// `t` is the receiver type (a float variable for an unsuffixed
    /// literal), `f` its width when known (f64 for a variable).
    fn float_method(&mut self, name: Sym, t: Ty, f: FloatTy) -> Option<(Builtin, Autoref, Vec<Ty>, Ty)> {
        use Builtin as B;
        let k = &*self.p.known;
        let un = |b: Builtin| Some((b, Autoref::None, vec![], t));
        let n = name;
        if n == k.sqrt {
            return un(B::FloatSqrt);
        }
        if n == k.abs {
            return un(B::FloatAbs);
        }
        if n == k.floor {
            return un(B::FloatFloor);
        }
        if n == k.ceil {
            return un(B::FloatCeil);
        }
        if n == k.round {
            return un(B::FloatRound);
        }
        if n == k.trunc {
            return un(B::FloatTrunc);
        }
        if n == k.fract {
            return un(B::FloatFract);
        }
        if n == k.signum {
            return un(B::FloatSignum);
        }
        if n == k.recip {
            return un(B::FloatRecip);
        }
        if n == k.exp {
            return un(B::FloatExp);
        }
        if n == k.ln {
            return un(B::FloatLn);
        }
        if n == k.log2 {
            return un(B::FloatLog2);
        }
        if n == k.log10 {
            return un(B::FloatLog10);
        }
        if n == k.powi {
            return Some((B::FloatPowi, Autoref::None, vec![int(IntTy::I32)], t));
        }
        if n == k.powf {
            return Some((B::FloatPowf, Autoref::None, vec![t], t));
        }
        if n == k.log {
            return Some((B::FloatLog, Autoref::None, vec![t], t));
        }
        if n == k.mul_add {
            return Some((B::FloatMulAdd, Autoref::None, vec![t, t], t));
        }
        if n == k.min {
            return Some((B::FloatMin, Autoref::None, vec![t], t));
        }
        if n == k.max {
            return Some((B::FloatMax, Autoref::None, vec![t], t));
        }
        if n == k.copysign {
            return Some((B::FloatCopysign, Autoref::None, vec![t], t));
        }
        if n == k.is_nan {
            return Some((B::FloatIsNan, Autoref::None, vec![], BOOL));
        }
        if n == k.is_infinite {
            return Some((B::FloatIsInfinite, Autoref::None, vec![], BOOL));
        }
        if n == k.is_finite {
            return Some((B::FloatIsFinite, Autoref::None, vec![], BOOL));
        }
        if n == k.is_sign_positive {
            return Some((B::FloatIsSignPositive, Autoref::None, vec![], BOOL));
        }
        if n == k.is_sign_negative {
            return Some((B::FloatIsSignNegative, Autoref::None, vec![], BOOL));
        }
        if n == k.to_bits {
            let bt = int(if f == FloatTy::F32 { IntTy::U32 } else { IntTy::U64 });
            return Some((B::FloatToBits, Autoref::None, vec![], bt));
        }
        if n == k.to_string {
            return Some((B::ToString, Autoref::Ref, vec![], STRING));
        }
        None
    }

    /// For `String == &str` style comparisons between different string types: the deref counts
    /// that reach each side's `String` or `str`. None if the types are not a valid mixed pair.
    fn mixed_string_eq(&self, a: Ty, b: Ty) -> Option<(u8, u8)> {
        let (ld, lb) = self.autoderef(a);
        let (rd, rb) = self.autoderef(b);
        let (Some(lk), Some(rk)) = (self.str_kind(lb, false), self.str_kind(rb, false)) else { return None };
        if lb == rb {
            return None;
        }
        string_eq_ok(ld, lk, rd, rk).then_some((ld, rd))
    }

    /// The std string type `t` is for `string_eq_ok`: String, str, or
    /// (with `cow`) `Cow<str>` (W-STD-B).
    fn str_kind(&self, t: Ty, cow: bool) -> Option<StrKind> {
        if self.tys.kind(t) == TyKind::Str {
            Some(StrKind::Str)
        } else if self.tys.is_string_ty(t) {
            Some(StrKind::String)
        } else if cow && crate::check::collect::cow_arg(&self.tys, t).is_some_and(|b| self.tys.kind(self.resolve(b)) == TyKind::Str) {
            Some(StrKind::Cow)
        } else {
            None
        }
    }

    /// Methods shared by `str` and `String` (through Deref). The receiver is always `&self`.
    /// The safe inherent methods of `*const T` and `*mut T` (w-cinterop):
    /// address queries and casts. Every one takes the pointer by value.
    /// Deref and the arithmetic that reads or writes through the pointer
    /// stay unsupported (they need `unsafe`, L0404's area), so a name
    /// outside this set falls through to the normal method error.
    fn ptr_method(
        &mut self,
        name: Sym,
        m: Mut,
        inner: Ty,
        explicit: &[Option<GenericArg>],
        name_span: Span,
    ) -> Option<(Builtin, Autoref, Vec<Ty>, Ty)> {
        use Builtin as B;
        let n = self.p.interner.get(name);
        let self_ty = self.tys.intern(TyKind::RawPtr(m, inner));
        match n {
            "is_null" => Some((B::PtrIsNull, Autoref::None, vec![], BOOL)),
            "addr" | "expose_provenance" => Some((B::PtrAddr, Autoref::None, vec![], USIZE)),
            // A fat pointer's `with_addr` keeps its metadata: not built.
            "with_addr" => {
                self.deferred_raw.push((inner, name_span, RawUse::Thin("`with_addr`")));
                Some((B::PtrWithAddr, Autoref::None, vec![USIZE], self_ty))
            }
            // `<*const [T]>::len` (tf-fatptr).
            "len" if { let d = self.deep(inner); matches!(self.kind(d), TyKind::Slice(_)) } => Some((B::PtrLen, Autoref::None, vec![], USIZE)),
            // `cast::<U>()` keeps the mutability; `cast_mut` and
            // `cast_const` keep the pointee.
            "cast" => {
                let u = explicit.first().copied().flatten().and_then(|g| g.as_ty()).unwrap_or_else(|| self.new_var(false));
                self.deferred_sized.push((u, name_span));
                Some((B::PtrCast, Autoref::None, vec![], self.tys.intern(TyKind::RawPtr(m, u))))
            }
            "cast_mut" => Some((B::PtrCastMut, Autoref::None, vec![], self.tys.intern(TyKind::RawPtr(Mut::Mut, inner)))),
            "cast_const" => Some((B::PtrCastMut, Autoref::None, vec![], self.tys.intern(TyKind::RawPtr(Mut::Shared, inner)))),
            _ => None,
        }
    }

    /// core's `[T]::split_at`, `split_at_mut`, their `_checked` forms,
    /// and `split_first`/`split_last` (and `_mut`) on `[T]`, `[T; N]`,
    /// and `Vec<T>`. Both parts borrow the receiver's loan, as core's
    /// signatures say (borrowck `receiver_builtin`).
    fn slice_split_method(&mut self, name: Sym, elem: Ty) -> Option<(Builtin, Autoref, Vec<Ty>, Ty)> {
        let n = self.name(name);
        let (b, mutable) = match n {
            "split_at" => (Builtin::SliceSplitAt(false), false),
            "split_at_mut" => (Builtin::SliceSplitAt(false), true),
            "split_at_checked" => (Builtin::SliceSplitAt(true), false),
            "split_at_mut_checked" => (Builtin::SliceSplitAt(true), true),
            "split_first" => (Builtin::SliceSplitEnd(false), false),
            "split_first_mut" => (Builtin::SliceSplitEnd(false), true),
            "split_last" => (Builtin::SliceSplitEnd(true), false),
            "split_last_mut" => (Builtin::SliceSplitEnd(true), true),
            _ => return None,
        };
        let sl = self.tys.intern(TyKind::Slice(elem));
        let part = self.tys.mk_ref(mutable, sl);
        let autoref = if mutable { Autoref::RefMut } else { Autoref::Ref };
        Some(match b {
            Builtin::SliceSplitAt(checked) => {
                let pair = self.tys.intern_tys(&[part, part]);
                let pair = self.tys.intern(TyKind::Tuple(pair));
                (b, autoref, vec![USIZE], if checked { self.tys.mk_option(pair) } else { pair })
            }
            _ => {
                let one = self.tys.mk_ref(mutable, elem);
                let pair = self.tys.intern_tys(&[one, part]);
                let pair = self.tys.intern(TyKind::Tuple(pair));
                (b, autoref, vec![], self.tys.mk_option(pair))
            }
        })
    }

    fn str_method(&mut self, name: Sym) -> Option<(Builtin, Autoref, Vec<Ty>, Ty)> {
        use Builtin as B;
        let k = &*self.p.known;
        let chars = CHARS;
        let opt_str = self.tys.mk_option(REF_STR);
        let bytes = self.tys.intern(TyKind::Slice(int(IntTy::U8)));
        let ref_bytes = self.tys.mk_ref(false, bytes);
        let n = self.p.interner.get(name);
        if n == "encode_utf16" {
            let ret = crate::ty::iter::mk_iter(&mut self.tys, crate::ty::iter::IterKind::EncodeUtf16, &[]);
            return Some((B::StrEncodeUtf16, Autoref::Ref, vec![], ret));
        }
        if n == "char_indices" || n == "bytes" {
            // (W-STD-B, lower/iter.rs.)
            let ret = if n == "bytes" {
                let it = crate::ty::iter::mk_iter(&mut self.tys, crate::ty::iter::IterKind::SliceIter, &[int(IntTy::U8)]);
                crate::ty::iter::mk_iter(&mut self.tys, crate::ty::iter::IterKind::Copied, &[it, int(IntTy::U8)])
            } else {
                crate::ty::iter::mk_iter(&mut self.tys, crate::ty::iter::IterKind::CharIndices, &[])
            };
            return Some((if n == "bytes" { B::StrBytes } else { B::StrCharIndices }, Autoref::Ref, vec![], ret));
        }
        // R3 (tf-small-a).
        match n {
            "replacen" => return Some((B::StrReplacen, Autoref::Ref, vec![REF_STR, REF_STR, USIZE], STRING)),
            "is_ascii" => return Some((B::StrIsAscii, Autoref::Ref, vec![], BOOL)),
            "eq_ignore_ascii_case" => return Some((B::StrEqIgnoreAsciiCase, Autoref::Ref, vec![REF_STR], BOOL)),
            "make_ascii_uppercase" => return Some((B::StrMakeAsciiUppercase, Autoref::RefMut, vec![], UNIT)),
            "make_ascii_lowercase" => return Some((B::StrMakeAsciiLowercase, Autoref::RefMut, vec![], UNIT)),
            "split_at" | "split_at_checked" => {
                let pair = self.tys.intern_tys(&[REF_STR, REF_STR]);
                let pair = self.tys.intern(TyKind::Tuple(pair));
                let checked = n == "split_at_checked";
                let ret = if checked { self.tys.mk_option(pair) } else { pair };
                return Some((B::StrSplitAt(checked), Autoref::Ref, vec![USIZE], ret));
            }
            _ => {}
        }
        let table = [
            // The `&[u8]` view, as `AsRef<[u8]>` gives it (W-STD-B).
            (k.as_bytes, B::ConvStrBytes, vec![], ref_bytes),
            (k.contains, B::StrContains, vec![REF_STR], BOOL),
            (k.find, B::StrFind, vec![REF_STR], self.tys.mk_option(USIZE)),
            (k.rfind, B::StrRfind, vec![REF_STR], self.tys.mk_option(USIZE)),
            (k.starts_with, B::StrStartsWith, vec![REF_STR], BOOL),
            (k.ends_with, B::StrEndsWith, vec![REF_STR], BOOL),
            (k.trim, B::StrTrim, vec![], REF_STR),
            (k.to_ascii_lowercase, B::StrToAsciiLowercase, vec![], STRING),
            (k.to_ascii_uppercase, B::StrToAsciiUppercase, vec![], STRING),
            (k.to_uppercase, B::StrToUppercase, vec![], STRING),
            (k.to_lowercase, B::StrToLowercase, vec![], STRING),
            (k.chars, B::StrChars, vec![], chars),
            (k.strip_prefix, B::StrStripPrefix, vec![REF_STR], opt_str),
            (k.strip_suffix, B::StrStripSuffix, vec![REF_STR], opt_str),
            (k.trim_start, B::StrTrimStart, vec![], REF_STR),
            (k.trim_end, B::StrTrimEnd, vec![], REF_STR),
            (k.replace, B::StrReplace, vec![REF_STR, REF_STR], STRING),
            (k.repeat, B::StrRepeat, vec![USIZE], STRING),
            (k.is_char_boundary, B::StrIsCharBoundary, vec![USIZE], BOOL),
        ];
        table.into_iter().find(|(n, ..)| *n == name).map(|(_, b, params, ret)| (b, Autoref::Ref, params, ret))
    }

    /// The arguments of a str search method, whose first is a
    /// `Pattern`: a char there records `Coerce::CharPat` (its
    /// encoding as the &str the builtin searches for, which finds
    /// exactly that char's occurrences); anything else coerces to
    /// &str as before. The rest check against their parameters.
    fn check_str_pattern_args(&mut self, params: &[Ty], args: &[ExprId], span: Span) {
        for (i, &a) in args.iter().enumerate() {
            if i > 0 {
                self.expect_expr(a, params[i]);
            } else {
                let at = self.expr(a, None);
                self.run_obligations(false);
                let deep = self.deep(at);
                if self.kind(deep) == TyKind::Char {
                    let ix = self.ei(a);
                    self.out.coerce[ix] = Coerce::CharPat;
                } else {
                    self.coerce_expr(a, at, REF_STR);
                }
            }
            self.reject_unsized_value(a);
        }
        let _ = span;
    }

    /// One binary operator through its operator trait, with the
    /// result type normalized through `Output`. None when no
    /// impl applies (the caller reports the plain operator error).
    fn trait_binop(&mut self, e: ExprId, op: BinOp, li: Ty, ri: Ty, ld: u8, rd: u8, span: Span) -> Option<Ty> {
        use BinOp::*;
        let p = self.p;
        if !self.generic_mode() {
            return None;
        }
        let lang = &p.gx.lang;
        let (trait_def, method_name) = match op {
            Add => (lang.add, "add"),
            Sub => (lang.sub, "sub"),
            Mul => (lang.mul, "mul"),
            Div => (lang.div, "div"),
            Rem => (lang.rem, "rem"),
            BitAnd => (lang.bit_and, "bitand"),
            BitOr => (lang.bit_or, "bitor"),
            BitXor => (lang.bit_xor, "bitxor"),
            Shl => (lang.shl, "shl"),
            Shr => (lang.shr, "shr"),
            _ => return None,
        };
        let out_var = self.new_var(false);
        let args_id = self.tys.intern_args(&[GenericArg::Ty(li), GenericArg::Ty(ri)]);
        let bindings = match lang.output_of(trait_def) {
            Some(assoc) => self.tys.intern_bindings(&[(assoc, GenericArg::Ty(out_var))]),
            None => EMPTY_BINDINGS,
        };
        let tr = TraitRef { def: trait_def, args: args_id, bindings };
        self.replay_operands(e, trait_def, &[li, ri]);
        let (id, impl_args) = match self.select_obligation(tr) {
            Selection::Impl { id, args, .. } => (id, args),
            Selection::ParamEvidence(i) => {
                self.record_pick_env(e, trait_def, 0, ReceiverForm::Value, Some(i));
                // A template check: the bound proves the operator. The
                // call is the trait method's stub; the result is the
                // bound's `Output`, or its rigid projection.
                let method_def = p.gx.index.trait_record(trait_def)?.method_by_name(p.interner.intern(method_name))?;
                let stub = *p.gx.trait_method_stubs.get(&method_def)?;
                if let Some(assoc) = lang.output_of(trait_def) {
                    let proj = self.tys.intern(TyKind::Projection(AssocId(assoc), args_id));
                    let normed = self.normalize_here(proj);
                    self.unify(out_var, normed);
                }
                self.set_res(e, Res::TraitBin { f: stub, ld, rd });
                return Some(self.normalize_here(out_var));
            }
            _ => return None,
        };
        let local = self.method_instance_for_impl(e, id, tr, impl_args, method_name, span)?;
        // The selected method's receiver and rhs are unified by
        // selection's probe through the trait ref above; record
        // the call for lowering.
        self.set_res(e, Res::TraitBin { f: local.0, ld, rd });
        Some(self.normalize_here(out_var))
    }

    /// A comparison operator through a written `PartialEq` or
    /// `PartialOrd` impl (`l` and `r` are the operand types with the
    /// same number of references peeled, as core's reference impls
    /// forward): records `Res::TraitCmp`. None when no written impl
    /// or bound applies; derived and core impls compare by structure
    /// (`has_eq`, `has_ord`) before this runs.
    #[allow(clippy::too_many_arguments)]
    fn trait_cmp(&mut self, e: ExprId, op: BinOp, l: Ty, r: Ty, ld: u8, rd: u8, span: Span) -> Option<Ty> {
        let lang = &self.p.gx.lang;
        let trait_def = if matches!(op, BinOp::Eq | BinOp::Ne) { lang.partial_eq } else { lang.partial_ord };
        let (f, via) = self.written_cmp_method(e, trait_def, op, l, r, span)?;
        self.set_res(e, Res::TraitCmp { f, ld, rd, via });
        Some(BOOL)
    }

    /// The method that answers comparison `op` between `l` and `r`
    /// through `trait_def` (`PartialEq` or `PartialOrd`): a written
    /// impl's own method for the operator, else the method core's
    /// default body calls (`eq` for `ne`, `partial_cmp` for `lt` and
    /// kin); in a template, the bound's stub. None for derived and
    /// core impls (they compare by structure) and when nothing applies.
    fn written_cmp_method(&mut self, e: ExprId, trait_def: DefId, op: BinOp, l: Ty, r: Ty, span: Span) -> Option<(LocalDefId, CmpVia)> {
        use crate::traits::index::Synthetic;
        let p = self.p;
        let direct = match op {
            BinOp::Eq => "eq",
            BinOp::Ne => "ne",
            BinOp::Lt => "lt",
            BinOp::Le => "le",
            BinOp::Gt => "gt",
            _ => "ge",
        };
        let args_id = self.tys.intern_args(&[GenericArg::Ty(l), GenericArg::Ty(r)]);
        let tr = TraitRef { def: trait_def, args: args_id, bindings: EMPTY_BINDINGS };
        self.replay_operands(e, trait_def, &[l, r]);
        match self.select_obligation_at(tr, span, 0) {
            Selection::Impl { id, args: impl_args, .. } => {
                let rec = p.gx.index.get(id).clone();
                if rec.synthetic != Synthetic::None {
                    return None;
                }
                let has = |n: &str| rec.items.iter().any(|d| p.local_def(d.hash).is_some_and(|f| p.name(p.fn_info(f).name) == n));
                let (method, via) = if has(direct) {
                    (direct, CmpVia::Direct)
                } else if op == BinOp::Ne {
                    ("eq", CmpVia::NotEq)
                } else if op == BinOp::Eq {
                    return None;
                } else {
                    ("partial_cmp", CmpVia::Partial(op))
                };
                let (f, _, _) = self.method_instance_for_impl(e, id, tr, impl_args, method, span)?;
                Some((f, via))
            }
            Selection::ParamEvidence(i) if i != usize::MAX => {
                let method_def = p.gx.index.trait_record(trait_def)?.method_by_name(p.interner.intern(direct))?;
                let stub = *p.gx.trait_method_stubs.get(&method_def)?;
                self.record_pick_env(e, trait_def, 0, ReceiverForm::Value, Some(i));
                Some((stub, CmpVia::Direct))
            }
            _ => None,
        }
    }

    /// Core's default bodies of the comparison traits, for a method
    /// call no impl method answers: `ne` through `eq` and `lt`/`le`/
    /// `gt`/`ge` through `partial_cmp` of a written impl
    /// (`Res::TraitCmpMethod`), and `Ord::max`/`min`/`clamp`
    /// (`Res::OrdPick`), which compare with Self's `PartialOrd`. None
    /// when another form or no impl applies (the caller reports the
    /// missing method). `base` is the receiver after `derefs` derefs.
    #[allow(clippy::too_many_arguments)]
    fn lang_default_method(&mut self, e: ExprId, recv: ExprId, base: Ty, derefs: u8, name: Sym, name_span: Span, args: &[ExprId]) -> Option<Ty> {
        let p = self.p;
        let lang = p.gx.lang;
        let op = match self.name(name) {
            "ne" => BinOp::Ne,
            "lt" => BinOp::Lt,
            "le" => BinOp::Le,
            "gt" => BinOp::Gt,
            "ge" => BinOp::Ge,
            "max" | "min" | "clamp" => return self.ord_pick_method(e, recv, base, derefs, name, name_span, args),
            _ => return None,
        };
        if args.len() != 1 || matches!(self.kind(base), TyKind::Param(_) | TyKind::Projection(..) | TyKind::Infer(_) | TyKind::Error) {
            return None;
        }
        // The argument is `&Rhs`: its type names Rhs.
        let at = self.expr(args[0], None);
        let at = self.deep(at);
        let TyKind::Ref(_, _, rhs) = self.kind(at) else { return None };
        let rhs = self.deep(rhs);
        let trait_def = if op == BinOp::Ne { lang.partial_eq } else { lang.partial_ord };
        let (f, via) = self.written_cmp_method(e, trait_def, op, base, rhs, name_span)?;
        let want = self.tys.mk_ref(false, rhs);
        self.coerce_expr(args[0], at, want);
        self.check_packed_borrow(recv, name_span);
        self.set_res(e, Res::TraitCmpMethod { f, derefs, via });
        Some(BOOL)
    }

    /// The inherent methods of `core::cmp::Ordering` lust computes in
    /// lowering (`Res::OrderingOp`): `is_eq`, `is_ne`, `is_lt`,
    /// `is_gt`, `is_le`, `is_ge`, `reverse`, and `then`. All take
    /// `self` by value (`Ordering` is `Copy`). None for another
    /// receiver, a user type named `Ordering`, or another name.
    fn ordering_method(&mut self, e: ExprId, base: Ty, derefs: u8, name: Sym, name_span: Span, args: &[ExprId]) -> Option<Ty> {
        if self.tys.adt_parts(base).map(|(d, _)| d) != Some(generics::ordering_def()) {
            return None;
        }
        use OrderingOpKind as K;
        let kind = match self.name(name) {
            "is_eq" => K::IsEq,
            "is_ne" => K::IsNe,
            "is_lt" => K::IsLt,
            "is_gt" => K::IsGt,
            "is_le" => K::IsLe,
            "is_ge" => K::IsGe,
            "reverse" => K::Reverse,
            "then" => K::Then,
            "then_with" => K::ThenWith,
            _ => return None,
        };
        // A local trait method of the same name could apply to a
        // reference receiver first, by rustc's probe order; that
        // mix is not supported (a reject, never a guess).
        let p = self.p;
        if p.gx.traits_by_method.get(&name).is_some_and(|ts| ts.iter().any(|t| p.gx.index.trait_record(*t).is_some_and(|r| r.local))) {
            for &a in args {
                self.expr(a, None);
            }
            self.errs.push(not_yet("L0720", name_span, "a local trait method named like an `Ordering` method"));
            return Some(ERROR);
        }
        let (params, ret) = match kind {
            K::Reverse => (vec![], base),
            K::Then => (vec![base], base),
            // `F: FnOnce() -> Ordering`; lowering calls closures only.
            K::ThenWith => {
                let lang = p.gx.lang;
                let f = self.new_var(false);
                let unit_args = self.tys.intern_tys(&[]);
                let unit = self.tys.intern(TyKind::Tuple(unit_args));
                let args_id = self.tys.intern_args(&[GenericArg::Ty(f), GenericArg::Ty(unit)]);
                self.obl.push(obligations::Obligation::Trait {
                    trait_ref: TraitRef { def: lang.fn_once, args: args_id, bindings: EMPTY_BINDINGS },
                    span: name_span,
                    depth: 0,
                });
                if let Some(out) = lang.output_of(lang.fn_once) {
                    self.obl.push(obligations::Obligation::AssocEq { eq: AssocEqData { assoc: out, trait_args: args_id, ty: base }, span: name_span });
                }
                (vec![f], base)
            }
            _ => (vec![], BOOL),
        };
        self.check_args(&params, args, name_span);
        if kind == K::ThenWith
            && let Some(&f) = params.first()
        {
            let at = self.deep(f);
            if !matches!(self.kind(at), TyKind::Closure(..) | TyKind::Error | TyKind::Infer(_)) {
                self.errs.push(not_yet("L0820", name_span, "`then_with` with an argument other than a closure"));
                return Some(ERROR);
            }
        }
        self.set_res(e, Res::OrderingOp { kind, derefs });
        Some(ret)
    }

    /// `Ord::max`, `min`, and `clamp` by core's default bodies
    /// (`Res::OrdPick`): Self must be `Ord`; the bodies compare with
    /// `PartialOrd::lt` (`clamp`: `le`, `lt`, `gt`) on Self, through a
    /// written impl's method or by structure. A written impl that
    /// replaces several of those methods is not supported for
    /// `clamp`. The receiver must be the value itself (no autoderef:
    /// core's `Ord for &A` would answer a reference receiver).
    #[allow(clippy::too_many_arguments)]
    fn ord_pick_method(&mut self, e: ExprId, recv: ExprId, base: Ty, derefs: u8, name: Sym, name_span: Span, args: &[ExprId]) -> Option<Ty> {
        use crate::traits::index::Synthetic;
        let p = self.p;
        let lang = p.gx.lang;
        let kind = match self.name(name) {
            "max" => OrdPickKind::Max,
            "min" => OrdPickKind::Min,
            _ => OrdPickKind::Clamp,
        };
        let n_args = if kind == OrdPickKind::Clamp { 2 } else { 1 };
        let bk = self.kind(base);
        let int_var = bk.is_int_infer();
        if derefs != 0
            || args.len() != n_args
            || (!int_var && matches!(bk, TyKind::Param(_) | TyKind::Projection(..) | TyKind::Infer(_) | TyKind::Error))
        {
            return None;
        }
        let _ = recv;
        // An integer variable is `Ord` at every type it can take.
        let ord_args = self.tys.intern_args(&[GenericArg::Ty(base)]);
        let ord_tr = TraitRef { def: lang.ord, args: ord_args, bindings: EMPTY_BINDINGS };
        if !int_var && !matches!(self.select_obligation_at(ord_tr, name_span, 0), Selection::Impl { .. } | Selection::ParamEvidence(_)) {
            return None;
        }
        self.record_glue_reads(lang.partial_ord, base);
        let (f, via) = if has_ord(p, &self.tys, base) {
            (None, CmpVia::Partial(BinOp::Lt))
        } else {
            let po_args = self.tys.intern_args(&[GenericArg::Ty(base), GenericArg::Ty(base)]);
            let po = TraitRef { def: lang.partial_ord, args: po_args, bindings: EMPTY_BINDINGS };
            let Selection::Impl { id, args: impl_args, .. } = self.select_obligation_at(po, name_span, 0) else { return None };
            let rec = p.gx.index.get(id).clone();
            if rec.synthetic != Synthetic::None {
                return None;
            }
            let has = |n: &str| rec.items.iter().any(|d| p.local_def(d.hash).is_some_and(|f| p.name(p.fn_info(f).name) == n));
            let (method, via) = if kind == OrdPickKind::Clamp {
                if ["lt", "le", "gt", "ge"].iter().any(|m| has(m)) {
                    return None;
                }
                ("partial_cmp", CmpVia::Partial(BinOp::Lt))
            } else if has("lt") {
                ("lt", CmpVia::Direct)
            } else {
                ("partial_cmp", CmpVia::Partial(BinOp::Lt))
            };
            let (f, _, _) = self.method_instance_for_impl(e, id, po, impl_args, method, name_span)?;
            (Some(f), via)
        };
        let params = vec![base; n_args];
        self.check_args(&params, args, name_span);
        self.set_res(e, Res::OrdPick { kind, f, via });
        Some(base)
    }

    /// One unary operator through its operator trait, like
    /// `trait_binop` with no right side. The result type is the
    /// bound's `Output`, normalized.
    fn trait_unop(&mut self, e: ExprId, op: ast::UnOp, inner: Ty, ld: u8, span: Span) -> Option<Ty> {
        let p = self.p;
        if !self.generic_mode() {
            return None;
        }
        let lang = &p.gx.lang;
        let (trait_def, method_name) = match op {
            ast::UnOp::Neg => (lang.neg, "neg"),
            ast::UnOp::Not => (lang.not, "not"),
        };
        let out_var = self.new_var(false);
        let args_id = self.tys.intern_args(&[GenericArg::Ty(inner)]);
        let bindings = match lang.output_of(trait_def) {
            Some(assoc) => self.tys.intern_bindings(&[(assoc, GenericArg::Ty(out_var))]),
            None => EMPTY_BINDINGS,
        };
        let tr = TraitRef { def: trait_def, args: args_id, bindings };
        let (id, impl_args) = match self.select_obligation(tr) {
            Selection::Impl { id, args, .. } => (id, args),
            Selection::ParamEvidence(_) => {
                let method_def = p.gx.index.trait_record(trait_def)?.method_by_name(p.interner.intern(method_name))?;
                let stub = *p.gx.trait_method_stubs.get(&method_def)?;
                if let Some(assoc) = lang.output_of(trait_def) {
                    let proj = self.tys.intern(TyKind::Projection(AssocId(assoc), args_id));
                    let normed = self.normalize_here(proj);
                    self.unify(out_var, normed);
                }
                self.set_res(e, Res::TraitBin { f: stub, ld, rd: 0 });
                return Some(self.normalize_here(out_var));
            }
            _ => return None,
        };
        let local = self.method_instance_for_impl(e, id, tr, impl_args, method_name, span)?;
        self.set_res(e, Res::TraitBin { f: local.0, ld, rd: 0 });
        Some(self.normalize_here(out_var))
    }

    /// One compound assignment through its assignment trait
    /// (`a += b` as `AddAssign::add_assign(&mut a, b)`). True
    /// when the trait path applies; the call is recorded as a
    /// `TraitBin` like the binary operators.
    fn trait_assign_op(&mut self, e: ExprId, op: BinOp, lt: Ty, rinner: Ty, rd: u8, span: Span) -> bool {
        use BinOp::*;
        let p = self.p;
        if !self.generic_mode() {
            return false;
        }
        let lang = &p.gx.lang;
        let (trait_def, method_name) = match op {
            Add => (lang.add_assign, "add_assign"),
            Sub => (lang.sub_assign, "sub_assign"),
            Mul => (lang.mul_assign, "mul_assign"),
            Div => (lang.div_assign, "div_assign"),
            Rem => (lang.rem_assign, "rem_assign"),
            BitAnd => (lang.bit_and_assign, "bitand_assign"),
            BitOr => (lang.bit_or_assign, "bitor_assign"),
            BitXor => (lang.bit_xor_assign, "bitxor_assign"),
            Shl => (lang.shl_assign, "shl_assign"),
            Shr => (lang.shr_assign, "shr_assign"),
            _ => return false,
        };
        let args_id = self.tys.intern_args(&[GenericArg::Ty(lt), GenericArg::Ty(rinner)]);
        let tr = TraitRef { def: trait_def, args: args_id, bindings: EMPTY_BINDINGS };
        self.replay_operands(e, trait_def, &[lt, rinner]);
        let local = match self.select_obligation(tr) {
            Selection::Impl { id, args, .. } => self.method_instance_for_impl(e, id, tr, args, method_name, span).map(|l| l.0),
            Selection::ParamEvidence(i) => {
                self.record_pick_env(e, trait_def, 0, ReceiverForm::Value, Some(i));
                let method_def = p.gx.index.trait_record(trait_def).and_then(|r| r.method_by_name(p.interner.intern(method_name)));
                method_def.and_then(|m| p.gx.trait_method_stubs.get(&m).copied())
            }
            _ => None,
        };
        match local {
            Some(f) => {
                self.set_res(e, Res::TraitBin { f, ld: 0, rd });
                true
            }
            None => false,
        }
    }

    /// Checks a binary expression, walking a left-leaning chain of
    /// non-`&&`/`||` operators (`a + b + c + ...`, up to the parser's
    /// 2000-term cap) in a loop: collect the left spine, check its
    /// base, then fold `binary_with_lt` back up. A spine of one, and
    /// `&&`/`||` (whose operands check against `bool`, not against
    /// each other), go through `binary` exactly as before.
    fn binary_chain(&mut self, e: ExprId, op: BinOp, lhs: ExprId, rhs: ExprId, span: Span) -> Ty {
        use BinOp::*;
        if matches!(op, And | Or) {
            return self.binary(e, op, lhs, rhs, span);
        }
        let p = self.p;
        let mut spine: Vec<(ExprId, BinOp, ExprId, Span)> = vec![(e, op, rhs, span)];
        let mut cur = lhs;
        while let Expr::Binary { op: o, lhs: l, rhs: r } = p.ast.expr(cur) {
            if matches!(o, And | Or) {
                break;
            }
            spine.push((cur, *o, *r, self.span(cur)));
            cur = *l;
        }
        if spine.len() == 1 {
            return self.binary(e, op, lhs, rhs, span);
        }
        let mut lt = self.expr(cur, None);
        let n = spine.len();
        for (i, (node, o, r, sp)) in spine.into_iter().rev().enumerate() {
            lt = self.binary_with_lt(node, o, lt, r, sp);
            // The outermost node's type is set by `expr` on return,
            // as `expr_inner` results always are; inner spine nodes
            // were set by the recursive `expr(lhs)` call they replace.
            if i + 1 < n {
                self.set(node, lt);
            }
        }
        lt
    }

    fn binary(&mut self, e: ExprId, op: BinOp, lhs: ExprId, rhs: ExprId, span: Span) -> Ty {
        use BinOp::*;
        if matches!(op, And | Or) {
            self.expect_expr(lhs, BOOL);
            self.expect_expr(rhs, BOOL);
            return BOOL;
        }
        let lt = self.expr(lhs, None);
        self.binary_with_lt(e, op, lt, rhs, span)
    }

    /// `binary` for a non-`&&`/`||` operator whose left operand type
    /// `lt` is already checked. Split out so `expr_inner` can check a
    /// left-leaning operator chain (`a + b + c + ...`) in a loop
    /// instead of recursing down its left spine.
    fn binary_with_lt(&mut self, e: ExprId, op: BinOp, lt: Ty, rhs: ExprId, span: Span) -> Ty {
        debug_assert!(!matches!(op, BinOp::And | BinOp::Or));
        // An open left operand gives the right one no expected type: rustc
        // checks the right operand on its own. So does a number (or a
        // number literal) on the left of arithmetic, bit, or shift
        // operators: their impls take `Rhs = T` and `Rhs = &T` (shifts any
        // integer), so rustc's `Rhs` stays a variable (`1u8 +
        // Default::default()` and `3 + it.sum()` are E0283/E0284) unless the
        // right operand fixes it (a literal, a typed value).
        let lk = self.kind(self.resolve(lt));
        let number = matches!(lk, TyKind::Int(_) | TyKind::Float(_)) || lk.is_int_infer() || lk.is_float_infer();
        // `String + x`: std's one impl is `Add<&str>`, so selection fixes
        // `Rhs = &str` before the right operand is checked (`s + if c {
        // "" } else { ">" }`, `s + &t`). `Cow<str>` has two `Add` impls,
        // so its right operand gets no expected type.
        let lt_deep = self.deep(lt);
        let expect = if op == BinOp::Add && self.tys.is_string_ty(lt_deep) {
            Some(REF_STR)
        } else if op == BinOp::Add && crate::check::collect::cow_arg(&self.tys, lt_deep) == Some(STR) {
            None
        } else {
            (!self.unbound_general(lt) && !(number && !op.is_cmp())).then_some(lt)
        };
        let rt = self.expr(rhs, expect);
        // ARCH 2.12 run point: an operator on a non-scalar must know the left
        // operand type. The scalar path above and below needs no trait search.
        self.run_obligations(false);
        if self.binop_waits(op, lt, rt) {
            return self.wait_binop(e, op, lt, rt, rhs, span);
        }
        self.binary_types(e, op, lt, rt, rhs, span)
    }

    /// True when rustc leaves this operator's trait selection pending:
    /// the left operand (under matching references) is a type variable,
    /// which an operator never binds (`?T: Add<u8>` waits for `?T`), or
    /// the right one is and the left side is a number, whose arithmetic
    /// has `Rhs = T` and `Rhs = &T` (a scalar comparison has only `Rhs =
    /// Self`, and a single written impl selects too: both bind it). Such
    /// an operator is checked at body end (`wait_binops`), and a variable
    /// still open there is rustc's E0282.
    fn binop_waits(&self, op: BinOp, lt: Ty, rt: Ty) -> bool {
        let (l, r) = self.binop_operands(op, lt, rt);
        // Both operands open (`|a, b| a + b`): the `open_binops` path.
        if self.unbound_general(l) && self.unbound_general(r) && self.unbound_general(lt) && self.unbound_general(rt) {
            return false;
        }
        if self.unbound_general(l) {
            return true;
        }
        // A mono instance's template already proved the operator through
        // its bounds (`X: Add<Output = X>` fixes `Rhs = X`): an open right
        // operand next to a now concrete left one is the template's.
        if self.p.gx.fn_class.get(self.fid.0 as usize) == Some(&generics::FnClass::Instance) {
            return false;
        }
        let k = self.kind(l);
        let scalar = matches!(k, TyKind::Int(_) | TyKind::Float(_)) || k.is_int_infer() || k.is_float_infer();
        self.unbound_general(r) && !op.is_cmp() && scalar
    }

    /// The operand types an operator's impls select on: under matching
    /// references for a comparison (`&A: PartialEq<&B>` is `A: PartialEq<B>`),
    /// under one reference each for arithmetic (`&u8: Add<u8>`).
    fn binop_operands(&self, op: BinOp, lt: Ty, rt: Ty) -> (Ty, Ty) {
        let (mut l, mut r) = (self.resolve(lt), self.resolve(rt));
        if op.is_cmp() {
            while let (TyKind::Ref(_, _, a), TyKind::Ref(_, _, b)) = (self.kind(l), self.kind(r)) {
                (l, r) = (self.resolve(a), self.resolve(b));
            }
            (l, r)
        } else {
            (self.resolve(self.peel_one_ref(l).1), self.resolve(self.peel_one_ref(r).1))
        }
    }

    /// An operator `binop_waits` holds until body end: a comparison is
    /// `bool`; arithmetic gives a variable for its result. With the left
    /// operand open, `<L as Op<R>>::Output` fixes it as soon as a later
    /// use fixes `L` (`|x| x * 2` called with a `u64`, then `y.pow(2)`);
    /// with a literal left operand and an open right one (`|x| 1 + x`),
    /// literal fallback decides it.
    /// With the left side a known number and the right one open, the
    /// projection would pick one of the `Rhs = T` and `Rhs = &T` impls,
    /// so only the body-end check (`finish_wait_binops`) binds it; also
    /// for a reference operand, whose scalar impls (`u32: Add<&u32>`,
    /// `&i32: Add<i32>`) the solver does not have.
    fn wait_binop(&mut self, e: ExprId, op: BinOp, lt: Ty, rt: Ty, rhs: ExprId, span: Span) -> Ty {
        self.set_res(e, Res::Bin { ld: 0, rd: 0 });
        let out = if op.is_cmp() { BOOL } else { self.new_var(false) };
        let (l, r) = self.binop_operands(op, lt, rt);
        let lk = self.kind(l);
        let literal_left = lk.is_int_infer() || lk.is_float_infer();
        let mut projected = false;
        if let Some(assoc) = self.binop_output_assoc(op)
            && ((self.unbound_general(l) && !self.unbound_general(r)) || (literal_left && self.unbound_general(r)))
            && !matches!(self.kind(self.resolve(rt)), TyKind::Ref(..))
            && !matches!(self.kind(self.resolve(lt)), TyKind::Ref(..))
        {
            let trait_args = self.tys.intern_args(&[GenericArg::Ty(lt), GenericArg::Ty(rt)]);
            self.obl.push(obligations::Obligation::AssocEq { eq: AssocEqData { assoc, trait_args, ty: out }, span });
            projected = true;
        }
        // A projected result is the projection's alone: literal fallback
        // decides it (`|x| x + 1` called with a literal is i32 + i32, and
        // a `u64` use is rustc's E0271), so body end does not bind it.
        let out_slot = if projected { None } else { Some(out) };
        self.wait_binops.push((e, op, lt, rt, rhs, span, out_slot));
        out
    }

    /// The `Output` item of an arithmetic or bit operator's trait.
    fn binop_output_assoc(&self, op: BinOp) -> Option<DefId> {
        use BinOp::*;
        let lang = &self.p.gx.lang;
        let tr = match op {
            Add => lang.add,
            Sub => lang.sub,
            Mul => lang.mul,
            Div => lang.div,
            Rem => lang.rem,
            BitAnd => lang.bit_and,
            BitOr => lang.bit_or,
            BitXor => lang.bit_xor,
            Shl => lang.shl,
            Shr => lang.shr,
            _ => return None,
        };
        lang.output_of(tr)
    }

    /// For a raw pointer's pointee: None when sized, Some(true) for the
    /// fat pointees lust builds (`str`, `[T]`, `dyn Tr`), Some(false) for
    /// other unsized ones (a struct with an unsized tail, `RefCell<dyn Tr>`).
    fn fat_pointee(&mut self, t: Ty) -> Option<bool> {
        let t = self.deep(t);
        match self.kind(t) {
            TyKind::Str | TyKind::Slice(_) | TyKind::Dyn(..) => Some(true),
            TyKind::Adt(d, _) if self.tys.unsized_field(d).is_some() => Some(false),
            _ if crate::check::own::dyn_cell_elem(&self.tys, t).is_some() || crate::check::own::dyn_lock_elem(&self.tys, t).is_some() => Some(false),
            _ => None,
        }
    }

    /// Body end (tf-fatptr): the raw pointer pointees and casts
    /// recorded in `deferred_raw` and `deferred_raw_casts`.
    fn check_deferred_raw(&mut self) {
        for (t, span, u) in std::mem::take(&mut self.deferred_raw) {
            let fat = self.fat_pointee(t);
            let d = self.deep(t);
            let is_dyn = matches!(self.kind(d), TyKind::Dyn(..));
            // A `T: ?Sized` param may be `dyn Tr` at an instance.
            let maybe_fat = matches!(self.kind(d), TyKind::Param(_)) && !self.sized_ok(d);
            let what = match (u, fat) {
                (RawUse::Thin(w) | RawUse::NotDyn(w), None) if maybe_fat => w,
                (_, None) => continue,
                (_, Some(false)) => "a raw pointer to this unsized type",
                (RawUse::Pointee, Some(true)) => continue,
                (RawUse::NotDyn(_), Some(true)) if !is_dyn => continue,
                (RawUse::Thin(w) | RawUse::NotDyn(w), Some(true)) => w,
            };
            let fix = if is_dyn { "Compare addresses with `std::ptr::addr_eq`, or cast to a thin pointer first (`p.cast::<()>()`)." } else { "Cast to a thin pointer first (`p.cast::<u8>()`)." };
            self.err("L0602", span, format!("{what} on a raw pointer to an unsized type is not supported yet"), fix);
        }
        for (from, to, span) in std::mem::take(&mut self.deferred_raw_casts) {
            let (from, to) = (self.deep(from), self.deep(to));
            // A pointee's class: thin (sized), fat (`str`, `[T]`, `dyn Tr`),
            // or maybe fat (a `T: ?Sized` param, rustc's "may be wide").
            #[derive(PartialEq)]
            enum C {
                Thin,
                Fat,
                MaybeFat,
            }
            let class = |cx: &mut Self, t: Ty| match cx.kind(t) {
                TyKind::RawPtr(_, e) => Some(match cx.fat_pointee(e) {
                    Some(_) => C::Fat,
                    None => {
                        let e = cx.deep(e);
                        if matches!(cx.kind(e), TyKind::Param(_)) && !cx.sized_ok(e) { C::MaybeFat } else { C::Thin }
                    }
                }),
                _ => None,
            };
            let (a, b) = (class(self, from), class(self, to));
            let err = match (a, b) {
                // To or from an integer: thin pointers only (rustc E0606).
                (Some(C::Thin), None) | (None, Some(C::Thin)) => None,
                (Some(_), None) | (None, Some(_)) => Some("L0116"),
                // To a thin pointer: always (a fat one gives its address).
                (Some(_), Some(C::Thin)) => None,
                // Thin to fat is no cast (E0607); a coercion cast does not get here.
                (Some(C::Thin), Some(_)) => Some("L0116"),
                // Fat to fat: the same pointee at another mutability. Other
                // known fat pairs (`[u32]` to `[u8]`) are valid Rust lust
                // does not build; a pair with a `?Sized` param is E0606.
                (Some(x), Some(y)) => {
                    let (TyKind::RawPtr(_, p), TyKind::RawPtr(_, q)) = (self.kind(from), self.kind(to)) else { unreachable!() };
                    if self.unify(p, q) {
                        None
                    } else if x == C::Fat && y == C::Fat {
                        Some("L0602")
                    } else {
                        Some("L0116")
                    }
                }
                (None, None) => None,
            };
            if let Some(code) = err {
                let (a, b) = (self.tn(from), self.tn(to));
                let (msg, fix) = if code == "L0116" {
                    (format!("cannot cast `{a}` as `{b}`"), "A fat raw pointer casts only to a thin raw pointer (`p as *const u8`), then to an integer.")
                } else {
                    (format!("the raw pointer cast `{a}` as `{b}` is not supported yet"), "Cast to a thin raw pointer instead (`p as *const u8`).")
                };
                self.err(code, span, msg, fix);
            }
        }
    }

    /// A compound assignment `lhs op= rhs` once both operand types are
    /// checked (`Expr::AssignOp`, or body end for `wait_assign_ops`).
    fn assign_op_types(&mut self, e: ExprId, op: BinOp, lt: Ty, rt: Ty, rhs: ExprId, span: Span) -> Ty {
        let lk = self.kind(lt);
        if self.tys.is_string_ty(self.resolve(lt)) && op == BinOp::Add {
            self.coerce_expr(rhs, rt, REF_STR);
            self.set_res(e, Res::Bin { ld: 0, rd: 0 });
            return UNIT;
        }
        if crate::check::collect::cow_arg(&self.tys, self.resolve(lt)) == Some(STR) && op == BinOp::Add {
            let rt_deep = self.deep(rt);
            if crate::check::collect::cow_arg(&self.tys, rt_deep) != Some(STR) {
                // Two `AddAssign` impls: no coercion of the right side (E0277).
                let exact_str = matches!(self.kind(rt_deep), TyKind::Ref(_, Mut::Shared, inner) if self.resolve(inner) == STR);
                if !exact_str && !matches!(self.kind(rt_deep), TyKind::Error) {
                    let rn = self.tn(rt_deep);
                    self.err("L0113", span, format!("cannot add-assign `{rn}` to `Cow<str>`"), "Add a `&str` (`&*s`, `s.as_str()`) or a `Cow<str>`.");
                    return UNIT;
                }
                self.coerce_expr(rhs, rt, REF_STR);
            }
            self.set_res(e, Res::Bin { ld: 0, rd: 0 });
            return UNIT;
        }
        let (rd, rinner) = self.peel_one_ref(rt);
        // `x += &y` is fine, but Rust has no compound assignment with a `&mut` operand.
        let rmut = matches!(self.kind(rt), TyKind::Ref(_, Mut::Mut, _));
        let int_like = |k: TyKind| matches!(k, TyKind::Int(_)) || k.is_int_infer();
        let ok = !rmut
            && match (op, lk) {
                (BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div | BinOp::Rem, TyKind::Float(_)) => self.unify(lt, rinner),
                (BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div | BinOp::Rem, k) if k.is_float_infer() => self.unify(lt, rinner),
                (_, TyKind::Error) => true,
                (BinOp::Shl | BinOp::Shr, k) if int_like(k) => int_like(self.kind(rinner)),
                (_, k) if int_like(k) => self.unify(lt, rinner),
                (BinOp::BitAnd | BinOp::BitOr | BinOp::BitXor, TyKind::Bool) => self.unify(lt, rinner),
                _ => false,
            };
        if !ok {
            // Through the assignment trait, like the binary
            // operators: a bound proves it in a template, the
            // unique impl answers in an instance.
            // The right side as written (no peeled reference):
            // `a += &b` needs `impl AddAssign<&B> for A`.
            if !rmut && self.trait_assign_op(e, op, lt, rt, 0, span) {
                return UNIT;
            }
            let (a, b) = (self.tn(lt), self.tn(rt));
            if int_shape(&a).is_some() && int_shape(&b).is_some() && !matches!(op, BinOp::Shl | BinOp::Shr) {
                let at = self.span(rhs);
                self.err_cast(
                    "L0113",
                    span,
                    format!("cannot apply `{}=` to `{a}` and `{b}`", op.symbol()),
                    format!("Cast the right side: write `(rhs) as {a}`."),
                    at,
                    &b,
                    &a,
                );
            } else {
                self.err(
                    "L0113",
                    span,
                    format!("cannot apply `{}=` to `{a}` and `{b}`", op.symbol()),
                    "Both sides must be the same integer type.",
                );
            }
        }
        self.set_res(e, Res::Bin { ld: 0, rd });
        UNIT
    }

    /// `assert_eq!`/`assert_ne!` operand types `a` and `b`: one type with
    /// PartialEq and Debug, or a String against a `&str`.
    fn assert_eq_types(&mut self, e: ExprId, a: Ty, b: Ty, span: Span, s: Span) {
        if let Some((ld, rd)) = self.mixed_string_eq(a, b) {
            // String against &str: compared as strings, as Rust's PartialEq impls do.
            self.set_res(e, Res::Bin { ld, rd });
        } else if self.unify(a, b) {
            let a = self.deep(a);
            if !has_eq(self.p, &self.tys, a) || !has_debug(self.p, &self.tys, a) {
                let tn = self.tn(a);
                self.err(
                    "L0112",
                    span,
                    format!("assert_eq! needs PartialEq and Debug, but `{tn}` lacks one"),
                    "Derive PartialEq and Debug on the type.",
                );
            }
        } else {
            self.mismatch(s, a, b);
        }
    }

    /// Body end: each operator `wait_binop` held is checked now that
    /// its operand types are known, or is an annotation error; so is
    /// each `assert_eq!` whose left type was open (`wait_asserts`).
    fn finish_wait_binops(&mut self) {
        for (e, op, lt, rt, rhs, span) in std::mem::take(&mut self.wait_assign_ops) {
            if self.unbound_general(self.resolve(lt)) {
                self.err(
                    "L0610",
                    span,
                    "type annotations needed: the left operand type of this operator must be known here",
                    "Annotate the type of the value, such as `let mut x: u8 = make();`.",
                );
                continue;
            }
            if self.unbound_general(self.resolve(self.peel_one_ref(rt).1)) {
                self.err(
                    "L0610",
                    span,
                    "type annotations needed: the right operand type of this operator must be known here",
                    "Annotate the type of the right operand, such as `let r: u8 = make();`.",
                );
                continue;
            }
            self.assign_op_types(e, op, lt, rt, rhs, span);
        }
        for (e, a, b, span, s) in std::mem::take(&mut self.wait_asserts) {
            if self.unbound_general(self.resolve(a)) {
                self.err(
                    "L0610",
                    span,
                    "type annotations needed: the type of the left value must be known here",
                    "Annotate the type of the value, such as `let x: i32 = make();`.",
                );
                continue;
            }
            self.assert_eq_types(e, a, b, span, s);
        }
        for (e, op, lt, rt, rhs, span, out) in std::mem::take(&mut self.wait_binops) {
            if self.binop_waits(op, lt, rt) {
                self.err(
                    "L0610",
                    span,
                    "type annotations needed: the operand types of this operator must be known here",
                    "Annotate the type of the operand, such as `let v: Vec<i32> = Vec::new();`.",
                );
                continue;
            }
            let t = self.binary_types(e, op, lt, rt, rhs, span);
            if let Some(out) = out
                && t != ERROR
                && !self.unify(out, t)
            {
                self.mismatch(span, out, t);
            }
        }
    }

    /// `binary_with_lt` once both operand types are checked.
    fn binary_types(&mut self, e: ExprId, op: BinOp, lt: Ty, rt: Ty, rhs: ExprId, span: Span) -> Ty {
        use BinOp::*;
        self.replay_pick_operands(e, &[lt, rt]);
        let (lk, rk) = (self.kind(lt), self.kind(rt));
        if lk == TyKind::Error || rk == TyKind::Error {
            return if op.is_cmp() { BOOL } else { ERROR };
        }
        let bad = |cx: &mut Self| {
            let (a, b) = (cx.tn(lt), cx.tn(rt));
            let fix = if op.is_cmp() && (a.starts_with('&') != b.starts_with('&')) {
                "Compare values of the same type: dereference the reference with `*`, or borrow the other side."
            } else {
                "Both operands must have the same type, and the type must support this operator."
            };
            if int_shape(&a).is_some() && int_shape(&b).is_some() && !matches!(op, Shl | Shr) {
                let at = cx.span(rhs);
                let fix = format!("Cast the right operand: write `(rhs) as {a}`.");
                cx.err_cast("L0113", span, format!("cannot apply `{}` to `{a}` and `{b}`", op.symbol()), fix, at, &b, &a);
            } else {
                cx.err("L0113", span, format!("cannot apply `{}` to `{a}` and `{b}`", op.symbol()), fix);
            }
            if op.is_cmp() { BOOL } else { ERROR }
        };
        // Both operand types still open (closure parameters a later
        // call fixes, `|a, b| a + b`): assume the builtin scalar
        // operator (Rhs = Self), check at body end that the types are
        // scalar, and take the result from the operator's `Output`
        // as rustc's `Op<Rhs>` selection does (see the int arm below).
        if self.unbound_general(lt) && self.unbound_general(rt) {
            if !self.unify(lt, rt) {
                return bad(self);
            }
            self.open_binops.push((e, op, lt));
            self.set_res(e, Res::Bin { ld: 0, rd: 0 });
            if op.is_cmp() {
                return BOOL;
            }
            let lang = &self.p.gx.lang;
            let tr = match op {
                Add => lang.add,
                Sub => lang.sub,
                Mul => lang.mul,
                Div => lang.div,
                Rem => lang.rem,
                BitAnd => lang.bit_and,
                BitOr => lang.bit_or,
                BitXor => lang.bit_xor,
                Shl => lang.shl,
                _ => lang.shr,
            };
            let out = self.new_var(false);
            if let Some(assoc) = lang.output_of(tr) {
                let trait_args = self.tys.intern_args(&[GenericArg::Ty(lt), GenericArg::Ty(rt)]);
                self.obl.push(obligations::Obligation::AssocEq { eq: AssocEqData { assoc, trait_args, ty: out }, span });
            }
            return out;
        }
        if op.is_cmp() {
            // String equality across String, str, and `Cow<str>`.
            let (ld, lb) = self.autoderef(lt);
            let (rd, rb) = self.autoderef(rt);
            if let (Some(lk), Some(rk)) = (self.str_kind(lb, true), self.str_kind(rb, true))
                && matches!(op, Eq | Ne)
            {
                if !string_eq_ok(ld, lk, rd, rk) {
                    return bad(self);
                }
                self.set_res(e, Res::Bin { ld, rd });
                return BOOL;
            }
            // Comparisons across sequence forms (`&[u8] == &[u8; N]`,
            // `Vec<T> == [T; N]`; check/slice.rs): core's asymmetric
            // slice/array/Vec `PartialEq` impls, as slice compares.
            if let Some(t) = self.seq_cmp(e, op, lt, rt, ld, lb, rd, rb, span) {
                return t;
            }
            // A written `PartialEq<Rhs>` or `PartialOrd<Rhs>` whose
            // Rhs is the right operand's type as written (`PathBuf
            // == &Path`, `Meters == &str`): rustc's operator lookup
            // selects by trait with that Rhs, not by first stripping
            // both sides to a common type. Try it when the operand
            // types differ as written; same-type comparisons keep
            // the structural path below. A failed selection rolls
            // back so the guards below still report the plain
            // operator error.
            {
                let (dl, dr) = (self.deep(lt), self.deep(rt));
                if dl != dr {
                    let snap = self.snapshot_vars();
                    let obl_len = self.obl_len();
                    if let Some(t) = self.trait_cmp(e, op, dl, dr, 0, 0, span) {
                        return t;
                    }
                    self.rollback_vars(snap);
                    self.obl_truncate(obl_len);
                }
            }
            // Equality allows `&T` against `&mut T`; ordering needs the same mutability.
            if !matches!(op, Eq | Ne) && self.ref_layers(lt) != self.ref_layers(rt) {
                return bad(self);
            }
            if ld != rd {
                return bad(self);
            }
            let snap = self.snapshot_vars();
            if !self.unify(lb, rb) {
                // Operands of two types compare only through a
                // written impl (`impl PartialEq<u8> for P`).
                self.rollback_vars(snap);
                let (lb, rb) = (self.deep(lb), self.deep(rb));
                if let Some(t) = self.trait_cmp(e, op, lb, rb, ld, rd, span) {
                    return t;
                }
                return bad(self);
            }
            let lb = self.deep(lb);
            let ok = match self.tys.kind(lb) {
                TyKind::Int(_) | TyKind::Float(_) | TyKind::Bool | TyKind::Char | TyKind::Str => true,
                k if k.is_int_infer() || k.is_float_infer() || self.tys.is_string_ty(lb) => true,
                _ if matches!(op, Eq | Ne) => has_eq(self.p, &self.tys, lb),
                _ => has_ord(self.p, &self.tys, lb),
            };
            if !ok && let Some(t) = self.trait_cmp(e, op, lb, lb, ld, rd, span) {
                return t;
            }
            // A structural answer depends on derives and on the written
            // `eq` impls the glue calls: both are in the Adt layouts read.
            if ok {
                self.record_glue_reads(self.p.gx.lang.partial_eq, lb);
            }
            if !ok {
                let tn = self.tn(lb);
                let fix = if matches!(op, Eq | Ne) {
                    "Add #[derive(PartialEq)] to the type."
                } else {
                    "Add #[derive(PartialOrd)] to the type, or implement `PartialOrd` for it."
                };
                self.err("L0112", span, format!("type `{tn}` cannot be compared with `{}`", op.symbol()), fix);
            }
            self.set_res(e, Res::Bin { ld, rd });
            return BOOL;
        }
        // String + &str.
        if op == Add && self.tys.is_string_ty(self.resolve(lt)) {
            self.coerce_expr(rhs, rt, REF_STR);
            self.set_res(e, Res::Bin { ld: 0, rd: 0 });
            return STRING;
        }
        // Cow<str> + &str (a Cow right side stays a Cow: the
        // separate `Add<Cow>` impl reads its view at lowering). With two
        // impls rustc selects on the right operand's own type, so it does
        // not coerce it: `cow + &string` is E0277.
        let lt_deep = self.deep(lt);
        if op == Add && crate::check::collect::cow_arg(&self.tys, lt_deep) == Some(STR) {
            let rt_deep = self.deep(rt);
            if crate::check::collect::cow_arg(&self.tys, rt_deep) != Some(STR) {
                let exact_str = matches!(self.kind(rt_deep), TyKind::Ref(_, Mut::Shared, inner) if self.resolve(inner) == STR);
                if !exact_str && !matches!(self.kind(rt_deep), TyKind::Error) {
                    let rn = self.tn(rt_deep);
                    self.err("L0113", span, format!("cannot add `{rn}` to `Cow<str>`"), "Add a `&str` (`&*s`, `s.as_str()`) or a `Cow<str>`.");
                    return ERROR;
                }
                self.coerce_expr(rhs, rt, REF_STR);
            }
            self.set_res(e, Res::Bin { ld: 0, rd: 0 });
            return self.deep(lt);
        }
        // Arithmetic and bit operations exist for `&T` operands, but not for `&mut T`.
        if matches!(lk, TyKind::Ref(_, Mut::Mut, _)) || matches!(rk, TyKind::Ref(_, Mut::Mut, _)) {
            return bad(self);
        }
        let (ld, li) = self.peel_one_ref(lt);
        let (rd, ri) = self.peel_one_ref(rt);
        let (lik, rik) = (self.kind(li), self.kind(ri));
        let int_like = |k: TyKind| matches!(k, TyKind::Int(_)) || k.is_int_infer();
        // Operator traits on non-scalars (section 2.5): the
        // builtin scalar path above stays first, as ARCH requires.
        // A scalar left side with a user type on the right (`2 * v`
        // through `impl Mul<V> for i32`) also goes through the trait.
        let user_rhs = self.tys.local_adt(self.resolve(ri)).is_some();
        if (user_rhs || (!int_like(lik) && !matches!(lik, TyKind::Bool)))
            && let Some(t) = self.trait_binop(e, op, lt, rt, 0, 0, span)
        {
            return t;
        }
        let result = match op {
            Add | Sub | Mul | Div | Rem
                if (matches!(lik, TyKind::Float(_)) || lik.is_float_infer())
                    && (matches!(rik, TyKind::Float(_)) || rik.is_float_infer()) =>
            {
                if !self.unify(li, ri) {
                    return bad(self);
                }
                li
            }
            Shl | Shr if int_like(lik) && int_like(rik) => li,
            BitAnd | BitOr | BitXor if lik == TyKind::Bool && rik == TyKind::Bool => BOOL,
            // One concrete int side fixes an unbound variable on
            // the other: scalar `Add` (and friends) have
            // Rhs = Self, Output = Self, so this is the same
            // binding the trait impl would make. Closure
            // signature inference depends on it.
            Add | Sub | Mul | Div | Rem | BitAnd | BitOr | BitXor
                if (int_like(lik) && (int_like(rik) || matches!(rik, TyKind::Infer(_))))
                    || (int_like(rik) && matches!(lik, TyKind::Infer(_))) =>
            {
                let general = |k: TyKind| matches!(k, TyKind::Infer(v) if !v.is_int() && !v.is_float());
                // A second check of a closure body (`deferred_closures`)
                // sees the operand fixed by then; rustc checks the body
                // once, so an operator deferred there stays deferred.
                let deferred = general(lik) || general(rik) || self.deferred_binops.contains(&e);
                if deferred && !self.deferred_binops.contains(&e) {
                    self.deferred_binops.push(e);
                }
                if !self.unify(li, ri) {
                    return bad(self);
                }
                if deferred {
                    // An operand that is a general variable (a closure
                    // parameter not known yet): rustc resolves the
                    // operator through `Op<Rhs>` selection, so the
                    // result is that impl's `Output`, known once the
                    // operand is (after literal fallback at the
                    // latest), not the operand itself. `|x| x + 1`
                    // called with a literal into a `u64` is then
                    // `i32 + i32`: a mismatch (rustc E0271).
                    let lang = &self.p.gx.lang;
                    let tr = match op {
                        Add => lang.add,
                        Sub => lang.sub,
                        Mul => lang.mul,
                        Div => lang.div,
                        Rem => lang.rem,
                        BitAnd => lang.bit_and,
                        BitOr => lang.bit_or,
                        _ => lang.bit_xor,
                    };
                    let out = self.new_var(false);
                    if let Some(assoc) = lang.output_of(tr) {
                        let trait_args = self.tys.intern_args(&[GenericArg::Ty(li), GenericArg::Ty(ri)]);
                        self.obl.push(obligations::Obligation::AssocEq { eq: AssocEqData { assoc, trait_args, ty: out }, span });
                    }
                    out
                } else {
                    li
                }
            }
            _ => return bad(self),
        };
        self.set_res(e, Res::Bin { ld, rd });
        result
    }

    fn struct_lit(
        &mut self,
        e: ExprId,
        path: &[ast::PathSeg],
        fields: &[(Sym, Span, ExprId)],
        update: Option<ExprId>,
        span: Span,
        expected: Option<Ty>,
    ) -> Ty {
        let p = self.p;
        let target = if path.len() == 1 {
            let n = path[0].name;
            // The flat type table answers below; the binding query is the
            // recorded read of that answer (ARCH 8.2).
            if n != p.known.self_type {
                self.binding(Namespace::Type, n);
            }
            let a = if n == p.known.self_type { self.self_adt() } else { self.type_name_adt(n) };
            let a = a.or_else(|| self.alias_adt(n).map(|(a, _)| a));
            match a.filter(|&a| !p.adt(a).is_enum).map(|a| (a, 0u32)) {
                Some(v) => Some(v),
                // An imported struct-like variant (`use E::*; C { .. }`).
                None => match self.pat_ident(n) {
                    PatIdent::Variant(a, v) => Some((a, v)),
                    _ => None,
                },
            }
        } else {
            match self.resolve_assoc(path, span) {
                Some(Res::Variant(a, v)) => Some((a, v)),
                _ => return ERROR,
            }
        };
        let Some((a, v)) = target else {
            for &(_, _, fe) in fields {
                self.expr(fe, None);
            }
            if let Some(u) = update {
                self.expr(u, None);
            }
            self.err("L0102", span, "unknown struct", "Check the struct name.");
            return ERROR;
        };
        self.set_res(e, Res::Variant(a, v));
        self.check_ne_lit(a, v, span);
        // A generic Adt literal instantiates its parameters from any
        // turbofish (with defaults) and the written fields: field types
        // are the template's, substituted with those args.
        let gen_args: Vec<GenericArg> = self.value_path_args(a, path, span);
        // An expectation of the same Adt (`let r: P<[u32]> = P { .. }`,
        // `W<&dyn Tr>`) fixes the params first, so the fields become
        // coercion sites for them (`|v| &v.links` to `fn(&V) -> &[u32]`,
        // `Box::new([1, 2])` to `Box<[u8]>`), as rustc's expected inputs
        // make them (ARCH 2.8). A user Adt never coerces to another
        // instance of itself, so the literal's type must be that one.
        if !gen_args.is_empty()
            && let Some(want) = expected.map(|t| self.deep(t))
            && let Some((def, eargs)) = self.tys.adt_parts(want)
            && def == p.gx.adt_info[a.0 as usize].0
        {
            let eargs: Vec<GenericArg> = self.tys.args(eargs).to_vec();
            for (g, w) in gen_args.iter().zip(eargs) {
                if let (GenericArg::Ty(x), GenericArg::Ty(y)) = (*g, w) {
                    self.unify(x, y);
                }
            }
        }
        let variant = &p.adt(a).variants[v as usize];
        // Tuple structs take index fields here (`T { 0: 5, ..a }`); their
        // field names are the index as a synthetic Sym, so the matching
        // below works for both shapes.
        if !matches!(variant.shape, VariantShape::Named | VariantShape::Tuple) && !(variant.fields.is_empty() && fields.is_empty()) {
            self.err("L0110", span, "this is not a struct with named fields", "Use the tuple or unit form.");
            return ERROR;
        }
        let mut seen = vec![false; variant.fields.len()];
        for &(fname, fspan, fe) in fields {
            match variant.fields.iter().position(|f| f.name == fname) {
                Some(i) => {
                    if seen[i] {
                        self.err("L0106", fspan, format!("field `{}` is set twice", self.name(fname)), "Remove one of them.");
                    }
                    seen[i] = true;
                    self.check_field_vis(a, fname, fspan);
                    let want = if gen_args.is_empty() { variant.fields[i].ty } else { self.subst_norm(variant.fields[i].ty, &gen_args, fspan) };
                    self.expect_expr(fe, want);
                    self.reject_unsized_value(fe);
                }
                None => {
                    self.expr(fe, None);
                    self.err("L0103", fspan, format!("no field `{}` on this struct", self.name(fname)), "Check the field name.");
                }
            }
        }
        // Struct update: the fields not written come from the base value.
        if let Some(u) = update {
            if self.is_rest_elem(u) {
                self.set(u, ERROR);
                self.err("L0110", self.span(u), "base expression required after `..`", "Add the value to fill the rest from, as in `..base`.");
                return ERROR;
            }
            if p.adt(a).is_enum {
                self.expr(u, None);
                self.err("L0110", span, "functional record update syntax requires a struct", "Set every field of the variant.");
                return ERROR;
            }
            // A field filled from the base must be visible here too
            // (rustc E0451): building a value with a private field from
            // another module is not allowed even by moving it through.
            for (i, f) in variant.fields.iter().enumerate() {
                if !seen[i] {
                    if variant.shape == VariantShape::Tuple {
                        self.check_tuple_field_vis(a, i as u32, span);
                    } else {
                        self.check_field_vis(a, f.name, span);
                    }
                }
            }
            // The base has the literal's own type (type-changing update
            // is unstable): `Hooks<u8> { a, ..Hooks::default() }`.
            let at = if gen_args.is_empty() {
                self.tys.adt_ty(a)
            } else {
                let (def, _) = p.gx.adt_info[a.0 as usize];
                self.tys.mk_adt(def, &gen_args)
            };
            self.expect_expr(u, at);
            if !gen_args.is_empty() {
                let preds = p.gx.adt_generics[a.0 as usize].predicates.clone();
                if !preds.is_empty() {
                    self.push_predicates(&preds, &gen_args, span);
                }
            }
            return at;
        }
        let missing: Vec<String> =
            variant.fields.iter().zip(&seen).filter(|(_, s)| !**s).map(|(f, _)| self.name(f.name).to_string()).collect();
        if !missing.is_empty() {
            self.err(
                "L0107",
                span,
                format!("missing fields: {}", missing.join(", ")),
                "Set every field, or fill the rest from another value with `..base`.",
            );
        }
        // Forming the type owes its parameter bounds.
        if !gen_args.is_empty() {
            let preds = p.gx.adt_generics[a.0 as usize].predicates.clone();
            if !preds.is_empty() {
                self.push_predicates(&preds, &gen_args, span);
            }
        }
        if gen_args.is_empty() {
            self.tys.adt_ty(a)
        } else {
            let (def, _) = p.gx.adt_info[a.0 as usize];
            self.tys.mk_adt(def, &gen_args)
        }
    }

    fn for_iter(&mut self, for_e: ExprId, iter: ExprId) -> Ty {
        let p = self.p;
        // `lo..` loops through its `RangeFrom` iterator (below).
        if let Expr::Range { lo, hi, inclusive } = p.ast.expr(iter)
            && !(lo.is_some() && hi.is_none() && !inclusive)
        {
            // `..hi`, `..=hi`, and `..` are no iterators (rustc E0277).
            let (Some(lo), Some(hi)) = (*lo, *hi) else {
                let s = self.span(iter);
                let kind = match (hi.is_some(), *inclusive) {
                    (false, _) => "RangeFull",
                    (true, false) => "RangeTo",
                    (true, true) => "RangeToInclusive",
                };
                self.err("L0612", s, format!("`std::ops::{kind}` is not an iterator"), "Give the range a start: `0..n`.");
                return ERROR;
            };
            let lt = self.expr(lo, None);
            let ht = self.expr(hi, Some(lt));
            // A `char` range loops through its iterator (core's
            // `Step for char` skips the surrogates), not the integer
            // counting loop lowering keeps for a syntactic range.
            if matches!(self.kind(self.resolve(lt)), TyKind::Char) && self.unify(lt, ht) {
                let Expr::Range { inclusive, .. } = p.ast.expr(iter) else { unreachable!() };
                let k = if *inclusive { crate::ty::iter::IterKind::RangeInclusive } else { crate::ty::iter::IterKind::Range };
                let rt = crate::ty::iter::mk_iter(&mut self.tys, k, &[CHAR]);
                self.set(iter, rt);
                return CHAR;
            }
            let ok = (matches!(self.kind(lt), TyKind::Int(_)) || self.kind(lt).is_int_infer()) && self.unify(lt, ht);
            if !ok {
                let s = self.span(iter);
                let (a, b) = (self.tn(lt), self.tn(ht));
                self.err(
                    "L0110",
                    s,
                    format!("range bounds must be the same integer type, found `{a}` and `{b}`"),
                    "Use integers of one type.",
                );
            }
            self.set(iter, ERROR);
            return lt;
        }
        let t = self.expr(iter, None);
        // An `Option` or `Result`, by value or by reference
        // (fx-option-rest): the loop runs its one-item iterator
        // (`opt_res_iter`).
        let dt0 = self.deep(t);
        if let Some(it) = crate::ty::iter::opt_res_iter(&mut self.tys, dt0) {
            return crate::ty::iter::item_ty(&mut self.tys, it).unwrap_or(ERROR);
        }
        // A map or set, by value or by reference (W-STD-B): the loop
        // runs its hash iterator (`hash_for_iter`).
        let dt = self.deep(t);
        if let Some(it) = crate::ty::iter::hash_for_iter(&mut self.tys, dt) {
            return match it {
                Some(it) => crate::ty::iter::item_ty(&mut self.tys, it).unwrap_or(ERROR),
                None => {
                    let s = self.span(iter);
                    let tn = self.tn(t);
                    self.err("L0113", s, format!("`{tn}` is not an iterator"), "Iterate over `&set` or `set` itself.");
                    ERROR
                }
            };
        }
        match self.kind(t) {
            _ if self.tys.is_chars_ty(self.resolve(t)) => CHAR,
            _ if crate::ty::iter::is_iter(&self.tys, self.resolve(t)) => {
                let r = self.deep(t);
                self.iter_item(r)
            }
            // `for x in &mut it` (or `it: &mut I`): core's `impl Iterator for
            // &mut I` steps `it` in place (lower.rs wraps the reference).
            TyKind::Ref(_, Mut::Mut, inner) if crate::ty::iter::is_iter(&self.tys, self.resolve(inner)) => {
                let i = self.deep(inner);
                self.iter_item(i)
            }
            TyKind::Ref(r, m, inner) => {
                // `&[T]`, `&[T; N]`, `&Vec<T>`, and `&Box<[T]>` (alloc's
                // `IntoIterator for &Box<[T]>`, and `&mut`, since 1.80).
                let elem = match self.kind(self.resolve(inner)) {
                    TyKind::Slice(elem) | TyKind::Array(elem, _) => Some(elem),
                    _ => {
                        let i = self.deep(inner);
                        self.tys.vec_elem(i).or_else(|| self.tys.boxed_slice_elem(i))
                    }
                };
                match elem {
                    Some(elem) => self.tys.intern(TyKind::Ref(r, m, elem)),
                    None if self.recv_elem(t).is_some() => self.recv_elem(t).unwrap_or(ERROR),
                    // A user `impl IntoIterator for &W` (or `&mut W`) (W-STD-B).
                    None => match self.for_trait_iter(for_e, iter, t) {
                        Some(item) => item,
                        None => {
                            let s = self.span(iter);
                            let tn = self.tn(t);
                            self.err("L0113", s, format!("cannot iterate over `{tn}`"), "Iterate over a range, `&vec`, or `&mut vec`.");
                            ERROR
                        }
                    },
                }
            }
            TyKind::Array(elem, _) => elem,
            _ if self.tys.vec_elem(self.resolve(t)).is_some() => self.tys.vec_elem(self.resolve(t)).unwrap_or(ERROR),
            // `for x in rx` and `for x in &rx` over an mpsc receiver
            // (W-THREADS): `recv` until every sender is gone.
            _ if self.recv_elem(t).is_some() => self.recv_elem(t).unwrap_or(ERROR),
            // A boxed slice by value (Rust 2024): its `vec::IntoIter`.
            _ if self.tys.boxed_slice_elem(self.resolve(t)).is_some() => self.tys.boxed_slice_elem(self.resolve(t)).unwrap_or(ERROR),
            TyKind::Error => ERROR,
            _ => match self.for_trait_iter(for_e, iter, t) {
                Some(item) => item,
                None => {
                    let s = self.span(iter);
                    let tn = self.tn(t);
                    self.err("L0113", s, format!("cannot iterate over `{tn}`"), "Iterate over a range, `&vec`, or `&mut vec`.");
                    ERROR
                }
            },
        }
    }

    /// A `for` loop through `IntoIterator` (section 2.4 in a
    /// loop head): select the impl, record the two method
    /// instances lowering calls, and answer the item type.
    fn for_trait_iter(&mut self, for_e: ExprId, iter: ExprId, t: Ty) -> Option<Ty> {
        let p = self.p;
        if !self.generic_mode() {
            return None;
        }
        self.run_obligations(false);
        let span = self.span(iter);
        // An `impl Iterator` value (a callee's opaque return): its bounds
        // prove `Iterator` for it, as for a method call on it.
        self.note_opaques(t);
        let args_id = self.tys.intern_args(&[GenericArg::Ty(t)]);
        let tr = TraitRef { def: p.gx.lang.into_iterator, args: args_id, bindings: EMPTY_BINDINGS };
        let lang = &p.gx.lang;
        // The into_iter call: an impl's method, the std blanket's
        // sentinel (no body: lowering uses the receiver as its own
        // iterator), or in a template check the bound's stub.
        let into_sel = self.select_obligation(tr);
        let into_from_env = matches!(into_sel, Selection::ParamEvidence(_));
        let into_local = match into_sel {
            Selection::Impl { id, args: impl_args, .. } => {
                let rec = p.gx.index.get(id);
                // core's synthetic collection impls (`Vec<T>`, `&[T]`)
                // keep their builtin loop; only the blanket over an
                // iterator uses the receiver as its own iterator.
                if rec.items.is_empty() && !matches!(p.tys.kind(rec.self_ty(&p.tys)), TyKind::Param(_)) {
                    return None;
                }
                if rec.items.is_empty() {
                    LocalDefId(u32::MAX)
                } else {
                    self.method_instance_for_impl(for_e, id, tr, impl_args, "into_iter", span)?.0
                }
            }
            Selection::ParamEvidence(_) => self.stub_instance(for_e, tr, p.interner.intern("into_iter"), span)?.0,
            _ => return None,
        };
        // The iterator type and item type, normalized.
        let into_iter_proj = self.tys.intern(TyKind::Projection(AssocId(lang.assoc_into_iter), args_id));
        let iter_ty = self.normalize_here(into_iter_proj);
        let iter_ty = self.deep(iter_ty);
        self.note_opaques(iter_ty);
        let item_proj = self.tys.intern(TyKind::Projection(AssocId(lang.assoc_into_item), args_id));
        let item_ty = self.normalize_here(item_proj);
        // next() on the iterator type.
        let iter_args_id = self.tys.intern_args(&[GenericArg::Ty(iter_ty)]);
        let tr2 = TraitRef { def: lang.iterator, args: iter_args_id, bindings: EMPTY_BINDINGS };
        // `&mut I` (core's `impl Iterator for &mut I`, synthetic): the loop
        // steps `*it` with `I`'s own `next` (lower.rs passes the reference
        // itself, not a borrow of it).
        let (tr2, iter_ty) = match (self.select_obligation(tr2), self.kind(iter_ty)) {
            (Selection::Impl { id, .. }, TyKind::Ref(_, Mut::Mut, inner)) if p.gx.index.get(id).items.is_empty() && !crate::ty::iter::is_iter(&self.tys, self.resolve(iter_ty)) => {
                let a = self.tys.intern_args(&[GenericArg::Ty(inner)]);
                (TraitRef { def: lang.iterator, args: a, bindings: EMPTY_BINDINGS }, inner)
            }
            _ => (tr2, iter_ty),
        };
        let next_local = match self.select_obligation(tr2) {
            // A builtin iterator (`type IntoIter = vec::IntoIter<T>`): its
            // `next` is the builtin call, marked by the sentinel id.
            Selection::Impl { id: id2, .. }
                if p.gx.index.get(id2).items.is_empty() && crate::ty::iter::is_iter(&self.tys, self.resolve(iter_ty)) =>
            {
                LocalDefId(u32::MAX)
            }
            Selection::Impl { id: id2, args: impl_args2, .. } => self.method_instance_for_impl(for_e, id2, tr2, impl_args2, "next", span)?.0,
            Selection::ParamEvidence(_) => self.stub_instance(for_e, tr2, p.interner.intern("next"), span)?.0,
            // A template bound `T: IntoIterator` proves into_iter from
            // the env, but no env predicate states `Iterator` for the
            // `IntoIter` projection (assoc-type bounds of a trait
            // definition are not elaborated into the env). The bound
            // still proves `next` exists, so the stub answers here;
            // instances re-select with concrete types.
            _ if into_from_env => self.stub_instance(for_e, tr2, p.interner.intern("next"), span)?.0,
            _ => return None,
        };
        self.set_res(for_e, Res::ForTrait { into_iter: into_local, next: next_local });
        Some(item_ty)
    }

    /// The method template of one selected impl by name,
    /// instantiated at the impl's args and recorded as an
    /// instance request at `site`. Trait defaults answer when
    /// the impl does not write the method.
    fn method_instance_for_impl(
        &mut self,
        site: ExprId,
        impl_id: crate::traits::ImplId,
        tr: TraitRef,
        impl_args: Vec<GenericArg>,
        name: &str,
        span: Span,
    ) -> Option<(LocalDefId, Vec<Ty>, Ty)> {
        let p = self.p;
        let record = p.gx.index.get(impl_id).clone();
        let local = record.items.iter().copied().find_map(|d| p.local_def(d.hash).filter(|&l| p.name(p.fn_info(l).name) == name)).or_else(
            || {
                // The trait default, materialized from its template
                // with the trait ref args as its prefix.
                let rec = p.gx.index.trait_record(record.trait_def)?;
                let name_sym = rec.methods.iter().find(|(_, n)| p.name(*n) == name).map(|(d, _)| *d)?;
                p.local_def(name_sym.hash)
            },
        )?;
        // rustc checks a call through a trait impl against the trait
        // item: its bounds hold even where the impl method states looser
        // ones (check/method.rs push_trait_item_bounds).
        let item_tmpl = record
            .items
            .contains(&p.def_id(local))
            .then(|| p.gx.index.trait_record(record.trait_def).and_then(|r| r.methods.iter().find(|(_, n)| p.name(*n) == name).map(|(d, _)| *d)))
            .flatten()
            .and_then(|d| p.gx.trait_methods.get(&d).cloned());
        let Some(Some(tmpl)) = p.gx.fn_templates.get(local.0 as usize).cloned() else {
            if let Some(t) = &item_tmpl {
                let tr_args: Vec<GenericArg> = self.tys.args(tr.args).to_vec();
                method::push_trait_item_bounds(self, t, &tr_args, &[], span);
            }
            let info = p.fn_info(local);
            return Some((local, info.params.clone(), p.ret_view(local)));
        };
        // Prefix: impl args for an impl method, trait ref args
        // for a trait default (its template generics are the
        // trait's). A default is the local whose def is a trait
        // method def, not an item of this impl.
        let is_default = !record.items.contains(&p.def_id(local));
        let prefix: Vec<GenericArg> = if is_default {
            let raw: Vec<GenericArg> = self.tys.args(tr.args).to_vec();
            raw.iter()
                .map(|&g| match g {
                    GenericArg::Ty(t) => GenericArg::Ty(self.deep(t)),
                    other => other,
                })
                .collect()
        } else {
            impl_args
        };
        let explicit: Vec<Option<GenericArg>> = prefix.iter().map(|&g| Some(g)).collect();
        let (mut params, ret, targs) = self.instantiate_template(site, local, &tmpl.generics.clone(), &explicit, span);
        if let Some(t) = &item_tmpl {
            let tr_args: Vec<GenericArg> = self.tys.args(tr.args).to_vec();
            method::push_trait_item_bounds(self, t, &tr_args, &targs[prefix.len().min(targs.len())..], span);
        }
        self.normalize_params(&mut params, span);
        Some((local, params, ret))
    }

    /// One format argument against its spec: the kind must exist for
    /// the type. Errors name the trait a kind needs (`LowerHex` and
    /// kin). Every flag applies to every type, as in Rust: the impl
    /// reads the ones it uses (`{:05}` on a str pads with spaces).
    fn check_fmt_arg(&mut self, t: Ty, spec: FmtSpec, span: Span) {
        // A projection reads through its normalization: `B::MIN` with
        // `const MIN: Self::Primitive` under `B: Bounds<Primitive = P>`
        // is a `P` (as in the deferred Debug loop).
        let t = self.normalize_here(t);
        let (_, base) = self.autoderef(t);
        let bk = self.kind(base);
        // Valid Rust lust has no rendering for yet: integer exponent
        // formats, and `env::Args` Debug (`Args { inner: [..] }`).
        let int_exp = matches!(spec.kind, FmtKind::LowerExp | FmtKind::UpperExp) && (matches!(bk, TyKind::Int(_)) || bk.is_int_infer());
        if int_exp || (spec.kind == FmtKind::Debug && self.tys.builtin_of(base) == Some(BuiltinTy::Iter(crate::ty::iter::IterKind::Args))) {
            let what = if int_exp { "an integer exponent format" } else { "Debug of `std::env::Args`" };
            self.errs.push(not_yet("L0641", span, what));
            return;
        }
        let what = match spec.kind {
            // A type with a user fmt impl in it proves the trait through
            // the obligation queue (check/fmt.rs `require_fmt`).
            FmtKind::Display => {
                if has_display(self.p, &self.tys, t) || self.kind(t).is_int_infer() || self.require_fmt(t, FmtKind::Display, span) {
                    None
                } else {
                    Some("Display")
                }
            }
            FmtKind::Debug => {
                // A range under plain references: its bounds' Debug
                // (lowering writes the parts, lower/range_fmt.rs).
                let dt = self.deep(t);
                let range = crate::check::fmt::range_fmt_kind(&self.tys, dt);
                if let Some((k, elem, _)) = range {
                    if k == crate::ty::iter::IterKind::RangeFull || has_debug(self.p, &self.tys, elem) {
                        None
                    } else {
                        Some("Debug")
                    }
                } else if has_debug(self.p, &self.tys, t) || self.require_fmt(t, FmtKind::Debug, span) {
                    None
                } else {
                    Some("Debug")
                }
            }
            FmtKind::LowerHex => {
                if matches!(bk, TyKind::Int(_)) || bk.is_int_infer() {
                    None
                } else {
                    Some("LowerHex")
                }
            }
            FmtKind::UpperHex => {
                if matches!(bk, TyKind::Int(_)) || bk.is_int_infer() {
                    None
                } else {
                    Some("UpperHex")
                }
            }
            FmtKind::Octal => {
                if matches!(bk, TyKind::Int(_)) || bk.is_int_infer() {
                    None
                } else {
                    Some("Octal")
                }
            }
            FmtKind::Binary => {
                if matches!(bk, TyKind::Int(_)) || bk.is_int_infer() {
                    None
                } else {
                    Some("Binary")
                }
            }
            FmtKind::LowerExp => {
                if matches!(bk, TyKind::Float(_)) || bk.is_float_infer() {
                    None
                } else {
                    Some("LowerExp")
                }
            }
            FmtKind::UpperExp => {
                if matches!(bk, TyKind::Float(_)) || bk.is_float_infer() {
                    None
                } else {
                    Some("UpperExp")
                }
            }
            // `Pointer` is on the pointer itself, never through a deref:
            // references, raw pointers, and fn pointers. A fat pointer
            // prints its metadata too, and the std smart pointers have it;
            // lust prints neither.
            FmtKind::Pointer => match self.kind(t) {
                TyKind::Ref(_, _, inner) | TyKind::RawPtr(_, inner)
                    if !matches!(self.kind(inner), TyKind::Dyn(..) | TyKind::Str | TyKind::Slice(_)) =>
                {
                    None
                }
                TyKind::FnPtr(_) => None,
                _ if self.tys.builtin_of(t).is_some() || matches!(self.kind(t), TyKind::Ref(..) | TyKind::RawPtr(..)) => {
                    self.errs.push(not_yet("L0641", span, "pointer format of this type"));
                    return;
                }
                _ => Some("Pointer"),
            },
        };
        if let Some(what) = what {
            if self.kind(t) != TyKind::Error && !self.tainted_lookup(t) {
                let tn = self.tn(t);
                let fix = match what {
                    "Debug" => "Add #[derive(Debug)] to the type.",
                    "Display" => "Use `{:?}` with #[derive(Debug)], or format the fields yourself.",
                    _ => "This format only applies to integer or float types, as written.",
                };
                self.err("L0112", span, format!("`{tn}` does not implement {what}"), fix);
            }
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn macro_expr(
        &mut self,
        e: ExprId,
        kind: MacroKind,
        args: &[ExprId],
        fmt: &[FmtPiece],
        repeat: bool,
        span: Span,
        expected: Option<Ty>,
    ) -> Ty {
        let fixed = match kind {
            MacroKind::Assert => 1,
            MacroKind::AssertEq | MacroKind::AssertNe => 2,
            MacroKind::Vec => args.len(),
            _ => 0,
        };
        let result = match kind {
            MacroKind::Vec => {
                let elem_expected = expected.and_then(|t| self.tys.vec_elem(self.resolve(t)));
                let elem = elem_expected.unwrap_or_else(|| self.new_var(false));
                if repeat {
                    self.expect_expr(args[0], elem);
                    self.expect_expr(args[1], USIZE);
                    let elem = self.deep(elem);
                    // An element type a later use fixes (`vec![Vec::new(); n]`,
                    // then a push) waits for body end, as rustc's `T: Clone`
                    // obligation does.
                    if self.tys.flags(elem).contains_infer() && !matches!(self.kind(elem), TyKind::Infer(_)) {
                        self.deferred_vec_clone.push((elem, span));
                    } else if !has_clone(self.p, &self.tys, elem) && !matches!(self.kind(elem), TyKind::Infer(_)) {
                        let tn = self.tn(elem);
                        self.err(
                            "L0112",
                            span,
                            format!("`vec![x; n]` needs Clone, but `{tn}` is not Clone"),
                            "Derive Clone on the element type.",
                        );
                    }
                    return self.tys.mk_vec(elem);
                }
                // `vec![a, b]` is an array literal moved into a Vec.
                let elem = self.array_elems(args, elem_expected);
                return self.tys.mk_vec(elem);
            }
            MacroKind::Assert => {
                if let Some(&c) = args.first() {
                    self.expect_expr(c, BOOL);
                }
                UNIT
            }
            MacroKind::AssertEq | MacroKind::AssertNe => {
                if args.len() < 2 {
                    self.err("L0105", span, "this macro takes 2 arguments", "Pass both values to compare.");
                } else {
                    let a = self.expr(args[0], None);
                    // `*left_val == *right_val` with the left type still a
                    // variable: rustc's `?T: PartialEq<R>` waits and never
                    // binds `?T` from the right side (E0283 unless a later
                    // use fixes it), so the check waits for body end.
                    let open = self.unbound_general(self.resolve(a));
                    let b = self.expr(args[1], if open { None } else { Some(a) });
                    let s = self.span(args[1]);
                    if open {
                        self.wait_asserts.push((e, a, b, span, s));
                    } else {
                        self.assert_eq_types(e, a, b, span, s);
                    }
                }
                UNIT
            }
            MacroKind::Println | MacroKind::Print | MacroKind::Eprintln | MacroKind::Eprint => UNIT,
            MacroKind::Format => STRING,
            MacroKind::FormatArgs => crate::ty::fmt::fmt_ty(&mut self.tys, crate::ty::fmt::FmtTy::Arguments),
            MacroKind::Panic | MacroKind::Todo | MacroKind::Unreachable => NEVER,
        };
        for piece in fmt {
            if let FmtPiece::Arg { index, spec, .. } = piece {
                // A width or precision argument is a `usize`.
                for c in [spec.width_arg, spec.precision_arg].into_iter().flatten() {
                    self.expect_expr(args[c as usize], USIZE);
                }
                let a = args[*index];
                let t = self.expr(a, None);
                let t = self.deep(t);
                // A still-unbound variable defers the test to
                // finish: its type may be a closure signature
                // that only the second inference pass binds. So
                // does one inside the type (`Vec<?T>` where a
                // pending `Iterator<Item = T>` bound binds `T`).
                let unbound = match self.kind(t) {
                    TyKind::Infer(_) => !self.kind(t).is_int_infer(),
                    _ => self.tys.flags(t).contains_infer(),
                };
                if unbound {
                    self.deferred_fmt.push((t, *spec, self.span(a)));
                    continue;
                }
                let s = self.span(a);
                // `format_args!` takes each argument by reference as a
                // sized `T` (rustc E0277 on `println!("{:?}", *v)`).
                self.require_sized(t, s);
                self.check_fmt_arg(t, *spec, s);
            }
        }
        // Arguments not referenced by the format string (only possible in assert macros).
        for (i, &a) in args.iter().enumerate() {
            let referenced = |p: &FmtPiece| match p {
                FmtPiece::Arg { index, spec, .. } => *index == i || [spec.width_arg, spec.precision_arg].contains(&Some(i as u32)),
                FmtPiece::Lit(_) => false,
            };
            if i >= fixed && !fmt.iter().any(referenced) {
                self.expr(a, None);
            }
        }
        // Format arguments are borrowed: a packed field may not be one.
        let borrowed_args: &[ExprId] = match kind {
            MacroKind::AssertEq | MacroKind::AssertNe => &args[..args.len().min(2)],
            MacroKind::Vec | MacroKind::Assert => &[],
            _ => args,
        };
        for &a in borrowed_args {
            self.check_packed_borrow(a, span);
        }
        result
    }

    // ---------- Patterns ----------

    /// Checks a pattern against a value of type `t`. Applies default binding modes.
    /// Records one pattern binding with the local type its mode gives it.
    fn bind_pattern_local(&mut self, pi: usize, name: Sym, mutable: bool, by_ref: bool, t: Ty, mode: BindMode, span: Span) {
        if self.prelude_variant(name, span.ctxt) {
            self.prelude_variant_binding_err(name, span);
        }
        // Edition 2024: once a pattern is implicitly borrowing (a default
        // binding mode shift happened above it), an explicit `ref` borrow
        // in it is an error.
        if by_ref && mode != BindMode::Move {
            self.err(
                "L0122",
                span,
                "cannot explicitly borrow within an implicitly-borrowing pattern",
                "Remove `ref`: the binding already borrows by default. To borrow explicitly, dereference with `&` at the top of the pattern first.",
            );
        }
        let mode = if by_ref { BindMode::Ref(mutable) } else { mode };
        let lty = match mode {
            BindMode::Move => t,
            BindMode::Ref(m) => self.tys.mk_ref(m, t),
        };
        let mutable_local = mutable && !by_ref;
        if mutable_local && mode != BindMode::Move {
            self.err(
                "L0122",
                span,
                "`mut` binding under a reference is not allowed here",
                "Remove `mut`, or match on the value instead of a reference.",
            );
        }
        // Inside a non-first or-pattern alternative, a binding the
        // first alternative already made reuses that local: every
        // alternative binds the same names to the same checker
        // locals, with the same type and binding mode (rustc
        // E0408 and E0409). The frames nest like the patterns do.
        let key = (name, span.ctxt);
        let mut hit: Option<(usize, usize)> = None;
        for (fi, frame) in self.or_frames.iter().enumerate().rev() {
            if let Some(bi) = frame.expected.iter().position(|b| (b.name, b.ctxt) == key) {
                hit = Some((fi, bi));
                break;
            }
        }
        if let Some((fi, bi)) = hit {
            let exp = self.or_frames[fi].expected[bi].clone();
            if fi + 1 != self.or_frames.len() {
                // Found only in an outer alternative: this one
                // binds a name its own first alternative did not.
                self.or_frames.last_mut().unwrap().extra.push((name, span));
            } else if self.or_frames[fi].seen[bi] {
                self.err(
                    "L0106",
                    span,
                    format!("`{}` is bound more than once in the same pattern", self.name(name)),
                    "Rename one of the bindings.",
                );
            }
            self.or_frames[fi].seen[bi] = true;
            if mode != exp.mode || mutable_local != exp.mutable {
                self.err(
                    "L0110",
                    span,
                    format!("variable `{}` is bound inconsistently across `|` alternatives", self.name(name)),
                    "Bind it the same way in every alternative (same `ref` and `mut`).",
                );
            }
            if !self.unify(lty, exp.ty) {
                self.mismatch(span, exp.ty, lty);
            }
            self.scopes.push((key, exp.local));
            self.out.pat_res[pi] = PatRes::Binding { local: exp.local, mode };
            if let Some(log) = &mut self.or_log {
                log.push(OrBind { name, ctxt: span.ctxt, local: exp.local, mode, ty: lty, mutable: mutable_local });
            }
            return;
        }
        if !self.or_frames.is_empty() {
            // A name the first alternative never bound: the
            // alternative is rejected when it ends, but checking
            // continues with a fresh local so the body still
            // resolves names.
            self.or_frames.last_mut().unwrap().extra.push((name, span));
        } else if let Some(&mark) = self.pat_marks.last()
            && self.scopes[mark..].iter().any(|&(k, _)| k == key)
        {
            // One pattern may not bind a name twice (rustc
            // E0416): bindings an enclosing or-pattern restored
            // into scope count too.
            self.err(
                "L0106",
                span,
                format!("`{}` is bound more than once in the same pattern", self.name(name)),
                "Rename one of the bindings.",
            );
        }
        let l = self.add_local(name, lty, mutable_local, span);
        self.out.pat_res[pi] = PatRes::Binding { local: l, mode };
        if let Some(log) = &mut self.or_log {
            log.push(OrBind { name, ctxt: span.ctxt, local: l, mode, ty: lty, mutable: mutable_local });
        }
    }

    /// Checks a const pattern's value against the scrutinee type, as
    /// rustc's const-to-pattern does: no NaN anywhere, the const's type
    /// implements `PartialEq`, and every Adt the value reaches derives
    /// it (structural match; L0633 otherwise). Then type equality and
    /// refutability outside `match`. Returns how the pattern resolves:
    /// a comparison with the value (scalar or structural), a unit
    /// variant, or `None` (the error is already reported).
    fn check_const_value(
        &mut self,
        cty: Ty,
        val: &crate::ty::consteval::ConstValue,
        t: Ty,
        span: Span,
        in_match: bool,
    ) -> Option<ConstPat> {
        use crate::ty::consteval::ConstValue as CV;
        let ct = self.resolve(cty);
        // rustc rejects a NaN anywhere in a const pattern's value,
        // before the structural rules below.
        if const_value_has_nan(val) {
            self.err("L0110", span, "cannot use NaN in patterns", "Use a guard to test for NaN.");
            return None;
        }
        if matches!(val, CV::StrBytes(_)) {
            self.err(
                "L0630",
                span,
                "a const string made by `split_at` in a pattern is not supported yet",
                "Match on a string literal, or compare in a guard.",
            );
            return None;
        }
        let scalar = matches!(val, CV::Int(_) | CV::Bool(_) | CV::Char(_) | CV::Float(..) | CV::Str(_));
        if !scalar {
            let ct = self.deep(ct);
            self.record_glue_reads(self.p.gx.lang.partial_eq, ct);
            if !has_eq(self.p, &self.tys, ct) {
                self.non_structural_const(ct, span);
                return None;
            }
            self.const_structural(ct, val, span, 0)?;
        }
        let out = match val {
            _ if scalar => ConstPat::Value,
            CV::Variant(0, fields) if fields.is_empty() && self.tys.option_elem(ct).is_some() => ConstPat::OptNone,
            CV::Variant(v, fields) if fields.is_empty() => match self.tys.local_adt(ct).filter(|&a| {
                self.p.adt(a).is_enum && self.p.adt(a).variants.get(*v as usize).is_some_and(|var| var.shape == VariantShape::Unit)
            }) {
                Some(a) => {
                    // A generic enum instance scrutinee names its own
                    // Adt; the const's type may name the template.
                    let dt = self.deep(t);
                    let a = match self.tys.local_adt(dt) {
                        Some(inst) if inst != a && self.p.def_of_adt(inst) == self.p.def_of_adt(a) => inst,
                        _ => a,
                    };
                    ConstPat::Variant(a, *v)
                }
                None => ConstPat::Value,
            },
            _ => ConstPat::Value,
        };
        if !self.unify(ct, t) {
            self.mismatch(span, t, ct);
            return None;
        }
        if !in_match {
            self.errs.push(unsupported(span, "refutable patterns here"));
        }
        Some(out)
    }

    /// Undoes the match-ergonomics peeling `pattern_mode` did for a
    /// pattern that turned out to be a const: a const pattern matches
    /// the scrutinee type as it is.
    fn unpeel_const_pat(&mut self, pi: usize, scrut_t: Ty) {
        self.out.pat_derefs[pi] = 0;
        self.out.pat_ty[pi] = scrut_t;
    }

    /// L0633: a const pattern value of type `t`, which is not
    /// structural-match (no derived `PartialEq`).
    fn non_structural_const(&mut self, t: Ty, span: Span) {
        let tn = self.tn(t);
        self.err(
            "L0633",
            span,
            format!("constant of non-structural type `{tn}` cannot be used in a pattern"),
            "Derive `PartialEq` on the type, match a field, or compare in a guard instead.",
        );
    }

    /// Walks a const pattern value at type `t` as rustc's
    /// const-to-pattern does: each Adt the value reaches must derive
    /// `PartialEq` (an Adt in a variant the value does not take is not
    /// checked), and fn pointers are rejected. Values lowering cannot
    /// compare field by field (statics, builtin aggregates) are the
    /// non-scalar unsupported error. `None` when an error was reported.
    fn const_structural(&mut self, t: Ty, val: &crate::ty::consteval::ConstValue, span: Span, depth: u32) -> Option<()> {
        use crate::ty::consteval::ConstValue as CV;
        let t = self.deep(t);
        let p = self.p;
        let fail = |this: &mut Self| {
            this.errs.push(unsupported(span, "non-scalar const patterns"));
            None
        };
        if depth > 64 {
            return fail(self);
        }
        let kind = self.kind(t);
        match (kind, val) {
            (TyKind::Int(_), CV::Int(_))
            | (TyKind::Bool, CV::Bool(_))
            | (TyKind::Char, CV::Char(_))
            | (TyKind::Float(_), CV::Float(..))
            | (TyKind::Unit, CV::Unit | CV::Aggregate(_))
            | (TyKind::Tuple(_), CV::Unit) => Some(()),
            (TyKind::Ref(_, Mut::Shared, inner), CV::Str(_)) if self.kind(inner) == TyKind::Str => Some(()),
            (TyKind::Tuple(ts), CV::Aggregate(vals)) => {
                let ts = self.tys.tys_of(ts).to_vec();
                if ts.len() != vals.len() {
                    return fail(self);
                }
                for (ft, v) in ts.into_iter().zip(vals) {
                    self.const_structural(ft, v, span, depth + 1)?;
                }
                Some(())
            }
            (TyKind::Array(el, _) | TyKind::Slice(el), CV::Aggregate(vals)) => {
                for v in vals {
                    self.const_structural(el, v, span, depth + 1)?;
                }
                Some(())
            }
            (TyKind::Array(el, _) | TyKind::Slice(el), CV::Repeat(v, _)) => self.const_structural(el, v, span, depth + 1),
            (TyKind::Array(el, _) | TyKind::Slice(el), CV::Bytes(_)) if self.kind(el) == TyKind::Int(IntTy::U8) => Some(()),
            (TyKind::Ref(_, Mut::Shared, inner), CV::Ref(v)) => self.const_structural(inner, v, span, depth + 1),
            // A slice reference holds its backing array in place.
            (TyKind::Ref(_, Mut::Shared, inner), CV::Aggregate(_) | CV::Repeat(..) | CV::Bytes(_))
                if matches!(self.kind(inner), TyKind::Slice(_)) =>
            {
                self.const_structural(inner, val, span, depth + 1)
            }
            (TyKind::FnPtr(..), _) => {
                self.err(
                    "L0633",
                    span,
                    "function pointers in patterns behave unpredictably and cannot be used",
                    "Compare the pointers in a guard instead.",
                );
                None
            }
            (_, CV::Variant(v, vals)) if self.tys.option_elem(t).is_some() => match (v, vals.as_slice()) {
                (0, []) => Some(()),
                (1, [x]) => {
                    let el = self.tys.option_elem(t).unwrap_or(ERROR);
                    self.const_structural(el, x, span, depth + 1)
                }
                _ => fail(self),
            },
            (_, CV::Variant(v, vals)) if self.tys.result_args(t).is_some() => {
                let (ok, err) = self.tys.result_args(t).unwrap_or((ERROR, ERROR));
                match (v, vals.as_slice()) {
                    (0, [x]) => self.const_structural(ok, x, span, depth + 1),
                    (1, [x]) => self.const_structural(err, x, span, depth + 1),
                    _ => fail(self),
                }
            }
            (_, CV::Aggregate(_) | CV::Variant(..)) if self.tys.local_adt(t).is_some() => {
                let a = self.tys.local_adt(t).unwrap_or(AdtId(0));
                if !p.derive_has(a, crate::check::derive_delta::bit::PARTIAL_EQ) {
                    self.non_structural_const(t, span);
                    return None;
                }
                let (v, vals) = match val {
                    CV::Aggregate(vals) | CV::Variant(0, vals) if !p.adt(a).is_enum => (0, vals),
                    CV::Variant(v, vals) if p.adt(a).is_enum => (*v, vals),
                    _ => return fail(self),
                };
                let Some(variant) = p.adt(a).variants.get(v as usize) else { return fail(self) };
                if variant.fields.len() != vals.len() {
                    return fail(self);
                }
                // A template Adt's field types take the type's args.
                let args: Vec<GenericArg> = match self.tys.adt_parts(t) {
                    Some((d, aa)) if d == p.def_of_adt(a) => self.tys.args(aa).to_vec(),
                    _ => Vec::new(),
                };
                for (f, x) in variant.fields.iter().zip(vals) {
                    let ft = if args.is_empty() { f.ty } else { self.subst_norm(f.ty, &args, span) };
                    self.const_structural(ft, x, span, depth + 1)?;
                }
                Some(())
            }
            _ if kind == TyKind::Error => None,
            _ if self.tys.builtin_of(t).is_some() => {
                // `Vec`, `String`, `Box`, the locks: their `PartialEq`
                // is written by hand, as in std.
                self.non_structural_const(t, span);
                None
            }
            _ => fail(self),
        }
    }

    /// A free const item used as a pattern, by const index.
    fn const_item_pat(&mut self, pi: usize, idx: u32, t: Ty, span: Span, in_match: bool) {
        // The pattern consumes the const's value: record its `Sig`
        // read so a value edit rechecks this body (ARCH 8.2).
        if let Some(&def) = self.p.const_defs.get(idx as usize) {
            let p = self.p;
            let _ = p.sig_of(&mut self.out.reads, def);
        }
        let c = &self.p.consts[idx as usize];
        let (ct, val) = (c.ty, c.value.clone());
        match self.check_const_value(ct, &val, t, span, in_match) {
            Some(ConstPat::Value) => self.out.pat_res[pi] = PatRes::ConstItem(idx),
            Some(ConstPat::Variant(a, v)) => self.out.pat_res[pi] = PatRes::Variant(a, v),
            Some(ConstPat::OptNone) => self.out.pat_res[pi] = PatRes::Opt(false),
            None => {}
        }
    }

    /// Tries to read a path pattern as a const pattern. Returns true
    /// when the path named a const (or a static, which errors), so
    /// the caller skips variant handling.
    fn try_const_path_pat(&mut self, pi: usize, segs: &[ast::PathSeg], t: Ty, span: Span, in_match: bool) -> bool {
        let p = self.p;
        if segs.len() == 1 {
            // Free consts and statics in one segment are handled by
            // the pattern-identifier resolution in the Path arm.
            return false;
        }
        // Primitive associated consts (`i64::MAX`, `u32::BITS`), the
        // same table `path_expr` reads for expression positions.
        if segs.len() == 2
            && let Some(it) = p.known.int_ty(segs[0].name)
        {
            let item = self.name(segs[1].name).to_string();
            let item = item.as_str();
            let bits = it.bits();
            let v = match item {
                "MAX" => Some(crate::ty::consteval::truncate_to_int(it.max128() as i128, it)),
                "MIN" => Some(if it.signed() { if bits >= 128 { i128::MIN } else { -(1i128 << (bits - 1)) } } else { 0 }),
                "BITS" => Some(bits as i128),
                _ => None,
            };
            if let Some(v) = v {
                let (ct, val) = if item == "BITS" {
                    (int(IntTy::U32), v)
                } else if it == IntTy::U128 && item == "MAX" {
                    (int(it), -1)
                } else {
                    (int(it), v)
                };
                let cv = crate::ty::consteval::ConstValue::Int(val);
                if self.check_const_value(ct, &cv, t, span, in_match).is_some() {
                    self.out.pat_res[pi] = PatRes::PrimConst(val);
                }
                return true;
            }
        }
        // Primitive float associated consts (`f64::INFINITY`,
        // `std::f64::consts::PI`): the same table the const
        // evaluator reads. A NaN value rejects in
        // `check_const_value`, as rustc rejects it.
        if let Some((cv, ct)) = self.primitive_float_const_pattern(segs) {
            if self.check_const_value(ct, &cv, t, span, in_match).is_some() {
                self.out.pat_const[pi] = Some(cv);
            }
            return true;
        }
        if let Some((adt, item)) = self.assoc_const_key(segs)
            && let Some(picked) = self.assoc_const_base(segs, Some(span)).and_then(|base| self.inherent_assoc_pick(adt, item, base, Some(span)))
        {
            if let Some((idx, _)) = picked {
                if self.p.gx.assoc_const_tmpls.contains_key(&idx) {
                    self.err("L0630", span, "a generic associated const in a pattern is outside the bounded const evaluator", "Bind the value first and compare in a guard.");
                    return true;
                }
                self.check_assoc_vis(adt, item, "associated constant", span);
                self.const_item_pat(pi, idx, t, span, in_match);
            }
            return true;
        }
        // A trait associated const pattern on a concrete type
        // (`S::C`): only a confirmed impl gives the value a
        // pattern needs. An abstract read (`U::K`, `Self::K` in
        // a generic context) depends on a generic parameter:
        // rustc rejects it (E0158), so it must not fall through
        // to variant handling.
        if segs.len() == 2
            && !self.assoc_const_key(segs).is_some_and(|(adt, item)| self.inherent_value_blocks(adt, item))
            && let Some(base) = self.assoc_const_base(segs, Some(span))
            && let Some(found) = self.trait_assoc_const(None, base, None, segs[1].name, span)
        {
            match found {
                (Some((idx, _)), _) if self.p.gx.assoc_const_tmpls.contains_key(&idx) => {
                    self.err("L0630", span, "a generic associated const in a pattern is outside the bounded const evaluator", "Bind the value first and compare in a guard.");
                }
                (Some((idx, _)), _) => self.const_item_pat(pi, idx, t, span, in_match),
                (None, ty) if self.kind(ty) != TyKind::Error => {
                    self.err(
                        "L0110",
                        span,
                        "constant pattern cannot depend on generic parameters",
                        "Compare with the constant in a guard instead.",
                    );
                }
                (None, _) => {}
            }
            return true;
        }
        false
    }

    /// A qualified path in pattern position: `<Type>::CONST`,
    /// `<Type as Trait>::CONST`, or a unit variant (`<E>::A`).
    /// The value side is `qpath_value`; a pattern needs a
    /// concrete value, so an abstract (generic-dependent) assoc
    /// const is an error here, as rustc's E0158.
    fn qpath_pat(
        &mut self,
        pi: usize,
        self_ty: ast::TyId,
        trait_path: &[ast::PathSeg],
        segs: &[ast::PathSeg],
        t: Ty,
        span: Span,
        in_match: bool,
    ) {
        if segs.len() != 1 {
            self.err("L0101", span, "cannot find the associated item", "Check the qualified path and the name.");
            return;
        }
        let name = segs[0].name;
        let base = self.resolve_written(self_ty);
        if self.kind(base) == TyKind::Error {
            return;
        }
        let hint = if trait_path.is_empty() {
            None
        } else {
            let tref = ast::TraitRefExpr { path: trait_path.to_vec() };
            match self.written_trait_ref(base, &tref, span) {
                Ok(tr) => Some(tr),
                Err(d) => {
                    self.errs.push(d);
                    return;
                }
            }
        };
        if hint.is_none() {
            if let Some((cv, ct)) = self.primitive_const_for_base(base, name) {
                if self.check_const_value(ct, &cv, t, span, in_match).is_some() {
                    self.out.pat_const[pi] = Some(cv);
                }
                return;
            }
            if let Some(adt) = self.tys.local_adt(self.resolve(base)) {
                // A unit variant through a qualified path is a
                // variant pattern, not a const comparison.
                if self.p.adt(adt).is_enum
                    && let Some(v) = self.p.adt(adt).variants.iter().position(|var| var.name == name)
                {
                    let v = v as u32;
                    let dt = self.deep(t);
                    let (a, adt_ty) = match self.tys.local_adt(dt) {
                        Some(inst) if inst != adt && self.p.def_of_adt(inst) == self.p.def_of_adt(adt) => (inst, dt),
                        _ => (adt, self.tys.adt_ty(adt)),
                    };
                    if !self.unify(adt_ty, t) {
                        self.mismatch(span, t, adt_ty);
                        return;
                    }
                    if self.p.adt(a).variants[v as usize].shape != VariantShape::Unit {
                        self.err("L0110", span, "this variant has fields", "Match its fields with `(..)` or `{ .. }`.");
                        return;
                    }
                    if self.hidden_variant(a, v, span) {
                        return;
                    }
                    self.check_ne_ctor(a, v, span);
                    self.out.pat_res[pi] = PatRes::Variant(a, v);
                    return;
                }
                if let Some(picked) = self.inherent_assoc_pick(adt, name, base, Some(span)) {
                    if let Some((idx, _)) = picked {
                        if self.p.gx.assoc_const_tmpls.contains_key(&idx) {
                            self.err("L0630", span, "a generic associated const in a pattern is outside the bounded const evaluator", "Bind the value first and compare in a guard.");
                            return;
                        }
                        self.check_assoc_vis(adt, name, "associated constant", span);
                        self.const_item_pat(pi, idx, t, span, in_match);
                    }
                    return;
                }
                if self.inherent_value_blocks(adt, name) {
                    self.err(
                        "L0110",
                        span,
                        "expected a const or a unit variant in this pattern",
                        "Use an associated const, or compare in a guard.",
                    );
                    return;
                }
            }
        }
        match self.trait_assoc_const(None, base, hint, name, span) {
            Some((Some((idx, _)), _)) if self.p.gx.assoc_const_tmpls.contains_key(&idx) => {
                self.err("L0630", span, "a generic associated const in a pattern is outside the bounded const evaluator", "Bind the value first and compare in a guard.");
            }
            Some((Some((idx, _)), _)) => self.const_item_pat(pi, idx, t, span, in_match),
            Some((None, ty)) if self.kind(ty) != TyKind::Error => {
                self.err(
                    "L0110",
                    span,
                    "constant pattern cannot depend on generic parameters",
                    "Compare with the constant in a guard instead.",
                );
            }
            Some((None, _)) => {}
            None => {
                self.err(
                    "L0104",
                    span,
                    format!("no associated const named `{}` here", self.name(name)),
                    "Check the spelling against the impl or trait definition.",
                );
            }
        }
    }

    /// A qualified path in value position: `<Type>::CONST` or
    /// `<Type as Trait>::CONST`. Calls through a qualified path
    /// resolve in the call arm instead. A named trait reads only
    /// that trait's item; with no trait, inherent items win, as
    /// on a plain path.
    fn qpath_value(&mut self, e: ExprId, self_ty: ast::TyId, trait_path: &[ast::PathSeg], segs: &[ast::PathSeg], span: Span) -> Ty {
        let p = self.p;
        if segs.len() != 1 {
            self.err("L0101", span, "cannot find the associated item", "Check the qualified path and the name.");
            return ERROR;
        }
        let name = segs[0].name;
        // `<u64>::MAX` is `u64::MAX`.
        if trait_path.is_empty()
            && let ast::TyExpr::Path(ty_segs) = p.ast.ty(self_ty)
            && let [ty_seg] = ty_segs.as_slice()
            && matches!(ty_seg.args, ast::GenericArgs::None)
            && self.prim_ty_by_name(ty_seg.name).is_some()
        {
            return self.path_expr(e, &[ty_seg.clone(), segs[0].clone()], span);
        }
        let base = self.resolve_written(self_ty);
        let hint = if trait_path.is_empty() {
            None
        } else {
            // `_` args become body variables, as in a qualified call.
            let tref = ast::TraitRefExpr { path: trait_path.to_vec() };
            match self.written_trait_ref(base, &tref, span) {
                Ok(tr) => Some(tr),
                Err(d) => {
                    self.errs.push(d);
                    return ERROR;
                }
            }
        };
        if hint.is_none()
            && let Some(adt) = self.tys.local_adt(self.resolve(base))
            && let Some(picked) = self.inherent_assoc_pick(adt, name, base, Some(span))
        {
            return match picked {
                Some((idx, v)) => {
                    // As on a plain `Type::C` path: the value is baked in
                    // (record its `Sig` read) and visibility applies.
                    if let Some(&def) = p.const_defs.get(idx as usize) {
                        let _ = p.sig_of(&mut self.out.reads, def);
                    }
                    self.check_assoc_vis(adt, name, "associated constant", span);
                    let t = p.consts[idx as usize].ty;
                    let i = self.ei(e);
                    self.out.const_exprs[i] = Some(v);
                    self.out.const_quals.insert(e, p.consts[idx as usize].qualif);
                    self.deep(t)
                }
                None => ERROR,
            };
        }
        let blocked = hint.is_none()
            && self.replay_pick(e).is_none()
            && self.tys.local_adt(self.resolve(base)).is_some_and(|adt| self.inherent_value_blocks(adt, name));
        if !blocked && let Some((idx, t)) = self.trait_assoc_const(Some(e), base, hint, name, span) {
            if let Some((_, v)) = idx {
                let i = self.ei(e);
                self.out.const_exprs[i] = Some(v);
            }
            return t;
        }
        // A slice's builtin method as a value (`<[Node]>::len`): the
        // primitive item value, as `str::len` is.
        if hint.is_none()
            && let base_r = self.resolve(base)
            && matches!(self.kind(base_r), TyKind::Slice(_))
            && let Some((b, ..)) = self.prim_assoc_sig(base_r, name, &[])
        {
            self.set_res(e, Res::PrimAssoc { b, self_ty: base_r, name });
            return self.prim_item_value(b, base_r, name, span);
        }
        // An inherent associated function as a value
        // (`<S>::mk`), resolved as the plain two-segment path
        // is. A trait's function as a value through a qualified
        // path is not resolved yet.
        // A longer type path (`m::S`, or `std::rc::Rc` from a `use`) that
        // does not resolve this way falls through to the trait items.
        if hint.is_none()
            && let ast::TyExpr::Path(ty_segs) = p.ast.ty(self_ty)
        {
            let mut segs2 = ty_segs.clone();
            segs2.push(segs[0].clone());
            let mark = self.errs.len();
            let resolved = self.resolve_assoc(&segs2, span);
            if resolved.is_none() && segs2.len() > 2 {
                self.errs.truncate(mark);
            } else if let Some(r) = resolved {
                // Function items only: variant construction
                // through a qualified path has no lowering yet,
                // so it rejects with the error below instead.
                if let Res::Fn(f) = r {
                    self.set_res(e, r);
                    return self.inherent_qpath_fn_value(e, f, base, span);
                }
                // A primitive's builtin method (`<str>::len`) or a builtin
                // item (`<Box<u8>>::new`), as on the plain path.
                if let Res::PrimAssoc { b, self_ty, name } = r {
                    self.set_res(e, r);
                    return self.prim_item_value(b, self_ty, name, span);
                }
                if matches!(r, Res::Builtin(Builtin::BoxNew | Builtin::RcNew | Builtin::StringFrom | Builtin::StringAsStr)) {
                    return self.builtin_item_value(e, r, &segs2, span);
                }
            } else {
                return ERROR;
            }
        }
        // A trait's function as a value: `<S as Tr>::mk`, also a
        // generic impl's fn or a trait default body, instantiated at
        // the selected impl's (or trait ref's) args.
        if let Some(found) = self.trait_fn_value(self.resolve(base), hint, name, true, span) {
            let Some((f, prefix)) = found else { return ERROR };
            self.set_res(e, Res::Fn(f));
            return self.fn_value_ty_prefixed(e, f, &prefix, span);
        }
        // No impl fn selects now (`<T as Sh>::mk` on a type parameter,
        // `<i32 as Clone>::clone`): the trait ref's deferred value, as
        // for `T::f`.
        if let Some(tr) = hint.or_else(|| self.unique_item_trait(base, name))
            && let Some(t) = self.trait_ref_fn_value(e, tr, name, span)
        {
            return t;
        }
        self.err(
            "L0104",
            span,
            format!("no associated const named `{}` here", self.name(name)),
            "Check the spelling against the impl or trait definition.",
        );
        ERROR
    }

    /// True when an inherent associated function or enum variant
    /// of this name shadows any trait associated const on an Adt
    /// (inherent items win in rustc's path resolution).
    fn inherent_value_blocks(&mut self, adt: AdtId, item: Sym) -> bool {
        let p = self.p;
        let template = p.defs.def_of_adt(adt).and_then(|d| p.defs.local_adt(d)).unwrap_or(adt);
        p.inherent_reads(&mut self.out.reads, p.def_of_adt(template), item);
        p.methods.contains_key(&(template, item)) || (p.adt(adt).is_enum && p.adt(adt).variants.iter().any(|v| v.name == item))
    }

    /// The value of associated const `idx` at one instance: its
    /// evaluated `consts` value, or a fresh per-instance
    /// evaluation when the const is generic
    /// (`gx.assoc_const_tmpls`). None when the instance is still
    /// abstract (a template check, or an argument inference has
    /// not named): the caller treats the read as param evidence.
    fn assoc_const_value(
        &mut self,
        idx: u32,
        generics: &Generics,
        args: Vec<GenericArg>,
        self_ty: Ty,
        trait_def: Option<crate::def::DefId>,
    ) -> Option<crate::ty::consteval::ConstValue> {
        let p = self.p;
        if !p.gx.assoc_const_tmpls.contains_key(&idx) {
            return Some(p.consts[idx as usize].value.clone());
        }
        let args: Vec<GenericArg> = args
            .into_iter()
            .map(|g| match g {
                GenericArg::Ty(t) => GenericArg::Ty(self.deep(t)),
                GenericArg::Const(c) => GenericArg::Const(self.resolve_const(c)),
                other => other,
            })
            .collect();
        let abstract_ = self.is_template_check()
            || args.iter().any(|g| match g {
                GenericArg::Ty(t) => self.has_unbound_var(*t) || self.tys.flags(*t).contains_param(),
                GenericArg::Const(c) => matches!(self.tys.const_kind(*c), ConstKind::Param(_) | ConstKind::Infer(_)),
                GenericArg::Lifetime(_) => false,
            });
        if abstract_ {
            return None;
        }
        let env = assoc_eval::AssocEnv { generics: generics.clone(), args, self_ty: self.deep(self_ty), trait_def };
        match assoc_eval::eval_assoc_const(p, &mut self.tys, idx, env) {
            Ok((v, _)) => Some(v),
            Err(d) => {
                self.errs.push(d);
                None
            }
        }
    }

    /// Resolves a trait associated const read (`Type::C`, `T::C`,
    /// `Self::C`, `<T as Tr>::C`) on self type `base`, like
    /// `assoc_call` resolves a trait method call: a written trait
    /// (`hint`), else the template pick, else the bounds on a
    /// type parameter, else every trait in scope that declares a
    /// const of this name. Returns the const's type and, when an
    /// impl is confirmed, its evaluated value as an index into
    /// `Program::consts` (the impl's own, else the trait
    /// default). Param evidence gives only the type; the
    /// instance check replays the pick for the value.
    fn trait_assoc_const(
        &mut self,
        pick_e: Option<ExprId>,
        base: Ty,
        hint: Option<TraitRef>,
        name: Sym,
        span: Span,
    ) -> Option<(Option<(u32, crate::ty::consteval::ConstValue)>, Ty)> {
        let p = self.p;
        if hint.is_none() && pick_e.and_then(|e| self.replay_pick(e)).is_none() && self.std_shadow_path(base, name, true, span) {
            return Some((None, ERROR));
        }
        // Every user trait that declares an associated const `name`.
        let mut by_name: Vec<DefId> = Vec::new();
        for &assoc in p.gx.trait_assoc_consts.keys() {
            let Some(t) = p.gx.index.trait_of_assoc(assoc) else { continue };
            let Some(rec) = p.gx.index.trait_record(t) else { continue };
            if rec.assoc_items.iter().any(|&(d, n, _)| d == assoc && n == name) && !by_name.contains(&t) {
                by_name.push(t);
            }
        }
        if by_name.is_empty() {
            return None;
        }
        let base_r = self.resolve(base);
        let bound: Vec<DefId> = if hint.is_none() && matches!(self.tys.kind(base_r), TyKind::Param(_) | TyKind::Projection(..)) {
            by_name
                .iter()
                .copied()
                .filter(|&t| {
                    self.env().iter().any(|pred| {
                        matches!(pred, Predicate::Trait(b) if b.count == 0 && b.value.def == t
                            && self.tys.args(b.value.args).first().and_then(|g| g.as_ty()) == Some(base_r))
                    })
                })
                .collect()
        } else {
            Vec::new()
        };
        // A projection's bounds do not bring their traits in scope (only a
        // param's do, as rustc's inherent candidates).
        let bound: Vec<DefId> = if matches!(self.tys.kind(base_r), TyKind::Projection(..)) {
            bound.into_iter().filter(|&t| method::trait_in_scope_pub(self, t)).collect()
        } else {
            bound
        };
        let traits: Vec<DefId> = match (hint, pick_e.and_then(|e| self.replay_pick(e))) {
            (Some(tr), _) => vec![tr.def],
            (None, Some(pick)) => vec![pick.trait_def],
            (None, None) if !bound.is_empty() => bound,
            (None, None) => by_name.into_iter().filter(|&d| method::trait_in_scope_at(self, d, base)).collect(),
        };
        let mut hits: Vec<(Option<(u32, crate::ty::consteval::ConstValue)>, Ty)> = Vec::new();
        let mut hit_traits: Vec<DefId> = Vec::new();
        for trait_def in traits {
            let Some(rec) = p.gx.index.trait_record(trait_def).cloned() else { continue };
            let Some(assoc) = rec.assoc_by_name(name).filter(|a| p.gx.trait_assoc_consts.contains_key(a)) else { continue };
            let snap = self.snapshot_vars();
            let obl_len = self.obl_len();
            let sites_len = self.generic_sites.len();
            let tr = match hint {
                Some(written) if written.def == trait_def => written,
                _ => {
                    let n_inputs = rec.generics.params.len().saturating_sub(1);
                    let mut tr_args: Vec<GenericArg> = vec![GenericArg::Ty(base)];
                    for _ in 0..n_inputs {
                        tr_args.push(GenericArg::Ty(self.new_var(false)));
                    }
                    let args_id = self.tys.intern_args(&tr_args);
                    TraitRef { def: trait_def, args: args_id, bindings: EMPTY_BINDINGS }
                }
            };
            let sel = self.select_obligation_at(tr, span, 0);
            let hit = match sel {
                // An impl parameter the header could not bind means
                // the Self type is not known here (a fresh variable
                // from a missing turbofish): rustc asks for the
                // annotation, so this is no hit.
                Selection::Impl { id, ref unbound, ref args, .. } if unbound.is_empty() => {
                    let impl_def = p.gx.index.get(id).def;
                    let impl_args = args.clone();
                    let picked = p
                        .impl_assoc_consts
                        .get(&(impl_def, assoc))
                        .copied()
                        .map(|idx| (idx, p.gx.index.get(id).generics.clone(), impl_args))
                        .or_else(|| {
                            p.trait_assoc_const_values
                                .get(&assoc)
                                .copied()
                                .map(|idx| (idx, rec.generics.clone(), self.tys.args(tr.args).to_vec()))
                        });
                    picked.map(|(idx, gens, args)| {
                        let ty = subst(&mut self.tys, p.consts[idx as usize].ty, &args);
                        let ty = self.deep(ty);
                        match self.assoc_const_value(idx, &gens, args, base, Some(trait_def)) {
                            Some(v) => (Some((idx, v)), ty),
                            None => (None, ty),
                        }
                    })
                }
                Selection::ParamEvidence(_) => {
                    let (declared, _) = p.gx.trait_assoc_consts[&assoc];
                    let args: Vec<GenericArg> = self.tys.args(tr.args).to_vec();
                    // `const MIN: Self::Primitive` under `B: Bounds<Primitive
                    // = i8>` reads as an `i8` (casts and drops need the
                    // normal form).
                    let t = subst(&mut self.tys, declared, &args);
                    Some((None, self.normalize_here(t)))
                }
                _ => None,
            };
            match hit {
                Some(h) => {
                    hits.push(h);
                    hit_traits.push(trait_def);
                }
                None => {
                    self.rollback_vars(snap);
                    self.obl_truncate(obl_len);
                    self.generic_sites.truncate(sites_len);
                }
            }
        }
        match hits.len() {
            1 => {
                let hit = hits.into_iter().next().unwrap();
                if let Some(e) = pick_e {
                    self.record_pick(e, hit_traits[0], 0, ReceiverForm::Value);
                    if hit.0.is_none() {
                        self.abstract_consts.push(e);
                    }
                }
                Some(hit)
            }
            0 => None,
            _ => {
                self.err(
                    "L0720",
                    span,
                    format!("multiple trait associated consts named `{}` apply here", self.name(name)),
                    "Name the trait with a fully qualified path, such as `<Type as Trait>::CONST`.",
                );
                Some((None, ERROR))
            }
        }
    }

    /// The self type a two-segment associated const path names:
    /// a type parameter or `Self` from the body scope, else a
    /// local Adt (written type arguments fix its parameters,
    /// fresh variables otherwise, as in `trait_assoc_base`). A
    /// `None` span (body const evaluation) reports no argument
    /// errors: the path's own check reports them.
    /// The one in-scope trait with a method `name` that holds for `base`
    /// (selection finds an impl, an env predicate, or a builtin answer),
    /// as its trait ref with fresh inputs. None when no trait or several
    /// do (rustc E0599, E0034).
    fn unique_item_trait(&mut self, base: Ty, name: Sym) -> Option<TraitRef> {
        let p = self.p;
        // A comparison trait's `Rhs` at a std type that has several
        // `PartialEq` / `PartialOrd` impls in std (`String: PartialEq<&str>`)
        // but one in lust: selecting the one impl would fix `Rhs` before
        // the arguments do, so `String::eq(&a, &&b)` would deref-coerce
        // where rustc rejects. Only scalars, user types, and params here.
        let rhs_trait = |d: DefId| d == p.gx.lang.partial_eq || d == p.gx.lang.partial_ord;
        let scalar_or_user = matches!(
            self.kind(self.resolve(base)),
            TyKind::Int(_) | TyKind::Float(_) | TyKind::Bool | TyKind::Char | TyKind::Param(_)
        ) || self.tys.local_adt(self.resolve(base)).is_some_and(|a| !generics::is_std_adt(&p.tys, a));
        let traits = p.gx.traits_by_method.get(&name)?.clone();
        let mut found: Option<DefId> = None;
        // The one found trait's selection was ambiguous.
        let mut open = false;
        for trait_def in traits {
            if !method::trait_in_scope_at(self, trait_def, base) {
                continue;
            }
            let n_inputs = p.gx.index.trait_record(trait_def)?.generics.params.len().saturating_sub(1);
            let snap = self.snapshot_vars();
            let obl_len = self.obl_len();
            let tr = self.fresh_trait_ref(trait_def, base, n_inputs);
            let sel = self.select_obligation(tr);
            self.rollback_vars(snap);
            self.obl_truncate(obl_len);
            let holds = matches!(sel, Selection::Impl { .. } | Selection::ParamEvidence(_) | Selection::Builtin);
            // A trait whose open inputs leave several impls (`Tr2<u8>`
            // and `Tr2<u16>` for `S`) also applies: with another trait
            // the item is ambiguous (rustc E0034), so none is unique.
            if holds || (n_inputs > 0 && matches!(sel, Selection::Ambiguous)) {
                if found.is_some() || open {
                    return None;
                }
                open = !holds;
                found = Some(trait_def);
            }
        }
        if open {
            return None;
        }
        let trait_def = found?;
        if rhs_trait(trait_def) && !scalar_or_user {
            return None;
        }
        let n_inputs = p.gx.index.trait_record(trait_def)?.generics.params.len().saturating_sub(1);
        Some(self.fresh_trait_ref(trait_def, base, n_inputs))
    }

    /// `trait_def` at Self `base` with fresh variables for its inputs.
    pub(super) fn fresh_trait_ref(&mut self, trait_def: DefId, base: Ty, n_inputs: usize) -> TraitRef {
        let mut a = vec![GenericArg::Ty(base)];
        for _ in 0..n_inputs {
            a.push(GenericArg::Ty(self.new_var(false)));
        }
        let args = self.tys.intern_args(&a);
        TraitRef { def: trait_def, args, bindings: EMPTY_BINDINGS }
    }

    /// A trait associated const of a concrete Self type, for body const
    /// evaluation (`[0; <S as Tr>::N]`): the one non-generic impl for
    /// `self_ty` (of `trait_def` when written, else of a trait in scope)
    /// that has the const, with the impl's value or the trait default
    /// collect evaluated. None when none or several apply, or a generic
    /// impl might.
    fn trait_const_value(&mut self, self_ty: Ty, trait_def: Option<DefId>, name: Sym) -> Option<crate::ty::consteval::TypedValue> {
        let p = self.p;
        let self_ty = self.deep(self_ty);
        let mut hit: Option<u32> = None;
        for (_, rec) in p.gx.index.all_impls() {
            if trait_def.is_some_and(|t| t != rec.trait_def) {
                continue;
            }
            let Some(assoc) = p.gx.index.trait_record(rec.trait_def).and_then(|r| r.assoc_by_name(name)) else { continue };
            if !p.gx.trait_assoc_consts.contains_key(&assoc) {
                continue;
            }
            if rec.self_ty(&p.tys) != self_ty {
                if !rec.generics.params.is_empty() && rec.blanket.is_some() {
                    return None;
                }
                continue;
            }
            if trait_def.is_none() && !method::trait_in_scope_at(self, rec.trait_def, self_ty) {
                continue;
            }
            let idx = p.impl_assoc_consts.get(&(rec.def, assoc)).or_else(|| p.trait_assoc_const_values.get(&assoc)).copied()?;
            if hit.is_some() {
                return None;
            }
            hit = Some(idx);
        }
        let idx = hit?;
        if p.gx.assoc_const_tmpls.contains_key(&idx) {
            return None;
        }
        let c = &p.consts[idx as usize];
        Some((c.value.clone(), c.ty))
    }

    fn assoc_const_base(&mut self, segs: &[ast::PathSeg], span: Option<Span>) -> Option<Ty> {
        let p = self.p;
        let head = segs[0].name;
        if let Some(&(_, t)) = self.body_scope.param_tys.iter().find(|(n, _)| *n == head) {
            return Some(t);
        }
        if head == p.known.self_type
            && let Some(t) = self.body_scope.self_ty
        {
            return Some(t);
        }
        // A block type item first (R18), as `assoc_const_key` reads it.
        let a = match self.local_adt_of(head) {
            Some(a) => Some(a),
            None => match self.binding(Namespace::Type, head) {
                BindingRes::Def(def) => p.adt_by_def(def),
                _ => None,
            },
        };
        // Through a type alias of a user Adt: the alias's type, with its
        // own args (`type R = M; R::NONE`).
        let Some(a) = a else {
            let (t, _) = self.alias_seg_ty(&segs[0], span.unwrap_or_default(), span.is_some())?;
            self.tys.adt_parts(t).and_then(|(d, _)| p.adt_by_def(d))?;
            return Some(t);
        };
        let generics = p.gx.adt_generics.get(a.0 as usize).cloned().unwrap_or_default();
        // `S::<3>::D` on a type with fewer type or const parameters
        // (rustc E0107): no base, so the const does not resolve.
        let written = match &segs[0].args {
            ast::GenericArgs::Angle(gs) => gs.iter().filter(|g| matches!(g, ast::GenericArg::Type(_) | ast::GenericArg::Const(_))).count(),
            _ => 0,
        };
        if written > generics.params.iter().filter(|g| g.kind != ParamKind::Lifetime).count() {
            if let Some(s) = span {
                self.err("L0110", s, "too many generic arguments for this type", "Remove the extra arguments.");
            }
            return None;
        }
        if generics.params.is_empty() {
            return Some(self.tys.adt_ty(a));
        }
        let mark = self.errs.len();
        let args = self.value_path_args(a, &segs[..1], span.unwrap_or_default());
        if span.is_none() {
            self.errs.truncate(mark);
        }
        Some(self.tys.mk_adt(p.def_of_adt(a), &args))
    }

    /// A zero const value of one type, for the template-only
    /// placeholder in `finish`. A `&str` gets an empty string and a
    /// parameter or projection type the unit value (the template is
    /// only borrow checked). Other reference and non-const shapes have no
    /// placeholder: a trait associated const of such a type read
    /// through a type parameter still fails the template check with
    /// the unassigned-temp error.
    fn zero_const(&mut self, t: Ty) -> Option<crate::ty::consteval::ConstValue> {
        use crate::ty::consteval::ConstValue;
        let t = self.deep(t);
        let t = self.normalize_here(t);
        match self.tys.kind(t) {
            // `const WHAT: &'static str` read through a parameter.
            TyKind::Ref(_, _, inner) if matches!(self.tys.kind(inner), TyKind::Str) => Some(ConstValue::StrBytes(crate::ast::ByteBlob::new(Vec::new()))),
            // A value of a parameter's type (`B::MIN` with `const MIN:
            // Self::Primitive` under `B: Bounds<Primitive = P>`): the
            // template body is only borrow checked, never built, so any
            // initialized value stands in.
            TyKind::Param(_) | TyKind::Projection(..) => Some(ConstValue::Unit),
            TyKind::Adt(..) if self.tys.option_elem(t).is_some() => Some(ConstValue::Variant(0, Vec::new())),
            TyKind::Adt(..) => {
                let p = self.p;
                let a = self.tys.local_adt(t)?;
                let (is_enum, field_tys) = {
                    let adt = p.adt(a);
                    (adt.is_enum, adt.variants.first()?.fields.iter().map(|f| f.ty).collect::<Vec<Ty>>())
                };
                let args: Vec<GenericArg> = match self.tys.adt_parts(t) {
                    Some((_, args_id)) => self.tys.args(args_id).to_vec(),
                    None => Vec::new(),
                };
                let mut vals = Vec::new();
                for ft in field_tys {
                    let ft = if args.is_empty() { ft } else { self.subst_field(ft, &args) };
                    vals.push(self.zero_const(ft)?);
                }
                Some(if is_enum { ConstValue::Variant(0, vals) } else { ConstValue::Aggregate(vals) })
            }
            TyKind::Int(_) => Some(ConstValue::Int(0)),
            TyKind::Float(f) => Some(ConstValue::Float(0, f)),
            TyKind::Bool => Some(ConstValue::Bool(false)),
            TyKind::Char => Some(ConstValue::Char('\0')),
            TyKind::Unit => Some(ConstValue::Unit),
            TyKind::Tuple(ts) => {
                let elems: Vec<Ty> = self.tys.tys_of(ts).to_vec();
                let mut vals = Vec::new();
                for e in elems {
                    vals.push(self.zero_const(e)?);
                }
                Some(ConstValue::Aggregate(vals))
            }
            TyKind::Array(e, c) => {
                let ConstKind::Int(n) = self.tys.const_kind(self.resolve_const(c)) else { return None };
                Some(ConstValue::Repeat(Box::new(self.zero_const(e)?), n as u64))
            }
            _ => None,
        }
    }

    /// The (Adt, name) key an associated const path (`Self::A`,
    /// `Type::A`) names, when the owning type is a local Adt.
    fn assoc_const_key(&mut self, segs: &[ast::PathSeg]) -> Option<(AdtId, Sym)> {
        if segs.len() != 2 {
            return None;
        }
        let p = self.p;
        let (ty_name, item) = (segs[0].name, segs[1].name);
        // A block type item shadows a module type of its name (R18).
        let adt = if ty_name == p.known.self_type {
            self.self_adt()
        } else if let Some(a) = self.local_adt_of(ty_name) {
            Some(a)
        } else {
            match self.binding(Namespace::Type, ty_name) {
                BindingRes::Def(def) => p.adt_by_def(def),
                _ => None,
            }
        };
        // Through a type alias of a user Adt (`type R = M; R::NONE`).
        let adt = adt.or_else(|| {
            let (t, _) = self.alias_seg_ty(&segs[0], Span::default(), false)?;
            p.adt_by_def(self.tys.adt_parts(t)?.0)
        })?;
        Some((adt, item))
    }

    /// The pick among same-name inherent associated consts for
    /// a written Self type instance, exactly as written
    /// (`assoc_const_base`): an impl applies when its Self
    /// pattern unifies with the instance under fresh impl
    /// arguments, probed with rollback so a rejected candidate
    /// binds nothing. The one hit replays for real (its
    /// predicates become obligations); several hits report the
    /// ambiguity here and act as no pick.
    /// `None` when no candidate applies (the caller keeps
    /// looking), `Some(None)` when several apply (reported
    /// here; the caller must not fall through to a trait item).
    fn inherent_assoc_pick(
        &mut self,
        adt: AdtId,
        item: Sym,
        written: Ty,
        span: Option<Span>,
    ) -> Option<Option<(u32, crate::ty::consteval::ConstValue)>> {
        let p = self.p;
        let cands: Vec<u32> = p.inherent_assoc_consts(adt, item).to_vec();
        if cands.is_empty() {
            return None;
        }
        let mut hits: Vec<(u32, Option<(Ty, Generics, Span)>)> = Vec::new();
        for &idx in &cands {
            let entry = p.gx.inherent_const_self.get(&idx).cloned();
            let applies = match &entry {
                None => true,
                Some((pat, gens, _)) => {
                    let snap = self.snapshot_vars();
                    let obl = self.obl_len();
                    let args = self.fresh_args(gens);
                    let cand = subst(&mut self.tys, *pat, &args);
                    let hit = self.unify(cand, written);
                    self.rollback_vars(snap);
                    self.obl_truncate(obl);
                    hit
                }
            };
            if applies {
                hits.push((idx, entry));
            }
        }
        match hits.len() {
            0 => None,
            1 => {
                let (idx, entry) = hits.pop().unwrap();
                let mut value = None;
                if let Some((pat, gens, _)) = entry {
                    let args = self.fresh_args(&gens);
                    let cand = subst(&mut self.tys, pat, &args);
                    if self.unify(cand, written) {
                        if let Some(span) = span {
                            let preds = gens.predicates.clone();
                            self.push_predicates(&preds, &args, span);
                        }
                        value = self.assoc_const_value(idx, &gens, args, written, None);
                    }
                }
                // An abstract instance (a template check) bakes
                // the placeholder; the instance re-check computes
                // the real value.
                let value = value.unwrap_or_else(|| p.consts[idx as usize].value.clone());
                Some(Some((idx, value)))
            }
            _ => {
                if let Some(span) = span {
                    self.err(
                        "L0110",
                        span,
                        format!("multiple associated constants named `{}` apply here", self.name(item)),
                        "Write the type arguments so only one impl applies, for example `Type::<Arg>::CONST`.",
                    );
                }
                Some(None)
            }
        }
    }

    fn pattern(&mut self, pat: PatId, t: Ty, in_match: bool) {
        // Names bound from here on belong to this one pattern
        // (see the duplicate-name check in `bind_pattern_local`).
        self.pat_marks.push(self.scopes.len());
        let err_mark = self.errs.len();
        self.pattern_mode(pat, t, BindMode::Move, in_match);
        self.pat_marks.pop();
        // A literal or const subpattern in a `let` records a
        // "refutable patterns here" reject while it is checked,
        // before the whole pattern is known to match every
        // value (`let (true | false) = b;`). When it does, that
        // reject is not real: drop it.
        if !in_match && self.pat_always_matches(pat) {
            let kept: Vec<Diag> = self
                .errs
                .drain(err_mark..)
                .filter(|d| !(d.code == "L9001" && d.message.starts_with("refutable patterns here")))
                .collect();
            self.errs.extend(kept);
        }
    }

    fn pattern_mode(&mut self, pat: PatId, t: Ty, mode: BindMode, in_match: bool) {
        let p = self.p;
        let pi = (pat.0 - self.out.pat_base) as usize;
        let span = p.ast.pat_span(pat);
        // Default binding modes: a non-binding pattern auto-derefs a reference scrutinee.
        let scrut_t = self.resolve(t);
        let mut t = scrut_t;
        let mut mode = mode;
        // `OP::Some(x)` and `RR::Ok(x)` through an alias of Option or
        // Result are the std variants (check/alias_path.rs).
        let alias_ctor = self.alias_ctor_pattern(pat, span);
        let opt = self.option_pattern(pat).or(alias_ctor.and_then(|(o, v)| o.then_some(v)));
        let structural = opt.is_some()
            || matches!(
                p.ast.pat(pat),
                Pat::TupleStruct { .. }
                    | Pat::Struct { .. }
                    | Pat::Path(_)
                    | Pat::Lit(_)
                    | Pat::Range { .. }
                    | Pat::Tuple(_)
                    | Pat::Slice { .. }
            );
        if structural {
            let mut derefs = 0;
            while let TyKind::Ref(_, m, inner) = self.tys.kind(t) {
                // A string literal, byte string literal, or &str const
                // pattern has a reference type itself, so it matches
                // the scrutinee reference directly and never
                // auto-derefs (rustc rejects `&&str` against `"ab"`
                // and `&&[u8]` against `b"ab"`).
                let str_pat = matches!(p.ast.pat(pat), Pat::Lit(l) if matches!(p.ast.expr(*l), Expr::Str(_)) || self.is_byte_str_lit(*l))
                    || matches!(p.ast.pat(pat), Pat::Path(segs) if segs.len() == 1 && p.const_names.get(&segs[0].name).is_some_and(|&i| matches!(p.consts[i as usize].value, crate::ty::consteval::ConstValue::Str(_))));
                if str_pat {
                    break;
                }
                derefs += 1;
                mode = match mode {
                    BindMode::Ref(false) => BindMode::Ref(false),
                    _ => BindMode::Ref(m.is_mut()),
                };
                t = self.resolve(inner);
            }
            self.out.pat_derefs[pi] = derefs;
        }
        self.out.pat_ty[pi] = t;
        // Turbofish on the pattern's path (`Some::<u8>(x)`, `None::<u8>`)
        // fixes the scrutinee's args, as in expressions.
        let pat_path: Option<&[ast::PathSeg]> = match p.ast.pat(pat) {
            Pat::TupleStruct { path, .. } | Pat::Path(path) => Some(path.as_slice()),
            _ => None,
        };
        if let Some(is_some) = opt {
            let inner = match pat_path.and_then(|segs| self.builtin_ctor_args(segs, 1, span)) {
                Some(a) => a[0],
                None => self.new_var(false),
            };
            let ot = self.tys.mk_option(inner);
            if std::env::var_os("LUST_DEBUG_PAT").is_some() {
                eprintln!(
                    "PAT opt scrutinee ty={} kind={:?} fn={} params={:?}",
                    self.tn(t),
                    self.tys.kind(t),
                    self.name(self.f.name),
                    self.f.params.iter().map(|&x| self.tn(x)).collect::<Vec<_>>()
                );
            }
            if !self.unify(ot, t) {
                self.mismatch(span, t, ot);
                return;
            }
            self.out.pat_res[pi] = PatRes::Opt(is_some);
            if let (true, Pat::TupleStruct { elems, .. }) = (is_some, p.ast.pat(pat)) {
                self.pattern_mode(elems[0], inner, mode, in_match);
            }
            return;
        }
        if opt.is_none()
            && let Some(occupied) = self.entry_pattern(pat)
        {
            self.entry_variant_pattern(pat, occupied, t, mode, in_match, span);
            return;
        }
        if opt.is_none()
            && let Some(is_ok) = self.result_pattern(pat).or(alias_ctor.and_then(|(o, v)| (!o).then_some(v)))
        {
            let (a, b) = match pat_path.and_then(|segs| self.builtin_ctor_args(segs, 2, span)) {
                Some(w) => (w[0], w[1]),
                None => (self.new_var(false), self.new_var(false)),
            };
            let rt = self.tys.mk_result(a, b);
            if !self.unify(rt, t) {
                self.mismatch(span, t, rt);
                return;
            }
            self.out.pat_res[pi] = PatRes::Res(is_ok);
            if let Pat::TupleStruct { elems, .. } = p.ast.pat(pat) {
                self.pattern_mode(elems[0], if is_ok { a } else { b }, mode, in_match);
            }
            return;
        }
        // A plain name that resolves to a const item, a unit struct, or
        // a unit variant is a path pattern, not a binding (unless a
        // local binding shadows the name). Imports count: resolution
        // goes through the module bindings, as in expressions. The
        // pattern consumes the const's value, so record its `Sig` read
        // (the fingerprint folds the evaluated value): a value edit
        // must recheck this body (ARCH 8.2), like a const in an
        // expression.
        if let Pat::Binding { name, mutable: false, by_ref: false } = p.ast.pat(pat)
            && self.lookup(*name, span.ctxt).is_none()
            && let Some(crate::check::collect::BodyItem::Const(ci)) = self.body_item_of(*name)
        {
            let c = &p.body_consts[ci as usize];
            let (ct, val) = (c.ty, c.value.clone());
            match self.check_const_value(ct, &val, t, span, in_match) {
                Some(ConstPat::Value) => self.out.pat_res[pi] = PatRes::BodyConst(ci),
                Some(ConstPat::Variant(a, v)) => self.out.pat_res[pi] = PatRes::Variant(a, v),
                Some(ConstPat::OptNone) => self.out.pat_res[pi] = PatRes::Opt(false),
                None => {}
            }
            return;
        }
        // A body fn or static of the name hides module items (a body
        // static is rejected at the binding below).
        if let Pat::Binding { name, mutable: false, by_ref: false } = p.ast.pat(pat)
            && self.lookup(*name, span.ctxt).is_none()
            && (self.local_ctor_of(*name).is_some() || self.body_item_of(*name).is_none())
            && self.const_param(*name).is_none()
        {
            match self.pat_binding(*name) {
                PatIdent::Const(idx) => {
                    self.const_item_pat(pi, idx, t, span, in_match);
                    return;
                }
                PatIdent::Static => {
                    self.err(
                        "L0110",
                        span,
                        "statics cannot be used as patterns",
                        "Use a const item for a pattern, or compare with the static in a guard.",
                    );
                    return;
                }
                PatIdent::Variant(a, v) => {
                    let adt_ty = self.tys.adt_ty(a);
                    if !self.unify(adt_ty, t) {
                        self.mismatch(span, t, adt_ty);
                        return;
                    }
                    if p.adt(a).variants[v as usize].shape != VariantShape::Unit {
                        self.err("L0110", span, "this variant has fields", "Match its fields with `(..)` or `{ .. }`.");
                        return;
                    }
                    if self.hidden_variant(a, v, span) {
                        return;
                    }
                    self.out.pat_res[pi] = PatRes::Variant(a, v);
                    return;
                }
                PatIdent::Other => {}
            }
        }
        // A const path pattern (`MAX`, `Self::A`, `Type::A`, `m::S`)
        // is not a variant: it compares against the const's value.
        if let Pat::Path(segs) = p.ast.pat(pat) {
            let segs = segs.clone();
            if self.try_const_path_pat(pi, &segs, scrut_t, span, in_match) {
                // A const path pattern never auto-derefs (rustc's
                // `AdjustMode::Pass`): it matches the scrutinee type
                // itself, so peeling above is undone.
                self.unpeel_const_pat(pi, scrut_t);
                return;
            }
        }
        // A qualified path pattern (`<K>::A`, `<K as Tr>::C`):
        // a const comparison or a unit variant, never a binding.
        if let Pat::QPath { self_ty, trait_path, segs } = p.ast.pat(pat) {
            let (self_ty, trait_path, segs) = (*self_ty, trait_path.clone(), segs.clone());
            self.qpath_pat(pi, self_ty, &trait_path, &segs, t, span, in_match);
            return;
        }
        match p.ast.pat(pat) {
            Pat::Wild => {}
            Pat::Binding { name, mutable, by_ref } => {
                // A plain binding named the same as a variant of the
                // matched enum type is an error (rustc E0170, the
                // deny-by-default `bindings_with_variant_name`): it can
                // never mean the variant. `mut`, `ref`, and `@` forms
                // are plain bindings and stay legal.
                if !mutable && !by_ref {
                    let (_, base) = self.autoderef(t);
                    if let Some(a) = self.tys.local_adt(self.resolve(base))
                        && p.adt(a).is_enum
                        && p.adt(a).variants.iter().any(|v| v.name == *name)
                        && self.lookup(*name, span.ctxt).is_none()
                        && !matches!(self.pat_binding(*name), PatIdent::Variant(b, _) if b == a)
                        && !self.lint_lifted(&["bindings_with_variant_name"])
                    {
                        let (vn, en) = (self.name(*name).to_string(), p.display_path(p.adt(a).name));
                        self.err(
                            "L0110",
                            span,
                            format!("pattern binding `{vn}` is named the same as one of the variants of the type `{en}`"),
                            format!("Rename the binding, or match the variant with `{en}::{vn}` (or `use {en}::{vn};` first)."),
                        );
                        return;
                    }
                }
                if self.binding_shadows_item(*name, span, !mutable && !by_ref) {
                    return;
                }
                self.bind_pattern_local(pi, *name, *mutable, *by_ref, t, mode, span);
            }
            Pat::At { name, mutable, by_ref, inner } => {
                if self.binding_shadows_item(*name, span, false) {
                    return;
                }
                self.bind_pattern_local(pi, *name, *mutable, *by_ref, t, mode, span);
                self.pattern_mode(*inner, t, mode, in_match);
            }
            Pat::Ref { mutable, inner } => match self.kind(t) {
                TyKind::Ref(_, m, inner_ty) => {
                    // Edition 2024: an explicit `&` dereference inside an
                    // implicitly-borrowing pattern is an error.
                    if mode != BindMode::Move {
                        self.err(
                            "L0122",
                            span,
                            "cannot explicitly dereference within an implicitly-borrowing pattern",
                            "Remove the `&`: the pattern already borrows by default, so the binding has the same type without it.",
                        );
                    }
                    if *mutable && !m.is_mut() {
                        self.err(
                            "L0110",
                            span,
                            "pattern requires `&mut`, but the matched type is a shared reference",
                            "Use `&` in the pattern, or match on a `&mut` value.",
                        );
                    }
                    if !*mutable && m.is_mut() {
                        self.err(
                            "L0110",
                            span,
                            "pattern requires `&`, but the matched type is a mutable reference",
                            "Use `&mut` in the pattern, or match on a shared reference.",
                        );
                    }
                    // An explicit `&` resets the default binding mode inside it.
                    self.pattern_mode(*inner, inner_ty, BindMode::Move, in_match);
                }
                TyKind::Error => self.pattern_mode(*inner, ERROR, mode, in_match),
                _ => {
                    let tn = self.tn(t);
                    self.err(
                        "L0110",
                        span,
                        format!("reference pattern cannot match a value of type `{tn}`"),
                        "Match on a reference, or remove the `&`.",
                    );
                    self.pattern_mode(*inner, ERROR, mode, in_match);
                }
            },
            Pat::Lit(l) => {
                // A byte string literal has type `&[u8; N]` but, as a
                // pattern, also matches a `&[u8]` scrutinee (rustc's
                // byte string pattern rule). Check it with no expected
                // type so the array keeps its own length, then apply
                // that rule by hand.
                let byte_str = self.is_byte_str_lit(*l);
                let lt = self.expr(*l, if byte_str { None } else { Some(t) });
                if !self.unify(lt, t) && !(byte_str && self.byte_str_pat_ok(lt, t)) {
                    self.mismatch(span, t, lt);
                }
                if !in_match {
                    self.errs.push(unsupported(span, "refutable patterns here"));
                }
            }
            Pat::Range { lo, hi, inclusive } => {
                // The parser only builds two-bound ranges today; a half-open
                // range checks its one bound the same way.
                let mut bound_tys = Vec::new();
                if let Some(lo) = lo {
                    bound_tys.push((*lo, self.expr(*lo, Some(t))));
                }
                if let Some(hi) = hi {
                    bound_tys.push((*hi, self.expr(*hi, Some(t))));
                }
                // A range bound that reads a trait associated const
                // through a type parameter depends on the parameter:
                // rustc rejects constant patterns that do (E0158).
                for &(b_e, _) in &bound_tys {
                    if self.abstract_consts.contains(&b_e) {
                        let b_span = self.span(b_e);
                        self.err(
                            "L0110",
                            b_span,
                            "a range pattern bound cannot depend on a generic parameter",
                            "Use a literal bound, or compare with an `if` guard.",
                        );
                    }
                }
                // An exclusive range `lo..hi` needs lo < hi (rustc E0579);
                // an inclusive one needs lo <= hi (rustc E0030). Float
                // ranges follow the same rules, and a NaN bound is an
                // error in rustc ("cannot use NaN in patterns").
                let mut empty = false;
                // An unresolved float variable falls back to `f64` at
                // body end, so its bounds read as `f64` here too.
                let float_ft = match self.kind(t) {
                    TyKind::Float(ft) => Some(ft),
                    k if k.is_float_infer() => Some(FloatTy::F64),
                    _ => None,
                };
                if let Some(ft) = float_ft {
                    let vals: Vec<Option<f64>> = bound_tys.iter().map(|&(b_e, _)| self.const_float(b_e, ft)).collect();
                    for (&(b_e, _), v) in bound_tys.iter().zip(&vals) {
                        if v.is_some_and(|v| v.is_nan()) {
                            let b_span = self.span(b_e);
                            self.err("L0110", b_span, "cannot use NaN in patterns", "Use a guard to test for NaN.");
                        }
                    }
                    if let [Some(lo_v), Some(hi_v)] = vals[..] {
                        empty = lo_v > hi_v || (!inclusive && lo_v == hi_v);
                    }
                }
                if let [(lo_e, _), (hi_e, _)] = bound_tys[..]
                    && let (Some(lo_v), Some(hi_v)) = (self.const_scalar(lo_e), self.const_scalar(hi_e))
                    && match (self.scalar_key(lo_v, t), self.scalar_key(hi_v, t)) {
                        (Some(a), Some(b)) => a > b || (!inclusive && a == b),
                        _ => lo_v > hi_v || (!inclusive && lo_v == hi_v),
                    }
                {
                    empty = true;
                }
                // `..MIN` is empty too: the exclusive upper bound is the
                // type's minimum, whose order key is 0 (rustc E0579).
                if lo.is_none()
                    && !inclusive
                    && let [(hi_e, _)] = bound_tys[..]
                    && self.const_scalar(hi_e).is_some_and(|hi_v| self.scalar_key(hi_v, t) == Some(0))
                {
                    empty = true;
                }
                if empty {
                    self.err(
                        "L0119",
                        span,
                        "lower range bound is greater than the upper bound",
                        "Swap the bounds, or fix the values. An empty range pattern never matches.",
                    );
                }
                if bound_tys.iter().any(|&(_, bt)| !self.unify(bt, t))
                    || !(matches!(self.kind(t), TyKind::Int(_) | TyKind::Float(_) | TyKind::Char)
                        || self.kind(t).is_int_infer()
                        || self.kind(t).is_float_infer())
                {
                    self.err(
                        "L0110",
                        span,
                        "range patterns need integer, float, or char bounds of the matched type",
                        "Use bounds of the scrutinee's type.",
                    );
                }
            }
            Pat::Path(segs) | Pat::TupleStruct { path: segs, .. } | Pat::Struct { path: segs, .. } => {
                // A path may also name a const item (`m::K`, rewritten
                // to its flat name) or a primitive associated const
                // (`u8::MAX`): both compare like literal patterns.
                if matches!(p.ast.pat(pat), Pat::Path(_)) {
                    if segs.len() == 1 {
                        match self.pat_ident(segs[0].name) {
                            PatIdent::Const(idx) => {
                                // As above: a const pattern never
                                // auto-derefs.
                                self.const_item_pat(pi, idx, scrut_t, span, in_match);
                                self.unpeel_const_pat(pi, scrut_t);
                                return;
                            }
                            PatIdent::Static => {
                                self.err(
                                    "L0110",
                                    span,
                                    "statics cannot be used as patterns",
                                    "Use a const item for a pattern, or compare with the static in a guard.",
                                );
                                return;
                            }
                            PatIdent::Variant(a, v) if p.adt(a).is_enum => {
                                let adt_ty = self.tys.adt_ty(a);
                                if !self.unify(adt_ty, t) {
                                    self.mismatch(span, t, adt_ty);
                                    return;
                                }
                                if p.adt(a).variants[v as usize].shape != VariantShape::Unit {
                                    self.err("L0110", span, "this variant has fields", "Match its fields with `(..)` or `{ .. }`.");
                                    return;
                                }
                                if self.hidden_variant(a, v, span) {
                                    return;
                                }
                                self.out.pat_res[pi] = PatRes::Variant(a, v);
                                return;
                            }
                            _ => {}
                        }
                    } else if let Some((cv, ct)) = self.primitive_const_pattern(segs) {
                        // As above: a const pattern does not auto-deref.
                        if self.out.pat_derefs[pi] > 0 {
                            self.mismatch(span, scrut_t, ct);
                            return;
                        }
                        if !self.unify(ct, t) {
                            self.mismatch(span, t, ct);
                            return;
                        }
                        self.out.pat_const[pi] = Some(cv);
                        return;
                    }
                }
                let target = if segs.len() == 1 {
                    let n = segs[0].name;
                    // The flat type table answers below; the binding query
                    // is the recorded read of that answer (ARCH 8.2).
                    if n != p.known.self_type {
                        self.binding(Namespace::Type, n);
                    }
                    let a = if n == p.known.self_type { self.self_adt() } else { self.type_name_adt(n) };
                    // A struct pattern through a type alias (`SA { a }`);
                    // tuple-struct and unit patterns need the value
                    // namespace, which an alias does not fill (rustc E0532).
                    let a = match p.ast.pat(pat) {
                        Pat::Struct { .. } => a.or_else(|| self.alias_adt(n).map(|(a, _)| a)),
                        _ => a,
                    };
                    match a.filter(|&a| !p.adt(a).is_enum).map(|a| (a, 0)) {
                        Some(v) => Some(v),
                        // An imported variant in a tuple or struct pattern
                        // (`use E::*; B(n)`): resolve through the bindings.
                        None => match self.pat_ident(n) {
                            PatIdent::Variant(a, v) => Some((a, v)),
                            _ => None,
                        },
                    }
                } else {
                    match self.resolve_assoc(segs, span) {
                        Some(Res::Variant(a, v)) => Some((a, v)),
                        Some(_) => {
                            self.err("L0110", span, "expected a variant or struct in this pattern", "Use `Type::Variant`.");
                            None
                        }
                        None => return,
                    }
                };
                let Some((a, v)) = target else {
                    self.err("L0102", span, "unknown struct or variant in pattern", "Check the name.");
                    return;
                };
                // Written args on the pattern's path (`E::<u8>::A(x)`), and
                // a path through `Self` (the impl's own args), must name
                // the scrutinee's own type.
                let ty_seg = segs[segs.len().saturating_sub(2)].name;
                let via_self = ty_seg == p.known.self_type;
                let via_alias = self.alias_adt(ty_seg).is_some_and(|(_, args)| !args.is_empty());
                if (via_self || via_alias || segs[segs.len().saturating_sub(2)..].iter().any(|s| s.has_args()))
                    && !p.gx.adt_generics[a.0 as usize].params.is_empty()
                {
                    let written = self.value_path_args(a, segs, span);
                    let wt = self.tys.mk_adt(p.def_of_adt(a), &written);
                    if !self.unify(wt, t) {
                        self.mismatch(span, t, wt);
                        return;
                    }
                }
                // A generic Adt pattern matches the scrutinee's
                // own instance when mono has made it; before that
                // (and in templates) it matches the template with
                // the scrutinee's args substituted into its fields.
                let dt = self.deep(t);
                let scrut_args: Vec<GenericArg> = match self.tys.adt_parts(dt) {
                    Some((d, aa)) if d == p.def_of_adt(a) => self.tys.args(aa).to_vec(),
                    _ => Vec::new(),
                };
                let (a, adt_ty) = match self.tys.local_adt(dt) {
                    Some(inst) if inst != a && p.def_of_adt(inst) == p.def_of_adt(a) => (inst, dt),
                    _ if !scrut_args.is_empty() => (a, dt),
                    _ => (a, self.tys.adt_ty(a)),
                };
                if !self.unify(adt_ty, t) {
                    self.mismatch(span, t, adt_ty);
                    return;
                }
                self.out.pat_res[pi] = PatRes::Variant(a, v);
                let variant = &p.adt(a).variants[v as usize];
                match p.ast.pat(pat) {
                    Pat::Path(_) => {
                        if variant.shape != VariantShape::Unit {
                            self.err("L0110", span, "this variant has fields", "Match its fields with `(..)` or `{ .. }`.");
                        } else {
                            self.check_ne_ctor(a, v, span);
                        }
                    }
                    Pat::TupleStruct { elems, .. } => {
                        if variant.shape != VariantShape::Tuple {
                            self.err(
                                "L0110",
                                span,
                                format!("this variant has {} field(s)", variant.fields.len()),
                                "Match every field, or use `_` for the ones you do not need.",
                            );
                            return;
                        }
                        if !p.adt(a).is_enum {
                            self.check_ctor_vis(a, span);
                        }
                        self.check_ne_ctor(a, v, span);
                        let Some(mapped) = map_tuple_elems(&p.ast, elems, variant.fields.len()) else {
                            self.err(
                                "L0110",
                                span,
                                format!("this variant has {} field(s)", variant.fields.len()),
                                "Match every field, use `_`, or skip the middle with `..`.",
                            );
                            return;
                        };
                        for (i, sub) in mapped {
                            let ft = variant.fields[i].ty;
                            let ft = if scrut_args.is_empty() { ft } else { self.subst_norm(ft, &scrut_args, span) };
                            self.pattern_mode(sub, ft, mode, in_match);
                        }
                    }
                    Pat::Struct { fields, rest, .. } => {
                        // Braces fit every shape, as in rustc: `U {}` for a
                        // unit struct, `P { 0: x, .. }` for a tuple struct.
                        if variant.shape == VariantShape::Unit && !fields.is_empty() {
                            self.err("L0110", span, "this variant does not have named fields", "Use the tuple form.");
                            return;
                        }
                        for &(fname, sub) in fields {
                            match variant.fields.iter().position(|f| f.name == fname) {
                                Some(i) => {
                                    self.check_field_vis(a, fname, p.ast.pat_span(sub));
                                    let ft = variant.fields[i].ty;
                                    let ft = if scrut_args.is_empty() { ft } else { self.subst_norm(ft, &scrut_args, span) };
                                    self.pattern_mode(sub, ft, mode, in_match);
                                }
                                None => {
                                    let s = p.ast.pat_span(sub);
                                    self.err(
                                        "L0103",
                                        s,
                                        format!("no field `{}` in this variant", self.name(fname)),
                                        "Check the field name.",
                                    );
                                }
                            }
                        }
                        self.check_ne_pat(a, v, *rest, span);
                        if !rest && fields.len() < variant.fields.len() {
                            self.err(
                                "L0107",
                                span,
                                "pattern does not mention all fields",
                                "Add the missing fields, or end the pattern with `..`.",
                            );
                        }
                    }
                    _ => unreachable!(),
                }
            }
            Pat::Or(alts) => {
                // Every alternative binds the same names into the
                // same locals: the first alternative records its
                // bindings, later ones reuse them (see
                // `bind_pattern_local`). The scopes this pattern
                // leaves behind are the first alternative's.
                let alts: Vec<PatId> = alts.clone();
                if alts.is_empty() {
                    return;
                }
                let scope0 = self.scopes.len();
                let parent_log = self.or_log.take();
                self.or_log = Some(Vec::new());
                self.pattern_mode(alts[0], t, mode, in_match);
                let first_log = self.or_log.take().unwrap_or_default();
                self.or_log = parent_log;
                if let Some(log) = &mut self.or_log {
                    log.extend(first_log.iter().cloned());
                }
                let first_scope: Vec<((Sym, CtxtId), u32)> = self.scopes[scope0..].to_vec();
                for &alt in &alts[1..] {
                    self.scopes.truncate(scope0);
                    self.or_frames.push(OrFrame { seen: vec![false; first_log.len()], expected: first_log.clone(), extra: Vec::new() });
                    self.pattern_mode(alt, t, mode, in_match);
                    let frame = self.or_frames.pop().unwrap();
                    let alt_span = p.ast.pat_span(alt);
                    for (b, &seen) in frame.expected.iter().zip(&frame.seen) {
                        if !seen {
                            self.err(
                                "L0110",
                                alt_span,
                                format!("variable `{}` is not bound in all `|` alternatives", self.name(b.name)),
                                "Bind it in every alternative, or in none of them.",
                            );
                        }
                    }
                    for (name, s) in &frame.extra {
                        self.err(
                            "L0110",
                            *s,
                            format!("variable `{}` is not bound in all `|` alternatives", self.name(*name)),
                            "Bind it in every alternative, or in none of them.",
                        );
                    }
                }
                self.scopes.truncate(scope0);
                self.scopes.extend(first_scope);
            }
            Pat::Tuple(elems) => {
                if elems.is_empty() {
                    if !self.unify(t, UNIT) {
                        self.mismatch(span, t, UNIT);
                    }
                    return;
                }
                let elem_tys: Vec<Ty> = (0..elems.len()).map(|_| self.new_var(false)).collect();
                // A rest element means the arity is not the written count; take
                // element types from the scrutinee tuple when it is known.
                let known: Option<Vec<Ty>> = match self.kind(t) {
                    TyKind::Tuple(ts) => Some(self.tys.tys_of(ts).to_vec()),
                    _ => None,
                };
                match known {
                    Some(kt) => {
                        let Some(mapped) = map_tuple_elems(&p.ast, elems, kt.len()) else {
                            self.err(
                                "L0110",
                                span,
                                format!("this tuple has {} element(s)", kt.len()),
                                "Match every element, use `_`, or skip the middle with `..`.",
                            );
                            return;
                        };
                        for (i, sub) in mapped {
                            self.pattern_mode(sub, kt[i], mode, in_match);
                        }
                    }
                    None => {
                        if elems.iter().any(|&s| matches!(p.ast.pat(s), Pat::Rest)) {
                            self.err(
                                "L0110",
                                span,
                                "cannot use `..` when the tuple type is not known",
                                "Add a type annotation, or match every element.",
                            );
                            return;
                        }
                        for (i, &sub) in elems.iter().enumerate() {
                            self.pattern_mode(sub, elem_tys[i], mode, in_match);
                        }
                        let ts = self.tys.intern_tys(&elem_tys);
                        let tt = self.tys.intern(TyKind::Tuple(ts));
                        if !self.unify(tt, t) {
                            self.mismatch(span, t, tt);
                        }
                    }
                }
            }
            // A bare `..` only appears inside tuple and slice forms, which map
            // it away before recursing; anywhere else it is a syntax error.
            Pat::Rest => {
                self.err("L0110", span, "`..` can only be used in tuple and slice patterns", "Remove the `..`.");
            }
            Pat::Slice { prefix, middle, suffix } => {
                let (elem, arr_len) = match self.kind(t) {
                    TyKind::Array(elem, c) => {
                        let n = match self.tys.const_kind(c) {
                            ConstKind::Int(n) => Some(n as u64),
                            _ => None,
                        };
                        (elem, n)
                    }
                    TyKind::Slice(elem) => (elem, None),
                    TyKind::Error => {
                        for &sub in prefix.iter().chain(suffix.iter()) {
                            self.pattern_mode(sub, ERROR, mode, in_match);
                        }
                        if let Some(mid) = middle {
                            if !matches!(p.ast.pat(*mid), Pat::Rest) {
                                self.pattern_mode(*mid, ERROR, mode, in_match);
                            }
                        }
                        return;
                    }
                    _ => {
                        let tn = self.tn(t);
                        self.err(
                            "L0110",
                            span,
                            format!("slice pattern cannot match a value of type `{tn}`"),
                            "Match on an array or a slice, for example `&value[..]`.",
                        );
                        for &sub in prefix.iter().chain(suffix.iter()) {
                            self.pattern_mode(sub, ERROR, mode, in_match);
                        }
                        return;
                    }
                };
                let fixed = (prefix.len() + suffix.len()) as u64;
                if let Some(n) = arr_len {
                    let bad = if middle.is_some() { fixed > n } else { fixed != n };
                    if bad {
                        self.err(
                            "L0110",
                            span,
                            format!("pattern requires {fixed} element(s) but the array has {n}"),
                            "Change the pattern length, or skip the middle with `..`.",
                        );
                        return;
                    }
                }
                for &sub in prefix.iter().chain(suffix.iter()) {
                    self.pattern_mode(sub, elem, mode, in_match);
                }
                if let Some(mid) = middle {
                    match p.ast.pat(*mid) {
                        Pat::Rest | Pat::Wild => {}
                        Pat::Binding { by_ref: true, .. } => {
                            let st = self.tys.intern(TyKind::Slice(elem));
                            self.pattern_mode(*mid, st, mode, in_match);
                        }
                        Pat::Binding { .. } => match (mode, arr_len) {
                            (BindMode::Move, Some(n)) => {
                                let c = self.tys.intern_const(ConstKind::Int((n - fixed) as u128));
                                let at = self.tys.intern(TyKind::Array(elem, c));
                                self.pattern_mode(*mid, at, BindMode::Move, in_match);
                            }
                            (BindMode::Move, None) => {
                                self.err(
                                    "L0110",
                                    span,
                                    "cannot bind the middle of a slice pattern by value",
                                    "Match on a reference, or use `ref` for the binding.",
                                );
                            }
                            (BindMode::Ref(_), _) => {
                                let st = self.tys.intern(TyKind::Slice(elem));
                                self.pattern_mode(*mid, st, mode, in_match);
                            }
                        },
                        _ => {
                            let st = self.tys.intern(TyKind::Slice(elem));
                            self.pattern_mode(*mid, st, mode, in_match);
                        }
                    }
                }
            }
            Pat::Paren(inner) => self.pattern_mode(*inner, t, mode, in_match),
            // QPath returns above; macro patterns stay rejected
            // by the parser.
            Pat::QPath { .. } | Pat::MacroCall(_) => {}
        }
    }

    /// `Some(p)` is Some(true), `None` is Some(false), anything else is None.
    /// True when `path` is `<parent>::<last>` with the parent in a
    /// plain or canonical std spelling (`Option::Some`,
    /// `std::option::Option::Some`).
    fn std_parent_path(&self, path: &[ast::PathSeg], parent: Sym, last: Sym) -> bool {
        if path.len() < 2 || path[path.len() - 1].name != last {
            return false;
        }
        let head = &path[..path.len() - 1];
        if head.len() == 1 {
            return head[0].name == parent;
        }
        if head[head.len() - 1].name != parent {
            return false;
        }
        let names: Vec<&str> = head.iter().map(|s| self.p.interner.get(s.name)).collect();
        crate::ty::lang::std_path_kind(&names) == Some(crate::ty::lang::StdPathKind::Type)
    }

    fn option_pattern(&self, pat: PatId) -> Option<bool> {
        let k = &*self.p.known;
        match self.p.ast.pat(pat) {
            Pat::Binding { name, mutable: false, by_ref: false } if *name == k.None => Some(false),
            Pat::Path(segs) if self.std_parent_path(segs, k.Option, k.None) => Some(false),
            Pat::TupleStruct { path, elems }
                if elems.len() == 1 && ((path.len() == 1 && path[0].name == k.Some) || self.std_parent_path(path, k.Option, k.Some)) =>
            {
                Some(true)
            }
            _ => None,
        }
    }

    /// `Ok(..)` as `Some(true)`, `Err(..)` as `Some(false)`, in the
    /// prelude spelling and the qualified `Result::Ok(..)` spelling.
    fn result_pattern(&self, pat: PatId) -> Option<bool> {
        let k = &*self.p.known;
        match self.p.ast.pat(pat) {
            Pat::TupleStruct { path, elems } if elems.len() == 1 => {
                let last = path.last().map(|s| s.name)?;
                if (path.len() == 1 && last == k.Ok) || self.std_parent_path(path, k.Result, k.Ok) {
                    Some(true)
                } else if (path.len() == 1 && last == k.Err) || self.std_parent_path(path, k.Result, k.Err) {
                    Some(false)
                } else {
                    None
                }
            }
            _ => None,
        }
    }

    /// `std::collections::hash_map::Entry::Occupied(..)` as `Some(true)`,
    /// `..::Vacant(..)` as `Some(false)`: the canonical std path the
    /// resolver writes for these variants however they were imported
    /// (`use std::collections::hash_map::Entry;` then `Entry::Occupied`).
    fn entry_pattern(&self, pat: PatId) -> Option<bool> {
        let Pat::TupleStruct { path, elems } = self.p.ast.pat(pat) else { return None };
        if elems.len() != 1 {
            return None;
        }
        let names: Vec<&str> = path.iter().map(|s| self.p.interner.get(s.name)).collect();
        match names.as_slice() {
            ["std", "collections", "hash_map", "Entry", "Occupied"] => Some(true),
            ["std", "collections", "hash_map", "Entry", "Vacant"] => Some(false),
            _ => None,
        }
    }

    /// True when `pat` binds the payload of an `Entry::Occupied(x)` /
    /// `Entry::Vacant(x)` somewhere: a guard would need it by reference
    /// before the arm takes it by value, which lowering does not build.
    fn entry_payload_bound(&self, pat: PatId) -> bool {
        let p = self.p;
        match p.ast.pat(pat) {
            Pat::TupleStruct { elems, .. } if matches!(self.out.pat_res[(pat.0 - self.out.pat_base) as usize], PatRes::Entry(_)) => {
                elems.iter().any(|&e| !matches!(p.ast.pat(e), Pat::Wild))
            }
            Pat::TupleStruct { elems, .. } | Pat::Tuple(elems) | Pat::Or(elems) => elems.iter().any(|&e| self.entry_payload_bound(e)),
            Pat::Paren(inner) | Pat::At { inner, .. } | Pat::Ref { inner, .. } => self.entry_payload_bound(*inner),
            Pat::Struct { fields, .. } => fields.iter().any(|&(_, e)| self.entry_payload_bound(e)),
            _ => false,
        }
    }

    /// Types an `Entry::Occupied(x)` / `Entry::Vacant(x)` pattern: the
    /// scrutinee is a map Entry, and `x` binds the Entry as an
    /// `OccupiedEntry` / `VacantEntry` by value. Other payload patterns
    /// (`ref x`, a match through a reference) are outside the subset.
    fn entry_variant_pattern(&mut self, pat: PatId, occupied: bool, t: Ty, mode: BindMode, in_match: bool, span: Span) {
        use crate::ty::hash::{HashTy, mk_hash};
        let p = self.p;
        let pi = (pat.0 - self.out.pat_base) as usize;
        let (k, v) = (self.new_var(false), self.new_var(false));
        let et = mk_hash(&mut self.tys, HashTy::Entry, &[k, v]);
        if !self.unify(et, t) {
            self.mismatch(span, t, et);
            return;
        }
        self.out.pat_res[pi] = PatRes::Entry(occupied);
        let Pat::TupleStruct { elems, .. } = p.ast.pat(pat) else { return };
        let sub = elems[0];
        let plain = matches!(p.ast.pat(sub), Pat::Wild | Pat::Binding { by_ref: false, .. }) && matches!(mode, BindMode::Move);
        if !plain || self.out.pat_derefs[pi] > 0 {
            self.errs.push(unsupported(p.ast.pat_span(sub), "a map Entry variant matched through a reference or with this payload pattern"));
            return;
        }
        let payload = mk_hash(&mut self.tys, if occupied { HashTy::OccupiedEntry } else { HashTy::VacantEntry }, &[k, v]);
        self.pattern_mode(sub, payload, mode, in_match);
    }

    /// Exhaustiveness for `match`, by the usefulness check in
    /// `usefulness.rs`. Patterns it cannot read still make it
    /// reject a match that Rust accepts (lust is a subset).
    fn exhaustive(&mut self, scrut_ty: Ty, arms: &[ast::Arm], span: Span, behind_deref: bool) {
        let p = self.p;
        // A scrutinee of an uninhabited type needs no arm at all
        // (`match v {}` on an empty enum).
        let scrut_deep = self.deep(scrut_ty);
        if self.ty_uninhabited(scrut_deep, &[], 0) {
            return;
        }
        let pats: Vec<PatId> = arms.iter().filter(|a| a.guard.is_none()).map(|a| a.pat).collect();
        if self.covers_behind(&pats, behind_deref) {
            return;
        }
        let (_, base) = self.autoderef(scrut_ty);
        let msg = match self.tys.local_adt(base) {
            Some(a) if p.adt(a).is_enum => {
                let mut flat = Vec::new();
                pats.iter().for_each(|&x| self.flatten_or(x, &mut flat));
                let missing: Vec<String> = (0..p.adt(a).variants.len())
                    .filter(|&v| !flat.iter().any(|&x| matches!(self.pres(x), PatRes::Variant(_, w) if w as usize == v)))
                    .map(|v| format!("{}::{}", p.display_path(p.adt(a).name), self.name(p.adt(a).variants[v].name)))
                    .collect();
                if missing.is_empty() {
                    "non-exhaustive match: some nested cases are missing".to_string()
                } else {
                    format!("non-exhaustive match: missing {}", missing.join(", "))
                }
            }
            _ if self.kind(base) == TyKind::Error => return,
            _ => "non-exhaustive match".to_string(),
        };
        self.err("L0115", span, msg, "Add arms for the missing cases, or add a `_ => ...` arm.");
    }

    /// Follows `@`, parenthesized, and reference wrappers to the pattern they
    /// wrap. For exhaustiveness only: a reference wrapper adds no condition.
    fn pat_unwrap(&self, mut pat: PatId) -> PatId {
        loop {
            match self.p.ast.pat(pat) {
                Pat::At { inner, .. } | Pat::Paren(inner) | Pat::Ref { inner, .. } => pat = *inner,
                _ => return pat,
            }
        }
    }

    fn pres(&self, pat: PatId) -> PatRes {
        // An `@` or parenthesized wrapper takes the resolution of what it wraps
        // for exhaustiveness, when the wrapped pattern has a variant or
        // Option resolution of its own.
        let own = self.out.pat_res[(pat.0 - self.out.pat_base) as usize];
        match self.p.ast.pat(pat) {
            Pat::At { inner, .. } | Pat::Paren(inner) | Pat::Ref { inner, .. } => match self.pres(*inner) {
                r @ (PatRes::Variant(..) | PatRes::Opt(_) | PatRes::Res(_) | PatRes::Entry(_)) => r,
                _ => own,
            },
            _ => own,
        }
    }

    fn flatten_or(&self, pat: PatId, out: &mut Vec<PatId>) {
        match self.p.ast.pat(pat) {
            Pat::Or(alts) => alts.iter().for_each(|&a| self.flatten_or(a, out)),
            _ => out.push(pat),
        }
    }

    /// An order-preserving key for an integer or char scalar at type
    /// `t`: raw bits, with the sign bit flipped for signed types.
    fn scalar_key(&self, v: i128, t: Ty) -> Option<u128> {
        match self.kind(t) {
            TyKind::Int(it) => {
                let bits = if it.bits() >= 128 { v as u128 } else { (v as u128) & ((1u128 << it.bits()) - 1) };
                Some(if it.signed() { bits ^ (1u128 << (it.bits() - 1)) } else { bits })
            }
            TyKind::Char => Some(v as u32 as u128),
            _ => None,
        }
    }

    /// The scalar value a pattern matches as a single point, if it is one.
    fn pat_scalar(&self, pat: PatId) -> Option<i128> {
        let pi = (pat.0 - self.out.pat_base) as usize;
        if let Some(cv) = &self.out.pat_const[pi] {
            return match cv {
                crate::ty::consteval::ConstValue::Int(v) => Some(*v),
                crate::ty::consteval::ConstValue::Char(c) => Some(*c as i128),
                _ => None,
            };
        }
        let item = match self.out.pat_res[pi] {
            PatRes::ConstItem(idx) => Some(&self.p.consts[idx as usize].value),
            PatRes::BodyConst(idx) => Some(&self.p.body_consts[idx as usize].value),
            _ => None,
        };
        if let Some(cv) = item {
            return match cv {
                crate::ty::consteval::ConstValue::Int(v) => Some(*v),
                crate::ty::consteval::ConstValue::Char(c) => Some(*c as i128),
                _ => None,
            };
        }
        match self.p.ast.pat(self.pat_unwrap(pat)) {
            Pat::Lit(l) => self.const_scalar(*l),
            _ => None,
        }
    }

    /// True when a checked pattern matches every value of its
    /// type: the syntactic `irrefutable` test, or the
    /// exhaustiveness test (`A(x) | B(x)` over a two-variant
    /// enum, a range over the whole type, and `Ok(x)` over
    /// `Result<_, Void>` always match, as in Rust).
    fn pat_always_matches(&self, pat: PatId) -> bool {
        self.pat_always_matches_at(pat, false)
    }

    /// `pat_always_matches` for a pattern matched on a place
    /// behind a dereference (`let Ok(x) = *r`), where empty
    /// constructors do not count.
    fn pat_always_matches_at(&self, pat: PatId, behind_deref: bool) -> bool {
        if self.irrefutable(pat) {
            return true;
        }
        self.covers_behind(&[pat], behind_deref)
    }

    /// True when a place expression reads through a dereference
    /// (`*r`, `(*r).f`, `(*r)[0]`), so its matched place sits
    /// behind that dereference.
    fn place_behind_deref(&self, e: ExprId) -> bool {
        match self.p.ast.expr(e) {
            Expr::Deref(_) => true,
            Expr::Field { base, .. } | Expr::TupleField { base, .. } | Expr::Index { base, .. } => self.place_behind_deref(*base),
            _ => false,
        }
    }

    /// True when a guarded arm's pattern binds a slice
    /// middle by value (an owned array) whose elements are not
    /// `Copy`, or also binds through an or-pattern: those arms
    /// bind before the guard runs, so drop order (and guard
    /// retry) would differ from Rust. See the call in the
    /// `match` check.
    fn slice_middle_move_blocks_guard(&self, root: PatId) -> bool {
        fn has_binding(cx: &Ctx, pat: PatId) -> bool {
            matches!(cx.out.pat_res[(pat.0 - cx.out.pat_base) as usize], PatRes::Binding { .. })
                || children(cx, pat).into_iter().any(|s| has_binding(cx, s))
        }
        fn has_or_binding(cx: &Ctx, pat: PatId) -> bool {
            (matches!(cx.p.ast.pat(pat), Pat::Or(_)) && has_binding(cx, pat))
                || children(cx, pat).into_iter().any(|s| has_or_binding(cx, s))
        }
        fn children(cx: &Ctx, pat: PatId) -> Vec<PatId> {
            match cx.p.ast.pat(pat) {
                Pat::TupleStruct { elems, .. } | Pat::Tuple(elems) | Pat::Or(elems) => elems.clone(),
                Pat::Struct { fields, .. } => fields.iter().map(|&(_, s)| s).collect(),
                Pat::Slice { prefix, middle, suffix } => {
                    let mut out: Vec<PatId> = prefix.clone();
                    if let Some(m) = middle {
                        out.push(*m);
                    }
                    out.extend(suffix.iter().copied());
                    out
                }
                Pat::Paren(i) | Pat::Ref { inner: i, .. } | Pat::At { inner: i, .. } => vec![*i],
                _ => Vec::new(),
            }
        }
        fn walk(cx: &Ctx, root: PatId, pat: PatId) -> bool {
            if let Pat::Slice { middle, .. } = cx.p.ast.pat(pat)
                && let Some(mid) = middle
                && has_binding(cx, *mid)
                && let TyKind::Array(elem, _) = cx.kind(cx.out.pat_ty[(mid.0 - cx.out.pat_base) as usize])
                && (!is_copy(cx.p, &cx.tys, elem) || has_or_binding(cx, root))
            {
                return true;
            }
            children(cx, pat).into_iter().any(|s| walk(cx, root, s))
        }
        walk(self, root, root)
    }

    fn irrefutable(&self, pat: PatId) -> bool {
        let p = self.p;
        // A struct, or an enum with one variant (rustc: exhaustive).
        let one_variant = |a: AdtId| !p.adt(a).is_enum || p.adt(a).variants.len() == 1;
        if matches!(self.out.pat_res[(pat.0 - self.out.pat_base) as usize], PatRes::Opt(_) | PatRes::Res(_) | PatRes::Entry(_)) {
            return false;
        }
        match p.ast.pat(pat) {
            Pat::Wild => true,
            // A binding that resolved to a const item can fail; one
            // that resolved to a unit struct cannot.
            Pat::Binding { .. } => match self.out.pat_res[(pat.0 - self.out.pat_base) as usize] {
                PatRes::Variant(a, _) => one_variant(a),
                PatRes::Binding { .. } | PatRes::None => self.out.pat_const[(pat.0 - self.out.pat_base) as usize].is_none(),
                _ => false,
            },
            Pat::Or(alts) => alts.iter().any(|&a| self.irrefutable(a)),
            Pat::Struct { fields, .. } => {
                matches!(self.out.pat_res[(pat.0 - self.out.pat_base) as usize], PatRes::Variant(a, _) if one_variant(a))
                    && fields.iter().all(|&(_, s)| self.irrefutable(s))
            }
            Pat::TupleStruct { elems, .. } => {
                matches!(self.out.pat_res[(pat.0 - self.out.pat_base) as usize], PatRes::Variant(a, _) if one_variant(a))
                    && elems.iter().all(|&s| self.irrefutable(s))
            }
            Pat::Path(_) | Pat::QPath { .. } => {
                self.out.pat_const[(pat.0 - self.out.pat_base) as usize].is_none()
                    && !matches!(self.out.pat_res[(pat.0 - self.out.pat_base) as usize], PatRes::ConstItem(_) | PatRes::BodyConst(_))
                    && matches!(self.out.pat_res[(pat.0 - self.out.pat_base) as usize], PatRes::Variant(a, _) if one_variant(a))
            }
            Pat::Tuple(elems) => elems.iter().all(|&s| matches!(p.ast.pat(s), Pat::Rest) || self.irrefutable(s)),
            Pat::Ref { inner, .. } => self.irrefutable(*inner),
            Pat::At { inner, .. } => self.irrefutable(*inner),
            Pat::Slice { prefix, middle, suffix } => {
                // The pattern matches every value only if it matches every
                // length: an array needs an exact-length pattern, or a `..`
                // with at most the array's length fixed; a slice needs a
                // lone `..` (`[]` matches only the empty slice, and
                // `[.., a]` misses it too).
                let t = self.out.pat_ty[(pat.0 - self.out.pat_base) as usize];
                let fixed = (prefix.len() + suffix.len()) as u128;
                let len_ok = match self.kind(t) {
                    TyKind::Array(_, c) => match self.tys.const_kind(c) {
                        ConstKind::Int(n) => {
                            if middle.is_some() {
                                fixed <= n
                            } else {
                                fixed == n
                            }
                        }
                        _ => false,
                    },
                    _ => middle.is_some() && fixed == 0,
                };
                len_ok
                    && middle.is_none_or(|m| matches!(p.ast.pat(m), Pat::Rest) || self.irrefutable(m))
                    && prefix.iter().chain(suffix.iter()).all(|&s| self.irrefutable(s))
            }
            Pat::Paren(inner) => self.irrefutable(*inner),
            Pat::Rest => true,
            _ => false,
        }
    }

    // ---------- Known-value overflow lint (rustc `arithmetic_overflow`) ----------

    /// The deny-level lints rustc runs over known values, mirrored from
    /// its MIR const-prop behavior (probed against rustc): an arithmetic
    /// operation on operands known at compile time that would overflow
    /// is an error (`arithmetic_overflow`, L0540), and so is an
    /// operation that always panics: division or remainder by a known
    /// zero, `MIN / -1`, and an index known to be out of bounds for an
    /// array type (`unconditional_panic`, L0541). The pass walks the
    /// checked body once, tracking scalar locals whose value is known.
    /// The tracked set follows the probed rules: a local whose address
    /// is taken anywhere is never tracked, knowledge does not survive a
    /// control-flow join for locals assigned on either side, a write
    /// through a field or index place drops the whole aggregate, reads
    /// through references and enum payloads are unknown, and a local
    /// assigned more than once is only known until the next MIR
    /// terminator (see `KLint`). A store back into the local it reads
    /// (`a = a + 1`, `a += 1`) fires like any other operation, but only
    /// inside that block. The lint never runs on a monomorphized
    /// instance: rustc runs it before mono, so a value that only a
    /// substitution makes known (a const param, an associated const)
    /// must not reject the build.
    fn overflow_lint(&mut self) {
        if matches!(self.p.gx.fn_class.get(self.fid.0 as usize), Some(generics::FnClass::Instance)) {
            return;
        }
        let p = self.p;
        let allow_arith = self.f.def(&self.p.ast).attrs.iter().any(|a| crate::check::allow_attr(a, &p.interner, "arithmetic_overflow"));
        let allow_panic = self.f.def(&self.p.ast).attrs.iter().any(|a| crate::check::allow_attr(a, &p.interner, "unconditional_panic"));
        if allow_arith && allow_panic {
            return;
        }
        let Some(body) = self.f.def(&self.p.ast).body else { return };
        // A local is multiply assigned when an explicit store lands on a
        // local a pattern already gave a value (a parameter, a `let`
        // with an initializer), or two explicit stores land on it (a
        // deferred `let a; a = ..; a = ..;`).
        let n_locals = self.out.locals.len();
        let mut multi = vec![false; n_locals];
        {
            let mut stores = vec![0u32; n_locals];
            let mut bound = vec![false; n_locals];
            let mut blocks: Vec<ast::BlockId> = vec![body];
            for pr in &self.out.pat_res {
                if let PatRes::Binding { local, .. } = pr {
                    bound[*local as usize] = true;
                }
            }
            for &pl in &self.out.param_locals {
                bound[pl as usize] = true;
            }
            for i in 0..self.out.expr_ty.len() {
                let e = ExprId(self.out.expr_base + i as u32);
                match p.ast.expr(e) {
                    Expr::Assign { lhs, .. } | Expr::AssignOp { lhs, .. } => {
                        let mut roots = Vec::new();
                        self.k_lhs_roots(*lhs, &mut roots);
                        for r in roots {
                            stores[r as usize] += 1;
                        }
                    }
                    Expr::Block(b) | Expr::UnsafeBlock(b) => blocks.push(*b),
                    Expr::LabeledBlock { body: b, .. } => blocks.push(*b),
                    Expr::If { then, .. } => blocks.push(*then),
                    Expr::While { body: b, .. } | Expr::Loop { body: b, .. } | Expr::For { body: b, .. } => blocks.push(*b),
                    _ => {}
                }
            }
            // A `let a;` without an initializer gives no value, so its
            // first explicit store is the local's only assignment.
            let mut deferred = vec![false; n_locals];
            for b in blocks {
                for stmt in &p.ast.block(b).stmts {
                    if let Stmt::Let { pat, init: None, .. } = stmt {
                        let mut locals = Vec::new();
                        self.k_pat_locals(*pat, &mut locals);
                        for l in locals {
                            deferred[l as usize] = true;
                        }
                    }
                }
            }
            for l in 0..n_locals {
                multi[l] = stores[l] >= 2 || (stores[l] == 1 && bound[l] && !deferred[l]);
            }
        }
        let mut lint = KLint {
            addressed: vec![false; self.out.locals.len()],
            multi,
            frames: Vec::new(),
            dead: false,
            allow_arith,
            allow_panic,
            stmt_allow_arith: 0,
            stmt_allow_panic: 0,
        };
        // A local whose address is taken anywhere in the body is not tracked.
        for i in 0..self.out.expr_ty.len() {
            let e = ExprId(self.out.expr_base + i as u32);
            match p.ast.expr(e) {
                Expr::Ref { expr, .. } => {
                    if let Some(root) = self.k_place_root(*expr) {
                        lint.addressed[root as usize] = true;
                    }
                }
                Expr::MethodCall { recv, .. } => {
                    let res = self.out.expr_res[i];
                    let ar = match res {
                        Res::Method { autoref, .. } | Res::BuiltinMethod { autoref, .. } => autoref,
                        _ => Autoref::None,
                    };
                    if ar != Autoref::None
                        && let Some(root) = self.k_place_root(*recv)
                    {
                        lint.addressed[root as usize] = true;
                    }
                }
                Expr::Macro { kind, args, .. } => {
                    // Format arguments are borrowed (as in `macro_expr`).
                    let borrowed: &[ExprId] = match kind {
                        ast::MacroKind::AssertEq | ast::MacroKind::AssertNe => &args[..args.len().min(2)],
                        ast::MacroKind::Vec | ast::MacroKind::Assert => &[],
                        _ => args,
                    };
                    for &a in borrowed {
                        if matches!(p.ast.expr(a), Expr::Path(_) | Expr::Field { .. } | Expr::TupleField { .. } | Expr::Index { .. })
                            && let Some(root) = self.k_place_root(a)
                        {
                            lint.addressed[root as usize] = true;
                        }
                    }
                }
                _ => {}
            }
        }
        // A captured variable can change behind the closure: do not track it.
        for c in &self.out.closures {
            for cap in &c.captures {
                lint.addressed[cap.root as usize] = true;
            }
        }
        let mut env: KEnv = vec![None; self.out.locals.len()];
        self.k_block(body, &mut env, &mut lint);
        // Each closure body is its own MIR body in rustc: lint it with
        // nothing known on entry.
        let bodies: Vec<ExprId> = self
            .out
            .closures
            .iter()
            .filter_map(|c| match p.ast.expr(c.expr) {
                Expr::Closure { body, .. } => Some(*body),
                _ => None,
            })
            .collect();
        for b in bodies {
            let mut env: KEnv = vec![None; self.out.locals.len()];
            lint.frames.clear();
            lint.dead = false;
            self.k_expr(b, &mut env, &mut lint);
        }
    }

    /// Zonks the closure records into `Checked`. A closure stored inside
    /// an Adt (a struct field, `Option`, `Vec`) holds its captures' loans
    /// through the Adt's type args, which the borrow checker tracks
    /// (W-BORROW closure contract), as it does a closure that returns a
    /// reference.
    fn finish_closures(&mut self) {
        for mut c in std::mem::take(&mut self.closures) {
            // A signature nothing fixed is an annotation error (rustc
            // E0282), never a silent default.
            if c.inputs.iter().chain([&c.output]).any(|&t| self.has_unbound_var(t) && !self.has_error_kind(t)) {
                let span = self.span(c.expr);
                self.err(
                    "L0610",
                    span,
                    "type annotations needed: cannot infer the closure's signature",
                    "Annotate the closure parameters, or use the closure where an Fn bound fixes them.",
                );
            }
            c.output = self.zonk(c.output);
            for t in c.inputs.iter_mut() {
                *t = self.zonk(*t);
            }
            for cap in c.captures.iter_mut() {
                cap.place_ty = self.zonk(cap.place_ty);
            }
            c.ty = self.zonk(c.ty);
            c.bound_output = c.bound_output.map(|t| self.zonk(t));
            self.out.closures.push(c);
        }
    }

    /// Ends the current MIR basic block for lint purposes: every
    /// multiply-assigned local stops being known (see `KLint`).
    fn k_break(env: &mut KEnv, lint: &KLint) {
        for (i, m) in lint.multi.iter().enumerate() {
            if *m {
                env[i] = None;
            }
        }
    }

    /// Collects the root locals an assignment target stores into,
    /// walking a destructuring target's places.
    fn k_lhs_roots(&self, e: ExprId, out: &mut Vec<u32>) {
        match self.p.ast.expr(e) {
            Expr::Tuple(elems) | Expr::Array(elems) => {
                for &el in elems {
                    self.k_lhs_roots(el, out);
                }
            }
            Expr::StructLit { fields, .. } => {
                for &(_, _, fe) in fields {
                    self.k_lhs_roots(fe, out);
                }
            }
            _ => {
                if let Some(r) = self.k_place_root(e) {
                    out.push(r);
                }
            }
        }
    }

    /// Collects the binding locals under a pattern.
    fn k_pat_locals(&self, pat: PatId, out: &mut Vec<u32>) {
        let p = self.p;
        if let PatRes::Binding { local, .. } = self.out.pat_res[(pat.0 - self.out.pat_base) as usize] {
            out.push(local);
        }
        match p.ast.pat(pat) {
            Pat::At { inner, .. } | Pat::Ref { inner, .. } | Pat::Paren(inner) => self.k_pat_locals(*inner, out),
            Pat::Tuple(elems) | Pat::TupleStruct { elems, .. } | Pat::Or(elems) => {
                for &s in elems {
                    self.k_pat_locals(s, out);
                }
            }
            Pat::Struct { fields, .. } => {
                for &(_, s) in fields {
                    self.k_pat_locals(s, out);
                }
            }
            Pat::Slice { prefix, middle, suffix } => {
                for &s in prefix.iter().chain(suffix.iter()) {
                    self.k_pat_locals(s, out);
                }
                if let Some(m) = middle {
                    self.k_pat_locals(*m, out);
                }
            }
            _ => {}
        }
    }

    /// Fires the arithmetic-overflow lint for `a op b` at integer type
    /// `t` when both operands are known and the result does not fit.
    fn k_check_arith(&mut self, op: BinOp, a: i128, b: i128, t: Ty, span: Span, lint: &KLint) {
        if self.k_is_u128(t) {
            let (au, bu) = (a as u128, b as u128);
            let r = match op {
                BinOp::Add => au.checked_add(bu),
                BinOp::Sub => au.checked_sub(bu),
                _ => au.checked_mul(bu),
            };
            if r.is_none() {
                self.k_fire(span, lint);
            }
            return;
        }
        let Some((_, lo, hi)) = self.k_range(t) else { return };
        let (Some(a), Some(b)) = (self.k_math(a, t), self.k_math(b, t)) else { return };
        let r = match op {
            BinOp::Add => a.checked_add(b),
            BinOp::Sub => a.checked_sub(b),
            _ => a.checked_mul(b),
        };
        if !matches!(r, Some(r) if (lo..=hi).contains(&r)) {
            self.k_fire(span, lint);
        }
    }

    /// The root local of a place expression, if the place is one.
    fn k_place_root(&self, e: ExprId) -> Option<u32> {
        match self.out.expr_res[self.ei(e)] {
            Res::Local(l) => return Some(l),
            _ => {}
        }
        match self.p.ast.expr(e) {
            Expr::Field { base, .. } | Expr::TupleField { base, .. } | Expr::Index { base, .. } => self.k_place_root(*base),
            _ => None,
        }
    }

    /// True when `t` is the `u128` type, whose known values are bit
    /// patterns rather than mathematical i128 values.
    fn k_is_u128(&self, t: Ty) -> bool {
        matches!(self.tys.kind(t), TyKind::Int(it) if !it.signed() && it.bits() >= 128)
    }

    /// The bit width of an integer type, when `t` is one.
    fn k_bits(&self, t: Ty) -> Option<u32> {
        match self.tys.kind(t) {
            TyKind::Int(it) => Some(it.bits()),
            _ => None,
        }
    }

    /// Orders two known values at integer type `t` (in the u128 domain
    /// for `u128`, where the stored i128 is only the bit pattern).
    fn k_cmp(&self, a: i128, b: i128, t: Ty) -> std::cmp::Ordering {
        if self.k_is_u128(t) { (a as u128).cmp(&(b as u128)) } else { a.cmp(&b) }
    }

    /// The mathematical value of an i128 seen at integer type `t`. For
    /// `u128` the bits pass through unchanged (see `KVal`).
    fn k_math(&self, v: i128, t: Ty) -> Option<i128> {
        match self.tys.kind(t) {
            TyKind::Int(it) => {
                let bits = it.bits();
                if it.signed() {
                    Some(crate::ty::consteval::truncate_to_int(v, it))
                } else if bits >= 128 {
                    Some(v)
                } else {
                    Some(v & ((1i128 << bits) - 1))
                }
            }
            _ => Some(v),
        }
    }

    /// Wraps an i128 to the range of its integer type (loss is intended:
    /// the value continues as the wrapped result, as in a wrapping op).
    fn k_wrap(&self, v: i128, t: Ty) -> Option<i128> {
        self.k_math(v, t)
    }

    /// The discriminant of a known enum variant, for an `as` cast. It
    /// records the enum's layout read: a discriminant edit changes the
    /// lint's answer for this body.
    fn k_discriminant(&mut self, a: AdtId, v: u32) -> i128 {
        let p = self.p;
        if p.resolved.is_some()
            && let Some(def) = p.defs.def_of_adt(a)
        {
            let _ = p.layout_of(&mut self.out.reads, def);
        }
        p.adt(a).variants[v as usize].disc
    }

    /// The value range of an integer type, when it fits in i128 values.
    fn k_range(&self, t: Ty) -> Option<(IntTy, i128, i128)> {
        match self.tys.kind(t) {
            TyKind::Int(it) => {
                let bits = it.bits();
                if bits >= 128 {
                    if it.signed() { Some((it, i128::MIN, i128::MAX)) } else { None }
                } else if it.signed() {
                    Some((it, -(1i128 << (bits - 1)), (1i128 << (bits - 1)) - 1))
                } else {
                    Some((it, 0, (1i128 << bits) - 1))
                }
            }
            _ => None,
        }
    }

    fn k_fire(&mut self, span: Span, lint: &KLint) {
        if lint.allow_arith || lint.stmt_allow_arith > 0 {
            return;
        }
        self.err(
            "L0540",
            span,
            "this arithmetic operation will overflow",
            "Change the values or the type. If the wrap is intended, use a `wrapping_*` operation.",
        );
    }

    /// The `unconditional_panic` fire: an operation on known values
    /// that always panics when it runs.
    fn k_fire_panic(&mut self, span: Span, lint: &KLint, what: &str, fix: &'static str) {
        if lint.allow_panic || lint.stmt_allow_panic > 0 {
            return;
        }
        self.err("L0541", span, format!("{what}: this operation will panic at runtime"), fix);
    }

    /// Reports an out-of-bounds index when the base expression has an
    /// array type (through any number of references) and the index
    /// value is known. Slice and `Vec` bases keep a runtime length
    /// rustc does not const-propagate, so they never fire here.
    fn k_check_index(&mut self, e: ExprId, base: ExprId, iv: &Option<KVal>, span: Span, lint: &KLint) {
        let Some(KVal::Int(i)) = iv else { return };
        // The indexed place autoderefs as check's `Expr::Index` did:
        // references, Box/Rc/Arc/Ref, then any user `Deref` steps it
        // recorded on `e`. A known array length is rustc's `Len`.
        let (_, mut t) = self.autoderef_smart(self.out.expr_ty[self.ei(base)]);
        if !matches!(self.tys.kind(t), TyKind::Array(..))
            && let Some((_, d)) = self.out.deref_recv.iter().rev().find(|(x, _)| *x == e)
        {
            t = self.autoderef_smart(d.target_ref).1;
        }
        let TyKind::Array(_, c) = self.tys.kind(t) else { return };
        let crate::ty::ConstKind::Int(len) = self.tys.const_kind(c) else { return };
        if *i < 0 || *i as u128 >= len {
            self.k_fire_panic(span, lint, "index out of bounds", "Change the index or the array length.");
        }
    }

    /// Places whose writes change a tracked local, found by span within
    /// the given regions (a loop body and its condition).
    fn k_assigned_in(&self, regions: &[Span]) -> Vec<u32> {
        let mut out = Vec::new();
        for i in 0..self.out.expr_ty.len() {
            let e = ExprId(self.out.expr_base + i as u32);
            let lhs = match self.p.ast.expr(e) {
                Expr::Assign { lhs, .. } | Expr::AssignOp { lhs, .. } => *lhs,
                _ => continue,
            };
            let sp = self.p.ast.expr_span(e);
            if regions.iter().any(|r| r.file == sp.file && r.lo <= sp.lo && sp.hi <= r.hi)
                && let Some(root) = self.k_place_root(lhs)
                && !out.contains(&root)
            {
                out.push(root);
            }
        }
        out
    }

    /// Records a value for a local, unless its address is taken.
    fn k_set(env: &mut KEnv, lint: &KLint, local: u32, v: Option<KVal>) {
        if !lint.addressed.get(local as usize).copied().unwrap_or(false) {
            env[local as usize] = v;
        }
    }

    /// Drops the knowledge of every local assigned in the given regions:
    /// after a control-flow join, a local assigned on any side is no
    /// longer known, even if all sides assign the same value.
    fn k_poison(&self, env: &mut KEnv, regions: &[Span]) {
        for r in self.k_assigned_in(regions) {
            env[r as usize] = None;
        }
    }

    /// True when a block cannot complete: a statement or its tail has
    /// type `!` (a return, a panic, a diverging call, a break).
    fn k_block_diverges(&self, b: ast::BlockId) -> bool {
        let block = self.p.ast.block(b);
        let never = |e: ExprId| self.tys.kind(self.out.expr_ty[self.ei(e)]) == TyKind::Never;
        block.stmts.iter().any(|s| match s {
            Stmt::Expr { expr, .. } => never(*expr),
            Stmt::Let { init, .. } => init.is_some_and(|i| never(i)),
            _ => false,
        }) || block.tail.is_some_and(never)
    }

    /// Binds the known value of a scrutinee into a pattern's locals.
    /// Tuple and struct projections keep their component values; enum
    /// payload bindings are unknown (the probed rustc behavior).
    fn k_bind_pat(&mut self, pat: PatId, v: &Option<KVal>, env: &mut KEnv, lint: &KLint) {
        let p = self.p;
        let pres = self.out.pat_res[(pat.0 - self.out.pat_base) as usize];
        match p.ast.pat(pat) {
            Pat::Binding { .. } => {
                if let PatRes::Binding { local, mode } = pres {
                    let val = if mode == BindMode::Move { v.clone() } else { None };
                    Self::k_set(env, lint, local, val);
                }
            }
            Pat::At { inner, .. } => {
                if let PatRes::Binding { local, mode } = pres {
                    let val = if mode == BindMode::Move { v.clone() } else { None };
                    Self::k_set(env, lint, local, val);
                }
                self.k_bind_pat(*inner, v, env, lint);
            }
            Pat::Tuple(elems) => {
                if let Some(KVal::Agg(items)) = v
                    && let Some(map) = map_tuple_elems(&p.ast, elems, items.len())
                {
                    for (idx, sub) in map {
                        self.k_bind_pat(sub, &items[idx].clone(), env, lint);
                    }
                } else {
                    for &sub in elems {
                        self.k_bind_pat(sub, &None, env, lint);
                    }
                }
            }
            Pat::TupleStruct { elems, .. } => {
                let struct_val = match pres {
                    PatRes::Variant(a, _) if !p.adt(a).is_enum => v.clone(),
                    _ => None,
                };
                match &struct_val {
                    Some(KVal::Agg(items)) => match map_tuple_elems(&p.ast, elems, items.len()) {
                        Some(map) => {
                            for (idx, sub) in map {
                                self.k_bind_pat(sub, &items[idx].clone(), env, lint);
                            }
                        }
                        None => {
                            for &sub in elems {
                                self.k_bind_pat(sub, &None, env, lint);
                            }
                        }
                    },
                    _ => {
                        for &sub in elems {
                            self.k_bind_pat(sub, &None, env, lint);
                        }
                    }
                }
            }
            Pat::Struct { fields, .. } => {
                let struct_fields = match pres {
                    PatRes::Variant(a, var) if !p.adt(a).is_enum => {
                        Some(p.adt(a).variants[var as usize].fields.iter().map(|f| f.name).collect::<Vec<_>>())
                    }
                    _ => None,
                };
                for &(fname, sub) in fields {
                    let slot = match (v, &struct_fields) {
                        (Some(KVal::Agg(items)), Some(names)) => {
                            names.iter().position(|&n| n == fname).and_then(|i| items.get(i)).cloned().unwrap_or(None)
                        }
                        _ => None,
                    };
                    self.k_bind_pat(sub, &slot, env, lint);
                }
            }
            Pat::Slice { prefix, suffix, .. } => match v {
                Some(KVal::Agg(items)) if items.len() >= prefix.len() + suffix.len() => {
                    for (i, &sub) in prefix.iter().enumerate() {
                        self.k_bind_pat(sub, &items[i].clone(), env, lint);
                    }
                    for (j, &sub) in suffix.iter().enumerate() {
                        self.k_bind_pat(sub, &items[items.len() - suffix.len() + j].clone(), env, lint);
                    }
                }
                _ => {
                    for &sub in prefix.iter().chain(suffix.iter()) {
                        self.k_bind_pat(sub, &None, env, lint);
                    }
                }
            },
            Pat::Or(alts) => {
                // A binding is known after an or-pattern only
                // when every alternative binds it to the same
                // known value; the matched alternative is the
                // only one that runs.
                let mut merged: Option<KEnv> = None;
                for &a in alts {
                    let mut alt_env = env.clone();
                    self.k_bind_pat(a, v, &mut alt_env, lint);
                    match &mut merged {
                        None => merged = Some(alt_env),
                        Some(m) => {
                            for (slot, other) in m.iter_mut().zip(alt_env) {
                                if *slot != other {
                                    *slot = None;
                                }
                            }
                        }
                    }
                }
                if let Some(m) = merged {
                    *env = m;
                }
            }
            Pat::Ref { inner, .. } | Pat::Paren(inner) => self.k_bind_pat(*inner, &None, env, lint),
            _ => {}
        }
    }

    /// Pushes statement-level `#[allow(..)]` counters for `attrs`;
    /// returns which counters rose, for `k_allow_pop`.
    fn k_allow_push(&self, attrs: &[ast::Attr], lint: &mut KLint) -> (bool, bool) {
        let arith = attrs.iter().any(|a| crate::check::allow_attr(a, &self.p.interner, "arithmetic_overflow"));
        let panic_ = attrs.iter().any(|a| crate::check::allow_attr(a, &self.p.interner, "unconditional_panic"));
        lint.stmt_allow_arith += u32::from(arith);
        lint.stmt_allow_panic += u32::from(panic_);
        (arith, panic_)
    }

    fn k_allow_pop(&self, pushed: (bool, bool), lint: &mut KLint) {
        lint.stmt_allow_arith -= u32::from(pushed.0);
        lint.stmt_allow_panic -= u32::from(pushed.1);
    }

    fn k_block(&mut self, b: ast::BlockId, env: &mut KEnv, lint: &mut KLint) -> Option<KVal> {
        // A block-level `#![allow(..)]` covers the whole block.
        let pushed = self.k_allow_push(&self.p.ast.block(b).inner_attrs.clone(), lint);
        let v = self.k_block_body(b, env, lint);
        self.k_allow_pop(pushed, lint);
        v
    }

    fn k_block_body(&mut self, b: ast::BlockId, env: &mut KEnv, lint: &mut KLint) -> Option<KVal> {
        let p = self.p;
        if lint.dead {
            return None;
        }
        let block = p.ast.block(b);
        for stmt in &block.stmts {
            if lint.dead {
                return None;
            }
            let diverges = match stmt {
                Stmt::Let { pat, init, els, attrs, .. } => {
                    // A statement-level `#[allow(..)]` covers this let.
                    let pushed = self.k_allow_push(attrs, lint);
                    let v = init.map(|i| self.k_expr(i, env, lint)).unwrap_or(None);
                    self.k_bind_pat(*pat, &v, env, lint);
                    if let Some(els) = els {
                        let mut eenv = env.clone();
                        self.k_block(*els, &mut eenv, lint);
                    }
                    self.k_allow_pop(pushed, lint);
                    init.is_some_and(|i| self.tys.kind(self.out.expr_ty[self.ei(i)]) == TyKind::Never)
                }
                Stmt::Expr { expr, attrs, .. } => {
                    // A statement-level `#[allow(..)]` covers this expr.
                    let pushed = self.k_allow_push(attrs, lint);
                    self.k_expr(*expr, env, lint);
                    self.k_allow_pop(pushed, lint);
                    self.tys.kind(self.out.expr_ty[self.ei(*expr)]) == TyKind::Never
                }
                Stmt::Item(_) | Stmt::Macro { .. } => false,
            };
            if diverges {
                return None;
            }
        }
        if lint.dead {
            return None;
        }
        match block.tail {
            Some(tail) => {
                // An outer `#[allow(..)]` on the tail covers it.
                let pushed = self.k_allow_push(&block.tail_attrs.clone(), lint);
                let v = self.k_expr(tail, env, lint);
                self.k_allow_pop(pushed, lint);
                v
            }
            None => None,
        }
    }

    /// A recorded const value as a known value, if it is scalar or an
    /// aggregate of knowns.
    fn k_const(&self, cv: &crate::ty::consteval::ConstValue, t: Ty) -> Option<KVal> {
        use crate::ty::consteval::ConstValue as CV;
        match cv {
            CV::Int(v) => self.k_math(*v, t).map(KVal::Int),
            CV::Bool(b) => Some(KVal::Bool(*b)),
            CV::Char(c) => Some(KVal::Int(*c as i128)),
            CV::Float(b, f) => Some(KVal::Float(*b, *f)),
            CV::Variant(v, _) => match self.tys.kind(t) {
                TyKind::Adt(def, _) => match self.p.adt_by_def(def) {
                    Some(a) if self.p.adt(a).is_enum => Some(KVal::Enum(a, *v)),
                    _ => None,
                },
                _ => None,
            },
            CV::Aggregate(vals) => Some(KVal::Agg(vals.iter().map(|v| self.k_const(v, ERROR)).collect())),
            _ => None,
        }
    }

    /// Walks one expression, lints overflowing operations with known
    /// operands, applies assignment effects to `env`, and returns the
    /// expression's known value when there is one.
    /// True when a `size_of`/`align_of`/`needs_drop` callee's baked
    /// answer is the template placeholder (its type argument names
    /// a parameter of this template): the value is not known here.
    /// True when a layout query over this body's params answers a
    /// placeholder: a template check, or a const initializer body (a
    /// generic associated const's value comes per instance from
    /// `assoc_eval`). Neither body is ever generated.
    fn layout_placeholders(&self) -> bool {
        self.is_template_check() || self.f.loc.is_const_init()
    }

    fn k_query_placeholder(&mut self, callee: ExprId) -> bool {
        if !self.layout_placeholders() {
            return false;
        }
        let arg = match self.p.ast.expr(callee) {
            ast::Expr::Path(segs) => segs.last().and_then(|s| s.type_args().first().copied()),
            _ => None,
        };
        let Some(arg) = arg else { return false };
        let t = self.resolve_written(arg);
        self.tys.flags(t).contains_param()
    }

    fn k_expr(&mut self, e: ExprId, env: &mut KEnv, lint: &mut KLint) -> Option<KVal> {
        let p = self.p;
        let span = self.span(e);
        let ety = self.out.expr_ty[self.ei(e)];
        if let Some(cv) = &self.out.const_exprs[self.ei(e)] {
            return self.k_const(cv, ety);
        }
        match p.ast.expr(e) {
            Expr::Int(v, _) => Some(KVal::Int(*v as u128 as i128)),
            Expr::Bool(b) => Some(KVal::Bool(*b)),
            Expr::Char(c) => Some(KVal::Int(*c as i128)),
            Expr::Float(i) => match self.tys.kind(ety) {
                TyKind::Float(f) => crate::check::collect::parse_float_literal_as(&p.ast.strings[*i as usize], f).map(|b| KVal::Float(b, f)),
                _ => None,
            },
            Expr::Path(_) | Expr::SelfValue => match self.out.expr_res[self.ei(e)] {
                Res::Local(l) => env.get(l as usize).cloned().unwrap_or(None),
                Res::Variant(a, v) if p.adt(a).is_enum => Some(KVal::Enum(a, v)),
                _ => None,
            },
            Expr::Block(b) | Expr::UnsafeBlock(b) => self.k_block(*b, env, lint),
            Expr::ConstBlock(_) => None,
            Expr::LabeledBlock { label, body } => {
                lint.frames.push((Some(label.name), Vec::new()));
                let v = self.k_block(*body, env, lint);
                let (_, breaks) = lint.frames.pop().unwrap();
                match (breaks.len(), v) {
                    (0, v) => v,
                    (1, None) => breaks.into_iter().next().unwrap(),
                    _ => None,
                }
            }
            Expr::If { cond, then, els } => {
                let cv = self.k_expr(*cond, env, lint);
                let then_span = p.ast.block(*then).span;
                let els_span = els.map(|x| self.span(x));
                if let Some(KVal::Bool(b)) = cv {
                    // Only the taken side runs (dead-side operations do not
                    // fire); locals it assigns are still lost at the join,
                    // and if it diverges, what follows is unreachable.
                    let saved = lint.dead;
                    lint.dead = false;
                    Self::k_break(env, lint);
                    let side_span = if b {
                        self.k_block(*then, env, lint);
                        then_span
                    } else {
                        match els {
                            Some(els) => {
                                self.k_expr(*els, env, lint);
                                self.span(*els)
                            }
                            None => span,
                        }
                    };
                    let side_diverges = lint.dead
                        || if b {
                            self.k_block_diverges(*then)
                        } else {
                            els.is_some_and(|x| self.tys.kind(self.out.expr_ty[self.ei(x)]) == TyKind::Never)
                        };
                    lint.dead = saved || side_diverges;
                    Self::k_break(env, lint);
                    if els.is_some() || b {
                        self.k_poison(env, &[side_span]);
                    }
                    return None;
                }
                let saved = lint.dead;
                lint.dead = false;
                let mut tenv = env.clone();
                Self::k_break(&mut tenv, lint);
                self.k_block(*then, &mut tenv, lint);
                lint.dead = false;
                if let Some(els) = els {
                    let mut eenv = env.clone();
                    Self::k_break(&mut eenv, lint);
                    self.k_expr(*els, &mut eenv, lint);
                }
                lint.dead = saved;
                Self::k_break(env, lint);
                match els_span {
                    Some(es) => self.k_poison(env, &[then_span, es]),
                    None => self.k_poison(env, &[then_span]),
                }
                None
            }
            Expr::While { label, cond, body } => {
                let regions = [self.span(*cond), p.ast.block(*body).span];
                let poison = self.k_assigned_in(&regions);
                let mut lenv = env.clone();
                for &r in &poison {
                    lenv[r as usize] = None;
                }
                Self::k_break(&mut lenv, lint);
                let saved = lint.dead;
                lint.dead = false;
                let cv = self.k_expr(*cond, &mut lenv, lint);
                if cv != Some(KVal::Bool(false)) {
                    lint.dead = false;
                    lint.frames.push((label.map(|l| l.name), Vec::new()));
                    self.k_block(*body, &mut lenv, lint);
                    lint.frames.pop();
                }
                lint.dead = saved;
                Self::k_break(env, lint);
                for &r in &poison {
                    env[r as usize] = None;
                }
                None
            }
            Expr::Loop { label, body } => {
                // A body that cannot fall through to a second iteration
                // (it always breaks or diverges at its top level) is
                // straight-line code in the same block; a body that can
                // repeat starts a new block at its head.
                let repeats = !self.k_block_diverges(*body);
                let poison = self.k_assigned_in(&[p.ast.block(*body).span]);
                let mut lenv = env.clone();
                if repeats {
                    for &r in &poison {
                        lenv[r as usize] = None;
                    }
                    Self::k_break(&mut lenv, lint);
                }
                let saved = lint.dead;
                lint.dead = false;
                lint.frames.push((label.map(|l| l.name), Vec::new()));
                self.k_block(*body, &mut lenv, lint);
                let (_, breaks) = lint.frames.pop().unwrap();
                lint.dead = saved;
                if repeats {
                    Self::k_break(env, lint);
                }
                for &r in &poison {
                    env[r as usize] = None;
                }
                if breaks.len() == 1 { breaks.into_iter().next().unwrap() } else { None }
            }
            Expr::For { label, pat, iter, body } => {
                self.k_expr(*iter, env, lint);
                let regions = [self.span(*iter), p.ast.block(*body).span];
                let poison = self.k_assigned_in(&regions);
                let mut lenv = env.clone();
                for &r in &poison {
                    lenv[r as usize] = None;
                }
                Self::k_break(&mut lenv, lint);
                let saved = lint.dead;
                lint.dead = false;
                let none = None;
                self.k_bind_pat(*pat, &none, &mut lenv, lint);
                lint.frames.push((label.map(|l| l.name), Vec::new()));
                self.k_block(*body, &mut lenv, lint);
                lint.frames.pop();
                lint.dead = saved;
                Self::k_break(env, lint);
                for &r in &poison {
                    env[r as usize] = None;
                }
                None
            }
            Expr::Match { scrut, arms } => {
                let sv = self.k_expr(*scrut, env, lint);
                let sty = self.out.expr_ty[self.ei(*scrut)];
                let saved = lint.dead;
                if let Some(arm) = sv.as_ref().and_then(|v| self.k_select_arm(arms, v, sty)) {
                    // Only this arm runs. With several arms its assignments
                    // and its value are still lost at the join; a single
                    // arm is straight-line code.
                    lint.dead = false;
                    let pushed = self.k_allow_push(&arm.attrs.clone(), lint);
                    if arms.len() > 1 {
                        Self::k_break(env, lint);
                    }
                    self.k_bind_pat(arm.pat, &sv, env, lint);
                    let v = self.k_expr(arm.body, env, lint);
                    self.k_allow_pop(pushed, lint);
                    let body_dead = lint.dead || self.tys.kind(self.out.expr_ty[self.ei(arm.body)]) == TyKind::Never;
                    lint.dead = saved || body_dead;
                    if arms.len() == 1 {
                        return v;
                    }
                    Self::k_break(env, lint);
                    self.k_poison(env, &[self.span(arm.body)]);
                    return None;
                }
                let mut regions: Vec<Span> = Vec::new();
                let mut single = None;
                for arm in arms {
                    lint.dead = false;
                    let mut aenv = env.clone();
                    if arms.len() > 1 {
                        Self::k_break(&mut aenv, lint);
                    }
                    let pushed = self.k_allow_push(&arm.attrs.clone(), lint);
                    self.k_bind_pat(arm.pat, &sv, &mut aenv, lint);
                    if let Some(g) = arm.guard {
                        self.k_expr(g, &mut aenv, lint);
                    }
                    let v = self.k_expr(arm.body, &mut aenv, lint);
                    self.k_allow_pop(pushed, lint);
                    regions.push(self.span(arm.body));
                    single = Some((aenv, v));
                }
                lint.dead = saved;
                if arms.len() == 1
                    && let Some((aenv, v)) = single
                {
                    *env = aenv;
                    return v;
                }
                Self::k_break(env, lint);
                self.k_poison(env, &regions);
                None
            }
            Expr::Break { label, value } => {
                let v = value.map(|x| self.k_expr(x, env, lint)).unwrap_or(None);
                let want = label.map(|l| l.name);
                if let Some(frame) = lint.frames.iter_mut().rev().find(|(n, _)| want.is_none() || *n == want) {
                    frame.1.push(v);
                }
                None
            }
            Expr::Continue(_) => None,
            Expr::Return(v) => {
                if let Some(v) = v {
                    self.k_expr(*v, env, lint);
                }
                None
            }
            Expr::Let { pat, scrut } => {
                let v = self.k_expr(*scrut, env, lint);
                self.k_bind_pat(*pat, &v, env, lint);
                None
            }
            Expr::Call { callee, args } => {
                self.k_expr(*callee, env, lint);
                let mut vals = Vec::new();
                for &a in args {
                    vals.push(self.k_expr(a, env, lint));
                }
                // A call is a terminator; a variant or tuple-struct
                // constructor is an aggregate in the same block.
                if !matches!(self.out.expr_res[self.ei(*callee)], Res::Variant(..) | Res::OptSome | Res::ConstUsize(_)) {
                    Self::k_break(env, lint);
                }
                match self.out.expr_res[self.ei(e)] {
                    Res::DefaultVal => match self.tys.kind(ety) {
                        TyKind::Int(_) | TyKind::Char => Some(KVal::Int(0)),
                        TyKind::Bool => Some(KVal::Bool(false)),
                        _ => None,
                    },
                    Res::FromCast => match vals.into_iter().next().flatten() {
                        Some(KVal::Int(v)) => self.k_wrap(v, ety).map(KVal::Int),
                        other => other,
                    },
                    _ => match { let r = self.out.expr_res[self.ei(*callee)]; r } {
                        Res::ConstUsize(u) if !self.k_query_placeholder(*callee) => Some(KVal::Int(u as i128)),
                        Res::Variant(a, v) if p.adt(a).is_enum => Some(KVal::Enum(a, v)),
                        Res::Variant(a, _) if !p.adt(a).is_enum => Some(KVal::Agg(vals)),
                        Res::OptSome => Some(KVal::Agg(vals)),
                        _ => None,
                    },
                }
            }
            Expr::MethodCall { recv, args, .. } => {
                self.k_expr(*recv, env, lint);
                for &a in args {
                    self.k_expr(a, env, lint);
                }
                Self::k_break(env, lint);
                None
            }
            Expr::Field { base, .. } | Expr::TupleField { base, .. } => {
                let bv = self.k_expr(*base, env, lint);
                match (bv, self.out.expr_res[self.ei(e)]) {
                    (Some(KVal::Agg(items)), Res::Field { derefs: 0, index }) => items.get(index as usize).cloned().unwrap_or(None),
                    _ => None,
                }
            }
            Expr::Index { base, index } => {
                let bv = self.k_expr(*base, env, lint);
                let iv = self.k_expr(*index, env, lint);
                self.k_check_index(e, *base, &iv, span, lint);
                Self::k_break(env, lint);
                match (bv, iv) {
                    (Some(KVal::Agg(items)), Some(KVal::Int(i))) if i >= 0 => items.get(i as usize).cloned().unwrap_or(None),
                    _ => None,
                }
            }
            Expr::StructLit { fields, update, .. } => {
                let base = update.and_then(|u| self.k_expr(u, env, lint));
                match self.out.expr_res[self.ei(e)] {
                    Res::Variant(a, v) if !p.adt(a).is_enum => {
                        let variant = &p.adt(a).variants[v as usize];
                        let mut items: Vec<Option<KVal>> = match base {
                            Some(KVal::Agg(items)) if items.len() == variant.fields.len() => items,
                            _ => vec![None; variant.fields.len()],
                        };
                        for &(fname, _, fe) in fields {
                            let fv = self.k_expr(fe, env, lint);
                            if let Some(i) = variant.fields.iter().position(|f| f.name == fname) {
                                items[i] = fv;
                            }
                        }
                        Some(KVal::Agg(items))
                    }
                    Res::Variant(a, v) if p.adt(a).is_enum => {
                        for &(_, _, fe) in fields {
                            self.k_expr(fe, env, lint);
                        }
                        Some(KVal::Enum(a, v))
                    }
                    _ => {
                        for &(_, _, fe) in fields {
                            self.k_expr(fe, env, lint);
                        }
                        None
                    }
                }
            }
            Expr::Tuple(elems) => {
                let items = elems.iter().map(|&el| self.k_expr(el, env, lint)).collect();
                Some(KVal::Agg(items))
            }
            Expr::Array(elems) => {
                let items = elems.iter().map(|&el| self.k_expr(el, env, lint)).collect();
                Some(KVal::Agg(items))
            }
            Expr::ArrayRepeat { value, len } => {
                self.k_expr(*value, env, lint);
                self.k_expr(*len, env, lint);
                None
            }
            Expr::Range { lo, hi, .. } => {
                for b in [lo, hi].into_iter().flatten() {
                    self.k_expr(*b, env, lint);
                }
                None
            }
            Expr::Ref { expr, .. } => {
                self.k_expr(*expr, env, lint);
                None
            }
            Expr::Deref(inner) => {
                self.k_expr(*inner, env, lint);
                None
            }
            Expr::Cast { expr, .. } => {
                let v = self.k_expr(*expr, env, lint);
                let from = self.out.expr_ty[self.ei(*expr)];
                match (v, self.tys.kind(ety)) {
                    (Some(KVal::Int(x)), TyKind::Int(_) | TyKind::Char) => self.k_wrap(x, ety).map(KVal::Int),
                    (Some(KVal::Bool(b)), TyKind::Int(_)) => Some(KVal::Int(b as i128)),
                    (Some(KVal::Bool(b)), TyKind::Bool) => Some(KVal::Bool(b)),
                    (Some(KVal::Enum(a, v)), TyKind::Int(_)) => {
                        let d = self.k_discriminant(a, v);
                        self.k_wrap(d, ety).map(KVal::Int)
                    }
                    (Some(KVal::Float(b, f)), TyKind::Int(it)) => {
                        // `as` saturates and maps NaN to 0.
                        let x = k_float(b, f);
                        match self.k_range(ety) {
                            Some((_, lo, hi)) if it.signed() => Some(KVal::Int((x as i128).clamp(lo, hi))),
                            Some((_, _, hi)) => Some(KVal::Int(((x as u128).min(hi as u128)) as i128)),
                            None => Some(KVal::Int((x as u128) as i128)),
                        }
                    }
                    (Some(KVal::Float(b, f)), TyKind::Float(g)) => Some(KVal::Float(k_float_bits(k_float(b, f), g), g)),
                    (Some(KVal::Int(x)), TyKind::Float(g)) => {
                        // An unsigned source converts from its value, which
                        // for u128 sits in the bits.
                        let unsigned = matches!(self.tys.kind(from), TyKind::Int(it) if !it.signed());
                        let bits = match (g, unsigned) {
                            (crate::ty::FloatTy::F32, true) => ((x as u128) as f32).to_bits() as u64,
                            (crate::ty::FloatTy::F32, false) => (x as f32).to_bits() as u64,
                            (_, true) => ((x as u128) as f64).to_bits(),
                            (_, false) => (x as f64).to_bits(),
                        };
                        Some(KVal::Float(bits, g))
                    }
                    _ => None,
                }
            }
            Expr::OffsetOf { .. } => match self.out.expr_res[self.ei(e)] {
                Res::ConstUsize(u) => Some(KVal::Int(u as i128)),
                _ => None,
            },
            Expr::Macro { args, .. } => {
                for &a in args {
                    self.k_expr(a, env, lint);
                }
                Self::k_break(env, lint);
                None
            }
            Expr::Binary { op, lhs, rhs } => self.k_binary(e, *op, *lhs, *rhs, span, env, lint),
            Expr::Unary { op, expr } => self.k_unary(e, *op, *expr, span, env, lint),
            Expr::Assign { lhs, rhs } => {
                self.k_place_parts(*lhs, env, lint);
                let whole = if matches!(p.ast.expr(*lhs), Expr::Path(_)) { self.k_place_root(*lhs) } else { None };
                let v = self.k_expr(*rhs, env, lint);
                match whole {
                    Some(root) => Self::k_set(env, lint, root, v),
                    None => {
                        // A destructuring target stores a known
                        // component into each whole-local element.
                        let mut done = false;
                        if let Expr::Tuple(elems) = p.ast.expr(*lhs)
                            && let Some(KVal::Agg(items)) = &v
                            && items.len() == elems.len()
                        {
                            done = true;
                            for (el, item) in elems.iter().zip(items.iter()) {
                                if matches!(p.ast.expr(*el), Expr::Path(_))
                                    && let Some(r) = self.k_place_root(*el)
                                {
                                    Self::k_set(env, lint, r, item.clone());
                                } else if let Some(r) = self.k_place_root(*el) {
                                    env[r as usize] = None;
                                }
                            }
                        }
                        if !done {
                            if let Some(root) = self.k_place_root(*lhs) {
                                env[root as usize] = None;
                            } else {
                                let mut roots = Vec::new();
                                self.k_lhs_roots(*lhs, &mut roots);
                                for r in roots {
                                    env[r as usize] = None;
                                }
                            }
                        }
                    }
                }
                None
            }
            Expr::AssignOp { op, lhs, rhs } => {
                let root = self.k_place_root(*lhs);
                let whole = matches!(p.ast.expr(*lhs), Expr::Path(_));
                if !whole {
                    self.k_place_parts(*lhs, env, lint);
                }
                let rv = self.k_expr(*rhs, env, lint);
                // The place is read after its own parts and the right
                // side run, so a terminator in either has already
                // cleared a multiply-assigned root. A field of a known
                // aggregate still reads its component; an index or a
                // deref reads nothing known.
                let old = if whole {
                    root.and_then(|r| env.get(r as usize).cloned().unwrap_or(None))
                } else {
                    match (root.and_then(|r| env.get(r as usize).cloned().unwrap_or(None)), self.out.expr_res[self.ei(*lhs)]) {
                        (Some(KVal::Agg(items)), Res::Field { derefs: 0, index }) => {
                            items.get(index as usize).cloned().unwrap_or(None)
                        }
                        _ => None,
                    }
                };
                if matches!(op, BinOp::Add | BinOp::Sub | BinOp::Mul)
                    && let (Some(KVal::Int(a)), Some(KVal::Int(b))) = (&old, &rv)
                {
                    let lt = self.out.expr_ty[self.ei(*lhs)];
                    let (a, b) = (*a, *b);
                    self.k_check_arith(*op, a, b, lt, span, lint);
                }
                if matches!(op, BinOp::Shl | BinOp::Shr)
                    && let Some(KVal::Int(s)) = rv
                {
                    let lt = self.out.expr_ty[self.ei(*lhs)];
                    if let Some(bits) = self.k_bits(lt) {
                        if s < 0 || s >= bits as i128 {
                            self.k_fire(span, lint);
                        }
                    }
                }
                if matches!(op, BinOp::Div | BinOp::Rem)
                    && let Some(KVal::Int(b)) = rv
                {
                    let lt = self.out.expr_ty[self.ei(*lhs)];
                    if let Some(b) = self.k_math(b, lt) {
                        if b == 0 {
                            self.k_fire_panic(span, lint, "attempt to divide by zero", "Change the divisor so it cannot be zero.");
                        } else if b == -1
                            && let Some((_, lo, _)) = self.k_range(lt)
                            && matches!(&old, Some(KVal::Int(a)) if self.k_math(*a, lt) == Some(lo))
                        {
                            self.k_fire_panic(span, lint, "attempt to divide with overflow", "Change the values or the type.");
                        }
                    }
                }
                // The checked operation ends the block; the store back
                // starts the next one, so break before recording it.
                if matches!(op, BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div | BinOp::Rem | BinOp::Shl | BinOp::Shr)
                    && self.k_bits(self.out.expr_ty[self.ei(*lhs)]).is_some()
                {
                    Self::k_break(env, lint);
                }
                match root {
                    Some(r) if matches!(p.ast.expr(*lhs), Expr::Path(_)) => {
                        let lt = self.out.expr_ty[self.ei(*lhs)];
                        let nv = match (old, rv) {
                            (Some(KVal::Int(a)), Some(KVal::Int(b))) => self.k_arith(*op, a, b, lt).map(KVal::Int),
                            _ => None,
                        };
                        Self::k_set(env, lint, r, nv);
                    }
                    Some(r) => env[r as usize] = None,
                    None => {}
                }
                None
            }
            Expr::Try(inner) | Expr::Await(inner) => {
                let v = self.k_expr(*inner, env, lint);
                Self::k_break(env, lint);
                v
            }
            Expr::Closure { params, body, .. } => {
                // A closure body is its own body for the lints: its
                // parameters are unknown, captures keep the knowledge
                // they have here, and nothing it assigns leaks out.
                let mut cenv = env.clone();
                let none = None;
                for param in params {
                    self.k_bind_pat(param.pat, &none, &mut cenv, lint);
                }
                let saved = lint.dead;
                lint.dead = false;
                self.k_expr(*body, &mut cenv, lint);
                lint.dead = saved;
                None
            }
            _ => None,
        }
    }

    /// Walks the sub-expressions of an assignment place (indexes and the
    /// like) so operations inside them are linted.
    fn k_place_parts(&mut self, e: ExprId, env: &mut KEnv, lint: &mut KLint) {
        match self.p.ast.expr(e) {
            Expr::Index { base, index } => {
                self.k_place_parts(*base, env, lint);
                let iv = self.k_expr(*index, env, lint);
                let span = self.span(e);
                self.k_check_index(e, *base, &iv, span, lint);
                Self::k_break(env, lint);
            }
            Expr::Field { base, .. } | Expr::TupleField { base, .. } => self.k_place_parts(*base, env, lint),
            Expr::Deref(inner) => {
                self.k_expr(*inner, env, lint);
            }
            // A destructuring target holds a place per element.
            Expr::Tuple(elems) | Expr::Array(elems) => {
                for &el in elems {
                    self.k_place_parts(el, env, lint);
                }
            }
            Expr::StructLit { fields, .. } => {
                for &(_, _, fe) in fields {
                    self.k_place_parts(fe, env, lint);
                }
            }
            Expr::Call { args, .. } => {
                for &arg in args {
                    self.k_place_parts(arg, env, lint);
                }
            }
            _ => {}
        }
    }

    /// The arm a known scrutinee value selects. Arms are read in
    /// order: an arm is selected only when its pattern certainly
    /// matches, it has no guard, and no earlier arm could have
    /// matched. A pattern this pass cannot decide (a guarded arm that
    /// covers, a payload subpattern, a const it cannot read) stops
    /// the selection, so the caller walks every arm instead.
    fn k_select_arm<'x>(&self, arms: &'x [ast::Arm], v: &KVal, sty: Ty) -> Option<&'x ast::Arm> {
        for arm in arms {
            match self.k_covers(arm.pat, v, sty) {
                KCov::Yes if arm.guard.is_none() => return Some(arm),
                KCov::Yes | KCov::Unknown => return None,
                KCov::No => {}
            }
        }
        None
    }

    /// Whether a pattern certainly matches, certainly misses, or may
    /// match the known scrutinee value.
    fn k_covers(&self, pat: PatId, v: &KVal, sty: Ty) -> KCov {
        match v {
            KVal::Int(i) => self.k_scalar_covers(pat, *i, sty),
            KVal::Bool(b) => self.k_scalar_covers(pat, *b as i128, sty),
            KVal::Enum(a, var) => self.k_enum_covers(pat, *a, *var),
            KVal::Float(..) | KVal::Agg(_) => KCov::Unknown,
        }
    }

    fn k_scalar_covers(&self, pat: PatId, val: i128, sty: Ty) -> KCov {
        let p = self.p;
        match p.ast.pat(pat) {
            Pat::Wild => KCov::Yes,
            Pat::Binding { .. } => match self.out.pat_res[(pat.0 - self.out.pat_base) as usize] {
                // A const item used as a pattern matches only its value.
                PatRes::ConstItem(_) | PatRes::BodyConst(_) => match self.pat_scalar(pat) {
                    Some(x) if self.k_cmp(val, x, sty) == std::cmp::Ordering::Equal => KCov::Yes,
                    Some(_) => KCov::No,
                    None => KCov::Unknown,
                },
                PatRes::Binding { .. } => KCov::Yes,
                _ => KCov::Unknown,
            },
            Pat::Path(_) => match self.pat_scalar(pat) {
                Some(x) if self.k_cmp(val, x, sty) == std::cmp::Ordering::Equal => KCov::Yes,
                Some(_) => KCov::No,
                None => KCov::Unknown,
            },
            Pat::Lit(l) => match p.ast.expr(*l) {
                Expr::Bool(b) => {
                    if val == *b as i128 {
                        KCov::Yes
                    } else {
                        KCov::No
                    }
                }
                _ => match self.const_scalar(*l) {
                    Some(x) if self.k_cmp(val, x, sty) == std::cmp::Ordering::Equal => KCov::Yes,
                    Some(_) => KCov::No,
                    None => KCov::Unknown,
                },
            },
            Pat::Range { lo, hi, inclusive } => {
                use std::cmp::Ordering::{Greater, Less};
                let lo_v = match lo {
                    Some(e) => match self.const_scalar(*e) {
                        Some(x) => Some(x),
                        None => return KCov::Unknown,
                    },
                    None => None,
                };
                let hi_v = match hi {
                    Some(e) => match self.const_scalar(*e) {
                        Some(x) => Some(x),
                        None => return KCov::Unknown,
                    },
                    None => None,
                };
                let lo_ok = lo_v.is_none_or(|x| self.k_cmp(val, x, sty) != Less);
                let hi_ok = hi_v.is_none_or(|x| {
                    let c = self.k_cmp(val, x, sty);
                    if *inclusive { c != Greater } else { c == Less }
                });
                if lo_ok && hi_ok { KCov::Yes } else { KCov::No }
            }
            Pat::Or(alts) => {
                let mut any_unknown = false;
                for &a in alts {
                    match self.k_scalar_covers(a, val, sty) {
                        KCov::Yes => return KCov::Yes,
                        KCov::Unknown => any_unknown = true,
                        KCov::No => {}
                    }
                }
                if any_unknown { KCov::Unknown } else { KCov::No }
            }
            Pat::At { inner, .. } | Pat::Paren(inner) => self.k_scalar_covers(*inner, val, sty),
            _ => KCov::Unknown,
        }
    }

    fn k_enum_covers(&self, pat: PatId, adt: AdtId, var: u32) -> KCov {
        let p = self.p;
        match self.out.pat_res[(pat.0 - self.out.pat_base) as usize] {
            PatRes::Variant(a, v) if a == adt => {
                if v != var {
                    return KCov::No;
                }
                // The variant matches; payload subpatterns that are
                // plain bindings cannot refuse it.
                let subs_catch = match p.ast.pat(pat) {
                    Pat::TupleStruct { elems, .. } => elems.iter().all(|&s| self.k_pat_catches(s)),
                    Pat::Struct { fields, .. } => fields.iter().all(|&(_, s)| self.k_pat_catches(s)),
                    _ => true,
                };
                if subs_catch { KCov::Yes } else { KCov::Unknown }
            }
            PatRes::Variant(..) => KCov::Unknown,
            _ => match p.ast.pat(pat) {
                Pat::Wild => KCov::Yes,
                Pat::Binding { .. } => match self.out.pat_res[(pat.0 - self.out.pat_base) as usize] {
                    PatRes::Binding { .. } => KCov::Yes,
                    _ => KCov::Unknown,
                },
                Pat::Or(alts) => {
                    let mut any_unknown = false;
                    for &a in alts {
                        match self.k_enum_covers(a, adt, var) {
                            KCov::Yes => return KCov::Yes,
                            KCov::Unknown => any_unknown = true,
                            KCov::No => {}
                        }
                    }
                    if any_unknown { KCov::Unknown } else { KCov::No }
                }
                Pat::At { inner, .. } | Pat::Paren(inner) => self.k_enum_covers(*inner, adt, var),
                _ => KCov::Unknown,
            },
        }
    }

    /// True when a subpattern accepts any payload (a binding, a
    /// wildcard, or the same nested under `@`, parens, or borrows).
    fn k_pat_catches(&self, pat: PatId) -> bool {
        match self.p.ast.pat(pat) {
            Pat::Wild | Pat::Rest => true,
            Pat::Binding { .. } => matches!(self.out.pat_res[(pat.0 - self.out.pat_base) as usize], PatRes::Binding { .. }),
            Pat::At { inner, .. } | Pat::Paren(inner) | Pat::Ref { inner, .. } => self.k_pat_catches(*inner),
            Pat::Or(alts) => alts.iter().any(|&a| self.k_pat_catches(a)),
            _ => false,
        }
    }

    /// Wrapped arithmetic for continuing a known value (no lint here).
    fn k_arith(&self, op: BinOp, a: i128, b: i128, t: Ty) -> Option<i128> {
        if self.k_is_u128(t) {
            // The stored values are u128 bit patterns; `b` of a shift is
            // the amount in its own type, already range-checked by the
            // caller, so a negative or huge amount just stops tracking.
            let (au, bu) = (a as u128, b as u128);
            let r = match op {
                BinOp::Add => au.wrapping_add(bu),
                BinOp::Sub => au.wrapping_sub(bu),
                BinOp::Mul => au.wrapping_mul(bu),
                BinOp::Div => {
                    if bu == 0 {
                        return None;
                    }
                    au / bu
                }
                BinOp::Rem => {
                    if bu == 0 {
                        return None;
                    }
                    au % bu
                }
                BinOp::BitAnd => au & bu,
                BinOp::BitOr => au | bu,
                BinOp::BitXor => au ^ bu,
                BinOp::Shl => au.checked_shl(u32::try_from(b).ok()?)?,
                BinOp::Shr => au.checked_shr(u32::try_from(b).ok()?)?,
                _ => return None,
            };
            return Some(r as i128);
        }
        let (a, b) = (self.k_math(a, t)?, self.k_math(b, t)?);
        let r = match op {
            BinOp::Add => a.checked_add(b)?,
            BinOp::Sub => a.checked_sub(b)?,
            BinOp::Mul => a.checked_mul(b)?,
            BinOp::Div => {
                if b == 0 {
                    return None;
                }
                a.checked_div(b)?
            }
            BinOp::Rem => {
                if b == 0 {
                    return None;
                }
                a.checked_rem(b)?
            }
            BinOp::BitAnd => a & b,
            BinOp::BitOr => a | b,
            BinOp::BitXor => a ^ b,
            BinOp::Shl => a.checked_shl(u32::try_from(b).ok()?)?,
            BinOp::Shr => a.checked_shr(u32::try_from(b).ok()?)?,
            _ => return None,
        };
        self.k_wrap(r, t)
    }

    /// A binary operation, then the terminator it ends the block with:
    /// a checked integer operation or a short-circuit, or a trait
    /// operation's call. Comparisons and bit operations stay in the
    /// block.
    fn k_binary(&mut self, e: ExprId, op: BinOp, lhs: ExprId, rhs: ExprId, span: Span, env: &mut KEnv, lint: &mut KLint) -> Option<KVal> {
        let lt = self.out.expr_ty[self.ei(lhs)];
        let breaker = matches!(self.out.expr_res[self.ei(e)], Res::TraitBin { .. })
            || matches!(op, BinOp::And | BinOp::Or)
            || (matches!(op, BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div | BinOp::Rem | BinOp::Shl | BinOp::Shr)
                && self.k_bits(lt).is_some());
        let v = self.k_binary_inner(e, op, lhs, rhs, span, env, lint);
        if breaker {
            Self::k_break(env, lint);
        }
        v
    }

    fn k_binary_inner(&mut self, e: ExprId, op: BinOp, lhs: ExprId, rhs: ExprId, span: Span, env: &mut KEnv, lint: &mut KLint) -> Option<KVal> {
        let lv = self.k_expr(lhs, env, lint);
        // A known short-circuit skips the right side entirely.
        match (op, &lv) {
            (BinOp::And, Some(KVal::Bool(false))) => return Some(KVal::Bool(false)),
            (BinOp::Or, Some(KVal::Bool(true))) => return Some(KVal::Bool(true)),
            _ => {}
        }
        let rv = self.k_expr(rhs, env, lint);
        if matches!(self.out.expr_res[self.ei(e)], Res::TraitBin { .. }) {
            return None;
        }
        // Float arithmetic is IEEE in rustc's const propagation too; an
        // f32 result computed in f64 and rounded once is exact for these.
        if let (Some(KVal::Float(a, f)), Some(KVal::Float(b, _))) = (&lv, &rv) {
            let (x, y) = (k_float(*a, *f), k_float(*b, *f));
            let r = match op {
                BinOp::Add => x + y,
                BinOp::Sub => x - y,
                BinOp::Mul => x * y,
                BinOp::Div => x / y,
                BinOp::Rem => x % y,
                _ => return None,
            };
            return Some(KVal::Float(k_float_bits(r, *f), *f));
        }
        match op {
            BinOp::And => match (lv, rv) {
                (Some(KVal::Bool(a)), Some(KVal::Bool(b))) => Some(KVal::Bool(a && b)),
                _ => None,
            },
            BinOp::Or => match (lv, rv) {
                (Some(KVal::Bool(a)), Some(KVal::Bool(b))) => Some(KVal::Bool(a || b)),
                _ => None,
            },
            BinOp::Eq | BinOp::Ne | BinOp::Lt | BinOp::Le | BinOp::Gt | BinOp::Ge => {
                let ord = match (&lv, &rv) {
                    (Some(KVal::Int(a)), Some(KVal::Int(b))) => {
                        let lt = self.out.expr_ty[self.ei(lhs)];
                        match (self.k_math(*a, lt), self.k_math(*b, lt)) {
                            (Some(a), Some(b)) => Some(self.k_cmp(a, b, lt)),
                            _ => None,
                        }
                    }
                    (Some(KVal::Bool(a)), Some(KVal::Bool(b))) => Some(a.cmp(b)),
                    _ => None,
                };
                ord.map(|o| {
                    KVal::Bool(match op {
                        BinOp::Eq => o == std::cmp::Ordering::Equal,
                        BinOp::Ne => o != std::cmp::Ordering::Equal,
                        BinOp::Lt => o == std::cmp::Ordering::Less,
                        BinOp::Le => o != std::cmp::Ordering::Greater,
                        BinOp::Gt => o == std::cmp::Ordering::Greater,
                        _ => o != std::cmp::Ordering::Less,
                    })
                })
            }
            BinOp::Shl | BinOp::Shr => {
                let lt = self.out.expr_ty[self.ei(lhs)];
                if let (Some(bits), Some(KVal::Int(s))) = (self.k_bits(lt), &rv)
                    && (*s < 0 || *s >= bits as i128)
                {
                    self.k_fire(span, lint);
                    return None;
                }
                match (lv, rv) {
                    (Some(KVal::Int(a)), Some(KVal::Int(b))) => self.k_arith(op, a, b, lt).map(KVal::Int),
                    _ => None,
                }
            }
            BinOp::Add | BinOp::Sub | BinOp::Mul => {
                let lt = self.out.expr_ty[self.ei(lhs)];
                let (Some(KVal::Int(a)), Some(KVal::Int(b))) = (lv, rv) else { return None };
                if self.k_is_u128(lt) {
                    let (au, bu) = (a as u128, b as u128);
                    let r = match op {
                        BinOp::Add => au.checked_add(bu),
                        BinOp::Sub => au.checked_sub(bu),
                        _ => au.checked_mul(bu),
                    };
                    return match r {
                        Some(r) => Some(KVal::Int(r as i128)),
                        None => {
                            self.k_fire(span, lint);
                            None
                        }
                    };
                }
                let Some((_, lo, hi)) = self.k_range(lt) else { return None };
                let (Some(a), Some(b)) = (self.k_math(a, lt), self.k_math(b, lt)) else { return None };
                let r = match op {
                    BinOp::Add => a.checked_add(b),
                    BinOp::Sub => a.checked_sub(b),
                    _ => a.checked_mul(b),
                };
                match r {
                    Some(r) if (lo..=hi).contains(&r) => Some(KVal::Int(r)),
                    _ => {
                        self.k_fire(span, lint);
                        None
                    }
                }
            }
            BinOp::Div | BinOp::Rem => {
                let lt = self.out.expr_ty[self.ei(lhs)];
                // A known zero divisor panics whatever the dividend is;
                // `MIN / -1` needs both sides known.
                if let Some(KVal::Int(b)) = &rv
                    && self.k_bits(lt).is_some()
                    && let Some(b) = self.k_math(*b, lt)
                {
                    if b == 0 {
                        self.k_fire_panic(span, lint, "attempt to divide by zero", "Change the divisor so it cannot be zero.");
                        return None;
                    }
                    if b == -1
                        && let Some(KVal::Int(a)) = &lv
                        && let Some((_, lo, _)) = self.k_range(lt)
                        && self.k_math(*a, lt) == Some(lo)
                    {
                        self.k_fire_panic(span, lint, "attempt to divide with overflow", "Change the values or the type.");
                        return None;
                    }
                }
                match (lv, rv) {
                    (Some(KVal::Int(a)), Some(KVal::Int(b))) => self.k_arith(op, a, b, lt).map(KVal::Int),
                    _ => None,
                }
            }
            BinOp::BitAnd | BinOp::BitOr | BinOp::BitXor => {
                let lt = self.out.expr_ty[self.ei(lhs)];
                match (lv, rv) {
                    (Some(KVal::Int(a)), Some(KVal::Int(b))) => self.k_arith(op, a, b, lt).map(KVal::Int),
                    _ => None,
                }
            }
        }
    }

    /// A unary operation. An integer negation of a non-literal is a
    /// checked operation, so it ends the block like `k_binary`.
    fn k_unary(&mut self, e: ExprId, op: UnOp, inner: ExprId, span: Span, env: &mut KEnv, lint: &mut KLint) -> Option<KVal> {
        let breaker = matches!(op, UnOp::Neg)
            && self.k_bits(self.out.expr_ty[self.ei(e)]).is_some()
            && !matches!(self.p.ast.expr(inner), Expr::Int(..));
        let v = self.k_unary_inner(e, op, inner, span, env, lint);
        if breaker {
            Self::k_break(env, lint);
        }
        v
    }

    fn k_unary_inner(&mut self, e: ExprId, op: UnOp, inner: ExprId, span: Span, env: &mut KEnv, lint: &mut KLint) -> Option<KVal> {
        let v = self.k_expr(inner, env, lint);
        match op {
            UnOp::Neg => {
                if let Some(KVal::Float(b, f)) = v {
                    return Some(KVal::Float(k_float_bits(-k_float(b, f), f), f));
                }
                let Some(KVal::Int(x)) = v else { return None };
                let t = self.out.expr_ty[self.ei(e)];
                // A literal under the minus is a magnitude, not a
                // negation of a value: `-128i8` and the `i128::MIN`
                // literal (magnitude 2^127, stored as the MIN bit
                // pattern) wrap to their own value and never fire.
                if matches!(self.p.ast.expr(inner), Expr::Int(..)) {
                    return self.k_wrap(x.wrapping_neg(), t).map(KVal::Int);
                }
                let Some((_, lo, hi)) = self.k_range(t) else { return None };
                let r = x.checked_neg();
                match r {
                    Some(r) if (lo..=hi).contains(&r) => Some(KVal::Int(r)),
                    _ => {
                        self.k_fire(span, lint);
                        None
                    }
                }
            }
            UnOp::Not => match v {
                Some(KVal::Int(x)) => {
                    let t = self.out.expr_ty[self.ei(e)];
                    let x = self.k_math(x, t)?;
                    self.k_wrap(!x, t).map(KVal::Int)
                }
                Some(KVal::Bool(b)) => Some(KVal::Bool(!b)),
                _ => None,
            },
        }
    }

    // ---------- Finish ----------

    /// True when the type still holds an unbound non-integer inference
    /// variable (an integer variable defaults to i32, as in rustc; any other
    /// one is the E0282 "type annotations needed" case).
    /// True for a type variable that is not an integer or float literal variable.
    fn unbound_general(&self, t: Ty) -> bool {
        matches!(self.kind(t), TyKind::Infer(v) if !v.is_int() && !v.is_float())
    }

    /// Also true for a const argument nothing fixed (`S<?N>` from a
    /// unit struct value, rustc E0284).
    fn has_unbound_var(&self, t: Ty) -> bool {
        if !self.tys.flags(t).contains_infer() {
            return false;
        }
        match self.tys.kind(self.resolve(t)) {
            TyKind::Infer(v) => !v.is_int() && !v.is_float() && !self.is_diverging_root(v.index()),
            TyKind::Ref(_, _, e) | TyKind::Slice(e) => self.has_unbound_var(e),
            TyKind::Array(e, n) => self.has_unbound_var(e) || self.unbound_const(n),
            TyKind::Tuple(ts) => self.tys.tys_of(ts).iter().any(|&e| self.has_unbound_var(e)),
            TyKind::Adt(_, a) => self.tys.args(a).iter().any(|g| match *g {
                GenericArg::Ty(e) => self.has_unbound_var(e),
                GenericArg::Const(c) => self.unbound_const(c),
                GenericArg::Lifetime(_) => false,
            }),
            _ => false,
        }
    }

    /// `has_unbound_var` at every depth: also inside fn items,
    /// closures, fn pointers, raw pointers, projections, and dyn
    /// args. The body-end scan of every expression and pattern type
    /// uses it.
    fn has_unbound_deep(&self, t: Ty) -> bool {
        if !self.tys.flags(t).contains_infer() {
            return false;
        }
        let args = |a: ArgsId| self.tys.args(a).iter().any(|g| g.as_ty().is_some_and(|e| self.has_unbound_deep(e)));
        match self.tys.kind(self.resolve(t)) {
            TyKind::Infer(v) => !v.is_int() && !v.is_float() && !self.is_diverging_root(v.index()),
            TyKind::Ref(_, _, e) | TyKind::Slice(e) | TyKind::Array(e, _) | TyKind::RawPtr(_, e) => self.has_unbound_deep(e),
            TyKind::Tuple(ts) => self.tys.tys_of(ts).iter().any(|&e| self.has_unbound_deep(e)),
            TyKind::Adt(_, a) | TyKind::Projection(_, a) | TyKind::Closure(_, a) | TyKind::FnDef(_, a) | TyKind::Opaque(_, a) => args(a),
            TyKind::FnPtr(sig) => {
                let b = self.tys.sig(sig);
                self.tys.tys_of(b.value.inputs).iter().any(|&e| self.has_unbound_deep(e)) || self.has_unbound_deep(b.value.output)
            }
            TyKind::Dyn(b, _) => self.tys.dyn_bounds(b).principal.as_ref().is_some_and(|pr| {
                let bound = self.tys.bindings(pr.value.bindings).iter().any(|&(_, g)| g.as_ty().is_some_and(|e| self.has_unbound_deep(e)));
                args(pr.value.args) || bound
            }),
            _ => false,
        }
    }

    /// True when `t` holds an inference var at any depth, also in the
    /// signature of a closure it holds (`Box<{closure}>` of `|| 1`): a
    /// coercion cast of it waits for body end (`deferred_coerce_casts`).
    fn cast_operand_open(&self, t: Ty) -> bool {
        let args = |a: ArgsId| self.tys.args(a).iter().any(|g| g.as_ty().is_some_and(|e| self.cast_operand_open(e)));
        match self.tys.kind(self.resolve(t)) {
            TyKind::Infer(_) => true,
            TyKind::Ref(_, _, e) | TyKind::Slice(e) | TyKind::Array(e, _) | TyKind::RawPtr(_, e) => self.cast_operand_open(e),
            TyKind::Tuple(ts) => self.tys.tys_of(ts).iter().any(|&e| self.cast_operand_open(e)),
            TyKind::Closure(d, a) => {
                args(a) || self.closures.iter().find(|c| c.def == d).is_some_and(|c| c.inputs.iter().chain([&c.output]).any(|&e| self.cast_operand_open(e)))
            }
            TyKind::Adt(_, a) | TyKind::Projection(_, a) | TyKind::FnDef(_, a) | TyKind::Opaque(_, a) => args(a),
            TyKind::FnPtr(sig) => {
                let b = self.tys.sig(sig);
                self.tys.tys_of(b.value.inputs).iter().any(|&e| self.cast_operand_open(e)) || self.cast_operand_open(b.value.output)
            }
            _ => false,
        }
    }

    /// `literal_fallback_ty`, also on the signatures of the closures `t`
    /// holds (`cast_operand_open`).
    fn literal_fallback_deep(&mut self, t: Ty) {
        self.literal_fallback_ty(t);
        let mut stack = vec![self.deep(t)];
        while let Some(t) = stack.pop() {
            match self.tys.kind(t) {
                TyKind::Closure(d, _) => {
                    if let Some(c) = self.closures.iter().find(|c| c.def == d) {
                        let sig: Vec<Ty> = c.inputs.iter().copied().chain([c.output]).collect();
                        for e in sig {
                            self.literal_fallback_ty(e);
                        }
                    }
                }
                TyKind::Ref(_, _, e) | TyKind::Slice(e) | TyKind::Array(e, _) | TyKind::RawPtr(_, e) => stack.push(e),
                TyKind::Tuple(ts) => stack.extend(self.tys.tys_of(ts).iter().copied()),
                TyKind::Adt(_, a) => stack.extend(self.tys.args(a).iter().filter_map(|g| g.as_ty())),
                _ => {}
            }
        }
    }

    /// Binds every integer or float literal variable in `t` to
    /// its fallback type (`i32`, `f64`), at any depth. General
    /// variables stay free.
    fn literal_fallback_ty(&mut self, t: Ty) {
        if !self.tys.flags(t).contains_infer() {
            return;
        }
        let args = |cx: &mut Self, a: ArgsId| {
            for g in cx.tys.args(a).to_vec() {
                if let Some(e) = g.as_ty() {
                    cx.literal_fallback_ty(e);
                }
            }
        };
        match self.tys.kind(self.resolve(t)) {
            TyKind::Infer(v) => {
                if v.is_int() {
                    self.bind_var(v.index(), I32);
                } else if v.is_float() {
                    let f = self.tys.float_ty(FloatTy::F64);
                    self.bind_var(v.index(), f);
                }
            }
            TyKind::Ref(_, _, e) | TyKind::Slice(e) | TyKind::Array(e, _) | TyKind::RawPtr(_, e) => self.literal_fallback_ty(e),
            TyKind::Tuple(ts) => {
                for e in self.tys.tys_of(ts).to_vec() {
                    self.literal_fallback_ty(e);
                }
            }
            TyKind::Adt(_, a) | TyKind::Projection(_, a) | TyKind::Closure(_, a) | TyKind::FnDef(_, a) | TyKind::Opaque(_, a) => args(self, a),
            TyKind::FnPtr(sig) => {
                let b = self.tys.sig(sig);
                for e in self.tys.tys_of(b.value.inputs).to_vec() {
                    self.literal_fallback_ty(e);
                }
                self.literal_fallback_ty(b.value.output);
            }
            TyKind::Dyn(b, _) => {
                if let Some(pr) = self.tys.dyn_bounds(b).principal.clone() {
                    args(self, pr.value.args);
                    for (_, g) in self.tys.bindings(pr.value.bindings).to_vec() {
                        if let Some(e) = g.as_ty() {
                            self.literal_fallback_ty(e);
                        }
                    }
                }
            }
            _ => {}
        }
    }

    fn unbound_const(&self, c: ConstId) -> bool {
        matches!(self.tys.const_kind(self.resolve_const(c)), ConstKind::Infer(_))
    }

    /// True when the type holds a const variable nothing fixed.
    fn has_unbound_const(&self, t: Ty) -> bool {
        if !self.tys.flags(t).contains_infer() {
            return false;
        }
        match self.tys.kind(self.resolve(t)) {
            TyKind::Ref(_, _, e) | TyKind::Slice(e) => self.has_unbound_const(e),
            TyKind::Array(e, n) => self.unbound_const(n) || self.has_unbound_const(e),
            TyKind::Tuple(ts) => self.tys.tys_of(ts).iter().any(|&e| self.has_unbound_const(e)),
            TyKind::Adt(_, a) | TyKind::FnDef(_, a) => self.tys.args(a).iter().any(|g| match *g {
                GenericArg::Ty(e) => self.has_unbound_const(e),
                GenericArg::Const(c) => self.unbound_const(c),
                GenericArg::Lifetime(_) => false,
            }),
            _ => false,
        }
    }

    /// A generic call whose type argument nothing fixed is an
    /// annotation error (rustc E0282 and E0283), never a dropped
    /// instance request. Runs after inference, before the hard
    /// obligation run, which then skips the obligations on the
    /// reported variables (one error per root). Closure sites
    /// have their own check below; a body with an error already
    /// reports nothing here, since its variables may be unbound
    /// only because of that error.
    fn uninferred_site_args(&mut self) {
        self.run_obligations(false);
        if !self.errs.is_empty() {
            return;
        }
        let p = self.p;
        let mut reported: Vec<u32> = Vec::new();
        for i in 0..self.generic_sites.len() {
            let (ei, template, args) = self.generic_sites[i].clone();
            let Some(gi) = args.iter().position(|g| g.as_ty().is_some_and(|t| self.has_unbound_var(t) && !self.has_error_kind(t))) else {
                // A const argument nothing fixed (rustc E0282).
                if let Some(ci) = args.iter().position(|g| match *g {
                    GenericArg::Const(c) => matches!(self.tys.const_kind(self.resolve_const(c)), ConstKind::Infer(_)),
                    _ => false,
                }) {
                    let param = p.gx.fn_templates.get(template.0 as usize).and_then(|t| t.as_ref()).and_then(|t| t.generics.params.get(ci));
                    let pname = param.map_or("_".to_string(), |d| self.name(d.name).to_string());
                    let fname = p.display_path(p.fn_info(template).name);
                    let span = self.span(ExprId(self.out.expr_base + ei as u32));
                    self.err(
                        "L0610",
                        span,
                        format!("type annotations needed: cannot infer the value of the const parameter `{pname}` of `{fname}`"),
                        "Name the value with a turbofish such as `::<3>`, or annotate the value the call returns.",
                    );
                }
                continue;
            };
            let t = args[gi].as_ty().unwrap_or(ERROR);
            let t = self.deep(t);
            self.unbound_vars(t, &mut reported);
            let param = p.gx.fn_templates.get(template.0 as usize).and_then(|t| t.as_ref()).and_then(|t| t.generics.params.get(gi));
            let pname = param.map_or("_".to_string(), |d| self.name(d.name).to_string());
            let fname = p.display_path(p.fn_info(template).name);
            let span = self.span(ExprId(self.out.expr_base + ei as u32));
            self.err(
                "L0610",
                span,
                format!("type annotations needed: cannot infer the type of the generic parameter `{pname}` of `{fname}`"),
                "Name the type with a turbofish such as `::<i32>`, or annotate the value the call returns.",
            );
        }
        if reported.is_empty() {
            return;
        }
        let pending = self.obl.take();
        for ob in pending {
            let mentions = match ob {
                obligations::Obligation::Trait { trait_ref, .. } => self.args_mention(trait_ref.args, &reported),
                obligations::Obligation::AssocEq { eq, .. } => {
                    self.args_mention(eq.trait_args, &reported) || reported.iter().any(|&v| self.occurs(v, eq.ty))
                }
                obligations::Obligation::DynStatic { .. } => false,
                obligations::Obligation::TypeStatic { ty, .. } | obligations::Obligation::StaticSource { ty, .. } => {
                    reported.iter().any(|&v| self.occurs(v, ty))
                }
            };
            if !mentions {
                self.obl.push(ob);
            }
        }
    }

    /// The unbound general variables in one deep-resolved type.
    fn unbound_vars(&self, t: Ty, out: &mut Vec<u32>) {
        if !self.tys.flags(t).contains_infer() {
            return;
        }
        match self.tys.kind(self.resolve(t)) {
            TyKind::Infer(v) if !v.is_int() && !v.is_float() => out.push(v.index()),
            TyKind::Ref(_, _, e) | TyKind::Slice(e) | TyKind::Array(e, _) | TyKind::RawPtr(_, e) => self.unbound_vars(e, out),
            TyKind::Tuple(ts) => {
                for &e in self.tys.tys_of(ts) {
                    self.unbound_vars(e, out);
                }
            }
            TyKind::Adt(_, a) | TyKind::Projection(_, a) | TyKind::Closure(_, a) | TyKind::FnDef(_, a) => {
                for g in self.tys.args(a) {
                    if let Some(e) = g.as_ty() {
                        self.unbound_vars(e, out);
                    }
                }
            }
            _ => {}
        }
    }

    /// True when a type argument list mentions one of `vars`.
    fn args_mention(&self, a: ArgsId, vars: &[u32]) -> bool {
        self.tys.args(a).iter().any(|g| g.as_ty().is_some_and(|t| vars.iter().any(|&v| self.occurs(v, t))))
    }

    /// The scalar rows of the `as` table (the cast check in `expr`) for a
    /// cast decided at body end: integer, float, bool and char operands,
    /// and a fieldless enum to an integer. Any other operand (a reference,
    /// a fn item, a raw pointer) is outside this deferred path.
    fn scalar_cast_ok(&self, t: Ty, target: Ty) -> bool {
        let enum_cast = self.tys.local_adt(t).is_some_and(|a| {
            let adt = self.p.adt(a);
            adt.is_enum && adt.variants.iter().all(|v| v.shape == VariantShape::Unit)
        });
        match (self.kind(t), self.kind(target)) {
            (_, TyKind::Int(_)) if enum_cast => true,
            (TyKind::Int(_) | TyKind::Bool | TyKind::Char, TyKind::Int(_)) => true,
            (TyKind::Int(_) | TyKind::Float(_), TyKind::Float(_)) => true,
            (TyKind::Float(_), TyKind::Int(_)) => true,
            (TyKind::Int(IntTy::U8) | TyKind::Char, TyKind::Char) => true,
            (TyKind::Bool, TyKind::Bool) => true,
            (TyKind::Error, _) | (_, TyKind::Error) => true,
            _ => false,
        }
    }

    /// Resolves every recorded type, defaults integer variables, and checks literal ranges.
    fn finish(&mut self) {
        // rustc's literal fallback runs between the last soft run and
        // the hard one: an obligation that is only ambiguous over a
        // literal's type (`{float}: Tr` with impls for f32 and f64)
        // selects with i32 or f64, the types body end defaults to.
        self.run_obligations(false);
        // Operators and sums that waited on an open operand or item, now
        // that later uses fixed it: before literal fallback, as rustc
        // selects them as soon as the variable is known.
        self.finish_wait_binops();
        self.finish_deferred_sums();
        self.finish_deferred_extends();
        self.run_obligations(false);
        self.literal_fallback_in_obligations();
        // Coercion casts with an open operand, after literal fallback
        // and before the last obligation run (rustc's `check_casts`).
        for (src, dst, span, ex) in std::mem::take(&mut self.deferred_coerce_casts) {
            self.literal_fallback_deep(src);
            let snap = self.snapshot_vars();
            let obl_len = self.obl_len();
            let err_len = self.errs.len();
            if !self.coerce_at(src, dst, span, Some(ex)) {
                self.rollback_vars(snap);
                self.obl_truncate(obl_len);
                self.errs.truncate(err_len);
                let (src_d, dst_d) = (self.deep(src), self.deep(dst));
                let (a, b) = (self.tn(src_d), self.tn(dst_d));
                self.err("L0116", span, format!("cannot cast `{a}` as `{b}`"), "Give the literal a type suffix (`1u8`), or annotate the value before the cast.");
            }
        }
        // `into()` calls whose target came later: std's conversions on
        // the final types (numeric, String/Box/Rc/identity, the std
        // `From` set). Any other target (a user `From` impl, a generic
        // one, one still open) rejects: a lust limit, never an accept.
        for (e, rt, dst, name, span) in std::mem::take(&mut self.deferred_into) {
            self.literal_fallback_deep(dst);
            let dst_d = self.deep(dst);
            let src_d = self.deep(rt);
            if matches!(self.kind(dst_d), TyKind::Error) {
                continue;
            }
            if self.has_unbound_deep(dst_d) {
                if !self.tainted_lookup(dst_d) {
                    self.err("L0610", span, "type annotations needed: the target of this `into()` is not known", "Annotate the target type, as in `let y: Vec<u8> = x.into();`.");
                }
                continue;
            }
            if Self::numeric_from_ok(self.kind(src_d), self.kind(dst_d))
                && matches!(self.kind(src_d), TyKind::Int(_) | TyKind::Float(_) | TyKind::Bool | TyKind::Char)
            {
                self.set_res(e, Res::PrimOp { kind: PrimOpKind::IntoCast, derefs: 0 });
                continue;
            }
            if self.builtin_into_method(e, rt, name, &[], &[], Some(dst_d)).is_some() || self.std_into_method(e, rt, name, &[], &[], Some(dst_d)).is_some() {
                continue;
            }
            let (a, b) = (self.tn(src_d), self.tn(dst_d));
            let self_ty = self.into_self(rt).0;
            let fargs = self.tys.intern_args(&[GenericArg::Ty(dst_d), GenericArg::Ty(self_ty)]);
            let from = TraitRef { def: self.p.gx.lang.from, args: fargs, bindings: EMPTY_BINDINGS };
            if matches!(self.select_obligation(from), Selection::NoImpl) {
                self.err("L0612", span, format!("no impl of `From<{a}>` for `{b}`"), "Convert with a cast or a method, or change the target.");
            } else {
                self.err("L0640", span, format!("`into()` from `{a}` to `{b}`, a target a later statement fixes, is not supported yet"), "Annotate the target at the call: `let y: T = x.into();`.");
            }
        }
        for (src, dst, span) in std::mem::take(&mut self.deferred_open_casts) {
            self.literal_fallback_deep(src);
            let (src_d, dst_d) = (self.deep(src), self.deep(dst));
            if !self.scalar_cast_ok(src_d, dst_d) {
                let (a, b) = (self.tn(src_d), self.tn(dst_d));
                self.err("L0116", span, format!("cannot cast `{a}` as `{b}`"), "Annotate the value's type before the cast.");
            }
        }
        // A deferred `as_deref` pick can bind type variables other
        // sites wait on, so it runs before the uninferred check.
        method::finish_deferred_lang_methods(self);
        for (target, item, span, (e, base, derefs)) in std::mem::take(&mut self.deferred_collect) {
            // A source collection target (`BTreeMap`, `IndexMap`) takes the
            // `FromIterator::from_iter` route, as at a call whose target is
            // known; its deferred call is picked by `finish_deferred_methods`
            // below.
            if self.from_iter_route(e, target, item, span, base, derefs).is_none() {
                self.collect_target_ok(target, item, span);
            }
        }
        self.uninferred_site_args();
        // ARCH 2.4 run point: the obligation queue runs at body end to a fixpoint.
        // Anything left there is an annotation error, never a silent default.
        self.run_obligations(true);
        method::finish_deferred_methods(self);
        self.finish_trait_fn_values();
        self.finish_trait_fn_calls();
        self.reject_marker_callables();
        // `?` conversions deferred on a projection error type:
        // it normalizes now its types are known (fx-tryfrom).
        for (e, err_t, ret_err, span) in std::mem::take(&mut self.deferred_try) {
            let err_t = self.deep(err_t);
            let err_t = self.normalize_here(err_t);
            let ret_err = self.deep(ret_err);
            self.decide_try_res(e, err_t, ret_err, span);
        }
        self.run_obligations(false);
        for (e, op, t) in std::mem::take(&mut self.open_binops) {
            use BinOp::*;
            let t = self.deep(t);
            let k = self.kind(t);
            let int = matches!(k, TyKind::Int(_)) || k.is_int_infer();
            let float = matches!(k, TyKind::Float(_)) || k.is_float_infer();
            let ok = match op {
                Add | Sub | Mul | Div | Rem => int || float,
                BitAnd | BitOr | BitXor => int || k == TyKind::Bool,
                Shl | Shr => int,
                Eq | Ne | Lt | Le | Gt | Ge => int || float || matches!(k, TyKind::Bool | TyKind::Char),
                And | Or => true,
            };
            if !ok && k != TyKind::Error {
                let span = self.span(e);
                self.err(
                    "L0610",
                    span,
                    "type annotations needed: the operand types of this operator must be known here",
                    "Annotate the closure parameters.",
                );
            }
        }
        // A local whose element or item type was never decided (`let a = [];`,
        // `let v = Vec::new();`) is an annotation error (rustc E0282). This
        // scan runs before the zonk below defaults those variables away.
        for i in 0..self.out.locals.len() {
            let t = self.out.locals[i].ty;
            if self.has_unbound_var(t) && !self.has_error_kind(t) {
                let span = self.out.locals[i].span;
                let name = self.name(self.out.locals[i].name).to_string();
                self.err(
                    "L0111",
                    span,
                    format!("cannot infer the type of `{name}`"),
                    "Add a type annotation, such as `let v: Vec<i64> = Vec::new();`.",
                );
            }
        }
        // Any other expression or pattern whose type nothing fixed
        // (`Vec::new();`, `let _ = None;`, `drop;`) is the same error
        // (rustc E0282): integer and float variables default, and a
        // variable a `!` value flowed into falls back to `!`.
        if self.errs.is_empty() {
            let open = |cx: &Self, t: Ty| cx.has_unbound_deep(t) && !cx.has_error_kind(t);
            if let Some(i) = (0..self.out.expr_ty.len()).find(|&i| open(self, self.out.expr_ty[i])) {
                let span = self.span(ExprId(self.out.expr_base + i as u32));
                let tn = self.tn(self.out.expr_ty[i]);
                self.err(
                    "L0610",
                    span,
                    format!("type annotations needed: cannot infer the type `{tn}` here"),
                    "Annotate the type, or name it with a turbofish such as `Vec::<i32>::new()`.",
                );
            } else if let Some(i) = (0..self.out.pat_ty.len()).find(|&i| open(self, self.out.pat_ty[i])) {
                let span = self.p.ast.pat_span(PatId(self.out.pat_base + i as u32));
                let tn = self.tn(self.out.pat_ty[i]);
                let msg = format!("type annotations needed: cannot infer the type `{tn}` here");
                self.err("L0610", span, msg, "Annotate the pattern's type.");
            }
        }
        // The same for a const argument in an expression that is no
        // local (`S;` for a unit struct with a const param, rustc E0284):
        // codegen has no value for it.
        // Only a body that made a const variable can keep one.
        if self.errs.is_empty()
            && self.next_const_id > generics::INFER_MARKER_BASE
            && let Some(i) = (0..self.out.expr_ty.len()).find(|&i| self.has_unbound_const(self.out.expr_ty[i]))
        {
            let span = self.span(ExprId(self.out.expr_base + i as u32));
            self.err(
                "L0610",
                span,
                "type annotations needed: cannot infer the value of a const parameter here",
                "Name the value with a turbofish such as `S::<3>`, or annotate the type.",
            );
        }
        // Deferred layout queries: every constraint is in, so the
        // fallback (`zonk`) gives the type rustc measures.
        for (e, t, align, span) in std::mem::take(&mut self.deferred_layout) {
            let t = self.zonk(t);
            self.layout_val_res(e, t, align, span);
        }
        // Deferred format tests, with types as bound by now.
        // A test whose type holds an Adt with a written impl queues its
        // goal (`require_fmt`), so the queue runs once more: the last
        // run above is over, and a goal left in it is never proved. A
        // literal in the goal (`Wrap(5)`) takes its fallback type first,
        // and so does one in the tested type: an Adt over a literal's
        // variable (`H<Range<{integer}>>`) is no instance yet, and the
        // derive walk would read it as a template.
        for (t, spec, span) in std::mem::take(&mut self.deferred_fmt) {
            self.default_literal_vars(t);
            let t = self.deep(t);
            self.require_sized(t, span);
            self.check_fmt_arg(t, spec, span);
        }
        self.run_obligations(false);
        self.literal_fallback_in_obligations();
        self.run_obligations(true);
        // Deferred Clone and PartialEq needs of builtin Vec and
        // slice methods, with types as bound by now.
        self.finish_make_mut();
        for (t, span) in std::mem::take(&mut self.deferred_clone) {
            let t = self.deep(t);
            let t = self.normalize_here(t);
            if !has_clone(self.p, &self.tys, t) && !matches!(self.kind(t), TyKind::Error | TyKind::Infer(_)) {
                let tn = self.tn(t);
                self.err("L0112", span, format!("`{tn}` does not implement Clone"), "Add #[derive(Clone)] to the type.");
            }
        }
        self.finish_unwind();
        for (t, span) in std::mem::take(&mut self.deferred_string_from) {
            let t = self.deep(t);
            let tn = self.tn(t);
            match self.kind(t) {
                TyKind::Error => {}
                _ if t == CHAR || t == STRING => {}
                TyKind::Ref(_, Mut::Shared, s) if self.kind(s) == TyKind::Str => {}
                TyKind::Infer(_) => self.err("L0610", span, "type annotations needed: the input of `String::from` is not known", "Annotate the input's type."),
                // No std impl, and no user one can exist (orphan rules).
                TyKind::Int(_) | TyKind::Float(_) | TyKind::Bool | TyKind::Unit => self.err(
                    "L0612",
                    span,
                    format!("the trait bound `String: From<{tn}>` is not satisfied"),
                    "Convert with `to_string()` or `format!`.",
                ),
                // std's `&mut str`, `&String`, and `Box<str>` impls, a
                // user impl, or a param's bound.
                _ => {
                    let what = format!("`String::from` as a value with input `{tn}` (lust takes `&str`, `char`, or `String` there)");
                    self.errs.push(unsupported(span, &what));
                }
            }
        }
        for (callee, e, dst, at, span) in std::mem::take(&mut self.deferred_own_from) {
            let (dst, at) = (self.deep(dst), self.deep(at));
            if self.has_error_kind(dst) || self.has_error_kind(at) {
                continue;
            }
            // The input was checked as itself, so only a std conversion
            // that takes it unchanged applies here.
            if self.tys.flags(dst).contains_infer() || self.std_from_arg(dst, at) != Some(at) {
                self.err(
                    "L0610",
                    span,
                    "type annotations needed: cannot infer the type this `from` builds",
                    "Write the target type, for example `let s: Rc<str> = Rc::from(x);`.",
                );
                continue;
            }
            self.set_res(callee, Res::Builtin(Builtin::ConvInto));
            self.set_res(e, Res::Builtin(Builtin::ConvInto));
        }
        for (dst, src, span) in std::mem::take(&mut self.deferred_prim_from) {
            let src = self.deep(src);
            if self.has_error_kind(src) {
                continue;
            }
            if matches!(self.kind(src), TyKind::Infer(_)) {
                self.err("L0610", span, "type annotations needed: the input of this `from` is not known", "Annotate the input's type.");
                continue;
            }
            if !Self::numeric_from_ok(self.kind(src), self.kind(dst)) {
                let (dn, sn) = (self.tn(dst), self.tn(src));
                self.err(
                    "L0612",
                    span,
                    format!("the trait bound `{dn}: From<{sn}>` is not satisfied"),
                    "Check the conversion: `From` between primitives only widens.",
                );
            }
        }
        // `type_name::<T>()` calls: with every constraint in, lust
        // must be able to print rustc's exact string for T (in a
        // template check a parameter or projection inside T is a
        // placeholder; each instance decides again).
        for (t, span) in std::mem::take(&mut self.deferred_type_names) {
            let t = self.deep(t);
            let t = self.normalize_here(t);
            if self.has_error_kind(t) {
                continue;
            }
            if self.tys.flags(t).contains_infer() {
                self.err(
                    "L0610",
                    span,
                    "type annotations needed: cannot infer the type `type_name` names here",
                    "Name the type, for example `type_name::<u8>()`.",
                );
                continue;
            }
            let open = self.tys.flags(t).contains_param() || self.tys.flags(t).contains_projection();
            if any::type_name_of(self.p, &mut self.tys, t, open).is_none() {
                let tn = self.tn(t);
                self.err(
                    "L0641",
                    span,
                    format!("`type_name` of `{tn}` is not supported yet"),
                    "Name a type whose exact `type_name` string lust can print (no closures, fn items, or `impl Trait`).",
                );
            }
        }
        for (t, span) in std::mem::take(&mut self.deferred_eq) {
            let t = self.deep(t);
            let t = self.normalize_here(t);
            if !has_eq(self.p, &self.tys, t) && !matches!(self.kind(t), TyKind::Error | TyKind::Infer(_)) {
                let tn = self.tn(t);
                self.err("L0112", span, format!("type `{tn}` cannot be compared with `==`"), "Add #[derive(PartialEq)] to the type.");
            }
        }
        for (t, span) in std::mem::take(&mut self.deferred_copy) {
            let t = self.deep(t);
            if !is_copy(self.p, &self.tys, t) && !matches!(self.kind(t), TyKind::Error | TyKind::Infer(_)) {
                let tn = self.tn(t);
                self.err("L0612", span, format!("`{tn}` is not Copy"), "Use `.cloned()` instead of `.copied()`.");
            }
        }
        for (t, span) in std::mem::take(&mut self.deferred_repeat_n) {
            let t = self.deep(t);
            if is_copy(self.p, &self.tys, t) && !has_clone(self.p, &self.tys, t) && !matches!(self.kind(t), TyKind::Error | TyKind::Infer(_)) {
                let tn = self.tn(t);
                self.err(
                    "L0612",
                    span,
                    format!("`repeat_n` of `{tn}`, a Copy type with a written Clone impl, is not supported"),
                    "Derive Clone on the type.",
                );
            }
        }
        for (r, w, span) in std::mem::take(&mut self.deferred_io_copy) {
            let peel = |cx: &mut Self, t: Ty| {
                let t = cx.deep(t);
                match cx.kind(t) {
                    TyKind::Ref(_, _, inner) => cx.deep(inner),
                    _ => t,
                }
            };
            let (r, w) = (peel(self, r), peel(self, w));
            if let Some(d) = crate::check::platform::io_copy_diag(self.p, &self.tys, r, w, span) {
                self.errs.push(d);
            }
        }
        for (t, incl, span) in std::mem::take(&mut self.deferred_exact_range) {
            let t = self.deep(t);
            // An integer variable still open falls back to `i32`.
            let int = match self.kind(t) {
                TyKind::Int(i) => Some(i),
                k if k.is_int_infer() => Some(crate::ty::IntTy::I32),
                _ => None,
            };
            if let Some(i) = int
                && !iter::exact_range_int(i, incl)
            {
                let t = if matches!(self.kind(t), TyKind::Int(_)) { t } else { self.tys.intern(TyKind::Int(i)) };
                let tn = self.tn(t);
                if incl {
                    self.err("L0612", span, format!("no impl of `ExactSizeIterator` for `std::ops::RangeInclusive<{tn}>`"), "Use an inclusive range of an 8-bit or 16-bit integer.");
                } else {
                    self.err("L0612", span, format!("no impl of `ExactSizeIterator` for `std::ops::Range<{tn}>`"), "Use a range of `usize` or of a 32-bit or narrower integer.");
                }
            }
        }
        for (t, span) in std::mem::take(&mut self.deferred_default) {
            let t = self.deep(t);
            if !has_default(self.p, &self.tys, t) && !matches!(self.kind(t), TyKind::Error) {
                let tn = self.tn(t);
                self.err("L0612", span, format!("`{tn}` does not implement Default, or lust cannot build its default yet"), "Use `replace` with a value.");
            } else {
                // The default glue reads the type's layout.
                self.record_glue_reads(self.p.gx.lang.default, t);
            }
        }
        for (t, span) in std::mem::take(&mut self.deferred_vec_clone) {
            let t = self.deep(t);
            if !has_clone(self.p, &self.tys, t) && !matches!(self.kind(t), TyKind::Error) {
                let tn = self.tn(t);
                self.err("L0112", span, format!("`vec![x; n]` needs Clone, but `{tn}` is not Clone"), "Derive Clone on the element type.");
            }
        }
        for (t, span) in std::mem::take(&mut self.deferred_downgrade) {
            let t = self.deep(t);
            // `Weak<str>` and `Weak<[T]>` are built (cgen/own.rs).
            if crate::check::own::dyn_wrapped_elem(&self.tys, t).is_some() {
                self.errs.push(not_yet("L0641", span, "a `Weak` of this unsized type"));
            }
        }
        for (t, span) in std::mem::take(&mut self.deferred_sized) {
            let t = self.deep(t);
            if matches!(self.kind(t), TyKind::Dyn(..) | TyKind::Slice(_) | TyKind::Str) {
                self.errs.push(not_yet("L0641", span, "this `Rc` function on an unsized type"));
            }
        }
        self.check_deferred_raw();
        for (t, span) in std::mem::take(&mut self.deferred_debug) {
            // A projection (`<T as TryFrom<U>>::Error` from a
            // deferred `try_into`, fx-tryfrom) reads through its
            // normalization, like the Clone loop above.
            let t = self.deep(t);
            let t = self.normalize_here(t);
            if !has_debug(self.p, &self.tys, t) && !matches!(self.kind(t), TyKind::Error) {
                let tn = self.tn(t);
                self.err("L0612", span, format!("`{tn}` does not implement Debug"), "Add #[derive(Debug)] to the type.");
            }
        }
        for (k, q, span) in std::mem::take(&mut self.deferred_hash_key) {
            self.check_hash_key(k, q, span);
        }
        for (t, span) in std::mem::take(&mut self.deferred_glue_hash) {
            self.glue_hash_ok(t, span);
        }
        for (t, span) in std::mem::take(&mut self.deferred_ord) {
            let t = self.deep(t);
            if !has_total_ord(self.p, &self.tys, t) && !matches!(self.kind(t), TyKind::Error) {
                let tn = self.tn(t);
                self.err("L0612", span, format!("`{tn}` does not implement Ord, or lust cannot compare it yet"), "Derive Ord on the type, or compare integers, chars, strings, or tuples of them.");
            }
        }
        for (t, span) in std::mem::take(&mut self.deferred_sort_ord) {
            let t = self.deep(t);
            if matches!(self.kind(t), TyKind::Error) {
                continue;
            }
            if !has_total_ord(self.p, &self.tys, t) {
                let tn = self.tn(t);
                self.err("L0612", span, format!("`{tn}` does not implement Ord, or lust cannot compare it yet"), "Derive Ord on the type, or compare integers, chars, strings, or tuples of them.");
            } else if !has_partial_cmp(self.p, &self.tys, t) {
                let tn = self.tn(t);
                self.err(
                    "L0640",
                    span,
                    format!("sorting `{tn}` compares with its written `PartialOrd::lt`, which lust cannot call yet"),
                    "Sort with `sort_by` and an explicit comparator, or derive `PartialOrd`.",
                );
            }
        }
        // Deferred fn casts with a `_` target: literal fallback
        // first (`g(3)` makes the `_` an `i32`), then the
        // signature check rustc runs after inference. A `_`
        // nothing else decided takes the operand's type here.
        for (src, dst, span) in std::mem::take(&mut self.deferred_fn_casts) {
            let dst = self.deep(dst);
            self.literal_fallback_ty(dst);
            let ok = match self.kind(src) {
                TyKind::FnDef(..) => self.fn_item_ptr_unifies(src, dst),
                _ => match (self.callable_sig(src), self.callable_sig(dst)) {
                    (Some((pa, ra)), Some((pb, rb))) => {
                        pa.len() == pb.len() && pa.iter().zip(&pb).all(|(&a, &b)| self.unify(a, b)) && self.unify(ra, rb)
                    }
                    _ => false,
                },
            };
            if !ok {
                let (src_d, dst_d) = (self.deep(src), self.deep(dst));
                let (a, b) = (self.tn(src_d), self.tn(dst_d));
                self.err(
                    "L0116",
                    span,
                    format!("cannot cast `{a}` as `{b}`"),
                    "A fn item or fn pointer casts only to a fn pointer of the same signature.",
                );
            }
        }
        // A `thread_local!` `const { .. }` init fn proves its const part (check/tls.rs).
        self.tls_const_init_check();
        self.build_closure_map();
        for i in 0..self.out.expr_ty.len() {
            let t = self.out.expr_ty[i];
            self.out.expr_ty[i] = self.zonk(t);
        }
        self.check_std_order_keys();
        self.settle_projections();
        for i in 0..self.out.pat_ty.len() {
            let t = self.out.pat_ty[i];
            let z = self.zonk(t);
            self.out.pat_ty[i] = self.settled(z);
        }
        self.finish_closures();
        for i in 0..self.out.locals.len() {
            let t = self.out.locals[i].ty;
            let z = self.zonk(t);
            let z = self.settled(z);
            if z == ERROR && !self.has_error_kind(t) {
                let span = self.out.locals[i].span;
                let name = self.name(self.out.locals[i].name).to_string();
                self.err(
                    "L0111",
                    span,
                    format!("cannot infer the type of `{name}`"),
                    "Add a type annotation, such as `let v: Vec<i64> = Vec::new();`.",
                );
            }
            self.out.locals[i].ty = z;
        }
        for i in 0..self.out.coerce.len() {
            match self.out.coerce[i] {
                Coerce::Unsize(t) => self.out.coerce[i] = Coerce::Unsize(self.zonk(t)),
                Coerce::CowDeref(n, t) => self.out.coerce[i] = Coerce::CowDeref(n, self.zonk(t)),
                Coerce::CowRecv(n, t) => self.out.coerce[i] = Coerce::CowRecv(n, self.zonk(t)),
                Coerce::ByNext(t) => self.out.coerce[i] = Coerce::ByNext(self.zonk(t)),
                Coerce::IntoIterCall(t) => self.out.coerce[i] = Coerce::IntoIterCall(self.zonk(t)),
                Coerce::ReifyFn(t) => self.out.coerce[i] = Coerce::ReifyFn(self.zonk(t)),
                // The raw pointer target can still be a var at the coercion
                // (`Cell::new(&x)` where `Cell<*const u8>` is expected).
                Coerce::RefToPtr(t) => self.out.coerce[i] = Coerce::RefToPtr(self.zonk(t)),
                _ => {}
            }
        }
        // A user `Deref` step's target can hold a literal's type var
        // (`L { v: vec![1, 2] }[0]`); lowering types the step's temporary
        // with it.
        for i in 0..self.out.deref_recv.len() {
            let t = self.out.deref_recv[i].1.target_ref;
            self.out.deref_recv[i].1.target_ref = self.zonk(t);
        }
        for i in 0..self.out.deref_coerce.len() {
            let t = self.out.deref_coerce[i].1.target_ref;
            self.out.deref_coerce[i].1.target_ref = self.zonk(t);
        }
        // A body with errors already (a missing impl, an error type) has
        // its vtable misses explained by them.
        let clean = !self.errs.iter().any(|d| d.severity == "error");
        for (x, y, span) in std::mem::take(&mut self.vtable_sites) {
            let (x, y) = (self.zonk(x), self.zonk(y));
            // An `impl Trait` source in the opaque view: the revealed
            // check asks for its hidden type's vtable.
            if self.opaque_mode == opaque::OpaqueMode::View && matches!(self.kind(x), TyKind::Opaque(..)) {
                continue;
            }
            // After mono, a concrete body's every coercion has its
            // vtable; a miss is a compiler gap, reported, never emitted.
            if self.p.gx.mono_done
                && clean
                && !self.has_error_kind(x)
                && !self.has_error_kind(y)
                && generics::vtable_for(self.p, &self.tys, x, y).is_none()
            {
                let tn = self.tn(x);
                self.err(
                    "L0702",
                    span,
                    format!("internal: no vtable was built for `{tn}` here, so this `dyn` coercion is not supported yet"),
                    "Report this; meanwhile, use generics instead of `dyn` here.",
                );
            }
            self.out.vtable_requests.push((x, y));
        }
        // Every local has a statically known size (rustc E0277): `let x
        // = *b;` for `b: Box<dyn Tr>` is a move out of the box that the
        // borrow checker allows for a sized pointee.
        for i in 0..self.out.locals.len() {
            let t = self.deep(self.out.locals[i].ty);
            if matches!(self.kind(t), TyKind::Dyn(..) | TyKind::Str | TyKind::Slice(_)) {
                let (tn, span) = (self.tn(t), self.out.locals[i].span);
                self.err(
                    "L0110",
                    span,
                    format!("the size for values of type `{tn}` cannot be known, so it cannot be a local variable"),
                    "Bind a reference instead: `let x = &*b;`.",
                );
            }
        }
        self.overflow_lint();
        // Abstract associated const reads (see `abstract_consts`)
        // get their zero placeholder now: every value-reading
        // analysis above has run, only lowering is left.
        for e in std::mem::take(&mut self.abstract_consts) {
            let i = self.ei(e);
            if self.out.const_exprs[i].is_none()
                && let Some(v) = self.zero_const(self.out.expr_ty[i])
            {
                self.out.const_exprs[i] = Some(v);
            }
        }
        for (template, args) in std::mem::take(&mut self.into_iter_requests) {
            let zargs: Vec<GenericArg> = args.iter().map(|&g| if let GenericArg::Ty(t) = g { GenericArg::Ty(self.zonk(t)) } else { g }).collect();
            self.out.inst_requests.push((template, zargs));
        }
        // Generic user `deref` fns of method receivers, as call sites.
        for (table, idx, is_mut, template, args) in std::mem::take(&mut self.deref_sites) {
            let zargs: Vec<GenericArg> = args
                .iter()
                .map(|&g| match g {
                    GenericArg::Ty(t) => GenericArg::Ty(self.zonk(t)),
                    GenericArg::Const(c) => GenericArg::Const(self.resolve_const(c)),
                    other => other,
                })
                .collect();
            if let DerefTable::Index = table {
                if let Some(entry) = self.out.index_recv.get_mut(idx) {
                    if is_mut {
                        entry.1.args_mut = zargs.clone();
                    } else {
                        entry.1.args = zargs.clone();
                    }
                }
                self.out.inst_requests.push((template, zargs));
                continue;
            }
            let entries = match table {
                DerefTable::Recv => &mut self.out.deref_recv,
                DerefTable::Coerce => &mut self.out.deref_coerce,
                DerefTable::Index => unreachable!(),
            };
            if let Some(entry) = entries.get_mut(idx) {
                if is_mut {
                    entry.1.args_mut = zargs.clone();
                } else {
                    entry.1.args = zargs.clone();
                }
            }
            self.out.inst_requests.push((template, zargs));
        }
        // Generic call sites become instance requests for mono,
        // with their args zonked into place for lowering.
        for (ei, template, args) in std::mem::take(&mut self.generic_sites) {
            let zargs: Vec<GenericArg> = args
                .iter()
                .map(|&g| match g {
                    // A projection whose inputs inference fixed late
                    // (`x.try_into().ok()` at a return type, fx-tryfrom)
                    // normalizes now, so lowering finds the instance.
                    GenericArg::Ty(t) => {
                        let z = self.zonk(t);
                        GenericArg::Ty(self.normalize_here(z))
                    }
                    GenericArg::Const(c) => GenericArg::Const(self.resolve_const(c)),
                    other => other,
                })
                .collect();
            if ei < self.out.generic_args.len() {
                self.out.generic_args[ei] = zargs.clone();
            }
            self.out.generic_site_args.push((ei, template, zargs.clone()));
            self.out.inst_requests.push((template, zargs));
        }
        self.hidden_fn_uses();
        // A generic Adt constructor names the template Adt; the
        // value's type names the instance mono made. Point the
        // resolution at the instance so lowering lays it out.
        for i in 0..self.out.expr_res.len() {
            if let Res::Variant(a, v) = self.out.expr_res[i]
                && let Some(inst) = self.tys.local_adt(self.out.expr_ty[i])
                && inst != a
            {
                self.out.expr_res[i] = Res::Variant(inst, v);
            }
        }
        for i in 0..self.out.pat_res.len() {
            if let PatRes::Variant(a, v) = self.out.pat_res[i]
                && let Some(inst) = self.tys.local_adt(self.out.pat_ty[i])
                && inst != a
            {
                self.out.pat_res[i] = PatRes::Variant(inst, v);
            }
        }
        // Literal range checks (the deny-level overflowing_literals
        // lint, for ints and floats alike).
        let base = self.out.expr_base;
        for i in 0..self.out.expr_ty.len() {
            let e = ExprId(base + i as u32);
            if let Expr::Float(s) = self.p.ast.expr(e)
                && let TyKind::Float(f) = self.tys.kind(self.out.expr_ty[i])
            {
                let text = self.p.ast.strings[*s as usize].as_str();
                if crate::check::collect::float_literal_overflows(text, f) && !self.lint_lifted(&["overflowing_literals"]) {
                    let sp = self.span(e);
                    self.err(
                        "L0118",
                        sp,
                        format!("literal out of range for `{}`", f.name()),
                        format!("Use a value that fits in `{}`, or a wider type.", f.name()),
                    );
                }
            }
            if let Expr::Int(v, _) = self.p.ast.expr(e)
                && let TyKind::Int(it) = self.tys.kind(self.out.expr_ty[i])
            {
                let neg = self.negated_lits.contains(&e);
                let max = if neg && it.signed() { it.max128() + 1 } else { it.max128() };
                if *v > max && !self.lint_lifted(&["overflowing_literals"]) {
                    let s = self.span(e);
                    self.err(
                        "L0118",
                        s,
                        format!("literal out of range for `{}`", it.name()),
                        format!("Use a value that fits in `{}`, or a wider type.", it.name()),
                    );
                }
            }
        }
        // The written std and lang trait impls this body's types can
        // select: format glue, `?`, `for` loops, operators, conversions,
        // and drop glue look them up with no `ImplSet` read
        // (`ReadKey::LangImpls`).
        let (p, out) = (self.p, &mut self.out);
        let site_tys = out.generic_site_args.iter().flat_map(|(_, _, args)| args.iter().filter_map(|g| g.as_ty()));
        let tys = out.expr_ty.iter().chain(&out.pat_ty).copied().chain(out.locals.iter().map(|l| l.ty)).chain(site_tys);
        p.record_type_lang_reads(&mut out.reads, &self.tys, tys);
        // The deep layout of each type the body holds by value: signatures
        // fold types shallow (`Program::record_type_layout_reads`). A
        // generic call's type args are not held here: the instance reads
        // its own, and what the call returns or takes is an expression type.
        let tys = out.expr_ty.iter().chain(&out.pat_ty).copied().chain(out.locals.iter().map(|l| l.ty));
        p.record_type_layout_reads(&mut out.reads, &self.tys, tys);
    }

    fn has_error_kind(&self, t: Ty) -> bool {
        // Each distinct type once: a type that doubles its args per
        // level (`((T, T), (T, T))`) is a tree exponential in its depth.
        let mut seen: crate::intern::FxMap<Ty, ()> = crate::intern::FxMap::default();
        let mut stack = vec![t];
        while let Some(t) = stack.pop() {
            if seen.insert(t, ()).is_some() {
                continue;
            }
            match self.kind(t) {
                TyKind::Error => return true,
                TyKind::Ref(_, _, e) | TyKind::Slice(e) | TyKind::Array(e, _) => stack.push(e),
                TyKind::Adt(_, a) => stack.extend(self.tys.args(a).iter().filter_map(|g| g.as_ty())),
                TyKind::Tuple(ts) => stack.extend(self.tys.tys_of(ts).iter().copied()),
                _ => {}
            }
        }
        false
    }
}

/// The const evaluator's context over a body being checked: names resolve
/// through the program tables and the Binding query, as in body checking.
struct CheckCx<'x, 'p> {
    cx: &'x mut Ctx<'p>,
}

impl CheckCx<'_, '_> {
    /// The call target of const fn `f` (a path call or a method call).
    /// The evaluator is about to run its body and bake the result into
    /// the body being checked: that body depends on the const fn's
    /// body, not only its signature. A `Checked` read records the
    /// edge; its replay never matches, so the reader rechecks whenever
    /// it is a walk candidate. Nested const calls inside the evaluated
    /// body come back here and record their own edges, so the
    /// dependency is transitive.
    fn const_fn_call(&mut self, f: LocalDefId) -> crate::ty::consteval::CallTarget {
        let p = self.cx.p;
        let target = crate::check::collect::const_fn_target(p, f);
        if p.fn_info(f).is_const && p.fn_info(f).def(&p.ast).body.is_some() {
            self.cx.out.reads.record_checked(p.def_id(f), Fingerprint(0));
        }
        if matches!(target, crate::ty::consteval::CallTarget::ConstFn(_)) {
            // The body names its own sibling items, not the caller's.
            self.cx.next_const_fn_sibs = Some(p.fn_siblings.get(&f).cloned().unwrap_or_default());
        }
        target
    }
}

/// rustc's `needs_drop::<T>()` for a concrete type: a written `Drop`
/// impl (`drop_defs`: the Adt defs that have one), or a part that
/// needs drop (`[T; 0]` never does). None for the types lust cannot
/// answer exactly yet (closures, iterator adapters, trait objects,
/// params, inference leftovers).
fn needs_drop_answer(p: &Program, tys: &mut impl TyIntern, drop_defs: &[DefId], t: Ty) -> Option<bool> {
    if crate::ty::iter::iter_parts(tys, t).is_some() {
        return None;
    }
    if tys.is_string_ty(t) || tys.vec_elem(t).is_some() || tys.smart_elem(t).is_some() {
        return Some(true);
    }
    let parts: Vec<Ty> = match tys.kind(t) {
        TyKind::Bool | TyKind::Char | TyKind::Int(_) | TyKind::Float(_) | TyKind::Str | TyKind::Never => return Some(false),
        TyKind::Ref(..) | TyKind::RawPtr(..) | TyKind::FnPtr(_) | TyKind::FnDef(..) => return Some(false),
        TyKind::Slice(e) => vec![e],
        TyKind::Array(e, c) => match tys.const_kind(c) {
            ConstKind::Int(0) => return Some(false),
            ConstKind::Int(_) => vec![e],
            _ => return None,
        },
        TyKind::Tuple(ts) => tys.tys_of(ts).to_vec(),
        TyKind::Adt(def, args) => {
            if let Some(e) = tys.option_elem(t) {
                vec![e]
            } else if let Some((a, b)) = tys.result_args(t) {
                vec![a, b]
            } else if drop_defs.contains(&def) {
                return Some(true);
            } else {
                // The template's field types with this instance's args.
                let a = tys.local_adt_of(def)?;
                if p.is_manually_drop_adt(a) {
                    return Some(false);
                }
                let args: Vec<GenericArg> = tys.args(args).to_vec();
                let fields: Vec<Ty> = p.adt(a).variants.iter().flat_map(|v| v.fields.iter().map(|f| f.ty)).collect();
                fields.into_iter().map(|f| crate::ty::subst(tys, f, &args)).collect()
            }
        }
        _ => return None,
    };
    let mut r = false;
    for e in parts {
        r |= needs_drop_answer(p, tys, drop_defs, e)?;
    }
    Some(r)
}

impl CheckCx<'_, '_> {
    /// The block item `name` denotes at `at`, if any: the checker's scopes,
    /// or by span for blocks inside the const expression itself, which the
    /// evaluator walks without the checker's scopes.
    fn body_item(&self, name: Sym, at: Span) -> Option<crate::check::collect::BodyItem> {
        self.cx.body_item_of(name).or_else(|| {
            crate::check::collect::stmt_item_in_blocks(&self.cx.p.ast, &self.cx.p.item_blocks, name, at)
                .and_then(|si| self.cx.p.body_items.get(&si).copied())
        })
    }
}

impl<'p> crate::ty::consteval::ConstCx<'p> for CheckCx<'_, 'p> {
    type Tys = Tys<'p>;

    fn alias_primitive(&self, name: Sym) -> Option<&'static str> {
        crate::check::collect::alias_primitive_of(self.cx.p, name)
    }
    fn alias_hash(&self, name: Sym) -> Option<crate::ty::hash::HashTy> {
        crate::check::collect::alias_hash_of(self.cx.p, name)
    }

    fn enter_const_fn(&mut self, owner: Option<Sym>) {
        let cx = &mut *self.cx;
        let a = owner.and_then(|n| cx.p.type_names.get(&n).copied());
        cx.const_fn_saved.push((cx.const_fn_self, cx.body_scope.self_ty));
        cx.const_fn_self = Some(a);
        cx.body_scope.self_ty = a.map(|a| cx.tys.adt_ty(a));
        // The const fn body names its own sibling items, not the
        // caller's block items.
        let sibs = cx.next_const_fn_sibs.take().unwrap_or_default();
        let layer: Vec<((Sym, CtxtId), u32)> = sibs
            .iter()
            .filter_map(|&si| {
                let name = match &cx.p.ast.stmt_items[si as usize].kind {
                    ItemKind::Fn(d) => Some((d.name, d.name_span.ctxt)),
                    ItemKind::Const(c) => c.name.map(|n| (n, c.name_span.ctxt)),
                    ItemKind::Static(st) => Some((st.name, st.name_span.ctxt)),
                    _ => None,
                };
                name.map(|n| (n, si))
            })
            .collect();
        let (tdefs, tpaths) = use_item_trait_layers(cx.p, &sibs);
        let saved = (
            std::mem::take(&mut cx.item_scopes),
            std::mem::take(&mut cx.item_scope_starts),
            std::mem::take(&mut cx.trait_scopes),
            std::mem::take(&mut cx.std_trait_scopes),
            std::mem::take(&mut cx.type_layers),
        );
        cx.const_fn_items_saved.push(saved);
        cx.item_scopes.push(layer);
        cx.item_scope_starts.push(0);
        cx.trait_scopes.push(tdefs);
        cx.std_trait_scopes.push(tpaths);
        let type_layer: Vec<u32> = sibs.iter().copied().filter(|si| cx.p.body_type_items.contains_key(si)).collect();
        cx.type_layers.push(type_layer);
        cx.refresh_type_overlay();
    }
    fn exit_const_fn(&mut self) {
        if let Some((o, t)) = self.cx.const_fn_saved.pop() {
            self.cx.const_fn_self = o;
            self.cx.body_scope.self_ty = t;
        }
        if let Some((scopes, starts, tdefs, tpaths, tlayers)) = self.cx.const_fn_items_saved.pop() {
            self.cx.item_scopes = scopes;
            self.cx.item_scope_starts = starts;
            self.cx.trait_scopes = tdefs;
            self.cx.std_trait_scopes = tpaths;
            self.cx.type_layers = tlayers;
            self.cx.refresh_type_overlay();
        }
    }

    fn tys(&mut self) -> &mut Tys<'p> {
        &mut self.cx.tys
    }
    fn tys_ref(&self) -> &Tys<'p> {
        &self.cx.tys
    }
    fn ast(&self) -> &'p ast::Ast {
        let p: &'p Program = self.cx.p;
        &p.ast
    }
    fn sym_text(&self, s: Sym) -> &str {
        self.cx.name(s)
    }
    fn patterns_resolved(&self) -> bool {
        self.cx.p.resolved.is_some()
    }
    fn block_const_item(&mut self, name: Sym, at: Span) -> Option<crate::ty::consteval::TypedValue> {
        match self.body_item(name, at)? {
            crate::check::collect::BodyItem::Const(ci) => {
                let c = &self.cx.p.body_consts[ci as usize];
                Some((c.value.clone(), c.ty))
            }
            _ => None,
        }
    }
    fn const_item(&mut self, name: Sym, at: Span) -> Option<crate::ty::consteval::TypedValue> {
        // A block item of this name wins over every module item, as
        // in `path_expr`: a body const answers with its value, a body
        // static or fn blocks the flat lookup (a static's value is
        // not a const read; `static_item` answers for it).
        if self.body_item(name, at).is_some() {
            return self.block_const_item(name, at);
        }
        // A const read inside body const evaluation consumes the value:
        // record the const's `Sig` read (its fingerprint folds the
        // value), as `path_expr` does for a plain expression use.
        let p = self.cx.p;
        let &i = p.const_names.get(&name)?;
        let out = {
            let c = &p.consts[i as usize];
            (c.value.clone(), c.ty)
        };
        if let Some(&def) = p.const_defs.get(i as usize) {
            let _ = p.sig_of(&mut self.cx.out.reads, def);
        }
        Some(out)
    }
    fn assoc_const_item(&mut self, segs: &[ast::PathSeg]) -> Option<crate::ty::consteval::TypedValue> {
        // An inherent associated const read inside body const
        // evaluation, through the same pick as `path_expr`.
        let p = self.cx.p;
        let (adt, item) = self.cx.assoc_const_key(segs)?;
        let picked = self.cx.assoc_const_base(segs, None).and_then(|base| self.cx.inherent_assoc_pick(adt, item, base, None)).flatten();
        let Some((idx, value)) = picked else {
            // A trait's const for a non-generic Adt (`S::N` in `[0; S::N]`).
            let base = self.cx.assoc_const_base(segs, None)?;
            return self.cx.trait_const_value(base, None, item);
        };
        let out = (value, p.consts[idx as usize].ty);
        if let Some(&def) = p.const_defs.get(idx as usize) {
            let _ = p.sig_of(&mut self.cx.out.reads, def);
        }
        Some(out)
    }
    fn qpath_const(&mut self, self_ty: ast::TyId, trait_path: &[ast::PathSeg], name: Sym) -> Option<crate::ty::consteval::TypedValue> {
        let t = self.cx.resolve_written(self_ty);
        let tref = ast::TraitRefExpr { path: trait_path.to_vec() };
        let tr = self.cx.written_trait_ref(t, &tref, Span::default()).ok()?;
        self.cx.trait_const_value(t, Some(tr.def), name)
    }
    fn static_item(&mut self, name: Sym, at: Span) -> Option<(u32, Ty)> {
        let body = self.cx.body_item_of(name).or_else(|| {
            crate::check::collect::stmt_item_in_blocks(&self.cx.p.ast, &self.cx.p.item_blocks, name, at)
                .and_then(|si| self.cx.p.body_items.get(&si).copied())
        });
        match body {
            Some(crate::check::collect::BodyItem::Static(idx)) => {
                let p = self.cx.p;
                let ty = p.statics[idx as usize].ty;
                if let Some(&def) = p.static_defs.get(idx as usize) {
                    let _ = p.sig_of(&mut self.cx.out.reads, def);
                }
                return Some((idx, ty));
            }
            Some(_) => return None,
            None => {}
        }
        let p = self.cx.p;
        let &i = p.static_names.get(&name)?;
        let ty = p.statics[i as usize].ty;
        if let Some(&def) = p.static_defs.get(i as usize) {
            let _ = p.sig_of(&mut self.cx.out.reads, def);
        }
        Some((i, ty))
    }
    fn static_value(&mut self, idx: u32) -> Option<&crate::ty::consteval::ConstValue> {
        // The value is consumed: record the static's `Sig` read, as
        // `static_item` does.
        let p = self.cx.p;
        if let Some(&def) = p.static_defs.get(idx as usize) {
            let _ = p.sig_of(&mut self.cx.out.reads, def);
        }
        p.statics.get(idx as usize).map(|s| &s.value)
    }
    fn call_target(&mut self, callee: ExprId) -> crate::ty::consteval::CallTarget {
        use crate::ty::consteval::CallTarget;
        let p = self.cx.p;
        let ast::Expr::Path(segs) = p.ast.expr(callee) else { return CallTarget::Unknown };
        let last = segs[segs.len() - 1].name;
        let ltext = self.cx.name(last).to_string();
        if matches!(ltext.as_str(), "size_of" | "align_of") {
            let args = segs[segs.len() - 1].type_args();
            if args.len() == 1 {
                let t = self.cx.resolve_written(args[0]);
                return if ltext == "size_of" { CallTarget::SizeOf(t) } else { CallTarget::AlignOf(t) };
            }
            return CallTarget::Unknown;
        }
        if segs.len() == 1 && last == p.known.Some {
            return CallTarget::VariantCtor { adt: AdtId(u32::MAX), variant: 1, ty: ERROR };
        }
        // The Result shim sits one below the Option shim (u32::MAX):
        // Ok is variant 0, Err is variant 1.
        if segs.len() == 1 && last == p.known.Ok {
            return CallTarget::VariantCtor { adt: AdtId(u32::MAX - 1), variant: 0, ty: ERROR };
        }
        if segs.len() == 1 && last == p.known.Err {
            return CallTarget::VariantCtor { adt: AdtId(u32::MAX - 1), variant: 1, ty: ERROR };
        }
        let span = self.cx.span(callee);
        let fid = if segs.len() == 1 {
            if self.cx.lookup(last, span.ctxt).is_some() {
                return CallTarget::Unknown;
            }
            match self.cx.body_item_of(last) {
                Some(crate::check::collect::BodyItem::Fn(f)) => Some(f),
                // A body const or static of this name shadows any
                // module fn: the call names no fn here.
                Some(_) => return CallTarget::Unknown,
                None => self.cx.binding_fn(last),
            }
        } else {
            match self.cx.resolve_assoc(segs, span) {
                Some(Res::Fn(f)) => Some(f),
                Some(Res::Variant(a, v)) => {
                    return CallTarget::VariantCtor { adt: a, variant: v, ty: self.cx.tys.adt_ty(a) };
                }
                Some(Res::Builtin(_)) => return CallTarget::NonConst,
                _ => None,
            }
        };
        if let Some(f) = fid {
            let target = self.const_fn_call(f);
            if let CallTarget::ConstFn(b) = &target
                && b.generic != crate::ty::consteval::ConstGeneric::No
                && segs.iter().any(|s| !s.type_args().is_empty())
            {
                return CallTarget::Unknown;
            }
            return target;
        }
        if let Some(a) = self.cx.tuple_struct_ctor(last)
            && segs.len() == 1
        {
            return CallTarget::VariantCtor { adt: a, variant: 0, ty: self.cx.tys.adt_ty(a) };
        }
        if segs.len() == 2 && matches!(self.cx.name(segs[0].name), "String" | "Vec") {
            return CallTarget::NonConst;
        }
        CallTarget::Unknown
    }
    fn method_target(&mut self, recv: Ty, name: Sym) -> crate::ty::consteval::CallTarget {
        let p = self.cx.p;
        match crate::check::collect::const_method_of(p, &self.cx.tys, recv, name) {
            Some(f) => self.const_fn_call(f),
            None => crate::ty::consteval::CallTarget::Unknown,
        }
    }
    fn adt_instance(&mut self, adt: AdtId, binds: &[Option<Ty>]) -> Option<Ty> {
        let (def, args) = crate::check::collect::const_adt_args(self.cx.p, adt, binds)?;
        Some(self.cx.tys.mk_adt(def, &args))
    }
    fn method_private(&mut self, recv: Ty, name: Sym) -> bool {
        match self.cx.tys.local_adt(recv) {
            Some(a) => self.cx.assoc_private(a, name),
            None => false,
        }
    }
    fn unit_variant(&mut self, segs: &[ast::PathSeg], expected: Option<Ty>) -> Option<(AdtId, u32, Ty)> {
        let p = self.cx.p;
        if segs.len() == 1 && segs[0].name == p.known.None {
            let elem = expected.and_then(|t| self.cx.tys.option_elem(t)).unwrap_or(ERROR);
            let ty = self.cx.tys.mk_option(elem);
            return Some((AdtId(u32::MAX), 0, ty));
        }
        // A single name looks the type maps up by flat name: its binding read.
        if let [seg] = segs
            && seg.name != p.known.self_type
        {
            self.cx.binding(Namespace::Type, seg.name);
        }
        let (adt, variant) = self.self_variant_of(segs)?;
        if p.adt(adt).variants[variant as usize].shape != VariantShape::Unit {
            return None;
        }
        // A generic unit value (`PhantomData`) takes the expected
        // instance of its own Adt.
        let def = p.def_of_adt(adt);
        let ty = match expected {
            Some(t) if segs.iter().all(|s| s.type_args().is_empty()) && self.cx.tys.adt_parts(t).is_some_and(|(d, _)| d == def) => t,
            _ => self.cx.tys.adt_ty(adt),
        };
        Some((adt, variant, ty))
    }
    fn struct_target(&mut self, path: &[ast::PathSeg]) -> Option<(AdtId, u32, Ty)> {
        let (adt, variant) = self.self_variant_of(path)?;
        Some((adt, variant, self.cx.tys.adt_ty(adt)))
    }
    fn pattern_variant(&mut self, segs: &[ast::PathSeg]) -> Option<(AdtId, u32)> {
        self.self_variant_of(segs)
    }
    fn variant_fields(&self, adt: AdtId, variant: u32) -> Vec<(Sym, Ty)> {
        if adt.0 >= u32::MAX - 1 {
            return Vec::new();
        }
        self.cx.p.adt(adt).variants[variant as usize].fields.iter().map(|f| (f.name, f.ty)).collect()
    }
    fn variant_count(&self, adt: AdtId) -> u32 {
        if adt.0 >= u32::MAX - 1 {
            return 0;
        }
        self.cx.p.adt(adt).variants.len() as u32
    }
    fn resolve_ty(&mut self, t: ast::TyId) -> Ty {
        self.cx.resolve_written(t)
    }
    fn layout(&mut self, t: Ty) -> Option<crate::ty::layout::Layout> {
        let p: &Program = self.cx.p;
        let t = self.cx.deep(t);
        // A layout answer inside body const evaluation (`size_of` in a
        // const block or array length) is baked into the body: record
        // the layout reads, as `layout_query` does.
        p.record_layout_reads(&mut self.cx.out.reads, &self.cx.tys, t);
        crate::ty::layout::layout_of_ty(&self.cx.tys, &UserLayout(p), t).ok()
    }
    fn adt_repr(&self, adt: AdtId) -> crate::ty::layout::Repr {
        self.cx.p.adt(adt).repr
    }
    fn discriminant(&self, adt: AdtId, variant: u32) -> i128 {
        self.cx.p.adt(adt).variants[variant as usize].disc
    }
    fn is_enum(&self, adt: AdtId) -> bool {
        adt.0 < u32::MAX - 1 && self.cx.p.adt(adt).is_enum
    }
    fn needs_drop(&self, t: Ty) -> bool {
        crate::check::collect::needs_drop_const(self.cx.p, &self.cx.tys, t)
    }
    fn interior_mut(&self, t: Ty) -> bool {
        crate::check::collect::interior_mut(self.cx.p, &self.cx.tys, t)
    }
    fn ty_text(&self, t: Ty) -> String {
        crate::check::collect::ty_name(self.cx.p, &self.cx.tys, t)
    }
    fn is_copy(&self, t: Ty) -> bool {
        crate::check::collect::is_copy(self.cx.p, &self.cx.tys, t)
    }
    fn named_field_private(&mut self, adt: AdtId, field: Sym) -> bool {
        // A privacy answer inside body const evaluation (a `const`
        // block the checker does not walk) depends on the Adt's
        // member visibility: record the same `Sig(adt)` read as
        // `check_field_vis`, so a visibility edit rechecks it.
        let p = self.cx.p;
        if p.resolved.is_some()
            && let Some(def) = p.defs.def_of_adt(adt)
        {
            let _ = p.sig_of(&mut self.cx.out.reads, def);
        }
        crate::check::collect::named_field_is_private(p, adt, field, self.cx.module)
    }
    fn tuple_field_private(&mut self, adt: AdtId, index: u32) -> bool {
        let p = self.cx.p;
        if p.resolved.is_some()
            && let Some(def) = p.defs.def_of_adt(adt)
        {
            let _ = p.sig_of(&mut self.cx.out.reads, def);
        }
        crate::check::collect::tuple_field_is_private(p, adt, index, self.cx.module)
    }
    fn ne_lit_what(&mut self, adt: AdtId, variant: u32) -> Option<&'static str> {
        self.cx.ne_read(adt, variant);
        crate::check::collect::ne_lit_what(self.cx.p, adt, variant, self.cx.module)
    }
    fn ne_ctor_what(&mut self, adt: AdtId, variant: u32) -> Option<&'static str> {
        self.cx.ne_read(adt, variant);
        crate::check::collect::ne_ctor_what(self.cx.p, adt, variant, self.cx.module)
    }
    fn ne_pat_what(&mut self, adt: AdtId, variant: u32, rest: bool) -> Option<&'static str> {
        self.cx.ne_read(adt, variant);
        crate::check::collect::ne_pat_what(self.cx.p, adt, variant, rest, self.cx.module)
    }
}

/// The (Adt, variant) a path denotes in the compat tables.
impl CheckCx<'_, '_> {
    /// `variant_of`, with `Self` (`Self { .. }`, `Self::A`) naming the
    /// Adt of the const fn being evaluated or of the body's impl.
    fn self_variant_of(&self, segs: &[ast::PathSeg]) -> Option<(AdtId, u32)> {
        let p = self.cx.p;
        if let Some(first) = segs.first()
            && first.name == p.known.self_type
            && segs.len() <= 2
        {
            let a = self.cx.self_adt()?;
            return match segs {
                [_] => (!p.adt(a).is_enum).then_some((a, 0)),
                [_, v] => p.adt(a).variants.iter().position(|x| x.name == v.name).map(|i| (a, i as u32)),
                _ => None,
            };
        }
        // A type item of an enclosing block shadows the module's (R18):
        // `E::X` in a body with its own `enum E` is that enum's variant.
        // A block alias or trait of the name is no Adt here.
        if let [head, rest @ ..] = segs
            && rest.len() <= 1
        {
            let bs = &self.cx.body_scope;
            if bs.local_aliases.iter().any(|e| e.0 == head.name) || bs.local_traits.iter().any(|e| e.0 == head.name) {
                return None;
            }
            if let Some(a) = self.cx.local_adt_of(head.name) {
                return match rest {
                    [] => (!p.adt(a).is_enum).then_some((a, 0)),
                    [v] => p.adt(a).variants.iter().position(|x| x.name == v.name).map(|i| (a, i as u32)),
                    _ => None,
                };
            }
        }
        variant_of(p, segs)
    }
}

fn variant_of(p: &Program, segs: &[ast::PathSeg]) -> Option<(AdtId, u32)> {
    // `std::borrow::Cow::Borrowed` and `Owned` (W-STD-B).
    if segs.len() == 4
        && matches!(p.interner.get(segs[0].name), "std" | "alloc")
        && p.interner.get(segs[1].name) == "borrow"
        && p.interner.get(segs[2].name) == "Cow"
        && let Some(a) = p.tys.local_adt_of(generics::cow_def())
    {
        let v = p.adt(a).variants.iter().position(|v| v.name == segs[3].name)?;
        return Some((a, v as u32));
    }
    // `std::cmp::Ordering::Less`: the same std variant paths
    // `resolve_assoc` answers, for const contexts.
    if segs.len() >= 4 {
        let path: Vec<&str> = segs.iter().map(|s| p.interner.get(s.name)).collect();
        return generics::std_variant_of(p, &path);
    }
    if segs.len() == 1 {
        let &a = p.type_names.get(&segs[0].name)?;
        if p.adt(a).is_enum {
            return None;
        }
        return Some((a, 0));
    }
    if segs.len() == 2 {
        let &a = p.type_names.get(&segs[0].name)?;
        let v = p.adt(a).variants.iter().position(|v| v.name == segs[1].name)?;
        return Some((a, v as u32));
    }
    None
}
/// The solver over one body's inference state (see
/// `traits::solve::SolveCx`): probes bind body variables and roll
/// back through the trail `bind_var` records.
impl<'p> SolveCx for Ctx<'p> {
    type Snapshot = usize;
    type Store = Tys<'p>;

    fn tys(&mut self) -> &mut Tys<'p> {
        &mut self.tys
    }
    fn deep_resolve(&mut self, t: Ty) -> Ty {
        self.deep(t)
    }
    fn unify(&mut self, a: Ty, b: Ty) -> bool {
        self.unify(a, b)
    }
    fn fresh_var(&mut self) -> Ty {
        self.new_var(false)
    }
    fn fresh_const_var(&mut self) -> ConstId {
        Ctx::fresh_const_var(self)
    }
    fn unify_const(&mut self, a: ConstId, b: ConstId) -> bool {
        Ctx::unify_const(self, a, b)
    }
    fn resolve_const(&self, c: ConstId) -> ConstId {
        Ctx::resolve_const(self, c)
    }
    fn snapshot(&mut self) -> usize {
        self.trail.len()
    }
    /// Pops the trail: type variables, and const variables (ids at or
    /// above `INFER_MARKER_BASE`, see `unify_const`).
    fn rollback(&mut self, snap: usize) {
        while self.trail.len() > snap {
            let var = self.trail.pop().unwrap();
            if var >= generics::INFER_MARKER_BASE {
                self.const_bindings.remove(&var);
            } else {
                self.vars[var as usize].bound = None;
            }
        }
    }
    fn closure_select(&mut self, obl: TraitRef) -> Option<Selection> {
        self.closure_select_impl(obl)
    }
    fn closure_output(&mut self, assoc: DefId, self_ty: Ty) -> Option<Ty> {
        self.closure_output_impl(assoc, self_ty)
    }
    fn builtin_assoc(&mut self, assoc: DefId, args: ArgsId) -> Option<Ty> {
        self.try_from_assoc(assoc, args)
    }
    fn builtin_select(&mut self, obl: TraitRef) -> Option<Selection> {
        let self_ty = self.tys.args(obl.args).first().and_then(|g| g.as_ty())?;
        self.try_from_select(obl, self_ty)
    }
    fn structural(&mut self, tr: TraitRef) -> Option<bool> {
        let p = self.p;
        let lang = &p.gx.lang;
        let self_ty = self.tys.args(tr.args).first().and_then(|g| g.as_ty())?;
        let self_ty = self.deep(self_ty);
        if matches!(self.kind(self_ty), TyKind::Infer(_)) {
            return None;
        }
        if tr.def == lang.sized {
            return Some(self.sized_ok(self_ty));
        }
        // The scalar `TryFrom` and `TryInto` pairs have no impl records
        // either: the pair table answers (fx-tryfrom).
        match self.try_from_select(tr, self_ty) {
            Some(Selection::ParamEvidence(_)) => return Some(true),
            Some(Selection::NoImpl) => return Some(false),
            _ => {}
        }
        // Numeric `From` has no impl records (it is a builtin widening
        // cast), so an empty bucket must not read as "never holds".
        if tr.def == lang.from
            && let Some(input) = self.tys.args(tr.args).get(1).and_then(|g| g.as_ty())
        {
            let input = self.deep(input);
            let (ik, sk) = (self.kind(input), self.kind(self_ty));
            let literal = matches!(ik, TyKind::Infer(v) if v.is_int() || v.is_float());
            if matches!(sk, TyKind::Int(_) | TyKind::Float(_)) && (literal || Self::numeric_from_ok(ik, sk)) {
                return Some(true);
            }
        }
        if let Some(refs) = unwind::unwind_trait(p, tr.def) {
            let env = self.solve_env();
            return unwind::unwind_safe(p, &mut self.tys, &env, refs, self_ty, &mut Vec::new());
        }
        if lang.is_auto(tr.def) {
            return self.auto_holds(tr.def, self_ty);
        }
        // The object candidate (`dyn P` implements `P` and its
        // supertraits) has no impl record, as in `select_obligation`.
        if let Some(pr) = object::principal_of(&self.tys, self_ty) {
            // The fmt traits are supertraits with no super slot (the
            // vtable header shims in check/object.rs).
            if (tr.def == lang.debug || tr.def == lang.display) && object::principal_has_supertrait(p, pr.def, tr.def) {
                return Some(true);
            }
            let want = object::with_self(&mut self.tys, tr, DYN_SELF);
            let want = TraitRef { bindings: EMPTY_BINDINGS, ..want };
            let snap = self.snapshot_vars();
            let holds = if pr.def == want.def {
                self.unify_args(pr.args, want.args)
            } else {
                object::upcast_path(p, &mut self.tys, pr, want).is_some()
            };
            self.rollback_vars(snap);
            if holds {
                return Some(true);
            }
        }
        if p.gx.index.derive_family.contains(&tr.def)
            && matches!(self.kind(self_ty), TyKind::Tuple(_) | TyKind::Array(..) | TyKind::Slice(_) | TyKind::Ref(..) | TyKind::RawPtr(..) | TyKind::Closure(..))
        {
            return Some(self.derive_query_holds(tr.def, self_ty));
        }
        // core's builtin impls: every fn pointer and fn item is Copy and
        // Clone, for any signature. (Their Debug, PartialEq, and kin
        // compare or print addresses, which lust does not match.)
        if (tr.def == lang.copy || tr.def == lang.clone) && matches!(self.kind(self_ty), TyKind::FnPtr(_) | TyKind::FnDef(..)) {
            return Some(true);
        }
        // A builtin iterator's Clone has no impl record either: the
        // method probe's where-clause filter (`impl<T: Clone> Tag for T`
        // at a `Range<i32>` receiver) must see the same answer as
        // `select_obligation_at`.
        if tr.def == lang.clone
            && matches!(self.kind(self_ty), TyKind::Adt(..))
            && (self.tys.is_chars_ty(self_ty) || crate::ty::iter::iter_parts(&self.tys, self_ty).is_some())
        {
            return Some(self.derive_query_holds(tr.def, self_ty));
        }
        None
    }
    fn record_impl_set(&mut self, trait_def: DefId, self_ty: Ty, _failed: bool) {
        let p = self.p;
        let resolved = self.resolve(self_ty);
        let head = Head::of(&self.tys, resolved);
        p.impl_set(&mut self.out.reads, trait_def, head);
    }
}

/// W-BORROW (`note_closure_bounds`): true when a bound's type has a region
/// position of its own (a reference, an Adt with lifetime params, a
/// borrowing builtin, `dyn`, a closure or fn pointer), not counting type
/// params and projections.
/// The regions of a regioned closure bound input `t` (`Box<dyn FnOnce() +
/// Send + 'a>`), a dyn's object lifetime included, for `named_only` in
/// `note_closure_bounds`. None for a type whose regions are not all
/// written slots here (fn pointers, closures, fn items, `impl Trait`).
fn bound_input_regions(p: &Program, t: Ty, out: &mut Vec<Region>) -> Option<()> {
    match p.tys.kind(t) {
        TyKind::Ref(r, _, inner) => {
            out.push(r);
            bound_input_regions(p, inner, out)
        }
        TyKind::Dyn(_, r) => {
            out.push(r);
            for e in crate::borrowck::dyn_arg_tys(&p.tys, t) {
                bound_input_regions(p, e, out)?;
            }
            Some(())
        }
        TyKind::Adt(_, args) => {
            // A std type with hidden regions (`Chars`, slice iterators).
            if p.tys.builtin_of(t).is_some_and(|b| matches!(b, BuiltinTy::Chars | BuiltinTy::Iter(_))) {
                return None;
            }
            for g in p.tys.args(args).to_vec() {
                match g {
                    GenericArg::Lifetime(r) => out.push(r),
                    GenericArg::Ty(e) => bound_input_regions(p, e, out)?,
                    GenericArg::Const(_) => {}
                }
            }
            Some(())
        }
        TyKind::Tuple(ts) => {
            for e in p.tys.tys_of(ts).to_vec() {
                bound_input_regions(p, e, out)?;
            }
            Some(())
        }
        TyKind::Array(e, _) | TyKind::Slice(e) => bound_input_regions(p, e, out),
        TyKind::FnPtr(_) | TyKind::Closure(..) | TyKind::FnDef(..) | TyKind::Opaque(..) => None,
        _ => Some(()),
    }
}

fn bound_type_has_regions(p: &Program, t: Ty) -> bool {
    use crate::ty::iter::IterKind;
    match p.tys.kind(t) {
        TyKind::Ref(..) | TyKind::Dyn(..) | TyKind::Closure(..) | TyKind::FnPtr(_) | TyKind::FnDef(..) | TyKind::Opaque(..) => true,
        TyKind::Adt(def, args) => {
            matches!(
                p.tys.builtin_of(t),
                Some(BuiltinTy::Chars | BuiltinTy::Iter(IterKind::SliceIter | IterKind::SliceIterMut | IterKind::VecDrain | IterKind::StringDrain))
            )
                || p.gx.adt_lifetimes.get(&def).is_some_and(|v| !v.is_empty())
                || p.tys.args(args).iter().any(|g| g.as_ty().is_some_and(|e| bound_type_has_regions(p, e)))
        }
        TyKind::Tuple(ts) => p.tys.tys_of(ts).iter().any(|&e| bound_type_has_regions(p, e)),
        TyKind::Array(e, _) | TyKind::Slice(e) | TyKind::RawPtr(_, e) => bound_type_has_regions(p, e),
        _ => false,
    }
}

